  ["Act_E1_2A_Corridor_MPA01_Look04_Max_010"] = "この子に何があったんだろう…",
  ["Act_E1_2A_Corridor_MPA01_Look05_Max_010"] = "早く女子トイレに行かないと あの子が大変なことになる!",
  ["Act_E1_2A_Corridor_MaxLocker_Interact02_Max_010"] = "パパとママの大事な写真 |ジャック・ケルアックはホントにかっこいい |アンディ 今日もバッチリ決まってるね…",
  ["Act_E1_2A_Corridor_MaxLocker_Interact03_Max_010"] = "やっぱり さっきと同じ",
  ["Act_E1_2A_Corridor_MaxLocker_Look01_Max_010"] = "みんなにロッカーの中は見られたくない",
  ["Act_E1_2A_Corridor_Plan01_Look01_Max_010"] = "こんなの暗記してる人 いるのかな? でも実際は みんなしたほうがいいよね",
  ["Act_E1_2A_Corridor_Poster01_Look01_Max_010"] = "大変だな… 私も活動に協力したほうがいいのかも… ま やらないけどね",
  ["Act_E1_2A_Corridor_Poster02_Look01_Max_010"] = "また灯台か…",
  ["Act_E1_2A_Corridor_Poster03_Look01_Max_010"] = "献血 したほうがいいよね?",
  ["Act_E1_2A_Corridor_Poster04_Look01_Max_010"] = "銃はおうちに置いてきましょう!",
  ["Act_E1_2A_Corridor_Poster05_Look01_Max_010"] = "こんなビラでいじめがなくなれば苦労しないって",
  ["Act_E1_2A_Corridor_Poster06_Look01_Max_010"] = "このポスター オタク臭全開だな。 ウォーレンが好きそう",
  ["Act_E1_2A_Corridor_Poster07_Look01_Max_010"] = "「私もネイサンやビクトリアみたいにイケてる生徒になりたいわ!」… |バッカみたい…",
  ["Act_E1_2A_Corridor_PrincipalDoor_Look01_Max_010"] = "校長先生はいつも校長室にこもってる",
  ["Act_E1_2A_Corridor_PrincipalDoor_Look02_Max_010"] = "早く女子トイレに行かないと!",
  ["Act_E1_2A_Corridor_RewindChoice_NathanDenounce_Max_010"] = "校長はなにもしてくれないだろうけど… |ブラックウェルはプレスコット家のものも同然だし |巻き戻して話を変えるべきかな?",
  ["Act_E1_2A_Corridor_RewindChoice_NathanLie_Max_010"] = "ダメだ 全然信じてない。 下手すると奨学金がもらえなくなるな… |巻き戻して 本当のことを話そうかな",
  ["Act_E1_2A_Corridor_Samuel_Look01_Max_010"] = "サミュエルってほんと変な人。 でもそこがいいんだよね",
  ["Act_E1_2A_Corridor_Samuel_Look02_Max_010"] = "サミュエルにも このことは話せないな",
  ["Act_E1_2A_Corridor_ScienceDoor_Look01_Max_010"] = "ここが科学室。 ウォーレンの脳みそへの入り口…",
  ["Act_E1_2A_Corridor_ScienceDoor_Look02_Max_010"] = "ダラダラしてないで 早くトイレにいかないと",
  ["Act_E1_2A_Corridor_Stella_Look01_Max_010"] = "ステラはいつもノートとにらめっこ。 本気で勉強しにブラックウェルに来てる",
  ["Act_E1_2A_Corridor_Stella_Look02_Max_010"] = "ステラ まだノートを見てる。 早く行かないと!",
  ["Act_E1_2A_Corridor_Taylor_Look01_Max_010"] = "テイラーだ。 いつもビクトリアを待ってる",
  ["Act_E1_2A_Corridor_Taylor_Look02_Max_010"] = "見てないで早く行かないと!",
  ["Act_E1_2A_Corridor_Trevor_Look01_Max_010"] = "スケーターは好きだけど 私の想いはいつも一方通行",
  ["Act_E1_2A_Corridor_Trevor_Look02_Max_010"] = "みんな 前と同じ場所に立ってる。 急がないと",
  ["Act_E1_2A_Corridor_Trophy01_Look01_Max_010"] = "すごいトロフィー。 さすがビッグフットってとこかな",
  ["Act_E1_2A_Corridor_Trophy02_Look01_Max_010"] = "水泳にはだいぶ力入れてるな。 カワウソ かわいいからいいけど |がんばれオッターズ!",
  ["Act_E1_2A_Corridor_VendingMachine_Look01_Max_010"] = "「砂糖販売機」って呼べばいのに… コインを入れたら砂糖が出てくる 最高だね",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_010"] = "わかってる コンテストに写真を出すのが怖いだけ",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_020"] = "たかだか写真 1 枚でビクビクするなんて…",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_030"] = "また個室に入って泣くつもり?",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_040"] = "みんなここにいるだけで幸せって感じ",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_050"] = "落ち着いて 水道で顔を洗おう…",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_060"] = "トイレで一息つきたい…",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_020"] = "先に 顔を洗ってスッキリしたいな…",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_030"] = "目がジンジンする。 先にトイレに行きたい",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_040"] = "まずトイレに行きたい",
  ["Act_E1_2A_Corridor_VoiceOverRewind01_Max_020"] = "誰にも言えない… おかしいと思われる…",
  ["Act_E1_2A_Corridor_VoiceOverRewind01_Max_040"] = "あの子をトイレで死なせられないよ…",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_010"] = "今出て行ったら あの子死んじゃう…",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_030"] = "ビビってないで トイレに行くんだ…",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_040"] = "今逃げたら一生後悔する…",
  ["Act_E1_2A_Corridor_Zachary_Look01_Max_010"] = "ジュリエットとザッカリーが付き合うのも当然 |ボルテックス・クラブの渦中の存在だもん",
  ["Act_E1_2A_Corridor_Zachary_Look02_Max_010"] = "ここにいる人は助けてくれない。 急がなきゃ!",
  ["Act_E1_2A_Toilets_Butterfly_Look01_Max_010"] = "あの蝶… 真っ青できれい |レースみたいな羽… 背景との対比もすてき… |いったいどこから来たんだろう?",
  ["Act_E1_2A_Toilets_Butterfly_Look02_Max_010"] = "あの蝶 どこから来たの? |今までに見たことない種類。 羽が光ってるみたい… |空気が流れるのを感じる… まるで精霊のよう…",
  ["Act_E1_2A_Toilets_FireAlarm_Look01_Max_010"] = "先月も誰かが鳴らしたな。化学の授業をサボれたからいいけど",
  ["Act_E1_2A_Toilets_FireAlarm_Look02_Max_010"] = "ハンマーでもないと壊せない!",
  ["Act_E1_2A_Toilets_Graffiti_Look01_Max_010"] = "こんなこと わざわざ書く?",
  ["Act_E1_2A_Toilets_Hammer_Look01_Max_010"] = "ハンマーがあった! これでガラスが割れる!",
  ["Act_E1_2A_Toilets_Poster01_Look01_Max_010"] = "これを見てセックスに励む人なんているのかな",
  ["Act_E1_2A_Toilets_Poster02_Look01_Max_010"] = "こないだの予防接種は 何も\"予防\"しなかったし。 もういいよ",
  ["Act_E1_2A_Toilets_Poster04_Look01_Max_010"] = "人生 こんなに単純だったら…",
  ["Act_E1_2A_Toilets_TamponDispenser_Look01_Max_010"] = "今はいらないかな",
  ["Act_E1_2A_Toilets_Trolley_Look01_Max_010"] = "サミュエルが掃除用具のカートを忘れてったみたい",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_010"] = "なにしに来たんだっけ…",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_020"] = "脂汗で気持ち悪いな…",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_030"] = "せっかく来たし 顔でも洗おう…",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_040"] = "ダメ!",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_010"] = "よし さっきを思い出して…",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_020"] = "顔を洗って…",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_030"] = "写真を破ったら…",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_040"] = "えーっと… 蝶が入ってきて…",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_050"] = "写真を撮った…",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_010"] = "うわ また同じだ…",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_020"] = "助けるなら今よ…",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_030"] = "マックス ほら なんとかしないと",
  ["Act_E1_2A_Toilets_VoiceOverRewind03_Max_010"] = "ダメ これじゃ一緒だ… また時間を巻き戻せば助けられるかも",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_010"] = "本当に変な力があるんだ…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_020"] = "時間を巻き戻した…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_030"] = "私にいったい何が起こってるの?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_040"] = "すごい… でも疲れた…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_060"] = "くたくただ…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_070"] = "撃たれた女の子を この手で助けたんだ… いったいどうなってるの?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_080"] = "落ち着いて… 落ち着かないと…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_090"] = "もう何が現実なのか分からないよ!",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_100"] = "私は大丈夫… あまり深く考えちゃダメ…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_110"] = "ウソ ウソ ウソ!",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_120"] = "こんなのあり得ない… 何が起きてるの…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_130"] = "パニックを起こしちゃダメ",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_140"] = "どうして私がこんな目に?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_150"] = "おかしくなってなんかない。 絶対に…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_160"] = "夢なら早くさめて…",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_170"] = "これは夢なの? 私 まだ寝てるの?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_180"] = "どうしてこんなことに…",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_010"] = "ダメ あいつ銃を持ってる! 他の方法は…?",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_020"] = "近づくのはヤバいって!",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_030"] = "あんなヤツに近づきたくない!",
  ["Cue_E1_2A_ArtClass_BellRing_Hayden_030"] = "どうかな…? なにしろ俺のは マン・レイとマンガの融合だぜ?",
  ["Cue_E1_2A_ArtClass_BellRing_Jefferson_010"] = "みんな 「日常ヒーロー」コンテストの期限が迫ってるぞ |優勝者は学校の代表としてサンフランシスコに連れていく |プロの世界に自分を売り込むチャンスだ |ステラも アリッサも 早く出すように |テイラー。 君もまだだな? 期待してるぞ |マックスも 言い訳は通用しないからな",
  ["Cue_E1_2A_ArtClass_BellRing_Taylor_020"] = "そんな暇ないよ。 どうせビクトリアが選ばれるに決まってるし",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Jefferson_002"] = "こらこら。 答えられないからといって誤魔化そうとするんじゃない |あとで先生のところに来なさい",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Max_001"] = "すみません… 気分が悪くて… 保健室行きたいです",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Max_003"] = "すみません トイレに行ってもいいですか?",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_002"] = "じゃあなんだ? \"絶好のシャッターチャンス\"を待っているとか?",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_004"] = "マックス 時間をムダにするな |「人生は他の計画を立てているうちに過ぎる」 |ジョン・レノンの言葉だ |肝に銘じておきなさい",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_006"] = "あれだけ自撮りしてるんだ 作品のストックなら いくらでもあるだろう?",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_011"] = "マックス 今日は絶好調だな! |まったく言うことナシだ |今日中に作品を用意すること。 君には期待してるよ",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_012"] = "さて ちゃんと提出する写真を用意してきてくれたんだろうね",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_013"] = "マックス 自分でも分かってるだろう? |「君はまだ若い」とか「可能性は無限だ」とか… |いまさら年寄り臭い説教をクドクド聞かせるつもりはないが |時間をムダにしちゃいけない |君には才能がある |君にしかない独自の視点で 世界を切り取ろうとする情熱がある |いいかい? 勇気を出して それを世界に発表するんだ |アマチュアからプロの卵へ 一歩踏み出してごらん",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_001"] = "出すつもりなんですが…",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_003"] = "そうです!",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_005"] = "でも… その… 出せる写真がなくて…",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_007"] = "でもいい写真がなかなかなくて",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_008"] = "今準備してます。 ジョン・レノンが言ってました |「人生は他の計画を立てているうちに過ぎる」",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_014"] = "でも先生… どうしても出さなきゃダメですか…",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_015"] = "宿題がありすぎて… どうしても時間が…",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_005"] = "マックス。 ついでだから君に聞こう |世界で最初のセルフポートレートの誕生に 大きく貢献した製版法は?",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_010"] = "予習してこなかったな?",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_011"] = "要は答えられないということか",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_016"] = "正解だ ちゃんと予習してきたようだな。 感心だぞ マックス",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_006"] = "私ですか…? えっと… その…",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_007"] = "知ってます! …でも忘れちゃって…",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_015"] = "ダゲレオタイプです |1830 年頃に フランス人のルイ・ダゲールが発明しました",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_001"] = "マックス。 お疲れ",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_003"] = "急に当てられるとキツいよね",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_005"] = "マックスのほうが才能あるよ。 それじゃ またあとでね",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_008"] = "バイバイ",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_010"] = "うん ちょっと悩みごと",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_013"] = "そうしたいところだけど… 宿題しないといけないから",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_016"] = "マックス すごいね。 顔色悪いけど… 大丈夫?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_018"] = "今が初めてだけど… どうかした?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_020"] = "つらいよね…",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_022"] = "うん 考えとく。 ありがとね",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_024"] = "分かった",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_002"] = "今日は授業中に恥かいちゃったよ…",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_004"] = "ビクトリアは別だろうけど",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_007"] = "うん またね。 お疲れ",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_009"] = "元気ないみたいだけど…",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_011"] = "コンテストの代表に選ばれるのはビクトリアだよ。 今回もね",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_012"] = "そっか。 お茶でもしながらグチりたい? つきあうよ",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_015"] = "うん わかった。 また今度ね",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_017"] = "ケイト… あのさ… 今日私と話した?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_019"] = "ごめん 変なこと聞いて… ストレスのせいかな",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_021"] = "ケイトも元気ないね。 もう行かなきゃだけど あとでお茶でもする?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_023"] = "もう行くね 今ちょっとテンパッてて",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_025"] = "ケイト",
  ["Cue_E1_2A_ArtClass_CHKate_Phase02_Kate_001"] = "またあとでね",
  ["Cue_E1_2A_ArtClass_Dial01_Daniel_020"] = "みんなギスギスしてて空気悪いよ…",
  ["Cue_E1_2A_ArtClass_Dial01_Stella_010"] = "今日の授業もためになったね",
  ["Cue_E1_2A_ArtClass_Dial01_Stella_030"] = "私には関係ない。 気にしたら負けだよ",
  ["Cue_E1_2A_ArtClass_Dial02_Taylor_020"] = "きっと優勝だね",
  ["Cue_E1_2A_ArtClass_Dial02_Victoria_010"] = "コンテストの課題 ちょっと本気出し過ぎたかも",
  ["Cue_E1_2A_ArtClass_Dial03_Alyssa_040"] = "宿題多すぎ… もう最悪",
  ["Cue_E1_2A_ArtClass_Dial03_Hayden_020"] = "今日は教室にヤバいオーラが充満してたな…",
  ["Cue_E1_2A_ArtClass_Dial03_Hayden_030"] = "ヤバいのは俺か…? 教室じゃなくて俺がヤバいのか…?",
  ["Cue_E1_2A_ArtClass_Dial03_Victoria_010"] = "アリッサは今日も相変わらず うっとうしいわね",
  ["Cue_E1_2A_ArtClass_Dial04_Courtney_010"] = "インスタントカメラとか めちゃくちゃダサいんですけど",
  ["Cue_E1_2A_ArtClass_Dial04_Courtney_030"] = "それに何なの あのおとなしいキャラ",
  ["Cue_E1_2A_ArtClass_Dial04_Taylor_020"] = "マックスはイケてると思ってんでしょ",
  ["Cue_E1_2A_ArtClass_Dial04_Taylor_040"] = "自撮り魔なんだから ほんとは目立ちたいに決まってるじゃん",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Jefferson_010"] = "ダメだ ビクトリア 宿題を免除することはできない |コンテストにはこのクラスの全員が参加するんだ |特別扱いは できないよ",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Jefferson_030"] = "君はコンテストに応募した。 それだけでも十分有意義だ |誰が代表に選ばれても この先チャンスはいくらでもある |君たちの熱意をくじくつもりはないが |先生は 写真の世界は厳しいという現実も知ってもらいたいと思ってるんだよ |チャンスというのは誰にでも 公平に訪れるべきだ |違うかい?",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Victoria_020"] = "それは分かってます。 ただこの写真を撮るのすごく大変だったんです |先生なら分かってくれるでしょう? |「日常ヒーロー」コンテストはとても有意義なイベントだと思います |どうしても代表に選ばれたくて…",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Victoria_040"] = "分かってます。 私は自分の才能を世に発表したいだけです",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_010"] = "では 人物の内面をモノクロ写真で完璧にとらえた写真家といえば誰だろう? |分かる人? 誰か?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_030"] = "なるほどね なぜそう思う?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_050"] = "アーバスは人間を「苦悩の存在」と考えた。 正直ヘドが出るね |はいはい 騒がない… |例えば 誰かを暗い部屋に座らせれば 絶望のシーンのできあがりだ |そんな写真は誰にだって撮れる。 要は安直すぎるんだ |そう思わないか? |逆に アーバスが被写体の最も美しい瞬間をとらえていたら どうだっただろう? |あれだけのセンスの持ち主なら 別なアプローチだって できたはずだ",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_070"] = "同感だね。 戦後のアメリカをとらえたフランクの作品には |貧しくても懸命に生きる人びとの姿が 浮き彫りになっている |それこそが真の美しさだ |フランクがケルアックにインスピレーションを与えたのもうなずける |2 人とも 50 年代の 偉大なアーティストだ |ケルアックの有名なバルコニーでのショットはみんな知っているね |都会で物思いにふける |孤独な詩人の姿を見事にとらえた一枚だ |すばらしいよ",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_080"] = "さて フランクと対照的なのが サルバドール・ダリのシュールレアリズムだ |コクトーと同様 ダリも多才な人物だったが |彼の有名なセルフポートレートの数々は |君たちがよく使うセンスのない言葉で言うところの 「自撮り」だ |でもセルフポートレートの歴史は古い。 自撮りだって立派な自己表現だ |言葉のチョイスは ま どうかと思うけどね",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_090"] = "自撮りは現代特有のナルシシズムだと思っている人 |批判は数百年前に向けるべきだ |さてと… そろそろ眠くなってきた人もいるかな… それじゃあ質問しよう |教科書を読んできた人は答えられるはずだぞ |セルフポートレートの誕生に貢献した 製版法の名前は なんでしょう?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_020"] = "ダイアン・アーバスです",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_040"] = "アーバスの作品にとらえられた 失意の人びとの目には 鬼気迫るものがあります",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_060"] = "確かに私 アーバスはいいと思えません |それより… ロバート・フランクとか…",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Jefferson_030"] = "ビクトリア 口を慎みなさい",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Jefferson_040"] = "さてマックス。 やっとコンテストの課題を持ってきてくれたんだな",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Max_010"] = "あのう… ジェファソン先生 今ちょっといいですか?",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Max_050"] = "えーっと…",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Victoria_020"] = "じゃまよ あっち行って",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_010"] = "誰か? 誰も答えられないのか…?",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_020"] = "遠慮なく答えていいんだぞ",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_030"] = "教科書に書いてあったはずだ",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_040"] = "みんな予習してきたよな?",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_060"] = "気まずい沈黙だな…",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_070"] = "みんなどうしたんだ? 顔が固まってるぞ",
  ["Cue_E1_2A_ArtClass_JeffersonTalks_Jefferson_010"] = "マックス・コールフィールド。 待ちなさい。 コンテストの課題はどうした",
  ["Cue_E1_2A_ArtClass_MaxAnswers_Jefferson_010"] = "「ダゲレオタイプ」は別名「銀板写真」ともいい |被写体の顔を鮮明に写し出すことができる技法だ |予習範囲を最後まで読めば詳しいことが書いてあるぞ |ちゃんと読んできたのはマックスだけみたいだが",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Jefferson_030"] = "アルフレッド・ヒッチコックは映画を「時間の断片」だと考えた |当然ながら写真についても同じことが言えるだろう |写真は被写体の喜怒哀楽を切り取る |光 影 カラー キアロスクーロなど 技法はさまざまだ",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Max_010"] = "…ッ!",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Max_020"] = "居眠りなんかしてない… それに 夢にしてはリアルすぎた… なんなの?",
  ["Cue_E1_2A_ArtClass_MaxSurprised_Max_010"] = "ウソ… ホントに巻き戻った…!",
  ["Cue_E1_2A_ArtClass_MaxSurprised_Max_020"] = "タイムマシンみたい…",
  ["Cue_E1_2A_ArtClass_Polaroid_Broken_Max_010"] = "ちょっと ウソでしょ…",
  ["Cue_E1_2A_ArtClass_Polaroid_Picture01_Jefferson_010"] = "ちょうど今 マックスが「自撮り」を撮ったぞ |&#8203;現代ならではの&#8203;セルフポートレートだが…&#8203; |マックス 君は筋がいい",
  ["Cue_E1_2A_ArtClass_Polaroid_Picture01_Jefferson_020"] = "肖像写真は 1800 年代初期から広く普及し 現在に至る |君たちの世代よりはるか昔から 「自撮り」の文化は存在したんだ |呼び方は変わったけどね |写真やアートの世界において人物の姿をとらえることは |常に極めて重要な要素でありつづけてきた",
  ["Cue_E1_2A_ArtClass_VictoriaJoke02_Victoria_010"] = "マックスはデジタル時代が怖いのよ",
  ["Cue_E1_2A_ArtClass_VictoriaJoke02_Victoria_020"] = "自分の身の丈を知るっていうのも 大事なことよね",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_010"] = "マックス 君はもういいよ",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_020"] = "誰か他に 答えられる人は?",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_050"] = "正解だ |「ダゲレオタイプ」は人物の顔を細部まで描写することで |1800 年代以降 広く普及した |この技法で初のセルフポートレートを撮ったのが コーネリアスだ",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_060"] = "彼に関する詳しいことは 教科書に書いてある",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_070"] = "もちろん ネットにもね",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Victoria_030"] = "フランスの画家&#8203;ルイ・ダゲール発明の&#8203;「ダゲレオタイプ」 |&#8203;鏡のように被写体をくっきり&#8203;写し出す手法です",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Victoria_040"] = "あなたのぼんやりした顔とは 正反対ね",
  ["Cue_E1_2A_Corridor_ArtClassDoor_Interact04_Max_010"] = "早く女子トイレに行かなきゃ… お願い 間に合って…",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_010"] = "で? 私のことどう思ってるの?",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_030"] = "カワイイだけ?",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_050"] = "それだけじゃ 授業中に\"いい写真\"送ってあげないよ",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_070"] = "そんな女じゃないし",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_090"] = "は? 急に何の話?",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_110"] = "最低ね",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_020"] = "分かってるだろ。 カワイイと思ってるよ",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_040"] = "ダメか?",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_060"] = "じらしプレイかよ",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_080"] = "科学の授業はオタクばっかでキモい",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_100"] = "でもお前が写真送ってくれたら 気が紛れる",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_010"] = "ここが正念場だよ…",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_020"] = "コーナー決めて…",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_030"] = "ヤバッ… ひと轢いちゃった…",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_040"] = "ここでギアチェンジッ!",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_050"] = "そこのフェラーリ どいたどいた!",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_060"] = "あと少し…!",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_070"] = "3位!? なによこのクソゲー! くっだらない…",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_010"] = "掃除は好きだけど 足ひきずるのはやめてくれ",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_020"] = "汚れが広がってしまうだろう",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_030"] = "でもこれはいいモップだ。 大事に使うよ",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_040"] = "僕は幽霊のようなものさ。 生徒には見えてないのさ",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_050"] = "かわいそうに… 行方不明だなんて…",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_020"] = "バイト代入ったのか?",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_060"] = "ようし ボコボコだ!",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_090"] = "指図すんなよ!",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_040"] = "なんのことだよ",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_070"] = "ローガン 頼むよ もうやめて",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_100"] = "お願い… 授業に行かせてよ",
  ["Cue_E1_2A_Corridor_Dial08_Logan_010"] = "ダニエル! バイト代 入ったか?",
  ["Cue_E1_2A_Corridor_Dial08_Logan_030"] = "金のこと忘れてねえだろな",
  ["Cue_E1_2A_Corridor_Dial08_Logan_050"] = "こいつボコボコにされてえらしい",
  ["Cue_E1_2A_Corridor_Dial08_Logan_080"] = "俺に指図すんのか?",
  ["Cue_E1_2A_Corridor_Dial09_Dana_020"] = "いつもでしょ",
  ["Cue_E1_2A_Corridor_Dial09_Dana_040"] = "たまにはシャキッとしてよ",
  ["Cue_E1_2A_Corridor_Dial09_Dana_060"] = "居眠りするなら授業出る意味ないじゃない",
  ["Cue_E1_2A_Corridor_Dial09_Dana_080"] = "まったく…",
  ["Cue_E1_2A_Corridor_Dial09_Dana_100"] = "あなたと話してると 怒るのもバカらしくなるわ",
  ["Cue_E1_2A_Corridor_Dial09_Justin_010"] = "眠くてさー… 全然起きられなかったよ",
  ["Cue_E1_2A_Corridor_Dial09_Justin_030"] = "でも君に会うためだったらー… ちゃんと起きるよ",
  ["Cue_E1_2A_Corridor_Dial09_Justin_050"] = "してるよ。 今日なんてさ 7 時に起きたんだぜ?",
  ["Cue_E1_2A_Corridor_Dial09_Justin_070"] = "授業なんてもともと意味ないよ",
  ["Cue_E1_2A_Corridor_Dial09_Justin_090"] = "俺はね 授業中 起きてたら 負けだと思ってる",
  ["Cue_E1_2A_Corridor_Dial09_Justin_110"] = "不眠症になったら 俺に相談しなー",
  ["Cue_E1_2A_Corridor_Insertion_ArtClassToCorridor_Max_010"] = "いつも通りの風景…",
  ["Cue_E1_2A_Corridor_Insertion_ArtClassToCorridor_Max_020"] = "トイレに行って ちょっとひとりになろう |顔でも洗って シャキッとしなきゃ… もっとバカにされちゃう",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_010"] = "おい! 非常ベルが聞こえないのか? 早く非難しろ",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_030"] = "お決まりの言い訳だな",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_050"] = "やましいことがあるんだろう。 顔にそう書いてあるぞ",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_070"] = "ならさっさと外へ出るんだ。 それとも出られない理由があるのか?",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_020"] = "トイレに行ってたんです…",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_040"] = "言い訳?",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_060"] = "急にベルが鳴るから…",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Principal_080"] = "もういい マドセン君。 安全の確認が取れた |生徒の尋問はそのくらいにして 早く非常ベルを解除しにいったらどうだね",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_010"] = "今ネイサン・プレスコットが 銃を持ってました…女子トイレで",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_030"] = "はい |銃を持ってブツブツ独り言を言ってるところ 私見たんです |明らかに異常でした…!",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_050"] = "物陰に隠れてて… 女子が女子トイレにいて 何かおかしいですか?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_070"] = "彼… ネイサンは すぐに出ていきました… どうするんですか?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_090"] = "それだけ? 銃を持ってたのに!?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_020"] = "プレスコット君が? 確かかね?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_040"] = "ちょっと待ちなさい |では何かね? 君は見ていたのに ネイサンは気づかなかったと?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_060"] = "そうは言っていない 事実関係をはっきりさせたいだけだ |プレスコット君はこの町の名家のご子息だ |本校における成績も極めて優秀 |彼がトイレで銃を振り回したなど にわかには信じがたい |それでそのあとは?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_080"] = "事実なら… 深刻な問題だ |私が個人的に対応する 知らせてくれてありがとう",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_100"] = "話の続きはまた後ほど 校長室ですることにしよう |分かったら君も早く外へ避難していなさい",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_010"] = "ちょっと具合が悪くて… その… 今日はあの日で…",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_030"] = "ウソじゃないです。 写真の授業中 めまいがして…",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_050"] = "だから具合が悪いって… それだけです。 隠してなんかないし",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_020"] = "だがフラフラ歩き回る元気はある |そんな言い訳をする生徒はごまんといるんだよ",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_040"] = "隠していることがあるなら 言ってみなさい",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_060"] = "君がそういう態度を取るなら もう結構だ。ただ 私の目はごまかせないぞ |君は入学して 3 週間でさっそく問題を起こした |ご両親はさぞがっかりされることだろう |話は以上だ。 行きなさい",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Max_030"] = "えっと… その… 進路のことでちょっと悩みが",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_010"] = "マックス ちょっと来なさい",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_020"] = "顔色が悪いようだが… どうかしたのか?",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_040"] = "すごい汗だ 本当にそれだけかね? 私には何でも打ち明けなさい",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_050"] = "それとも何かやましいことでもあるのか? …どうなんだ? |マックス。 答えなさい",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_010"] = "マックス 早く外へ出なさい",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_020"] = "フラフラしていないで 外に出なさい",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_040"] = "マックス 何をしてる 行きなさい",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_010"] = "この学校 マイノリティが少ないよね",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_030"] = "この地方にしては ってことでしょ?",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_140"] = "ヤッバ! スマホ忘れた!",
  ["Cue_E1_2A_Corridor_Random_CitizenF2_020"] = "そうかな。 私はそうは思わないけど",
  ["Cue_E1_2A_Corridor_Random_CitizenF2_150"] = "非常ベルの音って嫌い!",
  ["Cue_E1_2A_Corridor_Random_CitizenF3_040"] = "あんた 結局あいつと付き合ってるんだって?",
  ["Cue_E1_2A_Corridor_Random_CitizenF3_160"] = "銃声なんかしなかったよね",
  ["Cue_E1_2A_Corridor_Random_CitizenF4_050"] = "ボルテックス・クラブのパーティ 超アツいらしいよ",
  ["Cue_E1_2A_Corridor_Random_CitizenF4_070"] = "実際 世の中 そんなもんじゃん",
  ["Cue_E1_2A_Corridor_Random_CitizenF5_060"] = "でもふるいにかけられてるみたいで感じ悪くない? |親の仕事とか クレカ持ってるかとか",
  ["Cue_E1_2A_Corridor_Random_CitizenF6_090"] = "LA の友達は オレゴンは毎日雨で寒いって言ってたけど |そんなことないし この夏は一度も雨降らなかったよ |これって異常気象?",
  ["Cue_E1_2A_Corridor_Random_CitizenF7_100"] = "地元の住民がわざとウソの情報流してんでしょ",
  ["Cue_E1_2A_Corridor_Random_CitizenM1_010"] = "授業だりー つまんねー",
  ["Cue_E1_2A_Corridor_Random_CitizenM1_110"] = "おーい 待ってくれよ!",
  ["Cue_E1_2A_Corridor_Random_CitizenM2_020"] = "授業中 スマホ見てると怒られるぜ",
  ["Cue_E1_2A_Corridor_Random_CitizenM2_120"] = "煙のにおいしないよな?",
  ["Cue_E1_2A_Corridor_Random_CitizenM3_030"] = "ライブのチケット 150 ドルとか ありえねー",
  ["Cue_E1_2A_Corridor_Random_CitizenM3_130"] = "凸面鏡は別名「集光鏡」とも言って 光が集まる位置に像を結ぶ構造なんだ",
  ["Cue_E1_2A_Corridor_Random_CitizenM4_040"] = "そのうち 50 パーはサービス料なんだって",
  ["Cue_E1_2A_Corridor_Random_CitizenM5_050"] = "大丈夫だ… 俺は絶対大丈夫…",
  ["Cue_E1_2A_Corridor_Random_CitizenM6_060"] = "次のターゲットはあの子だ",
  ["Cue_E1_2A_Corridor_Random_CitizenM6_080"] = "お前のお袋",
  ["Cue_E1_2A_Corridor_Random_CitizenM7_070"] = "で その次は?",
  ["Cue_E1_2A_Corridor_Random_CitizenM7_090"] = "だから あんな笑い上戸だったのか",
  ["Cue_E1_2A_Corridor_Random_CitizenM8_100"] = "違うって 授業で使う画材が思ったより高くてさ! |お願いだから あと 600 ドル振り込んでよ…",
  ["Cue_E1_2A_Corridor_ToiletDoor_Interact03_Max_010"] = "よかった 誰もいない。 こんなとこ人に見られたら 最悪だよ…",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Chloe_020"] = "二度と近づくんじゃねえぞ!",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Nathan_010"] = "ウソだろ…",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Nathan_030"] = "ふざけやがって…",
  ["Cue_E1_2A_Toilets_Mirror_Interact01_Max_010"] = "今日はどこへ行っても誰かにバカにされてる気分…",
  ["Cue_E1_2A_Toilets_Mirror_Interact01_Max_020"] = "授業中にあの幻を見てからおかしくなった… 私どうしちゃったんだろう…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_030"] = "ちゃんと誰もいないか確認したんだろうな? さて 本題だけど…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_050"] = "ウソつけ ボンボンめ",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_070"] = "いいのか そんな態度をとって。 お前のろくでもない「ビジネス」のこと…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_090"] = "あいにく あたしが欲しいのは現金だけだ。 そんな話 興味ないね",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_100"] = "ご両親の耳に入ったら なんて言うだろうね。 新聞にデカデカと出たら…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_120"] = "それとも 学校中にネイサン・プレスコットは |トイレで独り言を言う 泣き虫野郎だって言いふらして…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_140"] = "何よそれ? ちょっとやめて… やめろ 近づくな!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_160"] = "こんなことしてタダで済むと思ってるの…",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_180"] = "ふざけんなよ 離れろ!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_010"] = "大丈夫だ 落ち着け 心配いらない… 深呼吸だ …|しっかりしろ… ここは俺の庭だ… 何でも思いどおりになる… だろ?",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_020"] = "何の用だ",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_040"] = "金ならねえぞ",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_060"] = "金持ちなのは親だ",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_080"] = "そうか… ならこうしよう。 うちの商品 回してやるよ",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_110"] = "親は関係ねえだろう!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_130"] = "てめえ なめた口利きやがって ぶっ殺してやる!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_150"] = "俺に指図するんじゃねえ! どいつもこいつも ひとをコケにしやがって!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_170"] = "てめえみてえなクズ 死んだって誰も気にしねえだろ!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_190"] = "え… ウソだろ! 違う… そんなつもりは…!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Rewind_Nathan_200"] = "そんな ウソだろ… なんで! なんでこんなこと…! お前が俺を怒らせるから…! |どいつもこいつも…! |俺… どうしたらいいんだよ… もうイヤだ…  もうおしまいだ…",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_010"] = "大丈夫 自信持たなきゃ… 私には才能がある…",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_020"] = "ダメだ…",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_030"] = "「扉が閉じたとき 別の窓が開いている」… とか なんとか…",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_040"] = "シャッターチャンス。 これは絶対撮らないと…",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_050"] = "一歩踏み出さなきゃ…",
  ["Act_E1_3A_CampusA_BigFootBanner_Look01_Max_010"] = "美術のコンクールとか科学展にも こういう垂れ幕を作ればいいのに",
  ["Act_E1_3A_CampusA_BigFootStatue_Look01_Max_010"] = "我が校のマスコットよ 私たちを見守りたまえ…",
  ["Act_E1_3A_CampusA_Board01_Look01_Max_010"] = "サスカッチとレーザーバックが本当に戦うなら興味がわいたのに",
  ["Act_E1_3A_CampusA_Board01_Look02_Max_010"] = "ノーコメント",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_010"] = "ちょっとお腹が空いたな…",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_020"] = "詩のコンテスト 撮影してみたい… 自信ないけど",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_040"] = "地元のことをもっと知るべきだと思うけど… 行かないだろうな",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_010"] = "このポスターのおかげでどれだけいじめが減ったんだろう",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_030"] = "まだそこまで追い詰められてないしなあ",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_040"] = "これは行ってみないと だね",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_050"] = "オタクの聖地って感じ? 行ってみようかな",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_060"] = "パス",
  ["Act_E1_3A_CampusA_BrookeBag_Interact01_Max_010"] = "小さいのに大げさな名前がついてるんだな",
  ["Act_E1_3A_CampusA_BrookeBag_Look01_Max_010"] = "ウォーレンと同じカバンかな? ちょっとオタクっぽいような…",
  ["Act_E1_3A_CampusA_BusSign_Look01_Max_010"] = "いつでも シアトル行きのバスに乗れる…",
  ["Act_E1_3A_CampusA_CHBrooke_Look01_Max_010"] = "ブルック 本当にドローンを持ってるの?",
  ["Act_E1_3A_CampusA_CHBrooke_Look02_Max_010"] = "そっけない反応。 時間を戻して関心を引くべきかも",
  ["Act_E1_3A_CampusA_CHDaniel_Look01_Max_010"] = "ダニエルはいつも何かを描いてる。 内気さは彼の勝ちね",
  ["Act_E1_3A_CampusA_CHDaniel_Look02_Max_010"] = "話しかけてみてよかった。もっといろんなことにチャレンジすべきかも",
  ["Act_E1_3A_CampusA_CHDaniel_Look03_Max_010"] = "ダニエルを傷つける気はなかったのに。申し訳ないな…",
  ["Act_E1_3A_CampusA_CHEvan_Look01_Max_010"] = "たしか エバンって名前。 いっつもなにかに集中してる",
  ["Act_E1_3A_CampusA_CHEvan_Look02_Max_010"] = "しっかりして 私… 巻き戻して 正解を答えるべきかな",
  ["Act_E1_3A_CampusA_CHGrant_Look01_Max_010"] = "グラント先生 熱心に署名を集めてるな…",
  ["Act_E1_3A_CampusA_CHGrant_Look02_Max_020"] = "私の答え あれでよかったのかな…",
  ["Act_E1_3A_CampusA_CHHayden_Look01_Max_010"] = "ヘイデンとボルテックス・クラブの取り巻きだ。 「夢を生きる」ってやつね…",
  ["Act_E1_3A_CampusA_CHJustin_Look01_Max_010"] = "ジャスティンとスケーター仲間だ。 色々できてかっこいいな",
  ["Act_E1_3A_CampusA_CHJustin_Look02_Max_010"] = "スケーター界の秘密を知ったことだし |巻き戻せばジャスティンにもっと話を聞けるかも",
  ["Act_E1_3A_CampusA_CHLuke_Look01_Max_010"] = "ルーク・パーカーだ。 ザッカリーがロッカーに押し込んだ子… かわいそうに",
  ["Act_E1_3A_CampusA_CHStella_Look01_Max_010"] = "ステラはいつも真面目で しっかりしてる。 さすがだな",
  ["Act_E1_3A_CampusA_CigaretteButts_Look01_Max_010"] = "うわっ。 電子タバコにすればいいのに",
  ["Act_E1_3A_CampusA_Coins_Look01_Max_010"] = "いい画だな… 水の底できらめく 緑のコイン。 みんなのお願いは叶ったのかな",
  ["Act_E1_3A_CampusA_Direction_Look02_Max_010"] = "ウォーレンの USB を取りに行かなきゃ",
  ["Act_E1_3A_CampusA_EvanPhotoBook_Look01_Max_010"] = "すごくいい写真だ… レイチェル・アンバーの顔から目が離せない…",
  ["Act_E1_3A_CampusA_EvanPhotoBook_Look02_Max_010"] = "エバンのポートフォリオ プロみたいでかっこいい。 中身 見てみたいな…",
  ["Act_E1_3A_CampusA_Fountain_Max_010"] = "本当におかしな日だな…",
  ["Act_E1_3A_CampusA_Fountain_Max_020"] = "いろいろ起きすぎて混乱しちゃうよ",
  ["Act_E1_3A_CampusA_Fountain_Max_030"] = "訳のわからない幻覚も この… 力も",
  ["Act_E1_3A_CampusA_Fountain_Max_040"] = "いまにも全部夢でした… って目覚めそう",
  ["Act_E1_3A_CampusA_Fountain_Max_050"] = "でも やっぱりどう考えても夢の感じがしない",
  ["Act_E1_3A_CampusA_Fountain_Max_060"] = "ってことは 本当に時間を巻き戻したんだ",
  ["Act_E1_3A_CampusA_Fountain_Max_070"] = "なにか 理由があるはず。 それを解明しなきゃ…",
  ["Act_E1_3A_CampusA_GoingPark_Max_020"] = "ウォーレンに会う前に 部屋から USB メモリを取ってこないと",
  ["Act_E1_3A_CampusA_GoingSchool_Max_010"] = "もう中には戻れない…",
  ["Act_E1_3A_CampusA_GoingSchool_Max_020"] = "部屋に戻って ウォーレンの USB を取ってこなきゃ",
  ["Act_E1_3A_CampusA_GoingStreet_Max_020"] = "ウォーレンは USB を受け取るために駐車場で待ってる。寮に戻らなきゃ",
  ["Act_E1_3A_CampusA_Graffiti01_Look01_Max_010"] = "コインを投げ入れて願いを叶えるんじゃなかったの?",
  ["Act_E1_3A_CampusA_Graffiti02_Look01_Max_010"] = "なにかあげたいけど ポケットはからっぽよ",
  ["Act_E1_3A_CampusA_Graffiti03_Look01_Max_010"] = "冴えた落書きね",
  ["Act_E1_3A_CampusA_Graffiti03_Look01_Max_020"] = "これって何語?",
  ["Act_E1_3A_CampusA_Graffiti04_Look01_Max_010"] = "かわいそうなカワウソ… なんちゃって",
  ["Act_E1_3A_CampusA_Graffiti05_Look01_Max_010"] = "ふーん",
  ["Act_E1_3A_CampusA_JeffersonPhoto01_Look01_Max_010"] = "ジェファソン先生の作品を展示してるの 最高",
  ["Act_E1_3A_CampusA_JeffersonPhoto02_Look01_Max_010"] = "これは先生の代表作のひとつ。 その瞬間を切り取ってるのが素敵",
  ["Act_E1_3A_CampusA_JeffersonPhoto03_Look01_Max_010"] = "ジェファソン先生はいろんな作風ができるんだよね",
  ["Act_E1_3A_CampusA_MPA01_Look01_Max_010"] = "わざわざポスターの上に貼るなんて… |レイチェル・アンバーって子を本当に見つけたいんだね",
  ["Act_E1_3A_CampusA_MPA01_Look02_Max_010"] = "一人の人間のために こんなにポスターが貼られてるなんて…",
  ["Act_E1_3A_CampusA_MPAGround_Look01_Max_010"] = "レイチェル・アンバー。 きれいで 希望に満ちた顔… |いったいどうなっちゃったんだろう…",
  ["Act_E1_3A_CampusA_Park_Look02_Max_020"] = "寮に戻らなきゃ。 今日は長い一日だな…",
  ["Act_E1_3A_CampusA_Poster01_Look01_Max_010"] = "なんでカワウソ…? よくわからない…",
  ["Act_E1_3A_CampusA_Poster02_Look01_Max_010"] = "カワウソがよっぽど好きなのかな",
  ["Act_E1_3A_CampusA_Poster03_Look01_Max_010"] = "ウソでしょ? これは絶対に行くしかない",
  ["Act_E1_3A_CampusA_Poster04_Look01_Max_010"] = "グラント先生は監視システムに反対みたい…",
  ["Act_E1_3A_CampusA_SignMainBuilding_Look01_Max_010"] = "今日の授業が終わっててよかった…",
  ["Act_E1_3A_CampusA_Statue_Look01_Max_010"] = "スマホ片手にうろうろしてる生徒の姿を見たら 学校の創始者はなんて言うだろう",
  ["Act_E1_3A_CampusA_SwimmingPoolDoor_Look01_Max_010"] = "水泳部… オッターズの巣だ",
  ["Act_E1_3A_CampusA_Tree_Max_010"] = "5 年ぶりに戻ったけど 変な感じ…",
  ["Act_E1_3A_CampusA_Tree_Max_020"] = "すぐに学校になじめると思ったのにな…",
  ["Act_E1_3A_CampusA_Tree_Max_030"] = "妙なことが起きたせいで 余計によそ者気分…",
  ["Act_E1_3A_CampusA_Tree_Max_040"] = "おまけに 日記とカメラ以外に相談相手はいないし",
  ["Act_E1_3A_CampusA_Tree_Max_050"] = "こんな青春で本当にいいのかな…?",
  ["Act_E1_3A_CampusA_Tree_Max_060"] = "まさに身も心も孤独って感じ…",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_010"] = "さて 寮から USB を持ってこなきゃ",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_020"] = "ウォーレンが USB を待ってる。 取りに行こう",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_030"] = "ウォーレンの USB を取りに行かなきゃ",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_040"] = "受信箱が爆発する前に ウォーレンのメールを読もう…",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_010"] = "今日はいったいなんなの?",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_020"] = "おかしいでしょ… 幻覚とか… 力とか…",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_030"] = "女の子が撃たれるのを見たなんて…",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_040"] = "ネイサン・プレスコットは おかしい。 校長に言ってよかった",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_050"] = "ネイサン・プレスコットは危険だ。 校長に言えばよかった…",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_070"] = "本当に時間を巻き戻したなんて…",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_010"] = "5 年経って来てみると 変な感じ…",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_020"] = "アルカディア・ベイは変わってないようで… 変わってる",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_030"] = "ブラックウェルは… 高校だけど大学みたい",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_040"] = "古い森の近くに学校があるのっていいな",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_050"] = "子どもの頃は町を知り尽くしてたのに 今は誰も知らない…",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_060"] = "まさに身も心も孤独って感じ…",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_004"] = "すごい よく知ってるね。 ちょっと驚いたよ",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_011"] = "ひょっとして… ドローン飛ばしたいの?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_012"] = "一緒にしないでよ。 ドローンってなんだか分かってるの?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_013"] = "ネットのウワサ信じすぎでしょ? |こりゃ操縦はムリだね |ウォーレンからは 頭いいって聞いてたのに… あっち行ってくれる?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_017"] = "違います。 まだ誰にも見せてないんだ",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_021"] = "へえ さすが。 ウォーレンが一目置くだけあるね",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_014"] = "飛ばしたい! 飛行機とか気球とか大好き!",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_015"] = "それってブルックの? 違法じゃないの?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_016"] = "それ HiFly ドローンだよね。 B400 EVO モデル? いいなあ",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_018"] = "えっと… 武器でしょ?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_019"] = "ドローンって軍事兵器じゃないの?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_020"] = "航空写真が好きなの |遠くまで飛ばせるモデルは 撮影機材に向いてるんだ |すごい時代だよね",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_023"] = "ブルック",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase02_Brooke_001"] = "あとにして。 今ドローンの整備で忙しいから",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase02_Brooke_004"] = "デイビッド・マドセンなら ドローンをうちらの監視に使うだろうね",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_001"] = "ああ… マックス。 よかったら… 頼んでもいいかな? |スケッチの… モデルになってほしいんだ |完成したら SNS にアップするけど…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_005"] = "いいんだ 僕なんかじゃイヤだよね。 じゃ スケッチを続けるから…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_008"] = "インスピレーションといえば… 一目見ただけで湧き立つモデルがいたよ… |レイチェル・アンバーさ…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_010"] = "急に授業に来なくなってね |家出したって言う人もいるし 崖から飛び降りたって言う人もいるけど… |無事だといいな",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_011"] = "違うけど 僕の絵のモデルになりたいって言われて 描いてあげたことがあるんだ",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_012"] = "そんな! 君だって… 十分代わりになるよ",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_015"] = "彼女の顔をあんな形で見るのはつらいよ… 優しい子だった",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_002"] = "ごめん やめておく。 すごく光栄だけど…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_004"] = "友達だったの?",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_007"] = "私でよければもちろん! インスピレーション湧きそう?",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_009"] = "何があったんだろうね。 なんでいなくなったのかな",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_013"] = "ダニエル お疲れ",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_014"] = "どこへ行ってもビラが貼ってあるよね…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_016"] = "それじゃ… そろそろスケッチ始めて |レイチェルほどいいモデルじゃないけど…",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase02_Daniel_001"] = "ありがとう。 よかったら また今度 モデルになってよ",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase02_Daniel_002"] = "スケッチ中なんだ。 ごめんね",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_001"] = "その前にテストさせてくれ。 質問に答えてもらうよ |「崩れ落ちる兵士」の撮影者は?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_003"] = "へえやるな。 ちょっと意外だったよ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_007"] = "おいおい… 君はストリートフォトとジャーナリズムの区別もつかないのか? |ポートフォリオは見せられないな",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_010"] = "たしかに 2人とも著名な戦場カメラマンだが まさか混同するとはね |残念ながら 不正解だ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_012"] = "君とは気が合いそうだな |僕のポートフォリオを見てくれてかまわないよ |君にはその価値がありそうだ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_028"] = "あの写真が撮影された当時 彼はまだ生まれてもいなかったというのに? |それにマッカリーはカラーで撮る |悪いけど ポートフォリオは見せられない",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_002"] = "ロバート・キャパでしょ? あの写真の真相はともかく 彼の作品は大好き",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_004"] = "見直してくれた?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_006"] = "ロベール・ドアノーだっけ…?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_009"] = "えーっと… ユージン・スミス",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_013"] = "拝見いたします",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_026"] = "エバン。 ポートフォリオを見せてもらってもいいかな?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_027"] = "えっと… スティーブ・マッカリー?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_001"] = "遠慮せず見てくれ。 僕も光栄さ。 どうか お手柔らかに頼むよ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_003"] = "アマチュアにつきあってる暇はないよ。 一枚でも多く撮らなきゃ |悪く思わないでくれ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_004"] = "失礼… ポートフォリオ作りで忙しいんだ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_001"] = "見てのとおり レイチェル・アンバーは最高のモデルだった |僕の感性に訴えるアングルを心得ていた",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_002"] = "いわば「戦友」ってところさ。 僕を批判せず 理解してくれた |ボルテックスの連中とつきあっても 自分を見失っていなかった |芯の通った子だったよ",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_005"] = "一言で言えば「機知縦横」。意味分かる?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_009"] = "よからぬことだよ… 間違いない",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_003"] = "親しかったの?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_004"] = "どんな子だった?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_006"] = "分かるよ それぐらい",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_007"] = "お気遣い どうもありがとう",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_008"] = "何があったんだろうね…",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_010"] = "エバン",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_001"] = "あらマックス ちょっとだけ話を聞いてくれないかしら? |今 署名運動を始めてるのよ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_004"] = "残念ね |あなたたちの学校生活をおびやかす計画への反対運動なのに |またあとで話を聞きにきてちょうだい。 よろしくね",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_005"] = "警備主任のデイビッド・マドセンが 校内に監視カメラを設置しようとしているの |廊下に教室 体育館と寮にもね |ここはハイスクールです |刑務所と同じにされては困るわ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_008"] = "ブラックウェルは由緒正しき学校です |ネイティブ・アメリカンが創立し 開拓者たちにも門戸を開いた |暴力とは無縁よ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_009"] = "断固阻止しないと。 取り返しのつかないことになってからじゃ遅いわ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_012"] = "彼らは植民者たちを温かく受け入れ 2 つの文化は共生関係を築いて発展したの",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_013"] = "自分の学校の歴史を知るのは大事よ |意外な事実に驚くはず |この辺り一帯には霊力が満ちてる |それが感性を刺激するのね",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_014"] = "特別講義はこのくらいにして… |時代錯誤な監視システムに抗議する署名をお願いできるかしら?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_017"] = "もちろん警備は大事よ |ただ プライバシーがなくなるのも危険だと言ってるの |あなたたちの世代は なんでも録画されて当然だと思ってるのね",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_018"] = "ありがとう あなたならきっと賛成してくれると思ったわ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_030"] = "そういう問題じゃないのよ |自由を重んじるブラックウェルの伝統と 公民権は保護しないと",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_032"] = "中立ってことね |先生だってもちろんレイチェルの無事を祈る気持ちは同じよ |でもこの署名はそれとは別",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_034"] = "科学はある意味 歴史よ |この町の民間伝承はとても興味深いわ |機会があれば特別授業で取り上げたいと思ってるの",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_035"] = "署名運動の説明を聞く気になった?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_038"] = "ずいぶん忙しいのね。 気が変わったら いつでも来なさい 詳しい話をするわ",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_002"] = "でも… 今ちょっと急いでて… あんまり時間ないんです…",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_003"] = "ええ もちろん かまいませんよ。 何の署名ですか?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_006"] = "そんなの マドセン主任の嫌がらせを増長させるだけです",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_007"] = "信じられない。 今のご時世 確かにいろいろ物騒だけど 寮にカメラなんて…",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_010"] = "ネイティブ・アメリカン?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_011"] = "そんなに昔から? 知らなかったです",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_015"] = "もちろんです。 安全対策はいいけど… これは行き過ぎです",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_016"] = "おっしゃることはよく分かるんですけど |でも 監視カメラがあると安心なのも事実なので…",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_029"] = "グラント先生",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_031"] = "カメラがあればレイチェルは見つかったかも。 どっちがいいとも言えない…",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_033"] = "科学の先生なのに歴史好きなんですね",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_036"] = "はい。 詳しく聞かせてください",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_037"] = "いえ… まだ急いでて ちょっと時間がないです",
  ["Cue_E1_3A_CampusA_CHGrant_Phase02_Grant_002"] = "署名は順調よ。 目標数に届きそう",
  ["Cue_E1_3A_CampusA_CHGrant_Phase02_Grant_004"] = "写真以外には興味ないわよね。 別にかまわないのよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_001"] = "お! レトロな自撮り系女子のご登場だな!",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_004"] = "この学校の生徒が自然と身につけるスキルさ |ボルテックス・クラブを代表するメンバーだったら… 特にね",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_005"] = "そんなに嫌うなよ… |ネイサンは親が金持ちだから なにかと目をつけられやすいんだ |つきあってみると いいヤツだよ |みんな単なるねたみさ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_008"] = "メンバーになれない人にとってはね。 いたって健全なクラブさ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_010"] = "ホントさ。 君も一度 遊びにきてみるといいよ |そうすれば ウワサなんか信じなくなる",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_013"] = "俺たちと遊んだことがないからさ |ビクトリアも パーティでは楽しい子なんだよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_014"] = "考えすぎだよ。 俺たちはそんなくだらないことしなくたって 十分楽しめる",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_016"] = "くだらないこと言うなよ |レイチェルもよく俺たちと遊んでたんだ。 楽しい子だったよ |頭のキレるタイプでさ…",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_021"] = "そりゃ ムシの居所が悪いときもあるさ。 人間なら当然だろ?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_022"] = "それは残念 |パーティではすごく楽しいヤツなのに |盛り上げるのも最高にうまいしね",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_025"] = "パーティ好きな子だったよ。 明るくて楽しくて… |そして何より すごく美人だった",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_027"] = "ああ またな。 俺もそろそろ 勉強に戻ったほうがよさそうだ |今度 デーナと君をパーティに呼ぶよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_029"] = "そうだなあ… まあ… 行方不明ってことだけははっきりしてるな",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_031"] = "君は分かってないな |ああ見えて ビクトリアだってレイチェルに一目置いてたよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_033"] = "いやいや… レイチェルはレイチェルさ |俺たちにはもったいないぐらいだった |俺にそう言わしめるんだから 相当さ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_035"] = "ああ そうだね。 俺もそろそろ 勉強に戻ったほうがよさそうだ |今度 デーナと君をパーティに呼ぶよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_037"] = "マックス どうした?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_002"] = "どうも 自撮り系女子です。 ヘイデンは相変わらずまったりしてるね",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_003"] = "でも ネイサン・プレスコットもメンバーでしょ?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_006"] = "そもそもボルテックス・クラブって何? 閉鎖的なイメージだけど",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_007"] = "すぐキレる危険人物だと思うけど",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_009"] = "ホントかなあ…",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_011"] = "遠慮しとく。 パーティとか 興味ないから",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_012"] = "ボルテックス・クラブのパーティに? |なんか ドッキリ仕掛けられそうで怖いんだけど…",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_015"] = "生徒が行方不明なのに パーティで騒ぐ気分になれないよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_019"] = "ヘイデン",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_020"] = "それでも ネイサンと遊ぶ気にはなれないよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_023"] = "それはどうかな",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_024"] = "レイチェルと知り合いだったの?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_026"] = "それじゃ またね",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_028"] = "何があったんだろうね…",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_030"] = "ビクトリアはレイチェルと仲よかったの? やきもち焼きそうだけど",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_032"] = "レイチェルもボルテックス・クラブのメンバーだったの?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_034"] = "なんだか余計混乱してきたよ… すべてがナゾって感じ… また今度話そう",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_036"] = "ねえ ヘイデン",
  ["Cue_E1_3A_CampusA_CHHayden_Phase02_Hayden_001"] = "悪いけど テストがあるから勉強しないと。 あとにしてくれよ",
  ["Cue_E1_3A_CampusA_CHHayden_Phase02_Hayden_002"] = "マックス また今度にしてくれよ",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_001"] = "マックスじゃーん。 かましにきたの?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_004"] = "うわ だっせー |ノーズスライドかトレフリップぐらい知っててもらわなきゃ話になんないね",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_005"] = "最初のトリックは何?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_008"] = "へえええ 結構詳しいじゃん",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_010"] = "そんじゃさ 俺らがお手本見せてやるよ。 リクエストある?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_020"] = "うちのトレバーがいいとこ見せるぜ",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_002"] = "かます? そんな魚いたような気が…",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_003"] = "もちろん そのつもり",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_006"] = "えっと… ジャンプかな",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_007"] = "ノーズスライドしたいとこだけど 誰かトレフリップ見せてくれるかな",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_009"] = "まあね。 ぜんぜんヘタくそだけど",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_018"] = "じゃあ… ノーズスライド",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_019"] = "トレフリップがいいな",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_021"] = "ジャスティン",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_003"] = "君ってたしか 写真の勉強してんだよね? スケボーやってそうに見えないけど",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_006"] = "そりゃ残念 |女子大歓迎なんだけどなー |レイチェル・アンバーとツレも よく俺たちとつるんでたし",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_008"] = "だよねー |女子大歓迎なんだけど |レイチェル・アンバーとツレも俺たちとつるんでたし",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_010"] = "よくスケボーしに来てたけど ある日急に来なくなったんだよ |どっかで元気にしてりゃいいけど |レイチェルに何かするようなヤツは 俺らがボードでボッコボコにするぜ!",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_011"] = "名前 忘れちゃったけど… かわいかったよ |タトゥー入ってて 髪の毛 青くて かっけーの |レイチェルがいなくなって その子も来なくなっちゃったんだけどさ |さみしいよね",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_015"] = "またマックスじゃーん。 どした?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_018"] = "俺らの写真撮りたくなったら いつでもモデルになるぜ",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_019"] = "まさか! あんなツンツンした女とつるむかっつの",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_020"] = "スケボーやってそうに見えないけど",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_004"] = "うん あんまり",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_005"] = "昔やってたけど 今はカメラ一筋",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_012"] = "レイチェルと知り合い?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_013"] = "レイチェルのツレって?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_014"] = "よっ!",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_016"] = "ビクトリアともよく遊ぶ?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_017"] = "じゃ またあとでね",
  ["Cue_E1_3A_CampusA_CHJustin_Phase03_Justin_002"] = "スケボーに興味ないなら 話すことはないね",
  ["Cue_E1_3A_CampusA_CHJustin_Phase04_Justin_001"] = "またトリック見せてやろっか?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_001"] = "今はほっといてくれるかな?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_004"] = "ネイサン・プレスコットのやつ |親がこの学校にたくさん寄付してるからって調子に乗りやがって |ボルテックス・クラブがなんだってんだ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_007"] = "知り合いなのか?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_008"] = "誰かガツンと言ってやらなきゃダメだ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_013"] = "え! それホント?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_014"] = "ちょっとその話 詳しく聞かせてよ。 何があったの?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_015"] = "それがホントなら 世の中 善人だらけだ |正義は寝て待てって? アホらしい…",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_017"] = "マックス すげえじゃん! ついに正義の味方の登場だ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_002"] = "どうしたの?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_003"] = "ああ ごめん… じゃあ またね",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_006"] = "あいつにはホント 気をつけたほうがいいよ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_009"] = "銃 持ってたから先生に報告した",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_010"] = "違うよ ときどき見かけるだけ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_011"] = "そのうちきっと 罰が下ると思うよ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_012"] = "そのうち墓穴掘るでしょ",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_016"] = "銃を振り回してたから校長先生に言いつけたの… あとは先生次第だけど",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_018"] = "ルーク?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_019"] = "ううん。 ああいう勘違いしたボンボンとは 関わりたくないな",
  ["Cue_E1_3A_CampusA_CHLuke_Phase02_Luke_001"] = "話せてよかったよ マックス。 また今度な",
  ["Cue_E1_3A_CampusA_CHLuke_Phase02_Luke_002"] = "また今度話そうぜ",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_002"] = "うん 私も先生の作品 大好き。 有名な先生に教えてもらえてラッキーだよね",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_003"] = "でもちょっと… よそよそしいというか 近づきがたいというか… |偉そうってわけじゃないけど 何考えてるか分からない",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_007"] = "え… どういうこと?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_009"] = "そ… そうなんだ… 学校生活って 毎日驚きの連続だね",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_010"] = "レイチェルと知り合いだったの?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_013"] = "ステラ お疲れ",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_014"] = "どうなんだろう |確かに天才だとは思うけど 先生の言うこと全部うのみにするのは違うかな",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_017"] = "ビクトリア 分かりやすいよね。 先生は相手にしてないと思うよ",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_018"] = "言われてみれば 先生はビクトリアをスルーしてるね。 先生もバカじゃないし",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_020"] = "まさか。 先生クビになっちゃうよ。 第一 生徒とつきあったりしないでしょ",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_001"] = "あなたはたしか 写真のクラスで一緒だよね |ジェファソン先生 最高じゃない?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_004"] = "ホントに |ニューヨークでの作品もよかったけど やっぱり先生のルーツはオレゴンだから |あのマーク・ジェファソンがこんな田舎の学校で教えてるなんて |イーストコーストの高級ギャラリーは今頃歯ぎしりしてるでしょうね |それに先生かなりイケメンだし",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_005"] = "まあね。 先生はアーティストだから",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_006"] = "ビクトリアがいなかったら 私もアタックするのに",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_008"] = "それはどうかな",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_011"] = "そういうわけじゃないけど ビクトリアたちと一緒にいるのをよく見かけたよ |レイチェルに関しては いろいろとすごいウワサを聞いてる",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_012"] = "ま そのうちいろいろ分かってくるよ。 それじゃ… また授業でね",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_015"] = "ちょっと気取ったとこはあるけど 本音で向き合ってくれるいい先生だよ",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_016"] = "私もそう思う。 でも ライバルは他にもいるし…",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_019"] = "本当に何も知らないんだね |ジェファソン先生はレイチェル・アンバーと寝たことがある |これは確かな情報だよ",
  ["Cue_E1_3A_CampusA_CHStella_Phase02_Stella_001"] = "ごめん 今ちょっと忙しいから",
  ["Cue_E1_3A_CampusA_DanielDraws_Daniel_010"] = "いいね いいポーズだ",
  ["Cue_E1_3A_CampusA_DanielDraws_Daniel_020"] = "うん いいね…",
  ["Cue_E1_3A_CampusA_DanielDraws_Max_030"] = "すごいよ ダニエル…!",
  ["Cue_E1_3A_CampusA_DroneControl_Brooke_010"] = "はい。ドローン 操縦していいよ",
  ["Cue_E1_3A_CampusA_FactNathan_Principal_010"] = "ネイサン・プレスコット君 至急校長室に来るように。 以上",
  ["Cue_E1_3A_CampusA_Idle_Grant_010"] = "校内のプライバシーが侵害されようとしています。 署名にご協力ください!",
  ["Cue_E1_3A_CampusA_Idle_Grant_020"] = "あなたたち全員に関わる 深刻な問題ですよ",
  ["Cue_E1_3A_CampusA_Idle_Grant_030"] = "あと 100 人の署名が集まれば 公聴会を開けます",
  ["Cue_E1_3A_CampusA_Idle_Grant_040"] = "安全対策も 行き過ぎると危険です",
  ["Cue_E1_3A_CampusA_Idle_Grant_050"] = "政治的な主張とは無関係よ |自由を重んじるブラックウェルの伝統を守るためです",
  ["Cue_E1_3A_CampusA_Idle_Grant_060"] = "スマホでチャットする時間があったら この問題のことも考えてみて",
  ["Cue_E1_3A_CampusA_Idle_Grant_070"] = "警備員にチャットの内容まで監視されたら 困るでしょう?",
  ["Cue_E1_3A_CampusA_Idle_Grant_080"] = "みんな聞いてる?",
  ["Cue_E1_3A_CampusA_Idle_Grant_090"] = "もしもし?",
  ["Cue_E1_3A_CampusA_StellaFriend_CitizenF1_020"] = "コントラストが絶妙",
  ["Cue_E1_3A_CampusA_StellaFriend_Stella_010"] = "すごく繊細だよね…",
  ["Cue_E1_3A_CampusA_StellaFriend_Stella_030"] = "ジェファソン先生は光と影のエキスパートだよ",
  ["Act_E1_3B_CampusB_BrokenWindow_Look01_Max_010"] = "カルマっていうのはこういうこと!",
  ["Act_E1_3B_CampusB_Bucket_Interact02_Max_010"] = "今は無理… サミュエルにバレちゃう",
  ["Act_E1_3B_CampusB_Bucket_Look01_Max_010"] = "ビクトリアの近くにペンキ… いいこと考えた",
  ["Act_E1_3B_CampusB_Bucket_Look02_Max_010"] = "さあ うまくいくかな",
  ["Act_E1_3B_CampusB_CHAlyssa_Look01_Max_010"] = "アリッサとはもっと仲良くなれそうだな",
  ["Act_E1_3B_CampusB_CHAlyssa_Look02_Max_010"] = "かわいそうに 今のはあざになりそう…",
  ["Act_E1_3B_CampusB_CHAlyssa_Look03_Max_010"] = "これでアリッサが平和に本を読める",
  ["Act_E1_3B_CampusB_CHKate_Look01_Max_010"] = "ケイトだ。 いつもよりふさぎこんでるみたい",
  ["Act_E1_3B_CampusB_CHLogan_Look01_Max_010"] = "こちらローガン・ロバートソン。 100% イヤなヤツ",
  ["Act_E1_3B_CampusB_CHSamuel_Look01_Max_010"] = "サミュエルのことを怖がる人もいるけど 怖い人じゃない。 変人ではあるけど",
  ["Act_E1_3B_CampusB_CHSamuel_Look02_Max_010"] = "サミュエルがペンキを塗り始める…",
  ["Act_E1_3B_CampusB_CHVictoria_Look01_Max_010"] = "うわ ビクトリアと取り巻きちゃんたちだ",
  ["Act_E1_3B_CampusB_CHVictoria_Look02_Max_010"] = "ひどい言葉… もう二度と聞きたくもない",
  ["Act_E1_3B_CampusB_CHVictoria_Look03_Max_010"] = "ずぶぬれでミジメなのに オシャレに見える",
  ["Act_E1_3B_CampusB_CHVictoria_Look04_Max_010"] = "テコでも動きそうにないや…",
  ["Act_E1_3B_CampusB_CHVictoria_Look05_Max_010"] = "1 人で座ってるとなんだか悲しそうに見える…",
  ["Act_E1_3B_CampusB_CHVictoria_Look06_Max_010"] = "同情すべきなのかもしれないけど 結局 自業自得だよね",
  ["Act_E1_3B_CampusB_CHVictoria_Look07_Max_010"] = "これで少しは ビクトリアに気に入られるかな",
  ["Act_E1_3B_CampusB_CHZachary_Look01_Max_010"] = "ザッカリーってフットボールよりビールが好きそうな顔してる",
  ["Act_E1_3B_CampusB_CHZachary_Look02_Max_010"] = "サイテーな男じゃなかったら 同情したかもしれない |ジュリエット かわいそう",
  ["Act_E1_3B_CampusB_Graffiti01_Look01_Max_010"] = "どうして木に当たるの?",
  ["Act_E1_3B_CampusB_Graffiti02_Look01_Max_010"] = "いい被写体になってくれそう",
  ["Act_E1_3B_CampusB_Graffiti03_Look01_Max_010"] = "ここの落書き ホントにひどいな",
  ["Act_E1_3B_CampusB_Graffiti04_Look01_Max_010"] = "象形文字にしか見えない…",
  ["Act_E1_3B_CampusB_Ladder_Look01_Max_010"] = "ハシゴをいじってサミュエルをケガさせたくない |ビクトリアがどくだけでいい…",
  ["Act_E1_3B_CampusB_MPA01_Look01_Max_010"] = "このポスター もっと見かけるようになればいいのに",
  ["Act_E1_3B_CampusB_Pipe_Look01_Max_010"] = "スプリンクラーのバルブ 私でも使えそう…",
  ["Act_E1_3B_CampusB_Plaque_Look01_Max_010"] = "「プレスコット寮」だって。 この寮までネイサンの家の持ち物ってわけ?",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_010"] = "いいよ どかせてみせるから",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_020"] = "任務開始 「ビクトリアをどかせ」",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_030"] = "むかつく 絶対どかせてやる",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver02_Max_010"] = "よし これでどうだろう",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver03_Max_020"] = "おしい! バケツの下に立っててくれないとダメだな",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver04_Max_020"] = "全然ダメ。 考えて… あとなにが足りない…?",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver05_Max_010"] = "大成功! 私をなめた罰だ",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver06_Max_030"] = "さすがにやりすぎたかな… 部屋に戻って ウォーレンに会いに行かなきゃ",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver07_Max_040"] = "これじゃビクトリアに都合がいいだけ… 仕返しした方がいいかな… |とにかく 部屋に戻って ウォーレンに会おう",
  ["Act_E1_3B_CampusB_RecycleBin_Look01_Max_010"] = "エコな学校でよかった",
  ["Act_E1_3B_CampusB_RewindChoice_KateIntervene_Max_010"] = "ケイトを助けられて日常ヒーロー気分だけど |鬼警備に目をつけられた気がする… |戻って 見て見ぬふりすべき?",
  ["Act_E1_3B_CampusB_RewindChoice_KatePhoto_Max_010"] = "ケイトとデイビッドの間に割って入ればよかった… |なんなの あの人… |戻って別の対応を試してみるべきかも",
  ["Act_E1_3B_CampusB_RewindChoice_VictoriaComfort_Max_010"] = "ビクトリアの「改心」は演技に決まってる… |戻って日ごろのうっぷんを晴らそうかな",
  ["Act_E1_3B_CampusB_RewindChoice_VictoriaPhoto_Max_010"] = "ざまあみろって感じ |でも 彼女と同じような人間にはなりたくない |力を使って 優しい言葉をかけてあげるべきかな…",
  ["Act_E1_3B_CampusB_Sign_Look01_Max_010"] = "ここに自分の部屋があると思うと 変な気持ち",
  ["Act_E1_3B_CampusB_Sprinkler01_Look01_Max_010"] = "オレゴンはしょっちゅう雨が降るんだから スプリンクラーなんていらないでしょ |カタログ写真のためにきれいにしておかなきゃならないのかな",
  ["Act_E1_3B_CampusB_Sprinkler01_Look02_Max_010"] = "最近は水不足なのに こんなに水を無駄遣いしちゃって",
  ["Act_E1_3B_CampusB_Sprinkler01_Look03_Max_010"] = "水をもっと出して ビクトリアと取り巻きを移動させられるかも",
  ["Act_E1_3B_CampusB_Sprinkler01_Look04_Max_010"] = "スプリンクラーのバルブはどこ?",
  ["Act_E1_3B_CampusB_Sprinkler01_Look05_Max_010"] = "今日だけはブラックウェルのスプリンクラーに感謝してる",
  ["Act_E1_3B_CampusB_Sprinkler01_Look06_Max_010"] = "ビクトリアに水をやったら やさしい一面が開花したりしないかな",
  ["Act_E1_3B_CampusB_Squirrel_Look01_Max_010"] = "かわいすぎるでしょ。 猫だったらもっとヤバかった",
  ["Act_E1_3B_CampusB_SupplyOffice_look01_Max_010"] = "忍び込んで校長先生の生活を覗いてみたい…",
  ["Act_E1_3B_CampusB_Totem_look01_Max_010"] = "あのトーテムは「トバンガ」っていうらしい。 前にウォーレンがそう言ってた",
  ["Act_E1_3B_CampusB_Umbrella_Look01_Max_010"] = "よその人ね",
  ["Act_E1_3B_CampusB_VoiceOver01_Max_010"] = "部屋に戻って ウォーレンの USB を取ってこないと",
  ["Act_E1_3B_CampusB_VoiceOver02_Max_020"] = "ウォーレンに今の状況を話したら 笑われるかな",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_010"] = "みんなに 寮生活に向いてそうって言われたけど 大ハズレ",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_020"] = "一見すると 楽しそうな学校だよね",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_030"] = "友だちや家族は「いつか花開く」って言ってくれるけど…",
  ["Act_E1_3B_CampusB_VoiceOver04_Max_010"] = "彼氏との問題を解決しただけで |ジュリエットとデーナがあんなに心を開いてくれるなんて… |すごい力だな",
  ["Act_E1_3B_CampusB_VoiceOver04_Max_020"] = "みんなのゴシップを伝えて回るだけで人気者になれそう |そのための幻覚や力なの?",
  ["Act_E1_3B_CampusB_VoiceOver05_Max_010"] = "やっとちゃんと人助けができた! こういうのがしたかったんだ",
  ["Cue_E1_3B_CampusB_AlyssaHurt_Alyssa_020"] = "痛った! なにすんの!",
  ["Cue_E1_3B_CampusB_AlyssaHurt_Zachary_010"] = "ふざけんなよ!",
  ["Cue_E1_3B_CampusB_AlyssaMoveSit_Alyssa_020"] = "えー 別にいいけど…",
  ["Cue_E1_3B_CampusB_AlyssaMoveSit_Max_010"] = "アリッサ そこどいて!",
  ["Cue_E1_3B_CampusB_BucketFall_Samuel_030"] = "ダメだよ… それはダメだ…",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_010"] = "ちょっとなにこれ! どういうつもり!?",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_020"] = "服が台無しになるところだったじゃない",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_040"] = "うちらの上に落ちてたらどうするのよ! 訴えられたいの?",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax02_Alyssa_001"] = "ホント ありがとね。 じゃ また",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_001"] = "マックス おかげで助かったよ。 ありがとね",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_004"] = "まあね。 子どもの頃から こういうの慣れてるから",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_005"] = "これだから脳筋男は… |ボルテックス・クラブのメンバーにはこんなことしないくせに",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_008"] = "だよね。 今度ゆっくり話そうよ。 今はこの中身空っぽの小説 読まなきゃ",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_002"] = "よかった。 反射神経いいね",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_003"] = "危なかったね…",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_006"] = "相手にしないことだよ",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_007"] = "くだらないクラブだよ",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa02_Alyssa_001"] = "もういいかな。 続きが気になっちゃって",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_001"] = "あれ  マックス",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_005"] = "「愛と永遠の眠りの狭間で」… 分かってる 何も言わないで",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_006"] = "一人で恋愛小説を読んでる私に聞く? |ボルテックス・クラブでビクトリアと遊ぶほうが楽しいかも",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_009"] = "まあね。 じゃ 続きを読むから…",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_003"] = "何 読んでるの?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_004"] = "元気?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_007"] = "でもそれ ベストセラーだよね?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_008"] = "読書のほうがマシだよ",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_001"] = "マックス",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_004"] = "よく覚えてない… 授業なんてどうでもいい気分なのかも",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_005"] = "なんか今日は何もかもどうでもよくて… めんどくさくてごめんね",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_007"] = "今はちょっとひとりになりたいんだ。 ごめん",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_002"] = "授業はどうだった?",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_003"] = "元気ないけど… 大丈夫?",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_006"] = "私でよかったら…",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_008"] = "ケイト",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate02_Kate_001"] = "ごめん マックス。 あとにして",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate02_Kate_002"] = "しつこいよ マックス",
  ["Cue_E1_3B_CampusB_CHLogan_MaxTalkLogan_Logan_001"] = "やめろよ。 写真を撮りたかったら 金曜日の試合中にしてくれ",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_002"] = "今日は忙しそうですね",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_003"] = "レイチェル・アンバーに何があったんですか?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_006"] = "レイチェル・アンバーのビラまで塗りつぶさないでくださいね",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_007"] = "まあ… たしかに。 でも ビラを見ると気がめいっちゃって",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_009"] = "レイチェルと知り合い?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_011"] = "サミュエル",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_012"] = "何があったんですかね…",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_013"] = "どんな子でしたか? 人気者だったと思うけど…",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_014"] = "それじゃ また",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_001"] = "やあ 元気かい?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_004"] = "僕はいつでも忙しいさ。 今日は庭掃除。 それからペンキ塗り",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_005"] = "それは本人にしか分からない",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_008"] = "光を塗りつぶすことはできない",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_010"] = "プリズムを知ることはできない |ただ見つめるのみだ… |では ペンキを塗りにいくよ",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_015"] = "過去に執着すべきではない。 僕は前進しつづける。 時計のように",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_016"] = "太陽の光も影を作る。 彼女は光であり 影だった |乾電池と同じだよ。 プラスとマイナスを持つ",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_017"] = "足元に気をつけるんだよ。 掃除が終わったら… ペンキ塗りだ",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel02_Samuel_001"] = "悪いけど 今忙しいんだ。 掃除を済ませて ペンキを塗らなきゃ…",
  ["Cue_E1_3B_CampusB_CHVictoria_Stained_Max_001"] = "えっと… あの… ビクトリア…",
  ["Cue_E1_3B_CampusB_CHVictoria_Stained_Victoria_002"] = "マックス。 何か用?",
  ["Cue_E1_3B_CampusB_CHZachary_MaxTalkZachary2_Zachary_001"] = "あっち行ってろよ。 インタビューはお断りだ",
  ["Cue_E1_3B_CampusB_CHZachary_MaxTalkZachary_Zachary_001"] = "今 フットボールの練習中だ。 あっち行けよ",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_010"] = "大丈夫…? その服 カシミアだよね",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_030"] = "前から思ってたけど いつもおしゃれだよね",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_050"] = "それに写真の才能も すごいよ。 リチャード・アヴェドンっぽい",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_090"] = "ムカついたけど… ちょっと 笑えたよ",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_110"] = "分かる そういうときってあるよね。 じゃ また",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_020"] = "まあね。 でも他にもあるし",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_040"] = "否定はしないけど。 ジェファソン先生にも言われたし…",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_060"] = "アヴェドンのファンなの… ちょっとうれしい",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_070"] = "…ったく タオルはまだ? いつまで待たせるの…",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_080"] = "さっきの写真 消すね |いじわるして悪かった… あと 「自撮りぼっち」とか言って",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_100"] = "今日はなんかツイてないみたい",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_120"] = "じゃあね",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_020"] = "なんだお前は。 仕事の邪魔をしないでもらいたい",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_040"] = "なんだと? 人聞きの悪いことを言うな… 安全を守るためだ",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_060"] = "お前も要注意だな。 このことはよく覚えておく",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Kate_080"] = "マックス ありがとう! やっと追い払えたよ |もう行かなきゃいけないんだけど 本当に感謝してるから",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_010"] = "ちょっと! もうやめてください",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_030"] = "生徒を怒鳴りつけ いじめることが仕事なんですか?",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_050"] = "ウソばっかり",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_070"] = "「お前」って…",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_090"] = "気にしないで",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_David_010"] = "…いいか よく聞け。 俺の目はごまかせない |隠し事ができるなどと思わないことだ。 わかったな",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_David_020"] = "俺のことは嵐だと思え。 嵐が近づいている。 覚悟しておけ",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_Kate_030"] = "もうやめてください…",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_Kate_040"] = "なんで止めてくれなかったの? 黙って見てるだけなんて",
  ["Cue_E1_3B_CampusB_KateAndDavid_David_010"] = "…いいか 俺は生徒のことは何もかも把握しているんだ |黙っていないで なんとか言え",
  ["Cue_E1_3B_CampusB_KateAndDavid_Kate_020"] = "なんのことか分かりません",
  ["Cue_E1_3B_CampusB_PipeActivated_Taylor_020"] = "大丈夫 ただの水だよ…",
  ["Cue_E1_3B_CampusB_PipeActivated_Taylor_040"] = "そ… そうだよね",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_010"] = "ちょっとなんなの!? 信じられない! ずぶ濡れよ!",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_030"] = "これカシミアなんですけど! この服 いくらしたか分かってるの!?",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_050"] = "もうマジで最悪",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_020"] = "待って。 動かないで",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_030"] = "これは SNS いき決定",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_040"] = "もうどいてくれる? 早く部屋に戻りたいんだけど",
  ["Cue_E1_3B_CampusB_TauntVictoria_Victoria_010"] = "黙って。 嫌みとか聞きたくないから",
  ["Cue_E1_3B_CampusB_TauntVictoria_Victoria_050"] = "生意気に… せいぜい気をつけなさい… ネイサンにもね",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_010"] = "あーら 自撮りクイーンのマックス・コールフィールドさん",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_020"] = "個性派 気取って マーク… じゃなかった ジェファソン先生の気を引くなんて",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_030"] = "「ダゲレオタイプです～!」 ろれつ回ってなかったし |酔っ払ってるのかしら?",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_040"] = "かしこいマックスさんなら これを見て分かるでしょ? 通行止めよ",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_050"] = "待って。 動かないで…",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_060"] = "傑作が撮れた 安心して |SNS にバラまく前に レトロフィルターで加工してあげる",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_070"] = "じゃ さよなら 「自撮りぼっち」さん",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Courtney_020"] = "大丈夫 ビクトリア?",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Courtney_060"] = "今タオルを持ってくるから ちょっと待ってて!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Samuel_040"] = "ああ 申し訳ない。 髪の毛につくと落ちないんだよ… すまない…",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_010"] = "ちょっと! 冗談じゃないわよ!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_030"] = "カシミアの服がペンキまみれになったのに 大丈夫だと思う!?",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_050"] = "近寄らないでよ 気色悪い!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_070"] = "早くしてよ 乾いちゃうでしょ!",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_010"] = "あっち行きなさいよ",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_020"] = "言葉 分からないの? あっち行って",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_030"] = "パパラッチは立ち入り禁止よ",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_040"] = "通行止めよ。 お分かり?",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_020"] = "よーしザック こいつを受けてみろ!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_110"] = "ヒュー!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_120"] = "いいねええええ!",
