  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_150"] = "おいおいおい!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_160"] = "よし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_170"] = "うっし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_180"] = "いいねえ!",
