  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_210"] = "うっしゃー!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_220"] = "おっし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_230"] = "いいねえ!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_240"] = "おし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_250"] = "投げろよ!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_260"] = "ははは!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_010"] = "早く投げろよ ローガン!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_030"] = "うっし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_040"] = "よーし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_050"] = "おし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_060"] = "ナイス!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_070"] = "オッケー!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_080"] = "ナイス スロー!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_090"] = "おっし!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_100"] = "いいね!",
  ["Act_E1_3C_Corridor_BlackwellMap_Look01_Max_010"] = "ブラックウェルは広くないけど まるで迷路",
  ["Act_E1_3C_Corridor_BrookeSlate_Look01_Max_010"] = "ウォーレンはブルックと付き合えばいいのに。 どう見ても相性ばっちりだもん",
  ["Act_E1_3C_Corridor_CHJuliet_Look01_Max_010"] = "ジュリエット 今にも泣き崩れそう",
  ["Act_E1_3C_Corridor_CHJuliet_Look02_Max_010"] = "マックス 人の名前は覚えた方がいい",
  ["Act_E1_3C_Corridor_CHJuliet_Look03_Max_010"] = "くだらないケンカを止める方法を見つけないと",
  ["Act_E1_3C_Corridor_CHJuliet_Look04_Max_010"] = "かわいそうなジュリエットに真実を伝えなきゃ",
  ["Act_E1_3C_Corridor_DanaSlate_Look01_Max_010"] = "デーナは根っからのチアリーダーだな…",
  ["Act_E1_3C_Corridor_DormMap_Look01_Max_010"] = "\"ブラックヘル\"へようこそ…",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_010"] = "ここの人たちは容赦ないな",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_020"] = "楽しそう。 唯一のオタク女子じゃないみたいでよかった",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_030"] = "警告どうも",
  ["Act_E1_3C_Corridor_ExpressionPanel_Look01_Max_010"] = "寮のすべてがここに詰まってる",
  ["Act_E1_3C_Corridor_ExpressionPanel_Look01_Max_020"] = "頑張れグラント先生! 私は無理かもしれないけど…",
  ["Act_E1_3C_Corridor_JulietSlate_Look01_Max_010"] = "\"ジュリエット スーパーレポーター\"",
  ["Act_E1_3C_Corridor_KateSlate_Look01_Max_010"] = "なにこれ ホントにバカみたい",
  ["Act_E1_3C_Corridor_KateSlate_Look02_Max_010"] = "世界共通の「私のことは放っといて」マーク",
  ["Act_E1_3C_Corridor_MPA01_Look01_Max_010"] = "人気者だったんだね。 あちこちに貼ってある",
  ["Act_E1_3C_Corridor_MPA02_Look01_Max_010"] = "いなくなったのはわかったよ。 貼ってる人 大丈夫?",
  ["Act_E1_3C_Corridor_MaxSlate_Look01_Max_010"] = "なにも書いてない。 なにも言いたいことがないの",
  ["Act_E1_3C_Corridor_MaxSlate_Look02_Max_010"] = "まあ こういうこと",
  ["Act_E1_3C_Corridor_ModernAlarm_Look01_Max_010"] = "非常ベルは まだ新しそう",
  ["Act_E1_3C_Corridor_Poster01_Look01_Max_010"] = "雰囲気があるね。 ほこりをかぶってるけど",
  ["Act_E1_3C_Corridor_Poster02_Look01_Max_010"] = "冗談でしょ",
  ["Act_E1_3C_Corridor_Poster03_Look01_Max_010"] = "\"奴らは生きてる!\"",
  ["Act_E1_3C_Corridor_Poster04_Look01_Max_010"] = "このポスター 結局なにが言いたいの?",
  ["Act_E1_3C_Corridor_ScoreBoard_Look01_Max_010"] = "ここに何か貼った人たちのコラージュを作ってみたいな",
  ["Act_E1_3C_Corridor_StellaSlate_Look01_Max_010"] = "217 号室? ここには絶対入らない",
  ["Act_E1_3C_Corridor_TaylorSlate_look01_Max_010"] = "ボルテックス・クラブなのか ビクトリア・クラブなのか はっきりして",
  ["Act_E1_3C_Corridor_ToiletPaper_Look01_Max_010"] = "トイレットペーパー戦争に勝者はいない。 亡霊しか残らない",
  ["Act_E1_3C_Corridor_VictoriaSlate_Look01_Max_010"] = "勘弁してよ ビクトリア…",
  ["Act_E1_3C_Corridor_VoiceOver01_Max_010"] = "部屋に戻って USB を取ってくるんでしょ",
  ["Act_E1_3C_Corridor_VoiceOver01_Max_020"] = "そんな場合じゃないかもしれないけど USB は返さなきゃ",
  ["Act_E1_3C_Corridor_VoiceOver02_Max_010"] = "デーナを助けなきゃ… |ビクトリアの部屋を調べて真実を確かめよう |イヤな役目だけど",
  ["Act_E1_3C_Corridor_VoiceOver02_Max_020"] = "まずはビクトリアの部屋に行かなきゃ",
  ["Act_E1_3C_DanaRoom_AbortionClinicList_Look01_Max_010"] = "デーナ ちゃんと診察に行ったのかな…",
  ["Act_E1_3C_DanaRoom_BigfootBanner_Look01_Max_010"] = "デーナはちゃんと母校愛があるんだね",
  ["Act_E1_3C_DanaRoom_CHDana_Look01_Max_010"] = "デーナ かなり溜めこんでるみたい",
  ["Act_E1_3C_DanaRoom_CHDana_Look02_Max_010"] = "最悪… さらにイヤな思いをさせちゃった",
  ["Act_E1_3C_DanaRoom_CheerleaderOutfit_Look01_Max_010"] = "チアリーダーの生活ってどんなだろう? 色々あるんだろうな",
  ["Act_E1_3C_DanaRoom_ClubSticker01_Look01_Max_010"] = "なにも書いてなかったら かっこいいステッカー",
  ["Act_E1_3C_DanaRoom_DanaLaptop_Interact01_Max_010"] = "デーナみたいな人気者なら 友だちもたくさんいるよね |リア充の SNS を覗けるなんてすごいけど ダメだよね 勝手に見ちゃ…",
  ["Act_E1_3C_DanaRoom_DanaLaptop_Look01_Max_010"] = "デーナの SNS 画面… 見ちゃダメだけど…",
  ["Act_E1_3C_DanaRoom_LoganNote_Look01_Max_010"] = "読んでて悲しくなるよ",
  ["Act_E1_3C_DanaRoom_MaternityBook_Look01_Max_010"] = "デーナ… 本当に本当なんだ…",
  ["Act_E1_3C_DanaRoom_PregnancyTest_Look01_Max_010"] = "あれって 妊娠検査薬…",
  ["Act_E1_3C_DanaRoom_PregnancyTest_Look02_Max_010"] = "妊娠検査薬なんて見えない っと",
  ["Act_E1_3C_DanaRoom_USBKey_Interact01_Max_010"] = "愛しい USB… もう二度と離さないからね",
  ["Act_E1_3C_DanaRoom_USBKey_Look01_Max_010"] = "あった USB メモリ",
  ["Act_E1_3C_DanaRoom_VoiceOver01_Max_010"] = "あとは… USB を持ってウォーレンに会いに行くだけ",
  ["Act_E1_3C_DanaRoom_VoiceOver01_Max_020"] = "また余計なことして彼女を傷つけちゃった。 巻き戻したらフォローできるかな",
  ["Act_E1_3C_MaxRoom_Artbooks_Look01_Max_010"] = "カルティエ＝ブレッソン ドアノー ハミルトン… 最高",
  ["Act_E1_3C_MaxRoom_Binder_Interact01_Max_010"] = "フィリップ＝ロルカ・ディコルシア! |あんな所にカメラを持ちこむなんて… すごい画… |ジュリア・キャメロンのビクトリア朝の画面も素敵。 アナログ中のアナログね |それにダリ… 時間を止めて切り取る天才",
  ["Act_E1_3C_MaxRoom_Binder_Look01_Max_010"] = "インスピレーションが必要な時はこれを見るんだ",
  ["Act_E1_3C_MaxRoom_Book_Look01_Max_010"] = "ケイトに「10 月はたそがれの国」を借りてよかった |ブラッドベリ 集めようかな",
  ["Act_E1_3C_MaxRoom_Cookies_Look01_Max_010"] = "ママは誕生日にチョコクッキーをこんなに大きな箱で送ってくれたし |200 ドルの商品券も忍ばせてくれてた |おかげでさみしい誕生日にはならなかった",
  ["Act_E1_3C_MaxRoom_Cushion_Look01_Max_010"] = "ありがちだけど ママとこれを作った日のことを思い出すとほっこりする",
  ["Act_E1_3C_MaxRoom_DVD_Look01_Max_010"] = "いつか映画のコレクションをきちんと整理する… それとテレビも HD にする",
  ["Act_E1_3C_MaxRoom_DanaNote_Look01_Max_010"] = "デーナがメモを置いて行ったみたい…",
  ["Act_E1_3C_MaxRoom_Guitar_Look01_Max_010"] = "いいギターなんだよね。 もっと弾いてあげないとな",
  ["Act_E1_3C_MaxRoom_Hifi_Look01_Max_010"] = "中古屋でレコード買いたいな… |いかにもな趣味だけど 音楽は私と作品に必要だからいいんだ",
  ["Act_E1_3C_MaxRoom_InstantFilm_Look01_Max_010"] = "インスタントカメラのフィルムってもうほとんど見ないし 高いんだよね |それでも私はアナログ派だけど",
  ["Act_E1_3C_MaxRoom_Laptop_Look01_Max_010"] = "そろそろ買い替え時のパソコン",
  ["Act_E1_3C_MaxRoom_MaxChloePhoto_Look01_Max_010"] = "「マックス＆クロエ: ずっと友だち」… だったはずなのに |いい加減 クロエに連絡しないと… |遅くなるほど 気まずくなるし",
  ["Act_E1_3C_MaxRoom_MaxClothing_Look01_Max_010"] = "映画に出てくるファッションには程遠いけど 私は気に入ってる",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact01_Max_010"] = "惨めな顔",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact02_Max_010"] = "ダニエルはすごいな。 私を描いたからって何か言われないといいけど",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact03_Max_010"] = "このサイト大好き… ビンテージカメラがこんなに…",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact04_Max_010"] = "ウォーレンってばホントおかしい。 ここでちゃんと友だちができてよかった",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Look01_Max_010"] = "ノート PC が構ってほしそうにしてる",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Look02_Max_010"] = "中身が全部あるか見ておかなきゃ |ウォーレンの隠しフォルダは… 見なくていっか |後悔しそうだしね",
  ["Act_E1_3C_MaxRoom_MaxRoomDoor_Interact01_Max_010"] = "ウォーレンに会う前に机から USB を取らなきゃ",
  ["Act_E1_3C_MaxRoom_Mirror_Look01_Max_010"] = "18 歳になったなんて。 大人には見えないな。 顔色悪いだけで",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_010"] = "スペースニードル見物で 唯一私が写っている写真…",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_020"] = "いい試合だったし 最高のホッケーが見れた",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_030"] = "このママの写真はお気に入り",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_040"] = "クリステンとフェルナンドが酔っぱらって フリーモントトロールに登ってたね…",
  ["Act_E1_3C_MaxRoom_PhotoWall_Look01_Max_010"] = "「マックス・メモリアル・フォトウォール」",
  ["Act_E1_3C_MaxRoom_Plant_Interact01_Max_010"] = "カラカラだ。 私ダメなママね。 はい お水",
  ["Act_E1_3C_MaxRoom_Plant_Look01_Max_010"] = "あなたのことは忘れてないよ リサ。 まだね",
  ["Act_E1_3C_MaxRoom_PostCard01_Look01_Max_010"] = "自分が 18 なんて信じられない |この歳まで写真を続けさせてもらえてよかった",
  ["Act_E1_3C_MaxRoom_Poster07_Look01_Max_010"] = "このポスター大好き。 荒々しくて派手で",
  ["Act_E1_3C_MaxRoom_Poster08_Look01_Max_010"] = "マン・レイも「自撮り」なんて言うかな?",
  ["Act_E1_3C_MaxRoom_Scarf_Look01_Max_010"] = "またパパと一緒にホッケーの試合を見に行きたいな",
  ["Act_E1_3C_MaxRoom_TeddyBear_Look01_Max_010"] = "ヨーホー キャプテン |あなたがいてくれると頼もしいよ |片目を飲みこんじゃって病院に運ばれた日からの親友だもんね",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_010"] = "ただいま 私の小さなお城",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_020"] = "一人の生活もいいけど シアトルの友だちと家族にも会いたい…",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_030"] = "部屋に引きこもりたいけど ウォーレンに USB を返さなきゃ |ここでの唯一の友だちだし大事にしないと…",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_040"] = "もうっ デーナの部屋に USB を取りに行かなきゃ",
  ["Act_E1_3C_MaxRoom_WarrenNote_Look01_Max_010"] = "USB にメッセージまで仕込んでた。 ウォーレンはお茶目だなあ",
  ["Act_E1_3C_MaxRoom_Window_Look01_Max_010"] = "私 いつもファインダー越しか窓越しに何かを見てる。 見てるだけ",
  ["Act_E1_3C_VicRoom_ClubSticker02_Look01_Max_010"] = "要はボルテックス・クラブに入れってことね。 絶対やだ",
  ["Act_E1_3C_VicRoom_GalleryLetter_Look01_Max_010"] = "厳しいね。 私と違って作品をアピールしてるだけマシか",
  ["Act_E1_3C_VicRoom_Gazette_Look01_Max_010"] = "この記事見て ビクトリアはジュリエットにキレたんじゃないかな…",
  ["Act_E1_3C_VicRoom_JeffersonBook_Look01_Max_010"] = "ビクトリアってジェファソン先生を崇拝してる",
  ["Act_E1_3C_VicRoom_Jewelry_Look01_Max_010"] = "高いアクセを着けられるなら 絶対にこれを着ける",
  ["Act_E1_3C_VicRoom_MPAVictoria_Look01_Max_010"] = "ビクトリアってこんなにレイチェルが嫌いなの?",
  ["Act_E1_3C_VicRoom_Mail_Look01_Max_010"] = "再生紙じゃないじゃん。 地球を大事にしてないな |今回はいい事のためだからチャラね",
  ["Act_E1_3C_VicRoom_Mail_Take_Max_010"] = "これでデーナが無実って信じてくれるかな…",
  ["Act_E1_3C_VicRoom_Photos_Interact01_Max_010"] = "写真でちょっとしたメッセージを送ろうかな |これを動かして… こっちに… |うん だんだん見えてきた",
  ["Act_E1_3C_VicRoom_Photos_Look01_Max_010"] = "自撮りしてるじゃん…",
  ["Act_E1_3C_VicRoom_Photos_Look02_Max_010"] = "意地悪だけど 自業自得",
  ["Act_E1_3C_VicRoom_Pictures_Look01_Max_010"] = "この写真 なんだかビクトリアみたい。 冷たくて魂がない感じ",
  ["Act_E1_3C_VicRoom_PlasmaTV_Look01_Max_010"] = "いいプラズマテレビ。 また忍び込んで「ファイナルファンタジー」でも観ようかな |誰が何と言おうとすばらしい SF 映画なんだから",
  ["Act_E1_3C_VicRoom_Poster06_Look01_Max_010"] = "ビクトリアの親がチェイス・スペースのオーナー? 素直に感心した",
  ["Act_E1_3C_VicRoom_Tablet_Interact01_Max_010"] = "寮に 3D プリンターを置く気? 取り巻きに入れてもらおっかな…",
  ["Act_E1_3C_VicRoom_Tablet_Look01_Max_010"] = "「違います 怪しい者じゃありません… 見てるだけです…」",
  ["Act_E1_3C_VicRoom_VicPhotoStuff_Look01_Max_010"] = "ビンテージの中判カメラに いいプライムレンズ… 許すまじ ビクトリア",
  ["Act_E1_3C_VicRoom_VictoriaClothing_Look01_Max_010"] = "ディオールにジバンシー… 私の学費分は入ってそう",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact01_Max_010"] = "いや サムい… 次 次",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact02_Max_010"] = "やってくれるね。 誰も私をヒップスターだなんて思ってないよ",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact03_Max_010"] = "さっきの写真じゃなく 素敵な写真を撮って上げたのは評価できるね",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact04_Max_010"] = "これだ ジュリエットに見せるべきメール |さっさとプリントしてここから出よう",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look01_Max_010"] = "もちろん ビクトリアだから高いノートを使ってるよね |私の写真をアップしたかだけ見せて…",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look02_Max_010"] = "メールの印刷さえ終われば…",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look03_Max_010"] = "やることはやった。 もうここに用はない",
  ["Act_E1_3C_VicRoom_VictoriaShoes_Look01_Max_010"] = "こんな靴じゃランウェイしか歩けないよ…",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_010"] = "まずすぎるよ… 早く証拠を探さなきゃ",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_020"] = "私は犯罪者じゃなくて ニンジャ… 早くしなきゃ",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_030"] = "イヤな気分だけど… 必要なら巻き戻せるし…",
  ["Act_E1_3C_VicRoom_VoiceOver02_Max_010"] = "証拠を印刷しないと…",
  ["Act_E1_3C_VicRoom_VoiceOver03_Max_010"] = "早くプリンターから紙を取って この部屋を出なきゃ",
  ["Act_E1_3C_VicRoom_VoiceOver04_Max_005"] = "ぼーっとしてる場合じゃない。 もう行こう!",
  ["Act_E1_3C_VicRoom_VoiceOver04_Max_010"] = "やるべきことはやった。 もうこんなマネはゴメン",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_001"] = "どうもしなかったら デーナを部屋に閉じ込めたりしないし",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_003"] = "あの女 ひとの彼氏とエロチャットしたのよ",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_010"] = "そっか。 デーナが私の彼氏のザックとエロチャットしてたの。 信じられる?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_013"] = "ビクトリアが教えてくれたの",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_015"] = "ひとの男とエロチャットするような人が?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_016"] = "あなたに関係ないでしょ? いちいち詮索しないでくれる? |これまで話しかけたことないくせに",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_020"] = "私の名字は?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_024"] = "ビクトリアによれば デーナは男のためなら何でもするって",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_027"] = "チャットのログ見たって。 ザックはさっきから電話出ないし |デーナが認めたら ここを開けてあげる。 絶交だけど",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_030"] = "意外。 私の名字 知らないと思った",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_033"] = "ほら やっぱりね。 心配してる振りしてくれてどうもありがとう |ちなみに ジュリエット・ワトソンだから",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_037"] = "意外。 私の名字 知らないと思った",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_002"] = "何があったの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_004"] = "友だちでしょ?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_011"] = "なんで分かったの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_014"] = "ジュリエット どうかしたの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_017"] = "ひどいね。 なんで分かったの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_018"] = "そんなことがあったんだ… でも なんで分かったの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_019"] = "だから今話してるの",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_022"] = "あ… 当たり前だよ",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_023"] = "間違いないの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_025"] = "ビクトリアが…? デーナがホントにそんなことするかな?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_028"] = "ジュリエット・パ… ジュリエット・パトソン",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_029"] = "ジュリエット・ワトソンでしょ",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_031"] = "知ってるよ。 人と話すのは得意じゃないけど 困ってるならほっとけない |で どうして分かったの?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_034"] = "ジュリエット… ジュリエット… オルソン",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_035"] = "えっと… ジュリエット… メイソン",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_036"] = "ビクトリアに聞いたの? そっか…",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_038"] = "ジュリエット・ワトソン 頭冷やして",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase02_Juliet_002"] = "あっち行ってよ。 関係ないでしょ",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase02_Juliet_004"] = "認めるまで絶対に開けないから",
  ["Cue_E1_3C_Corridor_CourtneyAndTaylorTowel_Courtney_020"] = "急がないとビクトリアに超怒られる…",
  ["Cue_E1_3C_Corridor_CourtneyAndTaylorTowel_Taylor_010"] = "コートニー 早く!",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_010"] = "マックス! 本当に誤解なの! きっとビクトリアの仕業だよ! |彼女の部屋に証拠があるはず!",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_020"] = "ジュリエット! お願いだから ドアを開けて!",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_030"] = "いい加減にしてよ!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Dana_020"] = "ジュリエット! お願いだから ドアを開けて! いい加減にしてよ!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Juliet_010"] = "本当のこと言いなよ デーナ。 言うまで絶対 開けないから!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Max_030"] = "まったく リアリティショーじゃあるまいし…",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_020"] = "開けてくれないと 大声出すから",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_060"] = "ホントだよ。 信じられない… 私がザックに手を出すと思う?",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_090"] = "洗濯もやってよね",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_120"] = "マックス ありがとう。 助かった。 USB は机の上だよ",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_010"] = "出なさいよ!",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_040"] = "そういうこと…!",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_050"] = "デーナ ごめん。 私がバカだった",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_070"] = "分かってる。 頭に血が上っちゃって…",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_080"] = "おわびにおごるから… 友だちでいて",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_100"] = "ありがと。 マックスはニンジャみたいだね",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_110"] = "ザックに ビクトリアのこと問い詰めてくる",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Max_030"] = "ジュリエット これ…",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_014"] = "さっきはホントにありがとうね |まったく ジュリエットも子どもみたいなことするんだから |あきれちゃう",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_016"] = "ボルテックス・クラブが全員仲よしと思ったら大間違い |特にビクトリアは敵が多いの",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_018"] = "殺されるならザックでしょ |正直 私はあんな男にはまったく興味ないけど |ま いかにもビクトリアが好きそうなタイプじゃない? |お似合いだよ",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_020"] = "え? まさか妊娠のこと?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_021"] = "首を突っ込まないのが一番だよ… ウォーレンはあなたに首ったけだけど",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_024"] = "USB メモリのファイル 見たでしょ? 「マックス」っていうフォルダーの中に |マニアックな映画がこれでもかってぐらい入ってたよ?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_025"] = "別に… |USB の中に 「マックス」っていうフォルダーがあるの 気づかなかった?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_027"] = "あれ? 赤くなってる…USB は机の上だよ",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_029"] = "ほんっとにみんな耳ざといんだから…! ねえ 誰にも言わない?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_032"] = "うん。 いいよ… だって 本当のことだし",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_033"] = "私ね… 妊娠してたの。 過去形",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_035"] = "\"無責任な父親\"なら 金曜の試合に向けて練習中。 でもザックじゃない",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_045"] = "マックスはいい人だね。 USB は机の上にあるよ。 ウォーレンによろしくね",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_015"] = "ビクトリアはひどいよ。 あんなに恵まれてるのにどうして… 友だち同士なのに",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_017"] = "だまされたジュリエットがかわいそう。 ビクトリアを殺さないといいけど",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_019"] = "デーナ… 余計なお世話かもしれないけど ちょっとウワサを聞いたの",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_022"] = "いい人だよ。 趣味も合うし",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_023"] = "どういうこと?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_026"] = "ああ なるほど。 あれのことね",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_028"] = "誰も信じてないと思うし 気にすることないよ。 耳に入れときたかっただけ",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_030"] = "もちろん",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_031"] = "本当に妊娠して…? ごめん 余計なこと…",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_034"] = "そうなんだ… えっと それじゃあ…",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_043"] = "ごめんね もうこれ以上は聞かないよ |それに フットボールの試合も見にいかない |あんまり興味ないし",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_044"] = "じゃあ誰… あ ごめん 言わなくていいよ。 ヘンなこと聞いちゃったね",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_046"] = "デーナ",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase02_Dana_001"] = "なんか どっと疲れちゃった",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase02_Dana_006"] = "これ以上何が欲しいのよ。 帰って",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_010"] = "早く出ていってよ",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_020"] = "マックス。 帰って",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_030"] = "聞こえないの? 帰って",
  ["Cue_E1_3C_DanaRoom_PregnancyTest_Dana_010"] = "ちょっと! 人の物 勝手に見ないで",
  ["Cue_E1_3C_DanaRoom_PregnancyTest_Dana_020"] = "親切なフリして 結局詮索? もう帰って",
  ["Cue_E1_3C_MaxRoom_BedLie_Max_010"] = "なんだか疲れちゃったよ… |ヘンなことばっかり起きるし… いつまで続くの これ…? |目が覚めたら 全部夢でした ってことにならないかな… |ポーの詩みたいに 「夢のまた夢」だったりして",
  ["Act_E1_3D_CampusPark_Bike_Interact01_Max_010"] = "いい構図じゃない",
  ["Act_E1_3D_CampusPark_Bike_Look01_Max_010"] = "自転車にトイレットペーパーって…",
  ["Act_E1_3D_CampusPark_CHJuliet_Look01_Max_010"] = "ジュリエットはまだザックとビクトリアのことで動揺してる",
  ["Act_E1_3D_CampusPark_CHWarren_Look01_Max_010"] = "ウォーレン いたいた… ホントに中古車買ったの?",
  ["Act_E1_3D_CampusPark_ChloeCar_Look01_Max_010"] = "えらそうでイライラする |「障害のある人には悪いけど |うちのトラックはあんたらよりも広いスペースが必要なんだ」ってことでしょ?",
  ["Act_E1_3D_CampusPark_DinerSign_Look01_Max_010"] = "ジョイスおばさんがまだ働いてるか見に行かなきゃ。 ついでにバーガーも食べよ",
  ["Act_E1_3D_CampusPark_DirtyWindow_Interact01_Max_010"] = "「拭いて」って書けなきゃ汚れてるとは言わない",
  ["Act_E1_3D_CampusPark_DirtyWindow_Look01_Max_010"] = "指でなにか書きたくなるくらいの埃",
  ["Act_E1_3D_CampusPark_DirtyWindow_Look02_Max_010"] = "よし これで正式に汚れた窓となりました",
  ["Act_E1_3D_CampusPark_DirtyWindow_Photo01_Max_010"] = "アルカディア・ベイの駐車場を撮って連作にできるかも",
  ["Act_E1_3D_CampusPark_Dog_Look01_Max_010"] = "あの犬 大人しく寝てるけど 近づきすぎたらダメ",
  ["Act_E1_3D_CampusPark_GoingCampus_Interact01_Max_010"] = "駐車場についたことだし ウォーレンと話そう",
  ["Act_E1_3D_CampusPark_GoingTown_Interact01_Max_010"] = "ここから歩いて町に戻れないよ。 ウォーレンに会わないとだし",
  ["Act_E1_3D_CampusPark_Graffiti01_Look01_Max_010"] = "まだ車を持ってなくてよかった",
  ["Act_E1_3D_CampusPark_Graffiti02_Look01_Max_010"] = "誰がこういうこと書くわけ?",
  ["Act_E1_3D_CampusPark_JeffersonCar_Look01_Max_010"] = "先生 車を大事にしてるんだな。 アートは儲かるのね",
  ["Act_E1_3D_CampusPark_MPA01_Look01_Max_010"] = "町全体が行方不明者のポスターになりそう",
  ["Act_E1_3D_CampusPark_MPA01_Look02_Max_010"] = "ほとんどのポスターが捨てられるの 残念ね",
  ["Act_E1_3D_CampusPark_MPA01_Look03_Max_010"] = "レイチェルは 探してもらえる人がいるだけ幸せなのかも",
  ["Act_E1_3D_CampusPark_MPAPile_Look01_Max_010"] = "ポスターを貼って回ってる人 本気だな",
  ["Act_E1_3D_CampusPark_OldVan_Look01_Max_010"] = "これだけ外が汚かったら 中も汚いよ",
  ["Act_E1_3D_CampusPark_Poster01_Look01_Max_010"] = "新しい監視システム? イヤな予感…",
  ["Act_E1_3D_CampusPark_RetardedSign_Look01_Max_010"] = "サミュエルが塗り直すんだろうな あれ",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_010"] = "割って入ってよかった。 ああいうのは許せない",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_030"] = "何かしてあげるべきだった。 あの人おかしいよ!",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_050"] = "ウォーレンを探そう。 USB を返してあげないとね",
  ["Act_E1_3D_CampusPark_WarrenCar_Look01_Max_010"] = "ウォーレンと時代錯誤の車… よく買うよ",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_001"] = "ああ… マックス。 ごめん まだちょっと動揺してて",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_005"] = "気づけただけよかったよ。 これでビクトリアも陰で笑ってられないでしょ",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_007"] = "あのバカ 救いようがないぐらい完全に腐ってる |エロチャットはジョークだって言い張って |バカじゃないの? なんかウォーレンが呼んでるけど?",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_009"] = "早くまた ザックとビクトリアと一緒に パーティで遊ぶのが待ち遠しいよ",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_011"] = "それじゃ またね",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_003"] = "ザックのこと あんなふうに知ったらショックだよね。 ホントにひどいよ",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_004"] = "じゃあそっとしとくね |ウォーレンが待ちくたびれてるから もう行くよ |それじゃ",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_006"] = "ザックとは話せた?",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_008"] = "あー… うん。 あまり気を落とさないようにね",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_010"] = "あー うん… そうだね",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_012"] = "ジュリエット… 大丈夫?",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase02_Juliet_001"] = "今は一人にして",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_003"] = "チョウチョなら見たけど",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_004"] = "何の話?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_005"] = "銃を持ってる生徒がいるってだけ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_009"] = "お説教されたのがそんなに不満?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_010"] = "もともとこの町出身だよ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_011"] = "あんたなんか怖くない",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_015"] = "ネイサン あなた 普通じゃないよ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_016"] = "じゃあ 私になんか構ってるヒマないね",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_017"] = "知ってるよ。 お金持ちのバカ息子でしょ?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_019"] = "下がりなさいよ ネイサン",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_020"] = "警察呼ぶよ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_001"] = "てめえ 校長に何を吹き込んだ? 言え!",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_002"] = "何を見たんだ。 吐け!",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_006"] = "\"俺\" が持ってたの間違いだろ! おかげで呼び出し食らった",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_007"] = "よそ者だからって 知らねえ振りしてんじゃねえぞ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_008"] = "ウソつくな。 白状すれば 大目に見てやったのに",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_012"] = "俺は誰の説教も聞かない… 誰の指図も… 受けない…",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_013"] = "なら 知ってるだろ。 この町はプレスコット家のもんだ",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_014"] = "てめえ 俺がどこの誰か まったく分かってねえらしいな",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_018"] = "生意気な口を利くな! 余裕かましやがって… 人の心配してる場合か?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_030"] = "さっさと答えろ!",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_031"] = "なんか言うことあるか?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_002"] = "大丈夫。 私もビクトリアの特ダネ写真をアップするつもりだから",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_004"] = "ビクトリアがしてきたことを思ったら いい薬だよね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_005"] = "その話はしたくない…",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_007"] = "茶化さないで。 そういう気分じゃないの",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_009"] = "言ってくれれば 撮ったのに",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_011"] = "そうかもね。 でも ビクトリアも私の写真削除してくれたから よかったよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_014"] = "絵 描けるの? 科学専門で 芸術は興味ないのかと",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_016"] = "へえ! 絵を描くときは パソコン使うの?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_018"] = "おもしろそう。 お願いしようかな",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_019"] = "ダニエル もうアップしてくれたんだ。 うれしい",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_021"] = "そのうちウォーレンにも声がかかるって",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_023"] = "だから やきもち焼かないで",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_025"] = "ごめん 勉強とかいろいろ忙しくて… 時間なくて",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_026"] = "1 週間でしょ。 タイトルだけは全部チェックしたよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_027"] = "うん 観たよ |「AKIRA」とか「トワイライト・ゾーン」とか |いま改めて見るとすごく深くておもしろかった",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_028"] = "物は言いようだね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_032"] = "観るわけないでしょ。 これ以上 人格ゆがんだら困るよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_033"] = "どうなのそれ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_034"] = "観たよ。 それより チープなバンパイア映画のほうがげんなりした",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_038"] = "「ファスター・プシィキャット・ダイ! ダイ!!」 まで持ってるなんて",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_039"] = "そういうつもりじゃないよ。 大丈夫 |ウォーレンの頭とセンスのよさはわかってるから",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_040"] = "きっと他の子も…",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_041"] = "普通 女子相手にそういうこと言う?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_045"] = "できれば話したくない |今日は信じられないことばっかで… |私 本気でヘンになったんじゃないかって思うぐらい…",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_046"] = "ねえ 聞いてくれる? 聞いてくれるだけでいいから",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_049"] = "なんで?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_051"] = "なにそれ! どんな思考回路してるのよ!",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_001"] = "ビクトリアのやつ SNS にアップしたマックスの写真 まだ削除してないよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_003"] = "マジかよ! あいつのマヌケ面がネットに出回るとは まさに因果応報だな",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_006"] = "なんだよ… やけにピリピリしてんだな",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_008"] = "ビクトリアが顔にペンキ浴びたんだって? |写真があったら 金払ってでも見るのに",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_010"] = "ネットで資金を募ってみたら? みんな喜んで出資する",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_012"] = "そういや ダニエルが君を描いたスケッチを見たよ |悪くないけど 俺ならもっとうまく描けたね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_015"] = "芸術は科学なり。 音楽も数学さ。 ホーキング博士はピカソに匹敵する芸術家だ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_017"] = "もちろん。 マックスの自撮り写真も 加工してかっこよくできるよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_020"] = "よかったじゃん。 これでダニエルのモデル・クラブの一員だな",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_022"] = "そりゃ楽しみだね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_024"] = "USB に入れてあった映画 観てくれた?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_029"] = "1 年ぐらい貸してたのに!",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_030"] = "俺は 既成概念にとらわれないポップカルチャー通だからね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_031"] = "ちょっと待って。 「食人族」 観てないの?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_035"] = "そんな言い方されると傷つくじゃん",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_036"] = "俺は大笑いだったよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_037"] = "エモいバンパイアのよさがわからないとはね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_042"] = "あの監督はモノクロ映画の天才だよ。 巨乳もヤバいしね",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_043"] = "ごめんごめん |そうそう 今週末さ 俺の車で 一緒に映画でも観に行かない? |…それどころじゃないかな",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_044"] = "そいつはどうも",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_047"] = "ウォーレン・グラハム先生に話してみな |悩みがあるなら何でも相談乗るよ。 遠慮しないで",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_048"] = "俺 ひとの話 聞くのは 結構得意だよ",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_050"] = "なんとなく 「タイプじゃない」って言われてる気がして",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_020"] = "はい これ。 ありがと",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_050"] = "いいね。 レトロな感じで",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_070"] = "ホント 古いもの好きだね",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_080"] = "まあ… 私もだけど",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_100"] = "今日はなんか すごくいろいろあって…",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_010"] = "マックス! 待ってたよ",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_030"] = "ああ うん",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_040"] = "車 買ったんだ",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_060"] = "78 年製だよ。 これでどっか行こうよ |ニューバーグのドライブイン・シアターとか",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_090"] = "どしたの?",
  ["Cue_E1_3D_CampusPark_JulietLoop_Juliet_010"] = "どうしてよ… ザックもビクトリアも なんでこんなことするの…?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_010"] = "その前にお願い。 誰にも言わないでね。 ネットに書くのもナシ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_030"] = "今日ね ジェファソン先生の授業中に ホントありえない体験をしたの |いまだに… 信じられない",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_040"] = "ウォーレンは 映画みたいにリアルな夢って見たことある?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_070"] = "授業なら受けてるけど?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_060"] = "マックス・コールフィールドだな",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_065"] = "お前 ジェファソンの取り巻きだろ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_080"] = "同じことだ! 写真を撮ったな? お前 女子トイレに隠れてただろ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_090"] = "何を見たんだ。 吐け!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_100"] = "てめえ なめた態度とってるとタダじゃおかねえぞ! |校長にデタラメのチクリをしやがって",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_110"] = "てめえ 校長に何を吹き込んだ? 言え!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Warren_020"] = "当たり前だろ。 大丈夫。 話してよ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Warren_050"] = "えー… っと…",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_070"] = "マックス?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_120"] = "早く乗って!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_140"] = "ハハハ! ざまみろ! じゃあな!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_040"] = "ちょっと! やめてよ!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_050"] = "痛い! 放して!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_080"] = "クロエ?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_100"] = "ウォーレン!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_010"] = "てめえ… 俺に指図する気か?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_020"] = "やってみろ。 警察は俺の味方だ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_060"] = "俺に指図するんじゃねえ! 親も 校長も お前も全員黙れ!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_090"] = "ふざけるな… またお前か…!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_130"] = "おい てめえら どこ行くつもりだ! 逃げられると思うなよ! |2 人ともタダじゃおかねえからな!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Warren_030"] = "いい加減にしろよ",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Warren_110"] = "逃げろ! 早く行け!",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_010"] = "マックス! 見てよ これ!",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_020"] = "マックス! こっちこっち!",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_030"] = "こっちだよ! おーい!",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Chloe_010"] = "どうぞ。 上がって",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Chloe_030"] = "ボロ家へようこそ",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Max_020"] = "全然… 変わってないね…",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_020"] = "子どもみたいに泣くなよ",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_040"] = "うちのクソオヤジの工具使えば 修理できんじゃない?",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_060"] = "そりゃ失礼。 でも ガレージの中には色々あるから とりあえず見てみな",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_070"] = "決まりだな",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_080"] = "じゃ 飛ばすよ",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_010"] = "うっそ… 壊れちゃってるよ…",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_030"] = "泣いてなんかない… でも このカメラどうしよう 困ったな…",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_050"] = "専用の工具がいるんだけど",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_001"] = "で さっきのは何?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_004"] = "バカ息子な。 …あの男子やるじゃん",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_005"] = "ここらじゃ有名なクズだよ… もう一人の子は知り合い?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_007"] = "「借り」は面倒だぞ… トラブルまで起こして…",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_009"] = "シアトルは肌に合わなかったんだ?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_012"] = "残念だったな ど田舎のアルカディアに戻るなんて",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_013"] = "都会のほうが好きそうだけど",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_016"] = "減らず口は変わらずか",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_018"] = "帰ってきたのは ブラックウェルに通うためだろ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_021"] = "つまり あたしのために戻ってきたわけじゃないと",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_022"] = "要は落ちぶれたんだろ。 ま なんでもいい",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_024"] = "どうかな。 5 年間 音沙汰もなかったんだ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_028"] = "そんな理由で あたしと縁切ったわけ?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_029"] = "よく言うよ。 電話くらいできただろ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_030"] = "いなかったクセに 何が分かんの?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_032"] = "ウソだね。 シアトルで新しい友だち作る気だったんだろ?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_035"] = "戻ってきて 1 か月も連絡よこさなかった言い訳は?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_037"] = "ジェファソンにはそんな見え透いたウソつかないだろ。 もういいよ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_002"] = "さあ。でも あれ プレスコット家の子だよね",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_003"] = "何でもないよ。 ねえ ネイサンとは知り合いなの?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_006"] = "ウォーレンね。 借りを作っちゃったな",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_008"] = "静かな町だから帰ってきたのに 全然落ち着かない…",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_010"] = "ううん アーティストが集まる明るい大都市って感じで |いい写真がいっぱい撮れたよ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_011"] = "そうなのかも。 楽しかったけど… 地元から離れて ちょっとさみしかった",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_014"] = "でも クロエに会えた",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_015"] = "そっちこそ。 どこの不良パンク少女かと思った",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_017"] = "そうでしょ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_019"] = "写真の授業で有名な学校だし |マーク・ジェファソン先生に教えてもらえるんだよ?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_020"] = "ジェファソン先生の授業を受けたかっただけ |90 年代に活躍した有名な写真家なんだ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_023"] = "クロエとも会いたかったんだよ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_025"] = "仕方ないでしょ。 私だっていろいろあったんだよ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_026"] = "連絡したかったよ… でも 急な引っ越しでバタバタして…",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_027"] = "ごめん… クロエも大変だったんだよね",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_031"] = "そんなんじゃないってば",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_033"] = "私だって 好きで引っ越したわけじゃないんだよ",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_034"] = "厳しいな…",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_036"] = "学校に慣れようと必死だったの 内気な自分はもうイヤで… |連絡したいと思ってたよ",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_020"] = "こら \"ありがとう\"は?",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_030"] = "5 年たっても相変わらずだな",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_040"] = "そんな顔すんな 久々に会えたんだし",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_070"] = "あたしも同じだよ",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_010"] = "なんなの あのネイサン・プレスコットってやつ… |シャレになんない… もうかんべんしてほしい…",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_050"] = "ホント 会えてうれしいよ",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_060"] = "それから ありがとね。 今日はいろんなことがありすぎて…",
  ["Act_E1_5A_BathRoom_Pills_Look01_Max_010"] = "これ クロエの? 大丈夫かな…",
  ["Act_E1_5A_Bathroom_Cabinet_Interact01_Max_010"] = "クロエの髪の色 好きだな。 内気さがミジンもない… 私とは正反対",
  ["Act_E1_5A_Bathroom_Dark_Look01_Max_010"] = "暗っ! これじゃ何も見えない",
  ["Act_E1_5A_Bathroom_Drawer01_Interact01_Max_010"] = "クロエの薬じゃないといいけど…",
  ["Act_E1_5A_Bathroom_MakeUpStuff_Look01_Max_010"] = "ジョイスおばさんの化粧品ね。 クロエは動物実験をするメーカーのは使わない",
  ["Act_E1_5A_Bathroom_Scale_Interact01_Max_010"] = "ノーコメント",
  ["Act_E1_5A_Bathroom_Scale_Look01_Max_010"] = "先週測ったばっかりだもん",
  ["Act_E1_5A_Bathroom_Shower_Interact01_Max_010"] = "シャワーを浴びたいけど ガレージで道具を探さないと",
  ["Act_E1_5A_Bathroom_Shower_Look01_Max_010"] = "綺麗なシャワー",
  ["Act_E1_5A_ChloeRoom_Bed_Interact01_Max_010"] = "もう子どもじゃないよ! ベッドの下には入れない!",
  ["Act_E1_5A_ChloeRoom_BlueDrawer01_Interact01_Max_010"] = "一緒に描いたの 楽しかったな…",
  ["Act_E1_5A_ChloeRoom_BlueDrawer01_Look01_Max_010"] = "これ覚えてる。 1 日かけて青く塗った。 クロエのお気に入りの青",
  ["Act_E1_5A_ChloeRoom_Box_Interact01_Max_010"] = "クロエの言う通り しまうべきだ…",
  ["Act_E1_5A_ChloeRoom_Box_Look01_Max_010"] = "古い段ボール…",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look01_Max_010"] = "やっちゃったな。 少し巻き戻したら直せるかも…",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look02_Max_010"] = "もう巻き戻して直せないじゃない",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look03_Max_010"] = "もう巻き戻して直せないじゃない |この力で できることと できないこと… ちゃんと覚えないと",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look01_Max_010"] = "つい 5 年前までは親友だったのに…",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look02_Max_010"] = "クロエはそんなに変わってない。 また親友になれるかな…",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look03_Max_010"] = "クロエがうれしそう。 身代りになってよかった",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look04_Max_010"] = "身代りにならなかったから 怒ってるみたい…",
  ["Act_E1_5A_ChloeRoom_Closet_Interact01_Max_010"] = "開かない",
  ["Act_E1_5A_ChloeRoom_Closet_Interact02_Max_010"] = "動かない。 でも ここに CD は入れないな",
  ["Act_E1_5A_ChloeRoom_Closet_Look01_Max_010"] = "子どもの頃に隠れた クローゼットの秘密基地!",
  ["Act_E1_5A_ChloeRoom_ClothDrawer01_Interact01_Max_010"] = "クロエ 雰囲気変わったな。 一瞬分からなかった",
  ["Act_E1_5A_ChloeRoom_ClothDrawer01_Look01_Max_010"] = "クロエのパパが作ったドレッサー",
  ["Act_E1_5A_ChloeRoom_Desk_Interact01_Max_010"] = "ゴチャゴチャだ… 中に CD 埋もれてないかな",
  ["Act_E1_5A_ChloeRoom_Desk_Look01_Max_010"] = "机なの? 収納スペースなの?",
  ["Act_E1_5A_ChloeRoom_Door_Interact01_Max_010"] = "もうデイビッドには会いたくないな",
  ["Act_E1_5A_ChloeRoom_DuffleBag_Interact01_Max_010"] = "うわっ 汚れた服のニオイ!",
  ["Act_E1_5A_ChloeRoom_DuffleBag_Look01_Max_010"] = "洗濯物袋みたい",
  ["Act_E1_5A_ChloeRoom_EmptyHiFi_Look01_Max_010"] = "電源が入っても ディスクがないとひらけないよ…",
  ["Act_E1_5A_ChloeRoom_FloorLamp_Look01_Max_010"] = "このランプぐらついてる。 触ったら倒れるかも",
  ["Act_E1_5A_ChloeRoom_HeightGauge_Look01_Max_010"] = "クロエはいつも私より背が高くて おじさんに測ってもらってた",
  ["Act_E1_5A_ChloeRoom_Hifi_Look01_Max_010"] = "電源がないと動かない",
  ["Act_E1_5A_ChloeRoom_Hifi_Look02_Max_010"] = "最近のクロエはどんな音楽聴いてるのかな…",
  ["Act_E1_5A_ChloeRoom_Hifi_Look03_Max_010"] = "こんなに切ない曲を聴いてるなんて… レイチェルのことを思い出すのかな",
  ["Act_E1_5A_ChloeRoom_Joint_Interact01_Max_010"] = "モノは隠せても臭いは隠せないよ…",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact01_Max_010"] = "超楽しそう",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact02_Max_010"] = "超悲しそう",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact03_Max_010"] = "超トんでそう",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact04_Max_010"] = "クロエらしさが出てる写真。 誰が撮ったんだろ?",
  ["Act_E1_5A_ChloeRoom_Laptop_Look01_Max_010"] = "クロエのパソコンから音楽を流せないのは残念… |でもこの古臭さが最高 |ステッカーまみれで まさにやりたい放題",
  ["Act_E1_5A_ChloeRoom_Letter01_Look01_Max_010"] = "レイチェルと 仲良かったんだ。 さみしいだろうな",
  ["Act_E1_5A_ChloeRoom_MPA_Look01_Max_010"] = "クロエがあのポスターを作ってたんだ",
  ["Act_E1_5A_ChloeRoom_MetalBox_Look01_Max_010"] = "ベッドの下に箱なんていかにも怪しい",
  ["Act_E1_5A_ChloeRoom_MetalBox_Look02_Max_010"] = "ここにもう秘密はない",
  ["Act_E1_5A_ChloeRoom_Multisocket_Look01_Max_010"] = "電源ケーブルね",
  ["Act_E1_5A_ChloeRoom_Multisocket_Look02_Max_010"] = "電源入るかな",
  ["Act_E1_5A_ChloeRoom_Paper01_Look01_Max_010"] = "アルカディア・ベイから出るには お金が必要だ",
  ["Act_E1_5A_ChloeRoom_Picture01_Look01_Max_010"] = "あのポンコツに 3000 ドル? クロエ 貯金をはたいたんじゃない…",
  ["Act_E1_5A_ChloeRoom_PostCard01_Look01_Max_010"] = "レイチェルからのポストカード…",
  ["Act_E1_5A_ChloeRoom_Poster_Look01_Max_010"] = "私は好きじゃない。 狙いすぎ",
  ["Act_E1_5A_ChloeRoom_ReportCard_Look01_Max_010"] = "クロエは 2 年前にブラックウェルを退学になってる… |昔はすごく勉強してたのに… |もったいないな…",
  ["Act_E1_5A_ChloeRoom_RewindChoice_InterveneTakeBlame_Max_010"] = "私 まずい状況じゃない? |クロエのためとはいえ ウソをついたら奨学金が危ないし |自分のことも考えないと…",
  ["Act_E1_5A_ChloeRoom_RewindChoice_InterveneTakeBlame_Max_020"] = "クロエとの関係はどうにかなったけど 面倒な人に目を付けられちゃった… |巻き戻して クロエにはあとでフォローしようかな",
  ["Act_E1_5A_ChloeRoom_RewindChoice_NotHidden_Max_010"] = "最悪… デイビッド完全にキレてる |巻き戻してクローゼットに隠れた方がいいかも",
  ["Act_E1_5A_ChloeRoom_RewindChoice_StayHiddenBlameChloe_Max_010"] = "デイビッド クロエになんてことを… もし私が割って入ってたら…?",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Interact01_Max_010"] = "いい写真。 クロエはパパっ子だったんだよね",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Look01_Max_010"] = "ここに何入れてんだろ…",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Look02_Max_010"] = "平気なフリしてるけど おじさんのことは忘れられないんだと思う…",
  ["Act_E1_5A_ChloeRoom_SuitCase_Look01_Max_010"] = "このスーツケースにはがらくただけ",
  ["Act_E1_5A_ChloeRoom_TV_Look01_Max_010"] = "あのテレビ 前にリビングにあったやつだ",
  ["Act_E1_5A_ChloeRoom_TrashCan_Interact01_Max_010"] = "駐車違反の罰金 払ってない… 大人しくできないタイプだもんね",
  ["Act_E1_5A_ChloeRoom_TrashCan_Look01_Max_010"] = "クロエのゴミ 溢れ出ん",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_010"] = "クロエ 怒ってるな。 CD 見つけないと",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_020"] = "もう子ども向けの教育番組は観ないよね さすがに…",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_030"] = "クロエの部屋で宝探しなんて何年ぶり?",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_040"] = "変な日… 今度はクロエの CD を探すことになるなんて",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_050"] = "全部打ち明けたいけど… きっとひかれるよ",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_060"] = "ただでさえ不機嫌だったのに 悪化させちゃった。 どうにかできないかな…",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_010"] = "クロエはそっとしておこう。 道具を探さなきゃ",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_020"] = "クロエを 1 人にしてあげて 道具を探そう",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_060"] = "昔はいつもクロエのママに うるさいって怒られてたのに。 静かだな",
  ["Act_E1_5A_ChloeRoom_VoiceOver03_Max_010"] = "今日は不思議なことばかり…",
  ["Act_E1_5A_ChloeRoom_VoiceOver03_Max_020"] = "クロエが踊ってる。 いい写真が撮れそう",
  ["Act_E1_5A_ChloeRoom_VoiceOverHelpChloe_Max_010"] = "かなり疲れてるけど クロエを助けられるかも",
  ["Act_E1_5A_ChloeRoom_VoiceOverHelpChloe_Max_020"] = "力を使えば 助けられるかも",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_010"] = "やっと落ち着けると思ったのに…",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_020"] = "時間を巻き戻せば…",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_030"] = "ウソでしょ。 今力を使うべき?",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_040"] = "隠れないと!",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_050"] = "どこに隠れよう",
  ["Act_E1_5A_ChloeRoom_VoiceOverNotHurtChloe_Max_010"] = "クロエを傷つけないようにできるはず",
  ["Act_E1_5A_ChloeRoom_VoiceOverNotHurtChloe_Max_020"] = "なんとかできるはず",
  ["Act_E1_5A_ChloeRoom_VoiceOverRewind_Max_010"] = "怖い人だな… |学校に言われたら 奨学金没収されちゃうかも |クタクタだけど まだ力は使えそう",
  ["Act_E1_5A_ChloeRoom_VoiceOverRewind_Max_020"] = "疲れてるけど 戻って違う選択もできる",
  ["Act_E1_5A_ChloeRoom_Window_Interact01_Max_010"] = "全然ダメだ。 他の所を探そう",
  ["Act_E1_5A_ChloeRoom_Window_Look01_Max_010"] = "「ここから下に降りる」度胸試し… 結局やらなかったな",
  ["Act_E1_5A_Corridor_AuroraPicture_Look01_Max_010"] = "「汝再び故郷に帰れず」というけど… 帰ってきた",
  ["Act_E1_5A_Corridor_Books_Look01_Max_010"] = "10 年は読まれてなさそうな本。 つまんないもんね",
  ["Act_E1_5A_Corridor_Closet_Look01_Max_010"] = "入れない",
  ["Act_E1_5A_Corridor_ExitCorridor_Interact01_Max_010"] = "道具は持ってきたし もう下に用はないな",
  ["Act_E1_5A_Corridor_GuestRoom_Look01_Max_010"] = "ここも入れない。 何に使うんだろう",
  ["Act_E1_5A_Corridor_ParentsRoom_Look01_Max_010"] = "クロエの両親の部屋ね",
  ["Act_E1_5A_Corridor_Window_Look01_Max_010"] = "なにも変わってない。 私たち以外は",
  ["Act_E1_5A_ParentsRoom_Bird_Look01_Max_010"] = "いや! かわいそうに! 私 助けてあげられるかも…",
  ["Act_E1_5A_ParentsRoom_Bird_Look02_Max_010"] = "さようなら 鳥さん |力を使えば助けられたかもしれないけど 限界はあるみたい…",
  ["Act_E1_5A_ParentsRoom_Bird_Look03_Max_010"] = "さようなら 鳥さん |力を使えば助けられたかもしれないけど 遅すぎたみたい…",
  ["Act_E1_5A_ParentsRoom_Bird_Look04_Max_010"] = "おはよう 鳥さん。 さあ飛んでおいき",
  ["Act_E1_5A_ParentsRoom_Book_Look01_Max_010"] = "「21 世紀のサバイバルガイド: 行動か死か」 |うわあ。 終末に向けての準備か",
  ["Act_E1_5A_ParentsRoom_Closet_Interact01_Max_010"] = "おばさん まだダイナーで仕事してるんだ |旦那さんは警官? どんまい クロエ",
  ["Act_E1_5A_ParentsRoom_Drawer01_Interact01_Max_010"] = "ドッグタグだ。 「デイビッド・マドセン」",
  ["Act_E1_5A_ParentsRoom_Drawer02_Interact01_Max_010"] = "おじさんの思い出の品だ。 新しい旦那さん 悪い人じゃなさそう…",
  ["Act_E1_5A_ParentsRoom_JoycePhoto_Max_010"] = "おばさん 幸せそう。 クロエの新しいパパ 悪い人じゃないんじゃ…",
  ["Act_E1_5A_ParentsRoom_Magazine_Look01_Max_010"] = "おばさんは通販カタログが好きなんだよね",
  ["Act_E1_5A_ParentsRoom_Necklace_Look01_Max_010"] = "あっ… これ クロエが母の日におばさんに作ってあげたんだっけ |大事にしてるね",
  ["Act_E1_5A_ParentsRoom_Papers_Look01_Max_010"] = "請求書が払えてないみたい…",
  ["Act_E1_5A_ParentsRoom_Uniform_Look01_Max_010"] = "おばさん まだダイナーで仕事してるんだ |旦那さんは警官? どんまい クロエ",
  ["Act_E1_5A_ParentsRoom_VoiceOver_Max_010"] = "クロエの両親の部屋だ。 今日は覗きまくり…",
  ["Act_E1_5A_ParentsRoom_VoiceOver_Max_020"] = "今日だけで 2 つの命を助けた… どういうこと?",
  ["Act_E1_5A_ParentsRoom_Window_Look01_Max_010"] = "すぐそこに住んでたなんて…",
  ["Cue_E1_5A_ChloeRoom_Box_Chloe_010"] = "ちょっと! スノードームが壊れたじゃん!",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_001"] = "CD 見つかった?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_002"] = "散らかってるけど 探せばあるから",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_003"] = "どっかにあるよ 探せって",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion2_Chloe_001"] = "音楽かけてくれる?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion3_Chloe_001"] = "5 年振りに会った大親友に いきなり大事なスノードーム壊されるとか |ありえなすぎて笑えるんだけど |もういいからさ 早く音楽かけてくれる?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_001"] = "で? 大人になったマックスは 毎日なにやってんの?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_006"] = "高校デビューして クラブ通いでもしてるのかと",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_007"] = "ムリすんなって。 パーティなんか行ったこともないクセに",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_008"] = "あー… うん。 聞くんじゃなかったよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_009"] = "ダサいってことないだろ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_014"] = "クラブで泥酔してひっくり返ってるバカどもなら観察する価値あるけど |きっといい写真 撮れるよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_015"] = "それ 12 歳のときの話だろ? 見栄張らないで 写真に専念しとけって",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_016"] = "なんで謝る? 写真は楽しくないのかよ? もういい…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_017"] = "へえ いいじゃん。 あたしもちょっと気が晴れたよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_002"] = "特に何も。 自ら動くより 見てるタイプだからさ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_003"] = "パーティ三昧だよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_004"] = "大人って実感はないよ… 年を取るだけ分からないことが増える… |今日は特にそう思う",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_005"] = "写真撮ってる |自撮りしたり 風景撮ったり いろいろ |ダサいかもしれないけど すごく楽しいよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_010"] = "そんなわけないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_011"] = "ひどいな。 クロエの誕生日パーティ行ったよ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_012"] = "ごめん…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_013"] = "フレームに「これだ!」って瞬間がおさまるとね… |怖いものなんてない って気分になる",
  ["Cue_E1_5A_ChloeRoom_CHChloe_DeskObj_Chloe_001"] = "工具 見つかったんだ。 そこの机 使っていいよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_001"] = "その顔は なんか言いたいことがあるな? 言えよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_004"] = "ネイサンみたいな野郎にまた襲われて 反撃できなかったら死ぬだろ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_005"] = "また誰かに襲われたらどうする",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_008"] = "あんなにたくさんあるんだ。 1 つぐらい借りても文句ないだろ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_009"] = "レイチェルと一緒に LA に行けてたら こんなことしなくて済んだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_011"] = "分かってる。 でも 銃を持ってれば身を守れるだろ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_014"] = "あたしに銃を向けるヤツがいなくなれば 必要なくなる",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_015"] = "ネットの動画で勉強したよ。 バッチリだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_018"] = "危ないことしようってわけじゃない 護身用だよ |力が弱い女こそ 銃で武装すべきだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_002"] = "なんで銃なんか盗んだの? 絶対バレるよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_003"] = "銃は返したほうがいいよ。 危ないって…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_006"] = "あの人にバレたら 大変なことになるよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_007"] = "そんなこと言わないで",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_010"] = "でもクロエ… 私 怖いよ…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_012"] = "それは違うよ! 銃は怖い。 こんなことしてないで ギターでも弾いてようよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_013"] = "使い方 分かるの?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_016"] = "銃 持ってたって 安全は保証されないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_017"] = "むやみに持ち歩かないでよ? 分かった?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun02_Chloe_001"] = "窓から抜けだそう",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_001"] = "MP3 の再生ぐらい 自力でできるだろ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_002"] = "音楽かけるより 気まずい沈黙のほうがいいか?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_003"] = "おーい 音楽まだかー?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_004"] = "マックス! ステレオはそこ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_005"] = "さっさと音楽かけてくれよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_006"] = "静かすぎてヘンになりそうだ。 早く音楽かけろって",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_007"] = "音楽かけろよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_001"] = "あたしが貼ったんだ。 親友だった |パパが死んでマックスが引っ越して ひとりぼっちだったとき… |レイチェルに救われた",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_004"] = "レイチェル・アンバー。 あたしの…親友だった |パパが死んでマックスが引っ越して ひとりぼっちだったとき… |レイチェルに救われた",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_006"] = "知ろうともしなかっただろ。 14 歳までは… 親友だったのに",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_009"] = "レイチェルはいつも味方だった。 一緒にビッグになろうって言ってさ… |あたしとは全然違うタイプで… スターになりたがってた",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_011"] = "それが夢だった あたしたち 2 人のね |こんな田舎町 出て ロスに行くつもりだった",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_015"] = "ママは再婚のことしか頭になかった",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_016"] = "クズとの再婚で浮かれてたよ… それも出て行こうと思った理由",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_017"] = "再婚のほうが大事だったんだろ… 家を出る理由が増えただけだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_019"] = "半年前。 突然 姿を消した。 あたしにも言わずに… 1 人で",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_022"] = "あたしに黙って行くはずない。 絶対 何かあったんだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_023"] = "現実逃避してるよ。 でも 絶対 何かあったんだ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_026"] = "みんないなくなる |パパもマックスも… レイチェルも… みんな。 ねえ 音楽まだ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_028"] = "いなくなる前 「運命の人と出会った」とか言ってた… それっきり",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_002"] = "レイチェル・アンバーだよね? 「尋ね人」のビラ 学校中に貼ってあるよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_003"] = "それ… 誰? 話したくなかったらいいよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_005"] = "全然知らなかったよ…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_007"] = "今も親友だよ |連絡しなかったのは完全に私が悪いけど… |レイチェルがいてよかった",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_008"] = "私の代わりに レイチェルがいてくれたんだね…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_010"] = "モデルみたいだよね",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_012"] = "どうして行かなかったの? ご両親に… おばさんに反対されたとか?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_013"] = "気持ちは分かるけど… おばさん 反対したでしょ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_014"] = "でもお母さんは? おばさんはそれを聞いてなんて?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_018"] = "そうだったんだ… レイチェルは いつ頃いなくなったの?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_020"] = "自分の意志でいなくなったんじゃない? 人生をやり直したくなったとか",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_021"] = "レイチェルのご両親は? 探してるんでしょ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_024"] = "分かってる。 ただ 可能性を考えてるだけ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_025"] = "他にも何か知ってる風だけど…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_027"] = "そのあと 一度も連絡ないの?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_001"] = "なあ そうなんだろ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_004"] = "すげえ… ニンジャみたいだ!",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_005"] = "相変わらずウソつくのがヘタだな",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_009"] = "マジかよ ヤベえ!",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_012"] = "あたしだって すぐ分かった?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_014"] = "だろうね。 なにしろ 5 年振りだもんな",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_016"] = "ま 当然だろうな",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_018"] = "ムリもないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_020"] = "それじゃ ネイサンとの話も聞いてたのか",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_022"] = "聞いてたんだな",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_024"] = "ウソだ いたなら全部聞こえただろ?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_026"] = "それじゃ 次の質問。 誰かに言ったか?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_031"] = "あのクズ… 思い出すだけでぞっとする… で 誰に言った?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_032"] = "誰にでもだ! 言ったのか?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_033"] = "ムリもないよ。 あたしもビビったし",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_034"] = "あの甘ったれたボンボンに そんな度胸はないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_038"] = "本気で言ってんの? あの酒浸りはな 学校の利益しか頭にないんだ |絶対 信用するなよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_040"] = "助かるよ… いつかちゃんと説明する。 ホント ありがとな",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_002"] = "うん… 奥に隠れてた",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_003"] = "誤解だよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_006"] = "ニンジャならネイサンを始末してたよ。 私はチョウチョの写真撮っただけ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_007"] = "わかったよ…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_010"] = "銃を見た瞬間 チビりそうになったけどね…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_013"] = "全然。 髪の毛も服も違ったから",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_015"] = "よく分からなかった",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_017"] = "すごく怖くて ちゃんと見てられなかったし",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_019"] = "うん… ホント 今日は驚きだらけ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_021"] = "パニクってたし… 何かわめいてるのは分かったけど…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_023"] = "少しだけね…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_025"] = "お金がどうこうって話は覚えてるけど… それ以上はホントに知らないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_027"] = "そりゃ言うよ! ネイサンは銃を持ってたんだよ!?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_028"] = "「誰か」って?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_029"] = "ううん… 怖くて無理だった…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_030"] = "言いたかったけど… だって あいつ何するかわかんないし",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_035"] = "校長先生に… でも信じてもらえなかった",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_036"] = "校長先生に言ったほうが…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_037"] = "でも あのままいけば絶対撃たれてたよ! やっぱり校長先生に…",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_039"] = "クロエの名前は出してない。 信じてよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_041"] = "ホントだって。 誰にも言ってない ウソじゃないよ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_001"] = "ガレージにクソオヤジの工具がある。 カメラ用のもきっとあるだろ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_002"] = "マックス ここには工具はないぞ。 ガレージを探せって",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_003"] = "1 人でまったりさせろよ。 工具は 1 階のガレージだってば",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_001"] = "窓から逃げるぞ。 クソオヤジに見つかると面倒だ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_002"] = "何やってんだよ? 早く行こう",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_003"] = "何グズグズしてんだ? 窓開けろって!",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_001"] = "よし 窓から脱出だ! 大丈夫 毎晩やってるから",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_002"] = "マックス 窓を開けろよ。 早く逃げるぞ",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_003"] = "早く逃げよう。 窓を開けろって!",
  ["Cue_E1_5A_ChloeRoom_ChloeDanceLoop_Chloe_010"] = "ちゃんとかっこよく撮ってくれよ!",
  ["Cue_E1_5A_ChloeRoom_ChloeDanceLoop_Chloe_020"] = "どうした? 早く撮れって",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_AlreadyOut_Max_010"] = "そうです… 私のです",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_030"] = "もう放っといてくれよ! 女子高生相手に軍隊ごっこしてんじゃねえ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_050"] = "うるせえよ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_090"] = "いいか 今度あたしに触れでもしたら ブタ箱にぶち込んでやるからな |よくおぼえとけよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_110"] = "ガキ相手に なにムキになってんだ?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_150"] = "知ってるぞ。 今日 ケイト・マーシュに嫌がらせしてただろ |証拠写真があんだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_170"] = "とぼけてんじゃねえよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_210"] = "言い訳はいい |みんな あたしを見捨てる。 親友も当てにならない |そうだろ?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_220"] = "この町にもう用はない… あんたにも会わなきゃよかった… |こんなとこ さっさと出て行きたいよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_020"] = "ウソをつけ。 クロエから買ったんだろう? 友だち価格でもお願いしたのか?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_040"] = "なんだその口の利き方は…!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_060"] = "… いいか… お前が悪いんだ。 俺にも限界がある!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_070"] = "マックス お前は相当な問題児だ。 せめて学校では大人しくしてるんだな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_080"] = "ここへは二度と来るな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_100"] = "刑務所行きはお前のほうだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_120"] = "その生意気な口と態度 いつか後悔するぞ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_130"] = "あと 部屋も片付けろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_140"] = "警告しておく。 クロエには近づくな |こいつといるとトラブルに巻き込まれるぞ |余計なことはするな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_160"] = "何の話だ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_180"] = "その生意気な口と態度 いつか後悔するぞ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_190"] = "あと 部屋も片付けろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Max_010"] = "私のじゃありません",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Max_200"] = "ごめん クロエ… パニクっちゃって…",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeHappy_Chloe_010"] = "かばってくれてありがと。 マックスのおかげで追い払えたよ |うちら 怖いものナシだな! 最高の気分だ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeHappy_Chloe_020"] = "よし 窓から逃げよう。 とっておきの場所を知ってるんだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_020"] = "絵に描いたみたいなクソオヤジだったろ?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_040"] = "いや 見つかってたら あれじゃ済まないし",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_060"] = "とりあえず 窓から逃げよう。 いいところに連れてってやるからさ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_010"] = "クロエ 大丈夫?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_030"] = "ごめんね…",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_050"] = "想像つかないよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceHidden_David_010"] = "誰のだ!?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceNotHidden_Chloe_010"] = "あたしのじゃないよ。 マックスのだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceNotHidden_David_020"] = "そうなのか?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_Chloe_020"] = "あんたの銃なんか取るわけねえだろ。 そもそも銃は嫌いだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_Chloe_040"] = "いちいちうるせえな! 放っといてくれよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_010"] = "銃が 1 丁なくなった",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_015"] = "お前か?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_030"] = "おい! なんだこれは! またここで吸ってたな!?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_050"] = "俺に口答えをするな… 質問に答えろ 命令だ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_Chloe_020"] = "触ってなんかねえよ! そんなもん興味もない",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_David_010"] = "ファイルには触るなと言ったはずだ。 どういうつもりだ?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_David_030"] = "問題ばかり起こすのもいい加減にしろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_GetOut_David_020"] = "そういうことか。 俺は他人を家に上げない。 特に問題児はな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_GetOut_Max_010"] = "ごめんなさい… それ 私のです",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_Chloe_010"] = "ったく…",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_Chloe_030"] = "服 着替えてただけだって。 大げさなんだよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_David_020"] = "何をしていた?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_David_040"] = "ごまかそうとしても無駄だ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_010"] = "ちっ…",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_030"] = "関係ねーだろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_050"] = "だから他人じゃねえっつうの! 友だちだよ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_020"] = "何をしている? どういうことだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_040"] = "他人を家に上げるな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_060"] = "お前のか? まったく冗談じゃない",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_010"] = "マックスには特別に見せてやるよ。 新しい\"おもちゃ\"だ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_020"] = "「プライス… クロエ・プライスだ」 バン!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_040"] = "大丈夫だよ。 弾 入ってないし。 まだね",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_060"] = "男が持つ場合の話だよ。 ネイサンとデイビッドとか あぶないヤツばっかだろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Max_030"] = "ちょっと… 危ないよ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Max_050"] = "銃は嫌いなんでしょ…?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_010"] = "あたしもママも あんたの軍隊の兵士じゃない!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_020"] = "さっさとママと別れろよ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_040"] = "二度と あたしに手あげんじゃねえぞ… |今度やったら… すぐに警察呼んでやるから…!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_060"] = "ブタ箱にぶち込んでやる!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_080"] = "知ってるぞ。 今日 ケイト・マーシュに嫌がらせしてただろ |証拠写真があんだ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_100"] = "こっちのセリフだよ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_010"] = "黙れ! ジョイスは関係ない!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_030"] = "クロエ… すまない。 ジョイスは大切な人だ… だがお前の態度は…",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_050"] = "口だけだな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_070"] = "クロエ… お前は何も分かっていない",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_090"] = "なんだと…? 余計な真似するな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_110"] = "クロエ… お前は何も分かっていない",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_050"] = "やめろ あたしの友だちにそんな口利くな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_070"] = "あんたこそ 警察 気取ってんじゃねえよ ただの警備員だろ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_110"] = "ケイト・マーシュにも嫌がらせして 次はマックスかよ!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_130"] = "証拠写真があんだ! 分かったら さっさと出てけ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_010"] = "よくも人の家にこんなものを… 警察を呼ぶか? |当然 学校にも報告がいくだろうな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_020"] = "どこで何をしようと勝手だが―",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_030"] = "クロエまで一緒に巻き込むのはやめろ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_040"] = "学校での一件といい 調子に乗るんじゃないぞ… |次から次へと… どうした 口答えしないのか? 何とか言え",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_060"] = "お前に友だちなどいない",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_080"] = "元軍人 のな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_090"] = "マックス。 今度この家に来たら… ただでは済まないからな",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_100"] = "非常ベルの件といい… どうもお前は図に乗っているようだ |どうした 口答えしないのか? え?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_120"] = "何? 何の話だ",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_140"] = "まったく… 知ったような口を",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_150"] = "マックス。 二度とこの家に来るな。 最後の警告だ",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_010"] = "この曲 アガるな…! 恥ずかしがんなって!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_020"] = "踊れって!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_030"] = "やればできるじゃん!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_050"] = "消して! 早く!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_070"] = "鳴らしてねえし!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_080"] = "ウゼー",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_100"] = "ふざっけんな…!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_110"] = "マックス 早く隠れて。 見つかったら あたしがぶっ殺される",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_130"] = "着替えてんだよ うるせーな!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_140"] = "マックス どっかに隠れろ。 早く!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_040"] = "クロエ! 部屋にいるのか?",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_060"] = "やかましい音楽を鳴らすな! 何度 言えば分かるんだ!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_090"] = "そこにいろ 話がある",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_120"] = "クロエ。 何してるんだ 早くドアを開けろ",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_020"] = "待てって!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_040"] = "着替えてるっつってんだろ!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_060"] = "ブラジャーが引っかかったんだよ!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_010"] = "クロエ… 何してるんだ",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_030"] = "何を隠してる",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_050"] = "ウソをつくな。 いいから ここを開けろ。 何をしてる? クロエ?",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_070"] = "ふざけるのもいい加減にしろ! さっさとここを開けるんだ!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_080"] = "3 秒以内に開けないなら ドアを破るからな。 1… 2… 3…",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_010"] = "たしか… 先月 誕生日だったよな",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_020"] = "死んだパパのカメラ… プレゼントだ",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_040"] = "いいって。 あたしは使えないし ふさわしい人にあげたほうがパパも喜ぶし",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_050"] = "再会の記念に この写真もらうから。 な?",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_070"] = "なんか湿っぽくなったな… よし 気分を変えて 踊りまくろう!",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_090"] = "ほら マックスも踊るんだよ! |どうした 恥ずかしいのか!? |じゃ そのカメラであたしを撮って",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_030"] = "誕生日覚えててくれてうれしいけど… これはもらえないよ",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_060"] = "ホントにいいの!? ありがとう すごくうれしいよ",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_080"] = "ちょっと本気?",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_010"] = "どうぞご自由に 何でも見てくれよ",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_020"] = "マックスは相変わらずだな",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_030"] = "相変わらずのマイペースだな",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Chloe_010"] = "おい 見るな!",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Chloe_030"] = "当たり前だよ…",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Max_020"] = "ごめん…! 悪気はなかったの… すごく仲よさそうに見えたから…",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_010"] = "どう?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_030"] = "これ マックスが?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_050"] = "えーと…",
  ["Cue_E1_5A_ChloeRoom_RepairFail_DavidTake_Chloe_010"] = "あの野郎… なにやってやがる…",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_010"] = "あれ…? これ見たことあるぞ。 どういうこと? いつ撮ったんだ?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_030"] = "おいおい マジかよ!",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_040"] = "トイレの非常ベル マックスの仕業? |だからネイサンに追われてた… |そういうことか!",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_050"] = "命の恩人じゃん…",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_060"] = "なあ そうなんだろ?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Max_020"] = "それは…",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Max_020"] = "全然ダメ",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Max_040"] = "うん。 今日撮ったやつね",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Victoria_Chloe_010"] = "はは… 笑える。 いい気味だな",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Victoria_Chloe_020"] = "構図もいい",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_010"] = "この部屋もだいぶ変わっただろ",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_030"] = "ま 義理のクソオヤジのせいで「まったり」ってわけにもいかないけど |ドアしめて",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_040"] = "音楽でもかけてよ",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Max_020"] = "いい感じ まったりできそう",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Chloe_010"] = "ガレージに行けば カメラを直す工具があるはずだよ",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Chloe_030"] = "全然平気。 ちょっとひとりでまったりしたいだけ",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Max_020"] = "クロエ… 大丈夫?",
  ["Cue_E1_5A_ChloeRoom_Window_Interact02_Chloe_010"] = "いいよ 先に降りて",
  ["Cue_E1_5A_ChloeRoom_Window_Interact03_Max_010"] = "クロエ 待ってよ!",
  ["Act_E1_5B_Garage_BlackWellMap_Look01_Max_010"] = "ブラックウェルの地図? どうしてこんなものが?",
  ["Act_E1_5B_Garage_Box01_Look01_Max_010"] = "おばさんはおじさんのものが捨てられないんだ",
  ["Act_E1_5B_Garage_Car_Look01_Max_010"] = "すごい車! クロエの新しいパパが好きなんだろうな",
  ["Act_E1_5B_Garage_Computer_Interact01_Max_010"] = "パスワードもないし 道具を見つける助けにならない",
  ["Act_E1_5B_Garage_Computer_Look01_Max_010"] = "新しいお父さんのものかな",
  ["Act_E1_5B_Garage_Cupboard01_Look01_Max_010"] = "中を見てみるべき?",
  ["Act_E1_5B_Garage_Cupboard02_Look01_Max_010"] = "棚の中に道具があるかも",
  ["Act_E1_5B_Garage_Drawer01_Interact01_Max_010"] = "ないか",
  ["Act_E1_5B_Garage_Drawer01_Look01_Max_010"] = "引き出しの中かな",
  ["Act_E1_5B_Garage_Drawer02_Interact01_Max_010"] = "違う引き出しにカギがあるのかも。 他を見よう",
  ["Act_E1_5B_Garage_Drawer02_Look01_Max_010"] = "何かのデータ…",
  ["Act_E1_5B_Garage_Drawer03_Interact01_Max_010"] = "道具 ないなあ",
  ["Act_E1_5B_Garage_Drawer03_Look01_Max_010"] = "ここにあるといいけど",
  ["Act_E1_5B_Garage_Drawer04_Interact01_Max_010"] = "クロエの新しいパパって 学校の警備主任だ! |学校中に監視カメラを置くの? 心配性すぎない?",
  ["Act_E1_5B_Garage_Drawer04_Look01_Max_010"] = "道具あるかな?",
  ["Act_E1_5B_Garage_Drawer05_Interact01_Max_010"] = "元軍人で警備員のオジサン。 クロエのこと嫌いだろうな",
  ["Act_E1_5B_Garage_Drawer05_Look01_Max_010"] = "お願い! ここにありますように!",
  ["Act_E1_5B_Garage_File_Interact01_Max_010"] = "あっ! 手が滑っちゃった!",
  ["Act_E1_5B_Garage_File_Interact02_Max_010"] = "何度やっても落としちゃう!",
  ["Act_E1_5B_Garage_File_Look01_Max_010"] = "あのファイル なにが書いてあるんだろう?",
  ["Act_E1_5B_Garage_FoodCan_Look01_Max_010"] = "アルマゲドンに備えてるの?",
  ["Act_E1_5B_Garage_Food_Look01_Max_010"] = "すごい量! 100 年は缶詰めに困らないね",
  ["Act_E1_5B_Garage_GarageDoor01_Interact01_Max_010"] = "やった! 開いた",
  ["Act_E1_5B_Garage_GarageDoor01_Look01_Max_010"] = "こっち側からドアが開けられる",
  ["Act_E1_5B_Garage_GunRack_Look01_Max_010"] = "銃が一丁ない… クロエのオジサンが持ってないといいけど",
  ["Act_E1_5B_Garage_IDcard_Look01_Max_010"] = "クロエの新しいパパって 学校の警備主任だ! 信じられない!",
  ["Act_E1_5B_Garage_Medals_Look01_Max_010"] = "すごい数のメダル。 元軍人だなんてすごいな クロエの新しいパパ",
  ["Act_E1_5B_Garage_Monitor_Interact01_Max_010"] = "なに これ? 部屋にカメラをつけたの? ウソでしょ? |これって深刻な問題だよ! |クロエとおばさんは知ってるのかな…",
  ["Act_E1_5B_Garage_Monitor_Look01_Max_010"] = "スイッチ入れるべき? どうする…?",
  ["Act_E1_5B_Garage_Picture01_Look01_Max_010"] = "どうしてケイトの写真がここに? 待って なんかすごくイヤな感じがしてきた",
  ["Act_E1_5B_Garage_Picture01_Look02_Max_010"] = "あの写真はもう見たくない。 どうしてデイビッドが持ってるの?",
  ["Act_E1_5B_Garage_PizzaBox_Interact01_Max_010"] = "落ちる前にやっとくべきだったね",
  ["Act_E1_5B_Garage_PizzaBox_Interact02_Max_010"] = "さすが やるねマックス!",
  ["Act_E1_5B_Garage_PizzaBox_Look01_Max_010"] = "この古ぼけた段ボールで…",
  ["Act_E1_5B_Garage_Shelf01_Interact01_Max_010"] = "なにもない! もう…",
  ["Act_E1_5B_Garage_Shelf01_Look01_Max_010"] = "棚がたくさん。 道具の気配…",
  ["Act_E1_5B_Garage_Target_Look01_Max_010"] = "やった! 高得点!",
  ["Act_E1_5B_Garage_Tool01_Interact01_Max_010"] = "これじゃ大きすぎて カメラは直せないな",
  ["Act_E1_5B_Garage_Tool01_Look01_Max_010"] = "道具の宝庫ね",
  ["Act_E1_5B_Garage_ToolBox_Look01_Max_010"] = "精密ドライバー発見! でも手が届かない…",
  ["Act_E1_5B_Garage_ToolBox_Look02_Max_010"] = "せっかく見つけたのにあんな所に入っちゃって届かないし どうしようもない |やったわね マックス",
  ["Act_E1_5B_Garage_ToolBox_Take01_Max_010"] = "これでカメラを修理できるね。 さっさとここを出よう",
  ["Act_E1_5B_Garage_Trophy_Look01_Max_010"] = "かわいそうに。 殺された上に首を飾られるなんて",
  ["Act_E1_5B_Garage_VoiceOver_Max_010"] = "ここに必要な道具があるはず",
  ["Act_E1_5B_Garage_VoiceOver_Max_020"] = "道具も見つけたし クロエが探す前に戻ろう",
  ["Act_E1_5B_Garage_VoiceOver_Max_030"] = "カメラを直すなら 2 階ね",
  ["Act_E1_5B_Garage_WashingMachine_Interact01_Max_010"] = "私はバカなの? 全然届かない",
  ["Act_E1_5B_Garage_WashingMachine_Interact02_Max_010"] = "こっちにおいで… ほら…",
  ["Act_E1_5B_Garage_WashingMachine_Look01_Max_010"] = "不安定そうだな",
  ["Act_E1_5B_Garden_BBQ_Look01_Max_010"] = "おじさんにバーガーを焼いてもらったっけ。 最後に使ったのはおじさんかな…",
  ["Act_E1_5B_Garden_Drawing_Look01_Max_010"] = "クロエと 1 日がかりで描いたんだっけ。 今はほとんど見えない",
  ["Act_E1_5B_Garden_Grave_Look01_Max_010"] = "クロエの猫のお墓。 かわいそうなボンゴ 車に轢かれるなんて",
  ["Act_E1_5B_Garden_Swing_Look01_Max_010"] = "大好きだったブランコ。 おじさんがクロエのために作ったの",
  ["Act_E1_5B_Garden_VoiceOver_Max_010"] = "寒い… もう夏も終わりって感じだね…",
  ["Act_E1_5B_Garden_VoiceOver_Max_020"] = "静かだな… 日本庭園みたい。 オレゴンだけど",
  ["Act_E1_5B_LivingRoom_AnsweringMachine_Look01_Max_010"] = "昔の留守番電話だ。 メッセージがあるみたい…",
  ["Act_E1_5B_LivingRoom_BayWindow_Look01_Max_010"] = "庭のドア…",
  ["Act_E1_5B_LivingRoom_Books_Look01_Max_010"] = "本を熟成させてるのかな",
  ["Act_E1_5B_LivingRoom_Couch_Look01_Max_010"] = "ソファがまだある! ここで海賊ごっこをしたっけな… もはや難破船だね",
  ["Act_E1_5B_LivingRoom_EntryDoor_Interact01_Max_010"] = "集中して 私。 カメラを直す道具がいるんでしょ",
  ["Act_E1_5B_LivingRoom_EntryDoor_Look01_Max_010"] = "カギがいくらあっても足りないんじゃない? …昔はいつも開いてたのにな",
  ["Act_E1_5B_LivingRoom_ExitHouse_Interact02_Max_010"] = "道具を見つけないと。 クロエをずっとほっとくわけにもいかない",
  ["Act_E1_5B_LivingRoom_ExitLivingRoom_Interact01_Max_010"] = "道具を見つけないと上には戻れないよ",
  ["Act_E1_5B_LivingRoom_FakeMagazines_Interact01_Max_010"] = "わあ おいしそう。 おばさんの料理 また食べたい",
  ["Act_E1_5B_LivingRoom_FakeMagazines_Look01_Max_010"] = "おばさんはいつもテーブルの上に雑誌を置いてたね",
  ["Act_E1_5B_LivingRoom_GarageDoor01_Interact01_Max_010"] = "ダメだ 向こう側からカギがかかってる",
  ["Act_E1_5B_LivingRoom_GarageDoor01_Look01_Max_010"] = "向こうからカギがかかってるみたい",
  ["Act_E1_5B_LivingRoom_Mail_Look01_Max_010"] = "プライス家の経済状況はよくないみたい…",
  ["Act_E1_5B_LivingRoom_MoneyBox_Look01_Max_010"] = "私もパリに行きたい。 この貯まり方じゃポートランド行きもあやしいよ",
  ["Act_E1_5B_LivingRoom_OfficeDoor_Interact01_Max_010"] = "開いてるわけないか",
  ["Act_E1_5B_LivingRoom_OfficeDoor_Look01_Max_010"] = "仕事部屋の扉ね",
  ["Act_E1_5B_LivingRoom_Picture01_Look01_Max_010"] = "思い出の中のクロエはいつも笑ってた… 今はあんまりみたい",
  ["Act_E1_5B_LivingRoom_Picture02_Look01_Max_010"] = "ジョイスおばさんはまだ ツー・ホエール・ダイナーで働いてるんだ |町内一のバーガー 食べたくなってきた",
  ["Act_E1_5B_LivingRoom_Picture03_Look01_Max_010"] = "私だったらもっと近くで撮れたのに",
  ["Act_E1_5B_LivingRoom_Stain_Look01_Max_010"] = "このシミ覚えてる! おばさんのワインをこぼしちゃって |クロエと必死にこすったんだけど全然落ちなくて… |すごく怒られたなあ",
  ["Act_E1_5B_LivingRoom_VoiceOver_Max_010"] = "ここに来るのは 5 年ぶり。 もっと長く感じる",
  ["Act_E1_5B_LivingRoom_Window_Look01_Max_010"] = "ここからおばさんに よく怒鳴られたな",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_010"] = "開けなよ。 ビビッたの?",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_030"] = "だったら マックスが先に飲んで",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_050"] = "はいはい。 じゃあ 飲むよ?",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_070"] = "おいしいよ… すごく",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_090"] = "お子様はだーめ!",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_110"] = "ヤッバ! じゅうたんが!",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_130"] = "パパたちが来る! 隠して!",
  ["Cue_E1_5B_Garden_CouchSit_Max_020"] = "ビビッてないもん! 今開けるって",
  ["Cue_E1_5B_Garden_CouchSit_Max_040"] = "イヤだよ! 言い出しっぺはクロエじゃん",
  ["Cue_E1_5B_Garden_CouchSit_Max_060"] = "どう?",
  ["Cue_E1_5B_Garden_CouchSit_Max_080"] = "私にも飲ませて!",
  ["Cue_E1_5B_Garden_CouchSit_Max_100"] = "ずるいよ! 私も飲む!",
  ["Cue_E1_5B_Garden_CouchSit_Max_120"] = "ワインだらけだよ… どうしよう…",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_020"] = "あたしはもう大人だもん。 マックスは?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_040"] = "あたしを置いて? ひどいな",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_060"] = "じゃあ あたし ララ・クロフトみたいになる! 強い女って超かっこよくない?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_080"] = "最高! 旅行先では何するの?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_100"] = "ムリじゃないよ! マックスは写真の才能あるもん |マックスが撮った写真は いつか美術館に展示される |あたしは信じてるよ",
  ["Cue_E1_5B_Garden_SwingSit_Max_010"] = "ねえ… 大人になったら何したい?",
  ["Cue_E1_5B_Garden_SwingSit_Max_030"] = "旅行したい。 すごい遠くの国とか… 世界中を旅したら 楽しいだろうな",
  ["Cue_E1_5B_Garden_SwingSit_Max_050"] = "クロエも一緒に決まってるじゃん。 冒険の旅にはボディガードが要るもん",
  ["Cue_E1_5B_Garden_SwingSit_Max_070"] = "いいね! そんで 車とか船とか飛行機とかで 好きなとこ行くの! |自分たちだけで好きなことをするの!",
  ["Cue_E1_5B_Garden_SwingSit_Max_090"] = "写真をたくさん撮りたいな。 私ホントはね 写真家になりたいんだ |絶対ムリだけどね…",
  ["Cue_E1_5B_LivingRoom_AnsweringMachine_Interact01_David_010"] = "クロエ… そこにいるのか? ピートから聞いたぞ |非番の日に お前を例のゴミ捨て場の近くで見かけたそうだ |あそこには近づくなと何度も言ったはずだな。 いいか? |あの辺りは危険だ |ろくでもない輩も住み着いている。 もう二度と行くな。 分かったな?",
  ["Act_E1_6A_CliffNow_Bird02_Look01_Max_010"] = "鳥はいいよね… いつでも逃げ出せて",
  ["Act_E1_6A_CliffNow_Bird_Interact01_Max_010"] = "捕まえた!",
  ["Act_E1_6A_CliffNow_Bird_Look01_Max_010"] = "すごくいい画になりそう! じっとしててね…",
  ["Act_E1_6A_CliffNow_Bush01_Look01_Max_010"] = "植物の 好き勝手生えてる感じがすごくいい",
  ["Act_E1_6A_CliffNow_Butterfly_Look01_Max_010"] = "蝶は自由ね",
  ["Act_E1_6A_CliffNow_CHChloe_Look01_Max_010"] = "太陽とクロエ いい構図になりそう…",
  ["Act_E1_6A_CliffNow_CHChloe_Look02_Max_010"] = "本当に怒ってる。 さっきの 言わなきゃよかったな…",
  ["Act_E1_6A_CliffNow_CampFire_Look01_Max_010"] = "未だに町の子はここで遊ぶんだね。 私は来なかったな…",
  ["Act_E1_6A_CliffNow_Fence01_Look01_Max_010"] = "このフェンスはもう風景の一部。 奥の道が駐車場に通じてる",
  ["Act_E1_6A_CliffNow_FootPrints_Look01_Max_010"] = "ビッグフットじゃないなら… なんの足跡かな?",
  ["Act_E1_6A_CliffNow_Graffiti01_Look01_Max_010"] = "これ いつからあるの?",
  ["Act_E1_6A_CliffNow_Graffiti02_Look01_Max_010"] = "綺麗だけど不穏…",
  ["Act_E1_6A_CliffNow_Graffiti03_Look01_Max_010"] = "うーん ここにもビッグフット",
  ["Act_E1_6A_CliffNow_Graffiti04_Look01_Max_010"] = "変だな このマークを見ると… 風を連想する",
  ["Act_E1_6A_CliffNow_LightHouse_Look01_Max_010"] = "カギがかかってる。 昔は階段を駆けあがったり降りたりしたな…",
  ["Act_E1_6A_CliffNow_OrientationMap_Look01_Max_010"] = "あっ クロエが秘密基地の目印に描いたやつ |非常事態の時にお互いを見つけられるようにって…",
  ["Act_E1_6A_CliffNow_SMSWarren01_Max_010"] = "ウォーレンを助けてよかった。 後悔しないといいけど…",
  ["Act_E1_6A_CliffNow_Sign01_Look01_Max_010"] = "また悪夢を見てるみたい…",
  ["Act_E1_6A_CliffNow_Sign02_Look01_Max_010"] = "この看板 ちゃんと読んだことなかったな",
  ["Act_E1_6A_CliffNow_Squirrel_Look01_Max_010"] = "こんにちは リスさん。 にらめっこしましょ",
  ["Act_E1_6A_CliffNow_Totem_Look01_Max_010"] = "こんなのあったっけ? 長い間あるように見えるけど…",
  ["Act_E1_6A_CliffNow_TrashCan_Look01_Max_010"] = "ひどい人もいるなあ",
  ["Act_E1_6A_CliffNow_Tree01_Look01_Max_010"] = "この木は何世紀も生きてるけど… 私は金曜日を生きのびられるかどうか…",
  ["Act_E1_6A_CliffNow_TreeGraffiti01_Look01_Max_010"] = "木に俳句? すてき",
  ["Act_E1_6A_CliffNow_TreeGraphiti_Look01_Max_010"] = "ウソ! すっかり忘れてた! この頃まで巻き戻せないの!?",
  ["Act_E1_6A_CliffNow_VoiceOver02_Max_010"] = "今思うと クロエを助けてあげればよかった…",
  ["Act_E1_6A_CliffNow_VoiceOver02_Max_040"] = "デイビッドとはもう会いたくないな",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_010"] = "何年ぶりに来たんだろう…",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_020"] = "10 月の空気 大好き",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_030"] = "悪夢よりずっと平和な光景",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_040"] = "子どもの頃に戻れたらいいのに",
  ["Act_E1_6A_CliffNow_WildLifePanel_Look01_Max_010"] = "80 年代から看板変えてないんじゃない…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_001"] = "いいから座れよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_003"] = "座んなよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_008"] = "味方になってほしかっただけだ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_009"] = "気にすんな。 あのクソオヤジじゃ 普通ビビるって",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_010"] = "クソオヤジから一本取ったからな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_011"] = "おかげで助かったよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_013"] = "イヤな思いをさせてゴメンな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_015"] = "ママが家に連れ込んだとたん ずっとあの調子だよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_020"] = "そもそも なんであの子を?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_021"] = "ケイトって 例の地味な子だろ? なぜあの子を?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_022"] = "ケイトなら知ってる。 クソオヤジは何であんないい子を…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_023"] = "それをダシにゆすれただろうな。 いまに見てろ…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_025"] = "秘密のファイル作ったりな。 敵の情報でも集めてるつもりだろ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_027"] = "ファイル 見たか?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_032"] = "やっぱりな。 何が入ってた?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_033"] = "見たんだろ? ウソつくな。 何が入ってたんだ? スナッフフィルムか?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_034"] = "あたしの予想じゃ… きっとエグいエロビデオだな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_035"] = "いい子ぶっちゃってさ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_039"] = "いくら仕事でもやりすぎだろ。 戦争じゃねえっつうの",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_040"] = "見なくてよかったな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_042"] = "クソみたいな人生だよ。 この町じゃ 誰も秘密を持てない",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_043"] = "あいつは学校の生徒にヤバいもん売りつけてる… |あたしもだまされて 飲まされた",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_044"] = "どうかな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_049"] = "初めて会ったのは とあるシケた飲み屋だ |酔ったあいつは 札束をちらつかせてた",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_051"] = "あの野郎… 許さないからな…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_056"] = "誰かさんが校長に言いつけてくれたから 大丈夫だろ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_057"] = "まだ誰も知らないのが救いだ。 このまま済ませてたまるか",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_058"] = "ムダだよ。 まだ誰も知らないのが救いだ。 あの野郎 覚えとけよ…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_060"] = "でも 今日は助けてくれたじゃないか。 いまだに信じられないよ |こうしてまた会えたのはきっと…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_064"] = "だよな。 ガレージに大事に隠してんだから よほどのもんなんだろ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_065"] = "あいつ ガレージに怪しいファイルを隠してるんだ。 前に見たことがある",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_067"] = "ああ でも 見なくてよかったかも。 バレたら殺されてた",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_068"] = "監視マニアなんだろ… 家の中にもカメラがありそうだ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_070"] = "は? ウソだろ?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_072"] = "やっぱり! あの野郎 どうかしてやがる…! |ひとまず知らなかったことにしよう…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_082"] = "欲しかったよ… 借金 やまほどあるから |レイチェルと町を出る資金も貯めときたかった",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_086"] = "あいつの部屋… 男子寮に行って 自慢話につきあった |油断した隙に… 飲み物に何か入れられたんだ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_087"] = "3000 ドルとその利子。 ネイサンから巻き上げようと思ったのに… |飲み物に妙なもん入れられてさ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_088"] = "気を失って倒れて… 目が覚めたら ネイサンがにやつきながらカメラを構えてた",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_090"] = "よく覚えてないけど… タマを蹴ってやろうとしたらランプに当たって |ヤツがひるんだ隙に逃げたんだ |マジでやばかった…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_093"] = "口止め料を巻き上げようと 女子トイレに呼び出した",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_095"] = "ムダだよ。 校長に言いつけて何かいいことあったか?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_097"] = "あたしがバカだった。 泥酔してたから いいカモだと思ってさ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_004"] = "クロエ… 怒ってる?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_005"] = "助けられなくてごめん",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_006"] = "ずいぶんごきげんだね",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_007"] = "ありがと。 ここに来たら気持ちも晴れたよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_012"] = "クロエは強いね。 デイビッドは本当に最低だよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_014"] = "クロエは毎日でしょ…? いつもあんなふうなの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_016"] = "ケイトをいじめた証拠の写真 撮っといてよかった",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_017"] = "ケイトの写真撮るのは気がひけたけど あまりにひどかったから…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_018"] = "今日 ケイト・マーシュをいじめてるの見たよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_019"] = "ケイトをいじめてたところ 写真に撮っとけばよかった",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_024"] = "デイビッドはちょっと普通じゃないよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_028"] = "うん 見た… 気になっちゃって",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_029"] = "ファイル?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_030"] = "気にはなったけど… でも 余計なことに首突っ込まないほうがいいかなって",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_031"] = "まさか",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_036"] = "ケイト・マーシュと… 他の生徒の隠し撮り",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_037"] = "えー…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_038"] = "うるさいな",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_045"] = "ネイサンにも秘密があるの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_046"] = "クロエでも?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_047"] = "なんでネイサンを脅してたの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_048"] = "うそ…!",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_054"] = "やめときなよ… あいつ様子がおかしかったもん",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_055"] = "私たちだけじゃどうにもならないよ? 警察に知らせなきゃ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_059"] = "毎回助けられるわけじゃないよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_061"] = "運命?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_062"] = "見つけたら絶対読んでたのに…",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_063"] = "ファイルって?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_066"] = "何それ 不気味だな… ファイルを見れば何か分かりそうだけど",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_069"] = "やっぱり知らなかったんだね… クロエの家 監視されてるよ",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_071"] = "家中に隠しカメラがある。 ガレージのモニターに映ってたの",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_073"] = "知らないほうがいいこともあるよね",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_074"] = "それで? ちゃんと説明して",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_079"] = "ホントなの…?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_081"] = "そんなにお金 欲しかったの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_083"] = "それから ネイサンとはどうなったの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_084"] = "借金って いくら?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_085"] = "信じられない… もちろん 信じるけど… ひどすぎるよ。 それで?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_089"] = "それで…?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_091"] = "信じられない… よく逃げたね。 それでどうしたの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_092"] = "ひどすぎる! 冗談じゃないよ! それでどうしたの?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_094"] = "それがさっきの…",
  ["Cue_E1_6A_CliffNow_DialEnd_Chloe_010"] = "これが運命なら… レイチェルを見つけたい。 レイチェルに会いたい",
  ["Cue_E1_6A_CliffNow_DialEnd_Chloe_020"] = "あたしの大事な人はみんないなくなるんだ…! |こんな町 爆弾 落として フッ飛ばしてやりたい",
  ["Cue_E1_6A_CliffNow_IntroDialChloe_Max_010"] = "しばらくひとりにしようか?",
  ["Cue_E1_6A_CliffNow_Reveal01_Chloe_010"] = "早く来いよー!",
  ["Cue_E1_6A_CliffNow_Reveal01_Chloe_030"] = "ここに来るとさー ガキの頃を思い出すよ",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_020"] = "待ってよ!",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_040"] = "ここに来るのは久しぶりなのに… さっき来たばかりのような気がする…",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_050"] = "これって… 授業中に見た夢で通った道とまったく同じ…",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_010"] = "クロエは根に持つタイプだからな",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_020"] = "ここに来るのは久しぶりなのに… さっき来たばかりのような気がする…",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_030"] = "これって… 授業中に見た夢で通った道とまったく同じ…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_010"] = "また? ウソでしょ…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_020"] = "クロエはまだいるの? 確かめなきゃ!",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_030"] = "どうして私がこんな目に…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_040"] = "クロエは大丈夫かな…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_060"] = "どうしてまたここに?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_070"] = "あの鹿… 見覚えが…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_080"] = "鹿についていけばいいのかな…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_095"] = "進まなきゃ… あの鹿が導いてくれてる気がする",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_100"] = "そんな! また竜巻が! これ 現実なの?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_110"] = "オレゴンでこんな嵐なんて…",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_120"] = "怖い… 何が起きてるの…?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_130"] = "大丈夫… 自分を信じて",
  ["Cue_E1_6B_CliffFuture_LightHouseFalling_Max_010"] = "…ッ!",
  ["Cue_E1_6B_CliffFuture_LightHouseFalling_Max_020"] = "あの竜巻 町に向かってる…!",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_010"] = "10 月 11 日? 今は金曜日…?",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_020"] = "あと 4 日しかない!",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_030"] = "そんな…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_020"] = "おい 大丈夫か? 気失ってたぞ…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_040"] = "オレゴンに竜巻なんて滅多にない… 夢だろ",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_060"] = "とにかく落ち着けって",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_080"] = "言ってみなよ",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_110"] = "いや… 何… 言ってんだ?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_130"] = "時間を巻き戻したっていうのか?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_140"] = "マジかよ",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_160"] = "マックスが想像力豊かなオタク少女なのはよく分かったけど |アニメとかゲームじゃあるまいし",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_180"] = "落ち着けって。 今日はいろいろあったから…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_190"] = "おい なんだこれ",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_210"] = "こんなに… あったかいのにか…? バカな",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_240"] = "マックス。 最初から話して",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_250"] = "ちゃんと聞くよ…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_010"] = "クロエ…! よかった… 戻れた… |どうしようやっぱり夢じゃないんだ… 私どうしたら…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_030"] = "違うの 聞いて! また見えたの…! 町が大きな竜巻に襲われる…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_050"] = "ホントなんだってば! 空気がビリビリするのまで肌に感じて…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_070"] = "クロエ 信じてよ。 他にも聞いてほしいことがあるの |すごく… ありえないこと",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_090"] = "今日 授業中にも同じ光景を見たの… 我に返ったら… |時間を巻き戻せるようになってた",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_100"] = "笑わないで。 ウソじゃない",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_120"] = "トイレでクロエを助けたときだってそう",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_150"] = "クロエが撃たれるのを見たの |クロエが目の前で… 死んで… |だから戻って非常ベルを押したの",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_170"] = "だけどできるの。 ホントに。 怖くてしょうがない",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_200"] = "雪…?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_220"] = "異常気象…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_230"] = "嵐の予兆かも",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_010"] = "助けて…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_020"] = "助けて… 誰か…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_030"] = "誰か助けて…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_040"] = "ダメ… ダメ!",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_050"] = "なんでこんなこと…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_060"] = "やめてよ… お願い!",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_070"] = "やめて…",
  ["Act_E2_1A_Bathroom_CHKate_Look01_Max_010"] = "ケイトは滅入ってる。 デイビッドには二度と彼女に近づいてほしくない",
  ["Act_E2_1A_Bathroom_CHKate_Look02_Max_020"] = "シャワーを浴びたら本を返しにいこう |ケイトと話すチャンスかも |人と話せば少しは気が晴れるかもしれないよね…",
  ["Act_E2_1A_Bathroom_Faucet_Look01_Max_010"] = "水は濃いお茶と同じくらい眠気覚ましになるよね",
  ["Act_E2_1A_Bathroom_Faucet_Look02_Max_020"] = "水圧のこと忘れてた",
  ["Act_E2_1A_Bathroom_Faucet_Look03_Max_030"] = "これでやっと静かにシャワーを浴びれるよ",
  ["Act_E2_1A_Bathroom_KateVideoLink_Interact01_Max_020"] = "これで少しでも動画を見る人を減らせる",
  ["Act_E2_1A_Bathroom_KateVideoLink_Look01_Max_010"] = "ケイトの動画のリンク? ビクトリアって最悪…",
  ["Act_E2_1A_Bathroom_Poster01_Look01_Max_010"] = "なんでカワウソ…? よくわからない…",
  ["Act_E2_1A_Bathroom_Poster02_Look01_Max_010"] = "こないだの予防接種は 何も\"予防\"しなかったし。 もういいよ",
  ["Act_E2_1A_Bathroom_TamponDispenser_Look01_Max_010"] = "今はいらないかな",
  ["Act_E2_1A_Corridor_BlackwellMap_Look01_Max_010"] = "学校はそんなに広くないけど 迷路みたいだね",
  ["Act_E2_1A_Corridor_CHAlyssa_Look01_Max_010"] = "アリッサがまたいじめられてる… 助けてあげなきゃ",
  ["Act_E2_1A_Corridor_CHAlyssa_Look02_Max_020"] = "もしアリッサを助ければ 「正義の味方」を名乗れるかな…",
  ["Act_E2_1A_Corridor_CHBrooke_Look01_Max_010"] = "ブルックだ。 相変わらずインテリっぽい",
  ["Act_E2_1A_Corridor_CHBrooke_Look02_Max_020"] = "とりあえず勉強熱心だよね…",
  ["Act_E2_1A_Corridor_CHJuliet_Look01_Max_010"] = "よっぽど面白いものを見てるみたい…",
  ["Act_E2_1A_Corridor_CHJuliet_Look02_Max_020"] = "ケイトがどれだけ傷ついているか分かってないよ",
  ["Act_E2_1A_Corridor_Doors_VoiceOver01_Max_010"] = "朝型じゃないんだね",
  ["Act_E2_1A_Corridor_Doors_VoiceOver02_Max_020"] = "目を覚ませ マックス。 ジュリエットは隣に立ってるんだから…",
  ["Act_E2_1A_Corridor_Doors_VoiceOver03_Max_030"] = "テイラーは相変わらずビクトリアに振り回されてるみたいね",
  ["Act_E2_1A_Corridor_Doors_VoiceOver04_Max_040"] = "ブルックは不在…",
  ["Act_E2_1A_Corridor_DormMap_Look01_Max_010"] = "\"ブラックヘル\"へようこそ…",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_010"] = "ここの人たちは容赦ないな",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_020"] = "楽しそう。 唯一のオタク女子じゃないみたいでよかった",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_030"] = "警告どうも",
  ["Act_E2_1A_Corridor_ExpressionPanel_Look01_Max_010"] = "寮のすべてがここに詰まってる",
  ["Act_E2_1A_Corridor_ExpressionPanel_Look01_Max_020"] = "頑張れグラント先生! 私は無理かもしれないけど…",
  ["Act_E2_1A_Corridor_KateDoor_VoiceOver01_Max_010"] = "ケイトは早起きだから もう部屋にはいないかも…",
  ["Act_E2_1A_Corridor_KateSlate_Look01_Max_010"] = "悪魔の仕業だ",
  ["Act_E2_1A_Corridor_KateSlate_Look02_Max_020"] = "落書きしたやつをとっちめたい…",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver01_Max_010"] = "私を見つめているみたい…",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver03_Max_030"] = "どこかに隠れてるだけならいいのに",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver04_Max_040"] = "クロエが絶対に見つけてくれるよ",
  ["Act_E2_1A_Corridor_MaxSlate_Look01_Max_010"] = "みんな冷たいよね。 芸術家は助け合うものでしょ…",
  ["Act_E2_1A_Corridor_MaxSlate_Look02_Max_020"] = "私だって書けるのだよ モリアーティ教授。 認めたくないかもしれないがね…",
  ["Act_E2_1A_Corridor_Poster01_Look01_Max_010"] = "これは怖すぎて行けないね",
  ["Act_E2_1A_Corridor_Poster02_Look01_Max_010"] = "雰囲気があるね。 ほこりをかぶってるけど",
  ["Act_E2_1A_Corridor_Poster03_Look01_Max_010"] = "\"奴らは生きてる!\"",
  ["Act_E2_1A_Corridor_Poster04_Look01_Max_010"] = "このポスター 結局なにが言いたいの?",
  ["Act_E2_1A_Corridor_ScoreBoard_Look01_Max_010"] = "ここに何か貼った人たちのコラージュを作ってみたいな",
  ["Act_E2_1A_Corridor_ToiletPaper_Look01_Max_010"] = "巻き戻せば 今の出来事を防げる…",
  ["Act_E2_1A_Corridor_TrashCan_Look01_Max_010"] = "サミュエルって変人だけど 掃除は完璧だよね",
  ["Act_E2_1A_Corridor_VictoriaDoor_VoiceOver01_Max_010"] = "居留守ね まあ いいけど",
  ["Act_E2_1A_DanaRoom_BigfootBanner_Look01_Max_010"] = "デーナはちゃんと母校愛があるんだね",
  ["Act_E2_1A_DanaRoom_BirthControl_Look01_Max_010"] = "うーん…",
  ["Act_E2_1A_DanaRoom_CHDana_Look01_Max_010"] = "デーナがコーヒー無しでこんなにウキウキしているの初めて見たよ",
  ["Act_E2_1A_DanaRoom_CheerleaderOutfit_Look01_Max_010"] = "チアリーダーの生活ってどんなだろう? 色々あるんだろうな",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look01_Max_010"] = "好奇心もほどほどに…",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look02_Max_020"] = "移り変わりの激しいこと… って声に出しちゃダメだって",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look03_Max_030"] = "学校中にガイコツやオバケを飾るのは面白いかも",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look04_Max_040"] = "こんなの誰が着る… あ ビクトリアか",
  ["Act_E2_1A_DanaRoom_HalloweenStuff_Look01_Max_010"] = "デーナ 本当にハロウィン・パーティを楽しみにしてるんだね",
  ["Act_E2_1A_DanaRoom_LoganNote_Look01_Max_010"] = "読んでて悲しくなるよ",
  ["Act_E2_1A_DanaRoom_MakeUp_Look01_Max_010"] = "ハロウィンといえばメイク。 さすがデーナ 色々使ってるんだな",
  ["Act_E2_1A_DanaRoom_Rollers_Look01_Max_010"] = "ローラーブレード! |前に試したことあるけど 履いただけで骨折しそうになった…",
  ["Act_E2_1A_DanaRoom_TrevorJacket_Look01_Max_010"] = "トレバー よくきてるのかな。 怒られないといいけど",
  ["Act_E2_1A_Dormitory_BookKate_VoiceOver01_Max_010"] = "ケイトに本を返さないと。 ただでさえ昨日のこと 怒ってるだろうし",
  ["Act_E2_1A_Dormitory_BookKate_VoiceOver02_Max_020"] = "ケイトに本を返さなきゃ |私のことを信じてもらうためにも 借りたものは返さないとね",
  ["Act_E2_1A_Dormitory_ChloeSMS_VoiceOver01_Max_010"] = "いろんなことがあったけど クロエとまた会えてよかった |昔とぜんぜん変わらない…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver01_Max_010"] = "さあ 服を着替えないと…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver02_Max_020"] = "着替えて ケイトに本を返しにいかないと…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver03_Max_030"] = "出る前に着替えないと…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver04_Max_040"] = "ネイサンの復讐だ。 クロエも校長先生には言うなって言ってたし…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver05_Max_050"] = "ビクトリアだよね。 彼女をからかうとこうなるってこと… 最悪",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver07_Max_070"] = "マックス どこに本を置いたか思い出して…",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver08_Max_070"] = "えっ こんどは匿名の脅迫? もう勘弁してよ! ネイサンからだと思うけど… |他にも可能性はあるし… |今まで以上に注意しないと… もう手遅れかもしれないけど…",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver01_Max_010"] = "超能力があっても 体は汚れる。 シャワーが必要だね",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver02_Max_020"] = "巻き戻しても体はキレイにならない。 シャワーを浴びないと",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver03_Max_030"] = "シャワー用品を持っていかないと",
  ["Act_E2_1A_KateRoom_AbstinenceFlyer_Look01_Max_010"] = "まさかケイトは多重人格なの? 昼間は神の僕 夜はパーティマニア?",
  ["Act_E2_1A_KateRoom_AuntLetter_Look01_Max_010"] = "「地獄行き」が書いてないだけマシ?",
  ["Act_E2_1A_KateRoom_Bible_Look01_Max_010"] = "ケイトは聖書にもメモするんだ… 私は 1 度も教会に連れていかれなかった |行く必要もないと思ってたけど 今は何を信じるべきか分からない…",
  ["Act_E2_1A_KateRoom_CHKate_Look01_Max_010"] = "かわいそう。 ケイト 相当落ち込んでるよ…",
  ["Act_E2_1A_KateRoom_CHKate_Look02_Max_020"] = "事態は思ってたより深刻だ。 ケイトの言ってることが本当だとしたら…",
  ["Act_E2_1A_KateRoom_ChildrenDrawings_Look01_Max_010"] = "ケイトの絵は子どもの絵本にぴったり |何もかも楽しそうでカラフルで… ポジティブ",
  ["Act_E2_1A_KateRoom_CreepyDrawings_Look01_Max_010"] = "ケイトの「H・R・ギーガー」期の作品だね…",
  ["Act_E2_1A_KateRoom_FamilyPortrait_Look01_Max_010"] = "なんて生気のない家族写真…",
  ["Act_E2_1A_KateRoom_FatherPostCard_Look01_Max_010"] = "父親に溺愛されてるんだね",
  ["Act_E2_1A_KateRoom_GroupPhoto_Look01_Max_010"] = "アリッサやステラと付き合いがあったなんて知らなかった…",
  ["Act_E2_1A_KateRoom_KateBook_VoiceOver03_Max_030"] = "ちょっと よく考えて |警察と校長に知らせるってことは… あの脅迫文もバレる |これで警察沙汰に巻き込まれるのは確定ね",
  ["Act_E2_1A_KateRoom_KateBook_VoiceOver04_Max_040"] = "何してるんだか… まるでケイトの力にはなれなかった |でも もっと証拠を集めないと",
  ["Act_E2_1A_KateRoom_KateTablet_Look01_Max_010"] = "ケイトは動画の件で頼れる人がいない。 母親に勘当されないといいけど…",
  ["Act_E2_1A_KateRoom_MessyClothes_Look01_Max_010"] = "普段は超キレイな部屋なのに… 彼女からしたら豚小屋だろうな…",
  ["Act_E2_1A_KateRoom_Mirror_Look01_Max_010"] = "なぜ鏡を覆ってしまったんだろう? 自分を見られない?",
  ["Act_E2_1A_KateRoom_Pictures_Look01_Max_010"] = "私は力を正しいことに使いますよ",
  ["Act_E2_1A_KateRoom_Rabbit_Look01_Max_010"] = "こんなかわいいウサギ初めて。 ケイトはいいお母さんだろうな",
  ["Act_E2_1A_KateRoom_SistersPhoto_Look01_Max_010"] = "忘れかけてたよ。 ケイトが笑ったときの顔…",
  ["Act_E2_1A_KateRoom_Tissues_Look01_Max_010"] = "たくさん泣いたんだ。 ティッシュが全然足りないよ",
  ["Act_E2_1A_KateRoom_Violin_Look01_Max_010"] = "ケイトは毎朝バイオリンを弾いていた… 先週までは…",
  ["Act_E2_1A_KateRoom_Windows_Look01_Max_010"] = "なんて憂鬱な部屋。 ケイトはそんなに暗くなかった… 最近までは",
  ["Act_E2_1A_MaxRoom_Artbooks_Look01_Max_010"] = "カルティエ＝ブレッソン ドアノー ハミルトン… 最高",
  ["Act_E2_1A_MaxRoom_BookRoomClean_Look01_Max_010"] = "とても思慮深く内省的な本だった。 もっとブラッドベリを読まないとね…",
  ["Act_E2_1A_MaxRoom_BookRoomSacked_Interact01_Max_020"] = "これで約束の時間までにケイトの本を返しにいける |といっても時間の心配は必要ないか… |今や世界中の時間は私のもの",
  ["Act_E2_1A_MaxRoom_BookRoomSacked_Look01_Max_010"] = "こいつめ 手こずらせてくれちゃって",
  ["Act_E2_1A_MaxRoom_Desk_Interact01_Max_010"] = "散らかってるけど… ここにはない",
  ["Act_E2_1A_MaxRoom_FacebookMeme_Look01_Max_010"] = "やってくれたね ビクトリア。 私のマヌケな姿が 世界に向けて発信されてるよ",
  ["Act_E2_1A_MaxRoom_Katebook_Interact03_Max_010"] = "早く何とかしないと。 これ以上ケイトの問題を増やしたくない",
  ["Act_E2_1A_MaxRoom_Katebook_Interact04_Max_010"] = "立ち去れ 邪悪なジュースよ!",
  ["Act_E2_1A_MaxRoom_MaxBed_Interact01_Max_020"] = "やっぱりきれいに整えられているベッドが好き。 ママのしつけのおかげだね",
  ["Act_E2_1A_MaxRoom_MaxBed_Look01_Max_010"] = "子どもの頃を思い出すな。 ごめんね ママ |でも今は 気が向いたときだけ ベッドメイクすればいいんだもんね",
  ["Act_E2_1A_MaxRoom_MaxBooks_Look01_Max_010"] = "時間を何日も巻き戻せばこの本全部読めるね |でも本当に私の能力のことが分かるかな?",
  ["Act_E2_1A_MaxRoom_MaxCamera_Interact01_Max_020"] = "笑顔禁止。 マジメに自分と向き合おう",
  ["Act_E2_1A_MaxRoom_MaxCamera_Look01_Max_010"] = "人生のこの不思議なひとときが記録されるね…",
  ["Act_E2_1A_MaxRoom_MaxClothes_Interact01_Max_020"] = "シャツとジーンズでいいよね |アインシュタインだって毎日同じスーツだったっていうし |時間を巻き戻せないのにだよ",
  ["Act_E2_1A_MaxRoom_MaxClothes_Look01_Max_010"] = "「お洋服さん! お目覚めいかが? |今日はグッチのシャツとヴィトンのジャケットにしようかしら」",
  ["Act_E2_1A_MaxRoom_MaxClothes_Look02_Max_010"] = "「きゃわいいレースのブーツで 学校の廊下をモデルみたいに歩くの… |あらビクトリア 今日もオシャレね!」",
  ["Act_E2_1A_MaxRoom_MaxDVDS_Look01_Max_010"] = "この中に 実話に基づいた映画ってあったっけ?",
  ["Act_E2_1A_MaxRoom_MaxDoor_Voiceover_Max_010"] = "待った ケイトに会いにいく前に本を探さないと",
  ["Act_E2_1A_MaxRoom_MaxGuitar_Look01_Max_010"] = "ギターはまだよく眠っているね",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact01_Max_020"] = "ぶっ飛びすぎてて 逆に信じちゃいそう",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact02_Max_030"] = "ワームホールはつじつまが合うけど |科学者にもできないことを なぜ私ができるのか説明できないよね…",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact03_Max_040"] = "以前だったらマトモじゃないって思ったけど 今見ると… 署名すべきかな?",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact04_Max_050"] = "ウォーレンで受信箱がいっぱい。 手伝ってくれるのはいいけど…",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact05_Max_060"] = "ちょっとついていけないかも… デーナは完全に本気だよ",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Look01_Max_010"] = "タイムトラベルについて調べていると時間が経つのを忘れちゃう |ひたすら検索 検索… |宿題にもこれくらい熱が入ればいいのに",
  ["Act_E2_1A_MaxRoom_MaxNotes_Look01_Max_010"] = "見てると眠くなるけど 科学的な答えがあるはず…",
  ["Act_E2_1A_MaxRoom_MaxObject01_Interact01_Max_010"] = "この先 腕時計することあるかな…?",
  ["Act_E2_1A_MaxRoom_MaxObject02_Interact01_Max_020"] = "つまんないことで騒いでないで みんなでゲームをすれば楽しいのにね…",
  ["Act_E2_1A_MaxRoom_MaxPlant_Interact01_Max_020"] = "はい どうぞ… おいしいお水だよ",
  ["Act_E2_1A_MaxRoom_MaxPlant_Interact02_Max_040"] = "さあ飲んで… 生き返るのよ… 命だって私の意のまま…",
  ["Act_E2_1A_MaxRoom_MaxPlant_Look01_Max_010"] = "おはよう リサ。 今日は葉っぱがきれいだね |華のない私でも 花屋さんになら なれるかな…",
  ["Act_E2_1A_MaxRoom_MaxPlant_Look02_Max_030"] = "リサ 干からびる寸前じゃない!",
  ["Act_E2_1A_MaxRoom_MaxSchedule_Look01_Max_010"] = "ホイダ先生はまだ病気みたい。 ひどいうつ病だって誰かが言ってた。 大変だね",
  ["Act_E2_1A_MaxRoom_Mirror_Interact01_Max_020"] = "うわ ゾンビみたい。 徹夜で量子物理学について調べるとこうなるんだよね…",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_010"] = "スペースニードル見物で 唯一私が写っている写真…",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_020"] = "いい試合だったし 最高のホッケーが見れた",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_040"] = "クリステンとフェルナンドが酔っぱらって フリーモントトロールに登ってたな…",
  ["Act_E2_1A_MaxRoom_PhotoWall_Look01_Max_010"] = "「マックス・メモリアル・フォトウォール」",
  ["Act_E2_1A_MaxRoom_PostCard01_Look01_Max_010"] = "自分が 18 なんて信じられない |この歳まで写真を続けさせてもらえてよかった",
  ["Act_E2_1A_MaxRoom_Poster08_Look01_Max_010"] = "マン・レイも「自撮り」なんて言うかな?",
  ["Act_E2_1A_MaxRoom_RoomSacked_Interact01_Max_020"] = "やっぱり片付いている部屋はいいよね。 落ち着く。 あの落書き以外は…",
  ["Act_E2_1A_MaxRoom_RoomSacked_Look01_Max_010"] = "かわいそうなドニー・ダーコ… |それにジレンホールを こんな目にあわせるなんて",
  ["Act_E2_1A_MaxRoom_RoomSackedbyNathan_Look01_Max_010"] = "ある意味アートかも… いやいや これを認めるわけにはいかない",
  ["Act_E2_1A_MaxRoom_Scarf_Look01_Max_010"] = "またパパと一緒にホッケーの試合を見に行きたいな",
  ["Act_E2_1A_MaxRoom_Search_Interact01_Max_010"] = "本はここじゃない…",
  ["Act_E2_1A_MaxRoom_Search_Interact04_Max_010"] = "何もなし",
  ["Act_E2_1A_MaxRoom_Search_Interact05_Max_010"] = "片付けるって約束する。 本を見つけたらね",
  ["Act_E2_1A_MaxRoom_Search_Interact06_Max_010"] = "あーもう ケイトの本がジュースまみれ",
  ["Act_E2_1A_MaxRoom_ShowelGel_Interact01_Max_020"] = "よし シャワーに行こう!",
  ["Act_E2_1A_MaxRoom_ShowelGel_Look01_Max_010"] = "誰かが女子のシャンプーにイタズラして髪が抜け落ちる事件があったから |シャワー用品は厳重に管理しないと…",
  ["Act_E2_1A_MaxRoom_VictoriaPhoto_Look01_Max_010"] = "確かに爆笑ものだけど… ビクトリアとやってること変わらないな",
  ["Act_E2_1A_MaxRoom_VoiceOverReveal_Max_010"] = "徹夜したせいでクタクタ… |時間を巻き戻せばもう少し調べることもできるけど |体力を温存したほうがいいよね…",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_010"] = "ほら 頭を使って! 考えろ!",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_020"] = "ブラッドベリさん隠れないで… 愛してるの",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_030"] = "記憶も巻き戻すことができればな…",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_040"] = "さて本をどこに置いたっけ? どこ?",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_010"] = "マックス!",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_040"] = "うん なんとか。 昨日はありがとうね。 おかげで助かったよ",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_060"] = "あの人だけじゃないよ",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_070"] = "マックス!",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_100"] = "そう 何もしてくれなかったよね。 他のみんなと同じなんだ…",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_120"] = "もういいよ。 今さら…",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_130"] = "ところで 「10 月はたそがれの国 」 貸してたよね?",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_150"] = "あとで部屋まで持ってきてくれる? 授業のために必要なんだ",
  ["Cue_E2_1A_Bathroom_DialKate_Max_020"] = "ケイト",
  ["Cue_E2_1A_Bathroom_DialKate_Max_030"] = "元気?",
  ["Cue_E2_1A_Bathroom_DialKate_Max_050"] = "もちろん。 あいつ ひどいよね",
  ["Cue_E2_1A_Bathroom_DialKate_Max_080"] = "あっ… ケ… ケイト",
  ["Cue_E2_1A_Bathroom_DialKate_Max_090"] = "昨日はごめん",
  ["Cue_E2_1A_Bathroom_DialKate_Max_110"] = "違うよ。 助けたかった。 でも… えっと…",
  ["Cue_E2_1A_Bathroom_DialKate_Max_140"] = "うん。 読んだよ。 すごく面白い。 ブラッドベリは 詩人でもあるよね",
  ["Cue_E2_1A_Bathroom_DialKate_Max_160"] = "もちろん。 あとで届ける",
  ["Cue_E2_1A_Bathroom_FaucetWater_Girl_010"] = "ちょっと! 水!",
  ["Cue_E2_1A_Bathroom_FaucetWater_Max_020"] = "ごめん 忘れてた!",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_020"] = "べつに",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_050"] = "だから あれは違うの…",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_080"] = "いつか後悔するわよ",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_030"] = "へえ そう?",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_060"] = "よく言うわね",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_100"] = "ほんと",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_120"] = "間違いないね",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_140"] = "あいつ ホント最低",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_160"] = "あのカメラ ダッサいしね",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_180"] = "ウケるんだけど! マジ最高!",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_200"] = "急いだんだけど…",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_010"] = "何してるの?",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_040"] = "動画見たけど お楽しみだったみたいね…",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_070"] = "照れないの。 ホントはあんなに大胆なんだから…",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_090"] = "あらら 後悔してるのはあなたでしょ? 自業自得よ",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_110"] = "きっとネイサンから 特別なヤツをもらったんでしょ",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_130"] = "ウソ まだ顔にペンキが付いてる |マックスのやつ 写真まで撮りやがって |思い知らせてやらなきゃ",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_150"] = "私がコンテストで優勝するのを妬んでんのよ |マーク… じゃない ジェファソン先生はマックスなんて眼中にないわ",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_170"] = "私 嫌い。 あの「自分は違うの」みたいな態度 |さて みんなのために動画のリンクを残してあげなくちゃ",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_190"] = "ウソ まだ顔にペンキが付いてる |誰かさんたちがもっと早くタオルを持ってくれば…",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_210"] = "いいわ テイラー |もう あなたたちには何も頼まないから |ケイトと友だちになれば? それともマックス?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_001"] = "マックス これで 2 回もモノが当たるのを防いでくれた。 私の守護霊なの?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_004"] = "さっきはすごかったよ",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_007"] = "この学校は嫌なやつばっかり",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_009"] = "ホント ウォーレンと趣味合うんだね |気をつけないと ブルックに嫉妬されるよ…",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_010"] = "そういえば ウォーレンから映画コレクションを借りたんだって? |マックスも同じ SF オタクだったとはね |好きな作品は?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_011"] = "80 年代の学校に戻れたら どうなるんだろう",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_013"] = "未来ならまだしも 過去に戻るのは絶対イヤ",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_003"] = "おはよう アリッサ",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_005"] = "第六感ってやつだよ。 役に立ってよかった",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_006"] = "私の超能力もまんざらでもないみたいだね",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_014"] = "定番だけど 「バック・トゥ・ザ・フューチャー」かな",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_015"] = "過去に戻って失敗をやり直せる「恋はデジャ・ブ」が好き",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_016"] = "「ルーパー」がすごい面白かった |難解すぎて いまだによく分かってないんだけどね…",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_018"] = "ヘアスプレーで窒息するかも",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_020"] = "そうだね。 でも大事なのは「今」何するかだよ",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_021"] = "さて 私には何の話だかさっぱり",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase02_Alyssa_002"] = "ガキばっかり… ごめん 今あんまり話する気分じゃなくて",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase02_Max_001"] = "大丈夫 アリッサ?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Quick01_Alyssa_001"] = "またあとで話そう。 ウォーレンとうまくやりなよ!",
  ["Cue_E2_1A_Corridor_CHAlyssa_Quick01_Alyssa_002"] = "マックス 話す気分じゃないんだ",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_002"] = "ああ マックス",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_008"] = "うん 今は雪のことで頭が混乱中",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_009"] = "気象学者にも説明できないくらいだからね |ウォーレンなら分かるかも。 彼とは話した?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_015"] = "だよね。 ウォーレンは私と気象学について話すのが好きなの |他に話が合う人 いないしね。 じゃ またあとで",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_016"] = "そっか。 きっと彼から連絡してくるよ。 またね",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_001"] = "ブルック",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_003"] = "昨日の季節外れの雪 見た?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_004"] = "ボーッとしてるけど 大丈夫?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_005"] = "ブルックでもそうなんだ… |私 科学はさっぱりだから どういうことか教えてほしくて…",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_013"] = "ううん。 こんな朝早くから話す用事もないし",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_014"] = "そのうちね",
  ["Cue_E2_1A_Corridor_CHBrooke_Quick02_Brooke_001"] = "今忙しいんだ。 またあとでね",
  ["Cue_E2_1A_Corridor_CHBrooke_Quick02_Brooke_002"] = "なんなの?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_001"] = "マックス ケイトの動画はもうチェックした?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_004"] = "カメラの前で酔いつぶれたケイトが悪いんじゃん",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_005"] = "面白いのに - 「教会娘ご乱心」",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_007"] = "動画を見る限り そういう子としか思えないけど",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_009"] = "痛いところをつかれたな。 昨日は真相を教えてくれてありがとね",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_013"] = "特に何も… どうやって仕返しするか 考え中",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_014"] = "まだ。 埋め合わせが済んだらね",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_015"] = "まさか。 取り乱した自分が 恥ずかしいくらいだよ",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_017"] = "マックスは優しいね… もうケイトの動画は見ないし 人にも教えないよ",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_019"] = "うん。 またね",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_002"] = "悪趣味だよ",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_003"] = "見たくない",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_006"] = "ケイトはそういう子じゃない",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_008"] = "見たらなんでも信じるの? ザックとデーナの件みたいに?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_010"] = "黒幕のビクトリアにはなんて?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_011"] = "ホント? てっきる怒ってるかと…",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_012"] = "ザックは? 許してあげた?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_016"] = "ジュリエットらしいね",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_018"] = "そうしてくれるといいな。 ありがと",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_020"] = "ジュリエット",
  ["Cue_E2_1A_Corridor_CHJuliet_Quick01_Juliet_001"] = "動画は見てないよ",
  ["Cue_E2_1A_Corridor_CHJuliet_Quick01_Juliet_002"] = "ごめん 今ザックにメール中",
  ["Cue_E2_1A_Corridor_CourtneyHomework_Courtney_020"] = "大丈夫よ ビクトリア |テストと宿題は午後までにちゃんと持ってくるから |まかせておいて",
  ["Cue_E2_1A_Corridor_CourtneyHomework_Victoria_010"] = "コートニー 遅くとも今晩までには持ってきてよ |頼んだからね ちゃんとしてよ",
  ["Cue_E2_1A_Corridor_KateVideo_Brooke_020"] = "ケイトはこんな子じゃないと思ったけど… 男子とイチャイチャするなんて",
  ["Cue_E2_1A_Corridor_KateVideo_Brooke_040"] = "もう みんな見てるよ",
  ["Cue_E2_1A_Corridor_KateVideo_Juliet_010"] = "ボルテックス・クラブってほんとクズの集まり。 ケンカしてよかった",
  ["Cue_E2_1A_Corridor_KateVideo_Juliet_030"] = "見ないほうがいいね…",
  ["Cue_E2_1A_Corridor_Knock02_Kate_020"] = "うん。 入って マックス…",
  ["Cue_E2_1A_Corridor_Knock02_Max_010"] = "ケイト いる?",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Alyssa_020"] = "いいけど。 マックスがそう言うなら…",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Alyssa_030"] = "危機一髪だったよ。 ありがとう マックス",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Max_010"] = "アリッサ ちょっとこっち",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_002"] = "別に嫌いじゃないよ。 私だってうわさ話好きだしね… ただ少しおせっかいだよ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_005"] = "長所かもよ。 おせっかいの天才だもん",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_009"] = "うん 2 人揃ってパーティに行ける… だからマックスもどう? |服を貸してあげるから ウォーレンと一緒にキュートなオタクカップルで…",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_021"] = "ところで 今日はすごいことがあったんだ |トレバーがハロウィン・パーティに誘ってくれた!",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_036"] = "昨日よりかずっとね。 話せてよかったよ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_037"] = "うん。 何度も言うけど 助けてくれてありがとう",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_041"] = "なんか不思議。 マックスは最初から全部知ってたみたい…",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_042"] = "笑っちゃうね。 でも 昨日助けてくれたこともあるし これでおあいこ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_052"] = "人生を無駄にしちゃだめだって。 ね? 絶対に参加するべきだよ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_056"] = "そうこなくっちゃ! これが終わったら次はレイブよ…",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_057"] = "少しは外に目を向けないと カラは破れないよ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_001"] = "えっと デーナ。 私のこと嫌いになった?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_003"] = "私の致命的な短所かも",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_007"] = "ホント? 別に言いたくなければいいんだけど…",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_022"] = "やったね デーナ",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_034"] = "デーナ 調子はどう?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_035"] = "デーナ 元気? ジュリエットとは仲直りできた?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_038"] = "だって心配だから",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_039"] = "私も。 話すと気が楽になるよね… ああいうのって",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_044"] = "コスプレは得意じゃなくて",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_049"] = "ベロベロの男子にゲロかけられるくらいなら カラにこもってたいよ… |でも ありがとう",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_053"] = "行くよ。 イヤになったら戻ればいいんだし… 部屋に",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_054"] = "ごめん。 やっぱりやめておく",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_055"] = "なんか楽しそう。 今後のパーティ計画を練るのも悪くないかも…",
  ["Cue_E2_1A_DanaRoom_CHDana_Quick01_Dana_001"] = "またあとでね",
  ["Cue_E2_1A_KateRoom_Believe_Kate_020"] = "ありがとう マックス 警察に話してみる… |ウェルズ校長にも |マックスが証人になれば きっと対応してくれるはず",
  ["Cue_E2_1A_KateRoom_Believe_Kate_040"] = "なんで? 何に対して?",
  ["Cue_E2_1A_KateRoom_Believe_Max_010"] = "うん 絶対に警察に行くべき。 私はケイトの言葉を全部信じるから |ネイサンは本当にヤバいよ",
  ["Cue_E2_1A_KateRoom_Believe_Max_030"] = "証人? うーん ケイトのことは信じてるけど… |警察や学校からしたら 私たちは世間知らずのお子様だし… |もっと慎重になったほうがいいと思う…",
  ["Cue_E2_1A_KateRoom_Believe_Max_050"] = "ほら… プレスコット家は影響力があるから 裏目に出たらマズイと思って |もちろんネイサンは報いを受けるべきだし… |許せないけど…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_001"] = "マックス なぜ昨日デイビッドから助けてくれたの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_002"] = "ねえ… なんで昨日デイビッドに絡まれていたとき 何もしてくれなかったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_008"] = "あんな人だとは知らなくて… でも マックスが来てくれてよかった",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_009"] = "マックスを巻き込みたいわけじゃない。 でもみんな冷たくて…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_010"] = "あんな人だと思わなかった。 でも マックスは心配してくれてたんだね",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_011"] = "関係ないふりもできたでしょ |どうせ みんな自分のことしか考えてないじゃん…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_013"] = "その…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_014"] = "勘違いされてるの。 私がボルテックス・クラブのメンバーだと思い込んでる",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_018"] = "私だって見れないよ…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_019"] = "魔が差して ボルテックス・クラブのパーティに行ったの。 完全に場違いだった",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_020"] = "動画を見たからでしょ",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_023"] = "ありがとう",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_024"] = "冗談でしょ?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_025"] = "もう 誰とも顔を合わせたくないよ",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_033"] = "ボルテックス・クラブのパーティに行ったら いつの間にか大勢とキスしてた… |でもその間の記憶がないの…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_037"] = "なんでだろ? ただ 新しい出会いがあったらいいなって",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_038"] = "してない",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_039"] = "長い話だよ。 自分でも整理がついてないし…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_041"] = "神に誓って 赤ワインを1 口だけ。 あとはお水",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_044"] = "1 口だよ。 ありえない",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_045"] = "教会でもワインを飲むけど あんな風になったことなんてないから",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_048"] = "確かに… 吐き気とめまいがしたのは覚えてる",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_049"] = "ネイサンが病院に連れていくって言って…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_054"] = "いつもと違って優しい感じだったの",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_055"] = "ううん。 少なくとも病院には行ってない…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_056"] = "最悪だったよ。 病院に行かないと死ぬかと思った",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_061"] = "とにかく 長い間 車に乗ってた… |目が覚めたらどこかの部屋で… |白くて明るかったから 病院だと思って…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_065"] = "覚えてるのはそれだけ! 後は分からない… |起きたら部屋の前で… |体にアザとかはなかったけど すごく気分が悪かった",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_066"] = "もちろんよ。 それとも何? 私がデタラメを言ってると思うの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_069"] = "知らないよ。 ビクトリアかも。 そこにいたし やりかねないし",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_071"] = "どうやったら動画を消せる? もう拡散してるけど… |教会に見られたらどうしよう。 どうしたらいいの…?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_077"] = "誰かが優しく私に話しかけてきて… 最初は医者かと思った… |そしたらネイサンの声がして 首筋に針が刺さるのを感じて… |それで…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_003"] = "うん その後は?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_004"] = "弱い者いじめは嫌いだから。 デイビッドはおかしいよ",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_005"] = "ごめん 怖かったんだ。 意気地なしだよね",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_006"] = "まずは証拠を集めようと思って…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_007"] = "ああするしかなくて。 デイビッドはおかしいよ",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_012"] = "私はケイトの味方だよ。 で デイビッドとは何があったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_015"] = "動画の件は? ちなみに 私は見てないからね",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_016"] = "パーティに参加したの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_017"] = "どうしてだろう?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_021"] = "私も見ない",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_022"] = "見たほうがいい? 参考のために…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_026"] = "つらいとは思うけど 動画のことを話してくれたら助けになれるかも…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_034"] = "そもそも… なんで行ったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_035"] = "ケイトらしくないよ。 ビクトリアとパーティなんて…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_036"] = "ひどい… でも なぜそんなことに?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_040"] = "それだけじゃわからないよ。 パーティで何があったの? お酒は?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_042"] = "酔っぱらうほどじゃないよね?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_043"] = "本当に 1 口だけ?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_046"] = "クスリを飲まされたとか?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_047"] = "それで…?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_050"] = "ネイサン・プレスコット!?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_052"] = "そんなに気分悪かったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_053"] = "行ったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_058"] = "想像すらできないよ。 それで?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_059"] = "結局 ネイサンは病院まで送ってくれたの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_060"] = "他に何か思い出せない?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_063"] = "それで?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_067"] = "そうじゃなくて… ただ 確認しておきたかっただけ。 その後は?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_068"] = "パーティの動画は? 誰が撮ったの?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_070"] = "辛かったね ケイト… でも これは大変な事件だよ",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_072"] = "一緒に考えよう。 またあとで連絡するから。 ね?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_076"] = "確かなの?",
  ["Cue_E2_1A_KateRoom_DialKate_Kate_020"] = "ありがとう… 本はかばんのところに置いといて",
  ["Cue_E2_1A_KateRoom_DialKate_Max_010"] = "ケイト 本を持ってきたよ…",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_020"] = "でもあれはクスリで…",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_040"] = "もう絶望的ってこと…?",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_060"] = "つまり どうしようもない。 それが答えなの?",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_080"] = "じゃあ何? |それまでは みんなにビッチ呼ばわりされてればいいの? |もういいよ…",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_010"] = "警察に行っても 信じてもらえないよ |多分 動画の内容からして 主張は受け入れてもらえないと思う",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_030"] = "それを証明しなきゃならないの |警察や学校は動画を見てどう思う? |ケイトが不利になるだけだよ…",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_050"] = "違うよ。 ただ これ以上ケイトに傷ついてほしくないだけ…",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_070"] = "待つべきだと思う。 別の方法があるかもしれないし",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_010"] = "マックス 1 つ聞いてもいい? 正直に答えて",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_030"] = "ネイサンに介抱されたのか… ひどいことされたのか 確かめたいの",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_050"] = "警察に行くべき?",
  ["Cue_E2_1A_KateRoom_KateBook_Max_020"] = "うん もちろん。 なに?",
  ["Cue_E2_1A_KateRoom_KateBook_Stella_010"] = "音楽消してよ! 寝てるんだけど!",
  ["Cue_E2_1A_KateRoom_KateBook_Stella_020"] = "うるさい! 寝させてよ!",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_010"] = "ちょっと 何これ!",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_020"] = "ブラックウェルまできて なんでこんな目に… これ 私が片付けるの?",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_030"] = "その前に ケイトの本か…",
  ["Act_E2_1B_CampusB_Birds_Look01_Max_010"] = "サミュエルの周りに鳥が集まっている…",
  ["Act_E2_1B_CampusB_BrokenWindow_Look01_Max_010"] = "窓が割れたままだ |アリッサにボールのことを警告したから… |ささいな行動が窓の運命を変えてしまった…",
  ["Act_E2_1B_CampusB_CHSamuel_Look01_Max_010"] = "あ サミュエルだ。 朝早くから 動物たちと語り合ってる…",
  ["Act_E2_1B_CampusB_CHSquirrel_VoiceOver_Max_010"] = "ベンチの近くにいると リスが警戒しちゃうかも",
  ["Act_E2_1B_CampusB_CHTaylor_Look01_Max_010"] = "ビクトリアたちと一緒じゃないテイラーって初めて見るかも",
  ["Act_E2_1B_CampusB_CHTaylor_Look02_Max_020"] = "悪い話し合いじゃなかった。 平和への一歩だ",
  ["Act_E2_1B_CampusB_CHWarren_Look01_Max_010"] = "ウォーレンも もう寮から出てきてる。 誰かを探してるみたいだけど…",
  ["Act_E2_1B_CampusB_CHWarren_Look02_Max_020"] = "ホント面白いヤツ。ウォーレンが味方でよかった",
  ["Act_E2_1B_CampusB_FootBall_Look01_Max_010"] = "校内に「フットボール禁止ゾーン」を作ってくれたらいいのに",
  ["Act_E2_1B_CampusB_MPA04_Look01_Max_010"] = "レイチェルが心配なのはわかるけど… 普通ビラまで持ってる?",
  ["Act_E2_1B_CampusB_Object01_Look01_Max_010"] = "サミュエルはサングラスなんてかけないし… なんでこんなものが?",
  ["Act_E2_1B_CampusB_Pipe_Look01_Max_010"] = "このレバーをいじるのは もうやめておこう…",
  ["Act_E2_1B_CampusB_Plaque_Look01_Max_010"] = "「プレスコット寮」だって。 この寮までネイサンの家の持ち物ってわけ?",
  ["Act_E2_1B_CampusB_RachelPhotos_Look01_Max_010"] = "なんでサミュエルがレイチェルの写真を持ってるの?",
  ["Act_E2_1B_CampusB_Scaffolding_Look01_Max_010"] = "すごくキレイに塗られてる。 サミュエルってセンスがあるんだね",
  ["Act_E2_1B_CampusB_Squirrel_Interact01_Max_010"] = "やった! ピューリッツァー賞はいただきだね",
  ["Act_E2_1B_CampusB_Squirrel_Look01_Max_010"] = "すごい… リスがこんなに近くまで来るなんて…",
  ["Act_E2_1B_CampusB_Tools_Look01_Max_010"] = "サミュエルったら カギをかけとかないと不用心だよ |これじゃすぐに忍び込めちゃう…",
  ["Act_E2_1B_CampusB_Totem_Look01_Max_010"] = "あのトーテムは「トバンガ」っていうらしい。 前にウォーレンがそう言ってた",
  ["Act_E2_1B_CampusB_TrashFood_Interact01_Max_010"] = "いい物があった! ほら リスさんおいで｡ 写真を撮ってあげるよ…",
  ["Act_E2_1B_CampusB_TrashFood_Look01_Max_010"] = "生ゴミの分別くらいすればいいのに |でもこれで リスをおびき寄せられるかも…",
  ["Act_E2_1B_CampusB_VoiceOver01_VoiceOver_Max_010"] = "早くメインキャンパスへ行って バスに乗らなきゃ |クロエがダイナーで待ってる",
  ["Act_E2_1B_CampusB_VoiceOver02_VoiceOver_Max_020"] = "早くメインキャンパスへ行って ダイナー行きのバスに乗らなきゃ |クロエが待ってる",
  ["Act_E2_1B_CampusB_VoiceOver03_VoiceOver_Max_030"] = "早朝のブラックウェルは ほんとに静かだ…",
  ["Act_E2_1B_CampusB_VoiceOver04_VoiceOver_Max_040"] = "キャンパスにいると 作品のイメージがどんどんわいてくる…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_001"] = "サミュエル 早起きですね",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_003"] = "それが この町の大好きなところです |森にいる たくさんの動物たち…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_007"] = "実は… 牝鹿を見たんです |私のことをじっと見ていて… まるで何かを訴えるように…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_015"] = "よくいる普通の動物です",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_017"] = "昨日の季節外れの雪のことはどう思います?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_021"] = "詮索してごめんなさい |でも… なぜ物置にレイチェルの写真があるんですか? |彼女のこと知りたくて…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_025"] = "知り合いなんですか?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_027"] = "警察に話したんですね。 レイチェルはモデルになりたかったみたいで…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_028"] = "レイチェルのことを心配して 探してる人たちがいるんです",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_030"] = "でも あなたは彼女の写真を持っている…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_034"] = "大切な朝のひとときを邪魔したくないので… またあとで",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_040"] = "サミュエル",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_042"] = "知り合いだったんですか?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_043"] = "レイチェルのことを心配して 探してる人たちがいるんです",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_002"] = "ああ おはよう マックス |早朝が好きなんだ。 穏やかで静かで… |動物たちも一緒に目を覚ます",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_004"] = "リスは毎朝来るんだよ… 餌を探しに |ささやきが聞こえるんだ… |森ではどんな動物を見たんだい?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_008"] = "それは君の守護動物だよ! マックスは自分のと出会えたんだ |運命の予兆かもしれないね… 説得力ないか |僕の守護動物はリスだしね",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_016"] = "それだけじゃなさそうだね",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_020"] = "地球からの警告だよ。 でも 正直言って 僕は今まであんなの見たことない",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_022"] = "と言いつつ 詮索は続けるのかい。 みんな彼女に興味津々だ",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_026"] = "警察にも言ったけど レイチェルはいい子だった。 彼女が写真をくれたんだよ",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_029"] = "見つかるかな。 いくら心配しても 解けない謎はあるのさ",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_031"] = "ああ。 レイチェルは宣材写真をばらまいていたから |マックス 詮索を続けなさい |時間は君の味方だよ…",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_035"] = "いつでもおいで",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_041"] = "やあ マックス",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase02_Samuel_001"] = "じゃあね マックス… 動物の声に耳を傾けるんだよ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_001"] = "テイラー…",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_004"] = "私はテイラーともビクトリアとも ケンカするつもりはないんだけどな |いっぺん普通に話そうよ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_006"] = "ケイトの動画 ひどいと思わない? 彼女 すごい苦しんでるよ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_008"] = "なんでビクトリアと一緒にいるの? あなたたちにも意地悪なのに",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_010"] = "そういえば 私にもそういう友だちいたっけな… ママは認めてくれなかったけど",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_012"] = "やっぱりなんでもない",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_014"] = "お母さんが病気だって聞いたよ。心配だよね… 何があったの?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_016"] = "知ってる。 だから話したかったの",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_027"] = "えーと ごめんなさい?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_002"] = "何話しかけてんの? 昨日ビクトリアをバカにしたくせに",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_003"] = "何よ? ビクトリアに優しくしたからって 私は馴れ合う気はないから",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_005"] = "ヘンな子。 まあ… ちょうどひまだったし… いいわよ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_007"] = "それで? いい子ぶって 実はビッチだったんだから。 自業自得よ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_009"] = "だから何? あんたに何が分かるっての? 彼女は最高の友だちよ",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_011"] = "口うるさくても 健康なら… 私のママなんて… はい やっぱ今のなし",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_013"] = "話せてよかった… でも調子に乗んないで。 もう一人にして",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_015"] = "ふん… 背中の手術よ |ビクトリアがそばにいてくれた |今のあんたとケイトみたいに |あたしだって人を傷つけたいわけじゃない",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_017"] = "そう… よかった",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_028"] = "まったくね。 じゃあ さっさと どっか行ってくれる?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase02_Max_001"] = "テイラー",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase02_Taylor_002"] = "話はおしまい",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase03_Max_001"] = "テイラー",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase03_Taylor_002"] = "案外楽しかったかも。 また話そうよ。 じゃあね",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_002"] = "ウォーレン 何してるの?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_005"] = "そういえば あの時はありがとう。 超カッコよかった。 そのうちお礼するから",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_007"] = "ヤバかったよね。 私も何が何だか… そのうちお礼するね",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_009"] = "ウォーレンはまさに「日常ヒーロー」だよ。 あいつに立ち向かったんだもん",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_010"] = "幼なじみのクロエ・プライス。 すごく久しぶりに会ったんだ",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_015"] = "ただの昔の知り合い",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_018"] = "昨日 トイレでネイサンが銃を持ってるのを見たの |怖くて校長先生には話せなかったけど |このことは誰にも言わないで。 今度ちゃんと話すから",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_022"] = "昨日 トイレでネイサンが銃を持ってるのを見たの |今度ちゃんと話すけど… 校長先生が対応してくれるはず",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_028"] = "あいつは危ないから 関わらないほうがいい |私は もう大丈夫だから |どうせネイサンには そのうちバチが当たるよ",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_036"] = "うん 気晴らしにはちょうどいいかもね。 レトロも猿も 大好きだし",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_040"] = "やめとく。 今 観ても楽しめそうにないし… むしろ逃げ出したい気分…",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_001"] = "あー別に… 電話を… 待ってるんだ |てか電話はもう出たんだけど… |まあ そんなことより 昨日は大変だったね",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_006"] = "ああ 期待しとくよ。 ボコられた甲斐もあるってもんだね |ヒーローにでもなろうかな",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_016"] = "彼女がさっそうと車で現れたときは ほっとしたんじゃない? |それはそうと… なんでネイサンに絡まれてたんだ?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_031"] = "昨日の雪といい 最近はまるでディストピアだ |そうだ 例のドライブイン・シアターで「猿の惑星」シリーズ一挙上映だって |行こうよ!",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_037"] = "てっきり断られるかと… 詳細は またメールするよ!",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_041"] = "しょうがないな。この汚らわしい人間め!",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_044"] = "でも君は俺を残して 女の子と逃げたよな… |いかにもパンクっぽい子だったけど 知り合い?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase02_Warren_001"] = "ブルックには やっぱり君と映画に行くって言うよ。 またメールする",
  ["Cue_E2_1B_CampusB_CHWarren_Phase03_Warren_001"] = "あーでもブルックも行きたがるかも。 聞いてからにするよ",
  ["Cue_E2_1B_CampusB_MeetWarren_IGE_Max_010"] = "ウォーレン 何してるの?",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_010"] = "マックス 見てみろよ!",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_020"] = "マックス こっち来いよ!",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_030"] = "マックス ちょっと来いよ!",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_040"] = "よお マックス。 元気か?",
  ["Act_E2_1C_CampusA_VoiceOver01_Max_010"] = "ああ これで誰ともしゃべらなくていい。 音楽にひたってぼんやりしよう…",
  ["Act_E2_1C_CampusA_VoiceOver02_Max_010"] = "デイビッドとネイサンが話してるってことは… |きっとケイトのことかな… それともレイチェル?",
  ["Act_E2_2A_Diner_AfterFrank_VoiceOver01_Max_010"] = "あの人も犬も なんだか気味悪い…",
  ["Act_E2_2A_Diner_CHCop_Look01_Max_010"] = "警官気取りのデイビッド・マドセンより ずっとまともそう…",
  ["Act_E2_2A_Diner_CHDinerFemale01_Look01_Max_010"] = "なんかイライラしてるのかな",
  ["Act_E2_2A_Diner_CHDinerFemale02_Look01_Max_010"] = "1 人で食事してると いろいろ考えちゃうよね",
  ["Act_E2_2A_Diner_CHDinerMale01_Look01_Max_010"] = "うわ… なんかヤバそうな人…",
  ["Act_E2_2A_Diner_CHDinerMale02_Look01_Max_010"] = "この人はいろんな時代のアルカディアを知ってるんだろうな…",
  ["Act_E2_2A_Diner_CHFisherman01_Look01_Max_010"] = "いかにもアルカディア・ベイによくいる無愛想な漁師って感じ…",
  ["Act_E2_2A_Diner_CHFisherman02_Look01_Max_010"] = "漁師って ホントに無口なんだね…",
  ["Act_E2_2A_Diner_CHHomeless_Look01_Max_010"] = "かわいそうに… 保護施設はないのかな",
  ["Act_E2_2A_Diner_CHHomeless_Look02_Max_010"] = "この人なら町がどんなふうに変わったか知ってるだろうな… 町の秘密も…",
  ["Act_E2_2A_Diner_CHJustin_Look01_Max_010"] = "ジャスティンって いつもダルそう",
  ["Act_E2_2A_Diner_CHNewsPaperMan_Look01_Max_010"] = "新聞も そのうち時代遅れになりそう…",
  ["Act_E2_2A_Diner_CHTrevor_Look01_Max_010"] = "デーナに負けないくらい幸せそうだ…",
  ["Act_E2_2A_Diner_CHTrucker01_Look01_Max_010"] = "トラックであちこち旅する暮らしって ロマンチックだな…",
  ["Act_E2_2A_Diner_CHTrucker02_Look01_Max_010"] = "私には運転手なんて絶対ムリ。 あんな大きなトラック乗れないよ",
  ["Act_E2_2A_Diner_Carving_Look01_Max_010"] = "笑える落書き。 ウォーレンが来たんだ",
  ["Act_E2_2A_Diner_ChloeStuff_Look01_Max_010"] = "よし 一個ずつよく見て クロエの持ち物を覚えなきゃ",
  ["Act_E2_2A_Diner_Coffee_Interact01_Max_010"] = "すべてがデジャブみたいに感じる… これは「過去」それとも「今」?",
  ["Act_E2_2A_Diner_Coffee_Look01_Max_010"] = "やっぱコーヒーはブラックじゃなきゃ",
  ["Act_E2_2A_Diner_CounterFood_Look01_Max_010"] = "ああ… どれも美味しそう",
  ["Act_E2_2A_Diner_DinerMenu_Look01_Max_010"] = "メニューも値段以外は昔から変わってない…",
  ["Act_E2_2A_Diner_DinerSign_Look01_Max_010"] = "昔はクロエも一緒に 家族みんなで食事したな… あの頃は楽しかった",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_010"] = "心の中でシャッターを切って 全部覚えよう",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_020"] = "一つ一つ 写真みたいに記憶するんだ",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_030"] = "バッチリ覚えた。 時間を戻してクロエを驚かせよう!",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_040"] = "全部覚えたら時間を巻き戻して クロエを納得させなきゃ",
  ["Act_E2_2A_Diner_FishermanPetitionStand_Look01_Max_010"] = "ビラがたくさんある… 誰も読まないのが悲しいね…",
  ["Act_E2_2A_Diner_FishingWallOfFame01_Look01_Max_010"] = "「漁師たちの栄光の壁」だ…",
  ["Act_E2_2A_Diner_Flyer01_Look01_Max_010"] = "クロエを誘ってみようかな",
  ["Act_E2_2A_Diner_Flyer02_Look01_Max_010"] = "よくこんなことできるなあ",
  ["Act_E2_2A_Diner_Flyer03_Look01_Max_010"] = "どう見ても つまんなそう",
  ["Act_E2_2A_Diner_FrankRVWindow_Look01_Max_010"] = "私の助言なんて誰もきかない",
  ["Act_E2_2A_Diner_FrankRV_Look01_Max_010"] = "こないだの汚い RV 車がある…",
  ["Act_E2_2A_Diner_Graffiti01_Look01_Max_010"] = "この落書きも昔からあるな…",
  ["Act_E2_2A_Diner_Graffiti03_Look01_Max_010"] = "キモい",
  ["Act_E2_2A_Diner_Graffiti05_Look01_Max_010"] = "田舎の詩人って感じ",
  ["Act_E2_2A_Diner_GumballStand_Look01_Max_010"] = "うわっ ヤダ… このガム 5 年前からずっとここにあるんじゃない?",
  ["Act_E2_2A_Diner_Jukebox_Interact01_Max_010"] = "シックスティーズ? 店の雰囲気にはピッタリだけど 勘弁してって感じ",
  ["Act_E2_2A_Diner_KateChoicePhone_VoiceOver01_Max_010"] = "私のせいで クロエとおばさん ケンカしてたな…",
  ["Act_E2_2A_Diner_KateChoicePhone_VoiceOver02_Max_020"] = "ケイト 電話に出なくて怒ってるかも…",
  ["Act_E2_2A_Diner_MaxFood_VoiceOver01_Max_010"] = "美味しい朝食を待つ気分ってサイコー",
  ["Act_E2_2A_Diner_MiscObject01_Look01_Max_010"] = "欲しいんだけど 観光客っぽいよね…",
  ["Act_E2_2A_Diner_MiscObject02_Look01_Max_020"] = "これって ケン・キージーとおばさん? うわ すごい",
  ["Act_E2_2A_Diner_NewsPaperBox_Interact01_Max_010"] = "「雪」か… そう書かれると読みたくなるよね…",
  ["Act_E2_2A_Diner_NewsPaperBox_Look01_Max_010"] = "あの雪の原因が載ってるかな…",
  ["Act_E2_2A_Diner_OffBus_VoiceOver01_Max_010"] = "時間を巻き戻さなくても… このダイナーは昔のまんまだ",
  ["Act_E2_2A_Diner_PostCardRack_Look01_Max_010"] = "このポストカードからは町の異常さはわからない",
  ["Act_E2_2A_Diner_Poster01_Look01_Max_010"] = "銃を持った生徒がいることについては言及なし",
  ["Act_E2_2A_Diner_Poster02_Look01_Max_010"] = "パレードなんてすごく懐かしい… クロエと一緒に よく見たな…",
  ["Act_E2_2A_Diner_Poster03_Look01_Max_010"] = "何これ。 世界の終わりって感じ…",
  ["Act_E2_2A_Diner_Predilection_VoiceOver01_Max_020"] = "よし 巻き戻して 今起きたことをクロエに話そう",
  ["Act_E2_2A_Diner_ProvedPower_VoiceOver01_Max_010"] = "やっと信じてくれた… でも クロエったら 次は何を企んでるのかな",
  ["Act_E2_2A_Diner_PuzzleDivination01_VoiceOver01_Max_010"] = "クロエの持ち物をしっかり覚えておかなくちゃ",
  ["Act_E2_2A_Diner_PuzzleDivination02_VoiceOver01_Max_010"] = "これから店の中で起きることを全部覚えておかなくちゃ |クロエをびっくりさせてやるんだ…",
  ["Act_E2_2A_Diner_RecallMemories_VoiceOver01_Max_010"] = "美味しい朝食の匂いと フォークやナイフのカチャカチャいう音… |13 歳のころに戻ったみたい",
  ["Act_E2_2A_Diner_WhalesPictures_Look01_Max_010"] = "家族でホエール・ウォッチングって行ったことないな。 すごく楽しそう",
  ["Act_E2_2A_Diner_Window_Look01_Max_010"] = "いつ見ても不思議な灯台… このまま時が止まればいいのに… |今なら巻き戻すことはできるけど… 時間を止めることはできない…",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_021"] = "まあね。 もうバスは来たのかしら? ネットの時刻表が使えないの",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_024"] = "仕事の面接に遅れたくないの |それにしたって バスでニューポートまで行かなきゃ仕事探しもできないのよ",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_025"] = "ああ ホッとしたわ。 この面接には遅れたくないの |バスでニューポートまで行かなきゃ 再就職の口もないなんてね",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_027"] = "いいように見える? ここじゃ家賃も稼げないわ",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_029"] = "ありがと 頑張るわ",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_022"] = "どうかな… いつもはすぐ来るんですけど",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_023"] = "私はスクールバスで来たばかりですけど 路線バスも停まるはずですよ",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_026"] = "景気 悪いんですか?",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_028"] = "うまくいくといいですね",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_030"] = "あの… 何か困ってます?",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase02_AdultFem_001"] = "バスが来ることを祈りながら待ち続けるわ",
  ["Cue_E2_2A_DinerPark_CHAdultMal02_Phase01_AdultMal02_001"] = "しゃべってるヒマはねえ。 俺は億万長者だぞ |この宝くじが見えねえか。 バスが来たら 換金しに行くんだよ",
  ["Cue_E2_2A_DinerPark_CHAdultMal02_Phase02_AdultMal02_001"] = "この宝くじはやらないぞ。 自分で買え",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_001"] = "見たかい これ! |世界各地で紛争中なのに 新聞の一面は「雪」だぞ |きっと来週は「雲」だな",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_004"] = "地球温暖化説か? アホくさい… ここは北西部だ。 雪くらい降る",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_005"] = "それなりにね。 だが もうこの町もゴーストタウン一歩手前だ",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_006"] = "それ以外には 行方不明者のネタしかないからな",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_010"] = "だったかな。 きっと この町に飽きて出てっただけだ。 無理もないさ",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_011"] = "君は若い。 すぐ忘れるよ",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_002"] = "でも 雪だって十分ニュースですよ… 空も晴れてたのに",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_003"] = "この町は長いんですか?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_007"] = "新聞の記事には好景気だって…",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_008"] = "レイチェル・アンバーのこと?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_009"] = "この町は わけわかんないことだらけ…",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_012"] = "あの… すみません",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase02_AdultMale_001"] = "まだ何か? 星占いを読んでるんだ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_002"] = "そいつは無理な話だ。 この町はもう昔のように魚が取れねえ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_005"] = "まだ用か?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_008"] = "すっかり変わり果てちまったよ。 俺が町一番の漁師だったのは大昔の話だ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_010"] = "昔は魚のほうから船に飛び込んできたもんさ… |プレスコット家が 港の権利を買い取るまではな",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_013"] = "「バリ・ハイ」って船だ |生活は苦しいが まだ手放しちゃいない… |昔の名残ってやつだな…",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_031"] = "そのうち町の名前も「プレスコット・ベイ」に変えられちまうかもな",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_033"] = "漁師の間じゃ有名さ。 ろくなことをしない連中だよ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_035"] = "ああいう連中は 学校や図書館を作って 尊敬を集めるんだ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_037"] = "気を落としても仕方ねえ |魚たちがバリ・ハイを呼んでいる… |「老漁師は死なず ただ生臭いのみ」って言うだろ",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_001"] = "さっきはどうも",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_003"] = "おはようございます。 いつでも漁に行けそうな恰好ですね",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_006"] = "もっといろいろ聞きたいけど 急いでるので。 たくさん釣れますように!",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_007"] = "そんなに変わったんですか?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_009"] = "今でも腕はよさそうですけど…",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_012"] = "船は?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_014"] = "この町は 魚がよく取れるって…",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_030"] = "この町はプレスコット家のもの同然…",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_032"] = "面識は?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_034"] = "学校も同じ状況…",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase02_Fisherman_001"] = "今日はしゃべりすぎちまったようだ",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_002"] = "ああ ごらんよ。若さあふれる女の子だ。 あんた 高校生かい?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_004"] = "そりゃもう。 この町の変化と共に生きてきたんだ",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_006"] = "一目ではわからんかもしれん。 この町は美しい。 だが 闇も深い |欲深い連中が町を乗っ取り… 人々は仕事を奪われ… |家を追われた。 あたしのように",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_008"] = "そりゃいろいろあったさ |人生は一歩足を踏み外すだけで 転がり落ちるもんだ… |ダメな男と結婚して せっせと貯めた金をだまし取られ… 家を失い… |今はこの様だ",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_010"] = "どこへ行けってんだい? この霧があたしを守ってくれる |たとえ住む家がなくとも アルカディア・ベイがあたしの故郷さ",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_012"] = "自分の家族よりも世話になってるよ |あんたくらいの年の不良娘がいる |ダンナはろくでなしだが…",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_016"] = "一度 あたしに「仕事を探せ」なんて言いやがった |せめてジョイスには優しくしてるならいいけどね",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_018"] = "粗暴だがかわいい子さ |よく美人の友だちといるのを見かけたよ… レイチェルといったかな",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_024"] = "諸悪の根源さ |町のために尽くしてくれた時期もあったが… |ずいぶん昔の話だ。 今じゃ町を牛耳ってる",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_028"] = "だったら あんたが守っておやり |プレスコット家が相手なら 警察もあてにならん |あんたの学校だって やつらの物 同然だ",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_036"] = "行方不明なのは知ってる。 たまにこのあたりで見かけたよ |一人っきりで 思い詰めたような顔をしてね |若くてキレイな子に どんな悩みがあったのやら…",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_038"] = "一度か二度ね |学校で悩みがあるとか カリフォルニアに行ってモデルになりたいとか… |心は開かないが 優しい子だった",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_040"] = "さっきも言ったけど ジョイスの娘とは仲がよさそうだったね |一度 年の離れた男といたけど ありゃ父親だね |娘がいなくなって かわいそうに",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_042"] = "無事でいることを祈るけど… 救えない人間だっているからね",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_046"] = "あんたは若いが頭がよさそうだ |私はブラックウェルや町のことなら 何でも知ってるよ…",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_048"] = "ああ そのようだね",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_001"] = "どうも",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_003"] = "この町に住んで 長いんですか?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_005"] = "町の変化って?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_007"] = "何があったんですか?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_009"] = "お気の毒に… この町を出たことは?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_011"] = "このダイナーのジョイス・プライスは知ってますか?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_015"] = "デイビッド・マドセンですね…",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_017"] = "娘に会ったことは?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_023"] = "プレスコット家について 教えてほしいんですけど",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_027"] = "あの家の人間に 脅されている子がいて…",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_035"] = "レイチェル・アンバーについて何か知りませんか?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_037"] = "話したことは?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_039"] = "いつも一人だったんですか?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_045"] = "ええ ブラックウェルの生徒です",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_047"] = "どうも また来ちゃった",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_100"] = "もう行かなきゃ。 さよなら",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase04_HomelessFem_001"] = "話がしたかったら いつでも来るといいよ お嬢さん",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopAdultFem_020"] = "誰かいてよかった…",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopAdultFem_040"] = "別に興味ないわね",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_010"] = "よーし これから宝くじを換金しに行くぞ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_030"] = "盗もうとするなよ。 俺の宝くじだ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_050"] = "億万長者になるぞ～",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_060"] = "誰も宝くじを盗まないでくれよ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_070"] = "さっさと金持ちになりたいぜ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_100"] = "おーい ビールとベーコン頼むよ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_120"] = "酒ないのか?",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_140"] = "酒がないって… 一体どんな店だよ",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_Joyce_110"] = "ここはダイナーだ。 バーじゃない",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_Joyce_130"] = "もう十分飲んだようだね。 ベーコンにしときな",
  ["Cue_E2_2A_DinerPark_FrankSleeping_Frank_010"] = "おい よせ。 吠えるんじゃねえ",
  ["Cue_E2_2A_Diner_CHAdultFem02_Phase01_AdultFem02_001"] = "あら おはよう お嬢さん。 とってもいいお天気ね |きっと今日は素晴らしい一日になるわよ |朝食を楽しんでらっしゃい",
  ["Cue_E2_2A_Diner_CHAdultFem02_Phase02_AdultFem02_001"] = "あら 何かご用かしら。 朝食を食べてきたら?",
  ["Cue_E2_2A_Diner_CHAdultMal_Phase01_AdultMal_001"] = "何だよ ビールを飲みすぎて気分が悪いんだ。 向こうへ行ってくれ |話すと頭がガンガンする",
  ["Cue_E2_2A_Diner_CHAdultMal_Phase02_AdultMal_001"] = "さっさと向こうへ行かねえと ゲロをぶちまけるぞ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_002"] = "オッケー いつでもどうぞ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_008"] = "簡単すぎるだろ。 じゃあ どんなキーホルダーだ?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_014"] = "そりゃそうだ。 じゃあ 本数はわかる?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_015"] = "そりゃ いくらかはね。 金額は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_016"] = "さすがだな。 じゃあ… 切符を切られた時刻は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_017"] = "ハズレ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_018"] = "それは車ん中",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_020"] = "全然ダメじゃん",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_025"] = "すごい… ハズレ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_037"] = "それじゃ タネ明かしに ポケットの中身を見せてやるよ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_086"] = "おいおい 惜しくもないぞ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_087"] = "ブー! 大ハズレ!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_088"] = "なんだよ 期待させといて",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_089"] = "はあ? あんたホントに親友?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_090"] = "他の人の趣味と勘違いしてないか?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_091"] = "当たり! やるじゃん!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_092"] = "けっこう悪運が強いんだな。 他には?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_098"] = "なかなかやるね… でも まぐれの可能性もある",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_099"] = "やるな! 次は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_100"] = "すごいじゃん! 他には何が入ってる?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_101"] = "タバコの本数がわかる能力… 面白い",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_102"] = "そんなに残ってるわけないじゃん",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_103"] = "残念…",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_104"] = "大ハズレ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_105"] = "ハハッ どうだ お金持ちだろ?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_106"] = "驚いたな… ハズレ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_107"] = "やるね 大当たりだ!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_108"] = "そんな早起きなわけないじゃん",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_109"] = "へえ 面白いじゃん。 それじゃ 答え合わせだ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_003"] = "それじゃ ポケットの中身を当ててみせるよ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_005"] = "車のキー",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_006"] = "古くなったチューインガム?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_007"] = "そうだな… 銃とか?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_011"] = "ポケットにタバコを入れてるでしょ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_012"] = "えーと… お金かな",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_013"] = "駐車違反の切符",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_021"] = "6 本ある",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_022"] = "7 本ある",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_023"] = "13 本あるはず",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_026"] = "25 セント",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_027"] = "82 セント",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_029"] = "86 セント",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_030"] = "午前 11 時 10 分",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_031"] = "午前 10 時 34 分",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_032"] = "午前 6 時 42 分",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_078"] = "うーん どうかな…",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_079"] = "パンク少女っぽいドクロのキーホルダーかな",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_080"] = "うーんと… カミソリのキーホルダー",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_081"] = "そのネックレスとおそろいの銃弾!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_083"] = "ピクセルのハート型かな…",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_084"] = "ペンギンのキーホルダー",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_085"] = "かわいいロボットパンダのキーホルダー!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_110"] = "ラメ入りのジェルが入ってるでしょ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_033"] = "それで その次は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_034"] = "なるほど それは見ないとな",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_036"] = "面白くなってきた! 次は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_037"] = "そんなバカな… とりあえず どうなるか見てみるか",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_045"] = "4 つの出来事を当てるって言ったろ｡ 全然足りないぞ",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_049"] = "4 つの出来事を当てるって約束だろ｡ 2 つだけじゃん",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_050"] = "いいぞ。 あと 1 つの出来事は?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_003"] = "トラックの運転手がマグを割って おばさんが怒る",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_004"] = "トレバーがグラスを割って ジャスティンがからかう",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_005"] = "警察官がグラスを割って おばさんが文句を言う",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_010"] = "警察官に無線が入って 応答する",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_011"] = "警察官に無線が入って すぐにダイナーを飛び出すの",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_012"] = "警察官に無線が入って 車に乗ってる相棒が|彼を置いてっちゃう",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_017"] = "ジャスティンとトレバーがケンカして おばさんが殴る",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_018"] = "ジャスティンとトレバーがケンカして おばさんがはやし立てる",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_019"] = "ジャスティンとトレバーがケンカするけど おばさんは気にしない",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_025"] = "ゴキブリが歩き回って ジュークボックスが暴走する",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_026"] = "ハエが止まった途端 ジュークボックスが暴走する",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_027"] = "トラックの運転手が曲を変える瞬間 ジュークボックスが暴走する",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_044"] = "おばさんがお皿を落として トラックの運転手がからかう",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_046"] = "警察官に無線が入るけど 無視してドーナツを食べ続ける",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_047"] = "ジャスティンとトレバーがケンカして おばさんが止める",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_048"] = "蝶が止まった途端 ジュークボックスが暴走する",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_002"] = "やあ お嬢さん。 何か困りごとかい?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_005"] = "ここが家だったら どんなにいいか |ジョイスのウマいコーヒーとバーガーが いつでも出てくるんだから… |君 クロエと同じ年頃かい?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_008"] = "ああ ジョイスの店はどれもうまいからね |俺も悩むよ… パンプキンパイか マカロニチーズか",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_011"] = "ジョイスの料理は最高だ。 署の連中もよく来る |みんな ここが好きなんだ。 彼女は俺たちの… お袋だな",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_017"] = "署じゃ クロエは有名だからな。 ジョイスも気の毒に",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_020"] = "悪い子じゃないんだ。 辛いことも経験してる。 言い訳にはならないがね…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_021"] = "手のかかる子だろ",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_023"] = "俺も 13 で父を亡くしたが グレなかったよ |ジョイスは最高の母親だ… |なのに クロエは認めようとしない",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_029"] = "運は自分で作るもんだ。 あの子は自ら破滅に向かってる |心理学者を気取るつもりはないが…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_031"] = "いい友だちのようだな。 ジョイスにとっても いい娘であってほしいものだが…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_034"] = "どうやら部屋に売人まで連れ込んだらしい…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_035"] = "どうやら部屋でハッパまで吸ってたらしい",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_037"] = "まるで見てたかのようなセリフだな",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_039"] = "通報があったわけじゃない |ジョイスはクロエの友だちが持ってたと言ってたが… どうかな",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_050"] = "ああ そうだ。 外の RV 車には近づかないようにしなさい",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_052"] = "賢明だな 中に住んでるフランクって男は 要注意人物だ |詳しくは言えんが… |さて これを飲んだら仕事に行くよ",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_057"] = "言わないんだ。 別にそいつを逮捕するつもりもないんだが |ただ クロエに二度と近づかないよう脅す… って冗談さ |それに クロエにはデイビッドがついてる",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_058"] = "君は友だちなのか?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_059"] = "とにかく ろくでもないことをしてたのは確かだ |クロエを悪く言いたくはないが こちらも仕事なんでね",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_060"] = "ただの知り合いだが なぜそんなことを聞く?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_063"] = "彼は立派な男だ。 軍の経験もある |高校の警備員は デイビッドにとってぴったりな仕事さ |誰もが警官になれるわけじゃないしね",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_064"] = "何か?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_001"] = "すみません",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_003"] = "いえ… むしろ ここは家みたいに落ち着くので",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_004"] = "何を食べようか 迷ってるだけです",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_010"] = "おばさんと親しいんですか?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_016"] = "クロエを知ってるんですか?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_018"] = "そういうわけでは…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_019"] = "そうです",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_022"] = "お父さんが亡くなったって…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_028"] = "いえ… クロエは少し運が悪かっただけ",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_030"] = "ときどき… でも 困ったときは助けてくれる 優しい子です",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_032"] = "えっ… 誰からそれを?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_033"] = "えっと… それはよくないですね。 あっ… ベーコン とってもいい匂い…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_036"] = "そんなに大したことじゃ… 部屋の中で自由にするくらい…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_038"] = "デイビッド・マドセンと親しいんですか?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_049"] = "もう行かなきゃ。 朝食をごゆっくり",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_051"] = "見るからに怪しい車には 近寄らないようにしてます",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_055"] = "その友だちの名前は?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_056"] = "今 聞いただけです",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_061"] = "少し気になっただけです… なぜ警察官にならなかったのかって",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_062"] = "ある意味 学校では有名人なので…",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_065"] = "また来ちゃいました",
  ["Cue_E2_2A_Diner_CHCop_Phase02_Cop_001"] = "コーヒー片手に話すのも嫌いじゃないが 今は一人にしてくれないか",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase01_Fisherman02_002"] = "大漁どころか 1 匹も釣れやしねえ。 まったくシケてやがるぜ |食事のジャマをしないでくれ",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase01_Max_001"] = "今日は大漁でした?",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase02_Fisherman02_001"] = "まだ食事中だ。 ジャマするな",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_001"] = "謝ることはないよ。 あんたは前に進んだのさ |ウィリアムが死んで 私もそうした。でも クロエは… |今でも納得してない… |とにかく また顔を出しておくれ |あの子には友だちが必要だ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_002"] = "探偵ごっこかい? |悪いけど あんた以外で心配な子は一人だけさ |それだけで手一杯だよ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_005"] = "ありがとう マックス。 思い出だけでも 十分なんだよ |クロエはまだ 分かってないけどね",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_006"] = "すぐ持ってくるよ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_013"] = "家での件も あんたが火に油注いだようなもんじゃないか",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_015"] = "クロエが何か言ってたのかい?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_017"] = "あんなの そんな大した事件じゃないよ |でも あの子をかばってくれてありがとう… 嬉しいよ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_019"] = "どこまでやりゃ気が済むのか… |退学 家出… タトゥー ピアスに真っ青な髪… |今は義理の父親に反抗してばかりだ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_022"] = "あの人も後悔してる… ちゃんと罰を受けるさ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_025"] = "そうかい? あの人は あんたが思うほど悪い人じゃない |それに あんたは自分のハッパだと言ったんだろ? 違うかい?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_027"] = "知ってるんだね。 クロエに手をあげたことを… まったく…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_028"] = "名前は聞いたことあるけど 詳しくは知らないね |お互いの仕事には口を出さないんだ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_030"] = "でも クロエも悪いんだよ。デイビッドは戦争で もう十分苦労した |彼なりに クロエや生徒たちのことを気にかけてるんだ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_032"] = "さて 肝心なことを忘れてたね。 注文は何にする?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_034"] = "あの子は人を… デイビッドを怒らせる天才さ |でも きっとそのうち家族になれる。 今は時間が必要なんだ…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_036"] = "いいとは思ってないよ。 でも デイビッドは二度と手を上げないって誓ったんだ |きっと そのうち家族になれるさ… |今は… 今は時間が必要なんだよ…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_003"] = "クロエとおばさんが大変だったときに… 電話もしなくてごめんなさい |今じゃ 家族はシアトルで 私は町で独りぼっち |バチが当たったね",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_004"] = "ウィリアムおじさん… 亡くなったんだもんね。 私も寂しいよ",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_008"] = "そのとおりかもね",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_009"] = "最後にここで ベルギーワッフルを食べたのは 13 歳のときだっけ… |久しぶりに食べたいな",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_012"] = "でも 奨学金を取り上げるって デイビッドに脅されて…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_014"] = "うん… 反省してる。 クロエも私も これ以上のトラブルはごめんだし…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_016"] = "でも まさかクロエをぶつとは…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_018"] = "クロエはわかってるよ。 ただ時間が必要なだけ。 おばさんは大変だろうけど…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_020"] = "私のせいにしてれば こんなことにならなかったのに…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_021"] = "何も言わなくたってわかるよ。 学校で デイビッドを見てるもん",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_024"] = "クロエはだいぶ変わっちゃったんだね…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_026"] = "気持ちはわかるけど…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_029"] = "メールで デイビッドにぶたれたって…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_031"] = "ケイト・マーシュのことも?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_033"] = "分かるよ おばさん。 クロエもケンカ腰だったし…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_035"] = "だからって 大人が子どもを殴ってもいいの?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_056"] = "ベーコンオムレツを ずっと食べたかったの…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_057"] = "言い争ってる現場の写真を撮ったの… おばさんなら 理由を知ってるかなって…",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_058"] = "言い争ってるところを見たから… 理由を知ってるかなって…",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_002"] = "授業サボってスケボー行く前の コーヒーブレーク |マックスこそ写真撮らないのか?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_004"] = "なあコーヒーに薬でも入れたら ちょっとは目が覚めるかな",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_007"] = "何それ ウケるね。 でも 俺 笑いの沸点超低いからな",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_009"] = "そっちこそ宿題やったのか?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_011"] = "付き合ってるってトレバーから聞いたよ |ぼーっとしてる間に先越されたってわけ… |じゃな マックス",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_001"] = "何してるの?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_003"] = "まだいいの。 私も… コーヒーブレーク中",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_005"] = "覚めても授業はサボるんでしょ",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_006"] = "写真ならいつでも撮ってるよ。 私自身がカメラだもん",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_008"] = "ちゃんと学校に行きなよ",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_010"] = "ああ言えばこう言う… そういえば トレバーとデーナの件は知ってるの?",
  ["Cue_E2_2A_Diner_CHJustin_Phase02_Justin_001"] = "眠くなってきたから あとにしてくれ",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_001"] = "トレバー",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_003"] = "うん デーナの部屋から出てくるとこ見ちゃった",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_004"] = "いや 見てないよ",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_008"] = "ジャスティンの反応は?",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_002"] = "よお マックス。 そういえば 寮で俺のこと見たって?",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_005"] = "さっき ジャスティンにも言ったんだ。 こいつもデーナを狙ってたから",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_006"] = "絶対目があったと思ったけど… ま これでバレたか… ジャスティンも知ってる",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_007"] = "すげえ怒ってたけど 大丈夫。 隠し通すことも無理だしさ… じゃ また授業で",
  ["Cue_E2_2A_Diner_CHTrevor_Phase02_Trevor_001"] = "また あとでな",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_004"] = "ごめんなさい",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_005"] = "私がどかないと見えないんですか?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_006"] = "おばさんみたいって?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_008"] = "おばさんは最高ですよ。 私もあんな大人になりたい",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_009"] = "少し失礼じゃないですか?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_010"] = "おばさんらしいな… そういうところが好きなんです",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_014"] = "えっと… こんにちは",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_001"] = "どいてくれないか? 見えないだろう",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_002"] = "いいんだよ |駐車場のトラックを確認したいだけでね |夜通し走ったから ちゃんと休ませてやらねえとな",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_003"] = "イヤな言い方しやがる。 ジョイスみたいだな",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_007"] = "偉そうで生意気だ… お前みたいに",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_011"] = "心配せずともなるだろうよ |ここに通って 3 年になるが ジョイスの口からは嫌味が増えるだけだ",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_012"] = "こっちは 2 トンもの硝酸を運ぶために 夜通しで運転した末に |やっと朝食にありついたとこなんだ |窓の外を眺めながら 静かに食いたいんだよ |わかったら どいてくれ",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_013"] = "なら お前も大人になったら 永遠と脂っこいベーコンを焼き続けるといいさ… |ジョイスみたいにな |これ以上 朝食のジャマをしないでくれ",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase02_Trucker1_001"] = "もういいだろ",
  ["Cue_E2_2A_Diner_CHTrucker2_Phase01_Trucker2_001"] = "今はおしゃべりする気分じゃない |大量の朝メシを腹に収めてるとこなんだ |話は終わりだ",
  ["Cue_E2_2A_Diner_CHTrucker2_Phase02_Trucker2_001"] = "言っただろ。 ジャマをするな",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_050"] = "偉大なるマックス様 おみそれいたしました…",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_070"] = "何言ってんだ! だってさ 誰かをぶん殴ったって |時間を戻すだけでなかったことにできるんだぞ!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_090"] = "あたしにも イタズラしたんじゃ…",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_110"] = "まさか ホントに時間を巻き戻せるなんて。 色々試さなきゃ!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_130"] = "マックスがそれ言う?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_140"] = "ちょっと… 鼻血 出てるよ。 ほじりすぎた?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_150"] = "おい 大丈夫か?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_170"] = "こっからが本番じゃん。 もっと見せてよ… いい場所があるんだ",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_180"] = "あたしに任せなって",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_200"] = "言ったとおりだ!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_210"] = "ハッ ヤバすぎる!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_220"] = "すごいな!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_230"] = "マジかよ!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_240"] = "さすが ママ!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_250"] = "当たりだな。 ガキが悪さでもしたか",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_260"] = "痴話ゲンカみたいだな",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_270"] = "ジュークボックスのゴキブリまで当たった!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_060"] = "この力はオモチャじゃないんだよ。 ちゃんと考えて…",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_080"] = "はしゃぎすぎ",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_100"] = "何もしてないよ",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_120"] = "時間ないよ",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_160"] = "興奮しすぎたかも。 クロエが あまりにもはしゃぐから…",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_190"] = "はいはい 分かりました… どこへでもついていくよ",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_030"] = "はずれたな",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_040"] = "違ったね マックス",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_050"] = "はい 空振り",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_060"] = "残念だったな",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_020"] = "どうしたんだ?",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_030"] = "おーい まだか",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_050"] = "目に焼きつけてんのか… 写真家だけに",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_060"] = "どうすんだ?",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_070"] = "何モタモタしてるんだ?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_050"] = "感動の再会は済んだ?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_090"] = "余計なお世話だよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_110"] = "また始まったよ。 もう「軍曹」とママの|ダブル説教は聞き飽きた",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_140"] = "やめろよ。 もうマックスを責めなくたっていいだろ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_160"] = "ママも「軍曹」も説教ばっか",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_200"] = "もう うんざりだよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_205"] = "何だ このひどい曲",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_210"] = "さて 本題だけど…",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_220"] = "力のこと教えてくれよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_240"] = "だから あれは夢だってば。 それより実際に見せてよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_260"] = "とにかく やってみてって。 ほら",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_010"] = "お腹の鳴る音が響いてるよ。 さあ お食べ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_030"] = "しかし 大人になったもんだね。 クロエの写真なんか見てると…",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_040"] = "あら ウワサをすれば…",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_060"] = "またタダメシを食べに来たのかい。 あんたのツケだけで 家が買えるよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_080"] = "バカ言わないで。 クロエを助けに 戻ってきてくれたんだ… サービスしとくよ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_100"] = "昨日の今日でよく言うよ この子は…",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_130"] = "昨日のお詫びのつもりかい?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_150"] = "わかってるよ。マックスはいい子さ… いや もう立派な大人だ",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_170"] = "イヤなら その呼び方をやめな",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_180"] = "あんたはベーコン 1 枚で十分ね",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_020"] = "ヨダレが出そう",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_070"] = "今日は私のおごりだから",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_120"] = "今日は私のおごりだから",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_190"] = "二人とも変わらないね",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_230"] = "教えるも何も… あの巨大な竜巻を見た理由だって わかんないし…",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_250"] = "私だってよくわかんなくて…",
  ["Cue_E2_2A_Diner_Citizens_Trucker1_010"] = "3 皿目もいけそうだ",
  ["Cue_E2_2A_Diner_Citizens_Trucker1_030"] = "まだ腹に余裕がある",
  ["Cue_E2_2A_Diner_Citizens_Trucker2_020"] = "まだ 1 皿目だろ",
  ["Cue_E2_2A_Diner_Citizens_Trucker2_040"] = "冬眠前の動物みたいだな",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_010"] = "さて お昼の「KBAY 7 ニュース」では 昨日の雪について検証していきます |晴れた午後に突然降り出した謎の雪に |町の人々は驚きと喜びをあらわにしていました",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_020"] = "番組内では 気象学者への取材 |そして雪に反応する人々の楽しい映像もお届けします",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_030"] = "この不思議な雪は 母なる大地のイタズラでしょうか? |どうかチャンネルはそのままで。 真相を解明いたします",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_035"] = "ベーコン 上がるよ!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_040"] = "ベルギーワッフル一丁 上がるよ!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_050"] = "できたよ!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_010"] = "ベーコンオムレツ入ったよ!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_020"] = "ベルギーワッフルを一丁 お願い!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_060"] = "注文だよ!",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_010"] = "ああ 久しぶりだね |すっかりキレイになって 元気にしてたかい マックス?",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_030"] = "ウェイトレスをやる以外 取り柄なんてないからね",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_050"] = "口がうまいね。 昔から利口だった",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_060"] = "うちのクロエにも見習ってほしいよ。 あの子ったら またモメ事を起こしてね",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_080"] = "そりゃクロエからしたら デイビッドは悪者だけどね… 本当は違うんだよ |いい人なんだ… ただ…",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_100"] = "マックスが戻ってきたんだ。 これでクロエも少しは落ち着くだろう",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_110"] = "口がうまいね。 昔から利口だった",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_120"] = "でも今はどうかな… うちでモメ事を起こしたって?",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_130"] = "昨日の話は全部 デイビッドから聞いたよ |もっとちゃんと紹介したかったけど… |いい人なんだよ。 クロエが何と言おうとね",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_150"] = "残念だよ。 あんたがいれば クロエも落ち着くと思ってたのに…",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_020"] = "おばさん また会えてうれしい。 変わらないね",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_040"] = "今でも美人だって意味",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_070"] = "知ってる。 クロエが義理のお父さんにぶたれたって…",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_075"] = "うん。 義理のお父さんがクロエを…",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_090"] = "うん おばさんが結婚した人だもんね。 でも… あまりクロエを責めないで",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_140"] = "うん わかってる。 あれは もうほとんど事故みたいなものっていうか… |自分でもバカだったと思ってる",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_160"] = "クロエなら大丈夫だよ",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_030"] = "おーい あたしは ほったらかしかよ",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_060"] = "何だよ",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_070"] = "ケイトといるほうがいいなら 好きにしな",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_090"] = "まあいい… 行こうぜ",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_010"] = "ケイト どうしたの?",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_020"] = "うん うん…",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_040"] = "うん 絶対に… 約束する",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_050"] = "信じて。 宿題でもやって 気を楽に… 今 話してもしょうがないから… |あとで電話するよ",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_080"] = "バカ言わないで。 クロエと一緒にいるから",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_010"] = "じゃね ママ!",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_030"] = "自由だ!",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_050"] = "電話 1 本で 大げさだよ",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_060"] = "さあ 来たまえ マックス君。 そなたの力で 世界を支配するのだ…",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Max_020"] = "さよなら",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Max_040"] = "ケイトに悪かったかな",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_010"] = "準備はいい? 早く行くよ",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_020"] = "出なくていいよ。 今はそんな場合じゃないだろ",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_030"] = "ほら ママに捕まる前に行かないと!",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_050"] = "何だよ。 あたしには一度も電話しなかったくせに |毎日会う同級生には優しいんだな |よくわかったよ。 電話に出ればいいじゃん |別の連中とつるむよ",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Max_040"] = "同級生のケイトからだ…",
  ["Cue_E2_2A_Diner_PowerProof01_Chloe_020"] = "えー 透視までできるのか? なんでもありだな",
  ["Cue_E2_2A_Diner_PowerProof01_Chloe_030"] = "えーと…",
  ["Cue_E2_2A_Diner_PowerProof01_Max_010"] = "じゃあ クロエのポケットの中身を全部言い当てるよ",
  ["Cue_E2_2A_Diner_PowerProof02_Chloe_020"] = "マジかよ",
  ["Cue_E2_2A_Diner_PowerProof02_Chloe_040"] = "いいよ やってみて",
  ["Cue_E2_2A_Diner_PowerProof02_Max_010"] = "未来を予言してあげる",
  ["Cue_E2_2A_Diner_PowerProof02_Max_030"] = "これから 30 秒くらいの間に起きる出来事を… 4 つ予言してみせるね",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Cop_030"] = "クソッ 呼び出しのせいで 朝メシはお預けだ… 相棒はどこいった?",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Joyce_020"] = "またマグを割ったのかい? まったく… お代わりナシだよ!",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Joyce_080"] = "このジュークボックスも ついにガタがきたかね…",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker1_010"] = "おっと!",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker1_070"] = "さっきのゴミみてえな曲に比べたら ずっとマシだ",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker2_060"] = "やっと まともな曲が聴ける",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Joyce_030"] = "ケンカなら外でやりな!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Joyce_050"] = "知らないわよ",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Justin_020"] = "叩くんじゃねえよ!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Trevor_010"] = "このバカ野郎!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Trevor_040"] = "こいつが先に",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_010"] = "マジかよ。 首のあたりに鳥肌立ちまくったぞ",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_020"] = "これ全部 当てたら マックスの力を信じてやるよ",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_030"] = "ホントなんだな…",
  ["Cue_E2_2A_Diner_ShowItems_Puzzle01_Chloe_010"] = "まったく 全然ダメじゃん。 ちょっと信じてたのにさ",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_020"] = "はいはい",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_060"] = "餓死するとこだったよ",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_080"] = "にしても さっきのはヤバかった。 もっと見せてよ |明らかに「超能力」って感じのさ…",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_010"] = "クロエ テーブルから物をどけなさい",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_030"] = "料理はどうだい",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_050"] = "そりゃよかったよ",
  ["Cue_E2_2A_Diner_TiddyTable_Max_040"] = "昔より美味しい",
  ["Cue_E2_2A_Diner_TiddyTable_Max_070"] = "そうだね",
  ["Act_E2_3A_Junkyard_Bottle01_Interact01_Max_010"] = "あーもう!",
  ["Act_E2_3A_Junkyard_Bottle01_Look01_Max_010"] = "これはこれは… 使い道のありそうなビンじゃないですか…",
  ["Act_E2_3A_Junkyard_Bottle02_Look01_Max_010"] = "これは的に使えそう",
  ["Act_E2_3A_Junkyard_Bottle03_Look01_Max_010"] = "よかった 割れてないし 完璧",
  ["Act_E2_3A_Junkyard_Bottle03_Look01_Max_020"] = "もっと高い所からならボートに乗れそう",
  ["Act_E2_3A_Junkyard_Bottle04_Look01_Max_010"] = "「ボトルハンター・マックス」 この秋公開…",
  ["Act_E2_3A_Junkyard_Bottle05_Look01_Max_010"] = "見つけた かくれんぼでもしてたの?",
  ["Act_E2_3A_Junkyard_Bottle1_VoiceOver01_Max_010"] = "ビン その 1 を発見。 あと 4 本!",
  ["Act_E2_3A_Junkyard_Bottle2_VoiceOver01_Max_010"] = "これであと 3 本",
  ["Act_E2_3A_Junkyard_Bottle3_VoiceOver01_Max_010"] = "あと 2 本。 5 本見つけるのも一苦労だよ",
  ["Act_E2_3A_Junkyard_Bottle4_VoiceOver01_Max_010"] = "あと 1 本だ!",
  ["Act_E2_3A_Junkyard_Bottle5_VoiceOver01_Max_010"] = "さて ビンをクロエ様に渡さなきゃ",
  ["Act_E2_3A_Junkyard_Bracelet_Look01_Max_010"] = "悲しくなるな…",
  ["Act_E2_3A_Junkyard_CHChloe_Look01_Max_010"] = "さすが クロエ…",
  ["Act_E2_3A_Junkyard_CHChloe_Look02_Max_010"] = "銃を手に持っても 全然リラックスしてる",
  ["Act_E2_3A_Junkyard_CHChloe_Look03_Max_010"] = "クロエ 次はどこに行くつもりなんだろう。 ここ以外ならどこでもいいか",
  ["Act_E2_3A_Junkyard_CHMax_VoiceOver01_Max_010"] = "なんでフランクはレイチェルのブレスレットを持ってたんだろう? |考えるのは後 今はクロエについていこう",
  ["Act_E2_3A_Junkyard_CampFire_Look01_Max_010"] = "ここは人気のスポットなんだろうな",
  ["Act_E2_3A_Junkyard_CarWreck01_Look01_Max_010"] = "車にもそれぞれ物語がある…",
  ["Act_E2_3A_Junkyard_CarWreck02_Look01_Max_020"] = "錆びた金属に囲まれると落ち着く… なんて 暗い? ゴスっぽい?",
  ["Act_E2_3A_Junkyard_CarWreck03_Look01_Max_030"] = "クロエ ここの車を見て おじさんの事故を思い出さないのかな",
  ["Act_E2_3A_Junkyard_ChairSit_Max_010"] = "怪しげな場所だけど クロエがよく来るのもわかる",
  ["Act_E2_3A_Junkyard_ChairSit_Max_020"] = "スチームパンクっぽいし…",
  ["Act_E2_3A_Junkyard_ChairSit_Max_030"] = "2 人で子どもの頃に戻ったみたい… |隠れて将来のことを考えて…",
  ["Act_E2_3A_Junkyard_ChairSit_Max_040"] = "ひどいことばっかり起きるけど また一緒にいられるのはうれしいな",
  ["Act_E2_3A_Junkyard_ChairSit_Max_050"] = "昔に戻ったみたいで 幸せ…",
  ["Act_E2_3A_Junkyard_ChloeEnd_VoiceOver01_Max_010"] = "今日も人生散々。 クロエのとこに行かなきゃ",
  ["Act_E2_3A_Junkyard_ChloeEnd_VoiceOver01_Max_020"] = "新たなドラマの幕開けってことね。 早くクロエと逃げよう",
  ["Act_E2_3A_Junkyard_Crate_Look01_Max_010"] = "これを使えばビンに届くかな",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_010"] = "あれ? 竜巻の夢に出てきたのと同じ鹿…?",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_020"] = "鹿の写真を撮るなら今…",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_030"] = "何か言いたげに じっと見てる…",
  ["Act_E2_3A_Junkyard_DoeRewind_VoiceOver01_Max_010"] = "え? 力が効かないの? どういうこと?",
  ["Act_E2_3A_Junkyard_Flyer_Look01_Max_010"] = "レイヴのためなら ロスにまで行きそう。 楽しそうだな",
  ["Act_E2_3A_Junkyard_Graffiti02_Look01_Max_010"] = "ご親切にどうも",
  ["Act_E2_3A_Junkyard_Graffiti05_Look01_Max_010"] = "キツイな…",
  ["Act_E2_3A_Junkyard_Graffiti07_Interact01_Max_010"] = "仲間は 3 人… あとはレイチェルを探すだけ",
  ["Act_E2_3A_Junkyard_Graffiti07_Look01_Max_010"] = "間に入るつもりはないけど… 私も来たんだし",
  ["Act_E2_3A_Junkyard_Makeup_Look01_Max_010"] = "クロエのメイクじゃなさそう",
  ["Act_E2_3A_Junkyard_MaxAfterEllipse_VoiceOver01_Max_010"] = "この力… 体への負担が大きいな |元に戻ってよかったけど |とりあえず クロエと話そう",
  ["Act_E2_3A_Junkyard_MessageInBottle_Look04_Max_040"] = "なに この秘密の関係? |レイチェルの考えはまとまってないみたい… それとも恥じてる? |いったい誰のことなんだろう… |これはクロエに見せられない",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_010"] = "ビンはどこ…? 冷蔵庫の中とか?",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_020"] = "小屋の中にビンがあるかもしれない…",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_030"] = "ボートがあるところに海賊あり… 酒瓶もあるはず",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_040"] = "この辺でたき火をするスポットがあるはず…",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_050"] = "車の残骸の中にビンが残ってないかな…",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_060"] = "あの人を撃ちそうになったせいで クロエも私も危険な目にあいそう",
  ["Act_E2_3A_Junkyard_Mixtape_Look01_Max_010"] = "「レイチェル・ソング」 クロエ 私にも作ってくれるかな",
  ["Act_E2_3A_Junkyard_NoShootFrank_VoiceOver01_Max_010"] = "私のせいで クロエの銃がフランクに取られた…",
  ["Act_E2_3A_Junkyard_Object01_Look01_Max_010"] = "かわいそうに 一人ぼっちにされたのね",
  ["Act_E2_3A_Junkyard_Object02_Look01_Max_010"] = "安らかに眠ってね…",
  ["Act_E2_3A_Junkyard_Object03_Look01_Max_010"] = "これすごく怖いんだけど…",
  ["Act_E2_3A_Junkyard_Object04_Look01_Max_010"] = "アメフト部が来てたんだ",
  ["Act_E2_3A_Junkyard_Object05_Look01_Max_010"] = "薬きょう? 新しいみたいだけど…",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_010"] = "ビンを探しに行かないとね",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_020"] = "ビンを探さなきゃ 宝探しの始まり",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_030"] = "隠れても無駄 絶対に見つけ出してやる",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_010"] = "巻き戻して ビンに命中させてあげよう",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_020"] = "すごかったけど クロエはビンに当てたいんだよね",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_030"] = "巻き戻して クロエの代わりに狙いをつけてあげなきゃ",
  ["Act_E2_3A_Junkyard_OldSmallBoat_Look01_Max_010"] = "陸上にあるボートを見ると 悲しくなる… 持ち主はどこ行ったんだろう…?",
  ["Act_E2_3A_Junkyard_OldWashingMachine_Look01_Max_010"] = "どれだけの服がこれで洗われたんだろう",
  ["Act_E2_3A_Junkyard_Paper_Look01_Max_010"] = "「死にたい」 誰 こんなの書いたの",
  ["Act_E2_3A_Junkyard_Photo_Look01_Max_010"] = "本当の親友だったんだ。 引っ越さなきゃ これが私だったかも…",
  ["Act_E2_3A_Junkyard_PieceRachelClothing_Look01_Max_010"] = "レトロなパンク T だね",
  ["Act_E2_3A_Junkyard_SchoolBus_Look01_Max_010"] = "昔 学生をたくさん乗せて走ってたなんて信じられない",
  ["Act_E2_3A_Junkyard_Shack_VoiceOver01_Max_010"] = "クロエとレイチェルの歴史が刻まれてる。 レイチェルのこと もっと知れそう",
  ["Act_E2_3A_Junkyard_Sign01_Look01_Max_010"] = "この店… 子どもの頃によく行ったなあ |お菓子がおいしかったの |今はただのゴミ捨て場の看板…",
  ["Act_E2_3A_Junkyard_Syringes_Look01_Max_010"] = "なんで こんなとこに古い注射器が…",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_010"] = "静かで原始的な感じ…",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_020"] = "森が囁きかけてくるみたい…",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_030"] = "アルカディア・ベイが何か言おうとしてるような…",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_040"] = "なんて言ってるかはわからないけど…",
  ["Act_E2_3A_Junkyard_VortexFlyer_Look01_Max_010"] = "レイチェル… ボルテックス・クラブのパーティに行ったんだ |日付はいなくなった日の前日",
  ["Act_E2_3A_Junkyard_WoodenPlankRewind_VoiceOver01_Max_010"] = "これじゃジャンプしないとボートから降りられない",
  ["Act_E2_3A_Junkyard_WoodenPlank_Interact01_Max_010"] = "思ったより 重いかも…",
  ["Act_E2_3A_Junkyard_WoodenPlank_Look01_Max_010"] = "うーん この板を橋の代わりに使えそう。 あまり重そうじゃないし",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_010"] = "びっくりしたよ。 気分はどうだ?",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_030"] = "刺激が強すぎたか?",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_050"] = "治ったら言ってくれ",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Max_020"] = "うん… 平気だよ ありがとう。 ちょっと… 休めば大丈夫",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Max_040"] = "そんなことないよ。 正直楽しいかも。 危険だし怖いけど… でも楽しい",
  ["Cue_E2_3A_Junkyard_Bottle01Fail01_IGE_Chloe_020"] = "オッケー",
  ["Cue_E2_3A_Junkyard_Bottle01Fail01_IGE_Max_010"] = "もうちょっと左",
  ["Cue_E2_3A_Junkyard_Bottle01Fail02_IGE_Chloe_020"] = "よーし 任せとけ",
  ["Cue_E2_3A_Junkyard_Bottle01Fail02_IGE_Max_010"] = "もうちょっと上かな",
  ["Cue_E2_3A_Junkyard_Bottle01Fail03_IGE_Chloe_020"] = "了解!",
  ["Cue_E2_3A_Junkyard_Bottle01Fail03_IGE_Max_010"] = "もーちょっと下のほう",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Chloe_010"] = "どこを狙う?",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Chloe_020"] = "よし どこを狙う?",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Max_030"] = "まず撃つとこ見せてよ",
  ["Cue_E2_3A_Junkyard_Bottle01Success_IGE_Chloe_020"] = "了解であります!",
  ["Cue_E2_3A_Junkyard_Bottle01Success_IGE_Max_010"] = "もうちょっと右",
  ["Cue_E2_3A_Junkyard_Bottle02Fail01_IGE_Chloe_010"] = "絶対外さないぜ…",
  ["Cue_E2_3A_Junkyard_Bottle02Fail02_IGE_Chloe_010"] = "ピーッ… ピーッ… 照準作動中…",
  ["Cue_E2_3A_Junkyard_Bottle02Fail03_IGE_Chloe_010"] = "フッ飛ばしてやる…",
  ["Cue_E2_3A_Junkyard_Bottle02FailChloe_IGE_Chloe_010"] = "よーし… どこを狙う?",
  ["Cue_E2_3A_Junkyard_Bottle02FailChloe_IGE_Max_030"] = "まずはそのまま撃って見せて",
  ["Cue_E2_3A_Junkyard_Bottle02Success_IGE_Chloe_010"] = "よし 命中だ!",
  ["Cue_E2_3A_Junkyard_Bottle03Fail01_IGE_Chloe_020"] = "気にくわないから撃つ!",
  ["Cue_E2_3A_Junkyard_Bottle03Fail01_IGE_Max_010"] = "あそこの青い板は?",
  ["Cue_E2_3A_Junkyard_Bottle03Fail02_IGE_Chloe_020"] = "よーし リブートさせてやる!",
  ["Cue_E2_3A_Junkyard_Bottle03Fail02_IGE_Max_010"] = "あそこの古いコンピューターのモニターはどうかな?",
  ["Cue_E2_3A_Junkyard_Bottle03Fail03_IGE_Chloe_020"] = "よーし ドラム缶だな。 フッ飛ばしてやる!",
  ["Cue_E2_3A_Junkyard_Bottle03Fail03_IGE_Max_010"] = "あのさびたドラム缶に穴開けてみよう!",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_010"] = "マックス どれを撃つ?",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_020"] = "おーい どれ撃つんだよ?",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_040"] = "ノリ悪いな いいよ そこのドラム缶撃ってやる… はあ…",
  ["Cue_E2_3A_Junkyard_Bottle03Success_IGE_Chloe_020"] = "ホイールだな オッケー!",
  ["Cue_E2_3A_Junkyard_Bottle03Success_IGE_Max_010"] = "左にあるホイールを撃ってみて",
  ["Cue_E2_3A_Junkyard_Bottle04Fail01_IGE_Chloe_020"] = "よし… ガソリンタンク爆破!",
  ["Cue_E2_3A_Junkyard_Bottle04Fail01_IGE_Max_010"] = "ガソリンのタンクを撃ったらどうなるかな?",
  ["Cue_E2_3A_Junkyard_Bottle04Fail02_IGE_Chloe_020"] = "さよなら… バンパー…",
  ["Cue_E2_3A_Junkyard_Bottle04Fail02_IGE_Max_010"] = "バンパーをヘコませてみようよ",
  ["Cue_E2_3A_Junkyard_Bottle04Fail03_IGE_Chloe_020"] = "破片には気をつけろよ!",
  ["Cue_E2_3A_Junkyard_Bottle04Fail03_IGE_Max_010"] = "フロントガラスをフッ飛ばして",
  ["Cue_E2_3A_Junkyard_Bottle04FailChloe_IGE_Chloe_020"] = "で? どれを撃てばいいんだ?",
  ["Cue_E2_3A_Junkyard_Bottle04FailChloe_IGE_Chloe_040"] = "もういいよ 自分でやる。 バンパー撃つぞ",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_020"] = "ビンは無傷だぞ",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_030"] = "おもしろかったけど ビンには当たってないな",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_050"] = "早くビンをフッ飛ばそうぜ",
  ["Cue_E2_3A_Junkyard_Bottle04Success_IGE_Chloe_020"] = "了解! 車輪よ さらば!",
  ["Cue_E2_3A_Junkyard_Bottle04Success_IGE_Max_010"] = "左のタイヤを撃ってみて",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_001"] = "むしろマックスが神になれる… やりたい放題だ!",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_003"] = "失敗したら 巻き戻してやり直す。 簡単だろ!",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_005"] = "人の命を救っといて よく言うよ。 次は何してやろっか…",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_006"] = "あたしは射撃場を作るんだよ。 しかし ホントに謎の能力だよな…",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_009"] = "責任は退屈だ。 あたしがおもしろくしてやるよ。 任せとけ",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_002"] = "ダメだよ。 どういう仕組みなのかも分からないし すぐ使えなくなるかも",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_004"] = "まあね。 その前にこの力を理解しなきゃ。 偉大なる力には偉大なる責任が…",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_007"] = "神様から授かったのかも… なんてね",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_008"] = "なんで私がビンを集める役なの? 納得いかない",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_010"] = "出来事をリセットして 時空をじゃんじゃん曲げまくり… |ついでに歴史も変えてる。 たいしたことないよ",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase02_Chloe_001"] = "射撃場を作るから ビン探してきて",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Chloe_010"] = "マックスの番な!",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Chloe_030"] = "ったく もう時間なんか気にすることないだろ!",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Max_020"] = "もう帰ったほうが…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_040"] = "失せろ フランク",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_060"] = "一緒にすんじゃねえよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_080"] = "金は返す",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_110"] = "そのブレスレット…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_130"] = "それはレイチェルのだ… なんでてめえが持ってんだ!?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_150"] = "ふざけんな! 盗んだんだろ! 今すぐ返しやがれ!",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_020"] = "よう。 悪巧みの最中か?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_030"] = "銀行でも襲う計画かな?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_050"] = "ああ こいつは失礼。 邪魔するつもりはなかったんだ |銃声が聞こえたもんでね |\"火遊び\"とは ほほえましい。 ガキの頃 思い出すぜ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_070"] = "同類だよ。 お前も金に困ってる… 俺からクソほど借金するぐらいな。 ああ?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_090"] = "みんなそう言うんだ。 返すあてもねえくせによ…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_100"] = "お前 なに隠してんだ。 見せてみろ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_120"] = "うるせえ。 ダチからのもらいもんだよ。 てめえには関係ねえ。 だが…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_140"] = "言っただろ。 もらったんだよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_160"] = "それ以上近づくと後悔するぜ。 下がれ。 切り刻まれてえか?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_180"] = "おいおい… やめとけよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Max_010"] = "ほら やってみろ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Max_170"] = "やめて… やめないと 撃つから",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_060"] = "どうしてくれんだよ…",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_080"] = "ネイサンに襲われたらどうすんだ |クソオヤジからもう 1 丁盗むのはさすがに無理だぞ",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_100"] = "分かってる… 正直… あたしもこうなって内心ホッとしてるよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_110"] = "銃なら他にもあるし…",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_120"] = "行こう。 すっかりシラけちまった… |ま フランクはもう しばらくは来ないよ |ヤツの狙いは金だ",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_010"] = "どうしたんだ? 撃ってみろよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_020"] = "笑かすぜ。 まったく とんだ茶番だな",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_040"] = "いい得物だ。 これで利子は帳消しにしてやるよ。 よかったな",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_050"] = "いいか 残りは金曜までに用意しろ |でなきゃ もらった この\"利子\"で取り立てるぜ |それじゃあ 仲よくな",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Max_070"] = "ごめん… 体が動かなくて…",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Max_090"] = "銃を人に向けたのなんて生まれて初めてだったから… 怖かったの",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Chloe_070"] = "ありがとな。 守ってくれて",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Chloe_080"] = "行こう。 すっかりシラけちまった… |ま フランクはもう しばらくは来ないよ |ヤツの狙いは金だ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_010"] = "ハハハ 笑わせてくれるぜ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_030"] = "覚えておくからな |てめえは俺を殺そうとした |言っておくが俺は根に持つタイプなんだ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_045"] = "金は金曜までに用意しろ |今度こんなマネしやがったら タダじゃ済まねえからな",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_050"] = "弾は入れとけよ。 クソガキが…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Max_060"] = "ごめん…",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_010"] = "よし… 今度こそマックスの番な",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_030"] = "なにいい子ぶってんだよ",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_040"] = "まったくガキじゃあるまいし! 大丈夫だって。 あたしがついてるから",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Max_020"] = "やっぱり… やめとこうかな",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Chloe_010"] = "なんだよ…",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Chloe_030"] = "ちゃんと集中してくれよ。 せっかくの力… 人のために使わなきゃ",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Max_020"] = "私のせいじゃないよ",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_010"] = "すっげえ! 見たかよ今の!?",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_030"] = "ヤベー アガる!",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_040"] = "よし 2 本目だ…",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Max_020"] = "見たよ",
  ["Cue_E2_3A_Junkyard_Gun02_Fail_Chloe_010"] = "ダメじゃん",
  ["Cue_E2_3A_Junkyard_Gun02_Success_Chloe_010"] = "見てろよ ネイサン",
  ["Cue_E2_3A_Junkyard_Gun02_Success_Chloe_020"] = "ヤッバいなこれ! よし 次はトリックショットだ。 どこに撃とうか…",
  ["Cue_E2_3A_Junkyard_Gun03_Fail01_Chloe_010"] = "はあ～…",
  ["Cue_E2_3A_Junkyard_Gun03_Fail02_Chloe_010"] = "ダメだ…",
  ["Cue_E2_3A_Junkyard_Gun03_Fail02_Chloe_020"] = "んだよ…",
  ["Cue_E2_3A_Junkyard_Gun03_Fail03_Chloe_020"] = "んー いい音ー!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_010"] = "やっべえ!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_030"] = "最高に楽しい!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_050"] = "まだまだ! もっとすごいのに挑戦しよう!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_020"] = "才能あるね",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_040"] = "満足した?",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_060"] = "それじゃ あの廃車を使ってみるのはどう?",
  ["Cue_E2_3A_Junkyard_Gun04_Fail01_Chloe_010"] = "これはこれでヤバいけど ビンは無傷だ",
  ["Cue_E2_3A_Junkyard_Gun04_Fail02_Chloe_010"] = "当たった! 弾が当たった! 早くなんとかして!",
  ["Cue_E2_3A_Junkyard_Gun04_Fail02_Max_020"] = "クロエ 大丈夫!? 今巻き戻すから!",
  ["Cue_E2_3A_Junkyard_Gun04_Fail03_Chloe_010"] = "危ないから隠れてな!",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_010"] = "キマったな",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_020"] = "マジ信じらんないよ。 スーパーヒーローみたいだ! |よし 今度はマックスの番な",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_040"] = "また鼻血… 大丈夫か?",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Max_030"] = "ちょっと待って…",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Max_050"] = "ちょっと… 気分が… 悪いかも…",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_020"] = "これはマジでヤバいぞ!",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_040"] = "時間巻き戻せよ! ちゃんとできるか実験だ!",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_060"] = "遅いぞ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_080"] = "だったら 怒られるようなことしなきゃいい",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_090"] = "さて \"別荘\"へようこそ。いいとこだろ?",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_110"] = "しっかし 親友と再会できたうえ 超能力者になってるとは…",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_130"] = "だから 今のうちに遊ぶ!",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_150"] = "はあ…",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_160"] = "信用しろよ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_180"] = "超能力者だろ いちいちビビるなって。 ただの実験道具だ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_200"] = "危険なヤツがいるからこそ あたしも銃を持つんだよ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_220"] = "マックスの力こそ革命だよ。 だから 使い道を見極めなきゃ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_230"] = "飲む?",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_250"] = "お子ちゃまだな。 ぜんぜん変わってない",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_255"] = "よし やるか。 まず 空きビンを 5 本集めてよ",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_270"] = "大丈夫だって。 空きビンを 5 本な。 よろしく",
  ["Cue_E2_3A_Junkyard_Insertion_Max_010"] = "ちょっと待ってよ!",
  ["Cue_E2_3A_Junkyard_Insertion_Max_030"] = "待ってってば! プレゼントを取ってくるから!",
  ["Cue_E2_3A_Junkyard_Insertion_Max_050"] = "待ってってば",
  ["Cue_E2_3A_Junkyard_Insertion_Max_070"] = "なんかやるたびに怒られてる気がする",
  ["Cue_E2_3A_Junkyard_Insertion_Max_100"] = "退廃的だね。 クロエにぴったり",
  ["Cue_E2_3A_Junkyard_Insertion_Max_120"] = "すぐ元に戻るかも…",
  ["Cue_E2_3A_Junkyard_Insertion_Max_140"] = "ちょっと本気? |昨日の今日で 銃なんてもうたくさんだよ |そんなの持ち歩くのやめなって…",
  ["Cue_E2_3A_Junkyard_Insertion_Max_170"] = "してるけど… 銃は嫌い",
  ["Cue_E2_3A_Junkyard_Insertion_Max_190"] = "その銃… デイビッドから盗んだんでしょ… |この町の住民はみんな武装してるの?",
  ["Cue_E2_3A_Junkyard_Insertion_Max_210"] = "そんな革命家みたいに言われても…",
  ["Cue_E2_3A_Junkyard_Insertion_Max_240"] = "いらない",
  ["Cue_E2_3A_Junkyard_Insertion_Max_260"] = "飲みながら?… 危ないよ",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_005"] = "ご苦労さん",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_010"] = "待った。 もう 1 本…",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_030"] = "一発も外さず 全部のビンに当てる",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_040"] = "そこでマックスの出番だ",
  ["Cue_E2_3A_Junkyard_IntroGun_Max_020"] = "ホントにやる気…?",
  ["Cue_E2_3A_Junkyard_Preparing_Chloe_010"] = "ちょい休憩!",
  ["Act_E2_3B_Railroad_BreakingMechanism_VoiceOver01_Max_010"] = "クロエに手を貸さなきゃ",
  ["Act_E2_3B_Railroad_CHChloe_Interact01_Max_010"] = "オノを使って何する気… 他の方法があるでしょ マックス!",
  ["Act_E2_3B_Railroad_CHChloe_Look01_Max_010"] = "私の細い腕じゃ引っ張り上げられないよ!",
  ["Act_E2_3B_Railroad_CHChloe_Look02_Max_010"] = "もうこうなったら 自分でクロエを引っ張り上げるしかないよ!",
  ["Act_E2_3B_Railroad_CHMax_Interact01_Max_010"] = "どのケーブルなの?",
  ["Act_E2_3B_Railroad_CHMax_Look01_Max_010"] = "どれを切ればいいの…",
  ["Act_E2_3B_Railroad_CHMax_VoiceOver01_Max_010"] = "ケーブルを切る道具を探そう",
  ["Act_E2_3B_Railroad_CableDrum_Interact01_Max_010"] = "スイッチレバーをダメにしちゃったみたいだ |クロエを助けるのに もっと別の方法はないかな…",
  ["Act_E2_3B_Railroad_CableDrum_Interact02_Max_010"] = "ドラムが何かに引っかかってる!",
  ["Act_E2_3B_Railroad_CableDrum_Look01_Max_010"] = "どうだろう… 重すぎるんじゃ…? スイッチレバーの真上だし…",
  ["Act_E2_3B_Railroad_CableGreen_Interact01_Max_010"] = "ライトか。 違う これじゃない…",
  ["Act_E2_3B_Railroad_CableRed_Interact01_Max_010"] = "よし 当たり!",
  ["Act_E2_3B_Railroad_CableYellow_Interact01_Max_010"] = "うわ ショートしちゃった",
  ["Act_E2_3B_Railroad_Cables_Interact01_Max_010"] = "ここでオノを使っても 意味がないような…",
  ["Act_E2_3B_Railroad_Cables_Interact02_Max_010"] = "どのケーブルなの?",
  ["Act_E2_3B_Railroad_Cables_Look01_Max_010"] = "どれを切ればいいの…",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver01_Max_010"] = "竜巻の幻覚は見るし クロエはヤバいし…!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver01_Max_020"] = "クロエが危ない! なんとかしないと!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver02_Max_010"] = "クロエを助けないと!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver03_Max_010"] = "小屋になにか役に立つものはないかな?",
  ["Act_E2_3B_Railroad_Crowbar_Interact01_Max_010"] = "これは使えそう!",
  ["Act_E2_3B_Railroad_Crowbar_Look01_Max_010"] = "バールだ! これを使おう",
  ["Act_E2_3B_Railroad_DoorLock_Interact01_Max_010"] = "よし 開けられた",
  ["Act_E2_3B_Railroad_DoorLock_Look01_Max_010"] = "よかった これで向こう側からこじ開けなくてもすむね",
  ["Act_E2_3B_Railroad_FuseBox_Interact01_Max_010"] = "よし カギがかかってない!",
  ["Act_E2_3B_Railroad_FuseBox_Look01_Max_010"] = "ヒューズボックス 開くかな?",
  ["Act_E2_3B_Railroad_Hatchet_Interact01_Max_010"] = "これで色々切れるかな?",
  ["Act_E2_3B_Railroad_Hatchet_Look01_Max_010"] = "刃がかなり鋭そう… 何かに使えるかな…",
  ["Act_E2_3B_Railroad_Pliers_Interact01_Max_010"] = "サバイバル番組みたい",
  ["Act_E2_3B_Railroad_Pliers_Look01_Max_010"] = "ペンチ 発見!",
  ["Act_E2_3B_Railroad_ReleasingMechanism_VoiceOver01_Max_010"] = "できる… 私なら… レバーを引いて…",
  ["Act_E2_3B_Railroad_ShedDoor_Interact01_Max_010"] = "やった!",
  ["Act_E2_3B_Railroad_ShedDoor_Interact02_Max_010"] = "全然動かない!",
  ["Act_E2_3B_Railroad_ShedDoor_Look01_Max_010"] = "カギがかかってる。 こじ開けないと",
  ["Act_E2_3B_Railroad_Switching_Interact01_Max_010"] = "1 ミリも動かない!",
  ["Act_E2_3B_Railroad_Switching_Interact02_Max_010"] = "なにこれ バールでも全然動かない!",
  ["Act_E2_3B_Railroad_Switching_Interact03_Max_010"] = "よし! やった!",
  ["Act_E2_3B_Railroad_Switching_Look01_Max_010"] = "今すぐスイッチレバーを引かなきゃ!",
  ["Act_E2_3B_Railroad_Wedge_Interact01_Max_010"] = "これでドラムが動かせる",
  ["Act_E2_3B_Railroad_Wedge_Interact02_Max_010"] = "引っかかってる! 何か使って動かさなきゃ",
  ["Act_E2_3B_Railroad_Wedge_Look01_Max_010"] = "ドラムは留め具で固定されてる…",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_001"] = "マックス! 助けて!",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_002"] = "早く何とかしてくれ!",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_003"] = "死にたくない!",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_039"] = "フランクに見つかっちまったから 新しい\"別荘\"は必要だな… |少しは落ち着いたか?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_044"] = "ごめんな… でもフランクはハッタリだけだ |ヤツは金と飼い犬のことしか頭にない",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_047"] = "こんなの あたしからしたら日常茶飯事だ |奴への借金だって はなから返す気ないさ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_049"] = "フランク・バワーズは\"売人\"だ |クソオヤジに見つかるとマズいもんの調達先だよ |昔 ツルんでた",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_050"] = "フランク・バワーズは… この町で\"売人\"やってる男だ |ヤツとは ときどきツルんでた",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_053"] = "なにキモい想像してんだよ。 だいたい向こうもそんな気ねえし |レイチェルと町を出たくて 金を借りただけだ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_054"] = "バーカ。 レイチェルと町を出るための資金源だよ |フランクは金を持ってた。 そんだけだ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_056"] = "でも ヤツがレイチェルのブレスレットを持ってた理由は… 絶対突き止める",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_062"] = "相性抜群だよ |レイチェルもアーティスト肌でさ… センスがよかっ… センスがいいんだ |口が減らないとこもそっくり。 きっと 3 人で親友になれるよ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_064"] = "マックスとこんな話するなんてヘンな感じだよ |5 年ぶりなのにさ… 全然そんな気しない |レイチェルもいたらよかったな…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_041"] = "昔みたいに 秘密基地をつくって 閉じこもりたい…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_042"] = "まだ体が震えてるよ… ホントに怖かった…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_043"] = "私たち フランクに狙われるのかな",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_045"] = "クロエ… 本気で言ってるの? |銃を取られて 脅されたんだよ? |向こうは何するか分からないよ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_046"] = "クロエ 分かってる? |私 人を撃とうとしたんだよ? |時を巻き戻せるからって 何してもいいわけじゃない… |もう銃はたくさん…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_048"] = "ねえ フランクとはいったいどういう関係なの? |そもそもあの人 何やってる人?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_051"] = "ツルむって… まさかクロエ…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_052"] = "ああいうタイプが好きなの…?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_055"] = "そっか…",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_057"] = "だけど気をつけないと。 やるなら フランクにバレないように 動きを探ろう",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_058"] = "どうするべきか私には分からないよ |いろんなことがありすぎて… 脳みそが働かない",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_060"] = "レイチェルと私 友だちになれるかな?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_061"] = "なんで? きっと嫌われるよ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_063"] = "5 年ぶりに話しても 何も変わらない… そんなクロエこそが 私の親友だよ",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_065"] = "落ち着かないよ。 すごく怖い。 フランクに狙われたらどうするの?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_066"] = "クロエがそう言うなら きっとなれるね。 大丈夫 もうすぐ会えるよ",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Chloe_020"] = "また助かった… すげえ… マジで命の恩人だよ!",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Chloe_040"] = "ケツと足に木のトゲがブッ刺さったよ もうちょっとていねいに助けろって… |あの電車の進路も変えちまったし… 知ーらね",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Max_010"] = "危なかった…!",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Max_030"] = "大丈夫?",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_010"] = "人気のない静かな穴場で朝を過ごした感想は?",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_030"] = "命の恩人のためなら よろこんで運転手をやらせてもらうよ",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_050"] = "関係ないよ… あたしたちさえ ずっと一緒なら",
  ["Cue_E2_3B_Railroad_Extraction_Max_020"] = "クロエと遊べて楽しかったけど 授業始まるまでに学校に戻らないと…",
  ["Cue_E2_3B_Railroad_Extraction_Max_040"] = "でもこの力… いつまでもつか分からないよ",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Chloe_050"] = "マックス! 助けて! 足が抜けない!",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_010"] = "完璧…",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_020"] = "ウソでしょ…",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_030"] = "あの竜巻は夢じゃなかった",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_040"] = "あの音は… 電車が来る! マズい!",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_060"] = "どうしたの!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_010"] = "まさかフランクに銃つきつけるとはな!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_030"] = "時間を巻き戻して銃をあいつのケツに突っ込んでやりゃよかったんだよ |ガツンと!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_050"] = "銃をフランクに渡しちまうなんて… 信じらんないよ",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_070"] = "怒ってない。 期待を裏切られるのも すっかり慣れっこだ |せっかく護身用だったのに…",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_090"] = "マックスがいてよかった",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_110"] = "少し休もうか",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_120"] = "別世界に来たみたいだろ? ずっとここにいたくなる…",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_020"] = "もう思い出したくないよ… 弾はいってなくてよかった…",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_040"] = "やだよ… あ 気をつけて",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_060"] = "また怒ってる… じゃあ私どうすればよかったの?",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_080"] = "私がいるから大丈夫",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_100"] = "ありがと |でも… クロエ… なんでフランクみたいな怪しい人と関わってるの? |クロエらしくないよ",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_010"] = "線路ってなんか落ち着くんだ… なんでだろな",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_030"] = "さすが詩人だね",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_050"] = "もうなってる。 あとは勇気を出すだけだ",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Max_020"] = "ケルアックなら… |「旅のロマンが感じられるから」って答えるよ… |夜陰に響く汽笛の音…",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Max_040"] = "なりたいのは写真家だけど",
  ["Cue_E2_3B_Railroad_Switching_Interact03_Chloe_030"] = "電車の進路変えちまったな… 問題なきゃいいけど",
  ["Cue_E2_3B_Railroad_Switching_Interact03_Max_020"] = "そうだね  もちろん",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_010"] = "マックス! 急いで!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_020"] = "なんとかしてくれ!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_030"] = "マックス!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_040"] = "電車が来る! 早くして!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_050"] = "マックス 助けて!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_060"] = "早く!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_070"] = "いや…",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_080"] = "いやあああ!",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_002"] = "なあ やっぱマックスの力と昨日の雪は関係あるんじゃないか? きっと竜巻も…",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_005"] = "何のんきなこと言ってんだ |マックスはあたしを 2 回も助けた |未来を変えたんだぞ! カオス理論 知らないのか?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_020"] = "それは 5 年前の話 |量子物理学的に考えて 今のマックスはまさに台風の目だ",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_021"] = "「何が起きても不思議じゃない」ってことだ。 マックスの場合は特に",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_023"] = "まさに「ストレンジ・アトラクター」だよ |この学校じゃそんなことも教えないのか? |竜巻に季節外れの雪にタイムリープ… |滅亡へのカウントダウンだ! |今のうちに遊びまくるしかないな",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_001"] = "もうさっきのこと忘れたの?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_003"] = "どうかな… 規則性がないよ",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_004"] = "「きっと」 何? |雪が降ったら 町が吹き飛ぶほど巨大な竜巻が来るの? まさか",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_018"] = "なによ偉そうに 数学嫌いなくせに",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_019"] = "えーっと 「すべては 予測不能」ってことでしょ?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_022"] = "なんで私が? こんな小さな町の ただのオタク少女だよ",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_024"] = "要は「あたしに任せな」ってことですね 先生",
  ["Cue_E2_4A_CampusA_CarArriving_Chloe_020"] = "こっちこそ。 退屈じゃなかったか?",
  ["Cue_E2_4A_CampusA_CarArriving_Chloe_040"] = "最悪から最高の一週間になったな",
  ["Cue_E2_4A_CampusA_CarArriving_David_060"] = "何をたくらんでやがる…",
  ["Cue_E2_4A_CampusA_CarArriving_Max_010"] = "送ってくれてありがとう。 遅刻せずに済みそうだよ",
  ["Cue_E2_4A_CampusA_CarArriving_Max_030"] = "もうさっきのこと忘れたの?",
  ["Cue_E2_4A_CampusA_CarArriving_Max_050"] = "最強コンビの復活だもん!",
  ["Act_E2_4B_ArtClass_ArcadiaPicture01_Look01_Max_010"] = "ここからだと アルカディア・ベイが壮大に見える…",
  ["Act_E2_4B_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "この辺の森は写真でもなんだか謎めいて見える…",
  ["Act_E2_4B_ArtClass_CHAlyssa_Look01_Max_010"] = "アリッサって授業のために生きてる感じ",
  ["Act_E2_4B_ArtClass_CHDana_Look01_Max_010"] = "デーナ 注目されて嬉しそう",
  ["Act_E2_4B_ArtClass_CHDaniel_Look01_Max_010"] = "ダニエルはいつも輪の外で見てる…",
  ["Act_E2_4B_ArtClass_CHHayden_Look01_Max_010"] = "ヘイデンは嫌いになれない だっていつもマイペースだし",
  ["Act_E2_4B_ArtClass_CHMax_VoicesOver01_Max_010"] = "ジェファソン先生の授業までちょっと時間あるから うろうろしようかな",
  ["Act_E2_4B_ArtClass_CHMax_VoicesOver01_Max_020"] = "エリートってパーティしないと生きていけないの? |またネイサンが誰かにクスリを飲ませるかも…",
  ["Act_E2_4B_ArtClass_CHNathan_Look01_Max_010"] = "校長先生にあのことを言ったのに どうして退学になってないの?",
  ["Act_E2_4B_ArtClass_CHNathan_Look02_Max_010"] = "ネイサンと銃のこと 校長先生に言えばよかった…",
  ["Act_E2_4B_ArtClass_CHStella_Look01_Max_010"] = "ステラはいざこざに首を突っ込まない",
  ["Act_E2_4B_ArtClass_CHTaylor_Look01_Max_010"] = "テイラーの才能は好きだけど 本人は…",
  ["Act_E2_4B_ArtClass_CHTrevor_Look01_Max_010"] = "トレバーが周囲をうかがってる…",
  ["Act_E2_4B_ArtClass_CHVictoria_Look01_Max_010"] = "昨日ビクトリアをバカにしたから なんだか気まずいな…",
  ["Act_E2_4B_ArtClass_CHVictoria_Look02_Max_010"] = "無視されてる。 でも昨日話せてよかったな",
  ["Act_E2_4B_ArtClass_DanielDrawing_Look01_Max_010"] = "デーナのスケッチ すごくいい。 ダニエルは本物だよ",
  ["Act_E2_4B_ArtClass_EverydayHeroesPoster_Look01_Max_010"] = "コンテストの作品 時間切れだな。 皮肉だけど",
  ["Act_E2_4B_ArtClass_GroupPhoto_Look01_Max_010"] = "最初の週に ジェファソン先生が撮ってくれたクラス写真 |私は写りたくなかったけど 先生が実際に写真を撮る姿を見られて |すごくうれしかったな",
  ["Act_E2_4B_ArtClass_JeffPoster01_Look01_Max_010"] = "ジェファソン先生が撮った雑誌の表紙。 さすがだなあ",
  ["Act_E2_4B_ArtClass_JeffPoster02_Look01_Max_010"] = "ジェファソン先生の作品を見てると 私も頑張ろうって思えてくる",
  ["Act_E2_4B_ArtClass_JeffersonCamera_Look01_Max_010"] = "ジェファソン先生のカメラはやっぱり違うな… |これってたしか 2 万ドルはするはず… |完璧なデジタル写真が撮れるんだろうな |私は インスタントカメラ派だけど",
  ["Act_E2_4B_ArtClass_KateChair_Look01_Max_010"] = "ケイト 授業に来ないのかな。 心配だな…",
  ["Act_E2_4B_ArtClass_ObjectOnMaxDesk_Look01_Max_010"] = "自分の本が出せるなんて 先生はやっぱりすごいよね",
  ["Act_E2_4B_ArtClass_Printer_Look01_Max_010"] = "こんなプリンターで 自分の写真をプリントしてみたいな… |個展開けるぐらいたっくさん! |ま もっとうまくなってからの話だけど…",
  ["Act_E2_4B_ArtClass_SeeDavid_VoiceOver01_Max_010"] = "どうしてデイビッドがケイトの写真を? 意味分かんない… 何がしたいの…?",
  ["Act_E2_4B_Corridor_BlackwellNotice01_Look01_Max_010"] = "ここに居れるだけラッキー だよね",
  ["Act_E2_4B_Corridor_BlackwellNotice02_Look01_Max_010"] = "でも銃は持って来ていいんでしょ?",
  ["Act_E2_4B_Corridor_BlackwellNotice03_Look01_Max_010"] = "必死だなあ もう入学してるのに",
  ["Act_E2_4B_Corridor_Board02_Look01_Max_010"] = "掲示板に貼ってあるものを見ると その学校のことがよく分かるね",
  ["Act_E2_4B_Corridor_CHCourtney_Look01_Max_010"] = "コートニーってビクトリアとボルテックス・クラブに尽くしてる",
  ["Act_E2_4B_Corridor_CHDavid_Look01_Max_010"] = "デイビッドは一体何をたくらんでるんだろう…",
  ["Act_E2_4B_Corridor_CHEvan_Look01_Max_010"] = "エバンの ボルテックス・クラブなんて気にしないって姿勢 すごく好き",
  ["Act_E2_4B_Corridor_CHJefferson_Look01_Max_010"] = "先生 いろんな問題のある生徒の相手してるんだろうな",
  ["Act_E2_4B_Corridor_CHJuliet_Look01_Max_010"] = "ジュリエット ザッカリーに容赦ないな",
  ["Act_E2_4B_Corridor_CHJustin_Look01_Max_010"] = "ジャスティンはいつも眠そう",
  ["Act_E2_4B_Corridor_CHLogan_Look01_Max_050"] = "まったく 今度はちゃんと避妊しなよね",
  ["Act_E2_4B_Corridor_CHLuke_Look01_Max_010"] = "ルークって電話を盾にして人を避けてる",
  ["Act_E2_4B_Corridor_CHPrincipal_Look01_Max_010"] = "ウェルズ校長っていつも大変そう",
  ["Act_E2_4B_Corridor_CHZachary_Look01_Max_010"] = "ザッカリーはフットボールのことしか考えてなさそう",
  ["Act_E2_4B_Corridor_GlobalWarmingNote_Look01_Max_010"] = "行ったらなにか学べるかな…",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_010"] = "どうしてフランクがあなたのブレスレットを持ってたの?",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_020"] = "フランクに借金とかあったの…?",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_030"] = "もっと早くクロエと逃げてほしかった",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_040"] = "レイチェル あなたに何があったのか突き止める",
  ["Act_E2_4B_Corridor_MaxLocker_Look01_Max_010"] = "人にロッカーの中 見られるのは好きじゃないな…",
  ["Act_E2_4B_Corridor_Plan01_Look01_Max_010"] = "こんなの暗記してる人 いるのかな? でも実際は みんなしたほうがいいよね",
  ["Act_E2_4B_Corridor_Poster01_Look01_Max_010"] = "献血 したほうがいいよね?",
  ["Act_E2_4B_Corridor_Poster02_Look01_Max_010"] = "こんなポスターでいじめがなくなれば苦労しないって",
  ["Act_E2_4B_Corridor_Poster03_Look01_Max_010"] = "銃はおうちに置いてきましょう!",
  ["Act_E2_4B_Corridor_Trophy01_Look01_Max_010"] = "すごいトロフィー。さすがは「ビッグフット」 名前負けしてないね",
  ["Act_E2_4B_Corridor_Trophy02_Look01_Max_010"] = "水泳にはだいぶ力入れてるな。 カワウソ かわいいからいいけど |がんばれオッターズ!",
  ["Act_E2_4B_Corridor_VortexBanner_Look01_Max_010"] = "入会か 死か!",
  ["Act_E2_4B_Corridor_VortexPoster01_Look01_Max_010"] = "こんなの信じる人いる?",
  ["Act_E2_4B_Corridor_VortexPoster02_Look01_Max_010"] = "「ボルテックスの侵攻」ってとこか",
  ["Act_E2_4B_Corridor_VortexPoster03_Look01_Max_010"] = "ネイサンと世界の終わりを迎えるなんて絶対イヤだ",
  ["Act_E2_4B_Corridor_VortexPoster05_Look01_Max_010"] = "普通の子だったらパーティを楽しみにするんだろうな",
  ["Act_E2_4B_Corridor_VortexPoster06_Look01_Max_010"] = "本当に竜巻がきたら マジで世界の終わりだよね",
  ["Act_E2_4B_Corridor_VortexPoster07_Look01_Max_010"] = "人に銃を向けた直後にパーティ? セレブは気楽だね",
  ["Act_E2_4B_Corridor_WarrenText_VoiceOver01_Max_010"] = "時間あるし ウォーレンに会いに実験室に行こうかな",
  ["Act_E2_4B_SciClass_Beckers_Look01_Max_010"] = "「脳を持ってこい!」ってね",
  ["Act_E2_4B_SciClass_CHBrooke_Look01_Max_010"] = "ブルックはいつも私に対してよそよそしい… なんでだろ",
  ["Act_E2_4B_SciClass_CHGrant_Look01_Max_010"] = "グラント先生はいい人だし 頭がいい 本物の\"先生\"",
  ["Act_E2_4B_SciClass_CHWarren_Look01_Max_010"] = "魔術師さんががんばってる",
  ["Act_E2_4B_SciClass_CHWarren_Look02_Max_010"] = "笑っちゃだめだけど ほんとおかしい",
  ["Act_E2_4B_SciClass_CHWarren_Look03_Max_010"] = "失敗したみたい",
  ["Act_E2_4B_SciClass_CHWarren_Look04_Max_010"] = "大成功ってやつね!",
  ["Act_E2_4B_SciClass_FishTank_Interact01_Max_010"] = "なにも起きないか…",
  ["Act_E2_4B_SciClass_FishTank_Look01_Max_010"] = "ガラスに触ったらみんな起きそう",
  ["Act_E2_4B_SciClass_PeriodicTable_Look01_Max_010"] = "周期表… そもそも「周期」ってなに?",
  ["Act_E2_4B_SciClass_SciencePoster01_Look01_Max_010"] = "ウォーレンを小さく丸めてテストに持ちこみたい",
  ["Act_E2_4B_SciClass_SciencePoster02_Look01_Max_010"] = "ダ・ヴィンチは天才",
  ["Act_E2_4B_SciClass_Skeleton_Look01_Max_010"] = "本物のガイコツは使わないの?",
  ["Act_E2_4B_SciClass_WarrenPhoto_Photo_Max_010"] = "ちょっと楽しかった。 ウォーレンはオタクモード全開の時いい感じ",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Dana_010"] = "きれいに撮ってね ヘイデン。 このポーズ どうかしら?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Dana_030"] = "テイラー どう?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Hayden_020"] = "んー最高だね デーナ。 左向いて。 じゃあ次は右。 目線くれるかな?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_060"] = "ああ きっと校長に言いつけると思うね",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_070"] = "だから何だって話だが",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_090"] = "マックスの話なんか 誰も聞きやしねえっつうのに…",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Taylor_040"] = "きれいに撮れたよ",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_050"] = "ここに座ってたら マックスは怒ると思う?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_080"] = "ジェファソン先生に言うんじゃない? くっだらない",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_100"] = "シーッ! 聞こえるよ",
  ["Cue_E2_4B_ArtClass_BeginLesson_Jefferson_110"] = "授業中はスマホ禁止だぞ! しまいなさい",
  ["Cue_E2_4B_ArtClass_CHAlyssa_Phase01_Alyssa_001"] = "あとにして。 今考え事してるから",
  ["Cue_E2_4B_ArtClass_CHDanaDial_Phase01_Dana_056"] = "あとにしてくれるかな。 今フォトセッション中なの",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_002"] = "ヘイデンの「撮影会」が済んだら デーナをスケッチするんだ",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_010"] = "大丈夫 気にしてないよ",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_013"] = "昨日のスケッチ 気に入ってもらえたかな",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_014"] = "君にはもうモデルは頼まないから安心して",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_017"] = "すごくたくさん「イイネ!」がついたんだよ! あ 赤くなった!",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_019"] = "君の肖像画はいつかルーブル美術館のダニエル・ダ・コスタ翼に飾られるよ |じゃ またね",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_001"] = "何してるの?",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_009"] = "昨日スケッチ断ったこと怒ってる? ごめんね… 私 恥ずかしがり屋で…",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_015"] = "うん! プロフィール写真にしちゃった",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_016"] = "うん。 でもね 私… 人に注目されるのがすごく苦手で…",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_018"] = "もう!",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_020"] = "本当にごめんね… |才能ある人にモデルになってって頼まれると気後れしちゃって…",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_021"] = "今度一緒に 美術史の話でもしようよ",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase02_Daniel_001"] = "今スケッチしてほしいの? んーまた今度でいいかな",
  ["Cue_E2_4B_ArtClass_CHHayden_Phase01_Hayden_001"] = "悪いけど 今はちょっと忙しいんだ",
  ["Cue_E2_4B_ArtClass_CHTaylor_Phase01_Taylor_001"] = "フォトセッション中だから あとにして",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale01_020"] = "行くに決まってるじゃん! 服も買ったし",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale02_030"] = "ビクトリアたちもパーティ用の服 買ってたよ",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale03_050"] = "昨日の雪 なんだったの?",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale04_060"] = "ねー。 異常気象にもほどがあるよ",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenMale02_010"] = "ボルテックス・クラブのパーティ 君も行くの?",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenMale02_040"] = "それで思い出した。 ネイサンからブツを仕入れなきゃ",
  ["Cue_E2_4B_ArtClass_Interrupt01_Zachary_010"] = "おい! 女子寮がすごい騒ぎになってるぞ! 来てみろよ!",
  ["Cue_E2_4B_ArtClass_Interrupt02_Jefferson_010"] = "ザック! 授業中だぞ! 邪魔をするな!",
  ["Cue_E2_4B_ArtClass_Interrupt05_Jefferson_010"] = "みんな! 勝手に席を立つんじゃない!",
  ["Cue_E2_4B_ArtClass_Interrupt06_Jefferson_010"] = "まったく…",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Alyssa_040"] = "具合が悪いって言ってました",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_010"] = "そこの君。 このクラスの生徒じゃないな? 早く出なさい |他のみんなは席について |今日も話すことがたくさんある |… さて みんなそろってるか…?",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_020"] = "ケイトは? どうしたんだ?",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_050"] = "ネットで拡散されている動画が話題になっているようだな |映っているのはある生徒… 友だちかもしれない |自分の実像とかけ離れたイメージが世間にさらされるのはどんな気分だろう |自分の欠点から目をそらし 他人を批判するのは簡単だ",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_060"] = "リアリティショーの影響もあるだろう |だが 批判すべきは自分自身の行動だけだ",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_070"] = "例えばコンテストの課題。 提出せずに後悔するのは 自分だぞ",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_080"] = "まだ出してない人がいるな。 マックス 君もその一人だ",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_090"] = "さて みんなシラバスを読んできたな |今日のテーマは「キアロスクーロ」だ |光と影のコントラストを指す |これによって写真には 視覚に訴える力が宿る",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_100"] = "陰と陽の関係とも言える |モノクロ写真は 白と黒のコントラストによって魅力を発揮する |まあ 厳密には…",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Victoria_030"] = "あら 有名人は大変ですね",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_010"] = "ああ…",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_020"] = "授業が始まるから またかけ直す",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_030"] = "だから今はマズいんだ。 頼むからあとにしてくれ",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_040"] = "分かった",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_060"] = "ああ 分かった",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_070"] = "だから もうすぐ授業が始まるんだ 切るぞ",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_080"] = "ああ… 分かった。 分かったから",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_090"] = "ああ… 分かってる。 分かってるよ",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_100"] = "あとでかけ直す",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_110"] = "もう切るぞ! 授業が始まる…",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_030"] = "もう無理",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_050"] = "そこ 私の席なんだけど",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_080"] = "なんなの…",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_110"] = "もう無理",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_130"] = "そこどいて。 座るから",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_190"] = "思ってないよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_210"] = "なんでもいいけど そこどいてくれる?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_260"] = "返す言葉もないよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_010"] = "ビクトリア 気をつけろよ。 汚ねえタレコミ屋のお出ましだぜ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_040"] = "怖ええー! お友だちができた途端強気かよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_070"] = "せいぜい 背後に気をつけるんだな",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_090"] = "ウワサをすれば ご本人の登場だ。 アーティスト気取りのマックス",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_120"] = "いいねえ! 女同士のケンカはいつ見ても興奮するぜ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_150"] = "どいてやろうぜ。 ここしか居場所ねえんだ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_200"] = "ただの構ってちゃんだからな",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_220"] = "いいか てめえ… 覚悟しとけよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_020"] = "パパラッチでしょ。 あの写真 消さないとタダじゃ済まないわよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_060"] = "調子に乗らないで。 覚えときなさい",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_100"] = "ただのパパラッチでしょ。 あの写真 消さないとタダじゃ済まないわよ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_140"] = "どうする? どくべき?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_180"] = "私と親友になれたとでも思ってた?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_210"] = "どうぞ。 記念に自撮りでもすれば?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_250"] = "この教室にいるヒヨッコたちと同じ",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_290"] = "私と仲よくなれたと思った? 笑わせないでよ",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Max_008"] = "ウォーレン",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Max_020"] = "ケイトは今 ちょっと大変で…",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_005"] = "今いいかな?",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_010"] = "ケイトを見かけたけど 目 真っ赤だった",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_030"] = "何も言わないし… 掛ける言葉もなくて…",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_040"] = "じゃ あとでね",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_001"] = "何の用? 写真ならお断りだよ |パーティに呼ぶゲストの名簿を作らないといけないから",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_010"] = "どうせ興味ないでしょうけど",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_012"] = "そんな服 着てるくせに? ボルテックス・クラブのパーティにはドレスコードがあるの |おしゃれな服 持ってる? あなたの来るところじゃないよ",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_014"] = "誘うつもりもないし。 それじゃ",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_016"] = "意外ね。 おしゃれには興味ないのかと思ってた |それじゃ 名簿に名前を載せておくから |パーティの前にアドバイスしてあげる",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_018"] = "詳しい情報はあとで送るから。 それじゃあね",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_008"] = "コートニー",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_009"] = "そうなんだ",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_011"] = "そんなことないよ",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_013"] = "まあ 確かにないけど",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_015"] = "ボルテックス・クラブにはドレスコードあるよね? |何を着たらいいか アドバイスもらえると助かるな",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_017"] = "よかった。 じゃあよろしくね",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase02_Courtney_001"] = "しつこいのは嫌いよ。 空気読んで",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase02_Courtney_002"] = "おしゃれに変身させてあげるからね。 それじゃ",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_035"] = "マックス。 少しいいか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_036"] = "昨日の クロエの部屋での一件で聞きたいことがある… |あれは本当にお前のだったのか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_037"] = "昨日のクロエとの件についてだが…",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_040"] = "さすがの俺もそこまではしない。 昨日のことはすまなかった |頭に血が上ってしたことだ |だが クロエにとって悪影響であることに変わりはない",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_044"] = "クロエは俺を侮辱した |だが 殴っていい理由にはならない |あの子には悪いことをした |すまなかった",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_045"] = "クロエから聞いたんだな。 そのとき… 俺の銃を盗んだとも言わなかったか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_046"] = "あの子が心配だから言っているんだ |俺があれくらいの頃はもっとひどかった |クロエも ここの生徒たちも それに比べたらずっとましだ |ケイト・マーシュも…",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_049"] = "大事な話の途中でお前が割り込んできた。 彼女はまた別の問題だ",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_050"] = "余計なことを言ったな… 例の動画のことは知っているだろう",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_053"] = "いいか これはケイトだけの問題じゃない |学校の生徒全員の安全に関わることだ |お前も含めてな",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_054"] = "憶測だけで物を言うな |生徒の安全のためにカメラの設置を提案しただけで偽善者扱いか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_057"] = "なら グラント先生の署名運動で行方不明の生徒が見つかるのか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_059"] = "お前と口論するつもりはない。 言い争いはもうたくさんだ。 話は以上だ",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_038"] = "そうです。 私のです |オレゴン州ではもうすぐ合法化される見込みですよね |学校内でも手に入るし |私を退学にする気ですか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_039"] = "違います。 あれは友だちのです。 私を退学にする気ですか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_041"] = "元軍人なのに クロエが怖いんですか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_042"] = "話すことなんてないです。 クロエを殴ったくせに",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_043"] = "クロエを殴ったでしょ",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_047"] = "ケイトにひどいことしたくせに",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_048"] = "ケイトが何か?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_051"] = "ケイトは悪いことしてません",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_052"] = "それでケイトに詰め寄ったんですか? その証拠写真もあるんですよ",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_055"] = "監視カメラで安全が守れるとは思えない",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_060"] = "あの… すみません",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_061"] = "レイチェルを見つけるのは警備主任のあなたの仕事じゃないんですか? |それとも レイチェルのことで何か隠してるとか?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase02_David_001"] = "これ以上お前と話すことはない",
  ["Cue_E2_4B_Corridor_CHEvanDial_Phase01_Trevor_002"] = "お マックスじゃん。 またあとでな",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_008"] = "今日こそ課題を提出してくれるのかな? それとも 何か別の話かい?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_042"] = "ああ… ウワサは聞いたよ。 ケイトと一緒に 警備主任と口論したんだって?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_043"] = "僕も心配だ。 ケイトのことで何かあるのかな?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_047"] = "なるほど。 マドセン氏ならありうることだが… |彼に非があることを示す証拠はあるかな?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_048"] = "話があるならいつでも聞くが… マックス 僕からも聞きたいことがある",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_049"] = "マドセン氏は警備と恫喝を取り違えている |ケイトはかわいそうだが… 校長に報告するにも証拠がないと…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_052"] = "迷ったら 撮る。 写真における最も基本のルールだ",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_053"] = "授業後に見せてくれ。 写真を撮るとは プロ意識が高いな",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_054"] = "いずれにせよ この件は学校側にきちんと報告する",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_055"] = "例の動画のことは知っているね?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_058"] = "ケイトにも問題があったのでは? 彼女の「説教」がうとまれていたのは事実だ |隠し事をしているようにも見える |ケイトと直接話したかい?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_064"] = "レイチェル・アンバーとケイトに なんの関係があるんだ?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_066"] = "レイチェルのことは気がかりだが 君は自分の心配をしたほうがいい… |ウェルズ校長から女子トイレでのことを聞いたよ…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_067"] = "レイチェルとケイトはまるで違うよ… |ところで 校長から君が隠し事をしていると聞いた |僕にも話せないことか?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_072"] = "マックス これは冗談じゃ済まされないぞ",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_074"] = "僕もそう思いたいよ |でも 仮にマドセン主任が君を「売人」だと言ったら 僕は信じるべきかな",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_075"] = "だといいんだが。 ただ ここ数日 君の周りではいろいろあったようだからね",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_007"] = "ジェファソン先生 今いいですか?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_044"] = "やっぱりいいです… 忘れてください |それじゃ… 課題をやらないといけないので… |失礼します",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_045"] = "マドセン主任がケイトを怒鳴りつけていたので 止めに入ったんです |とても見過ごせなくて…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_046"] = "マドセン主任がケイトに嫌がらせをしてるのを見たんです |ケイトは怖がってました",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_050"] = "私の証言だけじゃダメですか? 迷ったんですが 写真は撮らなくて…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_051"] = "実はそのとき 証拠の写真を撮ったんです",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_056"] = "みんな知ってます… そのことで相談したくて… ケイトはすごく傷ついています",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_057"] = "ケイトは取り乱しています。 毎日嫌がらせをされて 宿題も手につかないぐらい",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_059"] = "あとで話してみます。 今は 電話に出なかったから怒ってて |ただ ケイトがレイチェル・アンバーみたいになるのが怖いんです…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_061"] = "いえ… でも ケイトまでレイチェル・アンバーと同じになってほしくないんです",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_062"] = "はい 今朝 電話で話しました",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_063"] = "はい。 今朝 話しました",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_065"] = "こんなときは友だちが支えてあげないと |ケイトまでレイチェル・アンバーと同じになってほしくないんです",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_068"] = "なぜそれを… 先生に隠してたわけじゃないんですけど",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_069"] = "本当のことです。 ネイサン・プレスコットが女子トイレで銃を持ってて…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_070"] = "今はやめておきます。 もう少しいろいろ分かったら 全部話しますから",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_071"] = "昨日 女子トイレで ネイサンが銃を持ってたんです… |怖くて校長先生にも言えなくて…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_073"] = "私がウソついてるって言うんですか? 作り話なんてしませんよ!",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_076"] = "でも先生 私 本当に…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_080"] = "町中にビラが貼ってあるので どうしても頭をよぎってしまって…",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_081"] = "実は折り入って相談が… ケイトのことが心配なんです",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase02_Jefferson_001"] = "マックス 申し訳ないが あとにしてくれ",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_002"] = "「どうこう」って… ネイサンは本当に銃を持ってたんです |本人と話しましたか?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_003"] = "急に非常ベルが鳴ったりしたから 少し動揺しただけです",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_030"] = "あの…",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_031"] = "いえ… なんでもありません",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_033"] = "いえ。 隠し事なんてしてないです",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_035"] = "マドセン主任は生徒を囚人みたいに扱ってます",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_036"] = "昨日 マドセン主任がケイトに嫌がらせしてました",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_038"] = "そんなこと言われても…",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_040"] = "校長先生こそ 何が言いたいんですか?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_001"] = "ああ… マックスか。 また銃がどうこうとかいう話じゃないだろうね",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_004"] = "ああ。 非常に憤慨した様子だったよ… |無理もないだろう |事実関係が明らかになるまで 君は勉強に専念していなさい",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_005"] = "それだけで 君はあんなに怯えていたのかね?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_032"] = "ああ… マックスか。 隠し事を打ち明けてくれる気になったかね?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_034"] = "あくまで隠し通すつもりか。 なら結構 もう行きなさい",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_037"] = "マックス 性懲りもなく またそんなことを言うのかね",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_039"] = "この学校には危険なことなど何もない |警備主任が導入した新システムのおかげで 校内の安全は保たれている",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_045"] = "昨日の件で隠し事をしているような人間から |そんな話を聞かされてもうのみにはできない |これ以上 君のたわごとにつきあっている暇はない",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_048"] = "人の言動をあげつらうだけなら誰にでもできる |ネイサンの次はマドセン主任か? |いい加減にしなさい。 これ以上の話は無駄だ",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_068"] = "君のことだからまた誰かを告発しにきたのかと思ったが… 違うなら結構だ",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase02_Principal_001"] = "マックス 用がないならもう行きなさい",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_001"] = "ザック",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_003"] = "カメラがなくても 常にアイデアを練ってるよ",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_005"] = "言わないよ。 ビクトリアの思うツボだし",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_007"] = "なんで あんなことするんだろ…",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_009"] = "もう済んだことだよ。 しばらくしたらみんな忘れるって",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_011"] = "みんなの話題になりたいんじゃない? 今みたいに",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_002"] = "よう マックス。 今日はカメラ持ってねえのかよ",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_004"] = "へえ。 ビクトリアとエロチャットの話を言いふらすアイデアとかか?",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_006"] = "確かに… あいつ 騒ぎを起こすためなら なんでもやるのか… ったく…",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_008"] = "そこが分からねえんだよ |かわいいし金持ちだし頭もいいし… 何が不満なんだ? |ま 正直どうでもいいけどさ",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_010"] = "そうかもしれないけどさ |ビクトリアはホント何考えてんだろな。 意味分かんねー",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_012"] = "じゃ もう話すのやめようぜ。 お前 頭いいな。 金曜日の試合 来いよな",
  ["Cue_E2_4B_Corridor_CHZachary_Phase02_Zachary_001"] = "よう またあとでな",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_010"] = "ちょっと失礼",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_020"] = "もしもし? ああ… あー… ちょっと待って",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_030"] = "すまない 大事な電話だ… 教室に入っていなさい",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_010"] = "ケイト ちゃんと話して",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_030"] = "いいから落ち着くんだ",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_050"] = "正直に話すんだ",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_070"] = "少し冷静になって",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_090"] = "君は構ってほしいだけじゃないのか?",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_020"] = "何を? どうせ もうおしまいです!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_040"] = "もうほっといてください!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_060"] = "どうせ誰も信じません",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_080"] = "こんな状況でムリです!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_100"] = "よくそんなひどいことを…! 先生 何も分かってない!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_130"] = "もうほっといてってば!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_150"] = "もういいです… 私のことなんてどうでもいいんでしょう? |みんな 私のことなんて気にしないんだ…",
  ["Cue_E2_4B_Corridor_JeffKateDial_Jefferson_020"] = "ケイト 僕の立場も分かってくれ",
  ["Cue_E2_4B_Corridor_JeffKateDial_Kate_010"] = "何もしてくれないんですか…?",
  ["Cue_E2_4B_Corridor_JeffKateDial_Kate_030"] = "私の立場は分かってくれないのに? 本当はどうでもいいんでしょ…",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Jefferson_010"] = "ああ マックス ちょっといいかな?",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Jefferson_030"] = "元気がないな… 何か心配事か?",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Max_020"] = "はい",
  ["Cue_E2_4B_Corridor_KateLeaves_Kate_010"] = "もうほっといてよ…",
  ["Cue_E2_4B_Corridor_KateLeaves_Kate_020"] = "来ないで! ほっといてって言ってるでしょ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_001"] = "マックス。 どしたのー?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_004"] = "私に聞かないでよ。 バケガクは専門外 |ロボット工学だったら何聞かれても答えられるけどさ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_005"] = "駐車場で飛ばしてたら グラント先生に没収された |監視カメラがどうこうって |ウォーレンの車なんか監視するわけないのに",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_007"] = "そう |助手が優秀だと自信なくすから 初心者雇ったってわけね |しっかりサポートしてあげなよ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_010"] = "ああそう それじゃあね。 バイバイ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_013"] = "ここにエキスパートがいるのに なんでスルーするかなー |ま ウォーレンが私に頼むわけないか",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_014"] = "彼 優秀だからね",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_016"] = "そっちこそ ウォーレンにつけられてない?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_018"] = "どしたのー?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_002"] = "カリウムの実験のことで ちょっと聞きたいことがあって",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_003"] = "ドローンは順調?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_006"] = "ウォーレンの実験を手伝ってるの",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_008"] = "ブルック",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_009"] = "ごめん もう行かなきゃ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_011"] = "ほら 私おせっかいだから",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_012"] = "ウォーレンは 私のサポートなんていらないよ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_015"] = "ついでに ウォーレンに GPS つけたら?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_017"] = "ブルック ちょっといいかな",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase02_Brooke_001"] = "ウォーレンの実験 手伝うんでしょ? 早く行きなよ",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase02_Brooke_002"] = "ちょっと今 ゲームしてるから。 あとでね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_001"] = "マックス いいところに来てくれたわね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_012"] = "あなたはいつも先のことを考えてるわね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_013"] = "監視カメラ設置に反対の署名をしてくれて ありがとうね。 大事な 1票よ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_014"] = "署名をしてくれなかったのは残念だわ |あなたの 1 票が 結果を左右していたかもしれないのに",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_016"] = "みんな SNS を見るのに忙しくて署名どころじゃないのね |そうやって大事なことから目をそらしている隙に |いつの間にかプライバシーが奪われていくのよ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_018"] = "あなたのような賛同者がいれば 大丈夫よ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_020"] = "マドセン主任のような人に悪用されるわ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_022"] = "分かってる。 私はただ この学校をあの人の横暴から守ろうとしてるだけ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_023"] = "先生も秋が一番好き |季節が移り変わるのはいいものね… |この学校のキャンパスは特にきれいだし |ジェファソン先生もよく写真を撮ってるわ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_025"] = "才能豊かで教師としても優秀よ |この学校では私のほうが古株だけど |名物先生といえばジェファソン先生ね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_027"] = "ええ でも私は科学者よ。 データとにらめっこしてるほうが性に合ってる",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_028"] = "それに 本格的な秋はまだまだこれから",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_031"] = "説明のつかない気候の変化 |ネイティブ・アメリカンは違う解釈をするでしょうけど",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_032"] = "あなたと先生は陰と陽の関係ね。 アーティストと科学者",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_034"] = "あら くだらない質問なんてないのよ。 何かしら?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_036"] = "それじゃ何も起きないか爆発するだけよ。 塩素を試したら?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_040"] = "ごきげんよう",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_041"] = "署名に協力してくれてありがとうね。 本当に助かったわ",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_042"] = "誰かさんの署名がまだね。 誰とは言わないけれど",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_010"] = "グラント先生",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_011"] = "私は今 秋ならではの写真に夢中で…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_015"] = "署名運動は… 順調ですか?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_017"] = "でも これでカメラの設置が取りやめになるといいですね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_019"] = "でも 監視カメラ自体が悪いわけじゃ…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_021"] = "あの人と一緒にしないでください…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_024"] = "ジェファソン先生はどんな人ですか?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_026"] = "写真が好きなんですね",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_029"] = "昨日の雪ですけど… 科学的に見て どう思いますか?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_030"] = "私も秋本番が待ちきれないです。 あの独特の空気が好きで…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_033"] = "先生 ちょっと聞いてもいいですか? くだらない質問かもしれないけど…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_035"] = "今週の実験なんですけど 先生ならカリウムとナトリウム どっちを入れますか?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_037"] = "すみません 私 そろそろ行かないと…",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_039"] = "グラント先生",
  ["Cue_E2_4B_SciClass_CHGrant_Phase02_Grant_001"] = "それじゃ また今度話しましょう。 近いうちにね",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_008"] = "ウォーレン。大丈夫? 浮かない顔して… 悩み事?",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_009"] = "ウォーレンにも分からないならムリだって",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_011"] = "なんで私に聞くのか分からないけど… そうだな… カリウム!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_013"] = "うーん そうだなあ… じゃあ… ナトリウム!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_015"] = "ウォーレン この実験 危なくない? |やめといたほうがいいような気がするけどなあ",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_017"] = "カリウムをたくさん入れてみたらどうかな。 どっさり山ほどね",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_019"] = "ウォーレン カリウムもナトリウムもハズレだよ。 塩素を入れるのが正解",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_007"] = "マックス ちょうどいいとこに来てくれたね! |ちょっと実験のアドバイスがほしいんだ",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_010"] = "カリウムとナトリウム どっちを入れたらいいと思う? 教えて マックス博士!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_012"] = "はい カリウムね! うまくいったら… ハグしてあげるよ!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_014"] = "ホントに? マックス様のご神託を信じるよ? |それじゃあ仰せのままに… ナトリウム投入ッ!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_016"] = "しょうがない 孤独のマッドサイエンティスト ウォーレン様は |伝統の科学的手法に頼るとしよう… |どーれーにーしーようかーな…カリウムだ!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_018"] = "なんか目が輝いてるね。 科学者の顔になってるよ。 よし やってみよう!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_020"] = "塩素か… 思いつかなかったな… |でも その自信は信用に値する |やってみよう!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_001"] = "ダメだ。 失敗。 変化なしだ",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_002"] = "マックス すげえ 頭がいいじゃんか! |ブラックウェルからノーベル賞受賞者出ちゃうかも!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_003"] = "すっげえ楽しかったな! でも この実験のことは我々だけの秘密にしよう…",
  ["Cue_E2_4B_SciClass_WarrenDial_Brooke_060"] = "はいはい。 ブレイクスルー おめでとう",
  ["Cue_E2_4B_SciClass_WarrenDial_Max_040"] = "私は何も…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_010"] = "うーん どっちかなあ…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_020"] = "よく考えれば分かるはずだ…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_030"] = "大正解だ! ありがとう",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_050"] = "コールフィールド博士のお手柄だよ",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_080"] = "おっかしいな…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_100"] = "してやられたよ…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_110"] = "ダメダメ科学者だな…",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_120"] = "やーめた",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_010"] = "死なせない 絶対に",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_020"] = "力の限り時間を遡って止めないと",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_030"] = "また? なんでこんなときに",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_040"] = "どうにかしなきゃ… もう何回も巻き戻せないよ",
  ["Act_E2_4C_CampusB_VoiceOver_Max_010"] = "屋上に出るには寮に入らなきゃ…",
  ["Act_E2_4C_CampusB_VoiceOver_Max_020"] = "マックス ケイトを助けるの",
  ["Act_E2_4C_CampusB_VoiceOver_Max_030"] = "ああ 頭が割れそう… でも絶対に寮に行かないと…",
  ["Act_E2_4C_CampusB_VoiceOver_Max_040"] = "マックス 怖がっちゃダメ ケイトを助けるの",
  ["Act_E2_4C_CampusB_VoiceOver_Max_050"] = "頭痛なんてどうでもいい ケイトの気持ちを考えたら…",
  ["Act_E2_4C_CampusB_VoiceOver_Max_060"] = "寮の中からならすぐに屋上に行ける",
  ["Act_E2_4C_CampusB_VoiceOver_Max_070"] = "ケイト! ダメ! どうしよう 助けないと",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_001"] = "何しに来たの また昨日みたいに写真撮る気?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_002"] = "マックス 私 本気だよ。 それ以上近づいたら飛び降りる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_008"] = "私のためには戦わないんでしょ? だからデイビッドの時も 陰で隠れてた",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_009"] = "ウソつかないで! じゃあなんで写真撮ったの!?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_010"] = "分かってる… デイビッドに歯向かうなんて怖いよね。 マックスは悪くない…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_011"] = "スクラップブック用の写真が欲しかっただけでしょ? |今だってそうなんじゃないの!?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_013"] = "証拠なら 今から飛び降りて見せてあげる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_018"] = "死ねばいいって思ってるんでしょ。 望みどおりにしてあげる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_019"] = "もう行ってよ。 説得なんてムダだから。 こんな人生 今すぐ終わらせたい",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_020"] = "でももう遅い… 手遅れだよ。 これ以上生きてたってしょうがない",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_021"] = "こうするしかないの! もう死なせてよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_023"] = "ごめんね マックスは悪くないよ… |デイビッドを止めてくれてうれしかった |けど もう何もかもどうでもいいの",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_025"] = "私だってそう信じたいよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_027"] = "ウソつき! 私からの電話無視したくせに きれいごと言わないで!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_028"] = "マックスが気に掛けてくれるのはうれしいよ… 少し救われる気がする",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_034"] = "その子の悩みがそんなに深刻なら 私のことなんか放っとけばいいでしょ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_035"] = "マックスに相談したかったのに! みんな 私をビッチだと思ってる!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_036"] = "ほらね! そうやって 友だちからの電話を平気で無視する |私が死んだって気にしないでしょ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_037"] = "そんな見え透いたウソ信じると思う? みんなそうやって言い訳するんだから!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_039"] = "そんなくだらない言い訳するぐらいだったら 黙っててよ! |出たくなかっただけでしょ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_045"] = "電話で話したときは少し安心した。 マックスは親身になって聞いてくれるから",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_047"] = "あんな動画が出回っても 私のためにこうやって来てくれたのは|すごく うれしいよ…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_053"] = "ちゃんと私が全部説明したでしょ! |もういい! いまさら何をしたってムダだよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_054"] = "ネイサン・プレスコット? あの男ならありえるけど。 証拠は見つかったの?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_055"] = "マックスは人ごとだからいいよね! |動画に映ってるわけじゃないし! |もう いまさら何してもムダだよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_056"] = "ほら やっぱり自分のことしか考えてないんでしょ? もう誰も信じられないよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_057"] = "私だってそう信じたいけど… でも…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_060"] = "ありがとうマックス… この 1 週間で初めて希望が見えた気がする",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_067"] = "何も分かってないよ |母さんの言う通り 私が地獄へ落ちるか |今やって見せてあげる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_068"] = "適当なこと言わないでよ! 私には妹しかいないって言ったでしょ? |やっぱり私のことなんてどうでもいいんだね |もういいよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_069"] = "そうだね… 迷惑かけたけど… それでも父さんだけは私を信じてくれる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_071"] = "リンは… まだ 10 歳で… |笑った顔がすごくかわいくて… |悲しませたくない",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_074"] = "私なんかもう この世に必要ないよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_079"] = "この世に正義なんてある? そんなの信じられないよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_080"] = "同じことでしょ? どうせ生きてたって地獄なんだから!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_081"] = "マタイ福音書 11 章 28 節… 私が大好きな一節だよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_085"] = "ダメ… やっぱりこれ以上 生きていけない…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_094"] = "あの動画はネットから消えない…! だからいっそ 死んだほうがまし…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_095"] = "そうなればいいな… また普通の高校生に戻れたら… |私 戻れるかな? またやり直せるかな?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_096"] = "私の気持ち 分かる? 毎日みんなにジロジロみられて 笑われて…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_099"] = "\"こんなこと\"ね。 やっぱり私の気持ちを分かってくれる人なんて誰もいない!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_105"] = "そんなのウソだよ… |クスリを飲まされたって言っても誰も… |友だちですら信じてくれない",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_111"] = "マックスは何も分かってないね |ブルックは私が神様を信じてるからって バカにしてるんだよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_112"] = "デーナはトレバーと一緒にあの動画を見てた |友だちならそんなことする? 結局見せかけだったんだ…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_113"] = "確かに ステラは悪口言わないし 私の言うことも信じてくれる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_114"] = "うん… むしろ前より優しくしてくれる… |私も もっと心を開いたほうがいいのかな…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_121"] = "だけど 今朝電話したときは出てくれなかったじゃない。 友だちだと思ったのに",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_124"] = "そんなこと言われたって… 信用できないよ |今朝相談したとき… 何もするなって言ったじゃない!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_125"] = "本当に? マックス ありがとう…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_130"] = "ホントに勝てると思う? 私もう奇跡なんて信じられないよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_133"] = "やっぱりマックスも自分のことしか考えてない。 被害者は私なのに!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_134"] = "マックス 今は毎日が悪夢なの |このまま目が覚めないなら… 永遠の眠りについたほうがまし… |これでまたネットにばらまくネタができて みんな大喜びでしょ? |一度載ったら二度と抜け出せないなんて ホントに「クモの巣」みたい… |過去に戻って全部消せたらいいのに…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_136"] = "マックスは本当に優しいんだね |それが私を説得するためのウソだったとしても… それでもいい |ありがとう",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_137"] = "マックス… そんなふうに言われたら 信じたくなるよ…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_138"] = "いまさら気に掛けてるふりされても遅いよ |今朝相談したとき 何もするなって言ったくせに!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_004"] = "私もいじめられてるけど ひどいことをされても 負けずに戦ったよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_005"] = "ケイトのために証拠写真を撮ったんだよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_006"] = "あのときは状況が全然分からなかったから…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_007"] = "助けるべきだったよね。 証拠写真が役に立つと思ったけど そうじゃなかった |本当にごめん",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_012"] = "証拠を撮りたかったの!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_014"] = "そんなことない! みんなも心配してる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_015"] = "ダメだよ! お願い!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_016"] = "あのときは本当にごめん。 ケイトの力になりたいの",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_017"] = "違うよ! 私はケイトの味方だって分かってるでしょ…? |こんなのケイトらしくないよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_022"] = "分かったから落ち着いて! ここならいい? ケイト 私と話そう",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_024"] = "よくないよ! みんな心配してる",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_026"] = "ケイト! あきらめちゃダメだよ。 私といっしょに乗り越えよう。 力になるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_029"] = "クロエから悩みを相談されてて 出られなかったの。 本当にごめん",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_030"] = "マナーモードになってて気づかなかったからだよ。 じゃなきゃ絶対出てた!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_031"] = "電池が切れてて 充電器も持ってなかったの。 ホントだよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_032"] = "当たり前だよ。 友だちだもん",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_033"] = "ウォーレンかと思ったの! |この前番号教えたら しょっちゅうかけてくるようになって…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_038"] = "本当だって! 近いうちに電話買い換えようと思ってて…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_040"] = "そんなの気にすることない。 友だちと家族はいつもケイトの味方だよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_041"] = "そんなこと言わないで! 私はケイトの味方だよ…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_042"] = "ごめん 私が悪かった。 私はケイトの味方だよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_043"] = "そんなこと言わないで! 私の話を聞いて!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_044"] = "ケイト 私を信じて |そこから降りてこっちへきて 力になれるから |ウソじゃない",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_049"] = "今 ネイサンがケイトにクスリを飲ませた証拠を集めてるの |被害者は他にもいる |犯人を捕まえるために協力して",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_051"] = "どうしていいか分からなかったの |信じられないようなことが次々と起きて… |うまく説明できないよ…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_052"] = "当たり前でしょ? 今朝も言ったけど ネイサンが一枚かんでると思う |でも証拠をつかむのに時間がいるの |あと少しの辛抱だから…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_058"] = "私はケイトを信じてる。 だから信じて",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_059"] = "もうすぐ揃うよ。 そしたら警察に行こう。 私たちで 学校の安全を守るんだ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_061"] = "つらいときに支え合うのは当然だよ… お願い そこから降りてこっちへ来て",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_063"] = "お母さんはどうなるの? すごく悲しむよ |お母さんは動画なんて気にしない |大事な娘だもん",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_064"] = "ダメだよケイト 弟たちはどうなるの? お姉さんがいなくなったら…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_065"] = "ケイト お父さんからのハガキを見たよ。 すごく愛されてるんだね |お父さんはケイトの味方だよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_066"] = "部屋の写真を見たよ。 妹と仲よしなんだね |あの笑顔を見たら ケイトのことが大好きなんだって分かったよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_070"] = "ほらね? ケイトはひとりじゃないよ。 こんなこと 誰も望んでないよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_072"] = "なら リンのために こっちへおいでよ |リンがここにいたら きっとそうするでしょ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_073"] = "待って! お願いだから… 話を聞いて",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_075"] = "しん言にもあるでしょ? |「公義を行うことは義者の喜楽にして 悪を行うものの敗壊なり」",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_076"] = "私の使命はケイトを助けることなのかも |私もケイトの助けが必要だよ |これまでだって たくさん助けられてきた",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_077"] = "「すべて労する者 重荷を負う者 われに来たれ われ汝らを休ません」",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_078"] = "自殺は罪なんだよね? |そんなことしたら 本当に地獄へ行っちゃうかも |そんなのダメだよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_082"] = "私を信じて… 一緒に下へ降りよう",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_083"] = "ケイト お父さんが悲しむよ |お父さんは動画なんか気にしない |何があってもケイトの味方だよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_084"] = "妹の話をしてくれたよね? 一番下の子は特にケイトが大好きなんだ って",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_086"] = "まだ終わりじゃないよ |ケイトにはまだ果たさなきゃいけない使命があるはずだよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_088"] = "ケイト 待って! 私の話を聞いて…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_089"] = "気にすることないよ |明日にでもビクトリアの動画が拡散されて みんな忘れちゃうから",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_090"] = "ネット上に流れてる動画なんて数え切れないほどあるんだよ |みんなあっという間に忘れちゃうよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_092"] = "クスリを飲まされたことが分かったら みんなケイトを信じるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_093"] = "私と一緒に いじめるヤツらと戦おう |2 人で力を合わせれば きっと勝てるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_098"] = "ケイトの気持ちは 分かるよ。 私だっていじめられてるもん |こんなことで死んじゃダメ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_100"] = "戻れるよ 絶対に戻れる。 大丈夫だよ。 だからこっちへおいでよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_101"] = "友だちだもん。 だからこっちへおいで",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_102"] = "待って! こんなことしたら みんなが悲しむよ!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_103"] = "つらいのは分かるよ |でも 格言にもあるでしょ? 「これもまた やがて過ぎ去る」って",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_106"] = "ブルックは友だちでしょ?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_107"] = "アリッサは信じてるよ。 今でも前と同じようにつきあってくれてるでしょ?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_108"] = "ステラは信じてるよ! そもそもあんな動画のこと気にしてないもん!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_109"] = "デーナは? デーナなら信じてくれるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_110"] = "ケイトは大事な友だちだもん。 この一節が好きなこともちゃんと知ってるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_119"] = "大丈夫 つらい時期はすぐに終わるよ。 絶対に",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_120"] = "ホワイトボードの落書きだって 私が何度も消してきた",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_122"] = "私がいつもそばにいるから。 これからは友だちが最優先って決めたの",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_123"] = "今朝だって シャワー室の鏡に動画のリンクが書いてあったから 私が消したんだ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_126"] = "ケイトは誰かにクスリを飲まされたんだよ |一緒に犯人を突き止めて 報いを受けさせよう",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_127"] = "分かってる… 私が悪かったよ。 本当にごめん",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_128"] = "待って! 早まらないで!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_129"] = "お願い… こんなの間違ってるよ",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_131"] = "ケイトのことは信じてるよ。 でも 今私が動くと ケイトも私も危なくなる…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_132"] = "まずは自力で情報を集める時間が必要だったの。 慎重に進めないと…",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_135"] = "私は信じるよ。 それはケイトのおかげでもある |こっちに来て… 全部説明するから",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Alyssa_050"] = "ブルック 信じらんないよ…",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Brooke_060"] = "かわいそうに… あのくだらない動画のせいだよ",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Courtney_090"] = "そこまで思い詰めることないのに",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Courtney_160"] = "ウソでしょ…!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Daniel_020"] = "まさか… ケイトじゃないか?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Daniel_110"] = "まさかこの学校でこんなことがあるなんて…",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Juliet_120"] = "信じられない…",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy01_040"] = "おい あれ 見ろよ 飛び降りる気じゃね?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy01_170"] = "うわ!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_010"] = "おい あれ誰だよ?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_030"] = "ウソだろ…",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_150"] = "かなり前から",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_200"] = "今の見たか?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy03_140"] = "いつからあそこにいるんだ?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl01_070"] = "飛び降りたとしてもケガで済むんじゃない?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl01_190"] = "/!\\ WARNING /!\\ Text not localized : Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl01_190",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl02_080"] = "助からないよ",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl02_180"] = "うそ…!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Zachary_210"] = "/!\\ WARNING /!\\ Text not localized : Cue_E2_4C_CampusB_CommentingKate_IGE_Zachary_210",
  ["Cue_E2_4C_CampusB_Freeze_RTC_Max_010"] = "行かなきゃ… 早く… 行かなきゃ…",
  ["Cue_E2_4C_CampusB_Freeze_RTC_Max_020"] = "前へ…前へ 進まないと…",
  ["Cue_E2_4C_CampusB_Insertion_TeenBoy01_070"] = "ヤバいことになってるぞ!",
  ["Cue_E2_4C_CampusB_Insertion_TeenGirl01_010"] = "早まらないで! 降りてきなよ!",
  ["Cue_E2_4C_CampusB_KateIsAlive_RTC_Kate_010"] = "ゴメン… バカだった…",
  ["Cue_E2_4C_CampusB_KateIsAlive_RTC_Max_020"] = "ケイトはバカじゃないよ… 私の大事な友だちだよ",
  ["Cue_E2_4C_CampusB_KateIsDead_Max_010"] = "ダメ…! ケイト!",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_010"] = "そんな…",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_020"] = "力が使えない… 巻き戻せない…",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_030"] = "失敗したら おしまいだ…",
  ["Cue_E2_4C_CampusB_RoofArrival_Kate_020"] = "マックス 何しに来たの?",
  ["Cue_E2_4C_CampusB_RoofArrival_Kate_030"] = "来ないで! 来たら飛び降りるから!",
  ["Cue_E2_4C_CampusB_RoofArrival_Max_010"] = "間に合った…",
  ["Act_E2_5A_PrinOffice_AfterMajorChoice_Max_010"] = "頭が痛いけど もう一度力を使えそう",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_010"] = "早くサインすれば 早くここから出ていける",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_020"] = "サインすれば法廷ドラマのワンシーンは終わり",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_030"] = "どうしたのマックス?さっさと終わらせてこの部屋から出よう",
  ["Cue_E2_5A_PrinOffice_Insertion_David_090"] = "ハッ… なにがヒーローだ…",
  ["Cue_E2_5A_PrinOffice_Insertion_Jefferson_080"] = "おっしゃるとおりです。 マックスはヒーローだ",
  ["Cue_E2_5A_PrinOffice_Insertion_Max_070"] = "私は何も…",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_010"] = "これは誰にとっても気分のいいことではないが |今回の件に関わりがあると思われる者には… |事情を説明してもらう必要がある",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_020"] = "各自の証言は 警察の捜査の参考用に記録される。 すべて… 正直に話すように",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_030"] = "残念な事件だが... 経緯を明らかにする必要がある",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_040"] = "ケイトはいったいなぜ あそこまで追い詰められたのか。 うやむやにはできない",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_050"] = "今日の一件は実に遺憾だが |当校が一丸となり 1 人の女子生徒の命を救ったのは 誇らしいことだ",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_060"] = "ケイトを説得したマックスの功績は計り知れない",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_100"] = "校長として 私には生徒が健全な学校生活を送れるよう 管理する義務がある |学びの場でこのようなことが起きたのは遺憾きわまりない",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_110"] = "マドセン君。 屋上のドアは 警備上 常時施錠しておくことになっていたはずだ ||しかし今日はどういうわけか カギが開いていた |これは警備主任である君の責任だ",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_120"] = "ジェファソン君。 生徒 1 人ひとりの状態を把握するのは難しいだろうが |ケイトは君の授業の助手をしていた |何か気づけたはずだ",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_130"] = "ネイサン。 君はボルテックス・クラブのパーティを主催しており |前回はケイトも参加していた |君にもいくつか聞きたいことがある",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_140"] = "マックス。 まず君から なぜ屋上へ行ったのか説明してほしい |事前にケイトから 何か聞いていたのかね? |知っていることをすべて話しなさい",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_020"] = "いい加減にしてくれ…",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_040"] = "ケイトはろくでもない連中と関わっていた。 俺はそれが誰か調べていただけだ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_070"] = "よくもそんなウソを…",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_080"] = "こんな問題児の言うことを真に受ける気ですか? |こいつは危険なブツを 人の家に持ち込んだんですよ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_120"] = "校長は こんな問題児の言うことを真に受ける気ですか?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_160"] = "それは…! 誤解だ!",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_230"] = "本気ですか 校長… こんなふざけた話があるか! |大の大人が子どものたわごとに振り回されて!",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_250"] = "ウェルズ校長… そろそろマックスとネイサンを休ませてあげては?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_260"] = "目の前で仲間が亡くなったんです… これ以上はあまりに負担が大きい",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_270"] = "目の前で仲間が命を絶とうとしたんです… これ以上はあまりに負担が大きい",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_010"] = "ケイトはマドセン主任にいじめられて…",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_030"] = "ケイトに嫌がらせしてたでしょ? 私も見てたんです",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_060"] = "あなたが言わないでよ |私は主任がケイトの肩を押したりしてるところを見たんです",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_090"] = "はあ? それとこれとは関係ないでしょ!",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_130"] = "生徒に嫌がらせする職員のほうが問題だと思います",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_150"] = "証拠ならあります",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_155"] = "ケイトが嫌がらせされてたときの写真です",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_180"] = "例のファイルの話もバラしましょうか?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Nathan_050"] = "ケイトには裏の顔があったんだ。 俺も知って驚いたぜ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Nathan_280"] = "そうだ。 ショックでそれどころじゃない。 家に帰らせてくださいよ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_100"] = "確かに マックスは過去にも虚偽の証言をしたことがある |マドセン主任の主張はもっともだ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_110"] = "君の発言の真偽については 調査の必要がある",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_115"] = "マックスは ご両親に連絡のうえ 数日間の停学処分とする",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_140"] = "マックス。 証拠がない以上 この件については慎重に調査を行う必要がある |他にも何か言うことがあるかね?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_170"] = "これは裁判ではない |しかしながら 詳しく調べる必要はありそうだ |残念だが君を停職処分とする",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_190"] = "後日 改めて話し合いの場を設ける",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_200"] = "ケイトの退院を待ち 彼女にも同席してもらおう",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_210"] = "後日 改めて話し合いの場を設ける",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_220"] = "警察の捜査報告を待ってからだ",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_240"] = "マドセン君。 これは決定事項だ",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_020"] = "俺も報告した",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_080"] = "この生徒は素行に問題がある。 だまされないでください",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_110"] = "この生徒は信用できません",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_001"] = "ケイトはパーティでネイサンにクスリを飲まされました |もうろうとしている間に男子とキスしたところを動画に撮られたんです",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_003"] = "それだけじゃない。 病院に連れてくって ケイトにウソついたでしょ",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_005"] = "あのパーティでケイトに何かあったのは間違いないよ! |女子トイレで銃を持ってたことは どう説明する気?",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_060"] = "昨日は勇気が出なくて… でも今は違う",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_090"] = "誤解です! しかもそれとこれとは関係ないでしょ!",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_120"] = "女の子 殴る人が言わないで",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_002"] = "俺に? お前 大丈夫か? ちゃんと動画を見りゃ一目瞭然だよ |本人 完ッ全にノリノリだっただろ",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_004"] = "連れてくつもりだったけど すぐ落ち着いて 結局行かずに済んだんだよ",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_006"] = "てめえ 名誉棄損で訴えるぞ! この学校も一緒に訴えてやる! |弁護士だってもう雇ってあるんだ…",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_040"] = "ご勝手に。 後悔するぜ",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_010"] = "ネイサン! そのぐらいにしておきなさい |銃の件はすでにマックスから聞いた |残念ながら例の動画についても 複数の人物から報告を受けている",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_030"] = "ネイサン 君は件の動画にはっきりと映っているばかりか |パーティの主催者という立場でもあるね |以上を踏まえ 君をしばらく停学処分とする",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_050"] = "マックス 昨日は女子トイレで何もなかったと言ったね |どうして今になって急にそんなことを言いはじめた?",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_070"] = "まあ わからなくもないが…",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_100"] = "君たち! いいから落ち着きなさい!",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_030"] = "はい… 彼女は… このところふさぎ込んでいました |例の動画が原因だと思います。 私も非常に心配していました",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_040"] = "ケイトは 親身になって話を聞いてくれるのはマックスだけだと言っていた…",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_050"] = "ケイトは マックスが電話に出なかったことで傷ついていた |味方は一人もいないと…",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_080"] = "まったくそのとおりです。 マックスの言うとおりですよ |私は力になりたかったが およばなかった",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_100"] = "本気ですか?",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_120"] = "承知しました。 生徒一人の命を考えれば… そういった措置は当然です",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_130"] = "別の職員についても調査しては? マックスからマドセン主任の話を聞きました",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Max_010"] = "授業が始まる前 ケイトはジェファソン先生と話してて… |泣いているのを見ました",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Max_070"] = "はあ? ケイトは完全に被害者だよ",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Nathan_060"] = "動画撮られてんのに羽目外すからだろ",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_020"] = "ジェファソン君 ケイトは君の助手を務めていたね",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_090"] = "これは実に由々しき問題だ… |世間もすでに今回の一件に注目しはじめている |君はサンフランシスコでの「日常ヒーロー」コンテストに |出席しないほうがよさそうだ",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_110"] = "ああ。 コンテストに悪いイメージがついては困る |ことのなりゆき次第では君の懲戒処分も視野に入れる必要があるだろう",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_140"] = "それはマックス本人に聞くとしよう。 証言はすべて調査対象となる",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_010"] = "ではマックス |今話した内容がすべて真実であることの証明として 書類に署名をしなさい",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_030"] = "かえってなぞばかりが増えた感もあるが… 警察による捜査に期待するとしよう",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_040"] = "残念だが ボルテックス・クラブのパーティは中止せざるをえない |保護者から不安の声が多数寄せられているなか 開催を強行するのは賢明ではない |調査が完了するまでは 大事を取ることにする",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_050"] = "重ね重ね 今日のことは実に遺憾だ… |時間を戻してやり直せたらどんなにいいか… |私からは以上だ",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_010"] = "いまだに信じられないよ ケイトがあんなことするなんて… |幻を見てたような気分…助けられると思ったのに… |スーパーヒーローみたいに…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_030"] = "手 届かなかった…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_050"] = "でも 助けられなかったら意味ないよ |他の誰かが止めてくれてたら… こうなってなかったかも",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_070"] = "ウォーレン… 私ってホントにダメだね",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_090"] = "まるで夢を見てるみたいだった… |ケイトの手をつかもうとしたらスローモーションになって… |ケイトも私の手をつかんで…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_110"] = "どこが? 身も心もボロボロだよ…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_130"] = "ケイトのことが心配… |あんな動画なんかのせいで… まさか死のうとするなんて…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_150"] = "ウォーレンも見たの?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_170"] = "聞いて。 こんなこと言うとヘンに思われるかもだけど… |この学校で何かよくないことが起きてる",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_190"] = "ケイトの件とレイチェルの行方不明は関係があると思うの |それから… ネイサンとデイビッド・マドセンも",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_210"] = "ねえ あれ見て…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_230"] = "ホントだ…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_250"] = "ありがとう… でも平気 大丈夫",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_260"] = "太陽がどんどん欠けてく… 急に寒くなってきた…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_270"] = "まるで「キアロスクーロ」…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_290"] = "分かってるよ… もう 何が起きても不思議じゃない…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_020"] = "マックス 自分を責めるのはやめろって |ケイトのことはマックスのせいじゃない |君は悪くないよ",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_040"] = "マックスはすごいよ。 屋上へ行く勇気があったのは君だけだ |みんな何もできなかった",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_060"] = "君にしかできなかったよ",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_080"] = "バカなこと言うなって",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_100"] = "あんな感動的な場面 俺 生まれて初めて見たよ! |ケイトを抱きとめた瞬間…拍手喝采 涙の嵐! スーパーヒーローみたいだ!",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_120"] = "何言ってんの! キラキラ輝いてるよ。 背中に翼生えてもおかしくないね",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_140"] = "まあ あれだけ拡散されたらね…",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_160"] = "1 回だけだよ… 2 回だったかな",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_180"] = "同感だね",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_200"] = "陰謀論者ではないけど ありえると思うよ |昨日のネイサンは普通じゃなかったし マドセンは腐ってる |他にも何かあったっけ?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_220"] = "寒くなってきたな",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_240"] = "上着 貸そうか?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_280"] = "マックス 今日は日食の日じゃないよ… 絶対違う。 間違いない",
  ["Act_E3_1A_Bathroom_AbstinencePoster_Look01_Max_010"] = "ケイトが戻ってきたとき こんなポスターは見たくないだろうね…",
  ["Act_E3_1A_Bathroom_AbstinencePoster_Look02_Max_010"] = "ケイトの死をポスターのせいにはできない",
  ["Act_E3_1A_Bathroom_CHTaylor_Look01_Max_010"] = "テイラーは本気でケイトのことを心配してるみたい…",
  ["Act_E3_1A_Bathroom_CHTaylor_Look02_Max_010"] = "ああは言っていたけど やっぱりかなり動揺してるよね…",
  ["Act_E3_1A_Bathroom_Mirror2_Look01_Max_010"] = "リンクを書いたビクトリアが一番後悔してることを願うよ…",
  ["Act_E3_1A_Bathroom_Shower_Look01_Max_010"] = "うーん シャワー浴びたいけど時間がない。 クロエに会いにいかないと…",
  ["Act_E3_1A_Corridor_DanaSlate_Look01_Max_010"] = "デーナもかなりこたえてるみたい…",
  ["Act_E3_1A_Corridor_DeathShrine_Interact01_Max_010"] = "ケイト その穏やかな心に祝福がありますように…",
  ["Act_E3_1A_Corridor_DeathShrine_Look01_Max_010"] = "もう一度時間を巻き戻してあなたを救えるなら この力を失ってもいい… |絶対に真実を突きとめて 犯人に罪を償わせる…",
  ["Act_E3_1A_Corridor_Enter_VoiceOver01_Max_010"] = "うわ さすがに真っ暗。 闇を照らしたまえ…",
  ["Act_E3_1A_Corridor_KateDoor_Look01_Max_010"] = "テレビで見る犯罪現場みたいになってる",
  ["Act_E3_1A_Corridor_KateDoor_Look02_Max_010"] = "ここまでする必要あるの? ケイトは生きてるのに…",
  ["Act_E3_1A_Corridor_KateSlate_Look01_Max_010"] = "偽善者ばかりだ",
  ["Act_E3_1A_Corridor_MPA_Look01_Max_010"] = "どこにいるの? レイチェル・アンバー…",
  ["Act_E3_1A_Corridor_MPA_Look02_Max_010"] = "あなたに導かれている気がする… でもどこに?",
  ["Act_E3_1A_Corridor_MPA_Look04_Max_010"] = "絶対に見つけるよ レイチェル… クロエとケイトのために",
  ["Act_E3_1A_Corridor_MaxSlate_Look01_Max_010"] = "ケイトが翼を授かっていますように…",
  ["Act_E3_1A_Corridor_MaxSlate_Look02_Max_010"] = "早く元気になってね ケイト…",
  ["Act_E3_1A_Corridor_NathanGraffiti_Look01_Max_010"] = "これを消すのは無理。 サミュエル・ダ・ヴィンチに塗り替えてもらわないと…",
  ["Act_E3_1A_Corridor_Poster1_Look01_Max_010"] = "バカ騒ぎしたいだけでしょ… くだらない",
  ["Act_E3_1A_Corridor_Poster2_Look01_Max_010"] = "パーティの前に世界は終わってしまうかもよ…",
  ["Act_E3_1A_Corridor_Scripted2_Max_030"] = "ここ数日でやったことに比べたら 寮を抜け出すなんてわけない",
  ["Act_E3_1A_Corridor_Scripted4_Max_010"] = "クロエに会いにいったほうがいいね",
  ["Act_E3_1A_Corridor_Scripted4_Max_020"] = "夜中に出歩いているのを見つからないように よく注意しないと…",
  ["Act_E3_1A_Corridor_Scripted_Max_010"] = "彼本気だったんだ… 家族そろって大バカなんだね",
  ["Act_E3_1A_Corridor_Scripted_Max_020"] = "最悪… 私も人間離れしてるけど ネイサンは常軌を逸してる…",
  ["Act_E3_1A_Corridor_Scripted_Max_030"] = "ビクトリアはいない… 彼女の部屋を調べて 手がかりをつかむチャンスかも",
  ["Act_E3_1A_Corridor_TaylorSlate_Look04_Max_010"] = "信じられない。 恥知らずにもほどがある",
  ["Act_E3_1A_Corridor_VictoriaSlate_Look01_Max_010"] = "気が滅入るね。 いつも自分のことばかり…",
  ["Act_E3_1A_Corridor_VortexPoster_Look01_Max_010"] = "そのとおり ボルテックス・クラブはつまらない",
  ["Act_E3_1A_Corridor_VortexPoster_Look03_Max_010"] = "最初にレイチェル そしてケイト… ボルテックス・クラブはもう終わりだよ",
  ["Act_E3_1A_DanaRoom_CHDana_Look01_Max_010"] = "とても悲しそう。 そんな素振りを見せないようにしているけど…",
  ["Act_E3_1A_DanaRoom_CHDana_Look02_Max_010"] = "責任を感じてるけどホッとしているみたい… 本気で心配してたんだね",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Interact01_Max_010"] = "トレバーっていいヤツ。 よかったねデーナ",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Interact02_Max_010"] = "デーナはジュリエットにどこまで話すつもりなんだろう",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Look01_Max_010"] = "パソコンを使ってもデーナは気にしないと思う…",
  ["Act_E3_1A_DanaRoom_HalloweenStuff_Max_010"] = "デーナ 本当にハロウィン・パーティを楽しみにしてるんだね",
  ["Act_E3_1A_DanaRoom_LoganNote_Max_010"] = "読んでて悲しくなるよ",
  ["Act_E3_1A_MaxRoom_Bed_Look01_Max_010"] = "はあ もう疲れて死にそう… でも事件は待ってくれない… |解決に向けて捜査あるのみ…",
  ["Act_E3_1A_MaxRoom_DavidPicture_Look01_Max_010"] = "私ってバカだな |これを校長に見せればデイビッドを処罰してもらえたかもしれないのに…",
  ["Act_E3_1A_MaxRoom_Drawer01_Look01_Max_010"] = "ケイト… あそこまであなたを追い詰めたヤツには絶対責任を取ってもらうから",
  ["Act_E3_1A_MaxRoom_Drawer01_Look02_Max_010"] = "以前のケイトは驚くほど幸せそう… |なぜ彼女がこんなことになったのか 絶対に突き止めてみせる |こんなの許されない…",
  ["Act_E3_1A_MaxRoom_Hifi_Interact01_Max_010"] = "寮を抜け出すアリバイにはならないだろうね…",
  ["Act_E3_1A_MaxRoom_Hifi_Look01_Max_010"] = "滅入っていると 音楽どころじゃなくなるよね",
  ["Act_E3_1A_MaxRoom_Laptop_Interact01_Max_010"] = "さっそくマスコミは悲劇を大々的に取り上げている |これでケイトの両親は娘の死から逃げられない… |しかも今回は私も映っているし |ホント嫌な気分…",
  ["Act_E3_1A_MaxRoom_Laptop_Interact02_Max_010"] = "マスコミがケイトの件を取り上げている |これでケイトはまた別の動画まで拡散された |しかも今回は私も映っているし |幸い名前は公表されてないけど… 今のところは",
  ["Act_E3_1A_MaxRoom_Laptop_Interact03_Max_010"] = "ふーむ |レイチェルを除けば ここ最近行方不明になった人っていないんだ… |いいことなんだろうけど…",
  ["Act_E3_1A_MaxRoom_Laptop_Interact04_Max_010"] = "とても感動的なコピペ文章だね |ケイトには何の手も差し伸べなかったのに |今さら遅いよ…",
  ["Act_E3_1A_MaxRoom_Laptop_Interact05_Max_010"] = "みんな手のひらを返してケイトが大好き |いじめておいてよくやるよ。 偽善者!",
  ["Act_E3_1A_MaxRoom_Laptop_Interact06_Max_010"] = "ケイトが戻ってきたら 当然前よりもマシな接し方をするんだよね?",
  ["Act_E3_1A_MaxRoom_Laptop_Interact07_Max_010"] = "私のせいで大事になってしまった… ジェファソン先生に悪いことしたな…",
  ["Act_E3_1A_MaxRoom_Laptop_Interact08_Max_010"] = "デイビッドも監視社会を経験できるね",
  ["Act_E3_1A_MaxRoom_Laptop_Interact09_Max_010"] = "ページを削除するかみんなをブロックするか。 最近は隠れる場所がないね…",
  ["Act_E3_1A_MaxRoom_Laptop_Look01_Max_010"] = "シャーロック・ホームズはネットなしでどうやって推理したの?",
  ["Act_E3_1A_MaxRoom_Mirror_Look01_Max_010"] = "泣くのはおしまい。 振り返ってばかりいないで前に進もう",
  ["Act_E3_1A_MaxRoom_Mirror_Look02_Max_010"] = "ケイトは大丈夫。 深呼吸して気をしっかり持たなきゃ。 時間ならある",
  ["Act_E3_1A_MaxRoom_NathanPhoto_Look01_Max_010"] = "ネイサンのやつ… みんなサミュエルをキモいとか言ってる場合じゃないよ",
  ["Act_E3_1A_MaxRoom_Plant_Interact01_Max_010"] = "さあ飲んで",
  ["Act_E3_1A_MaxRoom_Plant_Look01_Max_010"] = "かわいそうに。 植物の世話よりも人の世話のほうが向いてるのかも…",
  ["Act_E3_1A_MaxRoom_Plant_Look02_Max_010"] = "あーあ… 人を助けられないどころか 植物の世話もできない… 役立たずだね",
  ["Act_E3_1A_MaxRoom_Plant_Look03_Max_010"] = "リサ 君はまだ生きているね… |人の世話よりも植物の世話のほうが向いてるのかも…",
  ["Act_E3_1A_MaxRoom_Plant_Look04_Max_010"] = "最初はクロエ 次にケイト そしてリサ。 今週はかなり命を救ってる",
  ["Act_E3_1A_MaxRoom_Plant_Look05_Max_010"] = "ごめんねリサ… ケイトは救えたけど 君は水浸しにしちゃった…",
  ["Act_E3_1A_MaxRoom_Plant_Look06_Max_010"] = "ごめんねリサ。 水が多すぎたよ |植物も死なせてしまうんじゃ ケイトなんか…",
  ["Act_E3_1A_MaxRoom_Rabbit_Interact01_Max_010"] = "おなかすいてるの? ほら ごはんだよ…",
  ["Act_E3_1A_MaxRoom_Rabbit_Look01_Max_010"] = "大丈夫 心配しないで… これからは私がお母さんだよ",
  ["Act_E3_1A_MaxRoom_Rabbit_Look02_Max_010"] = "ケイトはもうじき戻ってくるよ。 それまでは私がなんでもしてあげる",
  ["Act_E3_1A_MaxRoom_Schedule_Look01_Max_010"] = "さて… これ全部欠席扱いになるのかな",
  ["Act_E3_1A_MaxRoom_Schedule_Look02_Max_010"] = "どちらにしろ勉学に励む気にはなれないね… 当たり前だけど",
  ["Act_E3_1A_MaxRoom_Scripted_Max_010"] = "ケイトのことを考えずにはいられない… まるで覚めない悪夢のよう…",
  ["Act_E3_1A_MaxRoom_Scripted_Max_020"] = "ものすごく疲れているけど やらないわけにはいかないよね",
  ["Act_E3_1A_MaxRoom_Scripted_Max_030"] = "みんなの話題はケイト一色だろうね。 ひと月くらい休校になればいいのに",
  ["Act_E3_1A_MaxRoom_Scripted_Max_040"] = "デーナの部屋のドアが開いてる。 話しかけても大丈夫そう",
  ["Act_E3_1A_MaxRoom_Window_Look01_Max_010"] = "いろんなことがありすぎて日食のこと忘れかけてた… |最近の異常気象は偶然とは思えない… |それにすべてはあの竜巻へとつながってる…",
  ["Act_E3_1A_VicRoom_Cookies_Look01_Max_010"] = "私のクッキー? ビクトリアが盗んだ!? |でも取り返せないよね。 私の仕業だってバレちゃう |ビクトリアって… クッキー大好きなんだ",
  ["Act_E3_1A_VicRoom_Desk_Interact01_Max_010"] = "名づけて「バカ者たちの宴」",
  ["Act_E3_1A_VicRoom_Desk_Interact02_Max_010"] = "ケイト 完全にハイだ。 でも無理してる。 楽しんでるようには見えない",
  ["Act_E3_1A_VicRoom_Drawer1_Interact01_Max_010"] = "悪魔に取りつかれてる顔だよ…",
  ["Act_E3_1A_VicRoom_Drawer2_Interact01_Max_010"] = "私のタンスよりも高い靴下だね",
  ["Act_E3_1A_VicRoom_Object01_Interact01_Max_010"] = "ビクトリアの秘密? オタクだったのか…",
  ["Act_E3_1A_VicRoom_Object02_Interact01_Max_010"] = "ビクトリアも別に最先端じゃないけど… 独自のスタイルはあると思う",
  ["Act_E3_1A_VicRoom_Poster06_Look01_Max_010"] = "ビクトリアの親がチェイス・スペースのオーナー? 素直に感心した",
  ["Act_E3_1A_VicRoom_SchoolBag_Interact01_Max_010"] = "何が「独特の視点」かな… どうせコートニーに書いてもらったくせに",
  ["Act_E3_1A_VicRoom_Scripted3_Max_020"] = "どうせここまで首を突っ込んだんだ… |パーティで実際にケイトの身に何があったのか 手がかりを探してみよう",
  ["Act_E3_1A_VicRoom_Scripted3_Max_030"] = "特に何もなし。 がっかりしてもしょうがないね |でも 絶対ビクトリアは何か隠してるはず… 考えすぎかな?",
  ["Act_E3_1A_VicRoom_Trash_Interact01_Max_010"] = "セーターのシミ落としにしては高いね…",
  ["Act_E3_1A_VicRoom_Trash_Interact02_Max_010"] = "おめでとうマックス。 ついに人のゴミを漁るようになったね |ふむ この口紅はいいな",
  ["Act_E3_1A_VicRoom_VicPicture_Look01_Max_010"] = "これを盗めたということは ビクトリアも超能力者? … なんてね",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact01_Max_010"] = "どうやらビクトリアにも人の心があるみたいだね…",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact02_Max_010"] = "へえ… ビクトリアとテイラーも一応 悲しんではいるんだ",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact03_Max_010"] = "怒りに満ちてるね。 でも 「マックス・クラックフィールド」? |ひねりが足りんよ…",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Look01_Max_010"] = "ここに何か手がかりがあるはず…",
  ["Act_E3_1A_VicRoom_VictoriaShoes_Look01_Max_010"] = "こんな靴じゃランウェイしか歩けないよ…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_007"] = "ビクトリアはどこに行ったの?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_009"] = "私も私だよ。 またあとでね",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_010"] = "「信じられない」? テイラーや学校のみんながいじめたから飛んだんだよ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_011"] = "私は分かる。 止められなかったのを後悔してる… そっちは大丈夫?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_012"] = "「信じられない」? テイラーや学校のみんなのせいで飛ぼうとしたんだよ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_013"] = "私は分かる。 本当に飛ばなくてよかった。 テイラーは大丈夫?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_018"] = "私も。 でも テイラーがショックを受けてるのは意外 |ビクトリア軍団で ケイトをいじめてたじゃん…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_037"] = "だろうね。 じゃあ またあとで",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_040"] = "だろうね。 お母さん よくなるといいね。 何かあったら相談して",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_041"] = "誰にも言わない。 誓って",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_043"] = "うん… ビクトリアも動揺してるのかな |門限が過ぎてから寮を出たみたいだけど…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_044"] = "そうだよ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_048"] = "行き先は地獄じゃない? もう寝なきゃ 今日は長い一日だったし",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_052"] = "私も私だよ。 なにかあったら相談して",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_001"] = "マックス… ケイトを助けに屋上に行ったの 見たよ… |飛び降りたなんて信じられない…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_004"] = "マックス… 屋上でケイトを助けたの 見たよ… |飛び降りようとしたなんて信じられない…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_008"] = "私は私 ビクトリアのパシリじゃない。 それに あの子も動揺してる |今日も門限破って…  言っちゃいけないんだった",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_014"] = "ショックだよ。 自殺しようとする人なんて初めて見たから…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_015"] = "何? 私が悪いって言うの?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_016"] = "なんか 何も感じられない… 人が死ぬのを見たのは初めてだし",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_017"] = "何? 私が悪いって言うの?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_019"] = "もう これ以上しゃべらない。 ビクトリアに殺される",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_032"] = "マックスのこと 信じたいけど…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_036"] = "あんたのことは信じるよ |ビクトリア以外で病院のママのこと聞いてくれたの あんただけだし |本当にありがとね…",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_038"] = "ありがと… あんた 変だけどいい人ね |屋上に登ってるのを見たから 余計にそう思う |ビクトリアがあんたについて言ってたこと 間違ってるよ |じゃ これから眠れない夜をすごすから… |またね",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_039"] = "病院のママのこと聞いてくれたから |あんたのこと信じてるけど |話したらビクトリアにマジで殺されるから",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_045"] = "じゃあどっか行って。 放っておいて |私は自分のことでいっぱいいっぱいなの |今日はもうしゃべりたくない",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_046"] = "じゃあどっか行って。 放っておいて |ママが入院してるって言ったでしょ? |今日はもうしゃべりたくない",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_047"] = "ウソ 見たの? 寮を出る時 すごくビクビクしてた… |どこに行くのかも教えてくれなかったよ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_049"] = "ビクトリアがあんたについて言ってたこと 間違ってた |じゃ これから不安で眠れない夜をすごすから… おやすみ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_050"] = "またね マックス |それと… ケイトのこと助けに屋上に登ったの 結構かっこよかったよ",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_051"] = "またね マックス |あんたのことも心配だよ。 ケイトを助けようとしたの あんただけだし",
  ["Cue_E3_1A_Bathroom_CHTaylor_Quick01_Taylor_001"] = "もうしゃべりたくないって言ったでしょ マックス。 ほっといて",
  ["Cue_E3_1A_Bathroom_CHTaylor_Quick01_Taylor_002"] = "ねえ 私 ほんとに寝たいの マックス",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_003"] = "ケイトのことが頭から離れない… もし私のせいだったらと思うと…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_004"] = "飛び降りようとするなんて… 深刻どころじゃないよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_005"] = "ケイトよりは大丈夫。 自殺しようとしたなんて信じられない…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_006"] = "マックスは違うよ。 マックスだけは…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_012"] = "そうね… でも ケイトのために屋上に登ったのはマックスだけ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_014"] = "あんなに動画を広めて 顔面に一発お見舞いしたい |私にもできたことがあったのに",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_017"] = "あんなに動画を広めて 顔面に一発お見舞いしたい |私にもできたことがあったのに",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_021"] = "他に何があるって言うの?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_023"] = "何が言いたいの マックス",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_025"] = "マックス 私を容疑者扱いするつもり? |もうどっか行ってよ 頭痛くなってきたし",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_028"] = "あんな状態を撮られて逃げ出したかったのかも |悪口は言いたくないけど ひどかったよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_030"] = "ビクトリアとボルテックス・クラブのせいだよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_032"] = "マックス以外 誰も勇気がなかったんだよ… |私 もう寝るね。 今日のことはもう考えたくない…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_033"] = "うん… ケイトも無視すればよかったのに。 素直でイイ子すぎ…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_037"] = "運じゃないって。彼女を助けることを選んだんでしょ。 ヒーローみたいに!",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_039"] = "ネイサンが停学になった件と何か関係あるの?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_040"] = "ジェファソンが校長に絞られたみたいだけど… 関係あるの?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_041"] = "デイビッド・マドセンに関係ある話? 大目玉食らったらしいし",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_044"] = "怖がらせないでよ… さっきも一人コソコソ寮から抜け出してたし",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_047"] = "ビクトリア。 マックスもそのつもりでしょ?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_048"] = "昨日停学になった件と関係ある? ねえ 教えてよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_001"] = "ねえ デーナ… 大丈夫?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_002"] = "落ち込んでたのは知ってたけど あんなに深刻だったなんて…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_008"] = "今回のことは みんなの責任だと思う…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_009"] = "自分を責めないで。 いろんな人が関わってるじゃない。 ビクトリアとか",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_010"] = "ビクトリアはあの動画で ケイトをどれだけ苦しめたんだろう",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_011"] = "自分を責めないで。 いろんな人が関わってるじゃない。 ビクトリアとか",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_015"] = "知ってることは それだけ?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_016"] = "ケイトのかたきを討たないと。 うやむやにはさせない",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_022"] = "ケイトは本気だった。 でも あの動画がすべてじゃない…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_024"] = "そもそも どうしてケイトは屋上に登ったと思う?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_026"] = "ホントだよ… 他のみんなは何してたの?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_027"] = "運が良かっただけ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_029"] = "ねえ ホントにケイトがすすんで |ボルテックス・クラブのパーティで酔っぱらったと思うの?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_031"] = "「私だけ」だったのが問題なんだよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_034"] = "デーナ これはビクトリアとボルテックス･クラブだけの問題じゃない",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_035"] = "デーナは十分ケイトに優しかったよ。 他のみんなもそうだったらよかったのに",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_036"] = "もう関係ないよ。 ケイトは死んじゃったの",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_038"] = "なら そろそろ悪者退治に行かないと",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_042"] = "いま調べてるところ。 でも この学校が抱える闇を必ず明らかにしてみせるよ",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_043"] = "いろいろあるの… でも デーナまで巻き込みたくない。 少なくとも今は…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_045"] = "え? 誰のこと?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_046"] = "私は行かないよ クタクタだし… デーナもしっかり寝てね。 おやすみ",
  ["Cue_E3_1A_DanaRoom_CHDana_Quick01_Dana_001"] = "もう疲れちゃった。 あとでね",
  ["Cue_E3_1A_DanaRoom_DanaCall_Dana_010"] = "マックス! ちょっといい?",
  ["Cue_E3_1A_DanaRoom_DanaCall_Dana_020"] = "ねえ ちょっと話さない?",
  ["Cue_E3_1A_MaxRoom_MaxWakesUp_Max_010"] = "ケイト!",
  ["Cue_E3_1A_MaxRoom_MaxWakesUp_Max_050"] = "相変わらずせっかちだな クロエ… 行ってあげるか",
  ["Act_E3_1B_CampusB_Bench_Look01_Max_010"] = "昨日ケイトがここに座っていたなんて変な感じ…",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_010"] = "ケイトは飛び降りなかったけど いまだにドキドキする",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_020"] = "残留アドレナリンのせいかな…",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_030"] = "でもなんか無敵になった気分",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_010"] = "いったい何やってるんだろう…",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_020"] = "ケイトが死んだのに寮を抜けだして",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_030"] = "キャンパスがまるでお墓みたい…",
  ["Act_E3_1B_CampusB_BrokenLamp_Look01_Max_010"] = "サミュエル あれ直さないのかな",
  ["Act_E3_1B_CampusB_BrokenWindow_Look01_Max_010"] = "どこを見ても自分が歴史を変えた痕跡がある… 大なり小なり",
  ["Act_E3_1B_CampusB_CHPrincipal_Look01_Max_010"] = "ウェルズ校長はぐでんぐでんだった。 ケイトのことを気に病んでかな…",
  ["Act_E3_1B_CampusB_CHPrincipal_Look02_Max_010"] = "あんな姿を誰にも見られなくてよかったね… 私以外",
  ["Act_E3_1B_CampusB_Cardboard_Interact01_Max_010"] = "何かあるかな?",
  ["Act_E3_1B_CampusB_Cardboard_Look01_Max_010"] = "何もなし",
  ["Act_E3_1B_CampusB_Drawers_Look01_Max_010"] = "ナットとボルト… おじいちゃんのガレージみたい",
  ["Act_E3_1B_CampusB_Fireflies_Look01_Max_010"] = "ホタルって神秘的… 灯火みたい",
  ["Act_E3_1B_CampusB_GirlStuff_Look01_Max_010"] = "サミュエルはシルクのスカーフを巻かないよね… じゃあ誰が?",
  ["Act_E3_1B_CampusB_GotCaught_Scripted_Max_010"] = "バレた… ドアを開けようとしている隙に 通れないかな…",
  ["Act_E3_1B_CampusB_JanitorDoor_Interact01_Max_010"] = "カギが開いてる! サミュエルが来ませんように…",
  ["Act_E3_1B_CampusB_JanitorDoor_Look01_Max_010"] = "サミュエルの倉庫だ",
  ["Act_E3_1B_CampusB_KateSuicideTraces_Look01_Max_010"] = "彼女が飛び降りたなんてまだ信じられない…",
  ["Act_E3_1B_CampusB_KateSuicideTraces_Look02_Max_010"] = "でも今更なにをしたって…",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver01_Max_010"] = "ニンジャに転職でもしようかな",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver02_Max_010"] = "なんでこんなとこにいるの!",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver03_Max_010"] = "ああもう これじゃ出られない!",
  ["Act_E3_1B_CampusB_Magazine01_Look01_Max_010"] = "サミュエルがファッションに関心あったなんて…",
  ["Act_E3_1B_CampusB_Shelves_Look01_Max_010"] = "うーん ただの棚だね",
  ["Act_E3_1B_CampusB_Squirrel_Look01_Max_010"] = "おチビさん ちょっといいかな?",
  ["Act_E3_1B_CampusB_Squirrel_Photo01_Max_010"] = "レンズを見て… はい 「ナッツ!」",
  ["Act_E3_1B_CampusB_Squirrel_Photo01_Max_020"] = "よし!",
  ["Act_E3_1B_CampusB_Switch_Look01_Max_010"] = "ただのスイッチ",
  ["Act_E3_1B_CampusB_Toolbox_Look01_Max_010"] = "工具しかない…",
  ["Act_E3_1B_CampusB_Totem_Look01_Max_010"] = "トバンガって夜見ると怖いね… どうか何もしないで",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_010"] = "夜の学校は不吉な感じ…",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_020"] = "こんな遅くにデイビッドがうろついてないといいけど…",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_030"] = "デイビッドに出くわす心配はもうないね…",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_040"] = "ビクトリアにも絶対に会いたくないけど…",
  ["Act_E3_1B_CampusB_VoiceOverJanitor_Max_010"] = "ここにいたらまずいよ。 急ごう…",
  ["Act_E3_1B_CampusB_VoiceOverJanitor_Max_020"] = "確かにサミュエルは変わり者… でも本当にケイトやレイチェルと関係してるの?",
  ["Act_E3_1B_CampusB_VoiceOverObjective_Max_010"] = "クロエが校舎の前で待ってるはずだ",
  ["Act_E3_1B_CampusB_VoiceOverObjective_Max_020"] = "見つからないように。 ニンジャ・モード全開でいくよ",
  ["Act_E3_1B_CampusB_VoiceOverStealth_Max_010"] = "ウェルズ校長… 何でいるの? 見つかったらマズい…",
  ["Act_E3_1B_CampusB_VoiceOverStealth_Max_020"] = "困ったな… どうやって通り抜けよう",
  ["Cue_E3_1B_CampusB_LD_PRinLoopSit_IGE_Principal_010"] = "ケイト・マーシュの家族が悲しんでると言うのに 自己嫌悪に浸っている場合か… |きっと大変な訴訟になるぞ… |\"ブラック・ヘル\"などと呼ばれるわけだ…",
  ["Cue_E3_1B_CampusB_LD_PRinLoopSit_IGE_Principal_020"] = "嫌な日だ… また優等生を失うところだった… |ケイト・マーシュはいっそ町を出てくれないだろうか… |自分の失敗を教育のせいにしたがる父兄の相手なんかしてられるか…",
  ["Cue_E3_1B_CampusB_LD_PRinLoop_IGE_Principal_010"] = "おや カギをもっていたはずなんだが… どこだ… |ああ あったぞ! どうしてはまらないんだ? |壊れてしまったのか? それは私か…",
  ["Cue_E3_1B_CampusB_LD_PRinMove_IGE_Principal_010"] = "もう知らん。 開き直ってやる |誰も私を追い出すことなぞできん |今のところはな",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_IGE_Principal_010"] = "マックス 部屋に戻っていなさい!",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_IGE_Principal_020"] = "外をうろついていないで 部屋に戻りなさい!",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Max_030"] = "すみません… ケイトのことを考えてたら… その… 外の空気が吸いたくなって",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Max_050"] = "すみません… ケイトのことを考えてたら落ちつかなくて… |その… 外の空気が吸いたくなったんです",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_010"] = "マックス こそこそするならもっとうまくやりなさい |この時間は外出禁止だと分かっているだろう。 ん?",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_020"] = "マックス こそこそするならもっとうまくやりなさい |この時間は外出禁止だと分かっているだろう。 その上謹慎中だ",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_040"] = "今日はつらかっただろう。 君は助けようと行動を起こした… |私はどうだ… ここの責任者なのに ケイトも 学校も救えなかった |もう 部屋に戻って休みなさい。 ひどい一日だった… |ゆっくり寝るといい",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_060"] = "いや いいんだ。 君がケイトと一緒に降りてきたときに… |彼女はもちろんそうだが… 学校を救ってくれたと思ったよ |だが 夜 出歩くのは別の話だ |部屋に戻って ゆっくり休みなさい",
  ["Act_E3_1C_CampusA_ChloeFearsMax_VoiceOver01_Max_010"] = "クロエ どうしたんだろう… まさかデイビッドに捕まった? |ケイトのこともあったし もうこれ以上 悪い知らせは勘弁してほしい",
  ["Act_E3_1C_CampusA_ChloeFearsMax_VoiceOver02_Max_010"] = "約束 忘れてないよね… それともデイビッドに捕まった? |もう一度クロエを助けるのは神様が許してくれない気がする…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_037"] = "それに竜巻がこの町を消し去るのを阻止する… だっけ?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_041"] = "町全体に不吉なことが起きてる。 その中心地がこの学校ってわけだ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_042"] = "バカにしているわけじゃないんだ |あたしの皮肉は回避行動なんだってさ |カウンセラーが言ってたよ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_043"] = "でも その力は操れるだろ。 時間と空間が思いのままだ。 すごいじゃん",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_052"] = "そんなふうに自分を責めるもんじゃないよ。 とりあえず手がかりを集めよう",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_053"] = "クソオヤジとネイサンとかな…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_054"] = "レイチェルは誰とでも仲良くなれた。 あたしが嫌いな連中とも…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_061"] = "危険どころじゃないよ。 一人はガキに手をあげるクズ野郎だ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_062"] = "だね… 単にその 2 人が一番ムカつくだけだ…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_063"] = "だね… 単にその 2 人が一番ムカつくだけだ… |クソオヤジのやつ 顔殴りやがって…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_064"] = "そんなこと知るか! あたしはレイチェルを見つけたいだけ… |考えると怖くなるんだ… もしかしたら…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_068"] = "どうしても脳裏をよぎるんだ |マックス 早くレイチェルを見つけよう |早く…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_069"] = "それが逆に怖いんだよ。 マックス 早くレイチェルを見つけよう。 早く…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_070"] = "あたしを置いて行くはずない |絶対 何かに巻き込まれたんだ… |早く レイチェルを見つけよう |早く…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_071"] = "危険どころじゃないよ。 一人は女に銃を突きつけるクソ野郎だ…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_035"] = "ケイトを自殺まで追い詰めた犯人とかね… |これ以上の犠牲者を出すわけにはいかない",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_036"] = "ケイトをここまで追い詰めた犯人とかね… |これ以上の犠牲者を出すわけにはいかないよ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_038"] = "できれば… でもどうやって? あの雪と日食は不吉だよ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_039"] = "茶化さないで クロエ。 お願い",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_040"] = "前にこれは「カオス理論」だって言ってたよね? |そんなの とてもじゃないけど手におえないよ…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_044"] = "なんか… 自分の決断に自信が持てなくなってきた…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_046"] = "特にネイサンを停学させてから…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_047"] = "特にその結果を目の当たりにすると… 巻き戻すにも手遅れだし",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_048"] = "特にデイビッドを停職させてから…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_050"] = "特にジェファソン先生を巻き込んでから…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_051"] = "結果 自分まで停学になって…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_055"] = "了解。 まず第一に ケイトとレイチェルの周囲には共通の人物がいたということ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_056"] = "レイチェルと関わりのあった人間について もっと調べないといけないね",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_057"] = "大丈夫 絶対に見つけるよ。 まずは手がかりを探そう |で 見せたいものって何?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_058"] = "全てのカギはレイチェルが握っている気がする |変かな… 会ったこともないのに…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_059"] = "そう。 2 人とも危険人物だし",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_060"] = "それだけじゃないよ",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_065"] = "死んでるって言いたいの? ごめん こんなの口にしたくもなかったけど…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_066"] = "生きてると思う。 そうとしか思えない。 彼女の気を強く感じるから…",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_067"] = "案外ロスでうまくやってるかも。 可能性としてはあるよね…",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_010"] = "ばあっ!",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_020"] = "ビックリした? まさかチビってないよね?",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_040"] = "ご ごめん マックス… 何も考えてなかった。 ごめん…",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_060"] = "そりゃショックだろう。 あたしにはどうやって慰めていいか分からない |だからバカをする |でも マックスの力があれば全部解決できるよ。 謎は多いけどさ",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_080"] = "ごめん でもすごいじゃん。 友だちを救ったんだぜ!",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_100"] = "考えすぎだって。 ケイトが生きてるのはマックスのおかげ |マックスの言葉が効いたんだ… |それに その力がいずれみんなを救う。 まだ謎は多いけどな",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_030"] = "クロエ ふざけるのはやめて |ついさっき 目の前で友だちが屋上から飛び降りたんだよ? |さすがに ちょっと無神経だと思う |もし逆の立場だったら こういうことされたい?",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_050"] = "あまりグチりたくないけど… |ケイトが飛び降りた光景は一生忘れられないと思う… |私の力が使えなかったせいで… 役立たずだった",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_070"] = "クロエ ふざけないで。 今日は大変な一日だったんだよ |友だちが屋上から飛び降りるのを止めたりしてさ |ちょっとは考えてほしいな",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_090"] = "それはケイトの意志。 私は巻き戻すことができなかった… |頭が痛くて割れそうで… 何を言ったらいいかさえ分からなかった…",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_010"] = "驚くなよ… ほら 学校の合いカギ! クソオヤジからくすねてきた",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_030"] = "こんなに問題だらけの町だ。 今さらどうってことないだろ? |マックスだって停学中だし。 な?",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_040"] = "こんだけ問題だらけの町だ。 今さらどうってことないだろ? |やるっきゃないのさ。 な?",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_060"] = "誰が犯罪者だ…",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_020"] = "ほんと感心しちゃう。 とはいえ これ以上 問題を起こしてほしくはないけど…",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_050"] = "ついに犯罪者の仲間入りだね",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_070"] = "クロエしかいないでしょ…",
  ["Cue_E3_1C_CampusA_EnteringBuilding_Chloe_010"] = "さて いっちょやりますか",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Chloe_340"] = "完全にジェファソンを脅してやがる",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Chloe_360"] = "大変なことになってんな",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_020"] = "クラスメイトたちも君に続いてくれるといいんだが |気が散っていてすまない。 今日はいろいろありすぎた",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_040"] = "ありがとう。 君も… ケイトの件で大変だろうに…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_070"] = "ありがとう。 最悪の事態にならなくてよかったよ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_090"] = "\"ケイティ\"? 君たち そんなに仲がよかったのかい? 意外だな…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_110"] = "いや。 コンテストは実施されるし |先生が学校代表を選ばなきゃならないことは変わらない |マックスの写真以外は揃ったんだが…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_120"] = "いや ただ先生はサンフランシスコに行けない |僕はケイトの話を聞いただけなんだが マックスはそう思わなかったようだ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_140"] = "それは君のことじゃないかい?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_160"] = "あのマックスが? そんなわけないだろう",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_200"] = "彼は誰のことも調べてるさ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_220"] = "謹慎だ。 僕としては構わないけどね",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_240"] = "マックスが作品を提出したら選考するよ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_260"] = "「ジェファソン先生」だ。 それに… まだ優勝者を決めてない",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_270"] = "「ジェファソン先生」だ。 それに 僕は行けないと言っただろ?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_290"] = "今のは聞かなかったことにするよ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_310"] = "今の脅しも聞かなかったことにしよう。 話はこれでおしまいだ |君は生徒だろ 寮に戻りなさい",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_330"] = "ビクトリアは一体どこまで落ちる気なの…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_350"] = "さすがボルテックス・クラブ…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_370"] = "ホントに…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_010"] = "ポートフォリオを手伝ってくれてありがとうございます",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_030"] = "そうですね。 何かあったら聞きますよ ジェファソン先生",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_050"] = "ええ… 人が死ぬところを見たのは初めてでした… 可哀想なケイティ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_060"] = "今日は大変でしたものね。 話なら聞きますよ 先生",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_080"] = "ケイティが飛んでたらどうなってたか…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_100"] = "それより… 「日常ヒーロー」コンテストは中止になるんですか?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_130"] = "私 マックスのこと嫌いです |あの子繊細ぶってるけど ただ大げさでわがままなだけだし",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_150"] = "停学になったのはマックスですよ。 きっと屋上でケイトにひどいこと言ったんだ",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_170"] = "サミュエルが私にペンキをかけたとき マックスは写真を撮ったんです |そんな子信じられます?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_180"] = "たしかに ペンキをかけられたとき マックスはなぐさめてくれたけど… |写真でも撮ってバカにするかと思ったのに…",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_190"] = "マドセン主任があの子を調べてるみたいですけど",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_210"] = "マドセン主任をクビにさせたみたいですけど",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_230"] = "それで コンテストの優勝者は?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_250"] = "どうせ あの子は自撮りしかできませんよ |私の作品を見てくれたでしょう? |自撮りなんかよりずっといいじゃないですか |マーク 一緒にサンフランシスコに行きましょ?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_280"] = "もともと私の作品を評価してくれてるんだから |誰もヒイキだなんて思いませんよ |でも 私の写真を選んでくれたら… |一緒に過ごせる時間が増えるでしょ? ね?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_300"] = "私を選ばなかったら… |先生に 優勝させる代わりに いろいろ要求されたって言いふらしちゃうかも…",
