  ["Act_E3_2A_SciClass_WrongChemicals_Look03_Max_010"] = "化学にはうといけど これは絶対に塩素酸ナトリウムじゃないよ",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look01_Max_010"] = "違うね",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look02_Max_010"] = "はずれ",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look03_Max_010"] = "これは… 関係ないね",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look04_Max_010"] = "特に何もなし",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look05_Max_010"] = "大きくて使いにくそう…",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_005"] = "校長のファイルを覗くなんて ゾクゾクしちゃうな!",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_008"] = "どうせ巻き戻して直せるじゃん",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_009"] = "別に学校に戻りたいわけじゃないし どうでもいいよ",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_012"] = "ウソつけ 楽しんでるだろ",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_013"] = "マックスがいるからな",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_015"] = "おっと 怒られちゃったよ。 だんだんあたしに似てきたかな…",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_006"] = "頼むから間違ってハードディスクを消したりしないでよ",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_007"] = "学校に復讐するチャンスだね…",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_010"] = "頼りすぎたくないの",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_011"] = "まだ時間はあるよ…",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_014"] = "もう… 黙って続けなさい",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase01_Chloe_001"] = "おいおい 急がないと捕まっちまうって",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase02_Chloe_001"] = "よし ファイルを探そう。 お宝情報満載のな",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase03a_Chloe_001"] = "分かったよ。 金は取らない。 フランクに殺されてもしょうがないや。 な?",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase03b_Chloe_001"] = "見逃してくれてサンキュー。 さて ずらかりますか",
  ["Cue_E3_2A_Corridor_ChloeDoesntTakeMoney_Chloe_020"] = "札束にも魔力があるんだよ… でも マックスの言うとおりだ |多分… そうと決まったら 早く行こうぜ",
  ["Cue_E3_2A_Corridor_ChloeDoesntTakeMoney_Max_010"] = "本当に障害者基金を盗むつもり? |フランクに借りがあるのは知ってるけど… |いざとなれば私の力で守るから…",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_020"] = "おっと これは何かな?",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_030"] = "マジかよ!? 金だ! ラッキー!",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_050"] = "5 千ドルある。 今夜中にフランクに金を返せる! |これでヤツを撃とうとした件も 忘れてくれるだろ…",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_060"] = "5 千ドルある。 今夜中にフランクに金を返せるぜ |これでヤツの気もおさまるだろ…",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_070"] = "何だよ その顔? まさか巻き戻して独り占めする気か? 説教よりはマシだけど",
  ["Cue_E3_2A_Corridor_ChloeMoney_Max_010"] = "もう出たほうがいいよ。 調子に乗りすぎ…",
  ["Cue_E3_2A_Corridor_ChloeMoney_Max_040"] = "「障害者基金」にしては大金だね",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_020"] = "さすがマックスだ",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_030"] = "残りの金でポートランドまでドライブだ |散財するぞ! タトゥー ビール ドーナツ…",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_050"] = "あとストリップクラブ… なんてね! でもいいかも…",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Max_010"] = "フランクはレイチェルについて何か知ってる。 お金があれば 聞きだせるかも…",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Max_040"] = "パウエルズで本も",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_020"] = "ひと泳ぎどう? 今ならプールに誰もいない…",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_040"] = "今週は散々だったし 少しはハメ外したっていいだろ? |どうせ仕事は終わったんだ。 金も手に入れたしさ |ちょっとだけだって",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_045"] = "色々あったし…",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_050"] = "金もあきらめたんだ |フランクに殺される前に 少しくらいハメ外したっていいだろ? |ちょっとだけだって",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_070"] = "お いいノリだ。 だんだん染まってきたな",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_010"] = "いやな予感がするな…",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_030"] = "泳ぐって…これ以上無茶する気?",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_060"] = "そうだね。 それもいいかも。 行こう",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_020"] = "まかせな",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_040"] = "あたしの部屋にハッパを持ち込んだりするから… なんてね",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_050"] = "あたしのせいにするか? こないだみたいに…",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_070"] = "ちゃんとカギ開けて入っただろ。 なんの問題もないって!",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_090"] = "大丈夫 ここの警備主任はクソオヤジだ |あたしが警察に捕まって困るのはあいつだし… |てことで 早いとこ校長室を調べよう |どうせ捕まっても巻き戻せるんだしさ",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_100"] = "警備主任は今 家で謹慎中だ。 バレやしないよ… |てことで 早いとこ校長室を調べよう |どうせ捕まっても巻き戻せるんだしさ",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_130"] = "来いよ。 残すドアはあと 1 つだ",
  ["Cue_E3_2A_Corridor_Insertion_Max_010"] = "さすがだね クロエ",
  ["Cue_E3_2A_Corridor_Insertion_Max_030"] = "こんなことして平気かな… お互い目をつけられてるんだし…",
  ["Cue_E3_2A_Corridor_Insertion_Max_060"] = "ふざけないで。 これって不法侵入だし 冗談じゃすまないよ…",
  ["Cue_E3_2A_Corridor_Insertion_Max_080"] = "まじめな話 刑務所行きかも…",
  ["Cue_E3_2A_Corridor_Insertion_Max_110"] = "でもケイトは…",
  ["Cue_E3_2A_Corridor_Insertion_Max_120"] = "でもケイトのときは使えなくなったし… いつまたそうなるか",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_100"] = "クソッ ふざけんなよ!",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_120"] = "悪い こっちはお手上げ。 そっちは?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_140"] = "案外 あたしが先にこじ開けてるかもよ",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_010"] = "ウォーレン 今いい?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_012"] = "とりあえずベースに帰還すればいいよ。 それより ちょっと教えてほしいんだ |例えばの話だけど 美術室と理科室に入れる状況で |カギのかかったドアを開ける道具を作りたい場合… |どうしたらいいと思う?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_014"] = "えっ? 違うよ ただ興味があって",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_016"] = "ありがとう さすがだね。 いや いいよ 大丈夫 |バックアップ要員てことで。 じゃあ すぐにやり方を送って",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_020"] = "うん 「猿の惑星」見にいくの楽しみにしてるから… ありがとね",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_030"] = "ごめん 映画の件はちょっとまだ分からなくて |うん… ごめんね。 ありがとう",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_110"] = "だめだよ みんな起きちゃう",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_130"] = "ちょっと準備してくる。 ここに隠れて待ってて",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_150"] = "じゃあ 勝負ってことで",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_010"] = "絶対開けて マックスに嫌味言ってやる…",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_020"] = "あーもう どうなってんだよ! クソッ!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_040"] = "魔法かよ!? どうやって入ったんだ? 教えろよ!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_060"] = "ふーん 道理でカギなんか かけてるわけだ |どれもこれも 高そうなもんばっか… 悪趣味だけどな",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_070"] = "なんだ この鳥。 ホント 趣味悪い。 退学になってよかったよ",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_090"] = "ほっとけ。 あたしは机の上の書類をあたる",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_130"] = "このイス ダサいけど座り心地は最高!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_150"] = "マックス 分かってるよな |レイチェル ケイト ネイサン 誰でも… |なんでもいいから手がかりを見つけよう",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_030"] = "どうぞ あがってって",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_050"] = "友だちのおかげかな。 よし 早く始めよう。 力に頼れるのはここまで",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_080"] = "それって校長の趣味が良ければ クロエは退学にならなかったってこと?",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_160"] = "任せといて",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_040"] = "よっしゃ! 派手にいこうぜ!",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_060"] = "たまんないぜ…",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_080"] = "うおお… マジ最高",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_100"] = "えっ… どうするよ?",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_020"] = "真打ち登場。 これ試してみよう",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_030"] = "ドッカーンとね",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_050"] = "火をいただけるかしら?",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_070"] = "さあ 離れて",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_090"] = "ヤバい やっちゃった! これじゃ警察と消防が来ちゃうって!",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_010"] = "ここだ",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_015"] = "マジかよ!? 警備員のくせに校長室のカギ持ってねえ",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_030"] = "絶対開けてやる |実は 少しだけどピッキングもかじっててさ。 フランク様様だな |ちょっと試してみるか…",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_050"] = "一応 カギも探して… 念のため",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_080"] = "ちゃんとフランクに教えてもらえりゃよかった… |もう少し粘ってみるけど なんかいい方法考えてくれ",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_020"] = "きっと… 見られたくないものがあるんだ",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_040"] = "どうぞ。 もう後には引けないし…",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_060"] = "うん 分かった",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_070"] = "カギないみたい… 別の方法を探そう",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_090"] = "合点承知…",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_010"] = "マックス ちょっとこれ見てみろよ",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_040"] = "レイチェルが麻薬を所持しているとネイサンが訴えた? |あたしに悪影響が及ぶと考えたクソオヤジも それに同調しただと?",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_060"] = "「ネイサン・プレスコット 3 世」。 大した名前だぜ |プレスコット家はネイサンの本当の記録を金でもみ消したな… |学業不振 教師からのクレーム 謹慎処分… |あたしよりひどい",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_090"] = "ただの落書きだろ…",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_110"] = "イカれてる。 どういう意味なんだ? |ネイサンはマジでおかしい |絶対にレイチェルの失踪に関係してる…",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_130"] = "こいつらグルなんじゃないのか? そうとうキテるな",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_150"] = "ガレージにある あいつのファイルを調べるしかないね… |情報は手に入れたし さっさと帰ろう |でも… その前に手土産を…",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_180"] = "心を読んだのか? それとも あたしがイスを盗もうとして巻き戻した? |ややこしいな…",
  ["Cue_E3_2A_Corridor_RachelFile_Max_050"] = "デイビッドとネイサン・プレスコットが組んでるなら… まずいね",
  ["Cue_E3_2A_Corridor_RachelFile_Max_070"] = "とりあえずネイサンは停学になったけど。 そっちのノートは… 開いて",
  ["Cue_E3_2A_Corridor_RachelFile_Max_080"] = "お金で何でも解決してきたんだ… そっちのノートを開いて",
  ["Cue_E3_2A_Corridor_RachelFile_Max_100"] = "違う… |ほら 「レイチェルは暗い部屋の中… レイチェルは暗い部屋の中…」 |それが延々と…",
  ["Cue_E3_2A_Corridor_RachelFile_Max_120"] = "これを見て 「デイビッド・M はいつも聞いてくる |俺の頭の中のことを… デイビッド・M が従うルールに 俺も従う…」 |なんなの…",
  ["Cue_E3_2A_Corridor_RachelFile_Max_140"] = "デイビッドはケイトや私に絡んでただけじゃなく |レイチェルにも嫌がらせしてた…",
  ["Cue_E3_2A_Corridor_RachelFile_Max_170"] = "このイスはだめだからね",
  ["Cue_E3_2A_Corridor_RachelFile_Max_190"] = "親友だから 考えてることくらい分かるよ",
  ["Cue_E3_2A_PrinOffice_ChloeCallsOut_Chloe_010"] = "もう廊下は散々見ただろッ! こっちに来いよ!",
  ["Cue_E3_2A_PrinOffice_ChloeCallsOut_Chloe_020"] = "いつまで廊下をぶらついてんだ? 校長室はどうなった?",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_020"] = "頼むぞ…",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_030"] = "ふざけてんのかよ",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_040"] = "ダメだ…",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_050"] = "クソオヤジめ ふざけやがって…",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_060"] = "蹴り破ってもいいんだぜ",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_100"] = "おーい いい加減にしろって。 いつまで待たせるんだ?",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_040"] = "何か隠してるのは分かってんだ…",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_050"] = "秘密のファイルがあるはず…",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_070"] = "ごみ箱まで空だ…",
  ["Cue_E3_2A_PrinOffice_ScarfaceReference_Chloe_020"] = "「悪党に… おやすみをいいな」",
  ["Cue_E3_2A_PrinOffice_ScarfaceReference_Max_010"] = "クロエ… 「俺の坊やに挨拶しな!」",
  ["Act_E3_3A_SwimPool_CHChloe_Look01_Max_010"] = "早く電気をつけてあげたほうがいいね",
  ["Act_E3_3A_SwimPool_CHChloe_Look02_Max_010"] = "早くプールに入りたがってる",
  ["Act_E3_3A_SwimPool_CHChloe_Look03_Max_010"] = "クロエが隠れてる。 他の場所を探さないと…",
  ["Act_E3_3A_SwimPool_Drawer01_Look01_Max_010"] = "カワウソパワーだ! オッターズ!",
  ["Act_E3_3A_SwimPool_Flippers_Look01_Max_010"] = "プールに足ひれ? 海軍のフロッグマンでも育成してるの?",
  ["Act_E3_3A_SwimPool_FloatingDummy_Look01_Max_010"] = "あら 私に唇を奪ってほしいの…?",
  ["Act_E3_3A_SwimPool_Floats_Look01_Max_010"] = "子どもの練習用だよね?",
  ["Act_E3_3A_SwimPool_Graffiti01_Look01_Max_010"] = "これは… ひどい",
  ["Act_E3_3A_SwimPool_Graffiti02_Look01_Max_010"] = "だといいけど…",
  ["Act_E3_3A_SwimPool_Graffiti03_Look01_Max_010"] = "格好悪いね",
  ["Act_E3_3A_SwimPool_Graffiti04_Look01_Max_010"] = "あるある",
  ["Act_E3_3A_SwimPool_Graffiti05_Look01_Max_010"] = "ひどい言葉…",
  ["Act_E3_3A_SwimPool_Graffiti05_Look02_Max_010"] = "奇跡でケイトを救えればいいのに…",
  ["Act_E3_3A_SwimPool_Graffiti06_Look01_Max_010"] = "自己顕示欲モンスターだ…",
  ["Act_E3_3A_SwimPool_Graffiti07_Look01_Max_010"] = "あっそ…",
  ["Act_E3_3A_SwimPool_Graffiti08_Look01_Max_010"] = "さすが男子更衣室",
  ["Act_E3_3A_SwimPool_Graffiti09_Look01_Max_010"] = "ホント男子は下品だな…",
  ["Act_E3_3A_SwimPool_Graffiti10_Look01_Max_010"] = "男は死ぬまで治らない",
  ["Act_E3_3A_SwimPool_Graffiti11_Look01_Max_010"] = "時代錯誤だ",
  ["Act_E3_3A_SwimPool_Jacket_Look01_Max_010"] = "よっぽど愛校心がないとこれは着れないね",
  ["Act_E3_3A_SwimPool_LightControlCabinet_Look01_Max_010"] = "光と闇が私の思いのままに…",
  ["Act_E3_3A_SwimPool_MessageBoard01_Look01_Max_010"] = "猫の写真って… かわいそうではあるけど",
  ["Act_E3_3A_SwimPool_MessageBoard03_Look01_Max_010"] = "これを調べてる時間はないな…",
  ["Act_E3_3A_SwimPool_Mirror02_Interact01_Max_010"] = "あら美人… なんてね。 今は完全に不審者の顔してるよ…",
  ["Act_E3_3A_SwimPool_Mirror02_Interact01_Max_020"] = "マックス・コールフィールド モラルの体現者。 それか独善的な偽善者…",
  ["Act_E3_3A_SwimPool_MiscObject01_Look01_Max_010"] = "ブルックはウォーレンとドライブインに行きたいみたい…",
  ["Act_E3_3A_SwimPool_MiscObject03_Look01_Max_010"] = "バスの切符? 逃げようとしてたの? レイチェル・アンバーみたいに?",
  ["Act_E3_3A_SwimPool_MiscObject04_Look01_Max_010"] = "ビクトリアの秘密は自撮り? さんざん私をバカにして… いや ダメだ |芸術家が憎けりゃ写真まで憎い… これ いい写真だよ",
  ["Act_E3_3A_SwimPool_MiscObject06_Look01_Max_010"] = "ネイサンの処方薬… 色々あるみたいだけど…",
  ["Act_E3_3A_SwimPool_MiscObject08_Look01_Max_010"] = "努力は認めてあげようかな…",
  ["Act_E3_3A_SwimPool_MiscObject11_Look01_Max_010"] = "かわいい! ハロウィンの赤ちゃんカボチャ",
  ["Act_E3_3A_SwimPool_MiscObject12_Look01_Max_010"] = "クロエの…?",
  ["Act_E3_3A_SwimPool_MiscObject13_Look01_Max_010"] = "もう片方はどこに?",
  ["Act_E3_3A_SwimPool_MiscObject14_Look01_Max_010"] = "レイチェル…",
  ["Act_E3_3A_SwimPool_MiscObject16_Look01_Max_010"] = "電子タバコ 流行ってるな…",
  ["Act_E3_3A_SwimPool_MiscObject17_Look01_Max_010"] = "ザックのジャージなんか触らないよ…",
  ["Act_E3_3A_SwimPool_MiscObject18_Look01_Max_010"] = "もう泳いでも安全だと思ったらこれだ…",
  ["Act_E3_3A_SwimPool_MiscObject19_Look01_Max_010"] = "コーヒーと水泳 いい組み合わせ",
  ["Act_E3_3A_SwimPool_Necklace_Look01_Max_010"] = "高級アクセサリーをロッカーに入れておくのはビクトリアだけだね…",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_010"] = "クロエ すごく楽しそう。 ここは彼女の悪巧みに乗ってあげよう…",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_020"] = "クロエが待ってるけど ちょっとだけ男子更衣室をのぞいてみよう…",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_030"] = "クロエが待ってるけど どうしても女子更衣室を見てみたい…",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_040"] = "このあたりに電気の制御パネルがあるはず…",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_050"] = "覚悟はいい マックス?",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_060"] = "早く逃げないと!",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_070"] = "急いで! 捕まって力を無駄に使わないように!",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_080"] = "力を使うか… どこかに隠れるか… あるいはその両方か",
  ["Act_E3_3A_SwimPool_ObjectivesBoard_Look01_Max_010"] = "つまり重要なのは 勝つことってわけね",
  ["Act_E3_3A_SwimPool_OxygenKit_Look01_Max_010"] = "溺れたら ここに来ればいいね",
  ["Act_E3_3A_SwimPool_Phone_Interact01_Max_010"] = "こんなこと 知りたくもなかったよ",
  ["Act_E3_3A_SwimPool_Phone_Look01_Max_010"] = "ザックは不注意だな。 私が見るとも知らずにさ…",
  ["Act_E3_3A_SwimPool_Picture01_Look01_Max_010"] = "ジェファソン先生の教室で加工したんだ… でも なんで?",
  ["Act_E3_3A_SwimPool_PoolGlasses_Look01_Max_010"] = "おしゃれなゴーグルだね…",
  ["Act_E3_3A_SwimPool_PoolGlasses_Look02_Max_010"] = "「ゴーグル紛失事件」を見事解決。 でもそれどころじゃないな",
  ["Act_E3_3A_SwimPool_Poster02_Look01_Max_010"] = "カワウソが生き残れるといいね…",
  ["Act_E3_3A_SwimPool_Poster03_Look01_Max_010"] = "昔は女性がプールに入れなかったって本当?",
  ["Act_E3_3A_SwimPool_RescueBoard_Look01_Max_010"] = "ここで溺れた人はいないと思うけど… たぶん",
  ["Act_E3_3A_SwimPool_Scripted_Max_010"] = "あっちに戻ったら確実に警備員に見つかっちゃう",
  ["Act_E3_3A_SwimPool_SoapDispenser02_Look01_Max_010"] = "ほとんどカラだ。 男子も一応手を洗ってるのか…",
  ["Act_E3_3A_SwimPool_SoapDispenser_Look01_Max_010"] = "ネバネバしてキモい! みんな自分の石鹸を持ってくるわけだね…",
  ["Act_E3_3A_SwimPool_TShirts_Look01_Max_010"] = "カビの生えたシャツ… きったない",
  ["Act_E3_3A_SwimPool_Towels_Look01_Max_010"] = "何このふかふかのタオル! 欲しいな",
  ["Act_E3_3A_SwimPool_Trophies_Look01_Max_010"] = "行け オッターズ!",
  ["Act_E3_3A_SwimPool_VendingMachine_Look01_Max_010"] = "炭酸は大好きだけど たくさんは飲めないんだよね",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Interact01_Max_010"] = "私の名前を見たときのみんなの顔を撮りたい…",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Interact02_Max_010"] = "あらごめんなさい リストに名前がなくてよ… ふふっ いい気味!",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Look01_Max_010"] = "ボルテックス・クラブ パーティのゲストリストだ… どれどれ…",
  ["Cue_E3_3A_SwimPool_CHChloe_ChooseSide_Max_002"] = "もちろん女子!",
  ["Cue_E3_3A_SwimPool_CHChloe_ChooseSide_Max_003"] = "もちろん男子!",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_001"] = "あたしのときは使えただろ",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_005"] = "大事なのは これからどうするか。 それに うちらは運命共同体だ |あたしなしじゃ マックスは力に目覚めなかったんだから",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_011"] = "あたしもだ。 この町も マックスがいれば悪くない",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_012"] = "そうなの! あたしの言うことを聞いとけばいいのさ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_013"] = "もっと自信を持ちな。 マックスより頭が良くて才能あるヤツなんていないよ",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_015"] = "人をレイチェル信者みたいに言うなよ |それにマックスも男子に人気あんだろ? |ウォーレンとか…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_016"] = "そんな顔すんな。 ずっと一緒にいるから…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_023"] = "いい人? なんだ 脈なしなのか",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_024"] = "なに言ってんだか。 それにあたしは田舎者とは気が合わないんだ",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_025"] = "オタクでもいいじゃん。 もっと自分に自信を持てって",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_026"] = "心配すんな。 弱い自分さえ克服すれば なんだってできる",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_002"] = "どうにかね。 でも… もし失敗してたら? |もしクロエもケイトも死んでいたら…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_003"] = "どうにかね。 でも… もし失敗してたら? |ケイトは助かったけど クロエは… 死んでたよ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_004"] = "あのときはね。 でも それはクロエのおかげで力が覚醒したから…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_007"] = "そうだね。 クロエがいると自信がわいてくるよ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_008"] = "どうだろう…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_009"] = "ホントに…?",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_010"] = "分かったけど… 力を無駄使いさせないでよ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_014"] = "レイチェル・アンバーでも?",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_017"] = "ウォーレンは… いい人だよ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_018"] = "モテるのはクロエでしょ。 ワルっぽくて…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_019"] = "やだ この学校の男子になんかモテたくないよ |何人か格好いい人はいるけど どうせ私はオタクだと思われてるし…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_020"] = "ううん ウォーレンはイケてるよ |ネイサンから守ってくれたし… |でも 力のことはまだ… 教えてないんだ…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_021"] = "それもそうだね… どっちにしろ それどころじゃないんだし",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_022"] = "それだけは いくら巻き戻しても無理かな…",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_027"] = "クロエと一緒ならね…",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase01_Chloe_001"] = "おーい 電気はまだー?",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase02_Chloe_001"] = "ここは無理だ! 他の場所を探せ!",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase03_Chloe_001"] = "さ 着替えて帰ろうぜ",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_010"] = "最高! お風呂みたい! 金も手に入ったし もうこの世界はあたしのモンだ!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_020"] = "最高! お風呂みたい! |お金をみすみす置いてきたことだけが 心残りだけどな…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_025"] = "ジャン ジャン ジャン ジャン ジャン ジャン ジャン ジャン…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_030"] = "まさか 突っ立って見てるだけじゃないよな?",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_070"] = "悔しかったら来いよ!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_100"] = "あ カワウソ発見!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_130"] = "ズルだ!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_150"] = "レイチェルもいればな。 夜のプール 気に入ったと思う |2 人を会わせたかったよ…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_190"] = "その力がすべてを変えたな。 特にマックス自身を |臆病者でウジウジしてたのは昔の話だ",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_210"] = "うるさい。 なんていうか マックスが「力」そのものなんだよ",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_240"] = "はしゃぐつもりが おしゃべりになっちゃったからな… まあ いいか |もう 1 年分くらいプールに入った気がする。 出よう",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_060"] = "ちょっと…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_080"] = "子どもなんだから",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_090"] = "せーの!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_110"] = "出たよ。 それ分かってても怖いんだから やめて |サメのショーとかも無理なんだから",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_120"] = "次やったら 巻き戻して水に沈めるよ",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_140"] = "ズルって それクロエが言う?",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_160"] = "きっと会えるよ。 いろいろあったけど すべてつながっている気がするんだ…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_170"] = "亡くなったケイトのためにも 真相を突きとめなきゃ…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_180"] = "ケイトのためにも真相を突きとめる。 自殺しようとするなんて…",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_200"] = "それ褒めてる?",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_220"] = "むしろ「謎」そのものだよ |ケイトのときも 急に力を使えなくなったし… |ひたすら時間を行き来してるだけ… |でも なんのために?",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_230"] = "少し冷えてきたね",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_250"] = "そうしようか。 水から出たら凍えるかも…",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Chloe_020"] = "薬品まみれの髪も悪くないよ",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Chloe_070"] = "やばい!",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_010"] = "塩素が体中にしみ込んだ感じ…",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_030"] = "ありがとう。 クロエもね…",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_060"] = "やばい!",
  ["Cue_E3_3A_SwimPool_GuardsArrive_SecurityGuard1_040"] = "いい加減にしろ 悪ふざけもここまでだ… 本気だぞ",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_010"] = "いるのか?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_020"] = "どこに行った?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_030"] = "こっちで音がしたぞ",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_040"] = "おい",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_050"] = "誰だ?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_060"] = "隠れてもしょうがないぞ!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_070"] = "誰かいるのか?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_080"] = "おい!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard3_010"] = "周囲をしっかり調べるんだ!",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_020"] = "そんなことより温水プールだ!",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_050"] = "その力があれば怖いもんなしだって",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_060"] = "どっちにする?",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_070"] = "やはり変態か…",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_080"] = "女子? へえー…",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_090"] = "温水になってっかな…",
  ["Cue_E3_3A_SwimPool_Insertion_Max_010"] = "ほんとに来ちゃったよ!",
  ["Cue_E3_3A_SwimPool_Insertion_Max_030"] = "見つからないように用心しようね? 停学中とはいえ…",
  ["Cue_E3_3A_SwimPool_Insertion_Max_040"] = "見つからないように用心しようね? 私 生徒なんだし…",
  ["Cue_E3_3A_SwimPool_MaxLocker_Chloe_020"] = "逃げるよ!",
  ["Cue_E3_3A_SwimPool_MaxLocker_Max_010"] = "さすが私!",
  ["Cue_E3_3A_SwimPool_MaxOpenDoorFromInside_Chloe_020"] = "またそれかよ! もうそのパターン飽きたって",
  ["Cue_E3_3A_SwimPool_MaxOpenDoorFromInside_Max_010"] = "じゃーん!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_Chloe_030"] = "隠れて! 早く 早く!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_David_010"] = "周囲をしっかり調べるんだ!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_Max_020"] = "勘弁してよ…",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Chloe_010"] = "プールの電気をつけてよ! ムードを出そうぜ",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Chloe_030"] = "バーカ… いいから早く!",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Max_020"] = "いい雰囲気にしてどうするつもり?",
  ["Cue_E3_3B_CampusPark_ExitGirls_Chloe_020"] = "ふざけてるぜ",
  ["Cue_E3_3B_CampusPark_ExitGirls_Chloe_040"] = "なんなんだよ!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_010"] = "待って 逆方向。 向こうから来る!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_030"] = "戻って!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_050"] = "別の道を探さないと!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_010"] = "寮に戻る気かよ 見つかったらヤバいぞ! うちに来な",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_040"] = "乗って!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_050"] = "こいつを走らせるの手伝って…",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_060"] = "今だ!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_070"] = "早く!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_080"] = "ハハハ! じゃなー! やったぜ マックス! あたしたち最高だ!",
  ["Cue_E3_3B_CampusPark_GetAway_Max_020"] = "警備主任の家に泊まったほうが安全だって言うの? 本気?",
  ["Cue_E3_3B_CampusPark_GetAway_Max_030"] = "停職に追い込んだ警備主任の家に泊まったほうが安全だって言うの? 本気?",
  ["Cue_E3_3B_CampusPark_GetAway_Max_090"] = "あードキドキした…",
  ["Act_E3_5A_Bathroom_Bird_Look01_Max_010"] = "あれっ… 月曜日におばさんの部屋で助けた青い鳥だ…",
  ["Act_E3_5A_Bathroom_ChildishSponge_Look01_Max_010"] = "この汚い海賊のタオル クロエが子どものときから持ってた… 思い出しちゃった",
  ["Act_E3_5A_Bathroom_HairDye_Look01_Max_010"] = "今まで髪を青く染めようなんて思ったことなかったけど… いい機会かも?",
  ["Act_E3_5A_Bathroom_Mirror_Interact01_Max_010"] = "マッド・マックス参上! かましてやるぜ! なーんてね",
  ["Act_E3_5A_Bathroom_Tap_Interact01_Max_010"] = "プールの塩素で顔がすごくべたついてたからすごく気持ちいい…",
  ["Act_E3_5A_Bathroom_TeethBrush_Interact01_Max_010"] = "私は人に歯ブラシ使われたらイヤだけどね…",
  ["Act_E3_5A_Bathroom_TeethBrush_Look01_Max_010"] = "クロエは自分の歯ブラシを使われても気にしなかったな…",
  ["Act_E3_5A_ChloeRoom_Bills_Look01_Max_010"] = "地獄に落ちるかもしれないけど クロエのためなら… |あとで返そう… どうにかして",
  ["Act_E3_5A_ChloeRoom_CHChloe_Look01_Max_010"] = "障害者基金を盗まなかったことをそれほど気にしてないみたい…",
  ["Act_E3_5A_ChloeRoom_CHChloe_Look02_Max_010"] = "お金を手に入れて落ち着いてるみたい。 あれ 障害者基金だけど…",
  ["Act_E3_5A_ChloeRoom_Camera_Interact01_Max_010"] = "この瞬間を忘れないように…",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look01_Max_010"] = "私の写真にしてくれてるかなと思ったけど… レイチェルには勝てないね…",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look02_Max_010"] = "やった! 私の写真にしてくれてた… また大切な存在になれたんだ…",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look03_Max_010"] = "やっぱりあのお金を取ってきてよかった… この人本気でヤバい…",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look04_Max_010"] = "これってまずいよ… お金を取ることに反対しなければよかった…",
  ["Act_E3_5A_ChloeRoom_ChloeRoomDoor_Interact01_Max_010"] = "まずは服を着なさい",
  ["Act_E3_5A_ChloeRoom_ChloeWallet_Look01_Max_010"] = "レイチェルの写真と一緒に持ってくれてるんだ… うれしいな",
  ["Act_E3_5A_ChloeRoom_ClosetDoor_Interact01_Max_010"] = "ではクロエのコスプレをしようか…",
  ["Act_E3_5A_ChloeRoom_Closet_Look01_Max_010"] = "もしずっと隠れてたら 停学にはならなかったよ…",
  ["Act_E3_5A_ChloeRoom_Closet_Look02_Max_010"] = "クローゼットに隠れればよかったのかも。 そうすれば停学にはならなかった…",
  ["Act_E3_5A_ChloeRoom_Closet_Look03_Max_010"] = "ここから飛び出てクロエがぶたれるのを止めなかったことが今でも後ろめたい…",
  ["Act_E3_5A_ChloeRoom_Closet_Look04_Max_010"] = "あのまま隠れてたら デイビッドに目を付けられなかったね…",
  ["Act_E3_5A_ChloeRoom_Closet_Look05_Max_010"] = "クローゼットに隠れていれば デイビッドに目を付けられなかったね…",
  ["Act_E3_5A_ChloeRoom_DavidGun_Look01_Max_010"] = "フランクは手出しし難くなったかもしれないけど もしデイビッドに知られたら…",
  ["Act_E3_5A_ChloeRoom_Drawer01_Interact01_Max_010"] = "あ この電話覚えてる! 一緒にデコったんだよね",
  ["Act_E3_5A_ChloeRoom_Drawer02_Interact01_Max_010"] = "モッシュに参加するわけじゃないし…",
  ["Act_E3_5A_ChloeRoom_HiFi_Look01_Max_010"] = "この曲好き",
  ["Act_E3_5A_ChloeRoom_HiFi_Look02_Max_010"] = "今の曲 もう 1 回かけてよ",
  ["Act_E3_5A_ChloeRoom_Joint_Look01_Max_010"] = "クロエをかばうべきだったかな… そうすればぶたれなかったし…",
  ["Act_E3_5A_ChloeRoom_Joint_Look02_Max_010"] = "どうせ停学になるんだったら …って ダメだよね",
  ["Act_E3_5A_ChloeRoom_Joint_Look03_Max_010"] = "デイビッド よく私を見逃してくれたな…",
  ["Act_E3_5A_ChloeRoom_Joint_Look04_Max_010"] = "クロエがぶたれてるのに隠れてたなんて ほんと意気地なし…",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact01_Max_010"] = "考え方は否定しないけど… ケイトに嫌がらせをする理由なんてなかったはず",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_010"] = "とりあえず正体はバレてない… 今はね…",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_020"] = "行かないと。 お別れを言う最後のチャンスだから…",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_030"] = "大丈夫そうでよかった。 いつお見舞いにいけるかな…",
  ["Act_E3_5A_ChloeRoom_Laptop_Look01_Max_010"] = "このラップトップでニュースを見てもいいかな?",
  ["Act_E3_5A_ChloeRoom_MajorChoice_DontKiss_Max_010"] = "クロエの向こう見ずなとこ 好きだな…",
  ["Act_E3_5A_ChloeRoom_MajorChoice_Kiss_Max_010"] = "キスしたときのクロエの顔… まさかって感じだったね…",
  ["Act_E3_5A_ChloeRoom_MaxClothes_Look01_Max_010"] = "とにかく服を着ないと",
  ["Act_E3_5A_ChloeRoom_MaxClothes_Look02_Max_010"] = "うわ… まだ塩素の匂いが残ってる",
  ["Act_E3_5A_ChloeRoom_Paper01_Look01_Max_010"] = "なんか嬉しい… 私が見た夢の意味を本気で探ろうとしてくれてる…",
  ["Act_E3_5A_ChloeRoom_Photo01_Look01_Max_010"] = "これ 私の 10 歳の誕生日だ。 まだ取っておいてくれたんだ…",
  ["Act_E3_5A_ChloeRoom_RachelClothes_Look01_Max_010"] = "レイチェルのスタイルは少しおとなしめだね… 私みたい",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_010"] = "昨日と違って穏やかだ…",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_015"] = "クロエとまた親友になれてよかった…",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_020"] = "シャッターチャンス!",
  ["Act_E3_5A_ChloeRoom_VoiceOverClothes_Max_010"] = "まず服を着ないとね…",
  ["Act_E3_5A_Corridor_ArcadiaBayPoster_Look01_Max_010"] = "この町の人たちは何が起きているか全く知らない… それとも…?",
  ["Act_E3_5A_Corridor_ParentsRoomDoor_Look01_Max_010"] = "中には入らないほうがいい… デイビッドが寝ているかもしれないし…",
  ["Act_E3_5A_Corridor_VoiceOverBreakfast_Max_020"] = "うーん すごくいい匂い… 子どもの頃を思い出すな…",
  ["Act_E3_5A_Corridor_Window_Look01_Max_010"] = "近所の人たちにとっては普段と変わらない朝…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_002"] = "ガキのときみたいに ずっとこうしていられたらって思わない?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_006"] = "あ そう。 分かったよ |もうあのときとは違うってわけね |レイチェルはここが好きだったから 分かってくれただろうな… クソ…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_007"] = "デートもできるし? いつか彼氏を連れてくるんじゃないかって パパ怯えてたな",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_008"] = "もちろん |土曜の朝 起こされたくなくて 2 人で寝たふりをしたときなんか |マックスを思い出したよ…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_010"] = "都合がつけばいつでも |でも 彼女の家のほうがよかったな |クソオヤジが朝早くに起こすからさ… |いいもんだな マックスがここにいるのって",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_012"] = "ないない。 おふざけみたいなのばっか |一時期年下にハマってさ… 他にもいろいろと…ね",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_014"] = "それに下心しかないからな… すぐに分かると思うけど",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_017"] = "よく分かってるじゃん。 そんなときに レイチェルに会って救われたんだ",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_018"] = "なんだ なんだ 変なスイッチ入ったか? |ただ マックスに釣り合う相手はいないって言いたかっただけだ… |あたし以外は",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_021"] = "マックスも好きになってたよ |賢い セクシー オシャレ… あたしみたいだろ?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_022"] = "誰とでも仲良くなれたよ |あたしだけじゃなく いろんなヤツらと接点を持ってたみたいだし…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_025"] = "言ってな! でもありえるな… マックスは写真家 彼女はモデル志望だったから",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_026"] = "じゃあ どこにいるんだよ",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_001"] = "朝日が素敵。 とても穏やか…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_003"] = "だめだよ。 そんな呑気なこと言ってる場合じゃないし…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_004"] = "うん。 でも もう子どもじゃない",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_005"] = "うん。 レイチェルもここを気に入ってたんじゃない?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_009"] = "しょっちゅうお泊り会したの?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_011"] = "そういえば聞いてなかったけど 本気で付き合ってた人っていたの?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_013"] = "男子はトラブルの元だからね",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_015"] = "その辺の男子と付き合ってるとこ想像できない…",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_016"] = "経験者は語るってわけ? じゃあ ファーストキスは誰としたの?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_019"] = "ホントにレイチェルが好きだったんだね",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_020"] = "レイチェルってそんなにみんなから好かれてたの?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_023"] = "はいはい。 案外 私のほうが気に入られたかもよ",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_024"] = "でも クロエとロスに行きたがってたんでしょ?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_001"] = "巻き戻して取り消すなよ |シアトルのアート系男子よりあたしのがセクシーだろ?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_002"] = "知ってるぞ 実はキスをしたのに巻き戻して知らんぷりしてるだろ! さあ吐け!",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_003"] = "なんならクローゼットにきれいな服がないか探してみな",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_004"] = "そろそろ着替えろよ。 ママの朝ごはんが待ってる",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_005"] = "バッチリだな マックス! 下に行ってママに見てもらいなよ。 きっと気に入る",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_010"] = "昨日の夜のせいでくたくた。 でも楽しかった…",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_030"] = "あんなの序の口だぜ",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_050"] = "プールだけで満足してもらっちゃこまるぜ。 もっと上を目指さないと",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_020"] = "すっかり私も犯罪者の仲間入りだ",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_040"] = "正直 誰もいない夜のプールは楽しかった",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_060"] = "でも 力はよく考えて使うべきだよ… どんな反作用があるか分からない…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_010"] = "笑って!",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_040"] = "いい刺激になっただろ?",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_060"] = "拒絶を怖がってちゃ 何もできないよ。 提出しろって",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_080"] = "おいおい 別にあたしはそういうワケじゃ… |ボロクソに言ってたのはここを出たかったから… |マックスがいなくなってから ずっと… |もし レイチェルを見つけて フランクに金を返せても ここにはいられない…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_100"] = "よく言うよ。 停学中だろ",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_120"] = "なんだよ テストでもあるのか?",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_020"] = "せーの!",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_030"] = "昨日とは別世界みたい…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_050"] = "もうこりごり…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_055"] = "私 学校やこの町に貢献したいと思ってる |なのにコンテストの写真すら提出できない |拒絶されるのが怖いんだ",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_070"] = "クロエが嫌いな この町と学校のためでも?",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_090"] = "昔みたく ウダウダしてられたらいいのに… 起きようか |そろそろ学校に戻らないと…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_110"] = "宿題はあるんだよ |提出しないと親に連絡がいって ますます厄介なことになる…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_130"] = "毎日学校に行くことがテストみたいなものだよ。 学生らしい生活に戻らないと…",
  ["Cue_E3_5A_ChloeRoom_KissChoice_Max_010"] = "そういうこと言うと 友だちやめるよ",
  ["Cue_E3_5A_ChloeRoom_Kiss_Chloe_010"] = "マジで… マジでやった! |ウォーレンにメールして 脈がないことを知らせてやんないと… |ま 百合好きなら別だけど",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_020"] = "あたしのクローゼットから何か探しなよ",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_030"] = "ほら それ! レイチェルの服が残ってるだろ。 サイズも合うはず",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_050"] = "ぜいたく言うなよ。 いいから試してみな |いつだって塩素臭い T シャツと地味なデニムに巻き戻せるんだし",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_070"] = "言い訳はいいよ! |それ着て 内なるパンクロック魂を解き放て! 失うものなんてないんだから |何でもまずはやってみればいいんだって… |例えば… あたしにキスするとか!",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_100"] = "ほら やってみて。 キス",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_010"] = "うわ… まだ塩素の匂いが残ってる",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_040"] = "でも私っぽくない",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_060"] = "ひどい。 シャツもデニムも好きなのに… |でも 試着してみるのも 楽しいかも |入ればだけど…",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_090"] = "えっ!?",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_010"] = "いいよ マックス! タトゥーとピアスを足せば 立派なパンク娘だ",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_030"] = "やっぱナイわ… |下行ってママに会ってきな。 朝ごはんだ |あたしは寝起きの一服してから…",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_050"] = "そうしてくれるとありがたいよ",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_070"] = "なんだよ ケチケチするなよな",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_020"] = "モッシュ上等 チェケラッチョ!",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_040"] = "誰にも言わないよ",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_060"] = "今回は身代わりにはならないよ",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Chloe_020"] = "なにそれ? 本当はキスしてから巻き戻したくせに! |ウォーレンにメールしないと… |マックスはキミを愛してるって…",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Max_010"] = "その手には乗らないよ",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Max_030"] = "バカじゃないの",
  ["Act_E3_5B_ChloeRoom_BigPadlock_Max_010"] = "軍用の南京錠… デイビッドらしいね",
  ["Act_E3_5B_ChloeRoom_BigPadlock_Max_020"] = "暗証番号が読み取れる… これがパスワードかも…",
  ["Act_E3_5B_Garage_BlackwellCamerasProject_Look01_Max_010"] = "ふむ。 この ID 番号は使えるかも…",
  ["Act_E3_5B_Garage_Car_Look01_Max_010"] = "今にも走り出しそう。 監視よりもこっちのほうがいい趣味だよね…",
  ["Act_E3_5B_Garage_Cupboard01_Interact01_Max_010"] = "何も入ってない",
  ["Act_E3_5B_Garage_Cupboard02_Interact01_Max_010"] = "特に何もなし",
  ["Act_E3_5B_Garage_DavidLaptop_Interact06_Max_010"] = "何やってんの。 パソコンが固まったよ…",
  ["Act_E3_5B_Garage_DavidLaptop_Look03_Max_010"] = "ロックされちゃった。これじゃもうパスワードを入力できない…",
  ["Act_E3_5B_Garage_DeerHead_Look01_Max_010"] = "2001 年から こんな悪趣味なの飾ってるの?",
  ["Act_E3_5B_Garage_DinerSign_Look01_Max_010"] = "もうプロポーズしてるようなものだね…",
  ["Act_E3_5B_Garage_DinerSign_Look01_Max_020"] = "これがパスワードかも…",
  ["Act_E3_5B_Garage_Drawer02_Interact01_Max_010"] = "「新しいパパ」… パスワードに使ってたりしないかな…",
  ["Act_E3_5B_Garage_Laptop_Interact01_Max_010"] = "パスワードがかかってる… 「クソオヤジ」じゃ… ないよね… |何か手がかりないかな…",
  ["Act_E3_5B_Garage_Laptop_Interact02_Max_010"] = "パスワードを見つけないと。 探そう…",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_020"] = "だめ",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_030"] = "あーもう!",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_040"] = "ぜんぜん違う",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_050"] = "気になる結果は… はずれ",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_060"] = "うーん だめだめハッカー…",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_070"] = "もう 1 回…",
  ["Act_E3_5B_Garage_Laptop_Interact04_Max_010"] = "やった! 私 ハッカーの才能あるね!",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_010"] = "見張る人を間違えてるよ。 ちゃんとしてたら ケイトはこんなことに…",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_020"] = "尾行してる暇があったなら助けられたはずなのに…",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_030"] = "なにこれ… 気持ち悪い…",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_040"] = "うわっ特ダネ! レイチェルはフランクと付き合ってたんだ… |でもどうしてデイビッドが気にするの?",
  ["Act_E3_5B_Garage_Laptop_Look01_Max_010"] = "デイビッドが調べた情報はこのパソコンの中にあるはず",
  ["Act_E3_5B_Garage_Laptop_Look02_Max_010"] = "このパソコンを調べて答えを見つけよう…",
  ["Act_E3_5B_Garage_Object01_Look01_Max_010"] = "デイビッド・マドセンも誰かにとっては恩人なのかも…",
  ["Act_E3_5B_Garage_Object02_Look01_Max_010"] = "いいね… パスワードに使えるかも",
  ["Act_E3_5B_Garage_Object03_Look01_Max_010"] = "デイビッドの両親から? この日付がパスワードかも…",
  ["Act_E3_5B_Garage_Object04_Look01_Max_010"] = "これを付けた車におばさんを乗せて走ってるところは想像できないよ…",
  ["Act_E3_5B_Garage_Object05_Look01_Max_010"] = "この本を何度も読んだみたい。 何を学んだんだろう?",
  ["Act_E3_5B_Garage_Scripted_Max_010"] = "クロエに知らせなきゃ… 悲しむだろうな… というか怒るだろうな…",
  ["Act_E3_5B_Garage_WeaponClosetLock_Look01_Max_010"] = "クロエはもう銃を入手できないね。 フランクから盗んで取り戻す以外は…",
  ["Act_E3_5B_Garage_WeaponClosetLock_Look02_Max_010"] = "銃を戻そうにも もう無理だよ クロエ…",
  ["Act_E3_5B_Garage_WeaponCloset_Look01_Max_010"] = "この番号をパスワードにしてたりして…",
  ["Act_E3_5B_Garden_DeadBird01_Look01_Max_010"] = "鳥が死んでる。 かわいそうに…",
  ["Act_E3_5B_Garden_DeadBird02_Look01_Max_010"] = "どうして死んだんだろう…",
  ["Act_E3_5B_Garden_DeadBirds_Look01_Max_010"] = "3 羽も列になって死んでる… 不吉だよ…",
  ["Act_E3_5B_Garden_Swing_Look01_Max_010"] = "ブランコに乗ると落ち着く…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_010"] = "クロエと順番こで乗ってたことを思い出すな…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_020"] = "上まで高く上がれるようにお互い力いっぱい押したっけ…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_030"] = "クロエはいつもぐるっと 1 回転したがってた…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_040"] = "私はいつも怖くなって その前に飛び降りてた…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_050"] = "そしてクロエは今でも飛ぼうとしている…",
  ["Act_E3_5B_LivingRoom_Bird_Interact01_Max_010"] = "鳥さん出てって! ほら飛んで!",
  ["Act_E3_5B_LivingRoom_Bird_Look02_Max_010"] = "かわいそうに… なんか怯えてるみたい…",
  ["Act_E3_5B_LivingRoom_CHChloe_Look01_Max_010"] = "これでクロエの味方だって証明できたかな",
  ["Act_E3_5B_LivingRoom_CHDavid_Look01_Max_010"] = "デイビッド 私もうあなたが怖くないよ…",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look01_Max_010"] = "普段着のおばさんはいつもと全然違う…",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look02_Max_010"] = "おばさん… デイビッドを責めたことで私を嫌いになったかな",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look03_Max_010"] = "おばさんのためとはいえ デイビッドに甘くしすぎたかも…",
  ["Act_E3_5B_LivingRoom_DinnerPlate_Look01_Max_010"] = "やっぱ朝はパンケーキ!",
  ["Act_E3_5B_LivingRoom_DinnerPlate_Look02_Max_010"] = "ベーコンエッグ 早く食べたいな!",
  ["Act_E3_5B_LivingRoom_Eggs_Interact01_Max_010"] = "ニワトリより卵が先… っておばさんの口癖",
  ["Act_E3_5B_LivingRoom_Flyer_Look01_Max_010"] = "今回だけはこの人たちが正しいのかも…",
  ["Act_E3_5B_LivingRoom_Fridge_Interact01_Max_010"] = "野菜を食べた方がいいんだけど… ベーコンは捨てがたい",
  ["Act_E3_5B_LivingRoom_Fridge_Look01_Max_010"] = "昔と同じ冷蔵庫で嬉しい…",
  ["Act_E3_5B_LivingRoom_GarageDoor_Interact01_Max_010"] = "おばさんと話して 朝ごはんを食べるまでは帰れない",
  ["Act_E3_5B_LivingRoom_GarageDoor_Interact02_Max_010"] = "デイビッドのパソコンのパスワードを見つけないと…",
  ["Act_E3_5B_LivingRoom_Milk_Interact01_Max_010"] = "ミルクを確保…",
  ["Act_E3_5B_LivingRoom_NewsPaper_Look01_Max_010"] = "ケイトの人生を食い物にしないでほしい…",
  ["Act_E3_5B_LivingRoom_NewsPaper_Look02_Max_010"] = "こんなことで有名になりたくない…",
  ["Act_E3_5B_LivingRoom_Object04_Look01_Max_010"] = "クロエは今でも同じシリアルを食べてる… 私も…",
  ["Act_E3_5B_LivingRoom_Object05_Look01_Max_010"] = "誰も水やりをしてないみたい…",
  ["Act_E3_5B_LivingRoom_Phone_Interact02_Max_010"] = "さよなら。 今のクロエにこういうのは必要ないよ…",
  ["Act_E3_5B_LivingRoom_Phone_Interact02_Max_020"] = "さよなら",
  ["Act_E3_5B_LivingRoom_Phone_Look01_Max_010"] = "メッセージがあるみたい…",
  ["Act_E3_5B_LivingRoom_Phone_Look03_Max_010"] = "おせっかいなメッセージ… トラブルは間に合ってるよ",
  ["Act_E3_5B_LivingRoom_Phone_Look04_Max_010"] = "あっ… おばさんやクロエあてじゃなければいいけど…",
  ["Act_E3_5B_LivingRoom_TV_Interact01_Max_010"] = "どうなってるの? 竜巻が本当にくるの?",
  ["Act_E3_5B_LivingRoom_VoiceOverCook_Max_010"] = "卵とミルク 了解",
  ["Act_E3_5B_LivingRoom_VoiceOverCook_Max_020"] = "卵とベーコンね",
  ["Act_E3_5B_LivingRoom_VoiceOverLaptop_Max_010"] = "デイビッドのパソコンを調べないと… 絶対何か隠してるはず…",
  ["Act_E3_5B_LivingRoom_Window_Look01_Max_010"] = "いつか空が赤くなっても不思議じゃないよね…",
  ["Cue_E3_5B_Kitchen_BeerBottle_Max_010"] = "こんな朝早くから誰がビールを飲むのかな…",
  ["Cue_E3_5B_Kitchen_PeanutButter_Max_010"] = "粒入りじゃなくてクリーミーでよかった…",
  ["Cue_E3_5B_LivingRoom_BirdPuzzle_Joyce_010"] = "なんだ… ちょっと この鳥を外に出してくれるかい?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Chloe_170"] = "よい 1 日を!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_020"] = "うるさい お前がクロエの部屋でやったことは忘れてないぞ",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_050"] = "クロエが問題ばかり起こすからだろう!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_100"] = "お前らにどうこう言われる筋合いはない。 このクソガキどもが",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_120"] = "お前まで逆らうのか? |そうだ 女ってヤツはすぐに結託しやがる |まったく 冗談じゃない!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_140"] = "俺を追い出す気か? ここは俺の家だぞ",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_160"] = "言ってもムダだろ… 多勢に無勢だ",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_070"] = "何だって? それは本当かい マックス? |ちょっと デイビッド 何でそんなものを持ってるんだい? |一体どういうことなのさ",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_110"] = "ちょっと落ち着きなさい",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_130"] = "デイビッド… ホテルにでも行って頭を冷やしたらどうだい",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_150"] = "いいや ここは私の家だよ。 名義も私だ。 他に言うことは?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_180"] = "クロエ! もういい 黙ってな",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_010"] = "私見たんです |ケイト・マーシュが苦しんでたとき あなたは助けるどころか脅しましたよね |あなたにとって生徒は全員容疑者なんでしょ… ネイサン・プレスコット以外は |生徒も先生も 誰もあなたを良く思ってない |仕事だけじゃなくて 周りのことも考えたらどうですか",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_030"] = "それが 家族や学校のみんなを監視する口実? |じゃあ なんでケイトとレイチェルの写真を持ってるんですか?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_040"] = "私見たんです |ケイト・マーシュが苦しんでたとき あなたは助けるどころか脅しましたよね |あなたにとって生徒は全員容疑者なんでしょ… ネイサン・プレスコット以外は |生徒も先生も 誰もあなたを良く思ってない |そのうえクロエまでぶって… |仕事だけじゃなくて 周りのことも考えたらどうですか",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_001"] = "マックス! あたしの救世主!",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_002"] = "ごめん? すごかったじゃん! |あいつを言葉でぶちのめしたんだぜ! |気分はどうよ?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_004"] = "だろ? さすがだよ。 ママもようやく追い出す気になってくれた",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_005"] = "ママは現実が見えてなかったんだ。 でも やっと追い出す気になってくれた",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_006"] = "さっきはアツくなってごめん…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_007"] = "やっと言うべきことを言えて 気持ちよかった…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_008"] = "おばさんの前であんなこと言って後悔してる…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_009"] = "うん… でも 今重要なのはデイビッドじゃない |レイチェル それにフランクだよ…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_001"] = "どういうつもりだ マックス",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_002"] = "まさかあたしをぶった相手をかばうなんてな。 それでも親友?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_003"] = "まさかクソオヤジをかばうなんてな。 それでも親友?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_004"] = "命の恩人だからって偉そうにするなよ! クソオヤジは…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_005"] = "巻き戻さなくてもクロエが何を言いたいかは分かる…",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_006"] = "余計なトラブルを防ぐのも 親友の務めだよ",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_007"] = "あのね… 今は親子げんかをしいる場合じゃないの",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_008"] = "確かにデイビッドはむかつく… |でも今重要なのはレイチェル それにフランクだよ",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_001"] = "またもやガッカリだよ |クソオヤジの味方をするマックスなんて記憶から消したい",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_002"] = "さっきは感動した。 巻き戻して取り消すなよ!",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_003"] = "準備ができたら行くよ",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_001"] = "やれやれ… お前 俺の結婚生活を壊して満足か?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_002"] = "やれやれ… 俺をクビにしたうえ 結婚生活もぶち壊して満足か?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_003"] = "認めてやるよ。 度胸だけはあるな。 男に生まれていれば…",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_004"] = "俺は誰も脅しちゃいない。 自分を守ってるだけだ",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_005"] = "まったく… クロエと同じようなことを言いやがって…",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_009"] = "さもないと? それは脅しか? やれるもんならやってみろ いつでもな",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_006"] = "人を脅すことしかできない男に言われても 嬉しくありません",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_007"] = "私は女です。 そもそも何が言いたいんですか?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_008"] = "もう関わらないでください。 クロエにも。 さもないと…",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_001"] = "マックス… 俺の肩を持つ必要なんてなかっただろう。 なぜだ?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_005"] = "いいか 俺はいつも 2 人のために温かい家庭を守ろうとしてきたんだ",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_006"] = "そうか… ありがとう。 俺はただ家族を守りたいだけだ",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_008"] = "マックス 戦場に安全なんてものは存在しない |お前はまだ若いから この町のことを知らない… いや… |一線を越える必要も… ときにはあるんだ",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_002"] = "クロエとおばさんのためです",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_003"] = "分かりません。 そうした方が良いと思っただけで",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_007"] = "でも やり過ぎです",
  ["Cue_E3_5B_LivingRoom_CHDavid_QuickPhase_David_001"] = "かばってくれてありがとう。 だが これは家族の問題だ",
  ["Cue_E3_5B_LivingRoom_CHDavid_QuickPhase_David_002"] = "お前の顔も見たくないし 声も聞きたくない。 家族のことに口を出しやがって…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_002"] = "言いたいことは分かるよ |でも いつかレイチェルがひょっこり戻ってきたり |クロエに連絡してくるんじゃないかってね… 考えるのさ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_003"] = "そう願ってた… 願ってるよ| レイチェルは… 賢いし 世渡り上手で… |ただ 私には見せていない部分があったのかもね… |クロエにも…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_004"] = "クロエは周りとぶつかってたけど レイチェルとは仲良くやってた |まるであんたたちみたいにね… |でも あんたの方がしっかりしてるかな",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_005"] = "そうだね |捜査番組なんて見ると レイチェルが出るんじゃないかって気分が悪くなる… |だから 考えないようにしてるよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_012"] = "マックスったら あんた レイチェルに嫉妬してるの?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_015"] = "バカ言いな |クロエと一緒に海賊ごっこしてるのを見たとき |あんた以上の友だちはいないって思ったんだ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_016"] = "そうかい? でも クロエはあんたみたいになりたいって言ってたよ |5 年間ずっとね",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_018"] = "あんたがクロエをかばったとき それが確信に変わったよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_019"] = "ただ デイビッドがクロエに手をあげた件… あれを止めていてくれたらね…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_023"] = "そんなこと言ったら私はどうなるのさ? |あんたまだ 18 だろ |若いねー 私も時間を巻き戻したいよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_001"] = "私もそう願ってます。 だけど…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_006"] = "正直な話… レイチェルは無事だと思う?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_007"] = "レイチェルはクロエに怒ったりしてなかった? それでいなくなったとか…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_008"] = "こんなこと考えたくないけど もしかしてレイチェルは… |何か事件に巻き込まれたのかも",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_009"] = "私もクロエのことを思ってたより知らないのかも…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_010"] = "私がしっかりしてる? まさか |でも だからクロエはレイチェルが大好きなのかも…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_011"] = "クロエが必死で探す気持ち 分かるな",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_013"] = "ええ? まさか! |引っ越しで置き去りにした私より いい友だちができてうれしいよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_014"] = "そうかも。 レイチェルは私よりずっとステキだから…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_017"] = "まさか でも… 本当に? 5 年前ってなんだかすごく昔みたいで…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_020"] = "ありがとう…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_021"] = "うん…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_022"] = "でも 海賊ごっこなんて 大昔の話だよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_024"] = "そんないいものじゃないよ…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_001"] = "なんだい",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_003"] = "まさか 自分に怒ってるんだよ。 こんなことに巻き込んじゃって悪いね",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_006"] = "デイビッドをこの家に連れてきたのは私だよ |あの人 クロエには厳しかったけど 私には優しくてね。 優しすぎるぐらいだ…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_008"] = "どうだかね。 もう あの人を信じる気になれないよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_002"] = "おばさん… 私のこと… 怒ってる?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_004"] = "そんな おばさんのせいじゃないよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_005"] = "巻き込んじゃったのは私だし",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_007"] = "デイビッドは幸せ者だと思う",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_001"] = "なんだい",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_003"] = "どうしてだい? あんたはデイビッドをかばってくれた |クロエじゃこうはいかないよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_006"] = "あの子はすべてに対して怒ってるんだよ |1 日 平和に過ごすことすらできやしない",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_007"] = "私も分からないわけじゃないよ。 ただ あの子は自ら敵を作ってるだけだ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_009"] = "私はデイビッドのおかげで幸せだよ。 あとはクロエさえ心を開いてくれればね…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_002"] = "おばさん こんなことになってごめんなさい",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_004"] = "クロエ すごく怒ってるよ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_005"] = "クロエの気持ちも分かるな…",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_008"] = "そうだね。 私はただ 2 人に幸せになって欲しいだけ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_001"] = "頼んだよ 材料が揃ったらすぐ作るから",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_002"] = "ほら 座って待ってて。 もうすぐお腹いっぱい食べさせてやるから",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_003"] = "まったく…。 クロエは揉め事ばかり持ち込んでくれるね",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_004"] = "マックス 自分を責めるんじゃないよ |デイビッドの自業自得なんだ。 分かったね?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_005"] = "マックス デイビッドと私たち家族の味方をしてくれて ありがとう |クロエじゃこうはいかないよ",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_010"] = "あたしの悪口言って盛り上がってたんだろ?",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_050"] = "時間を稼ぐから ガレージに行って",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_070"] = "こっちの勝手だろ。 ったく この家にプライバシーってもんはないのかよ",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_100"] = "なんだよ 味方してくれないのか",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_120"] = "うるせえよ!",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_040"] = "ちょっとクロエ。 朝からケンカを売るんじゃないよ。 さっさと食べな",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_060"] = "何をコソコソしゃべってんだい",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_080"] = "聞いただけじゃないか。 何をそんなに怒るんだい…",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_110"] = "まったく この子は…",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_115"] = "いいから 少し落ち着きなさい…",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Max_030"] = "自意識過剰だよ…",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Max_090"] = "あの… お手洗い借りるね",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Chloe_020"] = "そうかよ? マックス様はお優しいねえ ||こいつの怪しい行動も クラスメイトのファイルの件も どうでもよくなったのか? |マックスも不審に思って…",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Chloe_060"] = "好きにしな。 行くぞ マックス",
  ["Cue_E3_5B_LivingRoom_DefendDavid_David_050"] = "同感だな。 俺も今は仕事のことを忘れたい |ゆっくりとジョイスの朝飯を食べさせてくれ",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Joyce_040"] = "やめな! 無闇に人のことを責めるもんじゃないよ |この家でそういう話をするのはやめてくれ。 もうたくさんだ",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Max_010"] = "あの 私たちデイビッドが何をしたか知らないし 証拠があるわけじゃないの |分かっているのは ネイサン・プレスコットが危険だってことだけ |だから決めつけるのは…",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_190"] = "それだけじゃない 学校に監視カメラまでつける気なんだろ。 いい趣味してるぜ",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_210"] = "あたしが悪いっての? 自分のことは棚に上げやがって",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_230"] = "あたしが退学になったとき 負け犬呼ばわりしたよな… |負け犬はどっちだよ? |レイチェルとケイトのことだって 調査どころか |迷惑しかかけてねえだろ!",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_010"] = "うまそうだな",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_030"] = "もうブラックウェルの警備主任じゃないからな",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_050"] = "校長にでも聞いたらどうだ |退役軍人で警備のプロである俺じゃなく |問題しか起こさない生徒の話を信じたアホめ",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_060"] = "もうこれが最後だ。 弁護士を呼んで訴えてやる",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_065"] = "やっぱりここにいたか。 レイチェルの服なんか着て なんのつもりだ?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_080"] = "何が言いたい? お前もクロエも偉そうな口をききやがって",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_100"] = "事件の調査で徹夜明けだ。 仮眠を取りにきた",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_120"] = "クズどもが夜のプールに押し入ったんだ |まったく どうなってんだ この学校は! |調子に乗った生徒しかいないじゃないか!",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_140"] = "他に誰がいる? 証拠はすぐそろう",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_150"] = "やっぱりここにいたか。 レイチェルの服なんか着て なんのつもりだ?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_170"] = "停学になってよかったな。 自由な時間がたっぷりできたろう",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_200"] = "やめろ クロエ。 それとこれは別だ",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_220"] = "いいから やめろ。 黙れ",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_020"] = "あら… なんでこんな時間に?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_040"] = "何があったの?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_055"] = "また? 何回 学校でトラブルを起こすつもりだい",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_090"] = "やめて デイビッド。 クビになったなんて嘘だと思いたいよ… |でも そうなるのも無理ないね |かわいそうな生徒たちを脅してたんだろ?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_130"] = "生徒の仕業だって証拠はあるのかい?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_180"] = "やめて デイビッド。 生徒を脅さないでちょうだい",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Max_070"] = "誰の服か分かるんだ",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_020"] = "レイチェル! |ああ えっとマックス… 驚いた |その服ぴったりじゃないか。 まあ 中身はあの子たちとは違うけどね |で 何が食べたい?",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_040"] = "そうじゃないかと思ったよ。 あんたもウィリアムも 大好物だったからね",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_060"] = "それじゃあ ちょっと手伝ってくれるかい? 卵とミルクを持ってきて",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_080"] = "昔はよく 「卵とベーコンが焼けたよ!」って起こしに行ったっけ",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_100"] = "それじゃあ ちょっと手伝ってくれるかい? 卵とベーコンを持ってきて",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_010"] = "おばさん おはよう",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_030"] = "おばさんのパンケーキが食べたいな",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_050"] = "そうそう 山盛りのをうばい合って食べてたっけ",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_070"] = "卵とベーコン焼いて!",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_090"] = "そうそう。 それで飛び起きてたよ",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_005"] = "ありがと",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_010"] = "ここ数年で色んなことがあったけど あんたとクロエがまた仲良くなれてよかった |レイチェルが失踪してからあの子は… |ああ その服を見ると思い出すね |レイチェルはいい子だった。 ロスで元気にしてるといいけど",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_020"] = "さあ みんなお待ちかねの朝食だよ。 そろそろ席について",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_020"] = "嫌味かしら",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_030"] = "あんたに会って… 本当にいろんなことを思い出したよ",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_040"] = "あんたの写真には到底及ばないと思うけど…",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_070"] = "あの人も私たちの幸せを願ってる。 うまく表せないだけで",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_090"] = "いつものあんたも素敵だよ",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_110"] = "そりゃよかった… ウィリアムがこれを撮ったんだ |結局 彼の最後の写真になったけど… |このあとすぐに車で出かけて… |そして…",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_130"] = "ごめん 湿っぽくなったね |そうだ この写真をもらってくれないか… |この頃のクロエは明るくて生き生きとして 前向きで… 今とは全然違う |本当に幸せなあの子を見たのは この日が最後",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_010"] = "ありがとう おばさん。 でも ここにいたら太っちゃうね",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_050"] = "私のお気に入りの写真家もこんな写真を撮るの",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_060"] = "デイビッドは幸せだね",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_080"] = "やっぱレイチェルみたいに この服 着こなせないな",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_100"] = "懐かしい… この写真 よく覚えてる",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_120"] = "うん… そうだったね…",
  ["Cue_E3_5B_LivingRoom_Phone_AnsweringMachine_010"] = "消去しました",
  ["Cue_E3_5B_LivingRoom_Phone_Interact01_Joyce_010"] = "何だって? もう… またかい クロエ 今度は何だい?",
  ["Cue_E3_5B_LivingRoom_Phone_Interact01_OfficerCorn_010"] = "デイビッド コーン巡査だ。 知らせたいことがある |お宅の娘さんの車が ゆうべブラックウェル付近で目撃された |例の事件が起こった頃だ… 至急連絡をくれ",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_020"] = "なんだよ さっきはあいつをかばったくせに",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_050"] = "いやな予感がする。 もう勘弁してくれよ…",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_065"] = "そんなバカな。 フランクをからかってただけだろ",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_080"] = "なんでだよ?",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_100"] = "もしそうだとしたら 今度こそ殺してやる",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_010"] = "クロエ デイビッドのファイルについて話したいんだけど…",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_030"] = "これは大事なことなの",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_040"] = "クロエ デイビッドのファイルについて話したいんだけど…",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_060"] = "これは大事なことなの",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_062"] = "あのね |デイビッドのパソコンの中に レイチェルとフランクが一緒にいる写真があって… |そういう関係だったみたい",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_067"] = "クロエ 私 写真については詳しいつもりだよ? |あれはホンモノだって |信じないなら フランクの車で実際に確かめてみようよ… |ほら! ダイナーに停まってる!",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_070"] = "信じないなら フランクの車を見に行こうよ",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_090"] = "レイチェルのブレスレットを持ってたんだから 他にも何かあるかも…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_006"] = "だってそうだろ。 それともあたしが全部悪いってのかよ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_007"] = "ケイト・マーシュの自殺は悲しいよ |でも あたしの人生がクソだってことには変わりないだろ!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_008"] = "ケイト・マーシュの件は悲しいよ |でも あたしの人生がクソだってことには変わりないだろ!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_009"] = "だって あいつフランクとろくでもない関係だったんだろ? |あたしにウソついてたんだ! もう誰も信じられない |どいつもこいつも 友だちのフリばっかりしやがって! |マックスもそうだろ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_016"] = "分かったよ… ごめん |でも マックスは分かってない |あたしはきっと 不幸にしかなれないんだ…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_017"] = "父親以外に誰がいるんだよ!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_018"] = "そうだよ。 パパはあたしを見捨てて いなくなったんだ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_019"] = "違う パパだよ! |あたしを見捨てて死んだ 本当のパパ! |代用品のクソオヤジじゃねえよ!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_023"] = "そんなの分かってるよ! でも ママは自分を責めてる… |パパに迎えにくるように頼んだから… |あたしだって ときどきママを責めたくなる…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_024"] = "ウソなんかじゃない |マックスには 帰るはずの父親が急にいなくなる気持ち |分からないだろ?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_027"] = "関係ないよ。 あれ以来 あたしの人生はクソまみれだ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_030"] = "ああ ホント余計なお世話だよ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_031"] = "その言葉を信じたいよ… できるなら また何かを信じたい…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_033"] = "もしあたしにマックスの力があれば… 巻き戻してすべてを変えてやるのに!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_005"] = "クロエさ 人生がうまくいかないからって |全部 私とか他人のせいにするのはよくないよ",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_010"] = "起きたことはしょうがないし 誰のせいでもない |ジェファソン先生が言いそうなことだけど… それにケイトだって…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_011"] = "大人になりなよ。 意地悪で言ってるんじゃないの |クロエだけが問題を抱えてるわけじゃない… |ケイトは自殺したんだよ?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_012"] = "大人になりなよ |クロエだけが問題を抱えてるわけじゃない… |ケイトはもう少しで…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_013"] = "レイチェルにも責任があるって言うの?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_014"] = "じゃあ 誰のせいだっていうの?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_015"] = "クロエ… 謝るなら今のうちだよ。 じゃないと…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_020"] = "ウィリアムおじさん? 本気なの?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_021"] = "デイビッドのこと?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_022"] = "おじさんは クロエを見捨てたわけじゃないよ…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_025"] = "そんな…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_026"] = "分からないけど… |でも あの日 私は一緒にいた |あれは誰のせいでもない 事故だよ!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_028"] = "でも クロエはまだ生きてる。 私と一緒に。 余計なお世話かもしれないけど…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_029"] = "かもしれない… |でも この 1 週間でクロエの人生が私の人生を変えた |もうクソじゃない",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_032"] = "クロエ 私一人じゃ何もできない |クロエが必要なの。 レイチェルも待ってるよ…",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_034"] = "私だって…",
  ["Act_E3_6B_DinerPark_Bird01_Look01_Max_010"] = "なんなの… 悲しさ 忌まわしさ 美しさが一体になった驚くべき光景…",
  ["Act_E3_6B_DinerPark_Bird01_Photo_Max_010"] = "いやな予感…",
  ["Act_E3_6B_DinerPark_CHCloe_Look01_Max_010"] = "犬が夢中になるような骨が見つかるといいけど…",
  ["Act_E3_6B_DinerPark_CHCloe_Look02_Max_010"] = "良い感じの骨だね…",
  ["Act_E3_6B_DinerPark_CHCloe_Look03_Max_010"] = "大丈夫… あの力があるんだから",
  ["Act_E3_6B_DinerPark_CHFisherman_Look01_Max_010"] = "署名運動を見ると胸がいっぱいになって悲しくなる…",
  ["Act_E3_6B_DinerPark_CHHomeless_Look01_Max_010"] = "年配の女性が路上で暮らしているのを見るのは忍びないね…",
  ["Act_E3_6B_DinerPark_CHTrucker_Look01_Max_010"] = "トラック運転手になるのもいいかも… ずっと旅してるみたいで…",
  ["Act_E3_6B_DinerPark_Deadbirds_Look02_Max_020"] = "いったいどうなってるの?",
  ["Act_E3_6B_DinerPark_Deadbirds_Look03_Max_030"] = "なんか気味悪い…",
  ["Act_E3_6B_DinerPark_Deadbirds_Look04_Max_040"] = "竜巻 雪 日食… そして今度は動物が… おかしいよ!?",
  ["Act_E3_6B_DinerPark_FrankRV_Look01_Max_010"] = "気をつけて 番犬がいるよ…",
  ["Act_E3_6B_DinerPark_NewspaperKateAlive_Look01_Max_010"] = "すっごい恥ずかしい… 面倒くさいことになりそう…",
  ["Act_E3_6B_DinerPark_NewspaperKateDead_Look01_Max_010"] = "いつもどおりのアルカディア・ベイ…",
  ["Act_E3_6B_DinerPark_RVDoor_Interact01_Max_010"] = "ロックされてる",
  ["Act_E3_6B_DinerPark_RVWindow_Look01_Max_010"] = "デジャヴ。 ほこりの上にほこりが…",
  ["Act_E3_6B_DinerPark_Truck_Look01_Max_010"] = "大型トラックの写真シリーズっていうのもいいな…",
  ["Act_E3_6B_DinerPark_Truck_Look02_Max_010"] = "運転手を喜ばせたら撮影の許可がもらえた! |ニーダム 1977 年モデル これは素晴らしいよ…",
  ["Act_E3_6B_Diner_BeansPlate_Look01_Max_010"] = "のんきに豆なんか食べてる",
  ["Act_E3_6B_Diner_BeerPrint_Look01_Max_010"] = "飲んでもいいし フランクにかけてもいいね。 でもビールはマズいから…",
  ["Act_E3_6B_Diner_Blocker01_Max_010"] = "あんなこと言わなきゃよかった。 巻き戻さないと…",
  ["Act_E3_6B_Diner_Blocker01_Max_020"] = "本気で怒らせちゃった。 巻き戻さないと…",
  ["Act_E3_6B_Diner_CHCop_Look01_Max_010"] = "どうぞ 気になさらないで… 売人のカギを盗みにきただけなので…",
  ["Act_E3_6B_Diner_CHFrank_Look01_Max_010"] = "頭をフルに使うんだ。 どうやったらフランクのカギを奪える?",
  ["Act_E3_6B_Diner_CHFrank_Look02_Max_010"] = "カギがないことに気づいたら すごく怒るだろうな",
  ["Act_E3_6B_Diner_CHNathan_Look01_Max_010"] = "ネイサンとフランク? 悪い予感しかしない…",
  ["Act_E3_6B_Diner_CHNathan_Look02_Max_010"] = "停学になったネイサンと 売人のフランクが同じ場所に…",
  ["Act_E3_6B_Diner_CHRudeDude_Look01_Max_010"] = "朝から飲んだくれてたら ろくな一日にならなさそう…",
  ["Act_E3_6B_Diner_CopKeys_Max_010"] = "カギは手に入れた。 戻ろう…",
  ["Act_E3_6B_Diner_Counterfood_Look01_Max_010"] = "おいしそう… でもまずカギの件が先決…",
  ["Act_E3_6B_Diner_FishermanPetitionStand_Look01_Max_010"] = "ビラがたくさんある… 誰も読まないのが悲しいね…",
  ["Act_E3_6B_Diner_FishingWallOfFame01_Look01_Max_010"] = "「漁師たちの栄光の壁」だ…",
  ["Act_E3_6B_Diner_FrankLeave_Max_010"] = "ご協力どうも フランク",
  ["Act_E3_6B_Diner_Graffiti01_Look01_Max_010"] = "私たち全員が…",
  ["Act_E3_6B_Diner_Graffiti01_Look02_Max_010"] = "あんたが飛び降りればよかったよ…",
  ["Act_E3_6B_Diner_Graffiti02_Look01_Max_010"] = "何これ… なんの予言?",
  ["Act_E3_6B_Diner_Jukebox_Look01_Max_010"] = "今は曲をかけてる場合じゃない! カギ!",
  ["Act_E3_6B_Diner_Keys_Interact01_Max_010"] = "悪いけどフランク 秘密を教えてもらうよ…",
  ["Act_E3_6B_Diner_Keys_Look01_Max_010"] = "魔法のカギ発見! これで車に入れる",
  ["Act_E3_6B_Diner_MaxSearch_Max_080"] = "作戦失敗 |あそこにいる警察官か… ネイサンにでも話しかけて |しつこく質問すれば有用な情報を聞きだせるかも……",
  ["Act_E3_6B_Diner_MaxSearch_Max_100"] = "「他の人に聞き込みしたまえ コールフィールド警部」",
  ["Act_E3_6B_Diner_NathanDickhead_Max_010"] = "どこまでもイヤなヤツ",
  ["Act_E3_6B_Diner_PostCardRack_Look01_Max_010"] = "ポストカードからは この町の本当の姿は見えてこないね…",
  ["Act_E3_6B_Diner_Poster01_Look01_Max_010"] = "銃を持った生徒がいることについては言及なし",
  ["Act_E3_6B_Diner_Poster04_Look01_Max_010"] = "ウォーレンとドライブインに行くのは楽しいだろうな… 息抜きが必要かも…",
  ["Act_E3_6B_Diner_Poster04_Look02_Max_010"] = "楽しそう… でも今はそういう気分じゃないんだ… ごめん ウォーレン…",
  ["Act_E3_6B_Diner_Scripted_Max_010"] = "どうやったらサクッとカギをゲットできるかな…",
  ["Act_E3_6B_Diner_Scripted_Max_020"] = "カギ ゲット! さあクロエのところに…",
  ["Act_E3_6B_Diner_Scripted_Max_030"] = "フランクとレイチェルを結ぶ手がかりがあるはず…",
  ["Act_E3_6B_Diner_Scripted_Max_040"] = "急がないとフランクが戻ってくる…",
  ["Act_E3_6B_Diner_Scripted_Max_060"] = "ベーコン… またお腹が空いてきた… |でも 先にフランクからカギを手に入れないと…",
  ["Act_E3_6B_Diner_Scripted_Max_070"] = "ゴミ屋敷化してるよ… 汚いなあ…",
  ["Act_E3_6B_Diner_Scripted_Max_080"] = "そんな… ケガしたりしてないといいんだけど…",
  ["Act_E3_6B_Diner_Scripted_Max_090"] = "今はエサに夢中だけど そのうち戻ってくるかも…",
  ["Act_E3_6B_FrankRV_BaseballBat_Look01_Max_010"] = "アルカディア・ベイ・ブルワーズに入団したいワケじゃないよね…",
  ["Act_E3_6B_FrankRV_BeerEmptyBottle_Look01_Max_010"] = "フランクとクロエが一緒に飲んでる姿は想像できない…",
  ["Act_E3_6B_FrankRV_BrokenKnife_Look01_Max_010"] = "ヤバッ! ナイフが壊れた!",
  ["Act_E3_6B_FrankRV_CHChloe2_Look01_Max_010"] = "クロエは怖がるどころか楽しんでる…",
  ["Act_E3_6B_FrankRV_DirtyPlates_Look01_Max_010"] = "絵に描いたような汚い台所…",
  ["Act_E3_6B_FrankRV_DogFood_Look01_Max_010"] = "これより骨のほうが好きみたいだね…",
  ["Act_E3_6B_FrankRV_DogFood_Look02_Max_010"] = "この犬のことがずっと心に引っかかりそう…",
  ["Act_E3_6B_FrankRV_DogPhoto_Look01_Max_010"] = "犬と一緒の写真はなんか微笑ましいかも…",
  ["Act_E3_6B_FrankRV_DogPhoto_Look02_Max_010"] = "もしフランクが知ったら 真っ先に復讐されるだろうな…",
  ["Act_E3_6B_FrankRV_DogPlate_Look01_Max_010"] = "「ポンピドゥー」… っていうの? プードルならともかく…",
  ["Act_E3_6B_FrankRV_DogPlate_Look02_Max_010"] = "ごめんね「ポンピドゥー」。 そんな名前だったんだ…",
  ["Act_E3_6B_FrankRV_DrugRelatedItem_Look01_Max_010"] = "ライターにしては大げさ…",
  ["Act_E3_6B_FrankRV_EmptyCupboard1_Look01_Max_010"] = "なんにもなし…",
  ["Act_E3_6B_FrankRV_EmptyCupboard2_Look01_Max_010"] = "秘密はなし…",
  ["Act_E3_6B_FrankRV_EmptyDrawer1_Look01_Max_010"] = "ない。なんにもないよ",
  ["Act_E3_6B_FrankRV_FrankGun_Interact01_Max_010"] = "後悔するかもしれないけど フランクにこれを使わせるわけにはいかない…",
  ["Act_E3_6B_FrankRV_FrankGun_Interact02_Max_010"] = "後悔するかもしれないけど クロエにこれを使わせるわけにはいかない…",
  ["Act_E3_6B_FrankRV_FrankGun_Look01_Max_010"] = "クロエの銃だ。 クロエに返したほうがいいかな?",
  ["Act_E3_6B_FrankRV_Hifi_Look01_Max_010"] = "いいね。 フランクにも大切にしているものがあるんだ…",
  ["Act_E3_6B_FrankRV_Knife_Interact01_Max_010"] = "これは使えそうだね",
  ["Act_E3_6B_FrankRV_Knife_Look01_Max_010"] = "ナントカに刃物は要注意だよ…",
  ["Act_E3_6B_FrankRV_Knife_Look02_Max_010"] = "ナントカに刃物は要注意だよ… 気をつけないと…",
  ["Act_E3_6B_FrankRV_Numbers_Look01_Max_010"] = "解読できそうにないな…",
  ["Act_E3_6B_FrankRV_Object10_Look01_Max_010"] = "そりゃおやつも食べるよね…",
  ["Act_E3_6B_FrankRV_Object1_Look01_Max_010"] = "すごい数のビニール袋… リサイクルしようよ",
  ["Act_E3_6B_FrankRV_Object2_Look01_Max_010"] = "人が生活する環境じゃないよね…",
  ["Act_E3_6B_FrankRV_Object4_Look01_Max_010"] = "ネズミ捕りを回避したい理由があるのかな…",
  ["Act_E3_6B_FrankRV_Object5_Look01_Max_010"] = "オンライン販売に進出?",
  ["Act_E3_6B_FrankRV_Object8_Look01_Max_010"] = "発見 フランクの宝物…",
  ["Act_E3_6B_FrankRV_Object9_Look01_Max_010"] = "これは自分用? 商売用? それとも両方?",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Interact01_Max_010"] = "クロエは怒るだろうけど… これを見せないと…",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look01_Max_010"] = "こんなレイチェル 知りたくなかったかも…",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look02_Max_010"] = "（ため息）レイチェルとフランクの犬…",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look03_Max_010"] = "本当にフランクと付き合ってたんだね",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look04_Max_010"] = "この車を運転させてもらったんだ… すごく幸せそう",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look05_Max_010"] = "うーん 喜ぶべきか悲しむべきか…",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look06_Max_010"] = "なんだか雲行きが…",
  ["Act_E3_6B_FrankRV_SteeringWheel_Look01_Max_010"] = "クロエとこの車で旅行できたら楽しいだろうな…",
  ["Act_E3_6B_FrankRV_VentShaft2_Interact01_Max_010"] = "残念 何もなし",
  ["Act_E3_6B_FrankRV_VentShaft2_Look01_Max_010"] = "何か道具があれば 開けられるのに…",
  ["Act_E3_6B_FrankRV_VentShaft_Interact01_Max_010"] = "さて 中身を拝見",
  ["Act_E3_6B_FrankRV_VentShaft_Look01_Max_010"] = "この通気口外れそう。 こじ開けるものさえあれば…",
  ["Cue_E3_6B_DinerPark_AlyssaWarn_Max_010"] = "アリッサ 危ない!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_GotHurt_Alyssa_002"] = "あとにして… これじゃ濡れネズミもいいとこだ…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_GotHurt_Max_001"] = "うわあ 大丈夫?",
  ["Cue_E3_6B_DinerPark_CHAlyssa_IGE_Alyssa_010"] = "ちょっと 冗談でしょ!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_IGE_Alyssa_020"] = "助かったよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase01_Alyssa_001"] = "ホントにありがとう。 また後でね!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase02_Alyssa_001"] = "とにかく 私もマックスのおかげで助かったよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase03_Alyssa_001"] = "あまり自分を責めないでね。 みんな マックスを誇りに思ってるよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_002"] = "ありがとう マックス |マックスがいたら 前も助けてもらえてたかな |いろいろあってさ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_003"] = "これで マックスに助けられたのも 2 回目! ありがとね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_004"] = "これで マックスにはもう 3 回も 助けてもらってるね。 私の守護霊様だ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_007"] = "ううん マックスはケイトの命を救ったじゃん |今やブラックウェルのヒーローだよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_008"] = "ううん マックスはケイトを助けようとしたじゃん |たった一人で… |他のみんなは写真撮ってたし",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_016"] = "ひどい話… でも マックスはいい友だちだよ |ケイトには味方がたくさんいるってことを知らせてあげたいよね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_017"] = "マックスが駆けつけたから 飛ばなかったんだよ |これからは学校のみんなも 優しくなるといいんだけど…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_018"] = "とにかく マックスがいてよかったよ。 大変だったろうけど…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_020"] = "何それ! そんなのありえないよ! 署名運動を始めなきゃ…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_021"] = "面会できるようになったら みんなでお見舞いに行こう |じゃあ また後で話そうね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_022"] = "そうだね 確かに。 そのとおりだ |また今度じっくり話そう またね マックス",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_023"] = "ケイトに写真を贈ってあげるのもいいかもね… じゃあ また今度 相談するから",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_028"] = "それは見てたみんなが分かってるよ。 マックスを誇りに思う |すごくカッコいいもん",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_029"] = "そんなこと言わないで |必死に助けようとしてたマックスを 学校中が見てた |たった一人で… ヒーローなのは変わらないよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_030"] = "ネットで叩かれ 学校には誰一人 味方がいなかったんだよ… 無理もないでしょ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_031"] = "何それ! そんなのありえないよ! 署名運動を始めなきゃ…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_035"] = "今度じっくり話そうよ。 もっと仲良くなりたいな… じゃあ また後で",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_036"] = "ケイトは死んだの。 過去に戻って助けられるわけじゃないんだ |じゃあね マックス",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_037"] = "言うね。 でも いいと思うよ。 今度また話そう。 じゃあね マックス",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_001"] = "ふう 危機一髪だったね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_005"] = "次は絶対助けてあげる。 ごめんね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_006"] = "そんな… 別にたいしたことしてないよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_009"] = "助けられてよかった。 ケイトはいい子だし… 友だちだからね |あんな動画で死のうとするなんて…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_010"] = "ツイてただけだよ。 ケイトが本気だったら止められなかった…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_011"] = "確かに 私以外 誰もケイトを助けようとしなかったし |あまり考えないようにしてたけど",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_012"] = "ヒーローって言っても停学になったけどね… |デイビッド・マドセンとプレスコット家のせいで",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_013"] = "そうだね",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_014"] = "大変だったのはケイトの方だよ。 私はただ… できることをやっただけ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_015"] = "ううん もう済んだことだし。 それに これで心置きなく写真を撮れるよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_024"] = "ケイトは友だちだった。 助けるためなら なんでもしたよ…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_025"] = "頑張ったんだけどね… 助けられなかった",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_026"] = "ケイトは自ら立ち向かおうとしなかったんだ… |少しでも 私の話を聞いてくれてたら… |繊細すぎたんだよ",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_027"] = "ヒーローって言っても停学になったけどね… |デイビッド・マドセンとプレスコット家のせいで",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_032"] = "今はそう思えないけど… ありがとう",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_033"] = "でも ケイトだって…",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_034"] = "いいよ。 もうブラックウェルなんて どうでもいいし",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_002"] = "聞くなよ。 雪は降るわ 日食は起きるわ… 次は竜巻でも来るのか?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_007"] = "何かが変なのは確かだ |なんせさっき駐車場でプレスコットのガキが一人で何かわめいてたよ",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_008"] = "俺は科学者じゃねえ |確かに海温は上がったが… |もっと… 悪い何かが起きようとしている",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_009"] = "ヤツだけじゃない |もしお前さんがアルカディア・ベイの魚のことを知ってたら… |いや なんでもない |話はもう終わりだ",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_010"] = "もしお前さんがアルカディア・ベイの魚のことを知ってたら… |いや なんでもない |話はもう終わりだ",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_012"] = "まあ でも カリフォルニアみたいに地震がないだけマシか",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_013"] = "ああ… 今さら転職もできないしな。 それじゃあ また",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_015"] = "何だ 知ってるのか。 悪いも何も 魚がいないんだよ!",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_017"] = "食いがいのあるヤツらはな。 サケもマスもスズキも全滅だよ |ふざけた話だ。 最近はハマグリにまで被害が出ている…",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_019"] = "悪い この話はもう終わりだ。 それじゃあな",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_001"] = "今日は大漁でしたか?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_003"] = "これって異常気象か何かなんでしょうか?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_004"] = "まさか…",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_005"] = "近辺の魚にも よくないことが起きているらしいですね…",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_006"] = "あいつが変なのは いつものことです",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_011"] = "「もっと悪い何か」?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_014"] = "確かに… うーん 何だかめまいがしてきた。 今日は大漁だといいですね!",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_016"] = "ええ? いないって… 1 匹も?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_018"] = "そんな… でも それって…",
  ["Cue_E3_6B_DinerPark_CHFisherman_QuickPhase01_Fisherman02_001"] = "言っただろ 話はもう終わりだ",
  ["Cue_E3_6B_DinerPark_CHFisherman_QuickPhase02_Fisherman02_001"] = "話しかけないでくれ 魚のことを考えてるんだ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_002"] = "あら あんた…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_003"] = "ホームレスのばあさんに何の用だね? あんた名前は?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_005"] = "いや… ブラックウェルで女の子が自殺したそうじゃないか… かわいそうに",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_006"] = "いや… ブラックウェルで女の子の自殺未遂があったそうじゃないか…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_012"] = "辛いだろうね |でも それは彼女が選んだことだ |あんたが背負うことはないさ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_013"] = "あんたが? 酒があれば 祝杯をあげたのに",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_014"] = "レイチェルは この町のあらゆる出来事に関係しているよ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_015"] = "停学もいい機会さ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_016"] = "世界ってのは悲しいものさ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_021"] = "でも あんたはまだ若い。 ああ 私もあんたくらいの歳に戻れたらね…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_022"] = "力なんてものはね 幻想にすぎないよ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_023"] = "特に他の人たちのことはね…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_024"] = "ケイトって子は すべてを失ったと思っちまったんだろうね… |その気持ち 分かるよ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_027"] = "この前 話を聞いてくれたじゃないか… |それに 自分の心配をしたほうがよさそうだ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_029"] = "あんたは 自分の心配をしたほうがよさそうだ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_031"] = "あたしはきっとあんたより いろいろ知ってるよ |みんな あたしを見て見ぬふり でも あたしはちゃんと見てるのさ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_036"] = "あの甘やかされたガキ ついに親父が牛耳る学校で停学になったか…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_037"] = "あの甘やかされたガキは なんだかヤバい匂いがプンプンするね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_038"] = "今日見たよ。 落ち着かない様子だったが…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_039"] = "どこぞの誰かから銃を奪ったって豪語してるそうだけど",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_043"] = "昨日ヤツがうろつき回ってるのを見たよ。 何だかいつも以上にイライラしてたね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_044"] = "ヤツは神経質な男だけど 何か目的があるようには見えるね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_047"] = "何だか あんたはあたしよりも いろいろ知ってるみたいだね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_050"] = "何か隠しているような口ぶりだけど",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_053"] = "あたしなんかが どうこう言えるもんか。 それにあんたはマトモさ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_054"] = "話したくないなら話さなくてもいいよ。 あたしはただのホームレスだからね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_056"] = "ありえない話じゃないね。 近頃 町の空気がおかしい |知らせてくれて ありがとよ",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_057"] = "食べ物より情報だ… 隠し事を話す気になったらおいで",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_001"] = "あの こんにちは",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_004"] = "マックスです。 どうかしたんですか?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_007"] = "ケイト・マーシュです |彼女が屋上から飛び下りたとき… そばにいたんです |助けようとしたのに…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_008"] = "ケイト・マーシュです。 実は 私が彼女を説得して 自殺を止めたんです…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_009"] = "ええ… これも レイチェル・アンバーの失踪と関係している気がして…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_010"] = "悲しい出来事でした。 停学になったのなんかどうでもいいぐらい…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_011"] = "とても悲しい出来事でした",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_017"] = "私の責任です… 彼女を救う力があったのに…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_018"] = "はい… 私の力ですべてが変えられるわけじゃないんですね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_019"] = "どうも。 おかげで学校は停学になっちゃった…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_020"] = "どうも。 お酒 あればよかったですね",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_025"] = "それにしても ケイトの件はまだ謎ばかり…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_026"] = "私にできることがあればいいんですけど…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_030"] = "とにかく謎が多すぎて…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_032"] = "フランクはレイチェルを知ってた… 彼をこの辺で見ましたか?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_033"] = "ネイサン・プレスコットも?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_034"] = "私は ジョイスおばさん家のデイビッドが関係してるんじゃないかって…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_035"] = "じゃあ 言いますよ… |実はアルカディア・ベイが竜巻で崩壊する未来を見たんです… |本当に",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_040"] = "なんで警察はあいつを放っとくんだろう",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_041"] = "自殺した子に クスリを盛ったんです",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_042"] = "自殺未遂した子に クスリを盛ったんです",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_045"] = "私がクビに追い込んだからだ…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_046"] = "私や彼の家族を苦しめること?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_048"] = "私はただ… 町が心配なんです",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_051"] = "あなたなら信じてもいいかな… 私をおかしいとも思わないだろうし",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_052"] = "そんなことないです…",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_055"] = "今度また 食べ物でも届けに来ますね",
  ["Cue_E3_6B_DinerPark_CHHomeless_QuickPhase01_HomelessWoman_001"] = "嵐のこと 話してくれてありがとう。 あたしも 何か分かったら知らせるよ",
  ["Cue_E3_6B_DinerPark_CHHomeless_QuickPhase02_HomelessWoman_001"] = "あたしは独りになりたいんだ。 あっちへ行って。 頼むから…",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_001"] = "どうも ちょっといいですか?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_003"] = "仕事で何かあったんですか?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_004"] = "ずいぶん機嫌悪いんですね…",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_005"] = "そこに停まってる 77 年製のトラックってあなたのですか?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_008"] = "それは… 災難でしたね",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_009"] = "大変ですね",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_012"] = "ちょっと ケイト・マーシュはあばずれなんかじゃない |理由があってすごく落ち込んでたんです |彼女の何を知ってるって言うんですか?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_013"] = "出て行けばいいじゃないですか",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_016"] = "レイチェルを知ってるんですか? 彼女のことを教えて",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_019"] = "ブラックウェルで勉強してるんです |トラックの…歴史を |だから自分でも運転してみたくて",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_020"] = "友達のレイチェルがこのトレーラーのことを教えてくれたんです |私写真を撮るのが好きだから",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_023"] = "じゃあ あなたも彼女を知ってるんですね?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_002"] = "何だ 話すことなんてないぜ",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_006"] = "クソガキどもが線路をメチャメチャにしたせいで |俺は 3 日も荷物が着くのを待つ羽目になったんだ |時は金なりって言うのに",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_007"] = "仕事が干上がっても 支払いはなくならん。 時間を無駄にはできねえ",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_010"] = "こんな町なんか さっさとおさらばしたいってのに |町全体がメチャクチャだ |雪に 日食 あばずれは自殺するし…",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_011"] = "こんな町なんか さっさとおさらばしたいってのに |町全体がメチャクチャだ |雪に 日食 あばずれは自殺未遂するし…",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_014"] = "ブラックウェルなんて甘やかされたガキばかりだろ |あの行方不明の女… レイチェルもとんだ負け犬だ",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_015"] = "できるならやってる |そういや前にレイチェルとかいう女がロスまで乗せてけって言ってきたな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_017"] = "いやだね。 仕事もしたことのないガキの相手なんかしてられん |俺のトラックでも運転してみたらどうだ! 77 年製のじゃじゃ馬だ |分かったら とっとと失せな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_018"] = "ずいぶん詳しいんだな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_021"] = "あそこにもおつむのまともなガキがいたか |次にこの辺で仕事があったら乗せてやるよ |じゃあな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_022"] = "レイチェルを知ってるのか? |あの女はトラックの事なんざ興味なかった… |仕事にもな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_024"] = "ダイナーで会った |あの女 金目当てに男に近づいていやがった… |いなくなったらしいが… 清々したぜ |だがお前ならいつでも俺のトラックの写真を撮っていいぜ |じゃあな",
  ["Cue_E3_6B_DinerPark_CHTrucker_QuickPhase01_Trucker_001"] = "あの芸術学校は言葉を教えないのか? 話は終わりだ 失せな",
  ["Cue_E3_6B_DinerPark_CHTrucker_QuickPhase02_Trucker_001"] = "後で撮影会について話そうぜ。 いいな",
  ["Cue_E3_6B_DinerPark_CHTrucker_Trucker_010"] = "おい! 写真を撮るな!",
  ["Cue_E3_6B_DinerPark_FrankRV_Chloe_010"] = "こいつだったらどこにでも行けるな |海沿いをビッグサーの方まで行ったら最高だぜ!?",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_010"] = "なにこれ? ウエッ…",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_020"] = "ゴミばかりだな…",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_030"] = "食べ物くらいあってもいいだろ…",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_010"] = "ドアを確認しよう。 カギをかけ忘れてるかもしれない",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_030"] = "しつこいな",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_040"] = "バレたらおしまいだぞ…",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_050"] = "クソっ。 じゃ こうしよう |あたしがフランクに金を返すから付いてこいって言う |そしたらマックスが時間を巻き戻して あたしを見えないようにする |その後 マックスがフランクに車を確認するように言って カギを手に入れ… |巻き戻して… あれ?",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_070"] = "また偉そうに。 あたしは犬の気を引くための食い物でも探すか…",
  ["Cue_E3_6B_DinerPark_Insertion_Max_020"] = "本当にあいつとツルんでたの?",
  ["Cue_E3_6B_DinerPark_Insertion_Max_060"] = "クロエ 大丈夫。 私に任せて",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_010"] = "さすがだね まったく頼りになるよ",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_030"] = "これを使いな",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_040"] = "1… 2 の…",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_050"] = "…3!",
  ["Cue_E3_6B_DinerPark_OpenDoor_Max_020"] = "お礼ならフランクにどうぞ。 さて 始めようか",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Chloe_020"] = "やっぱ犬は犬だな… バカめ",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Max_010"] = "ほら ごちそうだよ!",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Max_030"] = "これで安心して入れる。 さっさと済ませよう…",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Chloe_020"] = "道路に落ちたな…",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Chloe_050"] = "きっと大丈夫… 大丈夫だって… 急ごう 時間がなくなる…",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Max_010"] = "ほら ごちそうだよ!",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Max_040"] = "ウソ… お願い 轢かれたりしないでよ…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_001"] = "マックス 大丈夫かい? |ケイトを止めようと頑張ったのに その… 残念だったな |それでも みんなが君を誇りに思ってるよ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_002"] = "おやおや スーパー・マックスのお出ましだ |みんなそう呼んでる。 あまり悪く思わないでくれよ |ケイトを助けたことを みんな誇りに思ってるんだ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_005"] = "君は今やブラックウェルの顔だよ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_006"] = "とんでもないことを言うな。 プレスコット家のウワサは知ってるだろう",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_007"] = "そんなところだ。 プレスコット家は大きな土地取引に乗り出してるらしい",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_008"] = "取引といえば… プレスコット氏は以前 俺の家族を助けてくれてな… |その代わりに取引をした… そして もう抜け出せそうにない |ああ もし人生をやり直すことができたら… って関係ないな |朝食に戻るよ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_012"] = "それもあるが… 今は新しい土地取引にご執心だ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_014"] = "普通の町なら こんなことになってないさ… 考えると イヤな気分になるが…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_016"] = "今だけだろう。 尊敬していないわけじゃないが 色々とやりすぎだよ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_019"] = "そうみたいだな。 前も銃を盗まれたとか騒いでいたが… |思い込みが激しいんだろう",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_021"] = "ひどい話だよ まったく…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_022"] = "彼女を助けた君もな。 他の生徒にも見習って欲しいね",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_024"] = "フランクはもう生徒じゃない |残念なことに この町の顔であることは否定できないが… あいつには近づくな |それからあいつの犬にもだ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_026"] = "ペットというより ボディーガードだな |血を欲しがるように 訓練したんじゃないか",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_028"] = "あいつはかつて闘犬に夢中でね |だが なんのつもりか ある日 急に犬たちを助けた |今飼ってるのは そのうちの 1 匹だ |だが 危険なヤツには変わりない。 近づくなよ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_030"] = "何だと そのことが噂になってるのか?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_032"] = "プレスコット家に困ったことがないか ときどき調べてるだけだ… |ネイサンのことも。 頼むから黙っててくれ",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_003"] = "ありがとうございます。 私より警察のみなさんの方が大変だと思いますけど…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_004"] = "ありがとうございます。 でも 私は運よく そこにいただけで |重要なのはケイトが助かったことです",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_009"] = "ブラックウェルの顔といえば ネイサン・プレスコットでは?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_010"] = "アルカディア・ベイの乗っ取り…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_011"] = "ネイサンの悪事 隠ぺいとか…?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_013"] = "アルカディア・ベイは変な町だと思います?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_015"] = "ブラックウェルの顔は デイビッド・マドセンじゃないですか",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_017"] = "私とクロエに対しても 色々とやりすぎなんです",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_018"] = "レイチェルを見つけようと必死みたいです…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_020"] = "しばらくは ケイトがブラックウェルの象徴になりそうですね",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_023"] = "ネイサンは レイチェルとフランクがブラックウェルを… 象徴してるって",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_025"] = "フランクは犬をすごくかわいがってますよね",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_027"] = "まさか。 フランクはどこから犬を手に入れたんですか?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_029"] = "あの あなたがプレスコット家のために働いてると聞いたんですが…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_031"] = "別に責めてるわけじゃないんです",
  ["Cue_E3_6B_Diner_CHCop_QPhase01_Cop_001"] = "また後で話そう",
  ["Cue_E3_6B_Diner_CHCop_QPhase02_Cop_001"] = "何の用だい?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_001"] = "おい どういうことだ… どうしてお前がレイチェルの服を着てる?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_006"] = "そいつは怖い。 あんな骨董品 どうせいらねえよ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_007"] = "お前と違ってその服が似合ってたからな |で 何だ? また俺を撃ちにきたのか?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_008"] = "お前と違ってその服が似合ってたからな。 で 何だ? こないだの仕返しか?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_010"] = "いやだね。 俺につきまとうんじゃねえ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_016"] = "お前 実は相当頭悪いだろ?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_019"] = "お前のお願いなんざ聞いてやる義理がないね。 クロエにも伝えておけ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_020"] = "残念だが 叶えてやることはできねえな",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_022"] = "知った風な口をききやがる",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_024"] = "ネイサンにはダチとして処方薬をやっただけだ |近頃のガキは悩みが多いらしいじゃねえか",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_026"] = "はっ! なるほどな。 ついでに大学院の学費もやろうか? |いいか… 何を勘違いしてんのか知らねえが |俺は自分と犬が食ってくために まっとうに働いてんだ |お前みたいに時間が有り余ってる 甘やかされたガキとは違うんだよ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_028"] = "「でも」じゃねえ |いいか これ以上 俺に何も聞くなよ。 この先 二度とだ |さっさと失せな",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_030"] = "あ… お前どうやって知ったんだ? ああ? クロエから聞いたのか?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_032"] = "そうか? まあ そうだろうと思ったよ |確かにあれはよく撮れてたからな |ちょっと待てよ 今出すから… ほら 見てみな",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_035"] = "フリなんかしちゃいねえ。 誰からそのことを聞いた?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_039"] = "俺程じゃねえだろ。 お前みたいなガキに犬を預けられるか",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_040"] = "お前には犬のクソだって触らせねえよ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_041"] = "それに 目的は犬じゃなくて このカギだろう |何だ その物欲しそうな目はよ |次はヨダレをたらしてみるか? |なんにしても カギはやらねえよ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_002"] = "なんでレイチェルの服だって分かるの?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_005"] = "デイビッド・マドセンがあの銃を探してるの。 あなたの車に来るかも",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_009"] = "あなたの車を調べさせて",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_015"] = "クロエの借金 チャラにできない?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_017"] = "もしお願いを聞いてくれたら…",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_018"] = "だって聞くのはタダでしょ…",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_021"] = "だいぶネイサンと仲がいいみたいだけど 特別な関係?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_023"] = "過去にちょっとね。 それに 高校生はウワサが好きなの",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_025"] = "フランク… えっと… 「高等教育」を受けられるとこ… 知らないかな",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_027"] = "でも…",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_029"] = "レイチェルがあなたにあげた写真を見たの",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_031"] = "レイチェルがその写真を一番気に入ってた… ってね",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_033"] = "怖そうなフリしてるけど… 犬をたくさん助けたんだよね?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_036"] = "すごくいい話だね。 動物が好きなんでしょ",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_037"] = "私 犬が好きなんだ。 犬の散歩も得意なんだよ… |車から連れてきてあげようか。 今から…",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_038"] = "犬をなでてもいい? 車の外に出してあげたいんだ",
  ["Cue_E3_6B_Diner_CHFrank_QPhase01_Frank_001"] = "さっさと行って 服を着替えるんだな",
  ["Cue_E3_6B_Diner_CHFrank_QPhase02_Frank_001"] = "今度は何だよ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_002"] = "警察官もいるダイナーなら いくらあなたでも騒ぎを起こさないでしょ |強がってもムダだよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_004"] = "すべてをもみ消してくれる 優しいパパがいてうらやましいね",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_006"] = "パパの言いなりなんでしょ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_007"] = "だったら教えてよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_010"] = "脅してもムダだよ。 私は取引をしにきたの",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_011"] = "助けになれるかもよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_019"] = "あなたがフランクから処方薬をもらっていることを 言うこともできたけどね",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_021"] = "私には分かるんだよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_023"] = "ねえ あなたとレイチェルは フランクから色々手に入れてたんでしょ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_025"] = "ウソでしょ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_026"] = "それ フランクから聞いたの?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_029"] = "聞いてネイサン |もし 私をフランクに仲介してくれたら これまでのことは水に流すよ |意味は… 分かるよね?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_031"] = "徹勉するのも楽じゃないの。 とにかく どうなの?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_033"] = "ケイトなら泣き寝入りすると思ってたんでしょ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_035"] = "彼女を襲ったの?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_036"] = "何か盛ったんでしょ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_039"] = "ちょっと 騒ぎを起こさないでよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_043"] = "聞いた話だと あなたとフランク 見張られてるんだって? |あなたのパパが雇った警察官に",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_045"] = "フランクは? フランクには守ってくれるパパなんていないでしょ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_047"] = "ホントに? じゃあ フランクは捕まっちゃうんじゃ…",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_049"] = "「血の誓い」をどう忘れろって言うのよ…",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_051"] = "それ以上 クロエのことを言ったら こっちこそタダじゃおかないよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_053"] = "フランクの「血の誓い」とレイチェルのこと 秘密にしてるの?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_055"] = "でも レイチェルはフランクと関係を持ってた",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_001"] = "ふざけやがって… その服どこで手に入れた? |お前レイチェルを知らないだろ… |何を企んでるんだ? さっさと言え!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_003"] = "なんだと? 校長にチクっといて よくそんな台詞が吐けるな",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_005"] = "知った風な口をきくな! お前に親父と俺の何が分かる!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_008"] = "てめえ… あまり調子にのるなよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_009"] = "何でだ? 気にかけてるふりか? 教えることなんてねえ |親父はただのクソ野郎だよ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_012"] = "うるせえよ! 俺に関わんじゃねえ! いいな? さっさと失せろ!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_020"] = "な… なんで知ってる?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_022"] = "強がってるのは お前の方だろ |校長室では余計なことを言わなくて正解だったな",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_024"] = "ふん レイチェルはだいぶハマってたみたいだけどな。 俺は違うね",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_027"] = "まるで分かっちゃいねえな |レイチェルがフランクとツルんでたのは そこにいる警官も知ってるぜ… |って お前余計なこと言うんじゃねえぞ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_028"] = "周知の事実だよ。 そこの警官も知ってるぜ。 もういいだろ とっとと消えな!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_030"] = "風邪薬が欲しいなら薬局に行きな",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_032"] = "落ち着けよ。 しょうがねえな |そんなに「勉強」したいなら フランクに 「高等教育」って合言葉を言いな |用意してくれるぜ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_034"] = "何 言ってんだ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_037"] = "お前ホントひでえ女だな |んなことあるわけねえだろうが… |俺は指一本触れちゃいねえ |よくも俺を怒らせたなこのクソ…",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_038"] = "マックス お前 本当にバカだな |何も分かってねえくせに 偉そうにしやがって |そんなに俺を敵に回したいのか? ああ?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_040"] = "こんなの騒ぎのうちに入らねえよ |何なら名誉毀損でお前を訴えてやろうか? |分かったら さっさと失せな!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_044"] = "バカ言え。 持ち物を雇う必要がどこにある? |それに 警官も俺のことをチクるほどバカじゃねえ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_046"] = "あいつがどうなろうと 俺は痛くもかゆくもねえ |レイチェルと血の誓いを結んだバカなんて… |クソ 余計な話をしちまった |今のことは忘れろ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_048"] = "いずれ捕まるさ |レイチェルと血の誓いを結ぶような ヤバいヤツだしな… |クソ 余計な話をしちまった |今のことは忘れろ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_050"] = "フランクにしゃべってみろ |お前だけじゃねえ あのクソ女 クロエもタダじゃおかねえからな",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_052"] = "とにかく もう行け。 しゃべったら殺すぞ",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_054"] = "血の誓い? な… 何のことだ |俺はそんなこと誰にもしゃべってない… |それに どうせみんな フランクはウソつきの負け犬だと思ってるだろ |あのレイチェルだってな…",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_056"] = "レイチェルはフランクの商品欲しさに 写真を撮らせただけだ |フランクは盛大に勘違いしてるみたいだけどな バカバカしい",
  ["Cue_E3_6B_Diner_CHNathan_QPhase01_Nathan_001"] = "お前バカかよ? さっさと失せな!",
  ["Cue_E3_6B_Diner_CHNathan_QPhase02_Nathan_001"] = "ったく しつけえな。 今度は何の用だ?",
  ["Cue_E3_6B_Diner_CHNathan_QPhaseMax_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E3_6B_Diner_CHNathan_QPhaseMax_Max_001",
  ["Cue_E3_6B_Diner_DinerTV_DrHedorah_020"] = "はい しかし まだ この異常気象と季節外れの気候の因果関係を断定することは |正直なところ分かっていないことの方が多いのです",
  ["Cue_E3_6B_Diner_DinerTV_DrHedorah_040"] = "これまでのサンプルデータもありますし そう願いたいですね",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_010"] = "… しかし それでは最近の異常気象は説明できませんね",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_030"] = "へドラ博士 最新の調査で詳しいことが分かるでしょうか?",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_060"] = "アルカディア・ベイの住民はこの異常な天気を目の当たりにし |何が起きているのかと首を傾げています",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_070"] = "昨日には日食 そして 2 日前には雪 |言うまでもなくこの季節には珍しいことです",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_080"] = "前代未聞と言ってもいいでしょう |最後にこの規模の雪が降ったのは 100 年以上も前ですから",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_090"] = "アルカディア・ベイに何が起こっているのか 多くの人が知りたいと思っています",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_100"] = "ぜひあなたの身近な体験や意見をお寄せください |これは 地球温暖化の影響でしょうか? |この異常気象の原因は何でしょうか?",
  ["Cue_E3_6B_Diner_MeetFrank_Frank_010"] = "俺を撃とうとしたくせにのこのこ来るとは… 度胸があるな お嬢ちゃん |だが クロエとつるんで銃をおもちゃにしようが |レイチェルの服を着ようが ガキはガキだ |一体何の用だ?",
  ["Cue_E3_6B_Diner_MeetFrank_Frank_030"] = "度胸があるな お嬢ちゃん |だが クロエとつるんで銃をおもちゃにしようが |レイチェルの服を着ようが ガキはガキだ |一体何の用だ? |俺の写真なんか撮ったらカメラをぶっ壊すぞ",
  ["Cue_E3_6B_Diner_MeetNathan_Max_020"] = "あの…",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_010"] = "レイチェル? んだよ… お前か",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_030"] = "はっ 「マックス・アンバー」か |服だけはイケてるじゃないか |デイビッドをクビにしといて まだ何かもめ事起こそうってのか?",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_040"] = "はっ 「マックス・アンバー」か |イメチェンか? ところで俺を停学にしてくれてありがとよ |ここが公共の場でよかったな",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_050"] = "はっ 「マックス・アンバー」か |停学になったとたん ずいぶんパンクな格好してんな? |俺をトラブルに巻き込みやがって",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_060"] = "はっ 「マックス・アンバー」か |停学になったとたん ずいぶんパンクな格好してんな? |デイビッドをクビにした気分はどうよ?",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_070"] = "はっ「マックス・アンバー」か |パンクにイメチェンか? |そういや昨日 お前がジェファソンに歯向かったのは かなりの見物だったな",
  ["Cue_E3_6B_Diner_SpillFood_Frank_020"] = "てめえ 食ってるのがわからねえのか。 一体なんのつもりだ こら!",
  ["Cue_E3_6B_Diner_SpillFood_Max_010"] = "豚みたいね。 床で食べたら?",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_020"] = "おい てめえ何やってんだ",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_030"] = "俺のカギを返しやがれ",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_040"] = "聞こえてんのか こら!",
  ["Cue_E3_6B_Diner_TakeKeys_Max_010"] = "悪いけど カギはもらってくからね",
  ["Cue_E3_6B_Diner_ThrowWater_Frank_020"] = "てめえ ぶっ殺してやる!",
  ["Cue_E3_6B_Diner_ThrowWater_Max_010"] = "こうしたら一体どうなるか見たかったの",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_010"] = "回線弱いな… これじゃエロ動画落とせないぞ…",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_030"] = "こいつ 犬を使って何やってんだ…?",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_050"] = "首輪と犬のマスクつけるなんて マジかよ…",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_070"] = "いつこんな写真撮ったのさ? フランク本気モードじゃん…",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_020"] = "オエッ",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_040"] = "やめなよ",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_060"] = "バカでしょ!",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_080"] = "はいはい 無視 無視",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_010"] = "レイチェルがフランクに こんな写真を撮らせてたなんて… |ラブレターも書いて… フランクとヤってたなんて! |そんなの一言も言わなかった! なんで?",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_030"] = "友だちなら言うだろ! |結局 みんなあたしを裏切るんだ… |パパは死ぬし マックスは何年もいなくなるし… |ママはクソオヤジと再婚… そしてレイチェルまで…",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_070"] = "うるさい そんなこと聞きたくない!",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_080"] = "うるさい! クソオヤジの肩を持ったくせに! 聞きたくないんだよ",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_020"] = "怒るって分かってたからだよ",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_040"] = "レイチェルは行方不明… 裏切られたわけじゃないよ",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_090"] = "クロエ!",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_020"] = "おっ 期待できそうだ",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_030"] = "やるじゃん マックス。 ありがと。 これで安心できる…",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_050"] = "ああ もちろん",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Max_010"] = "本当は渡したくないけど…",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Max_040"] = "すぐにデイビッドに返しなよ",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_010"] = "あたしの部屋がマシに思えるな",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_030"] = "フランクは別に… いや あのブレスレットを持ってるだけで 十分あやしいか",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_040"] = "こいつだったらどこにでも行けるな |海沿いをビッグサーの方まで行ったら最高だぜ!?",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_070"] = "分かってる。 ただの夢さ",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_080"] = "車内を探して。 あたしはパソコンを探ってみる",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_020"] = "フランクと比べないでよ",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_050"] = "ハイウェイをブッ飛ばしながら またキスでもするの? |ほら おしゃべりは後にして レイチェルの手がかりを探そう",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_060"] = "ハイウェイをブッ飛ばしながら またキスでもせがむの? |ほら おしゃべりは後にして レイチェルの手がかりを探そう",
  ["Act_E3_7A_CampusA_BeforeMeetingMark_Max_010"] = "あの調子じゃ付き合いきれないよ… 助けてあげたいのに…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_001"] = "マックス 少し話せるかい?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_004"] = "あれからどうしてたか 気になってね",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_007"] = "分かるよ。 ケイトのあんな姿を見てつらかっただろう |よければ カウンセラーを紹介しよう",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_008"] = "ケイトを助けた君のことを 皆 誇りに思っているよ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_011"] = "自撮りが好きな割に 謙虚なんだな |もっと自分を褒めなさい |ちょっと… 大丈夫か?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_012"] = "僕がケイトを泣かしたことか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_014"] = "まったく… 君の詮索好きにはまいったね",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_015"] = "マックス 君の立場だったら僕も同じ事をしたかもしれない |だが 僕はケイトを助けようとしただけだ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_016"] = "正直なところ 僕はコンテストに疲れ切ってたよ |それに サンフランシスコなんて僕以上に気取ったやつばっかだしね… |だが 君のことは応援してるよ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_020"] = "監視システム顔負けのお節介だな。 とにかく君には関係ない",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_021"] = "マックス 僕は「日常ヒーロー」じゃない |ケイトのことは助けたかったが 話を聞いてくれなかった",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_023"] = "やれやれ 困ったな。 そんなんじゃ せっかくの才能が台無しだぞ?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_024"] = "後悔と追憶は危険な組み合わせだ。 過去は変えられない |現実を受け入れ 進まなくては |僕から言えるのは以上だ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_025"] = "ネイサンがケイトにクスリを盛ったことか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_026"] = "ネイサンを停学にさせたことか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_029"] = "君は銃の所持に関しても報告していたね |少し 自分の身を心配したほうがいい。 怖がらせるつもりはないが…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_030"] = "ネイサンは口だけでそんな度胸はない。 考えすぎだよ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_032"] = "デイビッドがケイトを脅したことか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_033"] = "デイビッドが停職になったことか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_036"] = "君を責める人なんていないさ。 知っての通り 僕もあの男が嫌いだ |何も心配いらないよ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_037"] = "君は優しいな。 だがあの男に罪悪感なんて感じるだけ無駄だぞ |ひどい言い方だがあいつは最低の男だ |考えすぎだよ",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_043"] = "停学処分が解けたら フォトグラファーとしての君の未来について話そう |いいね?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_044"] = "いずれフォトグラファーとしての君の未来について話そう。 いいね?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_003"] = "あ はい ジェファソン先生",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_005"] = "ありがとうございます。 でも 私は何もしてません… そこにいただけで…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_006"] = "どうも… でも 正直なところ 何も手につきません…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_009"] = "いえ… 私 なんであんなこと言ったのか…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_010"] = "大丈夫です… ただ昨日の校長室で起きたことを考えると…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_013"] = "はい… 先生を「日常ヒーロー」コンテストから追い出すことになるなんて… |怒ってますか?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_017"] = "ありがとうございます。 でも 写真のキャリアだなんて |サンフランシスコと同じぐらい遠い世界に思えて… |自信がないんです",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_018"] = "それに 夕べ ビクトリアと話してましたよね?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_019"] = "でも ケイトは泣きながら走っていったじゃないですか…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_022"] = "分かってます 悪いくせですよね",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_031"] = "でも 万が一の場合… 怖くてしょうがないです",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_034"] = "はい… 自業自得だとは思いますけど…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_035"] = "当然の報いなのに… 罪悪感を感じるんです",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_038"] = "私の自撮りのことですか? あんなの笑われるだけですよ…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_039"] = "才能?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_040"] = "そうですね。 ただ プロの世界は遠すぎて…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_042"] = "私は過去ばかり見てしまって 先のことを考えるのが苦手なんです",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_045"] = "はい… ネイサンは絶対復讐しに来るはず…",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_046"] = "ケイトに何か盛ったことは確かなんです",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_010"] = "気にすんなよ。 あたしなんかのことはいい",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_020"] = "こればっかりはどうにもできないよ |5 年前に戻って父さんを助けでもしない限りね… |んじゃまた",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_030"] = "こればっかりはどうにもできないよ |5 年前に戻って父さんを助けでもしない限りね… |授業頑張りな",
  ["Cue_E3_7B_MaxRoom_Insertion_Max_010"] = "クロエ… 私の力がもっと強ければ… もっと遡って すべてを変えられるのに…",
  ["Cue_E3_7B_MaxRoom_Insertion_Max_020"] = "何 今の…? 何が起きてるの?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_010"] = "それはあたしが決めるの! 約束したでしょ!",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_020"] = "パンケーキのこと?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_030"] = "マックスも何か言って…",
  ["Cue_E3_7B_MaxRoom_PolaRewind_PolarewindVoices_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E3_7B_MaxRoom_PolaRewind_PolarewindVoices_010",
  ["Cue_E3_7B_MaxRoom_PolaRewind_William_010"] = "クレープ作りを手伝うか?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_William_020"] = "フランス語では「クレープ」だ",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_010"] = "とにかく… 落ち着いて…",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_020"] = "そんな…",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_040"] = "いえ… あの クロエは今どこに…",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_030"] = "マックスじゃないか! いつシアトルから帰ってきたんだい… |また こうやって君に会えるとは思わなかったよ",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_050"] = "クロエは… 君とずっと会いたがってたんだ。 待ってて",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_060"] = "クロエ! お客さんだよ!",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF1_010"] = "この学校 マイノリティが少ないよね",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF1_030"] = "この地方にしては ってことでしょ?",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF2_020"] = "そうかな。 いろんな人がいると思うけど",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF3_040"] = "あんた 結局あいつと付き合ってるんだって?",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF4_050"] = "ボルテックス・クラブのパーティ 超アツいらしいよ",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF6_090"] = "LA の友達は オレゴンは毎日雨で寒いって言ってたけど |そんなことないし この夏は一度も雨降らなかったよ |これって異常気象?",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF7_100"] = "地元の住民がわざとウソの情報流してんでしょ",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM1_010"] = "あの授業退屈なんだよな",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM2_020"] = "授業中 スマホ見てると怒られるぜ",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM3_030"] = "ライブのチケット 150 ドルとか ありえねー",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM3_130"] = "凸面鏡は別名「集光鏡」とも言って 光が集まる位置に像を結ぶ構造なんだ",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM4_040"] = "そのうち 50 パーはサービス料なんだって",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM7_090"] = "だから あんな笑い上戸だったのか",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_010"] = "何ぼーっとしてんの",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_030"] = "やっぱり ボルテックスに入れたの間違いだったな",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_050"] = "そんなこと言ってないし",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_020"] = "今 マクシーンって呼んだ?",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_035"] = "…ごめん。 もう行くね",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_040"] = "ウォーレン… ステラと付き合ってるの?",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_050"] = "ウォーレン… ステラ…",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_060"] = "ビクトリアは私の親友… ウォーレンは私から距離を取ってる…",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_070"] = "そんな… 何もかもメチャクチャだ! 他には何が変わったの…? クロエは?",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_020"] = "なんか様子が変だよ… 大丈夫?",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_040"] = "コートニーは誰も入れたくないんでしょ",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_060"] = "やだ… マックスがハイになってる…",
  ["Cue_E3_7D_CampusA_AnotherReality_Victoria_010"] = "ちょっと ちゃんと聞いてる マクシーン?",
  ["Cue_E3_7D_CampusA_AnotherReality_Victoria_030"] = "ごめん ごめん マックスって呼ぶ約束だよね。 そう怒らないで |お詫びのしるしに あとでアレ渡すからさ",
  ["Act_E3_8A_Kitchen_CHCloeKitchen_Look02_Max_010"] = "とても幸せで屈託のないクロエ… 私が変えない限り もう二度と…",
  ["Act_E3_8A_Kitchen_CHWilliamKitchen_Look01_Max_010"] = "自分の家族みたいに大好きだったおじさん… |今日死なせるわけにはいかない… 絶対に",
  ["Act_E3_8A_Kitchen_CHWilliamKitchen_Look02_Max_010"] = "おじさんが生きてるなんて変な感じ… |何もかも同じ… なのに 現実離れしてる…",
  ["Act_E3_8A_Kitchen_ChloeMagazine1_Look01_Max_010"] = "そういえばこんなの読んでたね… でも この日を境に…",
  ["Act_E3_8A_Kitchen_Note2_Look01_Max_010"] = "これ 忘れてた… 灯台…",
  ["Act_E3_8A_Kitchen_Polaroids_Look01_Max_010"] = "前にも見たのを覚えている…",
  ["Act_E3_8A_Kitchen_StashSink_Look01_Max_010"] = "カギを洗い物の中に隠せるかも…",
  ["Act_E3_8A_Kitchen_Table_Interact01_Max_010"] = "ダメだ カギはない…",
  ["Act_E3_8A_Kitchen_Table_Look01_Max_010"] = "こんなに散らかして! 一緒にいろんな絵を描いて楽しかった…",
  ["Act_E3_8A_Kitchen_WilliamCamera_Max_010"] = "クロエとおじさんの絆が見て取れる… それから愛も。 そんな写真だね",
  ["Act_E3_8A_LivingRoom_ChloeMagazine2_Look01_Max_010"] = "クロエは漫画好きだった… この髪!",
  ["Act_E3_8A_LivingRoom_FamilyPortrait_Look01_Max_010"] = "うちはこういう家族写真 撮ったことないな…",
  ["Act_E3_8A_LivingRoom_Graffiti_Interact01_Max_010"] = "ちょっと分かりやすすぎるかな…",
  ["Act_E3_8A_LivingRoom_Graffiti_Look01_Max_010"] = "未来までメッセージを残しておけるか 確かめられるね…",
  ["Act_E3_8A_LivingRoom_Note01_Max_010"] = "おばさんはおじさんを本当に愛している…",
  ["Act_E3_8A_LivingRoom_NotePadWithPhoneNumbers_Look01_Max_010"] = "「ツー・ホエールズ」の電話番号! これでおばさんに警告できる…",
  ["Act_E3_8A_LivingRoom_Object3_Look01_Max_010"] = "懐かしい。 夜一緒に映画を見たっけ…",
  ["Act_E3_8A_LivingRoom_Object4_Look01_Max_010"] = "結局 旅行は実現しなかった…",
  ["Act_E3_8A_LivingRoom_PhonePowerPlug_Interact01_Max_010"] = "よし 線を抜いた!",
  ["Act_E3_8A_LivingRoom_PhonePowerPlug_Look01_Max_010"] = "そうだ 電話線を抜けば おじさんは電話を取れないよね!",
  ["Act_E3_8A_LivingRoom_Phone_Look01_Max_010"] = "「ツー・ホエールズ・ダイナー」に電話しておばさんに警告できる… |電話番号さえあれば…",
  ["Act_E3_8A_LivingRoom_Phone_Look02_Max_010"] = "番号があるんだからおばさんに電話しよう… 早く",
  ["Act_E3_8A_LivingRoom_SnowDoe_Look01_Max_010"] = "素敵なスノードーム…",
  ["Act_E3_8A_LivingRoom_SnowDoe_Look02_Max_010"] = "あのスノードームはおじさんのだったんだ…",
  ["Act_E3_8A_LivingRoom_WilliamCap_Interact01_Max_010"] = "よし!",
  ["Act_E3_8A_LivingRoom_WilliamCap_Look01_Max_010"] = "帽子の下になんか置かないよね?",
  ["Act_E3_8A_LivingRoom_WilliamCoat_Interact01_Max_010"] = "ダメだ… カギ どこ?",
  ["Act_E3_8A_LivingRoom_WilliamCoat_Look01_Max_010"] = "早く! 上着の内側を探して!",
  ["Act_E3_8A_Polarewind_Scripted_Max_010"] = "どうなってるの!? おじさんがいる! |クロエはまだ子ども… そんなに前まで戻ったの?",
  ["Act_E3_8A_Polarewind_Scripted_Max_025"] = "18 歳の私が 13 歳の自分の中に…? えっ?",
  ["Act_E3_8A_Polarewind_Scripted_Max_030"] = "つまり ここで私が何かを変えたら 過去も未来も全部変わってしまうのかな?",
  ["Act_E3_8A_Polarewind_Scripted_Max_040"] = "やらないと 絶対… |クロエのためにおじさんを救おう… |そのためにここにいるんだ…",
  ["Act_E3_8A_Polarewind_Scripted_Max_070"] = "なんのためにここにいるか忘れないで! 考えて!",
  ["Act_E3_8A_Polarewind_Scripted_Max_090"] = "おじさんを車に乗せたら また…",
  ["Act_E3_8A_Polarewind_Scripted_Max_130"] = "ここから先はぼやけている。 まるで写真の縁から出られないみたい…",
  ["Act_E3_8A_Polarewind_Scripted_Max_160"] = "ブザーが聞こえないところにカギを隠さないと…",
  ["Act_E3_8A_Polarewind_Scripted_Max_180"] = "おじさんが生きていたころは幸せだったクロエの家…",
  ["Act_E3_8A_Polarewind_Scripted_Max_190"] = "こんな不思議な体験は初めて… 現実離れしているのに… 現実なんだ…",
  ["Act_E3_8A_Polarewind_Scripted_Max_210"] = "気をつけないと おじさんに見られちゃうよ!",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_020"] = "ママは適当だよ",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_040"] = "じゃあ 何個?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_060"] = "へー 本当にシェフのつもりなんだ",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_080"] = "知らないよ?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_010"] = "卵はいくつ使うんだ?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_030"] = "そうだね",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_050"] = "まさかシェフを疑ってるのか?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_070"] = "ママがいないときはね",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_020"] = "もっと粉を付けないとね!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_050"] = "マックスをどアップで!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_070"] = "やる気!? 変な顔!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_090"] = "「はい チーズ!」",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_030"] = "見えないって!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_060"] = "やめてよ クロエ!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_100"] = "自分の写真は嫌い!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_010"] = "2 人とも 写真撮るぞ!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_040"] = "オバケみたいだ!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_080"] = "ほら! 1 + 1 は?",
  ["Cue_E3_8A_Kitchen_MaxPhoto_Chloe_020"] = "スターにしてよ!",
  ["Cue_E3_8A_Kitchen_MaxPhoto_Max_010"] = "こんどは私が撮るよ… はいポーズ!",
  ["Cue_E3_8A_Kitchen_MaxPhoto_William_030"] = "若く見えるようにな!",
  ["Cue_E3_8A_Kitchen_WarnChloe_Max_010"] = "あのね 今日はおじさんを車に乗らせちゃダメ! |変に思うかもしれないけど 私を信じて! |恐ろしいことが起きるの |絶対に車を運転させちゃだめ!",
  ["Cue_E3_8A_Kitchen_WilliamFindingkeys_William_010"] = "発見! こんなところにいたのか",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Chloe_020"] = "ちょっと待って 何がなんだかさっぱり分かんないよ…",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Chloe_040"] = "じゃあ 自分で説得しなよ",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Max_030"] = "私は本気なの!",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_020"] = "パパね 最新のパソコンを買うんだ",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_050"] = "それはあたしが決めるの! 約束したでしょ!",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_060"] = "ねっ? マックス。 ちょっと 顔真っ青だけど大丈夫?",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_090"] = "そうね 家族アルバムに保存ということで",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_110"] = "ところで朝ごはんはどうするの?",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_130"] = "パンケーキのこと?",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_150"] = "ウィ。 じゃあ卵を割ります!",
  ["Cue_E3_8A_LivingRoom_Insertion_Max_070"] = "うん… ちょっと… 多分… 大丈夫…",
  ["Cue_E3_8A_LivingRoom_Insertion_William_030"] = "フラッシュは平気だったかい?",
  ["Cue_E3_8A_LivingRoom_Insertion_William_040"] = "アルバム行きだな",
  ["Cue_E3_8A_LivingRoom_Insertion_William_080"] = "よし じゃあクロエ 決めてくれ",
  ["Cue_E3_8A_LivingRoom_Insertion_William_100"] = "はいはい",
  ["Cue_E3_8A_LivingRoom_Insertion_William_120"] = "そうだな。 ママが帰るまで時間もあるし。 クレープ作り手伝う人?",
  ["Cue_E3_8A_LivingRoom_Insertion_William_140"] = "フランスではクレープって言うんだ |それにシェフには助手が必要だ |朝ごはんが食べたければね",
  ["Cue_E3_8A_LivingRoom_MaxPhonDiner_Max_010"] = "あ… もしもし… えっと… ジョイス・プライスはいますか?",
  ["Cue_E3_8A_LivingRoom_MaxPhonDiner_Max_020"] = "もう帰った? えっと 確かですか? |分かりました |すいません… はい… どうも",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_Max_010"] = "いえ… いません",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_William_020"] = "こらこら 何をやってる",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_William_030"] = "もしもし…",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_Chloe_020"] = "もう 1 ドル罰金!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_010"] = "クソッ カギはどこにいった?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_030"] = "破産させる気かい!?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_040"] = "いつか役立つと思ったよ… でも どうしてここに?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_050"] = "いつか役立つと思ったよ… でも どうしてこんなところに?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_060"] = "いつか役立つと思ったよ… でもなんでカギがここに?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Chloe_090"] = "今日のマックス 絶対おかしい。 大丈夫?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_040"] = "バスでも行けますよ。 ね? バス停はすぐそこだし!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_060"] = "そうそう! バスはいいですよ! 15 分おきに来るし |おじさんとおばさんと買い物袋を乗せる場所もいっぱいあるし |環境にもいいし…",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_100"] = "クロエ… やったよ! 大成功だよ!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_010"] = "確かにここに置いたのに… うーん…",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_020"] = "おーい… カギよ 応答せよ…",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_030"] = "まったく… もう 二度とあの店で買わないぞ…",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_050"] = "確かにね。 名案だ マックス!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_070"] = "もうそのつもりだよ |では バス停に行こう。 ジョイスに怒られなきゃいいが…",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_Max_050"] = "私はただ… その… おばさんも準備に時間かかるんじゃないかって… |もう少し… 待ってみたら… その… ごめんなさい… はい…",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_William_040"] = "マックス いたずらも程々にな。 カギをかしなさい",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_William_060"] = "お説教はまた今度だ",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeysMobilePhone_William_010"] = "ジョイス! え? 家電にもかけたのかい? |クロエたちと朝ごはんを作ってたとこさ |「ツー・ホエールズ」で雇って… えっ? |…ああ 買い物ね。 もちろん迎えにいく |モカにありつけるかもしれないしね |すぐ行くよ。 じゃあ…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_030"] = "バカみたい",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "えー!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_070"] = "マックスはずっといるの!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "汚い言葉 1 ドル罰金!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_010"] = "ジョイス! クロエたちと朝ごはんを作ってたとこさ |「ツー・ホエールズ」で雇って…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_015"] = "えっ? |…ああ 買い物ね もちろん迎えにいく モカにありつけるかもしれないしね |すぐ行くよ。 じゃあ…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_020"] = "さて セーブマートまで女王陛下を迎えにいくことになった |平民の食料をたくさん買い込んだみたいなのでね…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_040"] = "それがパパのいいところさ",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_045"] = "カギをしめといてくれよ。 仲良く遊んで 家を壊さないように…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_060"] = "言うこと聞かないと |ママ特製のサーモン・サプライズとチョコレートケーキはお預けだ |マックスはどうするんだい?",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_080"] = "そうだったな",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_090"] = "クソっ カギはどこにいった?",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_110"] = "罰金じゃなくて大学資金な… カギは…",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_140"] = "あと ワインの試飲会はダメだぞ…",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_Max_010"] = "おじさん もし車を使う予定があればなんですが… |すごく道が混んでるみたいで… 道路工事も多いって |だから運転はやめたほうがいいかと…",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_Max_030"] = "そうじゃなくて… 道路が本当に悪いというか… だ だから…",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_William_020"] = "ニュースで見たのかな? |よし 運転するときは細心の注意を払うよ。 約束しよう",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_William_040"] = "マックス 心配してくれてありがとう。 でも おじさんなら大丈夫さ!",
  ["Cue_E3_Previously_Bink_Voices_Max_010"] = "前回までのあらすじ",
  ["Cue_E3_Previously_Bink_Voices_Max_020"] = "前回のライフ イズ ストレンジでは…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_002"] = "同情はよしてよ。 そういうの間に合ってるし |パパはいまだに あたしに車を買ったこと 後悔してるんだ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_003"] = "まだ話したことなかったね |どっかのバカが急に割り込んできて 車が溝に突っ込んだの",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_005"] = "雪だの日食だの… この世の終わりかも",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_006"] = "パパはあたしのために車を買ってくれただけ |悪いのは 急に飛び出してきた相手だよ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_009"] = "全部… スローモーションに見えて… 背骨が折れるのが分かった… |体の感覚があったのはそれが最後 |病院で目が覚めたときはもう 動けなかった",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_010"] = "新聞で読んだだけで 会ったことはないよ |レイチェルっていうんだ。 知り合いなの?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_011"] = "新聞で読んだだけだから 名前は知らない。 家族は悲しんでるだろうね…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_018"] = "あたしは毎日暇だからね 科学オタクだし! |でも こんなの説明できっこないよ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_019"] = "そう思いたいけど… あたしは希望と縁がないんだ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_020"] = "悪気はないんだ。 ただ最近 町に不吉な雰囲気が漂っててさ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_022"] = "こうしてると 子どもの頃に戻った気分。 懐かしいな…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_025"] = "いいの あたしは またこうしてマックスに会えただけで幸せなんだから |ブラックウェルの子みたいに 姿を消してたら こうはいかなかったよ…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_001"] = "クロエはすごくがんばってるよ。 絶対つらいはずなのに…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_004"] = "事故のこと… 聞いてもいい?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_007"] = "クロエはおじさんのせいだなんて 思ってないでしょ?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_008"] = "そのときのこと 覚えてるの?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_012"] = "レイチェル・アンバーのこと? 彼女と最後に話したのはいつ?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_013"] = "誰のこと?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_014"] = "なんだか… 子どもの頃からは想像できない世の中になったね",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_015"] = "そうなのかな… 実は あんまり詳しいことは知らなくて…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_016"] = "そうだとしても… 私は 未来は変えられると信じたい",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_017"] = "そんなこと言わないで",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_021"] = "確かに色々あったからね… でも クロエと私が一緒なら… きっと大丈夫だよ",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_023"] = "クロエ… ごめんね… もっと早く会いに来るべきだった |私 ひどいよね。 親友なのに",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_024"] = "そんな… ごめん 何て言ったらいいか…",
  ["Cue_E4_1A_Beach_Extraction_Chloe_010"] = "マックス… 来てくれただけでうれしいよ。 ホントにありがとう",
  ["Cue_E4_1A_Beach_Extraction_Chloe_030"] = "ちょっと 鼻が冷えてきちゃった。 そろそろ うちに帰ろっか?",
  ["Cue_E4_1A_Beach_Extraction_Chloe_050"] = "ごめん そういう言葉使い 好きじゃないな",
  ["Cue_E4_1A_Beach_Extraction_Max_020"] = "違うの…",
  ["Cue_E4_1A_Beach_Extraction_Max_040"] = "\"クソ\"寒いもんね",
  ["Cue_E4_1A_Beach_Extraction_Max_060"] = "そっか…",
  ["Cue_E4_1A_Beach_Insertion_Chloe_010"] = "なんか ちょっと… 不思議な感じだね",
  ["Cue_E4_1A_Beach_Insertion_Chloe_030"] = "手紙くれて うれしかったよ |みんなハガキぐらいしかくれないから… |しかも羊皮紙の便せんってところが マックスらしいよね",
  ["Cue_E4_1A_Beach_Insertion_Chloe_050"] = "手紙のほうが気楽だしね |あ ごめん 今の… 嫌みじゃないよ |こういうのが気まずいから来づらかったんだよね…",
  ["Cue_E4_1A_Beach_Insertion_Chloe_070"] = "腫れ物に触るみたいなのはやめて。 普通に くだらない会話がしたいの",
  ["Cue_E4_1A_Beach_Insertion_Chloe_080"] = "ちょっと待って",
  ["Cue_E4_1A_Beach_Insertion_Chloe_085"] = "ほら見て 夕日がすごくきれい。 何\"アワー\"だっけ…?",
  ["Cue_E4_1A_Beach_Insertion_Chloe_100"] = "マックスのおかげで 1 つ賢くなった。 きれいな写真が撮れるんだろうね… |でも クジラたち かわいそうだ |あたしにちょっと似てるかも… まあ あたしは生きてるぶん ましだね",
  ["Cue_E4_1A_Beach_Insertion_Max_020"] = "うん… でも楽しいよ",
  ["Cue_E4_1A_Beach_Insertion_Max_040"] = "気取りすぎかなって思ったけど… イギリスの詩人みたいでいいでしょ? |クロエには特別だよ",
  ["Cue_E4_1A_Beach_Insertion_Max_060"] = "まあ… ぶっちゃけ… そうかも",
  ["Cue_E4_1A_Beach_Insertion_Max_090"] = "「マジックアワー」",
  ["Act_E4_2A_Bathroom_Drawer02_Max_010"] = "なんにもない",
  ["Act_E4_2A_Bathroom_E4Mirror_Max_010"] = "マックス 元気? 変だな 前より老けたみたい…",
  ["Act_E4_2A_Bathroom_MedecineCabinet01_Max_010"] = "あった|クロエにモルヒネを持って行くことになるなんて",
  ["Act_E4_2A_Bathroom_Scripted04_Max_010"] = "暗視能力はないって",
  ["Act_E4_2A_Bathroom_Scripted04_Max_020"] = "バスルームは変わってない。 薬がずっと増えてるけど",
  ["Act_E4_2A_Bathroom_TeaTreeOilBootle_Max_010"] = "ハーブの薬も使ってるんだ",
  ["Act_E4_2A_ChloeRoom_AuntLetter_Max_010"] = "プレスコット財団の援助は… 無理だろうね",
  ["Act_E4_2A_ChloeRoom_Box02_Max_010"] = "\"おもちゃ\" |中に何が入ってるか見てみたい",
  ["Act_E4_2A_ChloeRoom_Box03_Max_010"] = "\"靴\" |ブーツでドカドカ歩くのが好きだったっけ",
  ["Act_E4_2A_ChloeRoom_Closet_Max_010"] = "クソオヤジから隠れる必要はなさそうだね…",
  ["Act_E4_2A_ChloeRoom_Crutches_Max_010"] = "歩行器… クロエがまた歩けることを願って 買ったんだ…",
  ["Act_E4_2A_ChloeRoom_E4Poster_Max_010"] = "青い蝶… きっと偶然だよね…?",
  ["Act_E4_2A_ChloeRoom_E4Window_Max_010"] = "前と変わってないのは この景色だけみたい",
  ["Act_E4_2A_ChloeRoom_MesuringMarks_Max_010"] = "この頃はいつも一緒だったのに",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_010"] = "クロエが痛み止めを待ってる",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_020"] = "前の部屋は散らかってても 元気があったな… 今は全然違う",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_030"] = "昔のクロエの人生は みんな箱の中… 時が止まってる",
  ["Act_E4_2A_ChloeRoom_UncleLetter_Max_010"] = "おじさんの兄弟のことは よく知らないな",
  ["Act_E4_2A_ChloeRoom_Zen_Max_010"] = "まだ この現実にとまどってる…",
  ["Act_E4_2A_ChloeRoom_Zen_Max_020"] = "みんなに苦しい思いをさせてる… 私のせいだ",
  ["Act_E4_2A_ChloeRoom_Zen_Max_030"] = "おじさんのこと クロエに決めてもらうことも出来たけど… そんなの残酷すぎる",
  ["Act_E4_2A_ChloeRoom_Zen_Max_040"] = "でも また三人一緒になれたんだよね… 私にはこれを壊す権利なんてないよ",
  ["Act_E4_2A_Corridor_scripted_Max_010"] = "バスルームで薬を探さなきゃ",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_010"] = "前と同じようでも 全然違う…",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_030"] = "過去を変えたって すべてが良くなるわけじゃないんだ…",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_040"] = "クロエと私には この世界での別の過去があるんだ… でも私にその記憶はない…",
  ["Act_E4_2A_ParentsRoom_ArcadiaBayPoster_Max_010"] = "謎だらけの町… アルカディア・ベイ",
  ["Act_E4_2A_ParentsRoom_Ashtray_Max_010"] = "昔はタバコ吸う人が大嫌いだったのに",
  ["Act_E4_2A_ParentsRoom_CHJoyce_Max_010"] = "おばさんはツラそうだ。 誰にも責められないよ",
  ["Act_E4_2A_ParentsRoom_ChloeDoor_Max_010"] = "もう侵入禁止の警告も貼ってない",
  ["Act_E4_2A_ParentsRoom_ChloePicture_Max_010"] = "このクロエ すごくかわいい。 誰が撮ったんだろう",
  ["Act_E4_2A_ParentsRoom_DoctorLetter_Max_010"] = "そんな… クロエの状態がこんなに悪かったなんて…",
  ["Act_E4_2A_ParentsRoom_E4Drawer01_Max_010"] = "おじさん頑張ってるな。 昔と変わらない",
  ["Act_E4_2A_ParentsRoom_E4Drawer02_Max_010"] = "もう十分 スーパーママだよ",
  ["Act_E4_2A_ParentsRoom_JoyceWilliamPicture_Max_010"] = "幸せそう… |こんな未来 想像してなかったよね",
  ["Act_E4_2A_ParentsRoom_Scripted05_Max_010"] = "おじさんとおばさんの部屋まで雰囲気が違う",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_001"] = "おはよう。 子どもの頃は お泊まりすると大騒ぎだったのにね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_003"] = "いつでも歓迎よ |マックスが遊びに来てくれるなんて あの事故以来初めてのことね…",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_005"] = "どうぞ ごゆっくり",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_011"] = "そんな心配しなくても大丈夫よ。 今こうして 会いに来てくれたんだから",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_014"] = "実はね クロエの病状は あまりよくないんだ |呼吸器系がかなり弱っていてね… |もう… ごめんなさいね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_015"] = "そんなことないよ。 クロエにはうんざりされちゃってるし |だからマックスが遊びにきてくれてよかった",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_016"] = "看護師の人たちが交代で見てくれてるわ |クロエは相変わらずトラブルメーカーで。 困ったもんだよ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_017"] = "どんなときも 家族 3 人で過ごす一瞬一瞬が宝物よ |家族って そういうものでしょ? 何があったって 一緒に乗り越えていくわ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_019"] = "あの人は本当によくやってくれてる。 クロエも私も… 幸せ者ね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_022"] = "あの人は全然変わりないわ。 本当に感謝してる |あの人なしじゃ生きていけないぐらい 心から愛してるの |やだわ 恥ずかしい…",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_023"] = "最近特に仲がよくてね。 クロエもウィリアムの言うことならちゃんと聞くし |2 人で結託して私に対抗してくるのは 勘弁してもらいたいけど",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_025"] = "どうなのかしらねえ… でも ありがとね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_026"] = "なんとかやってるわ。 そりゃあ 楽な暮らしだとは言わないけれど |この町では それはみんな同じことよ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_027"] = "私もよ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_029"] = "ウィリアムも私も 毎日朝から晩まで働きづめ |言うのもイヤだけど パン・エステートでパート勤めもしてるんだ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_031"] = "ショーン・プレスコットは アルカディア・ベイを丸ごと買い占めるつもりなのさ |あんたも 息子のネイサンには気をつけなさい",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_034"] = "さあ? この町が「もうそっとしておいてくれ」って 怒ってるんじゃないかね? |正直 私は家のことだけで精一杯だよ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_035"] = "ずいぶん唐突だね。 店にときどき来る バスの運転士さんのこと? |物静かでハンサムな人だけど… どうして?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_038"] = "好奇心旺盛なところは 子どもの頃から変わってないね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_039"] = "ただ… 鳥が死んだりクジラが打ち上がったりしてるのは気になるね |クロエのためにも 少しは気にしたほうがいいのかもしれない",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_002"] = "懐かしいな… またこの家に泊まれてうれしい",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_004"] = "おばさん。 また来ちゃった",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_007"] = "もっと早く会いにくるべきだった… クロエにさみしい思いをさせちゃったな…",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_008"] = "おじさんも元気そうでよかった… 相変わらずおばさんと仲がいいね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_009"] = "おばさん… 元気だった?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_010"] = "そろそろクロエのとこに戻らなきゃ。 おしゃべりできて楽しかった",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_012"] = "そうかな… おばさんたちに比べたら 私なんか何もできてない…",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_013"] = "おばさんたちが仕事のとき クロエはどうしてるの?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_018"] = "そんな… おばさんたち こんなにがんばってるのに…",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_020"] = "おじさんは 変わりない? その… いろいろあって 大変だったでしょ?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_021"] = "クロエとおじさんも 相変わらずいいコンビだね",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_024"] = "おばさんはステキだよ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_028"] = "でも… 仕事とか 大変でしょう?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_030"] = "プレスコット家とも知り合いなの?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_032"] = "デイビッド・マドセンって人 知ってる? |ダイナーのお客さんにそういう人いないかな?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_033"] = "おばさん… ここ最近起きてる異常な現象の原因は なんだと思う?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_036"] = "あ 別に… ちょっと… 聞いてみただけ",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_037"] = "うん そうだよね…",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_010"] = "マックス 遊びに来てくれてありがとね",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_020"] = "クロエもとても喜んでるわ",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_030"] = "マックスもすっかり大人っぽくなっちゃって… 見違えたわ",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_040"] = "ごめんね… 昔みたいに部屋が片付いてなくて",
  ["Act_E4_2B_Garage_Bathroom_Look01_Max_010"] = "ああ 新しいバスルームを作ったんだ。 いいご両親だな…",
  ["Act_E4_2B_Garage_Bracelet_Look01_Max_010"] = "向こうのクロエの片りん",
  ["Act_E4_2B_Garage_CHChloe_Look04_Max_040"] = "やめよう 薬を持って行ってあげなきゃ",
  ["Act_E4_2B_Garage_ChloeCHair_Look01_Max_010"] = "クロエは私のせいで車イスに…",
  ["Act_E4_2B_Garage_ComputerSP01_Interact01_Max_010"] = "心は今もパンクだね。でもダイブはもうできない…",
  ["Act_E4_2B_Garage_ComputerSP02_Interact01_Max_010"] = "よかった ネットの友だちも出来たんだ",
  ["Act_E4_2B_Garage_Computer_Look01_Max_010"] = "わあ これでパソコン操作するんだ… 人を助けるハイテクってかっこいいな",
  ["Act_E4_2B_Garage_Drawer_Max_010"] = "ここは薬だけ…",
  ["Act_E4_2B_Garage_E4Drawer02_Look01_Max_010"] = "血流を良くするために これを塗るみたい",
  ["Act_E4_2B_Garage_E4Drawer04SP01_Interact01_Max_010"] = "ウソでしょ この CD 作ったの 12 の時だよ?",
  ["Act_E4_2B_Garage_E4Drawer05SP01_Interact01_Max_010"] = "最低。 クロエがお金を盗んでくれてよかった… って 別の世界の話だけど",
  ["Act_E4_2B_Garage_E4Drawer05SP01_Interact02_Max_020"] = "最低 |クロエにお金を盗んでもらえばよかった… って あっちの世界の話だけど",
  ["Act_E4_2B_Garage_E4Drawer05_Interact01_Max_010"] = "わあ クロエはオール A だったんだ。 どこの大学だって行けたのに",
  ["Act_E4_2B_Garage_E4Drawer06SP01_Interact01_Max_010"] = "少なくとも 幸せな家族が戻ったんだから…",
  ["Act_E4_2B_Garage_E4Drawer06SP02_Interact01_Max_010"] = "こっちのクロエも やっぱりスケボー好きなんだ",
  ["Act_E4_2B_Garage_HeatLamp_Look01_Max_010"] = "すごい形のヒーター…",
  ["Act_E4_2B_Garage_MakeUp_Look01_Max_010"] = "クロエにメイクしてあげたいな。上手じゃないけど きっと楽しい",
  ["Act_E4_2B_Garage_MedicalVentilator_Look01_Max_010"] = "ああ 息をするにも こんな機械が必要なんだ",
  ["Act_E4_2B_Garage_MouthJoystick_Look01_Max_010"] = "これすごいな… ネコの動画も見放題だね",
  ["Act_E4_2B_Garage_PatientLifter_Look01_Max_010"] = "体重が軽くても大変そう",
  ["Act_E4_2B_Garage_Perfusion_Look01_Max_010"] = "これ モルヒネ用の器具なんだ…|痛いのツラそう…",
  ["Act_E4_2B_Garage_PhotoAlbum_Look01_Max_010"] = "クロエ専用のアルバム",
  ["Act_E4_2B_Garage_PhotoChloeWilliam_Max_010"] = "この写真を撮っててよかった。 おじさんとの新しい思い出になったよね",
  ["Act_E4_2B_Garage_PinboardSP01_Interact01_Max_010"] = "私の両親もハガキを送ってる",
  ["Act_E4_2B_Garage_PinboardSP02_Interact01_Max_010"] = "これ誰だろう。 ありがちなハガキ",
  ["Act_E4_2B_Garage_PinboardSP03_Interact01_Max_010"] = "私 クロエの近くにいてあげなかった。 ホント いい友だち",
  ["Act_E4_2B_Garage_PinboardSP04_Interact01_Max_010"] = "旅行の写真は送ったんだ。 クロエも さぞ嬉しかったろうね",
  ["Act_E4_2B_Garage_Pinboard_Look01_Max_010"] = "事故の後は手紙の数も少なそう… |私もほとんど書いてない。 ひどいな",
  ["Act_E4_2B_Garage_Scripted_Max_010"] = "クロエ 本当にツラそう… 痛み止めを探さなきゃ",
  ["Act_E4_2B_Garage_Scripted_Max_020"] = "モルヒネは 2 階だって言ってたよね",
  ["Act_E4_2B_Garage_Scripted_Max_040"] = "カオス理論か… 私が全部をメチャクチャにしてる",
  ["Act_E4_2B_Garage_Scripted_Max_050"] = "この世界は何もかもウソみたい",
  ["Act_E4_2B_Garage_Scripted_Max_060"] = "私がこれを望んだんでしょ? 満足した?",
  ["Act_E4_2B_Garage_Scripted_Max_080"] = "クロエがこうなっても おじさんを救うことに意味があるの…? その逆なら?",
  ["Act_E4_2B_Garage_Scripted_Max_110"] = "クロエには自分の部屋がすべて… |「当たり前」のありがたさは無くして初めて分かる",
  ["Act_E4_2B_Garage_SnowDoe_Look01_Max_010"] = "ああ シカのスノードーム… これは変わってない",
  ["Act_E4_2B_Garage_SnowGlobes_Look01_Max_010"] = "スノードームでいっぱいだ…",
  ["Act_E4_2B_Garage_ToyBear_Look01_Max_010"] = "「やあ クロエ」。 今はぬいぐるみも好きなんだ",
  ["Act_E4_2B_Garage_Window_Look01_Max_010"] = "庭を見て 子どもの頃を思い出したりするの? |もう芝生の感触もわからないなんて…",
  ["Act_E4_2B_Garden_DeadBirds_Look01_Max_010"] = "鳥が死んでる… ここでも… 同じことが…?",
  ["Act_E4_2B_Garden_Drawing_Look01_Max_010"] = "部屋から見えるように 絵の位置を変えたんだ… クロエ…",
  ["Act_E4_2B_Garden_Grave_Look01_Max_010"] = "ボンゴ ごめんね。 この世界に変わる前に あなたはもう…",
  ["Act_E4_2B_Garden_House_Look01_Max_010"] = "素敵なおうち。 おじさん 壁を全部塗り終えたんだね",
  ["Act_E4_2B_Garden_Swing_Look01_Max_010"] = "ああ ブランコがない… 取り外された時 クロエ悲しかったろうな…",
  ["Act_E4_2B_Garden_Window_Look01_Max_010"] = "景色が見える部屋でよかったね",
  ["Act_E4_2B_LivingRoom_Bills_Look01_Max_010"] = "そんな… 基本だけでこんなに…",
  ["Act_E4_2B_LivingRoom_CHWilliam_Look01_Max_010"] = "おじさん まさか人造人間じゃないよね…",
  ["Act_E4_2B_LivingRoom_CookieJar_Look01_Max_010"] = "前は貯金箱だったけど… そんな余裕ないか",
  ["Act_E4_2B_LivingRoom_EiffelTower_Look01_Max_010"] = "よかった ついにパリに行けたんだね",
  ["Act_E4_2B_LivingRoom_FoodCoupons_Look01_Max_010"] = "おばさんのクーポンがいっぱい",
  ["Act_E4_2B_LivingRoom_Graffiti_Look01_Max_010"] = "あ この落書き 変わってない",
  ["Act_E4_2B_LivingRoom_Keys_Look01_Max_010"] = "車のカギひとつで運命が変わるなんて…",
  ["Act_E4_2B_LivingRoom_Mail_Look01_Max_010"] = "借金がこんなに… 娘の世話をしてるだけなのに。 ひどい",
  ["Act_E4_2B_LivingRoom_Mortgage_Look01_Max_010"] = "医療費のために 家までなくすかもしれない… そんなのないよ",
  ["Act_E4_2B_LivingRoom_Newspaper_Look01_Max_010"] = "クジラは竜巻の前触れ… それに プレスコット財団? やだな…",
  ["Act_E4_2B_LivingRoom_Newspaper_Look02_Max_020"] = "レイチェルはここでも失踪中… 全部は変えられないんだ",
  ["Act_E4_2B_LivingRoom_OldTV_Look01_Max_010"] = "クロエに大きな HD テレビをあげて 自分たちはこんな古いのを使ってる…",
  ["Act_E4_2B_LivingRoom_SaleFlyer_Look01_Max_010"] = "ガレージセールなんて前は絶対やらなかった…",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_001"] = "マックスは あたしがこんなでも 一緒にいて 気まずくない?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_002"] = "もう住む世界が違うじゃない? 気軽に出かけることもできないし… |痛みがひどいと 1 日中麻酔でボーッとしてるし",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_003"] = "マックスは人生を楽しんでただけ |友だちが離れていくのはしかたない |ひどい話だけどさ。 って冗談だよ",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_009"] = "そうだな… イチャイチャできる相手とか! 赤くなって かーわいい! |マックスは 付き合ってる男子いないの?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_010"] = "でも あたしは恵まれてるよ。 パパとママに大事にされて… |今日はこうしてマックスにも会えた",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_012"] = "何言ってんの マックスはモテるよ。 いまに誰かから告られるね",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_013"] = "アーティストにとっては そういうのも大事なことだよ |いい恋愛をたくさんして 感性磨かなきゃ… 男でも女でもね",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_014"] = "残念。 ま 過去は忘れて 次に目を向けよう! なんか パパに似てきたな…",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_019"] = "もちろん。 パパ大好き。 あたしとママをすごく大事にしてくれる |親孝行できたらな…",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_020"] = "あたしはあんまりうれしくないんだけど! …パパには感謝してる |恩返しできてないけど",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_021"] = "迷惑かけてばっか。 でもそう言ってもらえると ちょっと気が楽かな",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_004"] = "正直言うと ちょっとね… |でも それはずっと会ってなかったから… 私のせいだよ",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_005"] = "まさか… そんな気つかわないでよ",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_006"] = "そんなのいるわけないよ |学校にかっこいい子はいるけど 私なんか… 相手にされないし",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_007"] = "うん… 他に何か欲しいものってある?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_008"] = "ウォーレンって子とちょっといい感じだったんだけど… |チャンス逃しちゃったみたい",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_011"] = "勉強が忙しくて それどころじゃないよ",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_015"] = "ウォーレンって子にデートに誘われたけど… |断っちゃって… 他の子に取られちゃった",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_016"] = "おじさんとは… その… 今も仲よくやってる?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_018"] = "それって いいことでしょ。 おじさんもうれしいんじゃないかな",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_022"] = "一緒にいることが 何よりの親孝行だよ",
  ["Cue_E4_2B_Garage_CHChloe_Quick01_Chloe_001"] = "今はちょっと休んでてもいいかな… ごめんね",
  ["Cue_E4_2B_Garage_CHChloe_Quick01_Chloe_002"] = "マックスごめん… ちょっと休むね",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_010"] = "映画 楽しかったな。 誰かさんは寝てたけど",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_020"] = "なんか久しぶりだから 不思議な感じがするね",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_030"] = "どう? このハイテクおもちゃ!",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_040"] = "2 階の部屋 どうなったのかな…",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_050"] = "頭が割れそう… 薬を早く…",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_060"] = "あそこにアルバムがあるから こっちへ持ってきて",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_070"] = "マックス… 友だちでいてくれてありがとう",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_015"] = "だって「お泊まり会」でしょ?",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_025"] = "うん でも クロエ変わってないよ",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_035"] = "すごいね! 自分で発明したの?",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_045"] = "きっと散らかってるよ",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_055"] = "分かった。 待ってて",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_065"] = "なんか恥ずかしいな…",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_075"] = "ううん こっちこそ ありがとう",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_010"] = "ページをめくってくれるかな? あたしはほら… \"忙しい\"から",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_020"] = "本当にいい写真だね… ねえ… もっと見たいな…",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_030"] = "マックス。 ページをめくって",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_010"] = "ありがと… やっと楽になれる",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_030"] = "心配しなくても大丈夫。 簡単だから… 痛くないし",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_050"] = "うん 大丈夫",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_060"] = "最近痛みが増してるんだけど… 今日は調子がいいほうだよ |こうして マックスと一緒に過ごせるだけで本当に幸せ… |あー ゴメン エモいし キモいよね |薬のせいかな",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_080"] = "さらにエモキモで悪いんだけどさ そこに アルバムがあるから取ってくれるかな |子どもの頃にマックスと一緒に撮った写真が見たいの",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_020"] = "でも… 失敗したら大変だよ…",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_040"] = "分かった。でも… 何かあったら すぐおじさんたちを呼んでね",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_070"] = "キモくないよ。 他に必要なものある?",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_090"] = "大丈夫 エモさなら私の日記に勝てないから |それに クロエと一緒に写真を見るなんて 断れるわけないじゃん",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_020"] = "バッチリ",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_025"] = "あたしたち こんなにちっちゃかったんだね。 お人形みたい",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_040"] = "パパにめちゃくちゃ怒られたよね。 「反省しなさい!」ってさ",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_060"] = "これ いい写真だね… 海賊ごっこしたときのだ!",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_080"] = "マックスならできるよ…",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_085"] = "懐かしい! パンケーキ作ったときだ。 この写真大好き |パパがこれを撮った日から まだたったの 5 年か…",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_100"] = "だったらいいのに",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_120"] = "あのね… |あたしは呼吸器系が弱ってて… その… か… 回復の見込みはないの |お医者さんが話してるのを聞いちゃったんだ |あたしは死を先延ばしにしてるだけなんだよね |パパもママもあたしも これ以上は苦しむだけ。 あたしはそんなのイヤだ",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_140"] = "あたしね… またマックスと一緒になれて もう思い残すことがないんだ… |町を二人で駆け回ってた 何でもできた |子どもの頃みたいな気分を もう一度味わいたかった |今日 その願いがかなったよ |だから これを… 最後の思い出にしたい… 分かる?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_010"] = "見える?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_030"] = "これは灯台に行った日だね",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_050"] = "なのにクロエ笑うんだもん。 うちなら勘当だよ",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_070"] = "結局 町を乗っ取ることはできなかったね",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_090"] = "私には 昨日のことのよう…",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_110"] = "うん…",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_130"] = "え…? 何が言いたいの?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_150"] = "うん… でも…",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_010"] = "点滴の目盛りを… 11 に上げるだけでいいの",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_030"] = "このまま… 眠っちゃうだけ… マックスの夢を見て… 幸せに",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_040"] = "ありがとうマックス… 写真家の夢 きっとかなえてよね… あたしを忘れないで",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_060"] = "大好きだよ… また会おうね",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_020"] = "クロエ…",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_050"] = "バカ…",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_070"] = "すぐに会えるよ",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Chloe_020"] = "マックスはその子を見捨てなかった… そうだよね |あたしも同じこと頼んでるだけ",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Chloe_040"] = "マックスは自分で選べる。 何かを決心したら行動すればいいだけ |でもあたしは… 何から何まで… 人任せ |最期ぐらい… 一番重要な決断は… 自分で下したいの |だから… 力を貸して",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Max_010"] = "クロエ… 私にはどうしたらいいか分からないよ |学校の友だちにね… 全部終わりにしようとした子がいて |私はその子を救おうと全力をつくしたの |私にはこんなことをする権利はないよ |きっと… 別の方法があるよ!",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Max_030"] = "クロエを助けてあげたいよ… でも こんなのは間違ってる",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_010"] = "点滴の目盛りを… 11 に上げるだけでいいの",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_030"] = "あたしの意志だよ… あたしが許可してる",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_050"] = "もうとっくにさよならは言ってある |でも望みを聞いてくれないの。 マックス… お願い",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_070"] = "何もしなくてもあたしは死んでしまう 同じこと |少し早めるだけ… どうせ逝くなら幸せな気持ちで逝きたい |親友にその助けをしてもらいたいの…",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_090"] = "どうして…? やっぱりマックスもあたしを見捨てるんだ |もう帰ってよ。 来た瞬間から帰りたかったんでしょ? |もう二度と顔を見せないで",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_020"] = "クロエ… できないよ |クロエが苦しむ姿は見たくないけど 私にはそんな権利ないよ",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_040"] = "でも おばさんに… おじさんが…",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_060"] = "ダメだよ… クロエを殺すなんて…!",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_080"] = "もっと別の形でクロエを助けてみせる。 お願い 私を信じて",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_100"] = "私は… もう二度と離れないって決めたんだ",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_110"] = "おじさん ごめん…",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_010"] = "それはあたしが決めるの! 約束したでしょ!",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_020"] = "パンケーキのこと?",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_030"] = "マックスも何か言って…",
  ["Cue_E4_2B_Garage_PolaRewind_PolarewindVoices_010"] = "「はい チーーーズケーキ!」 |よーし撮るぞ! みんな笑って! |真っ白だよ!",
  ["Cue_E4_2B_Garage_PolaRewind_William_010"] = "クレープ作りを手伝うか?",
  ["Cue_E4_2B_Garage_PolaRewind_William_020"] = "フランス語では「クレープ」だ",
  ["Cue_E4_2B_Garage_TurnPage_Max_010"] = "この写真… もしかして もう一度…",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_020"] = "あたしと 1 日過ごして疲れてたんだね。 確かに ちょっと眠くなる映画だったし |あの主人公は… レプリだと思う?",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_030"] = "ごめん まだ頭が働かないか",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_050"] = "ママとパパは寝落ちしないからね",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_070"] = "誰かさんには負けるよ",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_080"] = "昨日はホント… 楽しかった",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_100"] = "子どもの頃とはもう全然違うけど |でも… マックスといたら |海賊ごっこしながら森を走り回ってたときと同じ気分になれた… |こうして一緒に過ごせるだけで あたしにとっては…",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_110"] = "もう…! またいつもの頭痛が始まったよ… |2 階のバスルームへ行って モルヒネの注射器 取ってきてくれる?",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_130"] = "大丈夫… 最新式のヤツで… 針も極細でさ |ホント冗談じゃなくて… 持ってきてくれるかな |あたしが取れないように 2 階にあるんだけど… |マックスなら 階段上れるでしょ?",
  ["Cue_E4_2B_Garage_WakeUp_Max_010"] = "言ってるそばからさっそく寝るとか… ひどくない?",
  ["Cue_E4_2B_Garage_WakeUp_Max_040"] = "こっちこそ… 爆睡しちゃってごめんね… 大丈夫だった?",
  ["Cue_E4_2B_Garage_WakeUp_Max_060"] = "朝から皮肉?",
  ["Cue_E4_2B_Garage_WakeUp_Max_090"] = "私も。 会えてよかった",
  ["Cue_E4_2B_Garage_WakeUp_Max_120"] = "注射器…?",
  ["Cue_E4_2B_Garage_WakeUp_Max_140"] = "待ってて",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_002"] = "おじさん… あの… 今 お話してもいい?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_008"] = "また来ちゃいました",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_009"] = "やっぱり 医療費の負担はかなり… 大きいんですね",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_010"] = "うまく言葉が見つからないけど… クロエがこんなことになるなんて…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_013"] = "クロエの部屋を見てびっくりしちゃった。 ハイテク装置だらけで",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_017"] = "ホントに… おじさん全然変わってない… なんかウソみたい…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_018"] = "おじさん… この先何があっても 私はずっと… |クロエのそばを離れません。 絶対に",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_019"] = "ずっと会いに来なかったこと怒ってるかな…? |怒って当然ですけど… 私が悪いから…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_020"] = "ほんとに… でもおじさんがいてくれて… |クロエのお父さんがいてくれてよかった",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_023"] = "そろそろクロエのところに戻らなきゃ |おじさんと話せてホントによかったです…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_024"] = "またおじさんとおばさんに会えて… なんかすごく… 懐かしいです",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_025"] = "レイチェル・アンバーって子が行方不明だって 新聞で…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_026"] = "異常気象に 動物が死んだり… 何が起こってるんでしょう…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_027"] = "この町と言えばプレスコット家ですけど… おじさんはどう思います?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_028"] = "クロエのところに戻ります",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_029"] = "パリ旅行 行けたんですね…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_030"] = "目に浮かぶよう… 家族で海外旅行なんて おじさんたち最高ですよ",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_037"] = "よくご存じなんですか?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_001"] = "ダメダメ 請求書の整理中だから! |なんてね。 ダメなわけないよ。 久しぶりだね",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_003"] = "ああ いらっしゃい",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_005"] = "そりゃあ別人になってたらえらいことだ! マックスは大人っぽくなったね |で どうしたの?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_006"] = "ジョイスもがんばってくれてるしね |もし… 僕がいなかったらクロエはどうなってしまうか… |考えるだけで怖いよ",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_007"] = "ほんの数分の出来事が運命を変えてしまった… |でも命は助かったし クロエはよくがんばってる",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_011"] = "正直途方に暮れてるよ。 家のローンもろくに払えない… |でもまあ なんとかなるさ! |僕たち一家は\"プライスレス\"だからね!",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_012"] = "あの部屋 1 つで豪邸が何軒も建つぞ! |…実は保険だけではなかなか… 厳しくてね…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_014"] = "がっかりはしてたけどね… 分かってくれてるさ |僕たちだって現実を受け入れるには 長い時間がかかった",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_016"] = "そりゃあノスタルジーってやつだね! |クロエもよろこんでるよ。 もちろん ジョイスもね |この町もまだ捨てたもんじゃないな。 多分…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_021"] = "ああ 分かってるとも",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_022"] = "あの子もブラックウェルの生徒だったね。 かわいそうに |ご家族は悲しんでるだろう… もしクロエがいなくなったりしたら… |考えるのも恐ろしい…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_031"] = "クロエは留学したいとまで言ってね… もうかなわないことだが… |この世は非情だよ…",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_032"] = "ウイ! マドモワゼル! フランス語はそれしか知らないけどね |クロエは大喜びだったよ",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_033"] = "今生の別れみたいに言わないでくれよ。 またいつでもジャマしにおいで",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_034"] = "僕にはさっぱりだ。 ノストラダムスの予言が現実になったのかな |僕はクロエとジョイスが幸せでいてくれれば それでいいよ",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_035"] = "最低の連中。 以上",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_036"] = "正直 関わりたくないが ジョイスがパン・エステートで働いてるからね |やむを得ずさ",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_010",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_020",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_030",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_040"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_040",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_050"] = "どうしたらいいんだ…",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_060"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_060",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_070"] = "グチばかり言っててもしょうがないな…",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_080"] = "参ったな…",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_090"] = "どうしたもんか…",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_100"] = "ったく…",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_110"] = "まったく…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_010"] = "払っても払ってもきりがない…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_020"] = "どうすりゃいいんだ…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_030"] = "こんな金額 どうやって用意すりゃいいんだか…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_040"] = "何のための保険だか…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_050"] = "もう 1 つ仕事増やすか…",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_060"] = "こりゃジョイスのチップでも とても足りないな…",
  ["Cue_E4_2C_Kitchen_WilliamFindingkeys_William_010"] = "発見! こんなところにいたのか",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_010"] = "ジョイス",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_020"] = "え?",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_030"] = "そんなに荷物が多いなら 車で迎えに行くよ",
  ["Cue_E4_2C_LivingRoom_Insertion_Chloe_020"] = "パパね 最新のパソコンを買うんだ",
  ["Cue_E4_2C_LivingRoom_Insertion_William_030"] = "フラッシュは平気だったかい?",
  ["Cue_E4_2C_LivingRoom_Insertion_William_040"] = "アルバム行きだな",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Chloe_030"] = "今日のマックス 絶対おかしい。 もう会えないみたいな感じ…",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Chloe_050"] = "何の話かさっぱりだけど 元気出しなよ! |あたしマックスがいてくれてホントにうれしいよ |親にも友だちにも恵まれて 不満なんて全然ない |一生友だちだよ。 大人になってもずっと一緒にいようね",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Max_040"] = "クロエ… ホントにごめんね… |なんとかしようとがんばったんだけど… でも… |どうにもできない… ごめん",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Max_055"] = "お願い… 何があっても自分を強くもってほしい |私がクロエのそばにいなくても… 私はずっとクロエを見守ってるから |いつだって味方だから… いつだって…",
  ["Cue_E4_2C_LivingRoom_MaxPickUpPhone_William_030"] = "もしもし",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "えー!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_070"] = "マックスはずっといるの!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "汚い言葉 1 ドル罰金!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_060"] = "言うこと聞かないと |ママ特製のサーモン・サプライズとチョコレートケーキはお預けだ |マックスはどうするんだい?",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_080"] = "そうだったな",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_090"] = "クソっ カギはどこにいった?",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_110"] = "罰金じゃなくて大学資金な… カギは…",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_140"] = "あと ワインの試飲会はダメだぞ…",
  ["Act_E4_2D_Garage_Bathroom_Look01_Max_010"] = "ああ 新しいバスルームを作ったんだ。 いいご両親だな…",
  ["Act_E4_2D_Garage_Bracelet_Look01_Max_010"] = "向こうのクロエの片りん",
  ["Act_E4_2D_Garage_CHChloe_Look01_Max_010"] = "かわいそうって思うのは傲慢だし 失礼だ。 クロエは今でもカッコいい",
  ["Act_E4_2D_Garage_ChloeChair_Look01_Max_010"] = "クロエは私のせいで車イスに…",
  ["Act_E4_2D_Garage_ComputerSP01_Interact01_Max_010"] = "心は今もパンクだね。でもダイブはもうできない…",
  ["Act_E4_2D_Garage_ComputerSP02_Interact01_Max_010"] = "よかった ネットの友だちも出来たんだ",
  ["Act_E4_2D_Garage_Computer_Look01_Max_010"] = "わあ これでパソコン操作するんだ… 人を助けるハイテクってかっこいいな",
  ["Act_E4_2D_Garage_CupWater_Look01_Max_010"] = "一人では 水を飲むこともできないなんて |クロエにも選ぶ権利があったはずだよね?",
  ["Act_E4_2D_Garage_DVDPlayer_Look01_Max_010"] = "DVD プレーヤー。 あとはディスクを探さなきゃ",
  ["Act_E4_2D_Garage_DVDPlayer_Look02_Max_020"] = "これで映画観れるね",
  ["Act_E4_2D_Garage_Drawer_Max_010"] = "ここは薬だけ…",
  ["Act_E4_2D_Garage_E4Drawer02_Look01_Max_010"] = "血流を良くするために これを塗るみたい",
  ["Act_E4_2D_Garage_E4Drawer03_Interact01_Max_010"] = "あ DVD あった",
  ["Act_E4_2D_Garage_E4Drawer04SP01_Interact01_Max_010"] = "ウソでしょ この CD 作ったの 12 の時だよ?",
  ["Act_E4_2D_Garage_E4Drawer05SP01_Interact01_Max_010"] = "最低。 クロエがお金を盗んでくれてよかった… って 別の世界の話だけど",
  ["Act_E4_2D_Garage_E4Drawer05SP01_Interact02_Max_020"] = "最低 |クロエにお金を盗んでもらえばよかった… って あっちの世界の話だけど",
  ["Act_E4_2D_Garage_E4Drawer05_Interact01_Max_010"] = "わあ クロエはオール A だったんだ。 どこの大学だって行けたのに",
  ["Act_E4_2D_Garage_E4Drawer06SP01_Interact01_Max_010"] = "少なくとも 幸せな家族が戻ったんだから…",
  ["Act_E4_2D_Garage_E4Drawer06SP02_Interact01_Max_010"] = "こっちのクロエも やっぱりスケボー好きなんだ",
  ["Act_E4_2D_Garage_HeatLamp_Look01_Max_010"] = "すごい形のヒーター…",
  ["Act_E4_2D_Garage_MakeUp_Look01_Max_010"] = "クロエにメイクしてあげようかな。上手じゃないけど 楽しいかも",
  ["Act_E4_2D_Garage_MedicalVentilator_Look01_Max_010"] = "ああ 息をするにも こんな機械が必要なんだ",
  ["Act_E4_2D_Garage_MouthJoystick_Look01_Max_010"] = "これすごいな… ネコの動画も見放題だね",
  ["Act_E4_2D_Garage_PatientLifter_Look01_Max_010"] = "体重が軽くても大変そう",
  ["Act_E4_2D_Garage_Perfusion_Look01_Max_010"] = "これ モルヒネ用の器具なんだ… |痛いのツラそう…",
  ["Act_E4_2D_Garage_PhotoChloeWilliam_Max_010"] = "この写真を撮っててよかった。 おじさんとの新しい思い出になったよね",
  ["Act_E4_2D_Garage_PinboardSP01_Interact01_Max_010"] = "私の両親もハガキを送ってる",
  ["Act_E4_2D_Garage_PinboardSP02_Interact01_Max_010"] = "これ誰だろう。 ありがちなハガキ",
  ["Act_E4_2D_Garage_PinboardSP03_Interact01_Max_010"] = "私 クロエの近くにいてあげなかった。 ホント いい友だち",
  ["Act_E4_2D_Garage_PinboardSP04_Interact01_Max_010"] = "旅行の写真は送ったんだ。 クロエも さぞ嬉しかったろうね",
  ["Act_E4_2D_Garage_Pinboard_Look01_Max_010"] = "事故の後は手紙の数も少なそう… |私もほとんど書いてない。 ひどいな",
  ["Act_E4_2D_Garage_Scripted_Max_010"] = "クロエに早く水を持っていってあげなきゃ",
  ["Act_E4_2D_Garage_Scripted_Max_020"] = "できることは何でもしてあげるんだ",
  ["Act_E4_2D_Garage_Scripted_Max_030"] = "昔みたいに一緒に映画を見るなんて 変な感じ… でも悪くないね",
  ["Act_E4_2D_Garage_SnowDoe_Look01_Max_010"] = "ああ シカのスノードーム… これは変わってない",
  ["Act_E4_2D_Garage_SnowGlobes_Look01_Max_010"] = "スノードームでいっぱいだ…",
  ["Act_E4_2D_Garage_Tissues_Look01_Max_010"] = "顔の砂を取ってあげられてよかった。 クロエでも きっと私にそうする",
  ["Act_E4_2D_Garage_ToyBear_Look01_Max_010"] = "「やあ クロエ」。 今はぬいぐるみも好きなんだ",
  ["Act_E4_2D_Garage_Window_Look01_Max_010"] = "庭を見て 子どもの頃を思い出したりするの? |もう芝生の感触もわからないなんて…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_001"] = "分かってる。 気にしないで",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_005"] = "大人みたいなセリフ。 子どもの頃は遠い昔だね",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_008"] = "海賊ごっこしながら 町中走り回ったことかな",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_009"] = "デロリアンを改造できたらな…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_010"] = "そうそう パパとママまで小麦粉だらけにしてさ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_011"] = "それに マックスが手伝ってくれないと何もできないよ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_016"] = "みんなもう 連絡もくれなくてさ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_018"] = "ミーガン・ウィーバーっていう… マックスの知らない子 |でも 事故のあと 距離を置かれるようになって…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_019"] = "でも やっぱり遠い昔だよ。 あの頃の友だちは 会いにすら来ない… |マックス以外は",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_020"] = "はは どうかな。 こんな海賊 サマになんないよ |そもそも船に乗れないし。 マックスが乗せてくれる?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_027"] = "でもずっと会いに来てくれなかったよね… 写真とか送ってくれたけど…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_028"] = "ホント バカな質問 |別にさみしくはないよ |そりゃ 夜な夜なパーティには行けないし… 親を困らせたりもできないけど",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_029"] = "分かってる。 パパもママも  しょっちゅうあたしの様子を見に来てくれるんだ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_030"] = "どうやって? 超能力でも使うつもり? |無理するのは うちの親だけで十分だよ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_038"] = "熟年カップルの心配? 仲いいよ あたしのことで大変なのに |手つないでにこにこして… ほんと超ラブラブ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_039"] = "マックス。 2 人にはすごく苦労かけてるの |医療費がすごくかかるのに 保険も当てにならなくて",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_040"] = "薬代も看護師を雇うお金もかかるから… |うちの親はいつもお金のことで悩んでる。 申し訳ないよ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_041"] = "まさか。 金額は教えてくれないけど調べればすぐ分かる |年間の医療費はざっと 100 万ドル…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_042"] = "ま あたしも人のこと言えないけど",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_043"] = "つまんない。 でもありがと",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_002"] = "でも 余計なおせっかいだったね…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_003"] = "ほんとだよね… またあの頃に戻れたらいいのにね",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_004"] = "一番仲よかったのは誰?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_006"] = "クロエは 子どもの頃の思い出で 何が一番印象に残ってる?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_007"] = "私には つい昨日のことみたいに思えるよ |「パワーレンジャー」観たり 台所めちゃくちゃにしたり",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_012"] = "あれは笑えたよね",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_013"] = "懐かしいね。 今でも 海賊スピリットは忘れてないよ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_014"] = "そ… そうだね… クロエは科学が得意だから できるかもだけど… |タイムトラベルは リスクも大きいから…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_021"] = "私がいるよ。 もうどこへもいかないから",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_031"] = "もっと早く会いに来るべきだったよね。 完全に 私が悪いよ |でも もう違う。 過ちは正すから…",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_032"] = "あのね… バカな質問かもしれないけど… クロエはさみしくない?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_033"] = "2 人とも元気? その… 今も相変わらず仲よくやってる?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_034"] = "2 人とも クロエを愛してるよ",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_035"] = "大変だよね… この装置だって すごく高そうだし",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_036"] = "ちゃんと… 払えてるの?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_037"] = "クロエはいいご両親に恵まれたね",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_044"] = "でも… クロエは\"プライスレス\"だよ。 えっと… シャレじゃなくてね",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_010"] = "会いに来てくれて うれしいよ",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_020"] = "今でもつきあってくれるのはマックスだけ",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_030"] = "相変わらずマイペースだね",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_040"] = "私の部屋 ずいぶん変わったでしょ?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_050"] = "水を取ってくれる?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_060"] = "マックスと映画なんてうれしいな。 DVD はテレビのそばだよ",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_070"] = "ごめん ノドが… ガラガラなの… 水を 取ってくれる?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_015"] = "私もうれしい",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_025"] = "もっと早く来るべきだったね…",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_035"] = "懐かしいでしょ?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_045"] = "そうだね… でも… クロエらしいよ",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_055"] = "分かった",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_065"] = "了解! ちょっと待ってね",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_075"] = "分かった!",
  ["Cue_E4_2D_Garage_Cloth_Chloe_010"] = "ありがと… ちょっと 目に砂でも入ったかな",
  ["Cue_E4_2D_Garage_Cloth_Chloe_030"] = "中国のことわざみたい。 「セイカリョウゲン」って言ってさ… |「バタフライエフェクト」と同じ",
  ["Cue_E4_2D_Garage_Cloth_Max_020"] = "砂って 1 粒入るだけで すごい涙 出るもんね",
  ["Cue_E4_2D_Garage_Cloth_Max_040"] = "そうだね",
  ["Cue_E4_2D_Garage_Insertion_Chloe_020"] = "独房みたいでしょ。 でもパパとママにはすごく感謝してる。 苦労かけてるから",
  ["Cue_E4_2D_Garage_Insertion_Chloe_040"] = "そうかな。 私のせいで散歩にすら行けないんだよ? |ときどきわざと 2 人を怒らせて 怒鳴りつける口実作ってあげるの |バカみたいでしょ?",
  ["Cue_E4_2D_Garage_Insertion_Chloe_060"] = "マックスが思ってるような天使じゃないよ |用を足すとこ看護師に見られたり 医者に物みたいに扱われたりして |子どもみたいにかんしゃく起こすこともある",
  ["Cue_E4_2D_Garage_Insertion_Chloe_080"] = "今日はホントにありがとね。 あー声かれてきちゃった |そこの… 水取ってくれる?",
  ["Cue_E4_2D_Garage_Insertion_Max_010"] = "すごいハイテク装置だね…",
  ["Cue_E4_2D_Garage_Insertion_Max_030"] = "そんなふうに思われてないよ…",
  ["Cue_E4_2D_Garage_Insertion_Max_050"] = "クロエは… 本当にいい子だよ |素直で優しいし… つらくても泣き言言わないし",
  ["Cue_E4_2D_Garage_Insertion_Max_070"] = "そんなの想像つかない…|でも クロエは子どもの頃から 親思いのいい子だったよ",
  ["Cue_E4_2D_Garage_Movie_Chloe_010"] = "でも 娯楽なら何でもそろってるよ |子どもの頃 お泊り会したときみたいに なんか映画でも観よっか?",
  ["Cue_E4_2D_Garage_Movie_Chloe_030"] = "えっと… 「ブレードランナー」が観たいかな? ラストは泣くけど |子どもの頃 プリスの髪型にあこがれてたし",
  ["Cue_E4_2D_Garage_Movie_Chloe_050"] = "そうだったね。 ちゃんと起きてるよ。 マックスがいる間は… 大丈夫",
  ["Cue_E4_2D_Garage_Movie_Max_020"] = "うん。 リクエストは?",
  ["Cue_E4_2D_Garage_Movie_Max_040"] = "覚えてる。 いっそ青に染めたら似合うよ |じゃ さっそく観ましょうか |でもクロエ 映画観てると途中で寝るからなあ…",
  ["Cue_E4_2D_Garage_Water_Chloe_020"] = "ありがと… そりゃ声もかれるよね。 こんなにしゃべったの久しぶりだもん",
  ["Cue_E4_2D_Garage_Water_Chloe_040"] = "つまんない冗談やめてって |ポッドキャスト? 毎日ここに缶詰なのに ネタがないよ",
  ["Cue_E4_2D_Garage_Water_Max_010"] = "はい どうぞ",
  ["Cue_E4_2D_Garage_Water_Max_030"] = "それじゃ ポッドキャストとか やってみたら?",
  ["Cue_E4_2D_Garage_Water_Max_050"] = "ごめん… ちょっと思っただけ",
  ["Act_E4_3A_Bathroom_HairDye_Look01_Max_010"] = "青いヘアカラー うれしいな。 本当のクロエが戻ってきたんだ",
  ["Act_E4_3A_Bathroom_Sink_Look01_Max_010"] = "学校のトイレで顔を洗った時 何もかもが変わったんだ…",
  ["Act_E4_3A_ChloeRoom_AshTray_Look01_Max_010"] = "うん いつものクロエだ",
  ["Act_E4_3A_ChloeRoom_ButterflyPicture_Look01_Max_010"] = "この写真を撮ったの ずっと昔のことみたい… |あれから何度 力を使ったんだろう",
  ["Act_E4_3A_ChloeRoom_CashBox_Look01_Max_010"] = "お金の山… ごめんね 校長先生",
  ["Act_E4_3A_ChloeRoom_ChChloe_Look02_Max_020"] = "おじさんがクロエをどんなに愛してたか 言えたらいいのに…",
  ["Act_E4_3A_ChloeRoom_ChloeRoomWindow_Look01_Max_010"] = "こんなに穏やかな天気なのに 明日竜巻が襲ってきたりするの?",
  ["Act_E4_3A_ChloeRoom_Coffecups_Look01_Max_010"] = "徹夜はコーヒーを飲むいい口実だよね",
  ["Act_E4_3A_ChloeRoom_CrumbledPapers_Look01_Max_010"] = "どんな名探偵でも 手がかり全部は使わないよね",
  ["Act_E4_3A_ChloeRoom_GunMagazine_Look01_Max_010"] = "これでこそクロエだ",
  ["Act_E4_3A_ChloeRoom_Gun_Look01_Max_010"] = "クロエに銃を返すの やっぱり嫌だな",
  ["Act_E4_3A_ChloeRoom_InvestigationBoard_Look01_Max_010"] = "今やってることを考えたら 昔のお絵かきはホント無邪気だな",
  ["Act_E4_3A_ChloeRoom_MagazineClipping_Look01_Max_010"] = "プレスコット家を追及する記事なんて初めて… やった!",
  ["Act_E4_3A_ChloeRoom_PrintedEmail_Look01_Max_010"] = "留守電を消したぐらいじゃ 警察はごまかせないよね…",
  ["Act_E4_3A_ChloeRoom_PrintedEmail_Look03_Max_010"] = "ああ クロエまた見つかっちゃった。 前は私も共犯者だったけど 今は違う",
  ["Act_E4_3A_ChloeRoom_Scripted02_Max_020"] = "こんな力 むやみに使うのは危険すぎる |過去をメチャクチャにするのはやめて うまく現実を乗り切らなきゃ…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_010"] = "調査ボードに戻らなきゃ…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_020"] = "まるで迷路みたい… ていうかぐちゃぐちゃ",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_030"] = "ガレージに行ってデイビッドのファイルを調べなきゃ…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_040"] = "早く この世界に慣れなくちゃ…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_050"] = "戻って来たはいいけど こっちで何が起きてたか全然わかんない…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_060"] = "クロエがこんなに一生懸命になってるとこ 見たことない…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_070"] = "素人にしては レイチェル発見にかなり近づいてる気がする",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_080"] = "クロエが事故に遭った世界は まだ存在してるの?",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_090"] = "別の世界のことを考えるのはやめて 今に集中しなくちゃ",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_100"] = "ああ クロエと元に戻れてどんなにうれしいか 教えてあげたいよ",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_110"] = "ああ クロエを死なせるなんて絶対できなかった",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_120"] = "あっちの世界のクロエ… 願いを叶えてあげられなくてごめんね…",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_130"] = "わあ クロエの病室が あっという間にデイビッドの作業部屋に戻ってる",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_140"] = "新しい力で 自分が写った写真のどの瞬間にもタイムスリップできるんだ… |自撮りでも",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_150"] = "自撮りを使ってタイムスリップしてたら もっとメチャクチャなことになりそう…",
  ["Act_E4_3A_ChloeRoom_ShoeBox_Look01_Max_010"] = "おじさん ごめんなさい… 2 度も死ぬことになるなんて…",
  ["Act_E4_3A_ChloeRoom_SnowDoe_Look01_Max_010"] = "壊れたままのスノードーム… おじさんとクロエの運命みたい",
  ["Act_E4_3A_ChloeRoom_SnowDoe_Look02_Max_010"] = "これを見ると いつもおじさんとクロエのことを考える",
  ["Act_E4_3A_ChloeRoom_zen_Max_010"] = "いつも通りの風景に帰ってきたんだ…",
  ["Act_E4_3A_ChloeRoom_zen_Max_020"] = "何が起きたか クロエには絶対に言えない…",
  ["Act_E4_3A_ChloeRoom_zen_Max_030"] = "大事故に遭わせて 最後は安楽死させた… |それでおじさんをまた死なせて? |そんなの親友にどう説明するの?",
  ["Act_E4_3A_ChloeRoom_zen_Max_040"] = "大事故に遭わせて 最後の望みも叶えてあげなかった… |それでおじさんをまた死なせて? そんなの親友にどう説明するの?",
  ["Act_E4_3A_ChloeRoom_zen_Max_050"] = "ダメだ… 絶対に言えない。 クロエのこれからのためにも",
  ["Act_E4_3A_ChloeRoom_zen_Max_060"] = "でも竜巻が本当なら 来週にはみんな消えちゃうんだよね…",
  ["Act_E4_3A_Corridor_ArcadiaBayPoster_Look01_Max_010"] = "竜巻がきたら この町のポスターなんて作られないだろうな…",
  ["Act_E4_3A_Corridor_BlueBird_Look01_Max_010"] = "あっ あの小鳥 ここから出られないんだ!",
  ["Act_E4_3A_Corridor_BlueBird_VoiceOver01_Max_010"] = "ほら とんでけ!",
  ["Act_E4_3A_Corridor_BlueBird_VoiceOver01_Max_020"] = "ウソ! かわいそうに…",
  ["Act_E4_3A_Corridor_ParentsDoor_Look01_Max_010"] = "中にデイビッドがいるかもしれないし 他をあたろう",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_010"] = "分からないな…",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_020"] = "なんか見落としてるような…",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_030"] = "何か分かりそうなんだけど…",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Max_033"] = "よく調べてみて",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Max_036"] = "その調子だよ!",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_010"] = "「トバンガは この町 最古のトーテムポールである…」",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_020"] = "「しかし 地元のネイティブ・アメリカンは 製作したことを 認めていない」…",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_030"] = "ごめん つい夢中になっちゃった |「トバンガ」って名前も… なんか気になるし",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Max_025"] = "ネイサンが造ったんじゃないの?",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Max_035"] = "あんまり脱線しないでよ?",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_020"] = "オッケー。  何のこと…?",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_040"] = "んで クソオヤジから フランクとネイサンと「暗い部屋」について聞き出す!",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_050"] = "銃もあるしな…",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_080"] = "せめて銃があればな…",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_100"] = "クソオヤジを殴って巻き戻せば…!|はいはい分かりましたよ",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_120"] = "ま 金が手に入ったからいいけど",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_140"] = "あの金だって 取っときゃ借金返せたのに",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_160"] = "分かってる。 それじゃ マックスはガレージを調べてくれ |あたしはネットで 誰がどことつながってるか 探ってみる",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_170"] = "クソオヤジには気をつけろよ… ま 昨日の様子じゃ 仲良しみたいだけど",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_190"] = "クソオヤジに見つかんなよ… |ママに三行半突きつけられて 根に持ってるだろうから",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_010"] = "必要な情報が足りてない…|やるべきことは 3 つある",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_030"] = "まず フランクの手帳の解読  |それから ネイサンの電話を手に入れて |ボルテックス・クラブのパーティの日にどこにいたか探る |それから チャットのログも調べる",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_060"] = "しまっておいて。 そんなもの使わないよ",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_090"] = "またその話? 銃なんて必要ないよ",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_110"] = "この力はムダ使いできないの。 とにかく… 慎重に使わないと…",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_130"] = "あれは例外… フランクは危険だから やむを得ずだよ",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_150"] = "クロエ 私たちは泥棒じゃないんだよ",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_180"] = "やめてよ…",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_200"] = "任せといて",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_030"] = "うわ おい なんだよ! あのキスはそういうんじゃないぞ?",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_040"] = "やっぱりキスしたくなったのか? もう遅い",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_060"] = "なんか気持ち悪りいな… おかげで目が覚めたけど |徹夜で探偵ごっこしてたせいで 頭ボーッとしてたからさ",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_080"] = "ってか この話 したよな? あたしが寝てる間に またなんかしたか…?",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_010"] = "クロエ… よかった!",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_020"] = "クロエ… よかった 生きてる…!",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_050"] = "うれしいの… クロエが元気そうで!",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_090"] = "してないよ。 私もボーッとしてるだけ",
