  ["Act_E4_3B_LivingRoom_TornPhoto_Look01_Max_010"] = "おばさん すごく怒ってたんだ… 私 誰かの役に立ってる?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_001"] = "ブラックウェルには色々な事情がある。 お前は余計なものを見過ぎた |これ以上 首を突っこむな",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_007"] = "は? 誰がそんなこと言った。 ネイサン・プレスコットか? |停学で済むとは運のいいヤツだ!",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_008"] = "は? 誰がそんなこと言った。 ネイサン・プレスコットか? |あれで停学にならないとは運のいいヤツだ…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_011"] = "俺はお前のせいでクビだ お互い様さ。  とりあえずはな",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_012"] = "あの時はまだ証拠が揃っていなかったんだ。その  悪かったな マックス。",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_013"] = "で 俺がプレスコットに雇われてる証拠はあるのか?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_014"] = "あの性悪小僧め 停学で済むとは運のいいヤツだ!",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_015"] = "ネイサン・プレスコット? あれで停学にならないとは運のいいヤツだ…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_018"] = "感心するよ… たいした探偵だな。 だが 俺は雇われたわけじゃない |見積もりを出しただけだ。 個人的な理由でな",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_019"] = "どうせ信じないだろうが… |俺はショーン・プレスコットの腐った一族に仕える気は一切ない",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_020"] = "とにかく… 誰にとってもキツい 1 週間だった |特にケイト・マーシュには…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_023"] = "助けたさ。 お前はまさにヒーローだった |そもそも俺が屋上のカギを閉めておけば… ケイトもあんなことには",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_024"] = "お前は助けようと頑張った。 少なくとも俺よりは |そもそも俺が屋上のカギを閉めておけば… ケイトもあんなことには",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_025"] = "真っ先に屋上へ駆けつけたのもお前だしな",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_028"] = "奴は口先ばかりの気取り屋だ。 非番で家にいる今だから言うけどな |クロエも陰じゃ俺を「クソオヤジ」と呼んでるだろ |まったく 何が「アーティスト」だ",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_031"] = "類は友を呼ぶってやつだろ… 気取り屋同士",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_032"] = "アーティストなんて自分勝手なやつばかりだ |兵役中に何がいやだったって |人をよってたかって反戦ナントカのモデルにしたがる写真家どもさ",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_034"] = "俺には家庭があるんだよ。 それに俺はブラックウェルで働くしかないんだ |俺がいないと大変なことになる",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_035"] = "そんな中 グラント先生と楽観主義者どものせいで 監視カメラが中止になった |誰もレイチェル・アンバーとケイトから学んでない",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_037"] = "ブラックウェルに監視カメラを導入させるのも 生徒を守るためだ| これ以上レイチェル・アンバーやケイトのような子を出さないためにな…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_038"] = "しかし お前も監視カメラに負けない働きぶりだ |俺をかばってくれたのはありがたいが |お前やクロエがこれ以上 首を突っこむのを見過ごしにはできん |事態はひどくなる一方だ",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_040"] = "ふん… そろそろカメラの方を仕上げるとするか |俺だって アーティストなのさ",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_004"] = "「暗い場所」ってどこのこと?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_005"] = "今さらムリです。 すでに色々知ってるし |例えば あなたがショーン・プレスコットに雇われてるとか…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_006"] = "今さらムリです。 すでに色々知ってるし |例えば あなたとネイサン・プレスコットは…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_009"] = "私が停学になったことについては 何かないんですか",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_010"] = "運は関係ないと思いますけど。 私が停学になっても おかしくなかったし…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_016"] = "以前はパン・エステートの警備担当者だったんでしょ。 書類を見ました",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_017"] = "いえ。 でもプレスコット家の力は知ってます。 あなたが手下だってことも",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_021"] = "誰一人 助けようとしなかった…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_022"] = "助けようとはしたけど…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_026"] = "ケイトが苦しんでるのは知ってたのに |ジェファソン先生も。 今さら謹慎したって…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_027"] = "ケイトが苦しんでるのは知ってたのに。 ジェファソン先生も…",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_029"] = "先生は確かに気取り屋だけど… |私もそうだし… 写真に関してはホンモノなんです",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_030"] = "なぜそう思うんです?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_033"] = "でもブラックウェルはアーティストの学校ですよ |そんな所で働いて楽しいですか",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_039"] = "クロエと私なら 心配いりませんから",
  ["Cue_E4_3B_Garage_CHDavid_Phase02_David_002"] = "後にしてくれ 作業中だ",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_010"] = "おい そこ こそこそかぎ回ってるのはお見通しだぞ",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_020"] = "目の前で人の家を荒らすつもりか",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_030"] = "悪いが ここは「男の隠れ家」なんでな…|女子は立入禁止だ",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_040"] = "なあマックス…  あの時はかばってくれてありがとうよ",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_Chloe_030"] = "おい! 誰かヒューズ直せよ!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_010"] = "マックス 俺は周りをちょろちょろされるのは好かん。 やめろ",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_020"] = "ウソだろ こないだ直したばかりだぞ!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_050"] = "おいこら マックス! 人のものに勝手に触るな!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_060"] = "おい",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_010"] = "クロエ! ねえまだ? 寮に戻らなきゃ!",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_030"] = "バッチリ…! 秘密のファイルを発見したの… |ケイトと ネイサンと レイチェルの |あと 場所を示す座標もあった |デイビッドは本気で何か調べてるみたい… |見つかるとヤバいから 早く行こう!",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_035"] = "バッチリ…! 秘密のファイルを発見したの… ケイトと ネイサンと レイチェルの |あと 場所を示す座標もあった |デイビッドは本気で何か調べてるみたい… |見つかるとヤバいから 早く行こう!",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_David_010"] = "お前の勝ちだ マックス。 俺の家庭をみごと壊したな。 満足か",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_David_030"] = "手遅れさ もう | あいつは… 危なっかしいから気をつけてやってくれ |暗がりには踏み込むなよ…",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_Max_020"] = "待って… そんなつもりじゃなかったんです。 本当に |ただ クロエが傷つくのを見たくなくて",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_010"] = "俺に何か用か?",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_030"] = "お前には借りがある。 今日のところは信じてやるよ その言い訳",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_050"] = "そうかい。 クロエと出かけるんなら 危ない所には近寄らないようにな |アルカディア・ベイには暗い場所が多い",
  ["Cue_E4_3B_LivingRoom_DavidWorking_Max_020"] = "あ… クロエを待ってるだけです いまお手洗いに行ってて",
  ["Cue_E4_3B_LivingRoom_DavidWorking_Max_040"] = "「お前」じゃなくて コールフィールドです",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_010"] = "収穫は?",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_040"] = "よし 次は ネイサンの部屋だな",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_070"] = "よし 次はネイサンに目に物見せてやろう",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_020"] = "バッチリ! 見つからないうちに行こう",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_030"] = "寮に戻る前に ケイトのお見舞いに行っていい? 元気にしてるかな…",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_050"] = "慎重に行動しないと…",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_055"] = "慎重に行動しないと…",
  ["Act_E4_3C_ChloeRoom_CHChloe_Look01_Max_010"] = "ああクロエ こんなことになって本当にごめん",
  ["Act_E4_3C_ChloeRoom_CHChloe_Look02_Max_020"] = "レイチェルがもうすぐ見つかりそうだから クロエ すごい勢い",
  ["Act_E4_3C_ChloeRoom_Computer_Look01_Max_010"] = "必要な物は全部プリントしたし 調査ボードで考えよう…",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step1_Look01_Max_010"] = "写真を撮るだけじゃなくて もっとできたことあったのに…",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step2_Look01_Max_010"] = "これが誰の車か調べなきゃ",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step3_Look01_Max_010"] = "この座標はネイサンの部屋を示してたんだ… まだ何か隠してるかも",
