  ["Act_E4_3C_ChloeRoom_DavidClue02Step3_Look02_Max_020"] = "フランクがいつもいるビーチだ",
  ["Act_E4_3C_ChloeRoom_DavidClue03Step1_Look01_Max_010"] = "防犯カメラ つけすぎだよ",
  ["Act_E4_3C_ChloeRoom_DavidClue03Step2_Look01_Max_010"] = "うーん 他に誰の車をつけてたんだろう…",
