  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_020"] = "ああもう… 絶対なにか間違ってる…",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_030"] = "遊びはもういいから。 はい もう 1 回",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_040"] = "ダメ。 間違い。 これじゃない",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_050"] = "大っ嫌いな数学みたい。 ホント苦手",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_060"] = "なんか悲しくなってきたよ",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_070"] = "それじゃデタラメじゃない",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_080"] = "それとこれとは どう考えても関係ない",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_090"] = "違う。 他の手がかりをたどった方がいいみたい",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_100"] = "これは全然関係ないみたい",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_110"] = "関係性がないよ",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_120"] = "この組み合わせは間違いってことか",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Chloe_030"] = "やってみる",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Chloe_040"] = "待ってて レイチェル…",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Max_010"] = "よし これでやっと何か分かりそう…",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Max_020"] = "クロエ この座標から 実際の住所を割り出せないかな?",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Chloe_050"] = "そうだな… 分かった… しっかりしなきゃ… レイチェルのためだ… よし…",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Chloe_070"] = "フランクもだ。 あたしが巻き込んだ…",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_020"] = "クロエ… ねえ 聞いて… クロエだけが悪いわけじゃない |私のせいでもあるんだよ。 私がクロエを助けなかったから… |だから泣かないで",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_060"] = "そうだよ。 平気でいろっていうほうがムリなのは分かってるけど… きっと… |これは運命なんだ。 たくさんある運命の 1 つ |だから… 一緒に最後まで見届けよう? |レイチェルと ケイトのためにも",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_080"] = "がんばろう? しっかり集中して 手がかりを探らなきゃ |この座標をネットで調べてほしいの |そこに… レイチェルがいるかもしれない",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_090"] = "ありがとう",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDead_Max_010"] = "よし これでやっと何か分かりそう…! |クロエ この座標をネットで調べてくれる? |クロエ?",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDead_Max_030"] = "あれは正当防衛だったの! |気持ちは分かるけど 今は 1 分 1 秒も ムダにできないんだよ |レイチェルを見つけなきゃ",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_010"] = "マックス… あたし 人 殺しちゃった…",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_020"] = "あたし どうなるの…?",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_030"] = "なんでこんなことになったの… なんで…",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_040"] = "あの状況で… どうすりゃよかったの…?",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_050"] = "レイチェル お願い 無事でいて…",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_010"] = "手がかりを組み合わせれば 何か分かるはずだ",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_020"] = "マックスがいて 心強いよ",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_030"] = "ボードの手がかりを整理してくれ",
  ["Cue_E4_3C_ChloeRoom_ChloeQuickphase01_IGE_Chloe_010"] = "マックスは そこのボードに貼った手がかりを整理してみてくれ |あたしは 引き続きネットでいろいろ調べてみる",
  ["Cue_E4_3C_ChloeRoom_ChloeRecover_Chloe_040"] = "待っててレイチェル…",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_060"] = "所有者は… ハリー・アーロン… プレスコット…!",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_080"] = "バカ言うな。 警察はプレスコット家の犬だ",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_100"] = "この町 全体 腐りきってんだよ |警察も 誰も信用できない。 だから あたしらで調べにいく",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_130"] = "いや その必要はない。 大丈夫… マックスがいるし |レイチェルはきっと見つかるよ… 絶対に見つかる",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_150"] = "はいはい",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_070"] = "なるほど…",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_071"] = "警察に… 通報する…?",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_090"] = "腐ってるよ…",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_110"] = "やっぱりそうなるか… ウォーレンも連れていこうか? 用心棒になるよ",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_140"] = "うん。 でもクロエ… 力をあてにしすぎないで |慎重に行動するんだよ。 約束して",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_020"] = "ちょっと調べてみる",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_030"] = "いや… ハズレだな。 そこにはボロい納屋しかない",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_050"] = "ちょっと待ってろよ…",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Max_010"] = "これ見て… 見るからに怪しくない?",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Max_040"] = "その納屋の所有者 誰か分かる?",
  ["Cue_E4_3C_ChloeRoom_FrankDeadBis_Chloe_010"] = "マックス… あたし… レイチェルが見つかったら自首するよ… |一生隠し通すなんて絶対にムリだし… |逃亡生活なんてマジごめんだし |でもマックスのことは絶対に黙ってるから!… 安心して",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_020"] = "フランクを説得できてよかった。 敵は少ないほうがいい",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_040"] = "フランクの脚を撃ったことが 気になって…",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_045"] = "フランクのことが 気になって…",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_060"] = "信じらんないよ… フランクが… 死んだなんてさ… あたしが殺ったんだ",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_010"] = "クロエ… 大丈夫?",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_030"] = "そうだね",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_050"] = "あれは正当防衛だよ。 もう忘れよう。 フランクは自業自得だよ",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_070"] = "クロエ… あれは正当防衛だよ。 もう忘れよう。 レイチェルを探すんでしょ?",
  ["Cue_E4_3C_ChloeRoom_MaxAnswers_IGE_Max_010"] = "大丈夫だよクロエ。 私がなんとかするから |これまでに分かった情報を整理してみる",
  ["Cue_E4_3C_ChloeRoom_MaxAnswers_IGE_Max_015"] = "分かった。 情報を整理して よく考えてみるよ",
  ["Act_E4_3E_Hospital_Balloons_Look01_Max_010"] = "「よくなって」って ちょっと違うよね",
  ["Act_E4_3E_Hospital_Book_Look01_Max_010"] = "感想書くのも続けてるんだね",
  ["Act_E4_3E_Hospital_CHKate_Look01_Max_010"] = "つらい思いをして 今は天使みたいに寝てる",
  ["Act_E4_3E_Hospital_CHKate_Look02_Max_020"] = "また絵を描くようになったんだ… よかった",
  ["Act_E4_3E_Hospital_CatholicStuff_Look01_Max_010"] = "これでケイトが安眠できるなら いいと思う",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_010"] = "また こうやってケイトと過ごせるなんて うれしい…",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_020"] = "時間を止めてなかったら ケイトはやっぱり飛び降りてた?",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_030"] = "私がどこまで運命を変えてるかは 分からない…",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_040"] = "でも 運命はひとつしかないって 誰が言ったの?",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_050"] = "考えると 頭ぐちゃぐちゃになる…",
  ["Act_E4_3E_Hospital_Curtains_Look01_Max_010"] = "ちょうどいい光。 カーテンは開けないでおこう",
  ["Act_E4_3E_Hospital_FamilyPortrait_Look01_Max_010"] = "ありがとう。 妹さんたちのおかげだよ",
  ["Act_E4_3E_Hospital_Flowers_Look01_Max_010"] = "きれいな花… テイラーにしては気が利くね",
  ["Act_E4_3E_Hospital_GetWellSoon_Look01_Max_010"] = "すごくいいね… ビクトリアまで。 でもネイサンはなしか",
  ["Act_E4_3E_Hospital_KateDrawings_Look01_Max_010"] = "ふふ ケイトの描くキャラ 大好き",
  ["Act_E4_3E_Hospital_MedicalBed_Look01_Max_010"] = "クロエのベッドを思い出す… 安楽死を手伝う心配はないけど",
  ["Act_E4_3E_Hospital_MedicalBed_Look01_Max_020"] = "クロエのベッドを思い出す… 安楽死させるなんて絶対無理だった",
  ["Act_E4_3E_Hospital_Scripted_Max_010"] = "ケイトに会えて本当にうれしい…",
  ["Act_E4_3E_Hospital_Scripted_Max_020"] = "病院て好きじゃないな… 寒く感じる…",
  ["Act_E4_3E_Hospital_Scripted_Max_030"] = "ケイトの家族はどんな気持ちでいるんだろう…",
  ["Act_E4_3E_Hospital_Scripted_Max_040"] = "ケイトなら役に立つネイサンの情報をもっと知ってるかも…",
  ["Act_E4_3E_Hospital_VictoriaPostcard_Look01_Max_010"] = "ビクトリアは女王様気取りだけど 本当は悪い子じゃない",
  ["Act_E4_3E_Hospital_WellsLetter_Look01_Max_010"] = "ウェルズ校長も こういうこと書くんだ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_001"] = "何もかも マックスのおかげだよ |何か聞きたいことがある顔してるけど どうしたの?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_003"] = "うん もちろん",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_005"] = "ありがとう。 マックスは優しいね |ウサギの世話もしてくれて… アリスに よろしく伝えて",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_007"] = "ネイサンにはしかるべき罰を受けさせなきゃ |これ以上 犠牲者を増やしちゃダメだよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_009"] = "そうなの…? マックスすごい! ホントに勇気があるね",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_012"] = "でもネイサンのお父さんが そんなことさせないと思う。 うちの親よりひどいよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_013"] = "ネイサンは今 どうしてるの?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_017"] = "あれだけのことして おとがめなしなんて…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_020"] = "私も協力する! 部屋番号を調べて スマホに送るよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_021"] = "こういう言葉は使いたくないけど プレスコット家の人たちは悪魔だと思う |人の死にすら関係してそう…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_023"] = "これ以上 ネイサンを野放しにできないよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_024"] = "いいね! ついでに ウォーレンも誘ってみたら?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_028"] = "今週は お茶できなかったしね",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_029"] = "なにそれ。 じゃ 二人旅だね",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_030"] = "頭がよくておもしろくて… 優しい人だと思う。 かっこいいしね |絶対マックスに気があるよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_034"] = "ううん 行くべきだよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_035"] = "もったいない… お似合いだと思うけどなあ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_036"] = "マックスには幸せになってほしいから",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_039"] = "ビクトリアは確かに… その… |意地悪なとこもあるけど すべての罪は許されるべきだと信じてるから |彼女もきっと いろいろな悩みを抱えてるんだと思う",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_042"] = "そんなことあったんだ… でも なんでビクトリアは意地悪するのかな",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_045"] = "なんでなのかな… 手紙にはあんなに優しい言葉を書いてくれたのに",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_046"] = "なんでかな。 もっと自信持っていいのにね",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_048"] = "ううん… もっと根が深い問題だと思う…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_002"] = "ケイト 元気そうだね よかった",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_004"] = "ケイト もう少し喋ろ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_006"] = "そろそろ行くね… 捜査を進めなきゃ。 元気な顔を見られてよかったよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_008"] = "ネイサンが犯人だって証拠を もう少しでつかめそうなの",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_010"] = "ホント 退学にしてやれなかったのが悔しいよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_011"] = "私が証言したおかげで停学になったから しばらくは安心だけど",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_015"] = "しれっと今夜のパーティに 顔出すつもりじゃないかな",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_016"] = "親に泣きついてるんじゃないかな。 ひきょうな人たち…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_018"] = "ケイトとおしゃべりしたくて",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_019"] = "私に任せて。 ネイサンの部屋番号さえ分かれば |忍び込んで証拠を探せるんだけど…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_022"] = "男子禁制だよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_025"] = "ありがとう ケイト。 頼りにしてるよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_026"] = "じゃあ 埋め合わせに 今度ポートランドまで喫茶店ツアーにでも行こうか",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_031"] = "ウォーレンのこと… どう思う?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_032"] = "週末 デートに誘われてるんだよね… どうなることやら |でも こんなときに男子と出かけてていいのかな…",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_033"] = "そうみたいだね… 週末デートに誘われたけど 断っちゃった",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_037"] = "ケイトがいてくれれば 恋の悩みもあっという間に解決だね",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_038"] = "ビクトリアの手紙 見たよ… どう思う?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_040"] = "私も ビクトリアがペンキかぶったところを 写真に撮って… |悪いことしたな… 反省してる",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_041"] = "そうだね… 私も ビクトリアがペンキかぶったとき なぐさめてあげたら… |ちょっと分かり合えた感じがした",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_043"] = "そういう人だからだよ。 だってビクトリアは お金持ちだし かわいいし |才能だってあるでしょ? |周りに当たり散らす必要なんてないよ",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_044"] = "自信がないんだよ。 劣等感があるから… 威張ってないと不安なんだと思う",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_047"] = "ビクトリアを救ってあげられるとしたら… ケイトしかいないよ",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_010"] = "どうだった",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_030"] = "来てよかったな",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_050"] = "次はネイサンのお見舞いに行くとするか。 あいつは嬉しがらないだろうけどな",
  ["Cue_E4_3E_KateRoom_Extraction_Max_020"] = "元のケイトに戻ってきてる|よかった…",
  ["Cue_E4_3E_KateRoom_Extraction_Max_040"] = "ついてきてくれてありがとう",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_010"] = "病院は嫌いなんだよ",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_030"] = "マックスに会いたがってるよ。 決まってんだろ?",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_050"] = "ただ… そばにいてやればいいんだよ。 あたしは外で待ってるからさ",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_060"] = "こないだ… ケイトの電話に出たからってブチ切れて悪かった |マックスが正しかった |あの子はひどい目に遭ったんだろうな… でもマックスが助けた |あたしと同じように  ごめんな…",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_070"] = "あのさ… こないだはケイトの電話の件で怒って悪かった |あの子はひどい目に遭ったんだろう… |あたしが味方を取りあげちまった |マックスが助けてくれて…|よかったよ。 ごめんな…",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_090"] = "だな。 ケイトに うちらが仇を取るって言ってやりな",
  ["Cue_E4_3E_KateRoom_Insertion_Max_005"] = "ケイトはこの階のはず",
  ["Cue_E4_3E_KateRoom_Insertion_Max_020"] = "そ そうだね。 でもケイトのことを思うと… |面会できるようになってよかった。 少しは落ち着いたかな",
  ["Cue_E4_3E_KateRoom_Insertion_Max_040"] = "だといいけど。  なんか緊張する…",
  ["Cue_E4_3E_KateRoom_Insertion_Max_080"] = "ありがとクロエ。 でも もういいよ。 私たち チームでしょ",
  ["Cue_E4_3E_KateRoom_Insertion_Max_100"] = "そうね。  そうする",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_010"] = "あなたが退屈でなければいいんだけど…",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_020"] = "マックスがいてくれるだけで楽しいな",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_030"] = "お見舞いに来てくれてありがとうね",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_040"] = "母さんまであんなに優しい手紙をくれるなんて思わなかった",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_010"] = "マックス!",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_030"] = "もう会えないかと思った。 私 バカなことして… ほんとにごめん",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_050"] = "マックスが来てくれたから ずっと良くなった |あのときは ほんとにありがとう… 私もう どうしたらいいか分からなくて… |でも あなたがどれだけ心配してくれてるか気付いたから… |私はひとりじゃないって信じられた |マックスのおかげだよ",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_070"] = "そうね どれだけ手紙やハガキが来たことか |お花は私にはもったいないから 他の患者さんにだいぶあげちゃったけど |風船だけはとっておくの |看護師さんがペンと紙をくれたから 絵も描いてる",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_090"] = "しばらくは暗い絵ばかりだったけど |いじめについて絵本を作ることを思いついてね… |写真も入れようかなって考えてるところ",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_110"] = "分かりにくかった? 写真といえばマックスでしょ |それとね 明日 家族がきたら退院できそうなんだ",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_130"] = "私を一生守るって勢いよ |今度のことがショックで たぶん後ろめたい気分なんだと思う |ブラックウェルのみんなからもたくさん手紙が来て びっくり |ダニエルに ジェファソン先生に… ビクトリアまで |それも うわべだけじゃない気がする",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_150"] = "なかなか難しいけどね。 この絵だって ほんと大変…",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_020"] = "ケイト!",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_040"] = "ケイト… いい… ケイトはなんにも悪くないんだよ |悪いのは他の人たち。ケイトに会えて 今 私がどれだけうれしいか… |ホントによかった。 聞いたら変かもしれないけど 調子どう?",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_060"] = "私だけじゃない。 ケイトにはもう たくさんの味方がいるんだよ",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_080"] = "ケイトの絵 好きだよ",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_100"] = "私にその本のための写真を撮ってほしい ってことかな",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_120"] = "みんな元気?",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_140"] = "うん。 人を信じることは大事だよ",
  ["Act_E4_4A_Beach_Boardwalk_Look01_Max_010"] = "ついさっきまで もう 1 つの世界で クロエとここにいたなんて…",
  ["Act_E4_4A_Beach_CHChloe_Look01_Max_010"] = "クロエは準備できてるみたい",
  ["Act_E4_4A_Beach_DeflatedBeachBall_Look01_Max_010"] = "かわいそうなビーチボール…",
  ["Act_E4_4A_Beach_DogPlate_Look01_Max_010"] = "ゴハンが出てる! ポンピドゥー元気なんだ。 よかった…",
  ["Act_E4_4A_Beach_EmptyBottles_Look01_Max_010"] = "フランクのビアガーデンへようこそ…",
  ["Act_E4_4A_Beach_FranksCorpse_Look01_Max_010"] = "フランクが死んじゃった… 信じらんない…",
  ["Act_E4_4A_Beach_Garbage_Look01_Max_010"] = "ちょっと たまにはゴミ出しなよ",
  ["Act_E4_4A_Beach_NoCampingSign_Look01_Max_010"] = "心配ご無用",
  ["Act_E4_4A_Beach_NoSwimmingSign_Look01_Max_010"] = "見張りもいないし 見つからないでしょ",
  ["Act_E4_4A_Beach_PanEstatesFlyer_Look01_Max_010"] = "土曜には元凶がなくなってるかもね",
  ["Act_E4_4A_Beach_Path_Look01_Max_010"] = "悪夢が始まった場所…",
  ["Act_E4_4A_Beach_Pompidou_Look01_Max_010"] = "そんな… ポンピドゥー… ごめんね…",
  ["Act_E4_4A_Beach_RVWindow01_Look01_Max_010"] = "だから きれいにしなよって… このネタもういいか",
  ["Act_E4_4A_Beach_RVWindow01_Look02_Max_010"] = "こんなに汚れてたら スモークいらないでしょ…",
  ["Act_E4_4A_Beach_RVWindow02_Look01_Max_010"] = "これじゃ 中がまったく見えないよ…",
  ["Act_E4_4A_Beach_ScriptedFrankDead_Max_010"] = "ウソでしょ… クロエがフランクを殺しちゃった… |このさき罪悪感でずっと苦しむことになる… |巻き戻せるのは私だけだ…",
  ["Act_E4_4A_Beach_ScriptedFrankHurt_Max_010"] = "もう! ケガだけで済んで まだよかったけど |フランクはこの先クロエに何をするか… |今ならまだ 変えることができる…",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_010"] = "フランクに会いに こんな所まで来ちゃったよ",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_030"] = "町を出るべきなのかも |でもクロエは置いてけない… これを片付けなきゃ",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_070"] = "深呼吸して フランクに会おう。 自分を信じて…",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_100"] = "フランクがメモをくれてよかった… レイチェルには彼の良さが見えてたんだね",
  ["Act_E4_4A_Beach_TableAndChair_Look01_Max_010"] = "ここで人生を考えつつ… お酒を飲む と",
  ["Act_E4_4A_Beach_Whales_Look01_Max_010"] = "残酷な姿だけど… やっぱりどこか威厳がある",
  ["Act_E4_4A_Beach_Whales_Look02_Max_010"] = "宇宙の法則とか分かんないけど きっとこの現象にも理由があるはず…",
  ["Act_E4_4A_Beach_Whales_Look03_Max_010"] = "これもきっと全部 竜巻と関係あるはず",
  ["Act_E4_4A_Beach_WildLifeSign_Look01_Max_010"] = "森が静か。 生き物の気配すらない… 鹿も",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_005"] = "ってことは 巻き戻したんだな? で? 何をどうすりゃいいんだ?",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_006"] = "ああ 不満だね。 でもしょうがない。 危なくなったら すぐ巻き戻せよ?",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_007"] = "お説教かよ。 いい子のマックスを見習えばいいんだな |最近はいい子でもないか…",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_008"] = "失礼な! … あたしだって 冷静な話し合いぐらいちゃんとできる",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_001"] = "よく聞いて… このままだと 交渉は絶対に失敗する…",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_002"] = "銃を捨てて。 不満なのは分かるけど…",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_003"] = "言葉に気をつけて。 そうしないと フランクを怒らせて バッドエンドだよ…",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_004"] = "とにかく慎重に… |フランクに協力してもらえるように… |何があっても怒らせないで",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_001"] = "いいだろう。 ひとまず休戦だ。 だが妙なことしたら… |俺の犬ひいたトラックの運転手みてえに 半殺しにしてやるからな",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_002"] = "別にどうってことねえよ。 動物がひでー扱い受けてんのは ほっとけなくてよ |ポンピドゥーもそんとき引き取った",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_003"] = "ポンピドゥーの前の飼い主は ろくにしつけてなかった |そいつが死んで 俺がしつけてやったんだ",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_004"] = "いいだろう。 ひとまず休戦だ |だが妙なことしたら 俺の犬がてめえらの頭 食いちぎるからな |ハッタリじゃねえぞ",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_007"] = "奇跡的に命は助かった。 てめえにはどうでもいいことだろ",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_008"] = "俺がさせねえよ… 犬は好きか?",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_015"] = "あんときの犯人はてめえらか… てめえらが犬を外に出したんだな? |ふざけやがって!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_016"] = "なんで名前知ってんだ…? 俺の車ん中 見たのか? |あんとき犬が外に出たのはてめえの仕業か! ふざけやがって!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_017"] = "俺がポンピドゥーを虐待してるとでも思ってんのか? 俺はあいつを助けたんだ!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_005"] = "犬がトラックに…? かわいそうに… その… 無事だったの?",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_006"] = "話がしたいだけ。 犬には何もしないよ",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_009"] = "いい飼い主に巡り会えて ポンピドゥーは幸せだね",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_010"] = "犬は大好きだよ。 闘犬を何匹も助けたんだってね。 立派だと思う",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_011"] = "犬 大好き。 フランクの犬は よくしつけられてて お利口だね",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_012"] = "この前 あなたの犬に骨をあげたら…",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_013"] = "うん ポンピドゥーはかわいいね",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_014"] = "犬を人殺しの道具にするなんて 虐待だよ",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_018"] = "待って! 誤解だから…!",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_001"] = "もういい 帰れ。 ムダ話につきあって損したぜ",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_002"] = "まったく よく言うぜ。 人に銃突きつけたのはどいつだ",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_003"] = "てめえ 人を銃で吹っ飛ばそうとしといて 調子いいこと抜かしてんじゃねえぞ!",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_004"] = "ようやく まともなこと言ったな… |いいか 本気で殺す気がねえなら 引き金なんか引かねえことだ |ま お前じゃハエも殺せねえだろうが",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_005"] = "慣れねえことはするもんじゃねえ。 あんなオモチャを大げさに両手で抱えて… |俺も銃 用意しとくんだったな",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_008"] = "ようやく まともなこと言ったな… |いいか 本気で殺す気がねえなら 銃なんか出さねえことだ |ま お前じゃハエも殺せねえだろうが",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_015"] = "俺がナイフしか持ってなかったことに感謝するんだな |でなきゃ今頃… そいつと仲よく 2 人でオダブツだったぜ…",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_016"] = "\"アジト\"だあ? 悪いが ガキの遊びにつきあってる暇はねえんだよ |大人を怒らすと痛い目見るぜ…",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_017"] = "冗談もたいがいにしとけよ? |引き金を引いといて なんともなかったからいいだと?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_006"] = "お願い… ケンカしにきたんじゃないの。 私たちだけじゃ どうにもならない",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_007"] = "それは… その… ごめんなさい |ここ最近バカなことしてばっかりだけど… |そのなかでも一番バカだったと思う…",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_009"] = "わ…分かってる… あのときだってほんとに撃つ気はなくて… ただ…",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_010"] = "それは… その… ごめんなさい |ここ最近バカなことしてばっかりだけど… |そのなかでも一番バカだったと思う…",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_011"] = "クロエがナイフで脅されてて 怖かったの |ああするしかなかった… |撃ちたくなかったよ",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_012"] = "そっちがクロエをナイフで脅したから 守ろうとしただけ",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_013"] = "私たちのアジトに 勝手に入ってくるのが悪いよ",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_014"] = "弾は入ってなかった。 なんともなかったでしょ?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_018"] = "ホントは 銃なんて見たくもないの。 だから… もう二度としない",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_019"] = "私はただ… あのときは… パニクッてて…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_001"] = "だろうな。 お前はその手のこととは無縁そうだ。 で 何を聞きたいんだ?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_002"] = "なんだか分からんが 聞くだけ聞いてやる。 フザけた話だったら承知しねえぞ",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_003"] = "そういうセリフは聞き飽きてるが… ウソってわけじゃなさそうだな",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_006"] = "なあんだそんなことかよ? もったいつけやがって! |ついでに車のキーもやろうか?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_007"] = "何言ってんだ? キーはこないだなくして カギをつけかえたばっかだ |お前 まさか何かしたんじゃねえだろうな…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_008"] = "てめえ 性懲りもなく俺を脅す気か?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_009"] = "分からないね! まともに相手すんのもアホらしい |だいたい その人を見下した態度が気にいらねえ…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_017"] = "\"少しだけ\"な 最初はみんなそう言う。 そこのクロエがいい例だ。 なあ?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_018"] = "これだからブラックウェルのガキどもは…! 平気で人にタカりやがる |厚かましい… こっちは商売なんだよ!",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_022"] = "人に銃突きつけといて 犬が怖えだと?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_023"] = "てめえらと俺じゃケンカにもならねえよ |フザけたこと抜かしたら 即帰ってもらうぜ",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_024"] = "なんだと? 人に銃突きつけたのはそっちじゃねえのかよ ああ? |やっぱりな てめえは信用ならねえ",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_025"] = "言っとくが こんなキャンピングカーでも俺の家だ |今度ひとの縄張りで偉そうに指図したら 承知しねえぞ |今回は借金返済に免じて許してやる。 さっさと用件を言え",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_026"] = "これで満足か? 用件を言え",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_027"] = "これだからブラックウェルのガキどもは…! |いいか 俺はてめえらの奴隷じゃねえ! 偉そうに指図してんじゃねえぞ!",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_004"] = "そんなこと頼みに来たんじゃない",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_005"] = "顧客の本名を… 教えてもらいたいの…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_010"] = "大事なことだから こうして直接頼みにきたの |フランクをだます理由もないし… |これはあなたのためでもあるんだよ",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_011"] = "フランク お願い… 迷惑かけてるのは分かってるけど… 重要なことなの",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_012"] = "キーなら もうもらったよ",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_013"] = "協力して。 さもないと…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_014"] = "なんで分からないの? 重要なことなの",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_015"] = "一刻を争う事態なの。 少しだけでいいから 協力して",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_016"] = "ち… 違う… 私はただ…",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_019"] = "フランク… 犬が怖くて集中できないの… ドア 閉めてくれる?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_020"] = "時間を作ってくれてありがとう |今日は… ケンカをしに来たわけじゃないの 話がしたいだけ |お願い 協力して",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_021"] = "フランク… この前のことがあるから お互い武器はナシにしたいの |ナイフとか持ってたら… 話が終わるまで 車に置いといてくれる?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_001"] = "レイチェル? まさかそれが本当の目的か?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_002"] = "なんでてめえが知ってんだよ? あの写真は俺の宝だ |あれを見りゃ いつでもレイチェルに会える",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_004"] = "レイチェルが消えて 俺は望みを失ったんだ…",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_006"] = "俺が何もできなかったのに てめえらに何ができる? |思い上がってんじゃねえぞ。 ガキの遊びにつきあう暇はねえ…",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_013"] = "偉そうな口利いてんじゃねえよ。 俺を誰だと思ってやがる |あんまり調子こいてんじゃねえぞ コラ",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_014"] = "「手紙を読んだ」だ…? |てめえ 車んなかの手紙を 勝手に読んだって言ってんのかコラ…!?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_015"] = "ひとの縄張りで偉そうに指図してんじゃねえ クソガキが",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_017"] = "正直 どうかなっちまいそうだよ |今頃どこにいんだか… せめて声だけでも聞ければ…",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_018"] = "バカにしやがって |てめえは信用できねえ… これ以上関わりたくもねえ。 失せな",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_005"] = "もう少しでレイチェルの居場所が分かりそうなの |そのためには どうしてもフランクの協力が必要で…",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_007"] = "フランク お願い… 力を貸して",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_008"] = "レイチェルは お気に入りの写真をフランクにあげたって言ってた |それぐらい フランクはレイチェルにとって大切な人だった |お願い 協力して",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_009"] = "フランクは誰よりもレイチェルと親しかった |レイチェルにとって特別な人だった。 だから力を貸して |最後の望みなの",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_010"] = "何を隠してるの? レイチェルを見つけたいなら 協力すべきでしょ?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_011"] = "レイチェルの手紙 読んだよ… フランクは特別な人だったんでしょ",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_012"] = "ブレスレットを持ってるってことは 何か隠してるってことでしょ? 話してよ",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_019"] = "レイチェルのために協力して。一刻を争うの",
  ["Cue_E4_4A_Beach_DogDial_ChloeBadChoice_Chloe_010"] = "落ち着けよ フランク。 あたしらはレイチェルを探したいだけなんだ",
  ["Cue_E4_4A_Beach_DogDial_ChloeBadChoice_Frank_010"] = "レイチェルはここにいねえ! |てめえら 何のつもりだ! 何をコソコソたくらんでやがる! |顧客の本名だ? ふざけたこと抜かしてんじゃねえぞ!",
  ["Cue_E4_4A_Beach_DogDial_ChloeGoodChoice_Chloe_010"] = "それより レイチェルの話だろ!",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_020"] = "人殺しだ…!",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_040"] = "死んで… 死んでるよ…!",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_060"] = "ああ… だ… だけど…",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_080"] = "フランク… 許して…",
  ["Cue_E4_4A_Beach_FrankDead_Max_010"] = "ウソ…!",
  ["Cue_E4_4A_Beach_FrankDead_Max_030"] = "クロエは悪くない… 正当防衛だよ…",
  ["Cue_E4_4A_Beach_FrankDead_Max_050"] = "ここであきらめるわけにはいかないよ… 顧客リストを探さなきゃ…",
  ["Cue_E4_4A_Beach_FrankDead_Max_070"] = "あった… 早く行こう…",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_020"] = "ああ…!",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_050"] = "早く!",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_110"] = "行くぞ",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_030"] = "てめえらどうかしてるぜ! なんのマネだ!",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_060"] = "いま渡してやっから! まずそいつをしまえよ! クソガキが…",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_070"] = "ほらよ。 とっとと失せろ… 二度とツラ見せんな",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_090"] = "必要ねえ… サツに来られると面倒だ…",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_010"] = "酒はどこだ! …取り出さねえと…!",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_020"] = "あんなガキに撃たれるなんて… 冗談じゃねえ",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_030"] = "ポンピドゥー…",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_040"] = "よし… 引っ張り出すぞ… 慎重にな…",
  ["Cue_E4_4A_Beach_FrankHurt_Knife_Max_010"] = "クロエ… フランクが…",
  ["Cue_E4_4A_Beach_FrankHurt_Max_010"] = "クロエ! フランクが…",
  ["Cue_E4_4A_Beach_FrankHurt_Max_040"] = "こ… 顧客リストを見せて",
  ["Cue_E4_4A_Beach_FrankHurt_Max_080"] = "救急車呼んだほうがいい?",
  ["Cue_E4_4A_Beach_FrankHurt_Max_100"] = "あ… うん…",
  ["Cue_E4_4A_Beach_GunDial_ChloeBadChoice_Chloe_010"] = "いい加減にしろよ! マックスは悪くない |先にナイフちらつかせたのは あんたのほうだろ!",
  ["Cue_E4_4A_Beach_GunDial_ChloeBadChoice_Chloe_020"] = "もう水に流してくれよ",
  ["Cue_E4_4A_Beach_GunDial_ChloeGoodChoice_Chloe_010"] = "マックスはウソついてない。 水に流してくれ。 頼む",
  ["Cue_E4_4A_Beach_GunDial_ChloeNoChoice_Chloe_010"] = "あんたがナイフ出したから… ビビッただけだ! |あのときは… 3 人ともどうかしてたんだって",
  ["Cue_E4_4A_Beach_GunDial_FrankBadChoice_Frank_010"] = "じゃあなんだ 悪いのは俺だってのか? |人をバカにすんのもいい加減にしろ |これだからブラックウェルのガキどもは… |もうがまんの限界だぜ…",
  ["Cue_E4_4A_Beach_Insertion_Chloe_020"] = "ああ。 今頃あいつらの家族 海の中で心配してるだろうな…",
  ["Cue_E4_4A_Beach_Insertion_Chloe_030"] = "よし… 待ってろよ フランク",
  ["Cue_E4_4A_Beach_Insertion_Chloe_050"] = "当てになんかしてないよ。 そのための銃だ。護身用だってば",
  ["Cue_E4_4A_Beach_Insertion_Chloe_070"] = "信用しろって",
  ["Cue_E4_4A_Beach_Insertion_Chloe_080"] = "銃がありゃ楽だったのに",
  ["Cue_E4_4A_Beach_Insertion_Chloe_100"] = "心配するな 脅しに使うだけだ。 それに うっかり殺したら 巻き戻しゃいい",
  ["Cue_E4_4A_Beach_Insertion_Chloe_120"] = "こんなの… ガキの頃は想像もつかなかったな",
  ["Cue_E4_4A_Beach_Insertion_Chloe_140"] = "それいいな! マックスとあたしと… レイチェルで",
  ["Cue_E4_4A_Beach_Insertion_Chloe_160"] = "ああ 分かってるよ",
  ["Cue_E4_4A_Beach_Insertion_Max_010"] = "砂浜のクジラたち… かわいそうだね…",
  ["Cue_E4_4A_Beach_Insertion_Max_040"] = "銃なんて必要ないでしょ? クロエ 私の力を当てにしちゃダメだってば",
  ["Cue_E4_4A_Beach_Insertion_Max_060"] = "不安だな…",
  ["Cue_E4_4A_Beach_Insertion_Max_090"] = "話し合いをするんでしょ 銃なんか必要ないって",
  ["Cue_E4_4A_Beach_Insertion_Max_110"] = "だから 私の力を当てにしちゃダメだってば",
  ["Cue_E4_4A_Beach_Insertion_Max_115"] = "言ったでしょ? いつ使えなくなっても おかしくないんだよ",
  ["Cue_E4_4A_Beach_Insertion_Max_130"] = "早く終わらせて クロエとポートランドに遊びに行きたい",
  ["Cue_E4_4A_Beach_Insertion_Max_150"] = "そうだよ。 だから バカなことはしないで |フランクに借金返して 顧客の本名を聞き出す。 それだけ",
  ["Cue_E4_4A_Beach_Insertion_Max_151"] = "そうだよ。 だから バカなことはしないで |フランクを説得して 顧客の本名を聞き出す。 それだけ",
  ["Cue_E4_4A_Beach_Insertion_Max_170"] = "よし 行こう",
  ["Cue_E4_4A_Beach_Money_Chloe_020"] = "待って… ちょっと聞きたいことがあるんだ",
  ["Cue_E4_4A_Beach_Money_Frank_010"] = "確かに。 さっさと返しゃいいものを。 返せねえなら借りねえことだ",
  ["Cue_E4_4A_Beach_Money_Frank_015"] = "じゃあ とっとと帰んな…",
  ["Cue_E4_4A_Beach_Money_Frank_030"] = "なんだお前 まだ懲りてねえのか?",
  ["Cue_E4_4A_Beach_Money_Frank_035"] = "帰れ",
  ["Cue_E4_4A_Beach_Money_Frank_040"] = "ったく わーったよ…",
  ["Cue_E4_4A_Beach_Money_Frank_045"] = "売りもんはやらねえぞ",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeBadChoice_Chloe_010"] = "よく言うよ そのガキどもにメシ食わしてもらってんだろ? ヤク売りつけてさ!",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeBadChoice_Frank_010"] = "黙って聞いてりゃ… 何様のつもりだ!? |説教なら教会で聞く。 調子こいてると ケツにナイフ突っ込むぞ!",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeGoodChoice_Chloe_010"] = "あたしは関係ないだろ!",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_010"] = "金は… まだ 用意できてない…",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_030"] = "会って直接言おうと思って…",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_050"] = "聞きたいことがあるんだ",
  ["Cue_E4_4A_Beach_NoMoney_Frank_020"] = "どういうことだ… さっきのメッセージはウソか?",
  ["Cue_E4_4A_Beach_NoMoney_Frank_040"] = "見え透いた芝居はよせ。 何が目的だ?",
  ["Cue_E4_4A_Beach_RVDoor_Chloe_020"] = "相棒だから",
  ["Cue_E4_4A_Beach_RVDoor_Frank_010"] = "なんだ… 1 人多いな",
  ["Cue_E4_4A_Beach_RVDoor_Frank_011"] = "なんで連れてきた",
  ["Cue_E4_4A_Beach_RVDoor_Frank_030"] = "ボディーガード気取りか… それで? 金は持ってきたんだろうな",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Chloe_050"] = "やめろ!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_010"] = "俺に指図するな!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_040"] = "放せ!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_080"] = "このクソアマ!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Max_020"] = "ちょっと…!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Max_070"] = "クロエ!",
  ["Cue_E4_4A_Beach_RageDog_Max_010"] = "クロエ!",
  ["Cue_E4_4A_Beach_RageGun_Chloe_040"] = "マックスから離れろ!",
  ["Cue_E4_4A_Beach_RageGun_Chloe_090"] = "違う… そんなつもりじゃ…",
  ["Cue_E4_4A_Beach_RageGun_Frank_020"] = "てめえ 偉そうに指図してんじゃねえぞ!",
  ["Cue_E4_4A_Beach_RageGun_Frank_050"] = "ポンピドゥー!",
  ["Cue_E4_4A_Beach_RageGun_Frank_070"] = "てめえよくも…!",
  ["Cue_E4_4A_Beach_RageGun_Max_010"] = "待ってフランク… 落ち着いて…!",
  ["Cue_E4_4A_Beach_RageGun_Max_060"] = "そんな…",
  ["Cue_E4_4A_Beach_RageGun_Max_080"] = "クロエ…",
  ["Cue_E4_4A_Beach_RageKnife_Frank_010"] = "脅しを本気にするヤツがあるかよ! クッソォー!",
  ["Cue_E4_4A_Beach_RageNoGun_Frank_010"] = "こんどこそ切り刻んでやるよ…!",
  ["Cue_E4_4A_Beach_RageRachel_Chloe_020"] = "黙れよ! レイチェルとあたしは 親友以上だった!  絶対あきらめない…",
  ["Cue_E4_4A_Beach_RageRachel_Frank_010"] = "てめえに何が分かる! もう手遅れだ!",
  ["Cue_E4_4A_Beach_RageRachel_Frank_030"] = "なんも分かってねえな! てめえのせいなんだよ! |俺からレイチェルを奪いやがってよ!",
  ["Cue_E4_4A_Beach_Success_Chloe_010"] = "あたしからもお願いするよ… 頼む… 顧客リストがいるんだ",
  ["Cue_E4_4A_Beach_Success_Chloe_060"] = "ホント助かるよ… ありがとな",
  ["Cue_E4_4A_Beach_Success_Frank_020"] = "どうせ他に当てはねえ。 少しでも望みがあんなら 信じてやってもいい",
  ["Cue_E4_4A_Beach_Success_Frank_030"] = "ついでに犬にケガさせた犯人も探してくれ",
  ["Cue_E4_4A_Beach_Success_Frank_040"] = "犬もお前らのこと気に入ってるようだしな",
  ["Cue_E4_4A_Beach_Success_Frank_070"] = "お前らに賭けてみるからよ… がんばれよ。 そいじゃな",
  ["Cue_E4_4A_Beach_Success_Max_050"] = "ありがとう…",
  ["Act_E4_5A_Corridor_BigFoot_Interact01_Max_010"] = "写真家なら 1 度はビッグフットを撮らないとね…",
  ["Act_E4_5A_Corridor_BigFoot_Look01_Max_010"] = "もし本当にビッグフットが見つかっても 全然驚かないよ",
  ["Act_E4_5A_Corridor_BigfootPoster_Look01_Max_010"] = "がんばれー",
  ["Act_E4_5A_Corridor_CHChloe_Look01_Max_010"] = "ネイサンを探る「鷹の目のクロエ」って感じ…",
  ["Act_E4_5A_Corridor_CatPicturesPoster_Look01_Max_010"] = "猫の写真を盗んで何するの?",
  ["Act_E4_5A_Corridor_CondomPoster_Look01_Max_010"] = "ローガンもこのポスターを見てれば…",
  ["Act_E4_5A_Corridor_DanielDrawings_Look01_Max_010"] = "最低。 ケイトの方は落書きされてないけど",
  ["Act_E4_5A_Corridor_DanielSlate_Look01_Max_010"] = "ケイトの一件の後でも イジメのことを誰も学んでない",
  ["Act_E4_5A_Corridor_Door109Slate_Interact01_Max_010"] = "たまにはからかってみようかな |ずっと誘ってくれてるんだし… |思い切って 成り行きに任せるのも大事だよね…",
  ["Act_E4_5A_Corridor_Door109Slate_Interact01_Max_020"] = "たまにはからかってみようかな |頑張って誘ってくれてるのに ドライブインも… 結局断っちゃったし… |うーん 深く考え過ぎ?",
  ["Act_E4_5A_Corridor_Door109Slate_Look01_Max_010"] = "オタクっぽいって思われたらやだな… |まあ ウォーレンもそうだし… |笑ってくれるよね?",
  ["Act_E4_5A_Corridor_Door109Slate_Look02_Max_020"] = "ウォーレンが変に誤解しないといいけど… ていうか友だちだし |うーん 悩むな",
  ["Act_E4_5A_Corridor_DormMap_Look01_Max_010"] = "寮の地図って誰が見るの? |とりあえず 106 と 108 じゃないのはわかった",
  ["Act_E4_5A_Corridor_EvanSlate_Look02_Max_020"] = "エバン… さすが。 独自の道を進んでるって感じで かっこいいな",
  ["Act_E4_5A_Corridor_GamerGuysPoster_Look01_Max_010"] = "最後のミーティングになるかも…",
  ["Act_E4_5A_Corridor_HaydenSlate_Look01_Max_010"] = "このニオイとゲームの音… ヘイデンってすぐ分かる…",
  ["Act_E4_5A_Corridor_LoganSlate_Look02_Max_020"] = "ケイトのことを気にかけてる男子もいるんだ",
  ["Act_E4_5A_Corridor_NathanDoor_Interact01_Max_010"] = "よし 開いたね",
  ["Act_E4_5A_Corridor_NathanSlate_Look01_Max_010"] = "ネイサンの部屋はきっとここだ",
  ["Act_E4_5A_Corridor_NathanSlate_Look02_Max_020"] = "何としてもケイトのかたきをうたなきゃ",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_010"] = "気をつけよう 敵の陣地にいるんだから",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_020"] = "ネイサン お願いだから帰ってこないで…",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_030"] = "男子寮へようこそ",
  ["Act_E4_5A_Corridor_ScriptedKate_Max_010"] = "助かるよケイト! 魔法の番号は 「111」 ね",
  ["Act_E4_5A_Corridor_ScriptedKate_Max_020"] = "あ ケイトからメッセージ! すぐに見なきゃ",
  ["Act_E4_5A_Corridor_ScriptedMajorChoice_Max_010"] = "はあー ウォーレン相当キレてた… 助かったけど 怖かったな…",
  ["Act_E4_5A_Corridor_ScriptedMajorChoice_Max_020"] = "ネイサンが殴られて当然のヤツだとしても… 暴力はよくないよね",
  ["Act_E4_5A_Corridor_ScriptedNathanDoor01_Max_010"] = "消去法でいくと ネイサンの部屋は 「111」 しかない",
  ["Act_E4_5A_Corridor_ScriptedObjective01_Max_010"] = "えーと 寮の地図がどこかにあるはず",
  ["Act_E4_5A_Corridor_ScriptedObjective01_Max_020"] = "早くしないと誰かに見つかっちゃう!",
  ["Act_E4_5A_Corridor_ScriptedObjective03_Max_010"] = "ずいぶん騒ぎを起こしちゃったな。 クロエとウォーレンを探そう",
  ["Act_E4_5A_Corridor_StopBullyingPoster_Look01_Max_010"] = "ケイトのこと考えちゃう…",
  ["Act_E4_5A_Corridor_ToiletDoor_Look01_Max_010"] = "とりあえず この人の携帯は触りたくないかな",
  ["Act_E4_5A_Corridor_ToiletPaper_Look01_Max_010"] = "トイレットペーパー戦争 勃発…",
  ["Act_E4_5A_Corridor_TrevorSlate_Look01_Max_010"] = "あらら… トレバ―と… デーナだ…",
  ["Act_E4_5A_Corridor_WarrenDoor_Look01_Max_010"] = "ひどい ネイサンのしわざだ… 痛い目に遭わないと わからないの?",
  ["Act_E4_5A_Corridor_WarrenSlate_Look01_Max_010"] = "ウォーレンの部屋! ホーキング博士を尊敬してるんだね",
  ["Act_E4_5A_Corridor_ZachSlate_Look01_Max_010"] = "コレ書いたの ザックかローガンだな… ホント男子ってのは",
  ["Act_E4_5A_NathanRoom_Bed_Look01_Max_010"] = "部屋がきれいなのは心が病んでるサインだって どっかで読んだ… |ネイサンの部屋はチリひとつ無い",
  ["Act_E4_5A_NathanRoom_BluRayCollection_Look01_Max_010"] = "うーん 暗い映画ばっかり…",
  ["Act_E4_5A_NathanRoom_BondagePoster_Look01_Max_010"] = "こういう趣味を追求してるわけだ",
  ["Act_E4_5A_NathanRoom_Book_Look01_Max_010"] = "本 1 冊で治ったら 誰も苦労しないよ",
  ["Act_E4_5A_NathanRoom_BrokenLamp_Look01_Max_010"] = "これきっと クロエが壊したランプだ…",
  ["Act_E4_5A_NathanRoom_Camera_Look01_Max_010"] = "6000 ドルはする 最新のモノクロカメラ… 金持ちめ",
  ["Act_E4_5A_NathanRoom_Computer_Look01_Max_010"] = "これも調べなきゃね",
  ["Act_E4_5A_NathanRoom_DeadBirdsPicture_Look01_Max_010"] = "すっごい気持ち悪いけど… 自分のスタイルがある",
  ["Act_E4_5A_NathanRoom_DogPicture_Look01_Max_010"] = "いやだ… ネイサンほんとにイカレてる",
  ["Act_E4_5A_NathanRoom_Drawer01_Look01_Max_010"] = "クロエらしいけど…",
  ["Act_E4_5A_NathanRoom_Drawer02_Look01_Max_010"] = "ウソでしょ… クロエ… |ひどいよ…",
  ["Act_E4_5A_NathanRoom_ExhibitionPoster_Look01_Max_010"] = "このショー おもしろそう。 こういうセンスもあるんだ",
  ["Act_E4_5A_NathanRoom_KatePicture_Look01_Max_010"] = "ケイトの部屋の前にあったのだ… でもなんで? 何考えてるの?",
  ["Act_E4_5A_NathanRoom_Lens_Look01_Max_010"] = "高い機材といえばビクトリアだと思ってたけど プレスコット家には勝てないね",
  ["Act_E4_5A_NathanRoom_Marks_Look01_Max_010"] = "床にあるのは何の跡だろう…?",
  ["Act_E4_5A_NathanRoom_MaxPhoto_Look01_Max_010"] = "やだ 私の自撮り写真 盗んでたんだ",
  ["Act_E4_5A_NathanRoom_Mp3Player_Interact01_Max_020"] = "クジラの歌? ネイサンの心を癒せるのは これだけなのかも…",
  ["Act_E4_5A_NathanRoom_Mp3Player_Look01_Max_010"] = "音楽かけようかな",
  ["Act_E4_5A_NathanRoom_NathanArt01_Look01_Max_010"] = "わあ いい写真じゃん… もっと写真に力を入れたらいいのに",
  ["Act_E4_5A_NathanRoom_NathanCellphone_Look01_Max_010"] = "こんなとこに… 携帯はもらっていくよ",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact01_Max_010"] = "パーティのことしか頭にないみたい… イヤな予感がする",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact02_Max_020"] = "最低。 絶対許せない… ケイトの分も仕返ししてあげるから",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact03_Max_030"] = "ひどいな… この父親が本当の問題かも",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact04_Max_040"] = "あの家にもまともな人はいるんだ… お姉さん 外国か…",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact05_Max_050"] = "へえ ネイサンがダイエット薬品ね… しかも強い薬",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact06_Max_060"] = "ちょっと… ウェルズ校長 ゴマすりすぎ",
  ["Act_E4_5A_NathanRoom_Pills_Look01_Max_010"] = "病院の薬も効いてないみたい",
  ["Act_E4_5A_NathanRoom_PornMagazine_Look01_Max_010"] = "男子の部屋と言えば… 典型的だね",
  ["Act_E4_5A_NathanRoom_Projector_Look01_Max_010"] = "こんなハイテクのプロジェクタがあったら最高だろうな…",
  ["Act_E4_5A_NathanRoom_ScriptedGoToChloe_Max_010"] = "携帯も手に入ったし… ネイサンが戻って来ないうちに クロエに見せよう",
  ["Act_E4_5A_NathanRoom_ScriptedGoToChloe_Max_020"] = "クロエが待ってる。 携帯も手に入れたし ネイサンが戻る前に行かなきゃ",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_010"] = "ここは敵の本拠地… 何も見落とさないよう くまなく探さないと!",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_020"] = "この部屋… ネイサンの心の中みたい",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_030"] = "何もかも持ってるのに 安らぐ場所がない",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_040"] = "見つかったら巻き戻せるけど 毎回うまくいくかな…",
  ["Act_E4_5A_NathanRoom_ScriptedLightChange_Max_010"] = "この部屋にも光を…!",
  ["Act_E4_5A_NathanRoom_ScriptedObjective01_Max_010"] = "ネイサンの携帯とか 何か手がかりを探さなきゃ",
  ["Act_E4_5A_NathanRoom_Sofa_Interact01_Max_020"] = "何か隠してるはず…",
  ["Act_E4_5A_NathanRoom_Sofa_Look01_Max_010"] = "このソファ 前と後ろに何度も動かした跡がある…",
  ["Act_E4_5A_NathanRoom_StuffAboutFather01_Look01_Max_010"] = "今や皮肉にしか思えないけど… ずっと持ってるなんて かわいいとこもあるんだ",
  ["Act_E4_5A_NathanRoom_StuffAboutFather02_Look01_Max_010"] = "これって クロエを撃とうとした銃だ… 誰かからのプレゼント…?",
  ["Act_E4_5A_NathanRoom_StuffAboutFather03_Look01_Max_010"] = "不機嫌そうな顔… この父親とその服じゃしょうがないか…",
  ["Act_E4_5A_NathanRoom_ThreePosters_Look01_Max_010"] = "ひどい趣味だな… ついていけないよ",
  ["Cue_E4_5A_Corridor_CHChloe_QuickPhase_Chloe_001"] = "何してんだよ! 早く!",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_010"] = "泊まってくれてありがと",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_030"] = "ケイトは かわいそうだね…",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_050"] = "トレバーは優しいね… そういうとこが好き",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_020"] = "門限なんてクソくらえだ! ガキじゃねえっつの!",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_040"] = "ホントだよな。 家族もきっと悲しんでるよ…",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_060"] = "俺もデーナが好き",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_010"] = "男女別か。 つまんねー",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_030"] = "確かに",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_050"] = "あたしに任せときな",
  ["Cue_E4_5A_Corridor_Insertion_Max_020"] = "隣の部屋にネイサンがいるより ずっとマシだよ",
  ["Cue_E4_5A_Corridor_Insertion_Max_040"] = "ここにいて。 ネイサンが戻ってきたら すぐに知らせて",
  ["Cue_E4_5A_Corridor_Insertion_Max_060"] = "さて ネイサンの部屋はどこかな…",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_010"] = "なっさけねえな!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_020"] = "信じらんねえ",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_030"] = "俺も入れてくんないかな…",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_040"] = "おい マジかよ",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_050"] = "ああ… 俺ならそこでびしっとタックル決めるのによ…",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_060"] = "「見ろよ なんだあのボールさばきは!」",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_070"] = "あああ… そこだ!!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_080"] = "うほほほーほー!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_090"] = "行け! 行け! 行け! いいぞ! いいぞ!  あああっ…",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_100"] = "あー…  お おおおおー! …",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_110"] = "よーしキャッチしろよ そこで落としたら許さねえ",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_120"] = "うっしゃ!… おおお… そうこなくっちゃ!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Chloe_060"] = "早く行くぞ!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Chloe_090"] = "お似合いのツラだぜ",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Max_040"] = "もういいよ! ねえ… 落ちついて…",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Max_100"] = "クロエ!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Nathan_030"] = "やめ… ろよ…|やめ…| やめてくれ!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Nathan_050"] = "やめてくれ…  悪かった…",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Warren_020"] = "人を痛めつけるのが好きか? |マックスとか? ケイトとか? 俺とかを? なあ? |このクズ野郎!",
  ["Cue_E4_5A_Corridor_NathanBack_Chloe_020"] = "やったじゃん。 これであいつも終わりだな",
  ["Cue_E4_5A_Corridor_NathanBack_Max_010"] = "これを見て…",
  ["Cue_E4_5A_Corridor_NathanBack_Max_070"] = "ちょっと 落ち着いてよ",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_050"] = "俺の寮で何やってる!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_051"] = "コソコソかぎまわりやがって!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_080"] = "何だと こら",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_090"] = "うっ!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_091"] = "そこをどきやがれ!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_120"] = "てめえ そんなに死にたいのか!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_130"] = "やめろこのボケ!",
  ["Cue_E4_5A_Corridor_NathanBack_RTC_Chloe_002"] = "ああ よかった やっと戻ってきたか。 で 何を見つけた?",
  ["Cue_E4_5A_Corridor_NathanBack_RTC_Max_004"] = "なんかキレイだけど… 気味の悪い部屋だった",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Chloe_040"] = "行こう。 早く!",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Max_010"] = "ウォーレン やめて! もういいよ",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Nathan_015"] = "うう… 痛え。 なんだよお前ら その目つきは!? |お前も… お前も… 全員死ね!",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Nathan_030"] = "覚えてろ すぐに親父が来るからな! てめえらは もう おしまいだ!",
  ["Cue_E4_5A_Corridor_NathanBack_Warren_110"] = "マックス! さがってろ",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_010"] = "ちっくしょー… マジ痛え…",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_020"] = "顔の骨折れたかも…",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_030"] = "なんで俺がこんな目に…  なんで…",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_010"] = "よーし 行け…",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_020"] = "さっさと倒れろよ タコ怪獣…",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_030"] = "あと 1 回やれば 何とか…",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_040"] = "レベルアップだ!",
  ["Act_E4_5B_CampusB_BirdGrave_Look01_Max_010"] = "うーん こんなところに石なんてあったっけ? なんだか怖いな…",
  ["Act_E4_5B_CampusB_BirdGrave_Look02_Max_020"] = "サミュエルに石のことを聞けてよかった。 鳥さん どうか安らかに…",
  ["Act_E4_5B_CampusB_BirdGrave_PHOTO_Max_030"] = "後世のために 1 枚",
  ["Act_E4_5B_CampusB_BrokenWindow_Look01_Max_010"] = "アリッサを助けて残った物… 壊れた窓",
  ["Act_E4_5B_CampusB_CHBrooke_Look01_Max_010"] = "ウォーレンと映画に行くことになって うれしそう",
  ["Act_E4_5B_CampusB_CHBrooke_Look02_Max_020"] = "私がウォーレンと映画に行くの イヤなんだろうな",
  ["Act_E4_5B_CampusB_CHChloe_Look01_Max_010"] = "ジャスティンと仲いいね",
  ["Act_E4_5B_CampusB_CHDaniel_Look01_Max_010"] = "ダニエル元気ない。 どうしたのかな",
  ["Act_E4_5B_CampusB_CHGrant_Look01_Max_010"] = "グラント先生 熱心に話を聞いてる",
  ["Act_E4_5B_CampusB_CHJustin_Look01_Max_010"] = "クロエのこと好きなの バレバレだよ",
  ["Act_E4_5B_CampusB_CHSamuel_Look01_Max_010"] = "サミュエルが一人ぼっちじゃないの なんかうれしい",
  ["Act_E4_5B_CampusB_CHSquirrelFemale_Look01_Max_010"] = "お友だちがいたら 一緒に撮ってあげる",
  ["Act_E4_5B_CampusB_CHSquirrelFemale_Look02_Max_020"] = "ふふ おなかいっぱい食べてね",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look01_Max_010"] = "動物パパラッチのマックスから 隠れられると思った?",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look02_Max_020"] = "ほら こっちにおいで!",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look03_Max_030"] = "私に撮ってほしいの? しょうがないな",
  ["Act_E4_5B_CampusB_CHSquirrelMale_PHOTO_Max_040"] = "ほら撮るよ 笑って",
  ["Act_E4_5B_CampusB_CHZachary_Look01_Max_010"] = "ザック 次が最後の試合じゃないといいね…",
  ["Act_E4_5B_CampusB_KateAltar_Look01_Max_010"] = "ああ… ケイト…",
  ["Act_E4_5B_CampusB_PermitPanel_Look01_Max_010"] = "ふう ウェルズ校長のお金をクロエに盗ませなくてよかったよ…",
  ["Act_E4_5B_CampusB_PermitPanel_Look02_Max_020"] = "やだ… クロエが盗んだの バリアフリー資金のお金だったんだ… |私たちヒドいね",
  ["Act_E4_5B_CampusB_PrincipalQuarterDoor_Look01_Max_010"] = "こないだのウェルズ校長 すごい酔ってたな",
  ["Act_E4_5B_CampusB_ScriptedObjective01_Max_010"] = "ネイサンがどこにいるか調べなきゃ",
  ["Act_E4_5B_CampusB_ScriptedObjective01_Max_020"] = "えーと 誰に聞こう…",
  ["Act_E4_5B_CampusB_ScriptedObjective02_Max_010"] = "よし ネイサンは校内にいない! クロエのとこに行こう",
  ["Act_E4_5B_CampusB_Tobanga_Look01_Max_010"] = "トバンガが何か教えてくれたりしないよね…",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_010"] = "ウォーレンがマックスを映画に誘うなんて…",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_020"] = "「猿の惑星」が見たいなら私に言えばいいのに…",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_030"] = "私のほうから誘うべきだった…",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_010"] = "ウォーレンと映画に行くこと マックス怒ってるかな",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_020"] = "こんな 1 週間の後じゃ 週末は学校を離れたいよ",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_030"] = "ウォーレンも 本当はマックスと行きたいんじゃないかな",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_010"] = "まあ いつもどおり |そういえば… ケイトを助けたのすごかったね。 大丈夫?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_019"] = "ケイトのこともあったし あまり元気とは言えない。 マックスは大丈夫?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_021"] = "ほんとに大丈夫なの?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_023"] = "グラント先生はやっとあきらめて許可をくれたよ |でもウォーレンと映画に行くんならドローンなんかで遊ぶヒマないでしょ",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_024"] = "グラント先生がやっと折れて許可をくれてね。 飛ばしてみれば? |その間に私 ウォーレンと映画の時間について相談するから",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_027"] = "するどいね マックス。じゃ 悪いけど… 私 ドローンの調整するから",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_028"] = "猿鑑賞を楽しんできたら? 悪いけど私 ドローンの調整しなきゃ",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_029"] = "ウォーレンが新しい車を買ったって。 「新しい」は語弊があるけど |だから私 週末はがっつりドライブに行く気満々",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_030"] = "ニューバーグのドライブイン・シアター 好きなんだ |ダサいけど すごく楽しくて… ウォーレンみたい",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_034"] = "ウォーレンに聞けば? 一緒に映画とか行く仲なんでしょ",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_035"] = "さあ… ウォーレンと映画に行くことで頭がいっぱいで",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_040"] = "しょうがないな。 ネイサンなら さっき私のドローンを追い回してたよ |ヘンなやつでしょ |あとボルテックスのパーティに来るかって聞かれた |行くんだけどさ。 あとは知らない",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_041"] = "なに ウォーレンじゃ不足なの? ふーん |ネイサンならさっきすごい剣幕で校外に出てったよ… |じゃ デートがんばってね",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_042"] = "しょうがないな。 ネイサンなら さっき私のドローンを追い回してたよ |ヘンなやつでしょ |あとボルテックスのパーティに来るかって聞かれた |行くんだけどさ。 あとは知らない",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_043"] = "ネイサンなら今朝校外に出ていったよ。 いつにも増してカリカリしてた |私なら今は近づかないね",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_044"] = "丁度週末に ウォーレンと 2 人で仮説を立ててみる予定",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_045"] = "この異常現象の原因が判ったらノーベル賞ものだね |でもグラント先生もお手上げみたい",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_046"] = "まあ オタク同士の絆ってとこ? |私もウォーレンもまだ うまい説明を思いつかないんだけどね… |この異常現象",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_001"] = "ブルック 調子はどう",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_020"] = "ブルック 何度もごめん",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_022"] = "こんなとき気晴らしにドローンを飛ばせたらいいな",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_025"] = "なにそれ。 私がウォーレンと映画を観に行くならドローンは貸さないってこと?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_026"] = "いいかげんにしてよ。 意地悪はやめて |友達と映画を観に行くだけのことじゃない…",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_031"] = "楽しそうだね。 週末をウォーレンと一緒にドライブで過ごすわけか…",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_032"] = "えっ… ウォーレンから映画に誘われたの? あ そう… いいんじゃない?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_033"] = "ネイサンを探してるんだけど 見なかった?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_036"] = "停学になったとはいえ キャンパスにはいると思うんだけど…",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_037"] = "平日だから ここらへんにいるはずなんだけど",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_038"] = "引っかかる言い方だな… でも今はネイサンを探してるの",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_039"] = "やめてよブルック… |とにかく ネイサンは停学になったとはいえ |まだキャンパスにいると思うんだけど…",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_047"] = "変な日食とか打ち上げられたクジラとか もう頭がごちゃごちゃしてきたんだ… |ブルックなら何か知ってるかなって",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_048"] = "それいいかもね。 2 人とも頭いいんだし… 私よりは",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_049"] = "ウォーレンに誘われたの?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_050"] = "もう行かなきゃ。 じゃ またね",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeQP_Brooke_001"] = "そう じゃあね",
  ["Cue_E4_5B_CampusB_CHChloe_ChloeQP_Chloe_001"] = "収穫あったら教えて",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_028"] = "はは 僕は写真の才能が… 根本的に欠けてるみたいだ |アーティスト落第だよ…",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_030"] = "少し希望がわいてきたよ。 マックスは… いい人だね",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_032"] = "スケッチをやめる? 無理な話だね |そりゃ 君からカメラを取りあげるようなものだ |やっぱり僕は向いてないんだ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_034"] = "一理あるけど 授業の課題は選べないときもある |いっそ写真を描いてしまいたいぐらいだ… やっぱり僕は向いてないんだ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_036"] = "「レンズペン」かあ… なるほどね。それなら僕にもできそうだ…",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_039"] = "かまわないよ 気分転換になる",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_043"] = "どうせ歓迎されないよ。 ダンスより ロッカーに詰め込まれるほうが得意だしね",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_045"] = "それもそうだ。 ただのお飾りクラブだしね |君の言うとおり 行くまでもないや",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_046"] = "いいけど 絶対ついて来てくれよ |くそ 僕がパーティに行くなんて それこそ世も末だ! |あのさ やっぱ行く代わりに… |いや やっぱり… 行くよ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_048"] = "ああ とうとう停学くらったんだって?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_049"] = "最近?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_052"] = "なんか すごい怒りながら 外に出て行ったよ。 ついさっき",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_053"] = "さっきジェファソン先生がネイサンと話していたよ。 僕は見ていただけだけど |これ以上イヤな奴にかかわり合いたくないし",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_055"] = "僕は自分から人に話しかけないから… | でも 一度ブルックとその話になったことはある |ケイトのこと ずいぶん気にしてた",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_056"] = "僕は自分から人に話しかけないから… | でも 一度ブルックとその話になったことはある |マックスがすごく勇敢だったって言ってたよ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_059"] = "授業をボイコットして 抗議するべきかな |でも この学校じゃ無理… いや 僕なら…",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_060"] = "そうだね。 ケイトほど優しくて誠実な人はいないのに… |僕はともかく ケイトに手を出したのは許せない",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_062"] = "いつもはスケッチブックの中 限定だけどね",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_027"] = "ダニエル。 なんか元気ないね。 大丈夫?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_029"] = "アーティストといっても色々あるでしょ。 写真家だけじゃない |私を描いてくれたスケッチ すごくいいもん |そっちの才能あるよ 絶対",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_031"] = "まだあきらめることないよ。 しばらく スケッチの代わりに写真を撮ってみたら? |習慣にするのが大事だ ってジェファソン先生が言ってた",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_033"] = "題材を変えてみたらどうかな… 得意分野とかに…",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_035"] = "そうだ 絵を描くつもりで撮ってみれば? |スケッチしたいと感じたものを撮るの |カメラを「レンズペン」だと思って",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_037"] = "ダニエル 何度もジャマしてごめん",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_040"] = "じゃ またね。 元気出して",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_041"] = "今夜の「世界の終わり」パーティには行く?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_042"] = "ボルテックス・クラブなんて… わざわざ行くほどの所じゃないよ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_044"] = "だからこそ行く意味があるんだよ |ケイトのためにもいじめグループに立ち向かわなきゃ |そう思ってるのは一人じゃない",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_047"] = "ところで ネイサンを見なかった?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_050"] = "うん でも校内にはいるはずなんだ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_051"] = "うん 今日とか",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_054"] = "ケイトのことについて 誰かと話した?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_057"] = "分かるよ… 怒りすらわいてくる…",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_058"] = "正しいと思うことをしただけだよ |でも… 気持ちはうれしいな |それより大事なのは ケイトへのいたわりと… |黒幕への報いだよ",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_061"] = "ダニエルもかっこいいとこあるじゃない",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP1_Daniel_001"] = "はげましてくれてありがとう。 ボルテックス・クラブなんてくそくらえだ!",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP2_Daniel_002"] = "パーティに行く勇気をくれて ほんとにありがとう。 またあとで!",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP3_Daniel_001"] = "ああマックスか。ごめん まだ落ち込んでてさ。人と話をする気分じゃないんだ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_002"] = "あら うわさをすれば何とやらね |学校から監視カメラを追い出せたのは あなたたち生徒のおかげよ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_015"] = "あら うわさをすれば何とやらね |といっても 署名運動の話じゃないから安心して",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_017"] = "授業には出てないわね… 停学中だし。 あなたたち 友だちだったの?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_018"] = "まあ意外。 ネイサンと友だちだったのね",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_027"] = "「友だち」の定義にもよるけど… |でも イジメより友情が増えることに期待してるわ。 特に今はね…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_028"] = "それくらいで怒らないわ。 あなたでも悪態はつくのね",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_029"] = "難しい子よね。 プレスコット家の出だけに周りの期待も大きい |それが重すぎるのね。 先日の事件がいい証拠よ… |校長の処分は正しいわ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_030"] = "ひどく怒った顔でキャンパスを出ていったのは見たわ |正直 最近の様子は普通じゃない。 まあ 私が言うまでもないかしら",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_031"] = "言わないでおこうかと思ったけど ネイサンなら校外に飛び出していったわよ |色々あった後だし 会わないほうがよさそうだけど…|あなたはとても賢明な子だから あとは分かるわね",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_032"] = "私だって彼を助けようとしたんだけど… 逆効果だったみたいね |ネイサンなら ひどく不機嫌そうにキャンパスから出ていったわ |会わなくてよかったかも",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_033"] = "知りたいのは居場所だけじゃないみたいね |でも 今 ネイサンと顔を合わせるのは得策じゃないわ。 よく考えなさい",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_034"] = "ネイサンならさっき校外に飛び出していったわ |でも どうやら知りたいのは居場所だけじゃないみたいね",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_036"] = "それが分かるぐらいなら 今ごろノーベル科学賞を取ってるわ |あの日食についてさえまだ考えがまとまらないの |まして雪やクジラは…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_039"] = "私はNASAに友達がいるけど そこでも| あれが起きた原因に説明が付けられないとしたら…  |そのときは一大事かもね…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_040"] = "いいえ 私たちの知識が足りないだけのこと |理由が分からないからといって 現実は変わりはしません",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_042"] = "サミュエルと同じことを言うのね。 あなたが来る前 ちょうどその話をしていたの ||この星は変わっていく。 でもそれは神秘じゃない |自然現象よ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_045"] = "海岸線は後退しているし |海には汚染物質が毎日流れこんでる |野生動物が死ぬ原因としては充分よ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_046"] = "私も伝承やら予言やら そういう話は好きよ |でも 今のところ「世界の終わり」の前兆らしきものといえば |例のパーティポスターぐらいね",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_047"] = "他に思いあたることでも?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_050"] = "アルカディア・ベイにあるのはミミズの穴ぐらいよ |カオス理論は まあ置いといて… |もしタイムトラベルができるなら 私も体験したいわ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_051"] = "あのトーテムは 誰が建てたのかも分からないのよ |どうせ漁師が海で拾ってきたんでしょうけど。 でも… 確かに霊力は感じる",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_053"] = "ブラッドベリの「雷のような音」を読んだことはある? |ネタバレはよすけど 恐竜や蝶が出てくる話よ |時間は糸のようなもの。 むやみに触れたら すべてがほどけてしまう",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_056"] = "またいつでも話に来なさい",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_058"] = "いらっしゃい マックス",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_059"] = "マックス… かわいそうに 大変だったわね… |ケイトは誰よりも心優しい子だったのに… どうしてあんなことに… |あなたもカウンセラーとお話しする?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_060"] = "監視カメラがなくとも マックスがいるもの。 あなたは素晴らしいことをしたわ |次はケイトが必要なケアを受けられるようにしないと |あなたもカウンセラーとお話しをする?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_063"] = "それはよかった。 一人で抱え込むのだけはやめなさい |ケイトは相談に来なかったから… 私は気づいてあげられなかった…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_064"] = "今週は確かにいろいろあった |でも 私も 他の先生たちも いじめを撲滅するまで あきらめないわ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_066"] = "まずボルテックス・クラブは活動停止 そしてあのパーティは延期するべきね |ケイトの事件の後で 無神経にもほどがあるでしょう",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_069"] = "関係はない… でも 会員には特権がある |学校のスポンサーの息子なら なおさらね |私はそんなもの 認めないけど",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_070"] = "レイモンド・ウェルズ校長はこの学校を経営危機から救った人ですよ |人のことをすぐ決めつけるのは賢明じゃないわ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_072"] = "言いたいことは分かるわ |でも あなたやウォーレンが 才能を伸ばせる場所にしたい |斜に構えた若者も多いけど あなたの将来は楽しみにしてるから",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_001"] = "グラント先生",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_016"] = "ネイサンを探してるんですが 見かけませんでしたか",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_019"] = "先生なら知ってるかと思って…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_020"] = "全っ然。 ただネイサンには… えー… 聞きたいことがあって",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_021"] = "か 課題でペアになっただけです |あの人に友だちがいること自体 信じられない…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_022"] = "あんなクズ… あ すみません",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_023"] = "えっと… ネイサンは見かけてないんですね?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_024"] = "ええ… 誰かがなんとかしないと…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_025"] = "そうですね…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_026"] = "はい… えっと… それで ネイサンの居場所なんですけど",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_035"] = "最近 不思議な現象が続いてますけど 先生なら原因 分かりますか?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_037"] = "何か 科学的な説明はあるはず… ですよね?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_038"] = "科学を超越してるのでは…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_041"] = "世界ってそんなに確かなものでしょうか… |なんだか目の前で変わっていこうとしてるみたい",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_043"] = "ここの動物たちがどんどん死んでいるのも?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_044"] = "じゃ… 何かの予言とかと関わりがあるとは思わないんですか?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_048"] = "ワームホールやカオス理論や… タイムトラベルとか…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_049"] = "もしかしたら トバンガがすべてを知っているのかも…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_052"] = "過去を変えたいと思いますか?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_054"] = "監視カメラでケイトを救えたとは思えません",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_055"] = "すみません先生 私もう行かなきゃ… 失礼します",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_057"] = "グラント先生",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_061"] = "あ… いえ大丈夫です 先生。親友や両親が聞いてくれますから… 今のとこ",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_062"] = "ケアが必要なのはこの学校のほうです |何かとても良くないことが起こってるんです |気づいてますよね?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_065"] = "ケイトはボルテックス・クラブのパーティで クスリを盛られ… |そのうえ 動画の件でイジメられたんです… |手に負えませんよ…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_067"] = "ボルテックス・クラブはプレスコット家と関係あるんですか? |あれだけの資金が どこから出てるのか…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_068"] = "なんで校長先生は止めないんですか |正直いって 何が起きようと どうでもいいって思ってるみたいで…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_071"] = "そうですよね… |ただ この学校が 来る前に想像してたのとはずいぶん違うので…",
  ["Cue_E4_5B_CampusB_CHGrant_GrantQP_Grant_001"] = "また今度話しましょう",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_016"] = "まあ なんとかやってます。 サミュエルは?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_018"] = "お邪魔だったらすみません サミュエル",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_020"] = "謎は増えていく一方です…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_023"] = "アルカディア・ベイの動物たちに 何か異変が起きてるみたいですよね…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_024"] = "アルカディア・ベイに何が起きているのか 分からないことばかりなんです",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_026"] = "すみません 私もう行かなきゃ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_029"] = "ネイサンを見かけませんでしたか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_030"] = "あまり残念そうじゃないですね",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_031"] = "当然の報いです。 これでも軽いぐらい",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_032"] = "へえ ネイサンがよっぽど嫌いなんですね。 どうして?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_033"] = "ネイサンについて何を知ってるんですか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_038"] = "どういうことですか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_039"] = "えっと… それだけですか? |この学校の秘密に詳しいから 何か聞けると思ったのに…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_042"] = "その… ケイトが…  いなくなってから 学校が悲しみ一色の気がして…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_043"] = "実はケイトのお見舞いに行ってきたんです。  だいぶ元気になったみたい",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_049"] = "サミュエルは ケイトがいじめを受けてたことを知ってたんですか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_050"] = "私が何をしたとかじゃなく…  その… |人間の運命はひとりひとり決まっているのかも…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_052"] = "私もそう思う…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_054"] = "デイビッド・マドセンと話したことは?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_057"] = "デイビッドらしいね",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_059"] = "どうしてそう思うんです?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_060"] = "なんかイヤだな…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_063"] = "一番物事が見えてるのは サミュエルかも…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_065"] = "鳥がたくさん死んでいますよね…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_067"] = "そんなことしていいんですか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_068"] = "どうしてあんなことに…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_071"] = "何かの予兆としか思えない…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_073"] = "打ち上げられたクジラたち どうしてああなっちゃったのかな…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_074"] = "リスだけは まだ元気に走り回ってるみたいですね",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_077"] = "サミュエルがいれば大丈夫ですよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_078"] = "何かの環境災害だと思いますか? それとも…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_079"] = "私もよく泣きたくなります… 自分が無力すぎて…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_084"] = "え… ホントに?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_085"] = "レイチェル・アンバーがすべてのカギを握ってる気がして…  見つけなきゃ…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_086"] = "私 科学の才能がないから… どうしてあの日食が起きたのか分からないんです",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_087"] = "科学は得意じゃないけど ボルテックス・クラブよりはマシです",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_091"] = "すぐにみんな気づきます",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_093"] = "なぜ そう思うんですか?  教えてくれませんか",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_094"] = "始まりって 何の?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_098"] = "生きてると思いますか?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_099"] = "そうなのかも… どこに行っちゃったんだろう",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_102"] = "でも…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_015"] = "大丈夫かい マックス。 大変だったよね… いろいろ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_017"] = "悲しいし困惑しているよ この町の皆と同じく |君も解けない謎の山を抱えてるのかい…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_019"] = "ちっとも邪魔ではないよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_021"] = "僕でよければ相談に乗るよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_022"] = "ああ かわいそうに… 何が原因にしろ 動物たちにはなすすべもないんだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_025"] = "その答えを求める姿勢… グラント先生が君を気に入るのも納得だよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_027"] = "いや そもそも彼は停学中だしね",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_028"] = "見たくもないね",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_034"] = "彼は周りを傷つけるからね。 当然さ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_035"] = "決めつはよくないけど… ネイサンはここにいるべきじゃない |いや… あるいはいるべきなのか…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_036"] = "サミュエルは人が好きだ。 嫌う理由がないかぎり。 彼にはある。",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_037"] = "彼のことは知れば知るほど 後悔する",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_040"] = "君の目的は見当がつく。 だが役に立つようなことは知らないんだ… |力になれずにすまない…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_041"] = "マックス 僕にできることなんて限られてる… |できるのは 気をつけろと忠告するだけだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_044"] = "ああ… ブラックウェルは変わってしまった |だが 皆が顔をそむけたときも 君だけは手をさしのべた",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_045"] = "君のおかげだ。たいした救出劇だったよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_048"] = "僕をバカにするのはいいけど… ケイトにはやめるよう言ったんだ… |いじめは悪だよ マックス…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_051"] = "思うに… 人はそうして無数の運命を生きるんだろう |ケイトの信仰とは違うかもしれないが… それもまた運命だ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_053"] = "君は本当にケイトのことを想ってるんだね… |マックスのような子が… もっといればよかったのに…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_055"] = "彼が謹慎処分になってからは一度も。 どのみち 僕からは話しかけない |聞くだけだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_056"] = "マドセン「が」話すんだ。 僕は聞くだけ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_058"] = "彼は… 物は見えても 人が見えないのさ |でも… 君のことは例外かもしれない",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_061"] = "彼も… 君も カメラを通して世界を見るから",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_062"] = "でも… あれだけ監視カメラを集めても… |結局マドセンはなんにも見えちゃいないんだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_064"] = "い いやあ… 僕はただ 物事を… 違う角度で見てるだけ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_066"] = "もう何羽も埋めてやったよ… トバンガの根元に",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_069"] = "鳥たちの魂が旅立てば分かるだろう。 証明にはならないが…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_070"] = "たぶん空が汚れすぎたというだけじゃない。 風の中になにか悪いものがいる…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_072"] = "それが宿命なら… どうしようもないさ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_075"] = "父が漁師でね 一緒に海に出るとクジラの歌が聞こえたものだ… |でも今は… 泣き声が聞こえる",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_076"] = "うん。  でも リスまでどうかなったら…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_080"] = "エサを食べる時だけは平和なのさ |実によく食べるよ |そういえば そろそろエサをやる時間だった",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_081"] = "いや… 原因は誰かにある… 誰かがすべてを引き起こしているんだ…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_082"] = "いやいや… 君は無力なんかじゃないよ マックス",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_083"] = "君とアルカディア・ベイは 時と潮で結ばれている… |次は 僕から君に答えを求めに行こう",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_088"] = "見つかることを望んでいないかも…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_089"] = "さっきグラント先生にも言ったけど 科学で説明できないものはある… |先生の気を悪くするつもりはないんだけど… |でも これはほんの始まりだよ…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_090"] = "ああ… レイチェルも あのクラブの闇に気づいていた",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_092"] = "ボルテックスに飲み込まれてはいけないよ マックス… |抜け出すんだ… 時が味方についてるうちに…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_095"] = "ただ目を開けばいい… そうすれば 兆しが見えるはずだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_096"] = "終わりのないものだよ… 時にも終わりがないように…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_097"] = "アルカディア・ベイに大きな何かが近づいてくる… |マックス いやな予感がするんだ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_100"] = "彼女は僕たちの心に生き続ける… それだけでも 十分なんだよ",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_101"] = "見つける者がいるとすれば それは君だ。 僕の夢が告げている…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_103"] = "マックス 信じた道を進むんだ |そうすれば君の探しているものは見つかるだろう… |レイチェルも待っているよ…",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelQP_Samuel_001"] = "人はみな 風の前の塵に同じ",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_010"] = "ジャスティン! 超ひさしぶりじゃん!",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_030"] = "それどころじゃなくてさあ…",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_050"] = "まあまあ",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_070"] = "手がかりナシ… いまんとこな",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_090"] = "笑い上戸だから",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_110"] = "言えてる。 んじゃ またな",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_020"] = "最近ぜんぜん遊んでくれねーじゃん",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_040"] = "授業も宿題もねえくせに… よく言うねー",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_060"] = "レイチェル 見つかりそう?",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_080"] = "スケボーですっ転んで レイチェルに笑われたなー",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_100"] = "ああ… 笑わせ上手だしな",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_120"] = "たまには 顔出せよな",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_010"] = "僕には写真の才能がないことはたしかだな",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_020"] = "やっぱり絵に専念しよう…",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_030"] = "先生のような才能があったらな…",
  ["Cue_E4_5B_CampusB_Drone_Max_010"] = "ありがと",
  ["Cue_E4_5B_CampusB_Extraction_Chloe_020"] = "ジェファソン先生かっこいいしな",
  ["Cue_E4_5B_CampusB_Extraction_Max_010"] = "任務完了…|ここに クロエと一緒に通えたら 最高なのに",
  ["Cue_E4_5B_CampusB_Extraction_Max_030"] = "もう… クロエのバカ。 ほら 早く行くよ",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_TeenBoy02_020"] = "お前に言われたくねえ!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_TeenBoy02_040"] = "レーザーバックに勝つぞ!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_010"] = "ボールを落とすなよ!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_030"] = "試合で本気出す!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_050"] = "ビッグフット 最強!",
  ["Cue_E4_5B_CampusB_GrantCallsMax_IGE_Grant_010"] = "マックス 署名運動に協力ありがとうね!",
  ["Cue_E4_5B_CampusB_GrantCallsMax_IGE_Grant_020"] = "元気そうね マックス",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_040"] = "ども",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_060"] = "いろいろありまして。 詳しいことは… 校長が知ってるかと",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_240"] = "あたしが引っ張っていきますよ! 先生と踊りたいし",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_260"] = "また今夜!",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_270"] = "うん アリだな…",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_290"] = "そりゃあ… 今夜の\"作戦\"だよ…",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_310"] = "なんだよ ヤキモチ焼くなって!",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_330"] = "はいはい。 ちょっとジャスティンにあいさつしてくる。 久しぶりだし",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_010"] = "おっと マックスじゃないか",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_050"] = "よろしく。  こんな\"イケてる\"子が うちの生徒じゃないとは…",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_100"] = "マックス… 大丈夫かい?",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_110"] = "なるほど",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_140"] = "ここは刑務所じゃないんだ。 気にすることはない",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_170"] = "人間 生きていれば いろいろあるものさ",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_190"] = "僕もそろそろ \"イベント\"の準備をしないと |今夜のパーティで「日常ヒーロー」コンテストの優勝者を発表する |君たちも来るね? |マックスにも応募してもらいたかったが しかたない |無理強いはできないからね",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_220"] = "君は友だち思いの優しい生徒だ。 それに これからチャンスはいくらでもある |今後は積極的に作品を発表すること",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_250"] = "ダンスは勘弁してくれ。 老いぼれに恥を欠かせる気かい? |教師の面目は保たせてくれよ。 それじゃ",
  ["Cue_E4_5B_CampusB_Insertion_Max_020"] = "ああ… ジェファソン先生。 こんにちは",
  ["Cue_E4_5B_CampusB_Insertion_Max_030"] = "えっと… 彼女は 友だちのクロエ",
  ["Cue_E4_5B_CampusB_Insertion_Max_130"] = "停学になったのに学校に来てると… なんか気まずくて",
  ["Cue_E4_5B_CampusB_Insertion_Max_150"] = "似たようなものかも…",
  ["Cue_E4_5B_CampusB_Insertion_Max_160"] = "いろいろあったので… その… なんだか 落ち着かなくて…",
  ["Cue_E4_5B_CampusB_Insertion_Max_180"] = "それにしても \"イベント\"が多すぎです…",
  ["Cue_E4_5B_CampusB_Insertion_Max_200"] = "先生… 私のこと… 恨んでませんか…?",
  ["Cue_E4_5B_CampusB_Insertion_Max_210"] = "ちょっと後悔してます… でも写真に集中できなくて… 言い訳ですけど…",
  ["Cue_E4_5B_CampusB_Insertion_Max_230"] = "分かりました。 パーティには必ず行きます",
  ["Cue_E4_5B_CampusB_Insertion_Max_280"] = "ちょっと! 何考えてんの?",
  ["Cue_E4_5B_CampusB_Insertion_Max_300"] = "もう…",
  ["Cue_E4_5B_CampusB_Insertion_Max_320"] = "いい加減にしてよね…",
  ["Cue_E4_5B_CampusB_Insertion_Max_340"] = "うん いってらっしゃい",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_010"] = "リスたちがいないとさびしいな…",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_020"] = "空が何かを警告しようとしている…",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_030"] = "そろそろ落書きを消しに行くか…",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_020"] = "異常気象ね。 それにしてもこんなのありえないわ",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_040"] = "科学者としては 興味深いわ。 私個人としては やはり不安ね",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_060"] = "ケイトのこともあるしね…",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_010"] = "今日だけで鳥たちの死体の山がいくつできたことか… ああ",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_030"] = "何もかもが変わろうとしている",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_050"] = "アルカディア・ベイも不安がっている。 天気といい… 動物といい…",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_070"] = "もっと周りを注意深く 観察しなければ…",
  ["Cue_E4_5B_CampusB_Skater_IGE_TeenBoy01_010"] = "グラインドいくぜ!",
  ["Cue_E4_5B_CampusB_Skater_IGE_TeenBoy01_020"] = "おい そろそろ 4 時 20 分じゃね?",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_010"] = "しかし… ネイサン フルボッコだったな…",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_030"] = "次はフランクだな",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_070"] = "金を匂わせれば 即レスだ",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_080"] = "ほらな。 今すぐ来いって",
  ["Cue_E4_5C_CampusA_Extraction_Max_020"] = "うん ちょっと 怖かったね…",
  ["Cue_E4_5C_CampusA_Extraction_Max_040"] = "犬のことバレてないかな…",
  ["Cue_E4_5C_CampusA_Extraction_Max_050"] = "あの犬も いるかな…",
  ["Cue_E4_5C_CampusA_Extraction_Max_060"] = "連絡取れるの?",
  ["Cue_E4_5C_CampusA_Extraction_Max_090"] = "じゃあ さっそく行こう",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_030"] = "ネイサンを叩きのめしてくれたじゃん。 あんた やるね",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_050"] = "ネイサンに頭突きくらわせたろ。 やるじゃん",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_100"] = "これはあたしとマックスとで片を付けるよ。 ありがとな",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_170"] = "あいつ マックスにベタぼれじゃん",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_010"] = "なんていうかびっくりしたよ… ウォーレン… |さっきは その… ありがとう",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_070"] = "ウォーレンは全然違うよ",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_090"] = "警察はだめ。 今はまだ。 だから ウォーレンは… その…",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_120"] = "だったら 寮に戻って 嵐に関する情報を集めてくれると助かる",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_121"] = "それじゃ ネイサンの父親のこと できるかぎり調べて…",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_140"] = "ありがとう ウォーレン。 ホントに…|また電話するね",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_160"] = "うん。 頼もしい",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_180"] = "やっぱり…?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_020"] = "何が?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_040"] = "どうかな。 さすがにやりすぎたよ… あれじゃネイサンだ",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_060"] = "どうかな。あやうく完全にキレるところだった… まるでネイサンだ",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_080"] = "ありがとう。 これからどうするんだ? |俺もついてったほうがいいだろ… |いつまた乱闘騒ぎになるか分かんないしさ |それとも警察を呼ぶ?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_110"] = "そうか… 俺にできることはある?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_130"] = "分かった。 季節外れの雪と日食もそうだけど 最近はきな臭いことが多いな",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_150"] = "約束だぞ。 今なら何でもこいって気分だ",
  ["Act_E4_6A_Corridor_Digicode_Fail_Max_010"] = "うーん これじゃない",
