  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_030"] = "ネイサンの次のターゲットはビクトリア… 教えてあげるべき?",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_040"] = "ネイサンはボルテックスの顔なんだから 絶対ここにいるはず",
