  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_080"] = "ダメだ… VIP ラウンジに入るには 他の方法を考えなきゃ",
  ["Act_E4_8B_SwimPool_ScriptedPhoto_Max_010"] = "今はそんな気分じゃないけど… おもしろい写真になりそう",
