  ["Act_E4_8B_VIP_CHVictoria_Look02_Max_010"] = "思ったよりうまく話せたな。 私の話 信じてくれたよね… 多分",
  ["Act_E4_8B_VIP_CHVictoria_Look03_Max_010"] = "私の話 全然信じてくれなかった… 私 努力したのに…",
  ["Act_E4_8B_VIP_CHVictoria_Look04_Max_010"] = "忠告した方が良かったかな… ネイサンが本当に狙ってるかもしれないのに…",
  ["Act_E4_8B_VIP_CHZachary_Max_010"] = "ザック ジュリエットを傷つけたら 絶対許さないからね",
  ["Act_E4_8B_VIP_DrunkGirl_Max_010"] = "酔い潰れてるのに 誰も介抱してない… 誰も何も学んでないんだ",
  ["Act_E4_8B_VIP_Graffiti01_Look01_Max_010"] = "ああ すべてを壊して台無しにしてやりたい…",
  ["Act_E4_8B_VIP_Graffiti02_Look01_Max_010"] = "ビクトリアと取り巻きのしわざだ",
  ["Act_E4_8B_VIP_Pipe_Look01_Max_010"] = "もう… 勘弁してよ",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_010"] = "その革のソファ 本物なの?",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_020"] = "こんなので自分は特別って思うんだろな",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_030"] = "レイチェルはボルテックスなんか 嫌いだったと思う",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_040"] = "もう! このパーティ 何もかもが下品で無神経",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_050"] = "プレスコットの手のひらの上で 好きなだけ踊りなよ",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_010"] = "ビクトリアは… 好きじゃないけど… ネイサンのことは忠告すべきだったかも…",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_020"] = "忠告はしたものの… ビクトリアが私の方を信じるわけないか…",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_030"] = "ビクトリアと私にも望みがあるのかも… 忠告してよかった。 無事でいてね",
  ["Act_E4_8B_VIP_ScriptedObjective_Max_010"] = "ネイサンがどこにも見当たらない… 一体どこにいるの? クロエと合流しなきゃ",
  ["Act_E4_8B_VIP_ScriptedObjective_Max_020"] = "ウォーレンに殴られて ネイサンは部屋にこもってるのかも |クロエと寮に行ってみよう",
  ["Act_E4_8B_VIP_ZenVIP_Max_010"] = "ケイトも… レイチェルも死んだ。 人殺しクラブへようこそ",
  ["Act_E4_8B_VIP_ZenVIP_Max_015"] = "ケイトは自殺未遂 レイチェルは…死んだ。 人殺しクラブへようこそ",
  ["Act_E4_8B_VIP_ZenVIP_Max_020"] = "セレブ気取りでいい気になって 他人のことなんてどうでもいい…",
  ["Act_E4_8B_VIP_ZenVIP_Max_030"] = "もし今 竜巻が来てくれたら 私 ただ座って見てるよ",
  ["Act_E4_8B_VIP_ZenVIP_Max_040"] = "でもクロエをほっとくわけにはいかない",
  ["Act_E4_8B_VIP_ZenVIP_Max_050"] = "こんな気持ち嫌だ… 怒りと悲しみしかない…",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_001"] = "ステラ!",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_003"] = "ううん いい。 ところでネイサンは来てる?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_005"] = "どうしてそんなに嫌ってるの? |当然ではあるんだけど ちょっと理由が聞きたくて",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_007"] = "誰に聞かれたの?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_009"] = "そう… ところで どうしてここにいるの? |ボルテックス・クラブに興味があったなんて意外",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_011"] = "誰に頼まれたの?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_013"] = "クラブの様子はどう? なにか変わったことはない?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_015"] = "そんなことないよ |ステラは頭もいいし 誠実だし すごく頑張ってると思う |きっといつか成功するよ",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_017"] = "ちょっとね… ネイサンを探さないといけないの |それと 彼に会ってもあんまり近づかないでね",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_002"] = "「世界の終わり」へようこそ。 荷物があったら預かるけど?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_004"] = "来てないよ。 見たくもないけど |っていうか さっきもネイサンのことを聞かれたばっかりなんだけど",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_006"] = "乱暴者だし ウォーレンに怪我させたし… それにあいつの目 見たことある? |濁ってギラギラしてるの。 気持ち悪い",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_008"] = "青い髪の パンクっぽい女の子 |レイチェル・アンバーのポスターを貼って回ってた子だよ |ごめんね 私ここの仕事で忙しいから",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_010"] = "ただのバイトだよ",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_012"] = "ジェファソン先生が声をかけてくれたの |バイト代と奨学金だけじゃ足りなくて… |私 要領悪いしさ…",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_014"] = "別に。 誰もケイトのことなんて気にしてない |こんなパーティ中止にすればよかったのに |私がイケてないからそう思うだけかな",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_016"] = "ありがとう |そう言ってくれると嬉しいけど… ねえ どうしたの? 真剣な顔して",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_019"] = "もちろん。 どうせここで仕事してるだけだし |もしネイサンが来たらメールで教えるよ",
  ["Cue_E4_8B_Cloakroom_CHStella_Quickphase_Stella_001"] = "まだネイサンは来てないよ。 来たら教えるから",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_Stella_010"] = "もう 服だらけでイヤになっちゃう",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_Stella_030"] = "それに 偉そうなヤツらばっかだしさ",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_TeenFemale04_020"] = "確かにねー",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_TeenFemale04_040"] = "そりゃあ それが目的で来てるわけだから…",
  ["Cue_E4_8B_Cloakroom_Stella02_IGE_Stella_010"] = "コートと荷物は こちらにどうぞ",
  ["Cue_E4_8B_Cloakroom_Stella02_IGE_Stella_020"] = "いえ 猫画像が入ったタブレットは知らないよ…",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_001"] = "あれー マックスじゃん |クソつまらねえパーティに ようやく救世主登場だ |楽しんでる?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_003"] = "他に行く場所なんてどこもねえからさー。 だってよ |デーナも来てるし… まあ 俺とじゃないけど |だから クソつまんねえとも言えるわけですよ",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_005"] = "どうせ VIP ラウンジで ボルテックソ連中と騒いでるんだろ |マジで気に食わねえ ホント… 特にネイサン |あの野郎 そのうち絶対やらかすぜ",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_008"] = "格好つけてクールでいようと思ったのにさ |あいつらが一緒にいんの見たら なんか泣けちまって",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_011"] = "ああ さっきちょうど レイチェルとクロエのことを考えててさ… |あの 2 人がここにいてくれりゃよかったのに |レイチェルがいるとさ ビクトリアのやつ黙っちまうんだ",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_013"] = "なあ ちょっと今日変じゃねえか? なんかえらい余裕ない感じだし |鈍感な俺でも分かるよ |何かあったのか? とりあえず… 一服いっとく?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_015"] = "さすがマックス いいこと言うねー。 確かに ここにいても気が滅入るだけだ |居場所もねえしさ いっちょスケボーでもやってくるか",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_002"] = "なんかだいぶ できあがってるみたいだけど つまんなそうだね |そもそも どうして来たの?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_004"] = "ところで… ネイサンを見てない?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_006"] = "きっとね。 だから今日はネイサンに近づいちゃダメ。 他の人にも伝えて",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_007"] = "デーナとトレバ―が一緒にいるの キツイよね",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_009"] = "誰だってそうなるよ。 わざわざ むし返すようなこと言ってゴメンね… |でも ジャスティンは優しいから きっとそのうちいい人が見つかると思う |大丈夫だよ",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_010"] = "レイチェル・アンバーもいないしね…",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_012"] = "へえ。 私もそれ見てみたかったな",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_014"] = "う… ううん 大丈夫 |それより もう行かないと |ジャスティンも 外の空気に当たってきたほうがいいよ",
  ["Cue_E4_8B_MenToilets_CHJustin_Quickphase_Justin_001"] = "マジですぐ帰るって。 もう少し空気が落ち着いたらさ",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_Alyssa_010"] = "ちょっと ふざけないでよ もう!",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_TeenBoy01_007"] = "いや むしろ成功じゃね?",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_TeenBoy02_006"] = "やっべー やっちまった!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_020"] = "え 何",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_030"] = "また?",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_040"] = "うわっ!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_050"] = "まただよ! マックスは私の守護天使だね 間違いない |本当に何度もありがとう!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_060"] = "前もマックスのおかげで ひどい目に遭わずに済んだんだよね |ありがと マックス",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_070"] = "危なかった ありがとう! いつもマックスがいればいいのにな",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Max_010"] = "アリッサ 危ないよ!",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_002"] = "無様にプールに落ちた姿を見て それ聞く? |にしても マックスが警告してくれないなんて珍しいね",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_003"] = "無様にプールに落ちた姿を見て それ聞く? |前みたいにマックスが警告してくれると思っちゃダメだね",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_004"] = "無様にプールに落ちた姿を見て それ聞く? |それにしても ひどい目に遭うときはいつもマックスが近くにいるよね… |言ってくれればいいのに",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Max_001"] = "アリッサ! ちょっと大丈夫?",
  ["Cue_E4_8B_Pool_CHAlyssa_Quickphase_Alyssa_001"] = "さっきはありがとう。 おかげでこんなパーティでも楽しめてるよ",
  ["Cue_E4_8B_Pool_CHAlyssa_Quickphase_Alyssa_002"] = "ああ 今ちょっと話す気分じゃないの |あのアホどものせいで全身ずぶ濡れなんだから",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_001"] = "ここで会うなんて 驚いたよ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_003"] = "あ 何? 今度は警告しにきたわけじゃないの? ちょっと身構えちゃったよ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_005"] = "まあね。 私はウォーレンが来るし 気分が晴れるかと思って来たんだけど |ケイトのこと考えると ちょっとね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_007"] = "私は とにかくケイトがまた絵を描けるのが嬉しいよ |おばさんも 珍しく親身になってるし… それはよかったと思う",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_009"] = "すでに みんな ケイトのことなんて気にしてないみたいだし |新しい事件でも起きれば 動画のことも誰も思い出さなくなるって",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_011"] = "なにか知ってるんだね。 顔を見れば分かるよ |説明しなくてもいいけど 手伝えることがあったら言って |今度はあたしが助ける番",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_019"] = "VIP ラウンジじゃないかな |…「VIP」 って! 高級クラブかって感じ!",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_021"] = "マックスがいれば 怖いものなんてないよ。 じゃあね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_023"] = "そうかも。 私はさ 今週かなりキツかったし |みんなが集まってるとこで気晴らししたかったんだ… |嫌いなやつらばっかだけど",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_025"] = "殴られると思ってるんじゃない? 実際 殴ってやったほうがいいかもね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_027"] = "あの子のことはよく知らないんだけど… 無事だといいね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_029"] = "マックス なんだか余裕なさそうだけど疲れてる? |ケイトのことで自分も大変だったんだから |私のことも何度も助けてくれたし",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_031"] = "マックスはスーパーヒーローだよ。 いつも私を助けてくれるし |ロバート・フロストの詩みたい",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_033"] = "いいけど 語りはヘタだからね |「遠い遠い先の日に 私は深く息をつきながら語るだろう |森の中で道が二手に分かれていたことを |そして 踏み固められていないほうの道を選んだことを |その選択が全てを変えたことを」",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_035"] = "引かれなくて安心した。 いつもありがとうね |みんながマックスみたいだったら ここももっと良くなるのに… |いつか そうなるといいな",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_037"] = "なんだか訳ありって感じだね… でも分かった 約束するよ。 じゃあね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_002"] = "ねえ アリッサ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_004"] = "ケイトが目の前で自殺したっていうのに こんな大勢パーティに来るなんて",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_006"] = "ケイトが飛び降りるところだったっていうのにパーティを開くなんて |みんなケイトが死ななかったからパーティができるって喜んでるのかな",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_008"] = "あの動画 削除されてた |誰かがよそにアップしないといいんだけど… |期待できないかな",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_010"] = "私 ケイトの仇を討たないといけない。 こんなこと二度と起きちゃダメだよ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_012"] = "ネイサンを探してるんだけど どこにいるか知らない?",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_020"] = "ありがとう。 アリッサ 気をつけてね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_022"] = "うん なんていうか… こんなパーティに出るなんて きっと最初で最後だよね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_024"] = "アリッサってビクトリアに絡まれないよね。 私とか… ケイトとかと違って",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_026"] = "レイチェルもボルテックス・クラブを嫌ってたのかな",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_028"] = "ああ… うん。 じゃあ またね アリッサ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_030"] = "それにしてもよかった またアリッサを助けることができて",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_032"] = "その詩 聞かせてくれる?",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_034"] = "ありがとう アリッサ。 今の私にぴったりだよ",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_036"] = "その詩のこと聞きたいけど 急いでるから… 次会えた… 会ったら 聞かせてね",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_038"] = "ごめんね 私 えっと… もう行かないと。 またね アリッサ",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_002"] = "マックス? まさかこんなところで会うとは思わなかった",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_004"] = "私は見てないよ。 あんなやつ わざわざ会いたいとも思わないし |あいつも クラブも大嫌い",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_006"] = "課題もなくて退屈だし ちょっと待ち合わせにね",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_008"] = "そうなったら 私もせいせいするんだけど",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_010"] = "さっき外に行ったよ |あとで彼と一緒にドライブインデートのプランを考えることになってるの |ウォーレンがね まずはディナーに行きたいって |いいデートになりそうでしょ",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_013"] = "ありがとう。 デートの話とか 自分勝手だとは思うんだけどね… |ケイトのこととか 異常気象とかあるときに…",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_014"] = "私に聞く? マックスのほうが仲良いでしょ",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_016"] = "分かってるんだけど… 私 上手くいかない事があると ついピリピリしちゃって… |自分勝手だね。 マックスと大違い",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_017"] = "ううん ダニエルと話してたから… |週末にポートランド美術館に行こうって誘われたの",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_019"] = "まあ 私は科学のほうが専門なんだけど |それしか取り柄のない女って思われるのもあれだしさ…",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_020"] = "ううん。 でも あとで一緒にデートのプランを考えることになってるの |今はポートランド美術館に行こうってダニエルと話してた",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_022"] = "まあ 私は科学のほうが専門なんだけど |それしか取り柄のない女って思われるのもあれだしさ…",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_024"] = "どうしたの 悟りでも開いたみたい。雪と日食の影響で 変な力に目覚めたとか? |今なら空でも飛べるんじゃない",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_026"] = "もしあったら 文字通り 「世界の終わり」を確信してたよ",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_028"] = "そんなものかな? アルカディア・ベイを守って悪と戦ったりできればいいのにね",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_030"] = "またね。 来週 一緒にドローン飛ばそう",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_001"] = "ブルックじゃない",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_003"] = "私も。 ところでネイサンを探してるんだけど ブルック…",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_005"] = "じゃあ どうしてここに?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_007"] = "私も。 このパーティでボルテックス・クラブの歴史もおしまいになればいいのに",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_009"] = "ウォーレンには会った?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_011"] = "うん すごく素敵。 よかったね |ブルックとウォーレンが楽しそうにしてると 私も嬉しいよ",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_015"] = "やめてよ |確かに映画に誘われたりしたけど そういうのじゃないから |私 ブルックとは友達でいたいのに",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_018"] = "そうなんだ 面白そうだね。 ダニエルって美術館とか詳しそうだし",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_021"] = "いいね。 ダニエルも気晴らしを必要としてる感じだったし |美術館とか詳しそう",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_023"] = "そんなことないよ |ブルックは自分に正直でいようとしてるだけ。 みんなそうだって",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_025"] = "ドローンじゃあるまいし… |ところで 月が 2 つ浮かんでる空なんて今までに見たことある?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_027"] = "超能力があっても いいことばかりじゃないと思うよ |「大いなる力には 大いなる偽りが伴う」みたいな",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_029"] = "まあね… じゃ またね ブルック",
  ["Cue_E4_8B_Pool_CHBrooke_Quickphase_Brooke_001"] = "来週の話はまたあとでね",
  ["Cue_E4_8B_Pool_CHBrooke_Quickphase_Brooke_002"] = "話はまたあとでね。 彼を待ってるから",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_002"] = "マックス 見てくれよ! |君に言われたおかげで こんなパーティなんかに来ちゃったよ",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_004"] = "いや ここに来てからずっとブルックと一緒だったから… 大丈夫? |思いつめたような顔してるけど",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_006"] = "極秘任務遂行中って感じだ",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_008"] = "まあ ゴタゴタは日常茶飯事だもんね",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_010"] = "ん? まあ僕とブルックはここにいるから いつでもおいでよ",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_011"] = "よく分かんないけど 気分転換が必要そうだね |今度ブルックとポートランドに行くんだけど 一緒にどう? 大勢のほうが楽しいし",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_013"] = "いつか美術館で盛大にお披露目してみせるよ。 じゃあね",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_001"] = "ダニエル",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_003"] = "よかった ダニエルがその気になってくれて |ところで ネイサン・プレスコットを見かけなかった?",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_005"] = "うん… ちょっとパーティって気分じゃなくて",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_007"] = "大丈夫。 いろいろありすぎて疲れてるだけ",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_009"] = "うん でも終わりにしなきゃ。 レイチェルのためにも",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_012"] = "ありがとう。 私 今は大事な用があるからこれで… |がんばってね。きっと立派なアーティストになれるよ",
  ["Cue_E4_8B_Pool_CHDaniel_Quickphase_Daniel_001"] = "ちょっとトイレに行くところなんだ。 またあとでね",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_002"] = "マックス! やっと気を許せる人に会えたよ!",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_004"] = "いやあ ここの連中とは付き合いにくくて… |ええと それでどうしてネイサンを?",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_006"] = "またケイトみたいなことが…?",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_008"] = "本当に? ただごとじゃなさそうな雰囲気だぜ。 ネイサンに何かされた?",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_009"] = "ちなみに ネイサンなら昼間見たよ |顔に怪我してたな。 やっとバチが当たったんだ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_011"] = "俺 ネイサンはいつか痛い目に遭えばいいと思ってるんだよ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_013"] = "マジかよ! すげえな ウォーレン! |こうなったら あとはあの一家ごと 町から追い出すだけだ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_015"] = "俺は「ボルテックス・カルト」って呼んでる |ドレスコードだの VIP だの 何様のつもりだよ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_017"] = "あのオヤジとは 試合で一度会ったよ。 すげえムカつく野郎 |この親にしてこの子ありってやつ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_019"] = "こっちこそ。 俺 ケイトの件以来 マックスのこと尊敬してんだ。 またな",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_001"] = "ルーク 久しぶり",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_003"] = "ネイサンを探してて…",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_005"] = "いや その… 何となくイヤな予感がするだけ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_007"] = "大した用じゃないの",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_010"] = "実はね ウォーレンがネイサンをボコボコにブッ飛ばしてくれたんだ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_012"] = "実はね ウォーレンがネイサンに強烈な頭突きを決めてくれたんだ",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_014"] = "難しそうだね。 プレスコットが町とボルテックス・クラブを牛耳ってるうちは…",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_016"] = "むしろショーン・プレスコットは私たちを追い出したいんじゃない…? |それともパン・エステートに詰め込む気かも",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_018"] = "分かるよ。 じゃあ 私もう行かないと。 ありがとう 話 聞いてくれて",
  ["Cue_E4_8B_Pool_CHLuke_Quickphase_Luke_001"] = "俺 やっぱりここは性に合わないや",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_010"] = "なんでビクトリア?",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_020"] = "ブー!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_030"] = "ビクトリアはないでしょ!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_040"] = "調子にのらないでよ!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_TeenMale01_010"] = "冗談じゃねえよ! 審査やりなおせよ",
  ["Cue_E4_8B_SwimPool_BooingVictoria_TeenMale01_020"] = "おいおい!",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_010"] = "こんなにアニメについて語れるなんて",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_030"] = "ウォーレンもそうなの。 そういうところが好きで…",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_050"] = "うん でも私もそうだから",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_020"] = "僕は守備範囲が広いからね",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_040"] = "あいつは科学専門でしょ?",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_060"] = "僕は SF なら好きだけど…",
  ["Cue_E4_8B_SwimPool_Brooke_IGE_Brooke_010"] = "ドローンがないと退屈",
  ["Cue_E4_8B_SwimPool_Brooke_IGE_Brooke_020"] = "結局 このパーティの趣旨ってなんなわけ?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_010"] = "おいおい どうなってんだよ!?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_020"] = "ちょっと待てって おい誰が曲止めたんだ?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_030"] = "おい あんた! あんただよ! なにしてくれちゃってんだ!?",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Dana_010"] = "私のパパより下手じゃない!",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Dana_030"] = "すごいすごい! 今度はいいじゃん!",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Trevor_020"] = "よし それじゃこいつはどうだ?",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Trevor_040"] = "じゃあ今度はポッピンだ",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_010"] = "もういい。 結局ビクトリアとは一生分かり合えないよ",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_030"] = "分かったから ネイサンはどこ?",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_050"] = "いや 別に… 大したことじゃないよ",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_070"] = "じゃあね…",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_020"] = "何とでも言えばいいわ。 どうせ私に嫉妬してるだけでしょ |あなたのダサい自撮りと私の作品じゃ 比べようがないものね",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_040"] = "はい? なんで知りたいの?",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_060"] = "何それ? ネイサンなら見てないけど。 それじゃ",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenBoy_010"] = "早く曲鳴らしてくれよ! ドラムがねえと! バスドラムだよ! 聞かせてくれよ早く! |ああもう パーティに来てんだからさ! ヘビーなビートが必要なんだよ!",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_010"] = "えーっ!?",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_020"] = "お酒どこ?",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_030"] = "この歌いいじゃん!",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_040"] = "マルシア! マルシア!",
  ["Cue_E4_8B_SwimPool_GirlTalkMax_IGE_TeenGirl03_010"] = "マックス 意外なとこで会うね… でもこういう場所に来るのもいいと思うよ",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_010"] = "なあなあ もっとお話ししようぜー",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_020"] = "なんかクラクラするなー これ俺だけー?",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_030"] = "ダメだ もうつぶれそう… なあなあ 君らは平気?",
  ["Cue_E4_8B_SwimPool_JeffArrive_Chloe_100"] = "行くぞ マックス",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_010"] = "マックス 来てたのか",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_030"] = "2 人とも何かあったのか? 思いつめた表情をしてるが",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_050"] = "いつネイサンと友だちになったんだ? |彼とは午後に会ったきりだよ |かなり興奮してたな。 ケイトの一件以来 |まあ その… ずっとあんな感じだが",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_070"] = "またあとで話そう。 これからコンテストの優勝者を発表しなきゃいけないんだ |君も参加してくれればよかったんだがな |今後に期待してるよ",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_090"] = "では失礼するよ。 急がないと…",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_020"] = "あっ ジェファソン先生…",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_040"] = "あの ちょっとネイサンを探してたんです",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_060"] = "ええ… 確かに",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_080"] = "はい… がんばります",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Chloe_020"] = "どうでもいいよ。 レイチェルが生き返るわけじゃない。 それより ネイサンだ",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Courtney_010"] = "かっこいい ジェファソン先生! 最高!",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Dana_010"] = "ジェファソン先生 ステキ! キャー",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Max_010"] = "誰もの予想どおり ビクトリアが優勝か |まさか 先生を脅迫してたなんて 信じられ… るよね",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Max_030"] = "分かってる。 寮を探してみよう",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_010"] = "それでは皆さん…  はいはい 分かったから 静かに |えー パーティの邪魔をして申し訳ないが |「日常ヒーロー」コンテストの優勝者発表に移ってもいいかな",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_030"] = "その前に まずは参加者全員 |そして参加しようと考えてくれたみんなに礼を言いたい",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_040"] = "自分の作品を世に出す |これはアーティストを目指す上で最も大切なステップだ |そして君たちはこの学校と その理念を体現してくれた",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_050"] = "僕にとっては 君たち全員が「ヒーロー」だ",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_060"] = "では発表しよう",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_070"] = "優勝者は…",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_080"] = "おおっと なんと… ビクトリア・チェイス君だ!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_140"] = "おめでとう。 ところで ケイトと言えば…",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_150"] = "あの事件を受けて このパーティは中止になるところだった",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_160"] = "だが 理事会が開催を認めてくれた… |ボルテックス・クラブの貢献が功を奏したともいえるだろう",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_170"] = "そして だからこそ 今夜はその判断に恥じない振る舞いを心掛けてほしい |いいね",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_180"] = "さて 年寄りの説教はこれくらいにして… あとは目一杯楽しむといい |プールパーティで羽目を外すには最高の夜だ。 以上!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Taylor_020"] = "かっこいい!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_090"] = "ウソ… やった!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_100"] = "ありがとうございます ジェファソン先生 |私がブラックウェルに入ったきっかけは 先生の作品に感銘を受けたからです |これからも そのお名前に恥じない作品作りを続けていきたいと思っています",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_110"] = "それからもう一つ… 私はこの賞をケイト・マーシュに捧げたいと思います |彼女こそ 本物のブラックウェルのヒーローでした",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_120"] = "それからもう一つ… 私はこの賞をケイト・マーシュに捧げたいと思います |彼女こそ 本物のブラックウェルのヒーローです |一日も早い回復を願っています",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_130"] = "以上です",
  ["Cue_E4_8B_SwimPool_JustinDrunk_IGE_Justin_010"] = "マックスじゃん 何してんの?",
  ["Cue_E4_8B_SwimPool_JustinDrunk_IGE_Justin_020"] = "気持ちわりいな… 休めばまた飲めるか…",
  ["Cue_E4_8B_SwimPool_Luke_IGE_Luke_010"] = "ウォーレンがネイサンをか。 金払ってでも見たかったな",
  ["Cue_E4_8B_SwimPool_Luke_IGE_Luke_020"] = "誰かネイサンをガツンとやってくれねえかな",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Max_020"] = "私 ゲストなんだけど?",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Victoria_010"] = "ちょっと なんで あんたがここにいるわけ?",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Victoria_030"] = "ありえないし",
  ["Cue_E4_8B_SwimPool_NoNameSpeakerStops_IGE_TeenBoy01_010"] = "誰だあれ?",
  ["Cue_E4_8B_SwimPool_Party01_IGE_TeenBoy01_050"] = "うおお 酔っぱらったー",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_010"] = "なにが VIP ラウンジだよ",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_030"] = "これ誰が金出してんだ?",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_050"] = "ああ ネイサンってマジでどうかしてるよな",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenFemale01_020"] = "ケイトはクラブのメンバーに入れてもらえなかったんだって…",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenFemale01_040"] = "こんなときにパーティなんて よくないんじゃ…",
  ["Cue_E4_8B_SwimPool_Party03_IGE_TeenGirl01_030"] = "月が 2 つあるのを見たって聞いたけど… 言ってたのジャスティンだし",
  ["Cue_E4_8B_SwimPool_Party03_IGE_TeenGirl02_020"] = "世界の終わりとかさ もう子どもじゃないんだから",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale01_010"] = "ちょっと そろそろ出てもらえますか?",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale01_030"] = "気持ち悪くなってる人は他にもいるんですけど",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale02_020"] = "もう1時間くらい吐いてるんじゃないの?",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale02_040"] = "出てきてくれないと一緒に入っちゃうよ",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenBoy03_010"] = "クソっ あれなんだったんだ?",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenBoy03_030"] = "もう俺 トイレから出られねえかも",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenMale01_020"] = "エナジードリンクとエバークリアのカクテルだろ… うぐ 腹が…",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenMale01_040"] = "もうボルテックス・クラブのパーティには来ねえぞ… あっ やべえ…",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenBoy01_010"] = "おい なんだよ?",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenBoy02_020"] = "どうなってんだよ!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenFemale02_050"] = "音楽止まっちゃった!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenFemale05_080"] = "ウソ DJ ・ドゥームと目が合っちゃった!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenGirl03_030"] = "なに? なんなの?",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenMale01_070"] = "何だよつまんねえな",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenMale04_100"] = "なにやってんだよ DJ!",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Chloe_020"] = "上も調べたけど いなかったよ",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Chloe_040"] = "急ごう。 終わりにするんだ",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Max_010"] = "クロエ。 ネイサンはここにはいないみたい。 誰も見てないって",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Max_030"] = "ああ もう! ということはきっと寮だね",
  ["Cue_E4_8B_SwimPool_SpeakStella_Stella_010"] = "「世界の終わり」 へようこそ。 荷物があったら預かるけど?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_020"] = "マックス! どうしたの スターは遅れてご到着ってわけ? |「世界の終わり」にようこそ! |もっと早く来てくれればよかったのに… |でも VIP ラウンジにはちゃんと入れるようにしといたからね",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_040"] = "あいつ また勝手なことして! ビクトリアにでもなったつもり? ありえないし |私がついていくから 堂々と正面から入りましょ。 ね?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_050"] = "ちょっと! あたしがマックスを名簿に追加しといたの知ってる? |あたしの休憩中に マックスの邪魔してたんだって? |なに勝手なことしてんの",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_070"] = "もう遅い。 あんたは永久除名処分だからね |ようこそ ボルテックス・クラブへ",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Max_010"] = "コートニー 何してるの?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Max_030"] = "でも さっき入り口の人に入れてもらえなくて…",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_VIPKeeper_060"] = "待ってよ 私はただ…",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_020"] = "マックス・コールフィールドがボルテックス・クラブのパーティに来るなんて… |雪でも降るんじゃないの? ってもう降ったか |それで なにか用?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_040"] = "あなたが名簿に…? ありえないと思うけど 確かめてみるからついてきて",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_050"] = "ねえ マックスがゲストに入ってるはずだって言うんだけど… ウケるよね |とりあえず見せて?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_060"] = "え ウソ…",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_080"] = "ちょっと バカにしてるの? これ あたしの字じゃない! |名簿はあたしが作ってるんだよ! |ビクトリアの言ってた通り あんたホント ウザい! そこまでして入りたいの? |もうボルテックス・クラブに近づかないで。 分かった? |ほら さっさとどっか行ってよ",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_010"] = "コートニー 何してるの?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_030"] = "一人でいるのもイヤだったから… |ゲストの名簿に私の名前もあるはずなのに 入り口の人が通してくれないの",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_070"] = "ほら それ私の名前でしょ",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Courtney_020"] = "マックス・コールフィールドがボルテックス・クラブのパーティに来るなんて… |雪でも降るんじゃないの? ってもう降ったか |それで なにか用?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Courtney_040"] = "すごく楽しいよ 入れればだけどね |あんたには絶対無理だと思うけど。 じゃあね",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Max_010"] = "コートニー 何してるの?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Max_030"] = "一人でいるのもイヤだったから… |それに VIP ラウンジって楽しいだろうなと思って",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_010"] = "名簿に名前がないな",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_030"] = "その後 消したんじゃねえの",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_050"] = "知らねえな 名前書いてねえんだから",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_TeenBoy01_020"] = "いや あるって。 ビクトリアが書いてたよ",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_TeenBoy01_040"] = "おい ふざけんなよ! 俺が誰だか分かってんのか!?",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_030"] = "中に入りたいんだけど…",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_050"] = "悪いけど私はゲストなの。 よく見て",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_070"] = "私は…",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_090"] = "別にメンバーになりたいわけじゃなくて ただネイサンと話を…",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_110"] = "私は…",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_040"] = "悪いけどこの先は VIP 専用スペースなの。 わかる?",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_060"] = "あんたみたいなのが VIP リストに入ってるわけないじゃん。 残念でした",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_080"] = "うざいな 入りたいなら コートニーに言って。 私 代理でいるだけだから",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_100"] = "ビクトリアから あんたは入れるなって名指しで言われてるから |残念でした。 お気の毒さま",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_120"] = "うざいな 入りたいなら コートニーに言って。 私 代理でいるだけだから",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_130"] = "人の話聞いてた? あんたは入れないの!",
  ["Cue_E4_8B_SwimPool_VIPListYES_Hayden_060"] = "よう スーパーマックス! 来なよ みんな歓迎するよ!",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Logan_030"] = "ああ すげえいい写真だった",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Logan_060"] = "おい そりゃねえだろ。 ったくお前らはよ",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Taylor_020"] = "ビクトリアが優勝するに決まってるって",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Taylor_050"] = "さあ 空耳じゃない",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Victoria_010"] = "作品には自信があるの。 まあ結果は分からないけどね",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Victoria_040"] = "あれ なにか聞こえた?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_010"] = "聞いて… あなたの身が危ないの |ビクトリアがネイサンと仲いいのは知ってるけど |あんな危険なヤツ信用しちゃダメ |ネイサンはね… ケイトにクスリを盛っただけじゃなくて |その後 怪しい場所に連れ込んだんだよ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_030"] = "まだ分からない。 でも ケイトを見たでしょ…? |そして… 次はビクトリアが狙われてる",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_050"] = "ちょっとどころじゃないよ。 全然ちょっとじゃない |私のことは嫌ってもいいけど この話は信じて",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_090"] = "とにかく ネイサンには近づかないで。 それと 絶対一人にならないように",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_110"] = "私は大丈夫",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_130"] = "うん。 ありがとう ビクトリア",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_020"] = "はあ? そんなわけないじゃん。 どうしてネイサンがそんなことを?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_040"] = "バカバカしい。 ネイサンは私の一番の友だちなんだけど? |ちょっとした問題は起こすけど それだって彼のせいじゃない |全部あのろくでもない親が原因よ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_060"] = "… 私がペンキをかぶったとき マックスはバカにしなかった…",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_070"] = "私 マックスのこと嫌いじゃないよ。 ちょっと変わり者だけどね |私 きっと嫉妬してるんだと思う |マックスと違って 人の考えを気にせずにいられないから",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_080"] = "本当はね 私も最近のネイサンが怖いの… 今日は見かけてないけど",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_100"] = "今回は言うこと聞いてあげる。 今夜は他の子たちと一緒にいるようにするから |心配してくれてありがとう |でも… その話が本当なら あなたも気をつけて",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_120"] = "あと… もし何かあったらメールして",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_140"] = "じゃあね",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_010"] = "今は 2 人で言い争ってる場合じゃない… あなたの身が危ないの |ビクトリアがネイサンと仲いいのは知ってるけど |あんな危険なヤツ信用しちゃダメ |ネイサンはね… ケイトにクスリを盛っただけじゃなくて |その後 怪しい場所に連れ込んだんだよ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_030"] = "茶化さないで まじめに聞いて",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_050"] = "ちょっとどころじゃないよ。 全然ちょっとじゃない |私のことは嫌ってもいいけど この話は信じて",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_070"] = "気は済んだ?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_100"] = "ビクトリア お願いだから聞いて! |ケイトのことを思い出して。 真剣に頼んでるの!",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_120"] = "じゃあね…",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_020"] = "は? ドラマの観すぎなんじゃない?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_040"] = "いやよ。 ネイサンは私の一番の友だちなの |ちょっとした問題は起こすけど それだって彼のせいじゃない |全部あのろくでもない親が原因よ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_060"] = "あなたの言うことなんて 誰も信じないわ。 何よ 繊細ぶって |そういう狙ってるところが ホントウザいのよ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_080"] = "いいえ まだまだ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_090"] = "あなたは 自分が参加すらしなかったコンテストで |私が優勝するのが気に食わないだけでしょ |たった一枚の写真を出す勇気もないまま のんきに自撮りしてるだけ |この学校にいる資格はないわ",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_110"] = "知らないわよ。 いい? 今はパーティ中なの |何を言われようと 私は思いっきり楽しむ |ネイサンが来たら このこと話すから。 それじゃ",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_001"] = "マックスじゃない! 来るつもりだったなら言ってよ! |一緒に服 選んであげたのに",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_003"] = "ううん トレバーと踊ってたからね。 マックスも来なよ! |それにトレバーのダンスひどくない?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_005"] = "まあね。 彼はローガンとは大違い |将来の話もできるし… 私のことも考えてくれる",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_007"] = "最高! ひどい一週間だったから 今夜くらいは楽しくやりたくて |ケイトの分までね",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_009"] = "近づくつもりもないけど… しかし ネイサンもかわいそうだよね |家族のこととか 大変そうだし",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_011"] = "金持ちだってことくらいしか。 ネイサンは嫌ってるみたいね |あの家族もそうだけど このクラブもいろいろおかしいよ",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_014"] = "うん… ジュリエットがボルテックス・クラブをカルトに例えてたけど |あながち間違ってないかも。 本当にひどいもの",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_016"] = "別に友だちと遊ぶのにクラブなんていらないし |トレバーたちと一緒にいるのも楽しいしね。 もういいかなって",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_018"] = "でもね 彼ったらホント ダンス下手で… うわ ひどっ!",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_002"] = "ちょっとそれどころじゃなくてね… デーナ ネイサンを見かけなかった?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_004"] = "すごく仲良さそうだね",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_006"] = "「世界の終わり」は楽しんでる?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_008"] = "そっか。 でも ネイサンには近づかないでね。 お願い",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_010"] = "彼のお父さんについて何か知ってる?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_012"] = "でもボルテックス・クラブではやりたい放題じゃん…",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_015"] = "デーナもそう思うんだね",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_017"] = "そっか… トレバーと楽しめてるみたいでよかった",
  ["Cue_E4_8B_VIP_CHDana_Quickphase_Dana_001"] = "マックスは踊らないの? 私まだここにいるから またあとでね!",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_002"] = "見ろよ。 スーパーマックスが平和を守りに参上だ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_004"] = "おう マックスか… 君がこんなところにいるとは驚きだな",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_006"] = "わりい ちょっとやりすぎたみたいでさ 頭回らないんだわ |とりあえず マックスも隣 座りなよ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_008"] = "かたいこと言うなって。 ちょっとぐらいいいじゃんか |ほらほら 遠慮しないでどうぞ。 ちょうど隣 空いてっから。 ほら",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_010"] = "俺もネイサンを待ってんだよね。 さっき仕入れを頼んだところでさ |マックスもさ あれだよあれ |せっかく来たんだから 盛り上がっていきなよ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_012"] = "そこらへんにいるヤツに聞いてみれば? それともやっぱ 隣に座りたくなった?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_014"] = "さあ… 自分で探してくれよ。 俺はほら 今いいとこだからさ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_017"] = "当然だろ? そりゃプレスコットの金だよ |そうでなきゃ あんな有名 DJ 呼べるわけないって",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_019"] = "何だよ シラケるな… 人生楽しまなくちゃ損だろ… |せっかくマックスとデーナがパーティに来たって喜んでたのにさ |説教するだけかよ? マドセンじゃねえんだからさ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_021"] = "俺には関係ないね。 じゃあな 優等生",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_001"] = "ねえ ヘイデン",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_003"] = "ネイサンを見てない?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_005"] = "ケイトが自殺したばかりなのに パーティを開いてるほうが不思議だよ… |ねえ ネイサン見なかった?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_007"] = "私はいい",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_009"] = "ううん ネイサンを探してるだけだから",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_011"] = "今そんな気分じゃないから。 それで 誰かネイサンを見てないの?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_013"] = "ビクトリアはどこ?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_015"] = "ほどほどにしておいたほうがいいよ",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_016"] = "ボルテックス・クラブのパーティって |ショーン・プレスコットがお金を出してるの?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_018"] = "文字通り プレスコットに踊らされてるわけだね…",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_020"] = "前のパーティでケイトに起きたこと 忘れたの? |とにかく ネイサンには気をつけてね",
  ["Cue_E4_8B_VIP_CHHayden_Quickphase_Hayden_001"] = "ん マックスか? なんかぼやけてるな… うおお 部屋が回ってる…",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_002"] = "マックスか いいぜ! でもその前に一緒に踊れよ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_004"] = "なんだよ ビクトリアもテイラーも断りやがるしよ… |お前 ネイサンに会いたいのか? なんで?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_006"] = "金目当てならあいつの親父を狙ったほうがいいぜ |このクラブの資金源だしな。 VIP ラウンジ様様だ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_008"] = "つれないね。 せっかく VIP ラウンジにいるのによ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_010"] = "ビクトリアに聞けよ。 あいつなら知ってるだろ。 なあ なんでそう冷てえんだよ? |お前イケてるしさ たまには話でもしようぜ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_012"] = "キツいこと言ってくれんな おい… |俺もデーナのことはマジで悪かったと思ってんだよ |なあ どうすればいいと思う?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_015"] = "ビッグフットの次の試合のこととかさ。 お前も見にこいよ |そしたら俺 お前にタッチダウン決めてやるぜ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_017"] = "あーあ 何か踊る気も失せちまった。 じゃあな マックス",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_001"] = "ローガン ちょっと話があるんだけど",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_003"] = "いや いい… ネイサンを見てない?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_005"] = "いいから教えて",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_007"] = "関係ないでしょ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_009"] = "ただのプールでしょ。 で ネイサンは見てないの?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_011"] = "いい加減にして。 デーナは妊娠したとき ローガンを一番必要としてたんだよ |なのに見捨てた |それで 今度は私? 恥ずかしいと思わないの",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_013"] = "まずは女の人に片っ端から手を出そうとするのをやめること |あとはあなた次第。 よく考えて",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_014"] = "何を話すっていうの?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_016"] = "ローガン ほんとに怒るよ",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_018"] = "あ それとダニエルには二度と手を出さないで |じゃないと後悔するから。 それじゃ",
  ["Cue_E4_8B_VIP_CHLogan_Quickphase_Logan_001"] = "話はまた今度な。 お前の言ったこと考えてんだよ",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_003"] = "テイラー ネイサンを見なかった?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_006"] = "ビクトリアもネイサンを怖がってるの?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_008"] = "怖いって どんな風に?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_010"] = "なのにボルテックス・クラブに入りたかったの?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_012"] = "ケイトは前のパーティでネイサンにクスリを盛られたの |テイラーも 今夜は何も飲まないほうがいいよ",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_014"] = "どうしてパーティに来たの? メンバーの義務とか?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_016"] = "そう… じゃあ 私もう行かなくちゃ |気をつけてね テイラー |お母さんによろしく",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_018"] = "ビクトリアの腰巾着も大変だね。 それとネイサンには気をつけて",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_020"] = "バカみたい。 じゃ せいぜい楽しんでね",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_001"] = "マックスじゃん よく来たね!",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_002"] = "えっ マックス? なんで? こんなとこで何してるの?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_004"] = "ううん… 正直会いたくない |最近 なんか怖いし… ビクトリアなら知ってるかも",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_005"] = "見てたとしてもあんたには関係ないでしょ? |ここは VIP エリアなんだから 早く出てって",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_007"] = "ううん 全然… ビクトリアはネイサンと仲がいいからね |兄妹以上っていうか… 絆が深いっていうか",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_009"] = "前から気味悪いと思ってたんだよね |おもしろいヤツだけど 周りのこと考えないでしょ",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_011"] = "あたしはただ 家を出て いい学校に入りたかっただけ |勉強したり 友だちとパーティに行ったり… |でもケイトの件で 間違いに気づいたんだ",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_013"] = "大丈夫 ネイサンがいるときは気をつけてるから |何されるか分かったもんじゃないし",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_015"] = "変な話だけど 予感がしてさ |これがボルテックス・クラブの最後のパーティになるかもしれないって",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_017"] = "ありがとう。 今はもうだいぶ具合よくなったんだ。 心配してくれて嬉しいよ",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_019"] = "はいはい もう行って",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_021"] = "言われなくても楽しむし",
  ["Cue_E4_8B_VIP_CHTaylor_Quickphase_Taylor_001"] = "この曲が終わったら また話そう",
  ["Cue_E4_8B_VIP_CHTaylor_Quickphase_Taylor_002"] = "ダンスのレッスンでもしてほしいの? お断りよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_001"] = "ちょっと黙ってて。 今は無駄話してる場合じゃないの",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_004"] = "そんなこと どうだっていい",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_005"] = "つい先日 ケイトが自殺したんだよ。 ここにいる 全員の目の前で!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_006"] = "つい先日 ケイトが自殺しようとしたんだよ。ここにいる 全員の目の前で!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_008"] = "ビクトリアのせいでもあるよ! パーティでケイトを助けようとしなかった |そこにいたのに。 しかも そのうえ動画をばらまいたりして",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_010"] = "ワインにクスリが入ってたこと 知ってたのに何もしなかったんじゃない |そのせいでケイトはあんなことに… |しかも 懲りずに屋上にいるときの動画も撮ったんでしょ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_013"] = "それでケイトの家族が納得すると思うの? よく平気で眠れるね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_014"] = "本当に許せないのはネイサン。 でも 助けようとしなかった全員にも責任がある",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_016"] = "非を認めないつもり?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_020"] = "話をすり替えるのはよして",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_021"] = "責めるつもりはないけど |ケイトが教会に行く真面目な子だってことは知ってたでしょ |どうして動画を広めたりしたの?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_023"] = "ひどすぎるよ。 ケイトが一体何をしたっていうの? |しかも 懲りずに屋上にいるときの動画も撮ったんでしょ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_026"] = "ビクトリアのこと 信じたい |ケイトに送ったポストカードも見たしね |でも だったらなんであんなことを…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_027"] = "ビクトリアのこと 信じたい… でも だったらなんであんなことを…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_030"] = "写真家だって無理じゃない? 私の自撮りをバカにしてたけど |そういうあなたの写真は顔のアップばっかり |そんなんじゃ アヴェドンには一生追いつけないよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_032"] = "へえ 優勝するんだ |そういえば 昨日の夜にジェファソン先生を脅迫してたもんね |必死すぎて哀れになったよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_035"] = "ビクトリアだってジェファソン先生に相手にされてないじゃない |大体 先生にすり寄ってるとき どんな顔されてるか気づいてないの? |ホント哀れ…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_038"] = "それなの? 昨日 ジェファソン先生に言おうとしてたこと",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_040"] = "偶然通りかかったから",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_042"] = "フェアな勝負になれば… ね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_044"] = "私 ビクトリアの写真すごいと思う。 人を押しのける必要ないよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_046"] = "そんなことない。 まあ 私は先生をコンテストから追いやっちゃたんだけど…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_047"] = "そんなことする必要ないよ |ジェファソン先生は有名だけど そんなこと言ってなかったじゃない",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_050"] = "私だってそう。 でも結局自分次第だと思う",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_051"] = "ううん 才能あるよ |人を蹴落とさなくたって みんな分かってくれてる。 でしょ?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_053"] = "そうだね。 私にはホンモノの友だちがいるし。 ニセモノはいらない",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_055"] = "だって ペンキが落ちるように細工したの私だし。 サミュエルだとでも思った?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_057"] = "だって ペンキが落ちるように細工したの私だし |サミュエルだとでも思った? |それに そっちも人の部屋荒らしたでしょ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_059"] = "そうなってたら私も困ったな。 よく思いとどまったね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_062"] = "どうやら ボルテックスのメンバーにはなれそうにないね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_064"] = "友だちではないかもしれないけど 敵でもないよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_066"] = "私たちだよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_068"] = "断るよ… 理由は 多分ビクトリアの想像とは違うけど",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_070"] = "友だちでいいじゃない |お互い写真家を目指してるし 変わり者で 見栄っ張りだし |わだかまりを忘れて付き合えば うまくやれるよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_072"] = "もったいないな… きっと素敵な友だちになれたよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_076"] = "きっとそうだよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_078"] = "ホント… 間に合うといいんだけどね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_002"] = "言うじゃない。 私が一度謝ったからって調子に乗らないでよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_003"] = "言うじゃない。 なに 写真のことまだ根に持ってるわけ?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_007"] = "私のせいじゃないわ。 こっちに文句言わないでよね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_009"] = "あなたバカなの? あのワインを飲ませたのは私じゃないし |誰彼かまわずキスしたのはケイトよ。 ふざけないで",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_011"] = "動画はもう消したから。 あのときは考えてなかったの。 もういいでしょ…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_012"] = "あのときの動画はもう消したから",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_015"] = "ケイトは はしゃいでるようにしか見えなかったの! 私にどうしろって言うのよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_017"] = "停学中の人に言われてもね |大体それを言うなら 私以外 誰もネイサンのことを心配してないじゃない |そっちはどうなのよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_018"] = "何よ。 大体それを言うなら 私以外 誰もネイサンのことを心配してないじゃない |そっちはどうなのよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_019"] = "なら言うけど ネイサンのことを心配してる人だって私だけじゃない |あなたは彼を学校から追い出せて 満足だろうけどね",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_022"] = "あんなことするつもりじゃなかったの |でも ワインのせいでみんなどうかしてたから…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_024"] = "あの動画はもう消した。 私 ケイトが死んだのを見て… |あれが現実だなんて信じられなかった |私のせいなのかってずっと考えてる。 あれ以来ずっと心が痛むの",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_025"] = "あの動画はもう消した |私はケイトと仲良くなかったけど だからってあんなの望んでないし |そこまでひどい人間じゃない",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_028"] = "あのね 私は普通の学生なの。聖人君子でもなんでもない |ただ写真家になって 有名になりたいだけ!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_029"] = "私だってよく分からない。 劣等感だけは人一倍でさ |でも 私は別に立派な人間にならなくてもいい… 写真家にさえなれれば…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_031"] = "笑わせないで。私がコンテストで優勝しても同じことが言えるかしら? |悔しそうに泣きべそかくあなたの顔が目に浮ぶわ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_033"] = "ストーカーの趣味があるわけ? それとも嫉妬? |っていうか マックスのせいで 先生サンフランシスコに行けないし |はっきり言って 先生はあなたになんか興味ないの",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_034"] = "ストーカーの趣味があるわけ? コンテストのことを話してただけなんだけど |大体関係ないでしょ 作品を出してもないくせに",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_036"] = "うるさい",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_037"] = "まったく 友だちじゃないんだし もうほっといてくれる?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_039"] = "まさか 見てたわけ?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_041"] = "変な勘ぐりはよして |コンテストがいい勝負になりそうで嬉しいって聞かされただけだから",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_043"] = "結果はじきに分かるはずよ| というか 私たち友だちじゃないんだし もうほっといてくれる?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_045"] = "甘いわね。 親がギャラリーを持ってるから分かるのよ |人を蹴落とさなきゃ勝てない世界なの",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_048"] = "まあね… でもありがとう また褒めてくれて。 私 すぐ自信なくしちゃうから",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_049"] = "どちらにせよ 先生は私の写真を選ばないわ。 やっぱり才能なんてないんだ…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_052"] = "そうは思えないけど… 言いたいことは分かるよ |ねえ 私たちって友だちになれないのかな",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_054"] = "ニセモノはそっちでしょ |私がペンキをかぶったとき 本当は心配なんかしてなかったくせに",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_056"] = "そういうところがムカつくのよ |人がペンキかぶってるところを わざわざ撮ったくせに",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_058"] = "ふざけないで! 下手したら 死んでたのよ! |それに サミュエルまでクビにさせるところだった",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_060"] = "さっきからずいぶん上から目線じゃない。 本当にムカつく",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_063"] = "そんなの 当たり前でしょ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_065"] = "そんなの誰が決めるの?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_067"] = "…なんなら ボルテックス・クラブのメンバーに入れてあげてもいいけど",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_069"] = "何 その真剣な顔…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_071"] = "そう思ったこともあった |私の写真を「アヴェドンっぽい」って言ったときに |ま すぐ正気に戻ったけど",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_075"] = "うん そうかもね…",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_077"] = "マックス… ボルテックスに入る気ない? まだ間に合うよ",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_079"] = "どういう意味?",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_001"] = "ありがとう マックス。 気をつけてるから大丈夫",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_002"] = "マックス 茶番はもういいから。 とっとと消えて",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_003"] = "あなたがいるとパーティを楽しめないんだけど",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_010"] = "ううん… 深い意味はないの。 でも 話ができてよかった",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_030"] = "そ… そうかもね。 ところで ネイサンがどこにいるか知らない?",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_050"] = "えっと 校長先生が話したいとかで… 大したことじゃないの",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_070"] = "じゃあね…",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_020"] = "こっちこそ。 私もね 嫌われてる自覚くらいあるの |付き合ってる仲間が仲間だしね。 でも そろそろ大人にならなきゃ",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_040"] = "ネイサン? 何でそんなこと聞くの?",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_060"] = "説教されないといいね。 でも 私も見てないの。 それじゃあね",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_010"] = "なあ いいだろ",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_030"] = "いいじゃねえか",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_050"] = "いいから 大丈夫だって ほら力抜けよ",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_070"] = "ほら なあ 優しくするからさ",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_020"] = "アハハ やめてよ",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_040"] = "やだ くすぐったいってば",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_060"] = "人に見られちゃうよ",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_080"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_8B_VIP_HotScene_TeenGirl_080",
  ["Cue_E4_8B_VIP_MaxCallsChloe_Max_010"] = "クロエ 行こう!",
  ["Cue_E4_8C_CampusPark_InsertionCar_Chloe_010"] = "のんきにパーティなんかしやがって…",
  ["Cue_E4_8C_CampusPark_InsertionCar_Chloe_030"] = "イヤだね |それじゃレイチェルが浮かばれない。 犯人に報いを受けさせて… |仇をとる。 プレスコット家がどんだけ力を持ってようが… |あたしを止めることはできない |マックスもついてるし… だろ?",
  ["Cue_E4_8C_CampusPark_InsertionCar_Max_020"] = "ねえ 今すぐ警察に行ってもいいんだよ。 証拠があるし",
  ["Cue_E4_8C_CampusPark_InsertionCar_Max_040"] = "最後までつきあうよ。 当然でしょ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_050"] = "今どこにいる?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_090"] = "行こう マックス",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_150"] = "バカバカしい… 行くぞ マックス",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_020"] = "なんだかごきげんだね。 あのあと大丈夫だった?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_070"] = "もしかして お酒飲んでた?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_110"] = "うん…  気持ちは分かるよ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_140"] = "いいよ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_170"] = "ウォーレン もう少しだけ協力して |ネイサンを見たらすぐ連絡して。 いい? |向こうには気づかれないように",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_190"] = "そんなことないよ。 じゃ 後で",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_010"] = "世界の終わりによーこそ お嬢さんたち。俺をエスコートしに来てくれたのかい…",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_030"] = "ネイサンをぶん殴れてせいせいしたよ |ムカつくやつだし… マックス あいつはヤバいよ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_040"] = "止めてくれてありがとな…ネイサンはマジでヤバい",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_060"] = "あのあと寮では見てない。 俺はずっと部屋にいたしな",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_080"] = "ビールをコップ半分で「飲んだ」と見なすならね",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_100"] = "なあ 待てよ… 引き止めて悪いけど 1 枚だけ写真撮っていいか? |なんだかほんとに世界の終わりが来たみたいな気がしてさ… |明るい未来的な何かを… 持っときたいんだよ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_120"] = "わかってる わかってる 俺うざいよな。 1 枚でいいからさ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_130"] = "あー…",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_160"] = "ごめん… 普通の高校生っぽいことしてケンカのことは忘れたかったんだ |俺 人を殴ったのは初めてなんだよ… |ずっとやられる側だったからさ",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_180"] = "大丈夫。 俺 存在感ないほうだから…",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_200"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_8C_CampusPark_InsertionParty_Warren_200",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Chloe_020"] = "そんなのどうでもいい。 世界が終わるなら それでいいさ",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Chloe_040"] = "ああ ネイサンの人生が終わる予兆だ",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_010"] = "うわ あれ何? ちょっとクロエ 空を見て!",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_030"] = "分かってるの? 何かの予兆だよ 絶対!",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_050"] = "世界は終わっちゃうのかな",
  ["Cue_E4_8C_CampusPark_TextMessage_Chloe_010"] = "ヤバい ネイサンからのチャットだ… 証拠は全て消す って…",
  ["Cue_E4_8C_CampusPark_TextMessage_Max_020"] = "待って… それって もしかしてレイチェルの遺体も…!",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy01_010"] = "どうなってんだよおい 月がふたつ見えてんじゃん…",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy01_030"] = "いやいや そんなわけねえって… 光の屈折とかだろ きっと",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy02_020"] = "俺もだ そんなに酔ってねえのに… これ現実なのか?",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy02_040"] = "雪 日食 鳥とクジラの死体があったからな… |やっぱり現実なんじゃねえの これ",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenBoy03_010"] = "マジか 日食の次はこれかよ",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenBoy03_030"] = "ふたつともそっくりだな",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenGirl02_020"] = "ねえ なんか輪郭が変じゃない?",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenGirl02_040"] = "月がふたつなんて… こんなのありえないでしょ",
  ["Cue_E4_9B_Junkyard_End_Chloe_010"] = "よかった… まだここにいる…",
  ["Cue_E4_9B_Junkyard_End_Chloe_060"] = "マックス…?",
  ["Cue_E4_9B_Junkyard_End_Max_020"] = "見ないほうがいい…",
  ["Cue_E4_9B_Junkyard_End_Max_030"] = "痛っ…! え…?",
  ["Cue_E4_9B_Junkyard_End_Max_040"] = "クロエ! 危ない…!",
  ["Cue_E4_9B_Junkyard_End_Max_050"] = "ウソ…",
  ["Cue_E4_9B_Junkyard_End_Max_070"] = "クロエ…",
  ["Cue_E4_9B_Junkyard_Grave_Max_010"] = "クロエ! こっち! 早く!",
  ["Cue_E4_9B_Junkyard_Insertion_Chloe_020"] = "悪い… ネイサンが襲ってきたら すぐ巻き戻せよ",
  ["Cue_E4_9B_Junkyard_Insertion_Max_010"] = "ちょっと! もっと静かに歩いてよ!",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_010"] = "クロエ! 置いてかないでよ!",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_020"] = "静かにして… 見つかったらマズいよ",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_030"] = "クロエ お願いだから落ち着いてよ… ね?",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_040"] = "ちょっと落ち着いてってば… 見つかっちゃうでしょ",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_050"] = "クロエ 見つかったら殺されるよ! 静かにしてって!",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_010"] = "気味が悪いな…",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_020"] = "ネイサン… どこにいる…",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_030"] = "レイチェル… レイチェル…",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_040"] = "絶対に許さない…!",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_050"] = "どこにいやがる…!",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_010"] = "ネイサンの野郎… 殺してやりたい…!",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_020"] = "あのときひき殺しておけば…",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_030"] = "ネイサンは絶対 この近くにいる…!",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_040"] = "ネイサンを見つけたら 巻き戻してくれ。 1 回殺すだけじゃ足りない…",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_050"] = "プレスコット家ごと滅ぼしてやる…!",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_060"] = "レイチェル… 絶対にかたきを討つからな…",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_070"] = "ネイサンのヤツ 絶対許さねえ…",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_080"] = "マックスの力で ネイサンをブッつぶすんだ",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_010"] = "静かにしないと…",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_020"] = "何これ…! かんべんして…",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_030"] = "警察 呼ぼうよ…",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_040"] = "もうやだ…",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_050"] = "レイチェル かわいそう…",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_010"] = "待てよ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_020"] = "置いてくなって!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_030"] = "一人で勝手に行くなよ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_040"] = "ネイサンを見つけたのか!?",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_050"] = "待てって! 置いてくなよ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_010"] = "マックス こっちだ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_020"] = "マックス 遅いぞ! 早くしろ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_030"] = "マックス! 早く来いよ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_040"] = "スマホの電池がなくなるぞ!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_050"] = "何してんだ! ネイサンに逃げられるぞ!",
  ["Act_E5_1A_DarkRoom_Binder_Look01_Max_010"] = "あの中に 他の写真があるはず",
  ["Act_E5_1A_DarkRoom_BorkenStuff_Look01_Max_010"] = "そっか カートを蹴った時に割れたんだ…",
  ["Act_E5_1A_DarkRoom_CHVictoria1_Look01_Max_010"] = "そんな… ビクトリアもジェファソンに捕まったんだ… 最悪",
  ["Act_E5_1A_DarkRoom_CHVictoria1_Look02_Max_020"] = "ビクトリア… 絶対ここから連れ出してあげるから…",
  ["Act_E5_1A_DarkRoom_CHVictoria2_Look01_Max_010"] = "私が警告したせいで… ジェファソンに相談を… 私のせいだ |ごめん… ごめんね ビクトリア",
  ["Act_E5_1A_DarkRoom_Camera_Look01_Max_010"] = "この高級カメラでジェファソンの顔を殴ってやりたい",
  ["Act_E5_1A_DarkRoom_GuiltLines_Scripted_Max_010"] = "タイムリープはもうしないって決めたけど… こうするしかない…",
  ["Act_E5_1A_DarkRoom_MaxPhone_Look01_Max_010"] = "ゆっくり鑑賞でもするつもりなの…?",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look01_Max_010"] = "あれは私の写真…? 昨日の夜 撮ったんだ",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look01_Max_015"] = "遠すぎて… ハッキリ見えない",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look02_Max_030"] = "これで何とか… お願い…",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look03_Max_040"] = "こんな自分の姿見たくない… 絶対許さないから…",
  ["Act_E5_1A_DarkRoom_MaxPic02_Look01_Max_010"] = "この時はちゃんと起きてる… こっちで試してみよう",
  ["Act_E5_1A_DarkRoom_MaxPicFailed_Look01_Max_010"] = "だめ… この写真は使えない… |あれをもう一度体験するなんて 耐えられない… ムリ…",
  ["Act_E5_1A_DarkRoom_MaxStuff_Look01_Max_010"] = "見える場所にあるのに 届かない…",
  ["Act_E5_1A_DarkRoom_NeedleDrugs1_Look01_Max_010"] = "ダメだ 何も思い出せない… ネイサンがケイトに使ったのと同じクスリだ…",
  ["Act_E5_1A_DarkRoom_NeedleDrugs2_Look01_Max_010"] = "写真に集中したときに注射器が動いたんだ… 変化は起きてる! この調子!",
  ["Act_E5_1A_DarkRoom_PhotoTrolley_Look01_Max_010"] = "こっちに引き寄せられれば…",
  ["Act_E5_1A_DarkRoom_Polaroid_Look01_Max_010"] = "私のカメラが頼りなく思えてくる",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_020"] = "助けられなかった… また…",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_040"] = "クロエ… あんまりだよ…",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_050"] = "ジェファソンはイカレてる… こんなこと… どうして…",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_070"] = "あいつが私のヒーローだったなんて…",
  ["Act_E5_1A_DarkRoom_ScriptedIdle2_Scripted_Max_010"] = "あんな完璧な先生… おかしいって思うべきだった",
  ["Act_E5_1A_DarkRoom_ScriptedIdle2_Scripted_Max_030"] = "ここを出てクロエを助けるんだ… 絶対に",
  ["Act_E5_1A_DarkRoom_ScriptedObjective1_Scripted_Max_010"] = "ここから出る方法を探さないと",
  ["Act_E5_1A_DarkRoom_ScriptedObjective1_Scripted_Max_020"] = "自分が写った写真があれば… 時間を巻き戻せる",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_010"] = "ひどい… こんなことされてたなんて… 最低だよ",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_020"] = "あんな写真コレクションのために… 私にクスリを…",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_030"] = "こんなこと いつからやってたの?",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_040"] = "こんなとこで死ねない…",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_060"] = "別の写真を試そう… あいつのこと考えたら気持ち悪くなる…",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_070"] = "何かが変わった… 別の写真を試してみよう…",
  ["Act_E5_1A_DarkRoom_Straps2_Look01_Max_010"] = "これ キツいな…",
  ["Act_E5_1A_DarkRoom_TornFolder_Look01_Max_010"] = "あ… ジェファソンがシミのついた写真を許すはずがない… 使えるかも!",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_001"] = "ビクトリア 聞いてくれる?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_003"] = "お願い ちゃんと聞いて… 考えがあるの",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_005"] = "私も。 でも怖がってるヒマはないの。 戦わなきゃ… 今すぐ",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_007"] = "ジェファソンの好きにはさせない… |とにかく気を強く持って。 協力してほしいの",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_008"] = "しーっ! 静かにしないと あいつが戻って来ちゃう… お願い… 考えさせて…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_009"] = "ビクトリア しっかりして。 死なせないよ… もう誰も",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_011"] = "分かってる… とにかく落ち着いて",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_012"] = "私が間違ってた… こんなこと ネイサン一人でできるはずないのに…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_017"] = "違う。 ケイトを殺したのはネイサンとジェファソンだよ。 絶対 許さない…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_018"] = "私もいるから。ね?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_019"] = "ケイトだって 私達の無事を祈ってる。 出たら一緒に会いに行こう。 ね?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_023"] = "大丈夫 何とかするから。 絶対に",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_025"] = "意識があるうちに動かなきゃ… またクスリを打たれたら全部忘れちゃう…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_002"] = "こんな死に方イヤ… まだ 18 歳なのに…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_004"] = "本当に? どんな? 私… こわい",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_006"] = "自分の腕も動かせないのに… どうやって戦えって言うの?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_010"] = "そんな余裕ないでしょ! 監禁されてんのよ!?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_013"] = "マックス… 危険なのはネイサンじゃなかったの…? |なのにマークが… ジェファソン先生が…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_014"] = "どういうこと? 私達どうなるの? もうここから出して!",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_015"] = "ケイトが本当のこと言ってるって 本当は分かってたのに… |助けるどころか傷つけて… だから… |だからバチが当たったんだ",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_016"] = "マックス 私には無理よ… そうでしょ… ケイトにもあんな意地悪して… |その結果がこれなんだ…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_020"] = "ジェファソンがこんなヤツだったなんて… |私 コンテストのために脅したりして… バカ なんてバカなの!",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_021"] = "こんなの信じられない… ジェファソンが私を… 私達をこんな目に…",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_022"] = "ケイトとまた会えるなら何でもする… 会って謝りたい",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_024"] = "マックス… ありがとう",
  ["Cue_E5_1A_DarkRoom_CHVictoria_QPhase01_Victoria_001"] = "マックス… お願い ここから出して!",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_020"] = "待って 考えてる…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_040"] = "分かってる… だから落ち着いて…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_070"] = "私もだよ… でも 今は逃げるのが先",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_090"] = "ビクトリアのせいじゃない… 今は考えないで",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_110"] = "ううん ビクトリアのせいじゃない… 今は考えないで",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_130"] = "バカ言わないで。 誰も死なないよ。 一緒に逃げるの。 約束する",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_150"] = "一緒に頑張ろう ね?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_010"] = "マックス… どうしよう? ねえ?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_030"] = "こんなとこもういたくない!",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_050"] = "お願い 何とかして… ねえ お願い!",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_060"] = "マックス… ごめん… 私 何も知らなくて",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_080"] = "ケイトも同じ目にあったのに… 自殺に追い込んで…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_100"] = "ケイトも同じ目にあったのに… 死なせるところだった…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_120"] = "見捨てないで… ここで死ぬのはイヤ…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_140"] = "これは夢よね… 早く目を覚ましたい…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_160"] = "私 ホントにバカだった…",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_170"] = "どうしてジェファソン先生が? どうしてなの?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_180"] = "マックス… あなただけが頼りよ…",
  ["Cue_E5_1A_DarkRoom_InsertionBack_Max_010"] = "どうしよう… 考えなきゃ… どうしたらいいの… どうしたら…",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_010"] = "助け… て…",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_020"] = "ここは…? 暗い部屋… 「暗室」…?",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_030"] = "クロエ…?",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_040"] = "そんな… なんで…",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_050"] = "ウソ… ビクトリア…! しっかりして…",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_060"] = "ビクトリア! 起きて! 起きてよ!",
  ["Cue_E5_1A_DarkRoom_Insertion_Victoria_070"] = "ううっ… んっ…",
  ["Cue_E5_1A_DarkRoom_MaxFreeLeg_IGE_Max_010"] = "よし… これで何とかなるかも…",
  ["Cue_E5_1A_DarkRoom_MaxHelp_IGE_Max_010"] = "誰か! 助けて!",
  ["Cue_E5_1A_DarkRoom_MaxHelp_IGE_Max_020"] = "ねえ! 誰かいないの!? お願い 助けて!",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_030"] = "ほお マックス…",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_050"] = "これはイイな…",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_100"] = "聡明でありながら… 無垢だ",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_020"] = "ビクトリア! ビクトリア… 聞こえる…? 私… マックスだよ",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_040"] = "クスリを注射されたみたい… ケイトのときと同じ。 何か思い出せる?",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_080"] = "いい? 私たちはマーク・ジェファソンに誘拐されたの |ネイサンもあいつに利用されてる |ジェファソンが戻ってくる前に ここを脱出しないと…",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_030"] = "マックス… こ… ここ どこなの? どうなってるの!?",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_050"] = "確か… マックスが「ネイサンに気をつけろ」って言うから |ジェファソン先生に助けを求めて… |そしたら先生がキョドりはじめて… あとは何も覚えてない… |手が動かせない… マックス お願い 助けて… これまでのこと謝るから…",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_090"] = "ウソでしょ… イヤだ… 私 死にたくない… |こんな死に方イヤ… まだ 18 歳なのに…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_010"] = "これは傑作の予感だ… |ビクトリアは嫉妬するだろうが 彼女は分かっていないのさ |君と僕との特別な関係をね",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_020"] = "あの勘違い女 コンテストで優勝したいあまり 僕を脅迫するとは…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_030"] = "コンテストの本当の優勝者は君… 君自身だ",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_060"] = "意地を張らないで。 怖いんだね? |最初は皆 あどけない目をして目覚めるんだ… |そして徐々に恐怖に染まっていく…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_080"] = "よし セッションは終了だ |90 年代ならシャンパンと白い粉で打ち上げをしたものだが… |今ではみんな 健康茶とビタミン剤… |そもそも雑誌自体が風前の灯だ |あの時代が恋しいよ…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_100"] = "「どうして」? いい質問だ… |僕はただ 無垢な心が壊れていく瞬間をとらえたいのさ… |黒から白へ… そして灰色へ… そしてついには その先へ…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_110"] = "世間ずれしたプロのモデルではダメなんだ |ブラックウェルのキャンパスでまれに見つかる 希望の光をまとった生徒… 彼女たちだけが |僕の被写体となる栄光… 特権にあずかれるのさ",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_140"] = "では 写真をプリントしてみようか… |君のインスタントカメラなら |こんなことせずともすぐに作品を確認できるのにね",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_160"] = "うるさい! 命乞いするんじゃない! |クソ… なんて見苦しい… |今は最後のひとときを堪能しよう |このセッションも やがては君の死をもって終わるのだから…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_170"] = "君をこの部屋に迎えられて 本当によかったよ… |死の直前にその目がとらえるのは… 僕の目がとらえた君自身の姿… |まさに完璧だ",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_040"] = "うるさい…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_050"] = "願い下げだよ…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_070"] = "何… 何をする気なの…?",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_090"] = "先生… どうしてこんなことを…?",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_130"] = "先生は… 普通じゃない。 罪をつぐなってもらうから…!",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_150"] = "ここから出してください… 私 先生を助けてあげたいんです",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_151"] = "お願い 逃がして… 先生を助けたいんです…",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_152"] = "逃がして… お願いです… お願い…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_010"] = "このアングルは 君の無垢さを引き立てる |意識が混濁したモデルは自らを飾り立てようとしない |素の顔を引き出すことができるんだ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_012"] = "そう その表情… 完璧だよ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_014"] = "顔はそのまま!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_016"] = "勝手に動くな!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_020"] = "せっかくの構図が台無しだ…! |まあいい… 時間なら \"まだ\" たっぷりあるからね",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_030"] = "君の作品を初めて見た瞬間 特別だと思ったよ。 そう あの自撮り写真さ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_040"] = "君の姿は「無垢」そのものだ。 レイチェルとは違う |彼女は余計なものにばかり目を向けるクセがあったからね |惜しかったよ… 待って… 別のアングルも試してみよう…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_050"] = "動くな!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_060"] = "そう それでいいんだ… ネイサンにも見せてやりたかったよ |だが あいつも まだまだだ |複数の被写体を寄せ集めるだけで |一貫性のあるテーマを構築することはできないからね",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_070"] = "しかし 影の使い方は絶妙だ |そして他にも 希有な才能を持ち合わせていた… |それはじきに公になるだろう",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_080"] = "そう そのまなざし… すばらしいよ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_090"] = "聡明でありながら… 無垢だ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_100"] = "ただ… 君の好奇心の強さはいただけないな! |幸い この部屋は 24 時間監視下にあってね |ネイサンの電話から送ったメッセージ 1 つで 簡単に釣れたわけだ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_110"] = "お友だちとの探偵ごっこなどにうつつを抜かさず |勉強に専念していればよかったものを",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_130"] = "クロエ… そうそう |気の毒だが… 僕… \"ネイサン\"がしたことは正当防衛だ |それに 学校をやめ 道を踏み外した一人の女の子のことなど |誰も気にしないさ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_140"] = "だが君は違う。 今夜 君が死ねば 多くの人が悲しむ |言っただろう? 才能があると",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_145"] = "僕がわざわざこんな田舎町に来たのはね 君のように無垢なモデルを探すためさ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_150"] = "すばらしい… そうだな… アップも何枚か撮っておこう…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_160"] = "マックス 動くなと言ってるだろう。 台無しにする気かい 僕の完璧な構図を!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_165"] = "もう 1 本 注射が必要かな…?",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_170"] = "じっとしてなさい。 動くともっと… 痛いよ",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_180"] = "何をしやがる!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_190"] = "人の話を聞かないクズが! |だからこそ 僕の授業に隠されたヒントにも気づかないんだよ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_200"] = "だからケイトを救うことすらできなかった",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_210"] = "それでよくケイト・マーシュを救えたものだ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_220"] = "マックス その薬はとても高価なんだよ。 僕の給料ではとても買えない |だからネイサンが必要だったのさ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_230"] = "だが 努力は認めよう |それに 今まで見てきたなかでここ数日の君は |まるで人が変わったように勇敢だった",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_240"] = "私はカメラそのものだ。 君と同じさ |一部の文化ではね カメラは人の魂を捕らえると信じられているんだよ… |少ししたら 2 人のフォトセッションを始めよう",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_245"] = "私はカメラそのものだ。 君と同じさ。 知ってるかい? |一部の文化ではね カメラは人の魂を捕らえると信じられているんだよ… |さて まずはネイサンからだ… |大丈夫 君とのフォトセッションも すぐ始めるよ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_250"] = "徒労ではあったがね。 僕に死角などない",
  ["Cue_E5_1B_DarkRoom_Insertion_Max_120"] = "クロエ…",
  ["Cue_E5_1B_DarkRoom_Insertion_Max_130"] = "いや… いや… いや…",
  ["Act_E5_1C_DarkRoom_ArtClassSelfie_Look01_Max_010"] = "この写真… これを使えばすべてが始まった時に戻れる |何もかもやり直すチャンスかもしれない…",
  ["Act_E5_1C_DarkRoom_CHJefferson_Look01_Max_010"] = "もう顔も見たくない…",
  ["Act_E5_1C_DarkRoom_CHVictoria_Look01_Max_010"] = "眠っててくれて良かった… 私だって耐えられないよ…",
  ["Act_E5_1C_DarkRoom_Diary_Look01_Max_010"] = "日記には私の写真がたくさんある… なんとか取り戻さなきゃ…",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_010"] = "こんなの芸術じゃない…",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_020"] = "しっかりして… 考えるの",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_030"] = "話しかけて… 油断させれば… 写真を手放すかも",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_040"] = "他のことを聞いてみよう…",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_050"] = "ウソ 私の日記だ… あれさえあれば…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_001"] = "僕はいたって正常さ。だからこそ ここまでこれたんだ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_004"] = "まあ ビクトリアはどうでもいいが。 僕のモデルになる資格はない…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_005"] = "君のお友だちについても もういいだろ? |あの手のエセパンク女はシアトルで見飽きていてね",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_006"] = "僕はケイトほど純真じゃなくてね。 地獄なんて信じない |それに世界は アーティストが創るものなのさ… |ああ 彼女は傑作になれたのに…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_007"] = "彼女は武器を持っていた。 正当防衛さ |銃をおもちゃにした罰とも言える |被写体は 状況を一切把握せず 無駄に抗わないのが一番いい… |無垢なケイトのようにね…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_011"] = "君が最後に聞く声だ… 堪能するといい… |おや 気に障ったかな? |顔色が変わったね… 実に美しいよ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_012"] = "それはどうだろうね… |君が死んだあと ケイトをもう一度試してみるのも一興だ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_013"] = "ああ。 僕も実に残念だ… ケイトは強い心の持ち主だった |それを砕くのは 何にもかえがたい快感だったよ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_015"] = "君が校長にケイトとのことを言いつけたときは さすがに肝が冷えたよ |酒浸りの彼にまともな判断力がなかったおかげで 命拾いしたけどね",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_016"] = "幸い 君が校長に証言してくれたおかげで |諸悪の根源はネイサンということになっている |感謝しないとね",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_017"] = "マドセンに責任があると証言したのは君だ |真相に迫りつつあったのは彼だけだったというのにね…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_018"] = "しかし ネイサンが親に隠れて何をしていたか… |町中に知れ渡れば プレスコット家もおしまいだな…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_021"] = "「操作した」と言ってほしいね。 彼は実に扱いやすい操り人形だった",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_022"] = "決め付けはよくないな。 彼は実に哀れな子なんだよ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_025"] = "分かってないね。 ネイサンには才能があった。 そしてクズの父親がいた",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_026"] = "僕はネイサンの目を開かせてやっただけだ。 むしろ感謝してもらいたいね",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_029"] = "僕はネイサンの父親代わりだったのさ |教師と生徒の間には しばしばそういう信頼が育まれる |現に当初は 本当に心温まる関係だったよ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_031"] = "バカを言っちゃいけない。 彼の耳には 必要最低限の情報しか入れていないよ |プレスコット家の金さえ引き出せればよかったんだ |この「暗室」も 被写体に使うクスリが手に入ったのも すべてそのおかげさ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_033"] = "レイチェル・アンバーは… あれは… まさしく悲劇だった |未熟なネイサンが 投与するクスリの量を誤ってね…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_036"] = "今頃あの世で仲良くやっているさ… そう言えば満足かな?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_037"] = "話せば長くなるが… 彼女は特別だった |カメレオンのように 実に多様な顔を見せる被写体だった |僕と彼女は 心が通じ合っていたんだ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_039"] = "なんで? なんでだと? 黙ってろ バカ女!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_040"] = "すまない… ついカッとなってしまった…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_044"] = "あれはほんの気まぐれだ |レイチェルとフランクはとっくに切れていたよ |知らなかったのは男のほうだけさ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_045"] = "レイチェルは僕を愛していた。 これは事実だ |僕たちのフォトセッションを見れば 一目瞭然さ |被写体となった彼女は幸せの絶頂にいた",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_046"] = "まあいい… それにレイチェルはもういない |どうせ LA に行っても埋もれていたよ。 むしろ感謝してもらいたいね",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_048"] = "君だって 友だちがネイサンを殴り倒すのを止めなかった。 同類だよ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_049"] = "ネイサンを殴る友だちを止めただけで  善人面をするつもりかい?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_052"] = "うるさい 黙れ! あのクソガキはな レイチェルにのぼせ上がって |生意気にも僕のまねごとをしようとしたんだ… 身の程知らずが…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_054"] = "地下に埋まっているよ… |レイチェルの一件で 彼を飼いつづけるのは危険だと判断した |死体は警察にも見つけられはしない… |僕はね 君たちアマチュアとは別次元の存在なんだよ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_056"] = "まったく よくしゃべる… |だが… 君は自ら進んで首を突っ込んだおかげで 今ここにいるんだよ |それに モデルとしての役割を果たしてくれたら |君の痕跡は完全に消させてもらうさ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_058"] = "ああ 没収させてもらったよ… 女子学生の日記ほど純真無垢なものはない… |ああこれは… 僕の授業中に撮った自撮りか… |本当 人の話を聞かない悪い子だ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_059"] = "実にもったいない… 見てごらん 君にならもっといい写真が撮れたはずだ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_060"] = "ああ 没収させてもらったよ… 女子学生の日記ほど純真無垢なものはない…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_062"] = "黙ってろ! しかし… いい写真だ… 実にもったいないよ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_002"] = "地獄に落ちろ…! 絶対 許さないから…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_003"] = "クロエを…! 私の親友を殺した…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_008"] = "黙って… 声を聞くとむしずが走る…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_009"] = "ケイトは苦しさを乗り越えた |先生は失敗したの。 ケイトは強い |先生なんかよりずっと…!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_010"] = "アーティストは教え子を自殺に追い込んだりしない |先生はネイサンを利用して 意識のないケイトの写真を撮って… |そのせいで ケイトは…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_014"] = "絶対に… このままでは済まさないから…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_019"] = "人を利用するなんて…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_020"] = "ネイサンも同類です",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_023"] = "人を何だと思ってるの…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_024"] = "それは先生もでしょ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_027"] = "だから何?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_028"] = "要は洗脳でしょ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_030"] = "ネイサンにも 計画を全部話したの?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_032"] = "被写体じゃなくて犠牲者でしょ… レイチェルも…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_034"] = "先生は… クロエとレイチェルを殺した…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_035"] = "どうしてレイチェルを…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_038"] = "ひどい… なんで…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_041"] = "自ら進んでモデルになったとでも言いたいの…?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_042"] = "レイチェルと心が通じてたのは フランクでしょ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_047"] = "よくもそんなこと…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_050"] = "一緒にしないで!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_051"] = "ネイサンのことなんて どうでもいいくせに",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_053"] = "ネイサンはどこにいるの?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_055"] = "何 言ってるの? そこらじゅうに証拠を残して… |全部ネイサンのせいにできるとでも思ってるわけ? |私がどうなっても… 先生は絶対地獄に落ちる |クロエと レイチェルと 他の犠牲者たちが許さないから…!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_057"] = "私の日記…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_061"] = "その… 日記の写真… 見せて… お願い… 一目だけでも",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_063"] = "自ら進んでモデルになったとでも…? |そういえば 新しい人と出会ったってメモに書いてあった…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_002"] = "君と無駄話をしている暇はない |感覚が鈍る前に できあがった写真をチェックしないと… |きっと僕のキャリア史上最高の作品だ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_009"] = "この状況でそんなことを頼んだモデルは初めてだよ |最期に目にするのが |僕の目を通してとらえられた自分の姿というのも 悪くないだろうね… |いや むしろ完璧だ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_010"] = "うるさい! 命乞いするんじゃない! |クソ… なんて見苦しい… 今は最後のひとときを堪能しよう |このセッションも やがては君の死をもって終わるのだから…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_011"] = "大丈夫 誰にも読ませないよ |そう… 女子学生の日記ほど 純真無垢なものはない… |ああこれは… 僕の授業中に撮った自撮り…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_012"] = "「どうかしてる」…? 何も分かっていないくせに ナメた口をきくな! |僕はただ 輝く若者たちの姿を愛でているだけだ |夢が後悔に変わる前のね…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_013"] = "僕の写真の中で永遠に生き続けるのさ |君がこの世にいた証拠なんて それ以外はひとかけらも残さないよ",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_014"] = "そう… それで思い出したよ… 女子学生の日記ほど純真無垢なものはない…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_016"] = "女子学生の駄文ほど 無垢なものはない |美術の先生への秘めたる思いでもつづられているのかな |おや… 自撮り写真だ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_017"] = "実にもったいないよ… 見てごらん 君ならもっといい写真が撮れたはずだ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_019"] = "そうはいかない。 僕の夢はとうの昔についえたけれどね… |今はこうして 自らの居場所をつくりだすことが生きがいなんだ…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_020"] = "実にもったいないよ… ひどい写真だな。 君ならもっといいものが撮れただろう",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_001"] = "待って! 話を聞いて ジェファソン先生…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_003"] = "私にも… 私にも見せてください…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_004"] = "ここから出してください… 私 先生を助けてあげたいんです",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_005"] = "あの… 私の日記…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_006"] = "あなた… 先生は… どうかしてる… |しかるべき人に相談するべきです… |お願い… もうこんなことはやめて…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_007"] = "私… 私はどうなるんですか?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_008"] = "私を… 殺す気なんでしょ…? せめて日記は 誰にも見せないで…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_015"] = "読まないで…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_018"] = "お願い 逃がして… 後悔する前に…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_010"] = "これはいい… まさしく無垢の結晶だ…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_020"] = "すばらしい… 君にも見せてあげたい…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_030"] = "これはピンボケだな… 僕のミスだ 気にしないで",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_040"] = "君とはもう少し早く出会っていたかったよ…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_050"] = "大きく見開かれ… 戸惑いの色を映す瞳… 美しい",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_060"] = "世に発表できたら どんなにいいか…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_070"] = "傑作だ… どこに出しても恥ずかしくない",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_080"] = "君を撮れるのが僕だけとは… 実に惜しい…",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_090"] = "ああ… これぞまさに芸術だ",
  ["Cue_E5_1C_DarkRoom_PolaRewind_Jefferson_010"] = "アーバスは人間を「苦悩の存在」と考えた。 正直ヘドが出るね |はいはい 騒がない… |例えば 誰かを暗い部屋に座らせれば 絶望のシーンのできあがりだ",
  ["Cue_E5_1C_DarkRoom_PolaRewind_Victoria_010"] = "アーバスの作品にとらえられた 失意の人びとの目には 鬼気迫るものがあります",
  ["Act_E5_2A_ArtClass_ArcadiaPicture01_Look01_Max_010"] = "アルカディア・ベイにも |まだ美しさは残ってる",
  ["Act_E5_2A_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "灯台が… 今も呼んでる気がする",
  ["Act_E5_2A_ArtClass_BagHint_Scripted_Max_010"] = "カバンの中に学校のものがたくさんある… 必要なものが取り出せるかもしれない",
  ["Act_E5_2A_ArtClass_Books_Look01_Max_010"] = "1 週間前の私は恐る恐る向き合ってた… 写真にも… 人生にも…",
  ["Act_E5_2A_ArtClass_CHJefferson_Look01_Max_010"] = "よくも普通にしてられるね… すぐに正体をばらしてやるから",
  ["Act_E5_2A_ArtClass_CHKate_Look01_Max_010"] = "ケイト… 生きててくれて嬉しい…",
  ["Act_E5_2A_ArtClass_CHKate_Look01_Max_015"] = "ケイト…",
  ["Act_E5_2A_ArtClass_CHKate_Look02_Max_020"] = "信じてね… 今度は私がついてる",
  ["Act_E5_2A_ArtClass_CHKate_Look02_Max_025"] = "一人じゃないって分かってくれたかな…",
  ["Act_E5_2A_ArtClass_CHVictoria_Look01_Max_010"] = "ビクトリア そんなヤツの隣に立たないで…",
  ["Act_E5_2A_ArtClass_CHVictoria_Look01_Max_020"] = "もしジェファソンがどんなヤツか知ってたら…",
  ["Act_E5_2A_ArtClass_ContestPhoto_Look01_Max_010"] = "そんなにコンテストの写真が欲しいなら これでもどう",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_020"] = "戻った… メチャクチャな 1 週間の始まりに…",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_030"] = "もう誰にもクロエを傷つけさせない…",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_040"] = "失敗は許されない",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_050"] = "落ち着いて… 息をして… ひとつずつ直していけばいいんだ",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_060"] = "まずは ジェファソンがすぐに捕まるようにしよう",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_070"] = "デイビッドに ジェファソンと「暗室」のことを言わなきゃ",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_100"] = "この機会を失うわけにはいかない… お願い",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_120"] = "ここは過去の中の過去… 私の力 これ以上持つのかな?",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_130"] = "私のことはどうでもいい。 クロエを助けなきゃ!",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_140"] = "最低",
  ["Act_E5_2A_ArtClass_DanielTable_Look01_Max_010"] = "レイチェル… ごめんね…",
  ["Act_E5_2A_ArtClass_FocusBoundaries_Look01_Max_010"] = "写真の境界を超えることはできない。 この中でできることをしないと",
  ["Act_E5_2A_ArtClass_FocusWithinFocus_Scripted_Max_010"] = "えっと… 今 私は写真の中の写真の中にいる…?",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_010"] = "これがすべての始まりだったんだ…",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_020"] = "夢なら覚めてほしいよ…",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_030"] = "たった 1 週間が 5 年くらいに感じる…",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_040"] = "ジェファソンを見るのも嫌… えらそうに笑って",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_070"] = "今すぐみんなにバラして アイツが慌てるとこ見たいけど… |デイビッドに任せるべきだよね",
  ["Act_E5_2A_ArtClass_Ipad_Look01_Max_010"] = "ビクトリア… 大事なカメラだもんね。 待ってて…",
  ["Act_E5_2A_ArtClass_Ipad_Look02_Max_015"] = "高級品を持ってるからって 自分を特別だと思わないで… |今度はケイトを傷つけたりさせない",
  ["Act_E5_2A_ArtClass_JeffersonCamera_Look01_Max_010"] = "今すぐ壊してやりたい",
  ["Act_E5_2A_ArtClass_MaxBag_Interact01_Max_020"] = "学校のパンフレット… デイビッドの番号が記載されてるはず",
  ["Act_E5_2A_ArtClass_MaxBag_Look01_Max_010"] = "プリントがたくさんあったはず… デイビッドの番号 書いてないかな",
  ["Act_E5_2A_ArtClass_MaxBag_Look02_Max_030"] = "ないな…",
  ["Act_E5_2A_ArtClass_MaxBag_Look03_Max_040"] = "あった!",
  ["Act_E5_2A_ArtClass_MaxCamera_Look01_Max_010"] = "まさか私の自撮りが 時空を曲げるきっかけになるなんて…",
  ["Act_E5_2A_ArtClass_MaxDiary_Look01_Max_010"] = "日記 書いててよかったな",
  ["Act_E5_2A_ArtClass_MaxNotes_Look01_Max_010"] = "これが全部終わった後も まだ写真を好きでいられるかな… |「君は筋がいい」か。 ムカつく",
  ["Act_E5_2A_ArtClass_MaxPhone_Look01_Max_010"] = "デイビッドの番号さえあれば ジェファソンはすぐに刑務所行き…",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_010"] = "やった! すぐデイビッドに連絡しよう…って 電話番号知らないよ…",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_020"] = "デイビッド… 今回だけは キレてくれることに期待してるよ… |早くあいつを捕まえて",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_030"] = "「日常ヒーロー」コンテストの写真を出して すべてを終わらせよう |これで めでたし めでたし… になるはず",
  ["Act_E5_2A_ArtClass_PaperBall_Look01_Max_010"] = "もう誰にもいじめさせないから",
  ["Act_E5_2A_ArtClass_PhotoStuff01_Look01_Max_010"] = "もう全然いいと思えない",
  ["Act_E5_2A_ArtClass_PhotoStuff02_Look01_Max_010"] = "カメラに罪はないけど ジェファソンが使ってると思うと…",
  ["Act_E5_2A_ArtClass_Poster01_Look01_Max_010"] = "「日常ヒーロー」になるためにも あいつを止めなきゃ",
  ["Act_E5_2A_ArtClass_Poster02_Look01_Max_010"] = "これまでに 何人を犠牲にしたんだろう…",
  ["Act_E5_2A_ArtClass_Poster03_Look01_Max_010"] = "あなたの時代はもう終わったの",
  ["Act_E5_2A_ArtClass_TextBook_Look01_Max_010"] = "ビクトリア… 友達になれたかもね…",
  ["Act_E5_2A_ArtClass_TextBook_Look01_Max_015"] = "ビクトリア… 本当はこんなこと思ってたんだ…",
  ["Cue_E5_2A_ArtClass_BellRing_Hayden_030"] = "どうかな…? なにしろ俺のは、マン・レイとマンガの融合だぜ?",
  ["Cue_E5_2A_ArtClass_BellRing_Jefferson_010"] = "みんな 「日常ヒーロー」コンテストの期限が迫ってるぞ |優勝者は学校の代表としてサンフランシスコに連れていく |プロの世界に自分を売り込むチャンスだ |ステラも アリッサも 早く出すように |テイラー。 君もまだだな? 期待してるぞ |マックスも 言い訳は通用しないからな",
  ["Cue_E5_2A_ArtClass_BellRing_Taylor_020"] = "そんな暇ないよ。 どうせビクトリアが選ばれるに決まってるし",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_003"] = "あ… うん そうだ。 簡単すぎたかな",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_007"] = "うん…? どういう意味かな…?",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_008"] = "何か… 嫌なことでもあったのかな…? もう一度チャンスをあげよう",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_009"] = "今のは聞かなかったことにするから もう一度答えてごらん",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_014"] = "あー… では 授業を進めるが… 「ダゲレオタイプ」は銀板写真とも呼ばれている |人物の顔を鮮明に写し出すことができる技法だ |予習範囲を最後まで読めば詳しいことが書いてあるぞ |マックスは… ちゃんと読んできたみたいだな",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_015"] = "何を言いたいのかよく分からないが… |とにかく 「ダゲレオタイプ」は銀板写真とも呼ばれている |人物の顔を鮮明に写し出すことができる技法だ |予習範囲を最後まで読めば詳しいことが書いてあるぞ |マックスは… ずいぶんじっくり読んできたみたいだな",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_016"] = "あー… うん 話を進めよう。 「ダゲレオタイプ」は銀板写真とも呼ばれている |人物の顔を鮮明に写し出すことができる技法だ |予習範囲を最後まで読めば詳しいことが書いてあるぞ",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_017"] = "あー… うん 確かに |そうだな。 まあいいだろう |とにかく 「ダゲレオタイプ」は銀板写真とも呼ばれている |人物の顔を鮮明に写し出すことができる技法だ |予習範囲を最後まで読めば詳しいことが書いてあるぞ |マックスは…時間がなかったようだが…",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_018"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_018",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_002"] = "ダゲレオタイプ",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_004"] = "「ダゲレオタイプ」です。 彼は誰かみたいな偽善者じゃなかった",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_005"] = "人間を「とらえる」なんて言い方 悪趣味だと思います",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_006"] = "さあ? こんな授業 聞く意味ないし",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_010"] = "さあ? どうでしょうね",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_011"] = "ただモデルの写真を撮るだけで 芸術家ぶる人もいるってことです",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_012"] = "分かりましたよ… ダゲレオタイプでしょ? くだらない…",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_013"] = "先生。 もう時間がありませんよ… もうすぐ授業 終わりですし",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Jefferson_010"] = "ダメだ、ビクトリア、宿題を免除することはできない |コンテストにはこのクラスの全員が参加するんだ。 特別扱いは、できないよ",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Jefferson_030"] = "君はコンテストに応募した。 それだけでも十分有意義だ |誰が代表に選ばれても この先チャンスはいくらでもある |君たちの熱意をくじくつもりはないが |先生は 写真の世界は厳しいという現実も知ってもらいたいと思ってるんだよ |チャンスというのは誰にでも 公平に訪れるべきだ。 違うかい?",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Victoria_020"] = "それは分かってます。 ただこの写真を撮るのすごく大変だったんです |先生なら分かってくれるでしょう? |「日常ヒーロー」コンテストはとても有意義なイベントだと思います |どうしても代表に選ばれたくて…",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Victoria_040"] = "分かってます。 私は自分の才能を世に発表したいだけです",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_020"] = "えーっと…",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_060"] = "（ビクトリアをなだめて）まあまあ。 マックス どうした?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_120"] = "僕は… ノーコメントだよ…",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_150"] = "マックス どうしたんだい 唐突に…",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_010"] = "先生。 話があります",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_040"] = "ごめん。 でも もうそのくらいにしなよ",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_070"] = "ビクトリア |匿名の隠れみのを着て 人の動画をネット上にばらまくなんて 最低だよ |ビクトリアほど頭がよければ |その人の人生が壊れることぐらい 想像つくよね?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_080"] = "自分がそんなことされたら 耐えられる? |選択するのはいつだって 自分自身なんだよ |ビクトリアが本当は心の優しい人だって 私は知ってるよ",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_100"] = "才能あるんだから もっと自信持ちなよ |周りの人の足を引っ張るより |自分と同じ高さまで引き上げてあげるほうが ずっといいよ |ビクトリアなら それができる…",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_140"] = "気をつけてね",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_030"] = "ちょっと。 割り込まないでくれる?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_050"] = "はあ? あなた何様?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_090"] = "何… 私は… そんな…",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_110"] = "なにわけ分かんないこと言ってんの? |ジェファソン先生 なんとか言ってください",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_130"] = "私 もう行きます",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_020"] = "えーと…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_060"] = "まあまあ。 マックス どうした?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_120"] = "僕にふられても… 困ったな…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_150"] = "いやあ まさに正論だったが… |いったいどうしたんだ…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_170"] = "ああ えっと… ありがとう…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_190"] = "あー… うん |評価はまた改めてするが 提出してくれてうれしいよ |この学校にとってもいいことだからね |恐怖を克服して作品を世に出すことが |アーティストとしての第一歩だ |大事なのは… 無垢であること… |そう思わないかい?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_210"] = "あー… とにかく よかった |金曜日には 先生と一緒にサンフランシスコに行けるかもしれないな!",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_230"] = "謙遜しなくていい。 何が起きても不思議じゃないんだ…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_010"] = "先生。 話があります",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_040"] = "たいした用事もないくせに。 あとにしてよ",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_070"] = "ビクトリア。 自分は匿名の隠れみのを着て |人の動画をネット上にばらまくなんて |卑怯だよ",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_080"] = "ほんの悪ふざけのつもりでも それが人の人生を壊すこともあるの |そんなことして楽しい? 自分が何をしてるか もっとちゃんと考えてみなよ",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_100"] = "自分に自信がないから どれだけ才能があっても満足できない |周りの人を引きずり降ろさないと気が済まないんでしょ",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_140"] = "そうしたら?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_160"] = "これ 「日常ヒーロー」コンテストの課題です",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_180"] = "いえ… 先生のためじゃないんで",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_200"] = "思いません",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_220"] = "そんなうまくいきませんよ",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_240"] = "ええ そうかもしれませんね…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_030"] = "ちょっと。 割り込まないでくれる?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_050"] = "なんですって?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_090"] = "何… 私は… そんな…",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_110"] = "あなた何様のつもり? |先生 なんとか言ってください",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_130"] = "何なの… 私 もう行きますね",
  ["Cue_E5_2A_ArtClass_JeffGivingLesson_Jefferson_050"] = "誰かを暗い部屋に座らせれば 絶望のシーンのできあがりだ",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_020"] = "あ… マックス",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_040"] = "なに…?",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_060"] = "マックス… 今週初めて明るい光が見えた気がする… 私… なんて言ったら…",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_080"] = "ありがとう |マックスがいてくれれば安心だよ",
  ["Cue_E5_2A_ArtClass_KateHug_Max_010"] = "ケイト…",
  ["Cue_E5_2A_ArtClass_KateHug_Max_030"] = "ケイト 聞いて",
  ["Cue_E5_2A_ArtClass_KateHug_Max_050"] = "その… 何があっても ケイトは一人じゃないって 伝えたくて |私はいつだって味方だよ |私だけじゃない 他にもたくさんの人が  あなたを大切に思ってる |そのことを忘れないでね",
  ["Cue_E5_2A_ArtClass_KateHug_Max_070"] = "何も言わないで |ただ ハグすればいいんじゃないかな",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_010"] = "ちょうど今 マックスが「自撮り」を撮ったぞ |現代ならではのセルフポートレートだが… |マックス 君は筋がいい",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_020"] = "肖像写真は 1800 年代初期から広く普及し 現在に至る |君たちの世代よりはるか昔から 「自撮り」の文化は存在したんだ |呼び方は変わったけどね |写真やアートの世界において人物の姿をとらえることは |常に極めて重要な要素でありつづけてきた",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_030"] = "マックス。 ついでだから君に聞こう |世界で最初のセルフポートレートの誕生に 大きく貢献した製版法は?",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_010"] = "あんな未来はイヤだ…",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_015"] = "やった 戻ってこれたんだ! よかった",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_020"] = "ケイト…",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_030"] = "何が「日常ヒーロー」コンテストよ…",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_040"] = "サンフランシスコになんか行かせない… |こんなヤツ 刑務所でもぜいたくなくらいだよ",
  ["Act_E5_3A_Plane_CHPrincipal_Look01_Max_010"] = "ウェルズ校長にはいい息抜きかもね… 今週は後始末で大変だったはずだし",
  ["Act_E5_3A_Plane_CHPrincipal_Look02_Max_020"] = "隣にジェファソンが座ってたかと思うと… 寒気がする",
  ["Act_E5_3A_Plane_ContestInvit_Look01_Max_010"] = "アーティストって呼ばれて 悪い気はしないな…",
  ["Act_E5_3A_Plane_IdleAnnouncementLines_Scripted_Max_010"] = "本物のアーティストは　こうやって飛び回るのが当たり前なのかな",
  ["Act_E5_3A_Plane_IdleAnnouncementLines_Scripted_Max_020"] = "この現実は まだ可能性のひとつ… ずっと居座るわけにはいかないはず",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_010"] = "今度こそ うまくいったよね?",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_030"] = "でもクロエは生きてる! それが一番大事 |一段落したらすぐに会いに行こう |もう絶対にそばを離れないよ…",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_070"] = "やだ! また鼻血? これ以上 負担をかけたら 私どうなっちゃうの…",
  ["Act_E5_3A_Plane_MaxScreen_Interact01_Max_010"] = "サンフランシスコまでもうすぐ…　緊張するけど やっぱり楽しみ…",
  ["Act_E5_3A_Plane_ObjectiveLines_Scripted_Max_010"] = "はあ… 大丈夫… ここは… 飛行機?",
  ["Act_E5_3A_Plane_PlaneNewsPaper_Look01_Max_010"] = "よかった",
  ["Act_E5_3A_Plane_PlaneNewsPaper_Look01_Max_015"] = "ジェファソンとプレスコット家の 終わりの始まり…",
  ["Act_E5_3A_Plane_PrincipalScreenSausage_Look01_Max_010"] = "うわー ホットドッグマン 超久しぶり… |昔クロエといつも見てて ゲームもやったな… |あの頃は良かった…",
  ["Act_E5_3A_Plane_Window_Look01_Max_010"] = "色んな現実の狭間にいて変な感じ。 すべてがぼやけて 遠くにある",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger01_010"] = "オレゴンでおきてる異常気象の話 読んだ?",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger01_030"] = "テレビでもその話ばかりだよ |日食 クジラの死体… 月が 2 つ出たって話もある |NASA も調査中だって",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger02_020"] = "ネットの話は信じない主義なんだ",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger02_040"] = "ウソくさいね。 実際に見たら 起こしてくれよ",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger03_010"] = "席 狭すぎでしょ",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger03_030"] = "金持ちをエコノミーに座らせてやりたい",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_010"] = "高い料金払ってドリンクもなし? ぼったくりだわ…",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_020"] = "儲かるわけね",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_040"] = "まるで耐久レース。 テレビで中継でもすればいい",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger05_010"] = "サンフラン 楽しみだ",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger06_020"] = "サンフランなんて呼ぶヤツいないから",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger07_010"] = "早く地面に降りてよ… 早く… 早く",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger07_020"] = "早く着いて…",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger08_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_3A_Plane_ChitChat02_IGE_Passenger08_010",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger08_030"] = "俺に話しかけるな",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger09_020"] = "口笛やめてくれない?",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger10_010"] = "ええと… 横 10 列は 6 文字。 ヒントは「青い」…ってそれだけ?",
  ["Cue_E5_3A_Plane_Extraction_Captain_010"] = "「シートベルトをお締めになり |着陸後ゲートに着くまで 電子機器のご使用はお控え下さい」 |「まもなく着陸に向け降下を開始します」",
  ["Cue_E5_3A_Plane_Extraction_Captain_020"] = "「サンフランシスコの天気は晴れ 気温は 15 度です」 |「本日はパシフィックウエスト航空をご利用いただき誠にありがとうございます」 |「またのご利用をお待ちしております」",
  ["Cue_E5_3A_Plane_Extraction_Max_040"] = "よく眠れました?",
  ["Cue_E5_3A_Plane_Extraction_Max_060"] = "少しだけ",
  ["Cue_E5_3A_Plane_Extraction_Max_080"] = "もちろん… 分かってます",
  ["Cue_E5_3A_Plane_Extraction_Max_100"] = "はい 今から楽しみです",
  ["Cue_E5_3A_Plane_Extraction_Principal_030"] = "まったく… |こんな狭い座席にずっと座っているくらいなら |車で行った方がマシだよ",
  ["Cue_E5_3A_Plane_Extraction_Principal_050"] = "いびきは うるさくなかったかね",
  ["Cue_E5_3A_Plane_Extraction_Principal_070"] = "そいつは申し訳ない |だが ジェファソンとプレスコットの件で今週は大変だった |君も分かってくれると思うが… |色々あってね",
  ["Cue_E5_3A_Plane_Extraction_Principal_090"] = "「日常ヒーロー」コンテストで |我が校を代表する君に聞かせる話ではなかったかな |私が一緒では楽しめないかもしれないが |サンフランシスコで素晴らしい経験ができるよう 願っているよ",
  ["Cue_E5_3A_Plane_Insertion_Max_010"] = "…ッ!",
  ["Cue_E5_3A_Plane_Insertion_Max_020"] = "クロエ… 生きてる… 生きてるんだ…!",
  ["Cue_E5_3A_Plane_Insertion_Max_025"] = "やった…",
  ["Cue_E5_3A_Plane_Insertion_Max_030"] = "みんな救えた",
  ["Cue_E5_3A_Plane_Insertion_Max_040"] = "ふう…",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Passenger09_020"] = "なんで? これで落ちたりしないでしょ?",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Passenger09_040"] = "何 逮捕でもするわけ?",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_010"] = "恐れいります 降下中は携帯の電源をお切り下さい",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_030"] = "航空規定ですので…",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_050"] = "どうか ご協力にお願いいたします",
  ["Act_E5_3B_ArtGallery_ArtBook01_Look01_Max_010"] = "会場のツァイトガイスト・ギャラリーは |サンフランシスコでもかなり歴史があるみたい…",
  ["Act_E5_3B_ArtGallery_ArtBook02_Look01_Max_010"] = "ここのアートも見に行けたらいいな…",
  ["Act_E5_3B_ArtGallery_ArtFlyer01_Look01_Max_010"] = "わあ クロエが好きそうなデザイン。 私もパンク系になれるかな…",
  ["Act_E5_3B_ArtGallery_ArtFlyer02_Look01_Max_010"] = "楽しそう! ウォーレンもきっと行きたがるだろうな",
  ["Act_E5_3B_ArtGallery_ArtFlyer03_Look01_Max_010"] = "どうせ報道すらされないんだろうな",
  ["Act_E5_3B_ArtGallery_ArtFlyer04_Look01_Max_010"] = "ベイエリアのアートはカッコいいな… 同じベイでも大違い",
  ["Act_E5_3B_ArtGallery_ArtFlyer05_Look01_Max_010"] = "着ていく服がないよ",
  ["Act_E5_3B_ArtGallery_ArtFlyer06_Look01_Max_010"] = "謎のままの方がいいモノもあるよね…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_010"] = "私 本当にサンフランシスコにいるんだ…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_020"] = "人の死を何度も見た後で 頭がついてこないよ…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_030"] = "クロエが今ここにいたらいいのに…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_040"] = "クロエがいなかったら ジェファソンとも戦えなかった…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_050"] = "写真に自信を持てって 言ってくれたのもクロエ…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_060"] = "レイチェルやケイトのことを思えば 写真を出すなんて大したことなかったな…",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_070"] = "この力はまだ謎だけど やっと正しい使い方ができたのかもしれない…",
  ["Act_E5_3B_ArtGallery_CHPrincipalWells_Look01_Max_010"] = "ウェルズ校長が来てくれてよかった |事件の後じゃ参加を辞退してもおかしくなかったのに…",
  ["Act_E5_3B_ArtGallery_Camera_Look01_Max_010"] = "うーん この構図は… とある天才写真家を思い出すね…",
  ["Act_E5_3B_ArtGallery_Champagne_Look01_Max_010"] = "クロエとこぼしたワインのこと 思い出すな…",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_010"] = "この人達の相手してる時間はないよ…",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_020"] = "クロエが今 私を必要としてるんだ",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_030"] = "心をしずめて… |周りには誰もいない… 誰も…",
  ["Act_E5_3B_ArtGallery_DonationBox_Look01_Max_010"] = "これは募金せざるを得ないよね",
  ["Act_E5_3B_ArtGallery_DownstairExhibitText_Look01_Max_010"] = "面白いけど… 彫刻ってよく分かんない",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork01_Look01_Max_010"] = "こんなの部屋に飾りたい… いつかね",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork02_Look01_Max_010"] = "なんか変なの…",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork03_Look01_Max_010"] = "すごい。 これひとつ作るのに どれだけ時間かかったんだろう…",
  ["Act_E5_3B_ArtGallery_ExhibitIntro_Look01_Max_010"] = "私の写真が展示されてるなんて ウソみたい…",
  ["Act_E5_3B_ArtGallery_Food01_Look01_Max_010"] = "おいしくなさそうな高級料理にも 慣れなきゃいけないのかな…",
  ["Act_E5_3B_ArtGallery_Food02_Look01_Max_010"] = "んー でもあのフルーツタルトは魅力的…",
  ["Act_E5_3B_ArtGallery_GuestBook_Look01_Max_010"] = "コメントを読めるっていいな… 意地悪なのもあるけど",
  ["Act_E5_3B_ArtGallery_Hipster01_Look01_Max_010"] = "キザな感じだけど 写真はちゃんと見てるんだよね…",
  ["Act_E5_3B_ArtGallery_Hipster02_Look01_Max_010"] = "かわいいな。 私は将来どんな格好してるんだろ…",
  ["Act_E5_3B_ArtGallery_IntroLines_Scripted_Max_010"] = "でも まさか本当に成功するなんて… |びっくり",
  ["Act_E5_3B_ArtGallery_IntroLines_Scripted_Max_020"] = "あの「暗室」から… |このギャラリーに飛んできた |これでいくつ目の別次元だろう |変な人生を送ってるな…",
  ["Act_E5_3B_ArtGallery_MaxLabel_Look01_Max_010"] = "「窓」 2013 年 マクシーン・コールフィールド… |ちょっと マクシーンはやめてよ…",
  ["Act_E5_3B_ArtGallery_MaxPicture_Look01_Max_010"] = "うれしい… 今日だけは自分をアーティストって誇っていいかな…",
  ["Act_E5_3B_ArtGallery_NeonArt_Look01_Max_010"] = "好みじゃないけど 手法としてはアリかな… やだ 私えらそうに",
  ["Act_E5_3B_ArtGallery_Newspaper01_Look01_Max_010"] = "この頃を思いながら 一生刑務所で暮らすんだ… いい気味",
  ["Act_E5_3B_ArtGallery_Newspaper02_Look01_Max_010"] = "ダニー・リーの記事だ…",
  ["Act_E5_3B_ArtGallery_Newspaper02_Look02_Max_020"] = "ダニー・リーの記事だ…",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_010"] = "余計なこと言わずに 笑顔でいれば大丈夫…",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_020"] = "注目されるの やっぱり苦手かも…",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_030"] = "クロエは無事だし ジェファソンも捕まった |それに自分の写真がギャラリーに展示されるなんて…",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_040"] = "クロエと見た映画で言ってた。「今を楽しめ」って",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_050"] = "一度は自分の作品がギャラリーに展示されてるとこ 見ておこうかな |次はいつになるか 分かんないもんね",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_060"] = "話し相手がいなくても 校長がいてくれるから安心だな… |学校の外ではこんなに気さくなんて",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_070"] = "今週はいろいろあったけど　今生きてることに感謝しなきゃ",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_080"] = "巻き戻しの力も しばらく封印しておいたほうがいいのかも…",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_010"] = "絶対ダメ… クロエがまた死ぬなんて… 助けに行かなきゃ",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_020"] = "こんなところにいる場合じゃない… 早くアルカディア・ベイに戻らないと",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_040"] = "コンテストの写真… 戻るにはあれを使うしかない",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_060"] = "コンテストはまたあるけど… クロエは一人しかいない",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_070"] = "コンテストの写真の中に戻って その写真を破いちゃえば… |今ここじゃなく アルカディア・ベイにいるはず",
  ["Act_E5_3B_ArtGallery_Receptionist_Look01_Max_010"] = "ギャラリーの人に自分の作品のことを話せるなんて 思ってもみなかった",
  ["Act_E5_3B_ArtGallery_SFCityMap_Look01_Max_010"] = "この地図 雰囲気があって素敵だな",
  ["Act_E5_3B_ArtGallery_SFLook_Look01_Max_010"] = "この街にいたら いい写真がいっぱい撮れそう",
  ["Act_E5_3B_ArtGallery_SubmarineFlyer_Look01_Max_010"] = "潜水艦の中で暮らすのって どんな気分かな… 閉所恐怖症になりそう",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_010"] = "わあ これ最高",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_020"] = "他の素晴らしい作品と一緒に展示されるなんて 夢みたい",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_030"] = "このギャラリーに住みたいよ",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_040"] = "ケルアックやビートニク達もこの場所にいたなんて 感動",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_050"] = "広い空間をうまく使ってる… 照明も完ぺき",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_060"] = "写真を買いたいって人がいたら いくらにしよう… |っていくらなんでも気が早いよ",
  ["Act_E5_3B_ArtGallery_WinnerList_Look01_Max_010"] = "私の名前だ… 他の入賞者もたくさん…|いや 他の「アーティスト」かな",
  ["Act_E5_3B_ArtGallery_ZeitgeistLogo_Look01_Max_010"] = "「今週の特別展示: マックス・コールフィールド」なんてね… |でも これって本当にすごいことだよ",
  ["Cue_E5_3B_ArtGallery_ArtTalk01_IGE_Woman02_020"] = "いくらなら出す?",
  ["Cue_E5_3B_ArtGallery_ArtTalk01_IGE_Woman02_040"] = "今や誰でも写真家ね",
  ["Cue_E5_3B_ArtGallery_ArtTalk03_IGE_Man05_010"] = "悲しくなってくる…",
  ["Cue_E5_3B_ArtGallery_ArtTalk03_IGE_Man05_020"] = "高校を思い出すよ…",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Man06_010"] = "ギャラリーがよくこんな一等地 借りれるな",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Man09_010"] = "「日常ヒーロー」の写真は買えるのかな…",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman05_010"] = "アートって よくわかんない",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman06_010"] = "私 アート大好き…",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman07_010"] = "ここに来るといつも刺激を受けるの…",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Man01_010"] = "すみません |君の作品のことを聞いてもいいかな…",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Man02_030"] = "やあ… 君の写真すごくいいと思うよ",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Woman01_020"] = "あなたがウワサのマックスさん? どんなカメラ使ってるか教えて!",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Woman02_040"] = "私の写真にアドバイスしてもらえる?",
  ["Cue_E5_3B_ArtGallery_CHMan01_QPhase01_Man01_001"] = "あれ もしかしてセルフポートレートの子? ああ 自撮りって言うのかな |被写体よりフォーカスを向けること自体 主題にするとは… |感心したよ",
  ["Cue_E5_3B_ArtGallery_CHMan02_QPhase01_Man02_001"] = "お あの自撮りの子か… いや良かったよ。 後で俺とお茶しない?",
  ["Cue_E5_3B_ArtGallery_CHMan04_QPhase01_Man04_001"] = "この度はおめでとうございます |写真雑誌「アイリス・イン」の者ですが |今度出す期待の新人特集に ぜひあなたもと思いまして |後ほど詳細を送ります |いやあ 素晴らしい作品でございました",
  ["Cue_E5_3B_ArtGallery_CHMan05_QPhase01_Man05_001"] = "この手の展示はいつも眠くなるんだが |今回は抽象的なものではなく |明確な内容で良かった |今年のツァイトガイストは |面白い企画が多いな",
  ["Cue_E5_3B_ArtGallery_CHMan06_QPhase01_Man06_001"] = "君 最終選考に残ったんだろ? 僕もだ! |ほんと最高だよな |キャリアの最初を飾るには文句なしだ",
  ["Cue_E5_3B_ArtGallery_CHMan09_QPhase01_Man09_001"] = "すまない |君の名前は覚えてないが パンフレットで作品を見て 素晴らしいと思ったよ",
  ["Cue_E5_3B_ArtGallery_CHMan10_QPhase01_Man10_001"] = "これまでの「日常ヒーロー」コンテストでも 今回は最高だ |どの写真も「時間」というものをよく捉えている… 実に素晴らしい",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_MaxUnderwear_012"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_MaxUnderwear_012",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_001",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_004"] = "いや… そんな有名だなんて…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_007"] = "学校で起きたことを考えると なんだか実感がなくて…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_008"] = "運がよかっただけで… まだ本物の写真家だなんて言えません",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_010"] = "それに引け目を感じるというか・・",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_013"] = "ジェファソンはすべてを巧妙に隠していました… 皆だまされたんです",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_016"] = "先生のせいでは… 知らなかったんですから",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_017"] = "ネイサンのことは言いましたよね… 信じがたい話だったでしょうけど",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_018"] = "ネイサンは銃を持っていたんです。 私が報告してれば こんなことには…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_022"] = "ええ… でも 今はネイサンと一緒に刑務所の中です",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_024"] = "あとは異常気象さえ解明できれば… |すべてが元に戻る気がします",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_025"] = "これは天罰なんじゃないかって思うんです… プレスコット家への",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_028"] = "また一からやり直しましょう 校長先生",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_003"] = "写真家として有名になった気分はどうかな?",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_005"] = "「千里の道も一歩から」だ |私はアーティストではないが 君への賞賛の声を聞いて学校としても誇らしいよ",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_006"] = "こんな時だからこそ祝うんだ",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_009"] = "謙遜しなくていい",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_011"] = "引け目を感じるのは私で十分だよ… |ケイト・マーシュの件はもっと積極的に対処すべきだったんだ |自分の力でよく乗り越えてくれた |ネイサンのことも もっと早く気づいていれば…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_014"] = "その代表が私だ。 知名度だけであんな男を雇うとは…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_015"] = "それに ジェファソンの評判は特に良かった… |彼にあれほどの問題があるとは… |警察が「暗室」で発見した写真には |言葉もない |被害者に申し訳ないよ…",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_019"] = "ああ だが… 校長が知らなかったでは済まされない",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_020"] = "信じなかったことを 一生悔いるだろう… |結局 私はプレスコット家に負けたんだ",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_021"] = "おそらく聞いても信じなかっただろう |プレスコット家は周りを操るのもうまい… |いや「うまかった」か",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_023"] = "ああ そして捜査はショーン・プレスコットの過去の不正にまで及んでいる |力と金が物を言うのもここまでだ |だが皮肉なことに ショーンもジェファソンの悪事は一切知らなかったらしい… |ヤツを教師に招いたのもショーンだった",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_026"] = "環境学は私の専門外だが 学校が元通りになってくれれば それで十分だよ",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_027"] = "私も「因果応報」を信じていてね。 これですべてが収まったと願いたいが",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_029"] = "さっきも言ったが 君はもう私と対等の大人だ |レイと呼んでくれて構わない |さて ビュッフェの用意ができたようだ |また後で",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_QPhase01_Principal_001"] = "失礼 食事制限のことを気にしている妻に電話しなくては |何を食べたか口外しないでくれよ",
  ["Cue_E5_3B_ArtGallery_CHReceptionist_QPhase01_Receptionist_002"] = "あら マックス・コールフィールドさん |あなたの 「日常ヒーロー」 素晴らしいですね |コンテストのなかでも特に際立ってますよ",
  ["Cue_E5_3B_ArtGallery_CHWoman01_QPhase01_Woman01_001"] = "あなたブラックウェルの生徒? |ホントは私も行きたかったんだ… |授業は面白そうだし たくさん学べていいな…",
  ["Cue_E5_3B_ArtGallery_CHWoman04_QPhase01_Woman04_001"] = "コールフィールドさん カリフォルニア大学の者ですが |もしよければ当校への推薦入学について 後でお話させていただけませんか?",
  ["Cue_E5_3B_ArtGallery_CHWoman06_QPhase01_Woman06_001"] = "あなたがブラックウェルの |「日常ヒーロー」ね |デトロイト美術学校の者なんだけど |来春の入学について |ぜひお話させていただけないかしら |あ、ウェルズ校長にはまだ内緒よ",
  ["Cue_E5_3B_ArtGallery_CHWoman07_QPhase01_Woman07_001"] = "あなたの写真すごく好き。 本当におめでとう |これからもっと注目されるといいわね",
  ["Cue_E5_3B_ArtGallery_CHWoman08_QPhase01_Woman08_001"] = "すいません あなたの写真に感激したってひと言伝えたくて |他のどの写真より |内に秘めたパワーを感じたんです |今後にも期待してますね",
  ["Cue_E5_3B_ArtGallery_CHWoman10_QPhase01_Woman10_001"] = "あなた大丈夫? |まあ 田舎からサンフランシスコみたいな大都会に来たら誰でもビビるわよね |あ 悪気はないのよ",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Daughter_040"] = "ちょっとパパ 何言ってんの? 使い捨てカメラって書いてあるんですけど?",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Daughter_060"] = "はいはい…",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_010"] = "この写真を見てごらん。 奥行き 色彩 ボケ味… |中判カメラにライカの 35mm レンズを使ったものだ |写真の見方を知っていれば そういった背景… |物語が必ず伝わってくるんだよ",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_030"] = "若い頃は熱心に写真を勉強したものだが 君には言わなかったかな? |実際才能もあったんだが 仕事のために諦めてね… |ここは実に面白い |写真に詳しい僕と来れて 君もラッキーだ",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_050"] = "いや つまり ライカの使い捨てなんだよ… |あー その… 子どもが親に口出しするんじゃない…",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Wife_020"] = "へえ あなたがそんなに詳しいとは知らなかったわ",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_010"] = "素敵な街ですね… |こんなに大きなギャラリーもあるし",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_030"] = "キャビアだけはお断りですけど…",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_050"] = "まだ私は… 大人の集まりに混じった |小さな子どもの気分です",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_090"] = "情けないな… これまで色々あって 少しは度胸ついたと思ったのに",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_020"] = "ビュッフェも豪華だ。 イベントの良し悪しは食べ物で分かる",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_040"] = "今日は君の晴れ舞台だ |出品者として堂々と好きに振る舞えばいい |業界の人にもなるべく多く話しかけて |チャンスを活かすんだ",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_060"] = "この 1 週間で 君も子どもではなくなった |今や一写真家として称えられる |立派な大人だよ |だからこそ それ相応の行動が求められる",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_070"] = "私などトップに立つことを目指して 若い頃から進んで前に出たものだ |周りには嫌われたがね…",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_080"] = "キャビアが嫌いなら私が食べてやるから |君は来場者と話してきなさい |ほら 怖がっていないで |また後で話そう",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Man04_010"] = "本当はマーク・ジェファソンが来るはずだったんだろ…",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Man04_030"] = "ショックだよな… 彼の写真持ってるのに…",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Woman04_020"] = "らしいね",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Woman04_040"] = "とっておいて… そのうちスゴい値がつくわ",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_010"] = "失礼 君がマックス・コールフィールド?",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_030"] = "僕はバークレー新聞で記事を書いてる |ダニー・リー |君の作品すごく良かったよ",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_040"] = "皮肉的自撮りっていうのは 今やありきたりだけど 君の作品には… |時間を超えた何かを感じるんだ |よかったら話を聞かせてもらえないかな |これ僕の名刺 |じゃあ また後ほど",
  ["Cue_E5_3B_ArtGallery_Journalist_Max_020"] = "ああ… ええ はい…",
  ["Cue_E5_3B_ArtGallery_Journalist_Max_050"] = "ええと どうも",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_010"] = "ごめんなさい…",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_020"] = "後でいいですか? すみません…",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_030"] = "今はちょっと…",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_050"] = "急いでるので…",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_010"] = "シンプルだけど 心に残る写真だな…",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_030"] = "アーティストは?",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_050"] = "へえ いいな。 ずいぶん大人びてる…",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Woman01_020"] = "インスタントカメラって 時を超えた懐かしさがあるのよね",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Woman01_040"] = "高校生… コンテストの作品みたい",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_010"] = "個性的! レトロいいよね",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_050"] = "あら ヒーローのご登場ね",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_090"] = "大丈夫? ちょっとボーッとしてたけど…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer2_020"] = "ああ インスタントカメラが欲しくなる。 フィルムが死ぬほど高いけどな",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer2_100"] = "おい 鼻血が…!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer4_040"] = "ええと…「マックス・コールフィールド、日常ヒーロー」",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Chloe_150"] = "マックスか! 大変だよ! マックスが見た竜巻! ホントに来てる!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Chloe_170"] = "マックス 怖いよ どうしよう!? |今 海岸の近くで…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_060"] = "どうも…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_080"] = "クロエ!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_110"] = "大丈夫です… 飛行機で… 時差ボケかな…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_130"] = "音消してた! バカ!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_140"] = "お願い… 電話に出て…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_160"] = "え? そんな… クロエ 今どこなの?",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_180"] = "クロエ! 聞こえる!? もしもし!?",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_190"] = "もしもし",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_200"] = "どうしよう 竜巻が本当に… |そこまで直せなかったんだ!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_210"] = "クロエが死んじゃう… 町もきっとメチャクチャ…",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_220"] = "絶対に止める方法がある… 絶対",
  ["Cue_E5_3B_ArtGallery_Weirdo_IGE_Man11_010"] = "露出もダメ… 構図もダメ… ダメな写真だ…",
  ["Cue_E5_3B_ArtGallery_Weirdo_IGE_Man11_020"] = "僕ならもっとうまく撮るね",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_010"] = "頭が今にも割れそうだけど… 私が… やらなきゃ…",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_020"] = "嵐からクロエを救うことだけ考えよう",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_040"] = "嵐さえなんとかすれば… せっかくここまで来たんだ",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_050"] = "もう身体がもたないよ… 倒れる前にやらなきゃ…",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_060"] = "この時間軸は完ぺきだったのに… |でも アルカディア・ベイから離れたことが失敗だったんだ…",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_070"] = "一体どうなってるの? 現実が… 壊れてきてる… 私が時空を歪めてる?",
  ["Act_E5_4A_MaxRoom_Photo_Look01_Max_010"] = "写真を破ればコンテストに勝つこともない… ここにいて クロエを救えるんだ",
  ["Act_E5_4A_MaxRoom_Photo_Look02_Max_020"] = "ひとつの出来事さえ変えれば サンフランシスコに行かずに済む… 簡単だよ",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_010"] = "ううっ… 頭が…",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_020"] = "耐えられないよ…",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_030"] = "なんとかしないと!",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_050"] = "これでコンテストには応募できない",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_060"] = "コンテストよりクロエのほうが大事",
  ["Cue_E5_5A_TownDestroy_NathanMessage_AnsweringMachine_010"] = "1 件の新しいメッセージがあります。 昨夜 午後 9 時",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Limpbow_010"] = "これまで再三警告してきただろう! |お前たちが自らの罪を顧みないから ついに神がお怒りになったのだ",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Limpbow_020"] = "なのに なんで俺が このラジオ局に閉じ込められなきゃならない!? |誰か早く助けろ! 俺は税金を払ってるんだぞ!",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Nathan_030"] = "マックス… 俺… ネイサンだ。 最後にこれだけは伝えたくて… |俺は… レイチェルも ケイトも… 傷つけるつもりはなかった… |誰も傷つけたくなかったんだ… |俺はみんなに利用されたんだ… 許してくれ |俺はジェファソンに追われてる… もうおしまいだよ |マックス 次はお前だ… 気をつけてくれ |すまなかった…",
  ["Act_E5_5C_DinerPark_BlockedEntrance_Scripted_Max_010"] = "これじゃ入れない… 別の入り口を探さないと",
  ["Act_E5_5C_DinerPark_DeadWhale_Look01_Max_010"] = "ああ… 世界が… 終ろうとしてる… |でも 私ならきっと…",
  ["Act_E5_5C_DinerPark_ExplosionLines_Scripted_Max_010"] = "イヤ! ダメ!",
  ["Act_E5_5C_DinerPark_ExplosionLines_Scripted_Max_020"] = "これじゃダメ! 火を止めないと!",
  ["Act_E5_5C_DinerPark_FireWarn_Scripted_Max_010"] = "大変… 火がこっちに向かってる… 何とかしないと",
  ["Act_E5_5C_DinerPark_Fire_Look01_Max_010"] = "火を消すの! 急いで!",
  ["Act_E5_5C_DinerPark_HomelessWoman_Look01_Max_010"] = "ああ… 私が警告していれば… |名前すら聞かずに… ごめんなさい",
  ["Act_E5_5C_DinerPark_HomelessWoman_Look01_Max_015"] = "いない… あの人 シェルターに逃げてくれたのかな… |私 名前も聞かなかった…",
  ["Act_E5_5C_DinerPark_Newspaper01_Look01_Max_010"] = "頑張れ ジュリエット…",
  ["Act_E5_5C_DinerPark_Newspaper02_Look01_Max_010"] = "本当の怪物は ここの住人だよ…",
  ["Act_E5_5C_DinerPark_NewspaperDispenser_Look01_Max_010"] = "嫌な話…",
  ["Act_E5_5C_DinerPark_ObjectiveLines04_Scripted_Max_010"] = "ヤバい… 火がダイナーに移りそう! なんとかしなきゃ!",
  ["Act_E5_5C_DinerPark_OfficerBerry_Look01_Max_010"] = "そんな… ベリー巡査… 私 間に合わなかったんだ…",
  ["Act_E5_5C_DinerPark_Sand_Look01_Max_010"] = "この砂で火が消えますように…",
  ["Act_E5_5C_DinerPark_Trucker_Look01_Max_010"] = "身動きできなくなってる! 困ってる人は助けなきゃ",
  ["Act_E5_5C_DinerPark_TwoWhalesBoard_Look01_Max_010"] = "のんびり食べてた頃に戻れたら…",
  ["Act_E5_5C_DinerPark_TwoWhalesNeon_Look01_Max_010"] = "このダイナーがこんなことになるなんて…",
  ["Act_E5_5C_DinerPark_WarrenCar_Look01_Max_010"] = "ウォーレンの車だけは無事みたい… よかった",
  ["Act_E5_5C_Diner_Booth_Zen_Max_010"] = "ちょっとだけでいい。 何もしない時間がほしい…",
  ["Act_E5_5C_Diner_Booth_Zen_Max_020"] = "ここでクロエに巻き戻しの力を見せたっけ",
  ["Act_E5_5C_Diner_Booth_Zen_Max_030"] = "結局これは何のための力? 何を学んだの?",
  ["Act_E5_5C_Diner_Booth_Zen_Max_040"] = "壊しては直すの繰り返し…",
  ["Act_E5_5C_Diner_Booth_Zen_Max_050"] = "でも 望んで得た力なんかじゃない",
  ["Act_E5_5C_Diner_Booth_Zen_Max_060"] = "それに ジェファソンは止められたんだ…",
  ["Act_E5_5C_Diner_Booth_Zen_Max_070"] = "あとは クロエさえ救えれば…",
  ["Act_E5_5C_Diner_Booth_Zen_Max_080"] = "今度こそ 絶対に…",
  ["Act_E5_5C_Diner_CHFrank_Look01_Max_010"] = "フランクが味方でよかった…",
  ["Act_E5_5C_Diner_CHFrank_Look01_Max_015"] = "フランクは悪い人じゃない… 嫌われて残念",
  ["Act_E5_5C_Diner_CHJoyce_Look01_Max_010"] = "おばさん みんなの世話して… フランクまで",
  ["Act_E5_5C_Diner_CHJoyce_Look01_Max_015"] = "おばさん みんなの世話してる…",
  ["Act_E5_5C_Diner_CHWarren_Look01_Max_010"] = "ウォーレンはいつも 人のために行動してる…",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_015"] = "私の気持ちはキスで… ちゃんと伝わったよね…",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_020"] = "友だちとして大切に思ってること 伝わってるかな…",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_025"] = "ウォーレンはどんな時も変わらずいてくれる…",
  ["Act_E5_5C_Diner_CanStock_Look01_Max_010"] = "食べ物に困ることはなさそうだけど…",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_010"] = "おばさん みんなに手を差し伸べて… この町の天使だよ…",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_020"] = "デイビッドと一緒だったら… きっと支え合えたのに…",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_030"] = "ウォーレンの何があっても変わらないとこ 好きだな",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_040"] = "この前はワッフルとオムレツのどっちを選ぶかで悩んでたのに",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_050"] = "1 週間で人生を数回 体験した気がする…",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_060"] = "考えるのはやめ。 まずは写真だよ…",
  ["Act_E5_5C_Diner_FirstAidSupplies_Look01_Max_010"] = "ウォーレン さすが |これで足りるといいけど…",
  ["Act_E5_5C_Diner_Jukebox_Look01_Max_010"] = "音楽なんて…",
  ["Act_E5_5C_Diner_Menu_Look01_Max_010"] = "ほんの数時間前まで みんなここで朝食を食べてたのに…",
  ["Act_E5_5C_Diner_NoExitLines_Scripted_Max_010"] = "ウォーレンに会って写真をもらうまで どこにも行けない",
  ["Act_E5_5C_Diner_ObjectiveLines05_Scripted_Max_010"] = "みんなが無事でうれしいけど |クロエを助けるにはウォーレンから写真をもらわなきゃ",
  ["Act_E5_5C_Diner_Pompidou_Look01_Max_010"] = "フランクにはポンピドゥーがついてるね…",
  ["Act_E5_5C_Diner_VortexFlyer_Look01_Max_010"] = "パーティはおしまい… 本当の世界の終わりが来ちゃったんだ",
  ["Act_E5_5C_StoreRoom_ArcadiaFlyer_Look01_Max_010"] = "そのために今 頑張ってるんだよ… ホントだよ…",
  ["Act_E5_5C_StoreRoom_FisherMan_Look01_Max_010"] = "助けてあげたいけど… ショックで話もできなさそう",
  ["Act_E5_5C_StoreRoom_FisherMan_Look02_Max_020"] = "ああ…",
  ["Act_E5_5C_StoreRoom_Flyer01_Look01_Max_010"] = "ダメ… 悲しくなる…",
  ["Act_E5_5C_StoreRoom_FuseBox_Look01_Max_010"] = "お願い 動いてね…",
  ["Act_E5_5C_StoreRoom_Magazine01_Look01_Max_010"] = "これが終わったらクロエと…",
  ["Act_E5_5C_StoreRoom_ObjectiveLines02_Scripted_Max_010"] = "大変なことになってる…",
  ["Act_E5_5C_StoreRoom_ObjectiveLines03_Scripted_Max_010"] = "早くダイナーに行こう! ウォーレンの写真を手に入れなきゃ!",
  ["Act_E5_5C_StoreRoom_Sprinkler_Look01_Max_010"] = "電源を入れれば |スプリンクラーが作動するはず…",
  ["Act_E5_5C_StoreRoom_StoreLines_Scripted_Max_010"] = "渡れない。どこかに別の道はないかな",
  ["Act_E5_5C_StoreRoom_StoreRoomFire_Look01_Max_010"] = "まずは火を消さなきゃ 通れないよ…",
  ["Act_E5_5C_Street_BrokenTablet_Look01_Max_010"] = "事件は解決… でもバッドエンドかな…",
  ["Act_E5_5C_Street_CHAlyssa_Look01_Max_010"] = "アリッサがあの家に… 早く助けなきゃ",
  ["Act_E5_5C_Street_CHEvan_Look01_Max_010"] = "エバン 正気? 早く逃げなよ!",
  ["Act_E5_5C_Street_CHEvan_Look02_Max_020"] = "なんで… エバン… 私がつかまえてれば…",
  ["Act_E5_5C_Street_ChildrenDrawing_Look01_Max_010"] = "この子たちがどうなったかは考えたくない…",
  ["Act_E5_5C_Street_DeadPerson02_Look01_Max_010"] = "町の人がこんな姿に…",
  ["Act_E5_5C_Street_DeadPerson03_Look01_Max_010"] = "死が… 私についてまわってるの…?",
  ["Act_E5_5C_Street_DerailedTrain_Look01_Max_010"] = "うわ ダイナーに突っ込んでたかもしれない…",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_010"] = "やだ アリッサが危ない!",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_020"] = "エバン やだよ… 巻き戻して助けなきゃ…",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_030"] = "そんな… 今ので感電して…",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_040"] = "この人 移動させないと死んじゃう",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_020"] = "迷ってるヒマはない… やらなきゃ",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_030"] = "すごい嵐… 立ち止まっちゃダメ",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_040"] = "ウォーレンの写真を手に入れなきゃ!",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_050"] = "クロエは絶対に死なせない…",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_060"] = "でも この町を救うことなんて… 私にできるの?",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_070"] = "私が変えたのは 時間だけじゃない…",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_080"] = "ウォーレン おばさん どうか無事でいて…",
  ["Act_E5_5C_Street_ObjectiveLines01_Scripted_Max_010"] = "ウォーレンはダイナーにいる。 急ごう!",
  ["Act_E5_5C_Street_PanEstateFlyer_Look01_Max_010"] = "くだらない…",
  ["Act_E5_5C_Street_Plank_Look01_Max_010"] = "考えて! アリッサを助けるには…",
  ["Act_E5_5C_Street_StormStart_Scripted_Max_010"] = "みんなパニックに… 町が壊れていく… 私なら何かできるはず",
  ["Act_E5_5C_Street_WatchmenLogo_Look01_Max_010"] = "「よい 1 日を」。 そんなノンキなこと言ってる場合じゃないよ",
  ["Cue_E5_5C_Diner_AskPhoto_Max_020"] = "無事でホントによかった… |ネイサンをぶっ飛ばしたぐらいだから きっと大丈夫だとは思ってたけど",
  ["Cue_E5_5C_Diner_AskPhoto_Max_050"] = "私は… みんなを助けにきたの。 あの写真 持ってるよね?",
  ["Cue_E5_5C_Diner_AskPhoto_Max_070"] = "いいから聞いて",
  ["Cue_E5_5C_Diner_AskPhoto_Max_110"] = "私こそ… いつもありがとう",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_010"] = "こんなときにアレだけど… 本当に会えてうれしいよ…",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_040"] = "もっと早くああしときゃよかったよ |それにしてもさ 写真 1 枚のために よくこんな嵐のなか来たよね |別に… 俺を助けにきたってわけじゃないだろ?",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_060"] = "その前に…",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_080"] = "何があったんだ…? 前に駐車場でもはぐらかされたけど",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_090"] = "マックス… 俺には正直 何がどうなってるのかさっぱりだけど… |君なら必ずなんとかしてくれるって 信じてるから |マックスはホントにすごいよ",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_100"] = "しかし こんな歴史的瞬間に立ち会えるとは |しかも君と一緒に… 話してくれて ありがとう…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_002"] = "お前もな… これでポンピドゥーとレイチェルもいたら…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_003"] = "お前もな… あとはレイチェルさえいてくれたら…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_006"] = "で 俺が教えた情報は? レイチェルのこと何か分かったか?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_008"] = "まだ希望はあるさ。 しばらく休ませてくれ。 なんか疲れちまった |レイチェルはどこか遠くの太陽の下で幸せにしてるはずさ… |とりあえず ありがとうな。 あとは なるようになるのを待つしかないぜ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_010"] = "は? 竜巻に襲われ 足には穴が空き |犬は死んじまう… |そんでもってダイナーの床でくたばる前に最後に会うのがお前… |悪い冗談としか思えねえ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_011"] = "は? 竜巻に襲われ 足には穴が空いてる… |そんでもってダイナーの床でくたばる寸前に会うのがお前… |悪い冗談としか思えねえ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_012"] = "おい ウソだろ… そ そんな レイチェルが… ありえねえ… |そうだ お前になんで分かるんだ?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_013"] = "くだらねえウソつきやがって |んなわけねえ… 町を出ただけだ… |なんでお前に分かる? おいッ!?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_015"] = "ネイサン!? クソっ あんなイカレたガキ 相手にするんじゃなかった! |ポンピドゥーさえ嫌ってた! |見たのか…? レイチェルを?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_016"] = "どうせ あの盗っ人とお前はレイチェルを見つけられなかったんだろ?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_017"] = "どうせクロエとお前は レイチェルを見つけられなかったんだろ?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_019"] = "もういい! 頼むからどっか行ってくれ |お前の顔なんて見たくない。 さっさと消えろ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_022"] = "死因は? どうやって殺されたんだ?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_024"] = "クスリ? まさか… 俺があいつに売ったやつか? |俺が… 俺が殺したようなもんじゃねえか! そんな…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_025"] = "なんてことを…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_027"] = "そのジェファソンとかいう野郎はどこだ!",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_030"] = "レイチェル… なんで… 彼女は俺の人生で唯一の救いだった |そりゃ俺には若すぎたし… いつかは終わると思ってた |でも こんな形はあんまりだ… |夢を追う彼女を 俺はずっと応援したかっただけなのに",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_032"] = "クロエとレイチェルは… 仲がよかった… 俺は妬いてたんだ…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_034"] = "俺だけじゃないさ… レイチェルにはクロエがいた",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_035"] = "でも今は… レイチェルの気持ちが分かる… |クロエは大したタマだよ |俺に助けを求めてまで レイチェルを探そうとしたんだ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_037"] = "いつだったか親父が言ってた |「義とされて家に帰れ」 |聖書の一節で 正しいことをしろって意味だ… |同感だよ |お前のおかげで |少しはそうできそうな気がする…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_038"] = "誤解するなよ。 お前を気に入ったわけじゃねえ… でも 嫌いでもねえよ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_001"] = "フランク 無事でよかった",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_004"] = "ごめんなさい。 嵐のせいで調べてる時間がなくて…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_005"] = "フランク… すごく言いにくいんだけど… |レイチェルは その… 死んだの",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_007"] = "あなたに教えてもらった名前から ある納屋を特定できた |そこはマーク・ジェファソン先生の秘密の撮影部屋で… |彼はネイサンを利用して生徒たちの自由を奪い… 撮影してたの",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_009"] = "フランク 無事でよかった。 大丈夫?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_014"] = "すべての手がかりがマーク・ジェファソン先生に行き着いた |彼はネイサンを使って生徒たちの自由を奪い… |秘密の撮影部屋でその姿を撮ってたの",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_018"] = "えっと… それどころじゃなくなって… ほら 嵐でバタバタして |フランク… その… ごめんなさい",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_020"] = "うん… フランク 私 何て言ったらいいか… |ネイサンがジェファソンに認められたくて 殺してしまったの…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_021"] = "ううん… でもネイサンがジェファソンに認められたくて 殺してしまったの… |レイチェルを…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_023"] = "クスリを… 過剰摂取させて…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_026"] = "今さら関係ないよ。 レイチェルはもういない",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_028"] = "死んだよ… もう終わったんだ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_029"] = "捕まったよ… もう終わったんだ",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_031"] = "うん… クロエも同じ…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_033"] = "うん… レイチェルもあなたを大切に思ってたよ…",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_036"] = "クロエが聞いたら喜ぶよ",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_001"] = "マックス… 本当にレイチェルは…? 悪い あとにしてくれ",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_004"] = "悪いが あとにしてくれ。 また話す機会があればいいけどな",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_005"] = "おい 聞こえてなかったのか 二度とお前の顔は見たくねえんだ",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_002",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_003",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_002"] = "ようやく一段落ついたと思ったらこれだよ… クロエは?",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_007"] = "この嵐の中 行かせるわけないだろ |今はクロエと… デイビッドがどこかで無事であることを祈るしかないよ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_008"] = "ああ よかった… ずっと気が気じゃなくてね… |こうしてる間に 今度はクロエが危ない目にあうんじゃないかって…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_009"] = "気にするのはよしな。 この竜巻はあんたのせいじゃない…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_011"] = "心配いらないよ。 デイビッドは立派な大人だし 色んな経験も積んでるんだ |そうは見えなくともね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_013"] = "あんたは人のいい面を見ようとしただけ |デイビッドにも見習ってほしいね。 それに 今はそれどころじゃないよ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_015"] = "今週の出来事を振り返ると そう思うのも無理ないよ",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_017"] = "あんたは正しいことをしただけ |以前からデイビッドの監視好きは度が過ぎるんじゃないかと思ってたけど… |今は反省してるようだしね |ここにいてくれたらよかったのに…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_019"] = "今週の出来事を振り返ると そう思うのも無理ないよ |私は家庭崩壊の危機にも面してるけど |デイビッドを追い出したのは間違いだったのかね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_021"] = "それはよかった… でも あの人のやり方に納得できない時もあるし… |正直 クロエへの暴力は許せない |一度あることは二度あると言うし…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_023"] = "私は苦労に慣れてる… ただクロエにはあまりにも早すぎた |このうえデイビッドにまで苦しむ必要はない… |マックスの言うとおり |決断すべきなのかもね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_024"] = "それはよかった… |でも あの人のやり方には納得できなかったり… 恐怖を感じる時もある",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_026"] = "今週を振り返ると そう思うのも無理ないよ |私は家庭崩壊の危機にも面してるけどね",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_028"] = "嬉しいことを言ってくれるよ |あんたのご両親もさぞ誇らしいだろうね |あのデイビッドが褒めるだけのことあるわ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_030"] = "それはよかった… |デイビッドは戦争の重荷を抱えているけど 本心から人を助けたいと思ってる |クロエをぶったあと カウンセリングを受けることにも同意したしね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_031"] = "それはよかった… デイビッドは戦争の重荷を抱えているけど |本心から人を助けたいと思ってる |一緒にカウンセリングを受けることにも同意したしね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_033"] = "デイビッドとクロエが仲よくしてくれたら それ以上に嬉しいことはないよ… |でも もう どうしたらいいのか… |早く嵐が収まってほしいよ… この町を離れてやり直したほうがいいのかもね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_035"] = "そうだね… それに彼はウィリアムじゃない |出会った頃を思い出すよ… あの頃 私は人生を諦めかけてた |でもあの人の愛が力をくれたんだ… 私を必要としてくれた |やっぱりあの人を想う気持ちは変わらないよ 帰ってきてほしい |早くそう伝えたいね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_038"] = "そうね… 前にも言ったけど あの人は誤解されやすいだけなんだ |クロエもいつか分かるといいけどね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_039"] = "それを聞いて安心したよ… デイビッドは誤解されやすくてね… |みんな彼の悪い面しか見ない… |けどマックスはいい面を見てくれた。 私が愛する一面を…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_001"] = "おばさん 大丈夫?",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_003",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_004"] = "その… 探してくるよ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_005"] = "クロエなら… 大丈夫。 電池が切れる直前に メール送ってきたの",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_006"] = "こんなことになってしまって…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_010"] = "ううん… それだけじゃなくて デイビッドの件も…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_012"] = "別にデイビッドの味方をしたつもりはなかったの…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_014"] = "うん… |でも なんかいろんな災が束になってこの町に降りかかってきてるみたいで…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_016"] = "ごめんなさい。 私がデイビッドに余計なこと言わなければ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_018"] = "早く元の日常を取り戻したい…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_020"] = "デイビッドは私を… その… 嵐から救ってくれた |不器用だけど根はいい人なんだと思う。 後はおばさん次第だよ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_022"] = "うん… そうだね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_025"] = "大変だとは思うよ…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_027"] = "おばさんは家族のためにたくさん頑張ってる… |もし私のお母さんだったら… |すごく誇らしい",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_029"] = "デイビッドは私を… その… 嵐から救ってくれた |不器用だけど クロエのことも本当に心配してて… |デイビッドにはおばさんが必要だよ |きっとおばさんだって…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_032"] = "いろいろ考えたんだと思う… |それだけおばさんとクロエのことを大切に思ってるんだね…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_034"] = "デイビッドは本物のヒーローだよ。 彼はおばさんを幸せにしたいだけ… |だから おばさんとクロエのためなら なんでもするはず…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_036"] = "デイビッドはおばさんを愛してるし 必要としてるよ",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_037"] = "デイビッドは本物のヒーローだよ |戦争ではきっと大変な体験をしたんだよね… |それに 辛いときに自分を信じることができたのはデイビッドのおかげだよ",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceQuickPhase_Joyce_001"] = "ここにいる人たちの世話をしないといけないから 今は仕事に戻らせて…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDialQuickPhase_Warren_001"] = "マックス… とんでもない 1週間を過ごしてたんだね…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_001"] = "ちゃんと話すよ… でも詳しい説明は抜き。 私のこと信じてくれる?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_003"] = "思うに この嵐は… |すべては… 私が時間を巻き戻す力を得たときに始まったの… |偶然なんてことはありえないよね?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_004"] = "過去に戻る必要があるの。 ジェファソンはもうクロエを… 殺してしまった… |そんなの許せない… なんとかしないといけないの!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_005"] = "ジェファソンはネイサンを利用してて… |認められようとしたネイサンがレイチェルを殺しちゃったの… |でも… もう 2 人とも死んだよ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_010"] = "そんな… すべて… 私のせいなの?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_013"] = "ジェファソンはネイサンを利用して クスリとお金を手に入れてたの |私もジェファソンに捕まって… 縛られて… |クスリの力で無理やり写真を撮られた… |最低だよ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_015"] = "でも 私なら過去を変えることができる。 でしょ?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_016"] = "ジェファソンはネイサンを利用してて… |認められようとしたネイサンがレイチェルを殺しちゃったの… |それでネイサンも殺され… ジェファソンは捕まったよ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_018"] = "ジェファソンの授業中 竜巻でこの町が壊滅する夢を見たの |そしてトイレに行ったら 目の前で親友のクロエがネイサンに撃たれた… |ここまではいい?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_020"] = "そのとき時間を巻き戻せることに気づいた… |その後 いろいろあって ジェファソンが危険だったことが分かった",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_024"] = "死んだ。 でも過ちを直すには ジェファソンも元に戻さないと… ダメかな?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_025"] = "捕まった。 でも過ちを直すには ジェファソンも元に戻さないと… ダメかな?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_026"] = "ウォーレンは友だちでしょ? 信じてくれるよね? |これはクロエ以外に話したことないし… |クロエは… 今 私を助けられない…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_027"] = "この災害も全部… 私のせい?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_028"] = "こんな話 まともじゃないよね… でも 今頼れるのはあなただけなの |もっと時間があればよかったけど… |信じてくれる?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_032"] = "でも 力のことは何も分かってない",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_033"] = "もちろん。 でも 力のことはまだ何も分かってない",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_034"] = "魔法なのか 何なのか…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_035"] = "私もだよ ウォーレン",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_002"] = "当たり前だろ。 サクッと頼むぜ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_006"] = "嵐だけじゃないよ。 日食 鳥 クジラ 何もかもだ!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_007"] = "この嵐は… マックスが過去に戻ったから起きてるんじゃ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_008"] = "なんちゃって科学者の意見だけど |これはきっと 因果関係に基づくカオス理論的現象なんだと思う… |それで ジェファソンは? …もしかして あいつに何かされた?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_014"] = "マックス… すごく大変な思いをしたんだな… 君は誰よりも勇敢だよ |あのクソ野郎ブッ殺してやる… |ヤツは今どこだ?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_019"] = "もちろん。 続けて…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_021"] = "そんな… それで?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_022"] = "なんだよそれ… もっと詳しく聞きたいけど もう時間がないな…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_023"] = "すべての作用には反作用がある… |時間を巻き戻したり変えたりしたことで連鎖反応が生じたのかもしれない… |環境にも…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_029"] = "友だちどころか… こんな冴えないオタクを マックスはずっと人間扱いしてくれた |俺 前にも言っただろ? |いつだって君を信じるってさ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_030"] = "何言ってんだ。 別にマックスが望んでこうなったわけじゃないだろ",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_031"] = "信じるに決まってるだろ。 マックスのこと尊敬してるんだ |だから 君にも俺を信じてほしい",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_036"] = "魔法だろうがワームホールだろうが 何か大きいものの一部さ |科学ですべてを説明できると思ってたけど |結局 俺は何も知らなかっただけだ…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_037"] = "君の存在には理由がある… それを見つけることができるのは君だけだよ",
  ["Cue_E5_5C_Diner_CHWarren_WarrenMinorChoiceQuickPhase_Warren_001"] = "マックス もっと一緒にいたいけど 君にはやるべきことがあるから…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenMinorChoiceQuickPhase_Warren_002"] = "俺と話すより 今やらなきゃいけないことがあるだろ…",
  ["Cue_E5_5C_Diner_ChoiceHug_Max_010"] = "その前にハグしてもいいかな…",
  ["Cue_E5_5C_Diner_ChoiceHug_Max_040"] = "みっともなくなんかない。 尊敬してるから |私… これからは正しい選択をしてみせるよ… 絶対に",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_020"] = "もちろん",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_030"] = "ほら… みっともなく引き止める前に 行ってくれ",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_050"] = "それでこそ ヒーローだ",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_010"] = "ありがと…",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_030"] = "知ってるよ…",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_050"] = "これからは正しい選択をしてみせるよ… 絶対に",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_020"] = "これが最後だといけないから… その マックス…",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_040"] = "そっか",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_060"] = "それでこそ ヒーローだ",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_010"] = "おばさんを頼んだよ… フランクも",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_015"] = "おばさんを頼んだよ… 他のみんなも",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_030"] = "これからは正しい選択をしてみせるよ… 絶対に",
  ["Cue_E5_5C_Diner_ChoiceNothing_Warren_020"] = "任せなって。 さあ 行けよ",
  ["Cue_E5_5C_Diner_ChoiceNothing_Warren_040"] = "それでこそ ヒーローだ",
  ["Cue_E5_5C_Diner_Focus_Warren_010"] = "マックス… 気をつけてな",
  ["Cue_E5_5C_Diner_FrankDialogIntro_IGE_Joyce_010"] = "またあとで。 こっちの人も手当てをしてあげないと",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_010"] = "ったく こんなところで死にたかないぜ…",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_020"] = "俺もロスに行こうってときに…",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_030"] = "ポンピドゥーが一緒ならいいか…",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_035"] = "ポンピドゥーがいてくれたらな…",
  ["Cue_E5_5C_Diner_HealFrank_IGE_Frank_020"] = "いてえよ ジョイス",
  ["Cue_E5_5C_Diner_HealFrank_IGE_Frank_040"] = "泣き言言ってる場合でもないか… 悪いな",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_010"] = "じっとしてな… 少し痛いよ…",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_030"] = "はいはい ごめんよ",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_050"] = "大丈夫 何とかなるよ",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_OldMan_020"] = "クソッ!",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_OldMan_040"] = "いや こっちが悪かった… ありがとう…",
  ["Cue_E5_5C_Diner_InsertionDiner_Announcer_020"] = "…避難してください。 繰り返します。 これは訓練ではありません |E6クラスの竜巻警報が アルカディア・ベイおよび周辺地域に発令されています |緊急放送システムによる避難勧告…",
  ["Cue_E5_5C_Diner_InsertionDiner_Frank_040"] = "ポンピドゥー…",
  ["Cue_E5_5C_Diner_InsertionDiner_Frank_045"] = "ポンピドゥー… いい子だ…",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_030"] = "じっとしてな…",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_060"] = "マックス!",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_070"] = "ああ よかったよ 無事で! 大丈夫だったかい?",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_090"] = "なんとか持ちこたえてるけど 竜巻をやり過ごせるかどうか… |ベリー巡査や外の人たちはかわいそうに…",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_110"] = "さあ 入って… |私はこの人の手当てをしないと… |ウォーレンが救急用品を集めてくれて…",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_080"] = "はい。 おばさんたちは?",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_100"] = "ええ…",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_130"] = "ウォーレンは大丈夫?",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_150"] = "こんなの防ぎようがなかったよ",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_050"] = "マックス!",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_120"] = "あまりないですが これで全部です",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_140"] = "あれだけ前兆があったのにな。 雪 日食…",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_160"] = "大バカだよ。 予期すべきだった…",
  ["Cue_E5_5C_Diner_JoyceDialogIntro_IGE_Joyce_010"] = "マックス こっちで話しましょう…フランクを休ませないとね",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_010"] = "頼むから無事でいてクロエ… お願いだから…",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_020"] = "マックス… これが私たちの最後だと思うかい?",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_030"] = "ダイナーにいるのも運命なのかね…",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_040"] = "何言ってんだか… 今は目の前のことに集中…",
  ["Cue_E5_5C_Diner_PolaRewind_Max_010"] = "いいよ",
  ["Cue_E5_5C_Diner_PolaRewind_Max_020"] = "そんなことないよ。 じゃ 後で",
  ["Cue_E5_5C_Diner_PolaRewind_Max_030"] = "もしかして お酒飲んでた?",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_010"] = "わかってるわかってる 俺うざいよな。 1 枚でいいからさ",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_020"] = "んー…",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_030"] = "世界の終わりによーこそ お嬢さんたち。俺をエスコートしに来てくれたのかい…",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Alyssa_020"] = "分かってる!",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Alyssa_030"] = "うん 行くよ!",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Max_010"] = "ほらアリッサ! 手をつかんで!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Alyssa_010"] = "気をつけて!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Alyssa_030"] = "これでおあいこ! じゃあね マックス!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Max_020"] = "あ… 危なかった。 ありがとう アリッサ!",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Alyssa_010"] = "ありがと マックス!",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Alyssa_030"] = "おかげさまでね! 早く避難しよう",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Max_020"] = "大丈夫?",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Max_040"] = "一人で行って。 私は他の人を助けるから",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Alyssa_020"] = "ふざけないでよ! マックスが来るたびに 私ひどい目にあう…",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Alyssa_030"] = "だからもう――",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Max_010"] = "アリッサ 大丈夫? 今 助けるから!",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Alyssa_020"] = "お願い 早く! こんなとこで死にたくない!",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Alyssa_030"] = "何か探してきてよ",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Max_010"] = "アリッサ 大丈夫? 今 助けるから!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_010"] = "誰か助けて!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_020"] = "降りられない!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_030"] = "もう誰か助けてよ!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_040"] = "助けて!! 降りられない!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_050"] = "お願い 早くして!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_010"] = "ロバート・キャパよ 今に見てろ!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_030"] = "こんなチャンスを逃す手はないだろ! 見ろよ!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_050"] = "分かったよ… まったく…",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_060"] = "マックス! 未来でも見えてるのか! 危なかったよ",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_080"] = "「日常ヒーロー」の言うことは聞くよ… マックスも行こう!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_100"] = "自分の心配をしなよ。 まずは生き残らないと!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_020"] = "エバン 竜巻が見えないの? 早く逃げなよ!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_040"] = "死んだら写真も何もないよ! 早く逃げて!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_070"] = "いいから 嵐がおさまるまで安全な場所にいなよ",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_090"] = "他の人も助けなきゃ",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_010"] = "ロバート・キャパよ 今に見てろ!",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_020"] = "素晴らしい構図だ",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_030"] = "頼むぞ もう 1 枚だ…",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_040"] = "台風の目を捉えろ…",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_050"] = "これは傑作間違いなし…",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_010"] = "ああ もう やめてくれ…",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_020"] = "嵐はもうたくさんだ",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_030"] = "これで終わりなのか?",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_040"] = "いやだ… こんなとこで死ぬなんて…",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Fisherman_020"] = "息が… 息ができない…",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Fisherman_040"] = "町が死んでいく…",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Max_010"] = "しっかりして! 早くここから出ましょう",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Max_030"] = "さあ 出ましょう!",
  ["Cue_E5_5C_Street_Panic_IGE_Girlfriend_010"] = "お願い 動いて お願い",
  ["Cue_E5_5C_Street_Panic_IGE_Girlfriend_020"] = "ウソでしょ… 死なないで",
  ["Cue_E5_5C_Street_Panic_IGE_Man05_030"] = "頼む 誰かここから出してくれ…",
  ["Cue_E5_5C_Street_Panic_IGE_Man07_010"] = "もう終わりだ 全部おしまいだ…",
  ["Cue_E5_5C_Street_Panic_IGE_Woman01_010"] = "こ… こんなのありえない…",
  ["Cue_E5_5C_Street_Panic_IGE_Woman03_010"] = "なんなの これ… なんなのよ!?",
  ["Cue_E5_5C_Street_Panic_Man01_020"] = "おい やばいぞ!",
  ["Cue_E5_5C_Street_Panic_Man01_030"] = "危ない!",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_010"] = "おい そこの… えっと マット!",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_020"] = "頼む… 助けてくれよ",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_030"] = "おい! 置いてかないでくれ!",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_010"] = "おい! 誰かいないのか?",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_020"] = "お願いだ! 誰か 早く助けてくれ!",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_030"] = "死にたくない 助けてくれ!",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_020"] = "大丈夫ですか?",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_040"] = "もう行ったほうが…",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_060"] = "いえ 友だちを探してるので",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_010"] = "助かった… ありがとな",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_030"] = "ああ 早く逃げねえと |どっかのバカが線路を壊さなきゃ こんなクソみたいな町にいなかったのによ",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_050"] = "ああ 二度と帰ってくるものか… 乗ってくか?",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_070"] = "そうか 達者でな",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_020"] = "大丈夫ですか?",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_040"] = "もう行ったほうが…",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_060"] = "いえ 友だちを探してるので",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_010"] = "助かった… ありがとな",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_030"] = "ああ 早く逃げねえと。 いい加減 もうこんなクソみたいな町とはおさらばだ",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_050"] = "ああ 二度と帰ってくるものか… 乗ってくか?",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_070"] = "そうか 達者でな",
  ["Act_E5_5D_DarkRoom_BigChair_Look01_Max_010"] = "まだ縛られた感触が… |イヤだ 思い出すのやめよう",
  ["Act_E5_5D_DarkRoom_BondagePicture01_Look01_Max_010"] = "モデルになりたい女性は多かったはず… |でも ジェファソンにとってモデルはなりたくてなるものじゃなかった",
