  ["Act_E5_5D_DarkRoom_Picture01_Look01_Max_010"] = "こんなの 見たくないよ…",
  ["Act_E5_5D_DarkRoom_Picture03_Look01_Max_010"] = "うわ… 全部燃やしてやりたい…",
  ["Act_E5_5D_DarkRoom_Receipt_Look01_Max_010"] = "プレスコットのお金で セキュリティをさらに頑丈にしようとしてたんだ…",
  ["Act_E5_5D_DarkRoom_SaveTimeLine_Scripted_Max_010"] = "最初の最初まで巻き戻して… ワナを仕掛けてもいいかも…",
  ["Act_E5_5D_DarkRoom_Stereo_Look02_Max_020"] = "きっと刑務所ではこんな音楽流れないだろうね… いい気味",
  ["Act_E5_5D_DarkRoom_Syringe_Look01_Max_010"] = "見るだけで吐き気がする",
  ["Act_E5_5D_DarkRoom_VicBracelet_Look01_Max_010"] = "ビクトリアのブレスレット… これでネイサンに罪を着せるつもりだったんだ",
  ["Act_E5_5D_DarkRoom_WarningLines_Scripted_Max_010"] = "これじゃダメだ… 早すぎた!",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_020"] = "全部燃やされてる… 私の写真まで…",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_030"] = "そうだ! |ウォーレンが撮った写真を使えばいいんだ!",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_050"] = "ウォーレンの写真でクロエを救えるか… 試してみるしかない",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_060"] = "外に出てウォーレンに電話しよう |出てくれるといいんだけど…",
  ["Act_E5_5D_DarkRoom_ZeitgeistFlyer_Look01_Max_010"] = "ジェファソン… ギャラリーなんか二度と行けないよ",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_001"] = "ああ… だがこの部屋は… 異常だ",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_006"] = "しかし この野郎… あやしいとは思っていたが",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_009"] = "そんな… まさか…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_010"] = "よく無事だった…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_011"] = "プレスコット家の連中に気を取られすぎた… |網を広げすぎて |肝心なところを見落としていた",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_012"] = "教師を疑う生徒はいない",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_015"] = "ケイトの件でジェファソンを校長に報告したとき |気づくべきだったのかもしれない",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_016"] = "俺もてっきり ケイトの件で容疑者をネイサンだけに絞ってしまった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_017"] = "お前からしたら 俺も相当怪しく見えていたんだろう |ケイトの件は… 誤解されても仕方がなかった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_018"] = "それに… 俺はケイトを傷つけてしまった |あの子は俺と違ってまっすぐないい子だ |本人に直接謝りたい",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_019"] = "それに… ケイトの自殺は 俺の責任でもある… 一生自分を責め続けるだろう…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_023"] = "ネイサンが危険なのは分かっていた。 俺がもっと早く行動していれば…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_024"] = "過去を悔やんでいるのはお前だけじゃない |だが まさかお前とクロエだけでここまでやるとは… 俺にはできなかった |2 人でよく頑張ったな",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_025"] = "黒幕はすぐ近くにいたのに… |俺が気づいてさえいれば ジェファソンとネイサンの凶行を止められたはずだ…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_033"] = "まさか… クロエは俺を憎んでる |知ってのとおり 俺は… あの子に手をあげてしまった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_034"] = "まさか… クロエは俺を憎んでる",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_035"] = "俺とは大違いだ |元々 人と協力するのが苦手でな… 軍でもそれが問題になった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_037"] = "自分の振る舞いについて言い訳をするつもりはない |ベストを尽くしたつもりだったが… 力不足だった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_038"] = "よい父親になろうとも努力した… だが クロエには認めてもらえない",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_039"] = "よい父親になろうとも努力した… |だが ジョイスに捨てられて すべてを失った",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_044"] = "だとしたら うれしいことだ…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_045"] = "ああ… 分かってるよ",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_046"] = "いや 自宅にカメラを設置した俺のせいだ… ファイルも処分すべきだった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_047"] = "ああ… その気持ちはよく分かる",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_050"] = "また言い訳のように聞こえるかもしれんが… |戦場を経験した人間にとって |その後の人生は苦しいものだ |誰も理解してくれなかったが… |ジョイスだけが 俺を救ってくれた |希望をくれたんだ",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_052"] = "俺はクロエに無事でいてほしいだけだ |それと ジョイスには カウンセリングを受けると約束した |まずは… クロエに謝るよ |パパとは呼んでくれなくても せめて「クソオヤジ」はやめてもらえるように…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_004"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_004",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_005"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_005",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_002"] = "ジェファソンは… 私を殺すつもりで… ビクトリアはもう…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_003"] = "ジェファソンは私を殺すつもりで… |あなたが来なければ…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_007"] = "あなたは全員をあやしんでただけじゃ…?",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_008"] = "私は全然気づかなかった…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_013"] = "私もです…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_014"] = "ジェファソンは先生なんかじゃない。 結局 授業も 計画の一部だった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_020"] = "うん… ケイト きっと喜ぶと思います",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_021"] = "ケイトは確かに悩んでた… でも 追い詰めたのはネイサンとジェファソンです",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_022"] = "そんなことない… ケイトの自殺は ネイサンとジェファソンのせいです",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_026"] = "ネイサンとジェファソンは親子みたいな関係だったんです… |でもネイサンがレイチェルを殺しちゃって… |ジェファソンはネイサンにすべての罪を着せようとした",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_027"] = "ネイサンが銃を持ってたって校長先生に伝えたけど 信じてもらえなかった… |あきらめずにもっと食い下がればよかった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_028"] = "ネイサンが銃を持ってたこと |校長先生に言うべきだった |みんなが危険な目に遭ったのは 私のせいだ…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_029"] = "あなたがお手本になったのかも…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_030"] = "2 人で協力してきたから…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_031"] = "でも 後悔してるはず…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_032"] = "急に親子になれと言われても… 難しいですよね…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_036"] = "それはきっと辛いことがたくさんあったから…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_040"] = "クロエは頑固だから… あなたと似て",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_041"] = "あなたが家族を思ってることはよく分かる。 ただ もう少し… その…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_042"] = "私のせいで… その… ごめんなさい…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_043"] = "あのときは 怒りを抑えられなくて…",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_048"] = "あなたの味方をしてよかった",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_049"] = "おばさんには 私が間違ってたって伝えます |おばさんもちゃんと分かってるはず",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_051"] = "そして私はあなたに救われた |クロエもきっと… 喜んでくれるはず",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_030"] = "そうか… タバコに救われるとは 皮肉だな…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_040"] = "よし… このパソコンにどんな証拠が隠されているか確認しよう…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_080"] = "ああ。 そうするといい",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_090"] = "お前のように勇敢な子がクロエの親友で 俺もうれしい |さあ  いつまでもこんなところにいる必要はない",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_Max_020"] = "クロエは… えっと… 疲れたからちょっと一服するって言って… |いなくなった間に 私だけさらわれたんです |だから… 無事ですよ…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_Max_070"] = "私… ちょっと外の空気を吸ってくる… 電話もしたいし",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_010"] = "待て…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_015"] = "で クロエはどこだ?",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_030"] = "まさか そんな… |そんなバカな… |クロエが… 死んだ? |マックス 本当なのか? 勘違いじゃ…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_050"] = "昨日の夜…? 俺がホテルの部屋で自分の愚かさを嘆いている間に …",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_055"] = "昨日の夜…? あと少し早く気づいていれば…!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_060"] = "必ず守ると約束したのに… |ああジョイス… 俺を許してくれ… |クロエに伝えたかったことも… |まだ… クソッ!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_070"] = "貴様があの子を殺したのか!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_080"] = "俺の大切なムスメを…!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_100"] = "マックス… すまない… |お前には見せたくなかったが…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_120"] = "ああ… 俺はなんてことを… |何もかも無駄だった… |クロエ… ジョイス すまない… |俺は何もできなかった",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_140"] = "マックス… 外へ出ていなさい… |もうこんなところにいちゃいけない",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_020"] = "クロエは… クロエは… 死んじゃった…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_040"] = "昨日の夜… 廃品置き場で… |私の目の前で… |ジェファソンに殺されたの…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_090"] = "待って… ダメ!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_110"] = "痛みすら感じないよ… ってこっちのセリフだったね",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_130"] = "そんなことありません… そんなこと…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_150"] = "デイビッド… 助けてくれて ありがとう…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_010"] = "こんな… ひどすぎる…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_020"] = "貴様…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_030"] = "ただでは済まさん…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_040"] = "よくもこんなことを… イカレてる…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_050"] = "これで貴様も終わりだ",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_060"] = "レイチェル… なんてことを…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_070"] = "異常だ…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_080"] = "生きて警察に引き渡されるだけ幸運だと思え…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_010"] = "ふざけたまねを…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_020"] = "俺のクロエを…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_030"] = "クソ… ジョイスに何と言えばいいんだ…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_040"] = "これが夢だったら… どんなにいいか…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_050"] = "また失ってしまった… まただ…",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_060"] = "貴様… 何度でも殺してやる…",
  ["Cue_E5_5D_DarkRoom_DavidFight_David_080"] = "ジェファソン! あきらめろ!",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_010"] = "クソ… なんなんだ この部屋は…",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_020"] = "まさか… これはスタジオか…?",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_030"] = "ここまで異常だったとは…",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_040"] = "マックス… もっと早く助けてやりたかった",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_050"] = "プレスコット家が かんでるな…",
  ["Cue_E5_5D_DarkRoom_DavidIntro_Max_010"] = "あの…",
  ["Cue_E5_5D_DarkRoom_DavidIntro_Max_020"] = "大丈夫ですか?",
  ["Cue_E5_5D_DarkRoom_DavidJeffersonFaceOff_Jefferson_010"] = "銃がなければ お前など…",
  ["Cue_E5_5D_DarkRoom_DavidSpeak_BeforeDial_Max_010"] = "あの…",
  ["Cue_E5_5D_DarkRoom_DavidSpeak_BeforeDial_Max_020"] = "平気ですか?",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_010"] = "マックス 何てことだ…! |ケガはしていないか? 動けるか?",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_030"] = "礼はいい… |ここが分かったのもお前のおかげだ",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_040"] = "まずはこいつを拘束しないとな",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_060"] = "こいつだけは逃がすわけにいかん",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_070"] = "刑務所にぶち込んでやる |よくて終身刑だろう",
  ["Cue_E5_5D_DarkRoom_DavidUntie_Max_020"] = "はい… ありがとうございます… 助かった…",
  ["Cue_E5_5D_DarkRoom_DavidUntie_Max_080"] = "ジェファソン先生 |今度はあなたが\"捕らわれる\"番です",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_010"] = "分かった!",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_030"] = "よし!",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_050"] = "よし…",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_060"] = "おらよ!",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_030"] = "今 何と言った?",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_040"] = "まったく… 授業中もよく上の空だったが… |相変わらずだな |自撮りをするには 今が絶好のチャンスかもしれないぞ…? |かつての自分から 新たな自分へと 生まれ変わる瞬間の記録さ… |だが まずは 質問に答えてもらおう",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_050"] = "マックス 質問に答えなさい… 答えろ! 痛い目に遭いたいのかい?",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_070"] = "なかなかいい答えだ",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_080"] = "おや… 鼻血が出ているね |クスリの量が多すぎたかな。これは申し訳ない |だが どうせ死ぬんだ |鼻血ぐらいでいちいち騒ぐ必要もないだろう",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_010"] = "ウソでしょ…!",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_020"] = "日記が焼かれてる…",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_060"] = "あんたなんか死ねばいい",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_063"] = "あんたに言うことなんてない",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_066"] = "口が臭い",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_David_120"] = "動くな!",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_010"] = "その瞳孔… まるでシャッターのようだ… |その瞳に 僕の姿を焼きつけているんだね |しかし あの写真を破り捨てるとは… |あれほどの傑作ならコンテストで優勝できたのに …",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_020"] = "それと所持品は焼かせてもらったよ |つい やりすぎてしまった… |君のことは元々評価していたんだが…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_030"] = "ここ数日の間に 君は内気な少女からヒーローへと変貌した |一体… 何が君をそうさせたのか…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_040"] = "おっと… 外はすごいことになってるぞ…|本当… おかしな出来事ばかりだ…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_050"] = "恐怖を感じているね…? |最後のセッションを君と共にできて |とても光栄だ |今回のテーマが 見る者に伝わることを祈るよ… そう… 「若さの喪失」が…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_060"] = "君に授業をするのも… これが最後になるんだね…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_065"] = "君に授業をするのも… |これが最後になるんだね…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_070"] = "もう鼻血を出すこともない… 安心しなさい",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_090"] = "もういい… 何も言わないで…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_100"] = "大丈夫… 痛みすら感じないよ…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_110"] = "なにっ?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_130"] = "デイビッド・マドセン…! 危なかった…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_131"] = "デイビッド・マドセン… 警備員が警察のまねごとをするからこうなる… |身の程知らずめ",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_132"] = "デイビッド・マドセン! このバカめ… |でしゃばるからこういうことになるんだ…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_133"] = "悪いな マドセン…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_135"] = "せいせいしたよ… このクズは学校でも鼻つまみ者だった。 だろ?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_137"] = "元々気に食わないヤツだったが… 君もだろ マックス?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_140"] = "よし…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_142"] = "ミス・デジャヴ",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_144"] = "もう一度 いこうか…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_150"] = "身の程知らずが でしゃばりやがって",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_160"] = "デイビッド・マドセン…",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Max_080"] = "お願いです… やめて… やめてください… じゃないと大変なことに…",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_010"] = "ああ… ビクトリアなら旅立ったよ",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_030"] = "何を驚くことがある? 至極当然の結果じゃないか",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_050"] = "おいおい なんだその顔は",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_060"] = "あの女は僕を脅迫しようとしたからね… こうするよりなかった |当然 すべての責任はネイサンに負ってもらうよ。 彼にうってつけの役だ",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Max_020"] = "まさか…",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Max_040"] = "そんな…",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_010",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_020"] = "お願いです…",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_040"] = "やめて!",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_050"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_050",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_060"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_060",
  ["Cue_E5_5D_DarkRoom_JeffersonFight_Jefferson_020"] = "僕のジャマをするんじゃない!",
  ["Cue_E5_5D_DarkRoom_JeffersonFight_Jefferson_060"] = "殺してやる!",
  ["Cue_E5_5D_DarkRoom_JeffersonWarn_Jefferson_010"] = "何…? なぜわかった?",
  ["Cue_E5_5D_DarkRoom_JeffersonWarn_Jefferson_020"] = "いい加減 黙ってろ!",
  ["Cue_E5_5D_DarkRoom_MaxFree_David_040"] = "警察に連絡しないと",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_020"] = "クロエ…!",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_030"] = "ダメだ…",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_050"] = "ウォーレン!",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_060"] = "ダメ… 圏外だ…!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_010"] = "デイビッド 危ない!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_050"] = "そこに銃を隠してる!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_060"] = "デイビッド! テーブルを蹴って!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_070"] = "そのカメラを取って!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_080"] = "銃を拾って!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_090"] = "ビンを持って!",
  ["Cue_E5_5D_DarkRoom_MaxWishDrink_Jefferson_020"] = "いいとも。 君は大切なモデルだ",
  ["Cue_E5_5D_DarkRoom_MaxWishDrink_Max_010"] = "ノドが… 焼けつくようで… 水を飲ませてもらえませんか…",
  ["Cue_E5_5D_DarkRoom_MaxWishLight_Jefferson_020"] = "見上げた写真家魂だな… 最後だからこそ 妥協はできないか…",
  ["Cue_E5_5D_DarkRoom_MaxWishLight_Max_010"] = "照明… 消してもらえませんか? まぶしくて… いい表情がつくれないので",
  ["Cue_E5_5D_DarkRoom_MaxWishMusic_Jefferson_020"] = "最期まで雰囲気を大事にするとは… やはりアーティストだ",
  ["Cue_E5_5D_DarkRoom_MaxWishMusic_Max_010"] = "何か音楽をかけてもらえませんか… 安らかにいけるように…",
  ["Cue_E5_5D_DarkRoom_MaxWishPicture_Jefferson_020"] = "驚きだな… ようやく僕を理解してくれたようだね…",
  ["Cue_E5_5D_DarkRoom_MaxWishPicture_Max_010"] = "最後に… もう 1 枚撮ってください… 最高の被写体になりたいんです…",
  ["Cue_E5_5D_DarkRoom_MaxWish_Jefferson_020"] = "要望があれば 遠慮なく言ってくれたまえ",
  ["Cue_E5_5D_DarkRoom_MaxWish_Jefferson_040"] = "いい表情だ |そんな顔で頼まれたら 嫌とは言えないよ",
  ["Cue_E5_5D_DarkRoom_MaxWish_Max_010"] = "待って! 聞いて!",
  ["Cue_E5_5D_DarkRoom_MaxWish_Max_030"] = "最後に… ひとつだけ お願い… してもいいですか…",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_010"] = "助かった…",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_020"] = "やった!",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_030"] = "もしもし? ウォーレン?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_050"] = "聞いて… 昨日 駐車場で写真を撮ったでしょ? |あれ まだ持ってる?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_070"] = "それ いま必要なの! どこにいる?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_090"] = "すぐ行く",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_110"] = "分かってる… |でも私がなんとかするから そこで待ってて!",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_130"] = "よし 覚悟を決めて… 急いでダイナーに行かないと…",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_140"] = "ジェファソン先生… 悪いけど 使わせてもらいます",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_145"] = "ジェファソン先生… 悪いけど この車 もらいます",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_150"] = "デロリアンとはいかないけど…",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_155"] = "運転できるかな…",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_160"] = "でも本当に… 嵐が来たんだ!",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_165"] = "ウォーレンを探さなきゃ…",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_040"] = "マックス! 無事だったのか! 今どこだ?",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_060"] = "え? 持ってるけど… |そんなにいい写真じゃないよ…",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_080"] = "ツー・ホエールズ・ダイナーで ジョイスさんと一緒に足止めされてる |こんな嵐 生まれて初めてだよ…",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_100"] = "は? 何言ってんの! |危ないからそこから動いちゃダメだ |雨も風もまったくおさまりそうにないし… |さすがに ちょっとヤバいかもしれないぞ これ",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_120"] = "ちょっと…!",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_010"] = "もう 全然聞いてくれない… 巻き戻してやり直そう",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_020"] = "あと少しだったのに… もう一回試してみよう",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_030"] = "本気で説得すれば 絶対聞いてくれる… 親友だもん…",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_040"] = "力のことを知ってるんだから… 信じてくれるはず",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_002",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_004"] = "ネイサンが…? なんで分かんだよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_008"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_008",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_009"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_009",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_016"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_016",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_017"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_017",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_021"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_021",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_022"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_022",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_023"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_023",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_026"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_026",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_027"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_027",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_028"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_028",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_031"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_031",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_033"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_033",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_037"] = "ネイサンはレイチェルを殺したんだ。 絶対許さない。 マックスだってそうだろ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_038"] = "何があったんだ? 全部話してくれ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_042"] = "マジかよ… だったら 2 人で乗り込んでぶっ倒そう!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_043"] = "なら 標的をジェファソンに変えるだけだ |マックスがためらうのも分かる。 あたし一人でやるよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_044"] = "マジかよ… 悪い… あたしのせいだ… あたしが巻き込んだから |マックスをそんな怖い目に遭わせた… |ジェファソンの野郎… 絶対に殺してやる…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_046"] = "あたしの過去 5 年間がどんだけ悲惨だったか 分かってんのか…?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_048"] = "だったら 一緒に行こう |5 年前じゃない 今マックスが必要なんだ! |マックスの力と この銃があれば何でも思い通りになるって!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_050"] = "未来を作り替えた? それ… 何の話だよ?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_054"] = "要は未来は分かんないってことだろ |ジェファソンをぶっ殺せば それが現実になるだけだ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_056"] = "マックス 何が言いたいんだ?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_060"] = "分かってる。 あたしだって そんな状況になったらどうしていいか分かんないよ |でも こうして元に戻れたんだ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_062"] = "分かったよ… でも ジェファソンを野放しにしていいのか?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_064"] = "だから 警察は腐ってんだって! 逆にブタ箱に入れられんのがオチだ |ビビるのもムリないけどさ ジェファソンはあたしらで捕まえるしかないんだよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_066"] = "だったらいいとは思うよ。でも あたしはそんなきれいごと信じない |このままじゃレイチェルが浮かばれない… |あたしらで 直接かたきを討たないと…!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_069"] = "クソオヤジが…? |なんであんなヤツ信用すんだよ。 せっかく家から追い出したのに",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_070"] = "だからこないだ あいつの肩持ったのか? 冗談だろ?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_075"] = "それがホントなら 殴ったりしないだろ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_076"] = "あたしの部屋で怒鳴られたこと もう忘れたのか?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_077"] = "あたしの部屋で起きたこと もう忘れたのか?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_078"] = "マジかよ… 本当ならあたしが行くべきだったけど… |クソオヤジが助けてくれたのか…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_079"] = "クソオヤジは全員調べてただろ。 ケイトだって。 信用できるかよ |やっぱ あたしたちでやるしかない",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_085"] = "ウソだろ? あいつがママ以外の人間のこと 気にかけるとは思わなかった…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_086"] = "で どうすればいいんだ?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_090"] = "学校で習って 唯一ためになった言葉がある |「歴史に学ばぬ者は 過ちをくり返す」ってやつ… |やんなきゃダメなんだ。 あたし一人でも…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_091"] = "マックス ちゃんと話してくれ。 怒らないから…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_093"] = "パパに会ったのか?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_095"] = "あたしがそんなことを…? それはキツかったな… その… 悪かったよ…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_096"] = "分かった 信じる。 だってあたしは 何があってもマックスの親友だからな",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_097"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_097",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_David_067"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_David_067",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_073"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_073",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_081"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_081",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_001",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_003"] = "ネイサンはもう死んでる… クロエも危ないの",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_005"] = "そこにいたから…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_006"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_006",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_007"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_007",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_010",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_011"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_011",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_012"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_012",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_013"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_013",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_014"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_014",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_015"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_015",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_018"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_018",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_019"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_019",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_020",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_024"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_024",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_025"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_025",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_029"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_029",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_030",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_032"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_032",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_034"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_034",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_035"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_035",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_036"] = "クロエ… 死んじゃったら かたき討ちできないよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_039"] = "ジェファソンが レイチェルや他の生徒たちを誘拐したの |ネイサンも利用されてて… 殺された…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_040"] = "私… ジェファソンにクスリを注射されて 地下室に閉じ込められたの |ひどい目に遭ったけど なんとかここに戻ってきた… |もう二度と クロエを死なせるわけにはいかないから… |クロエだけは絶対に守るから!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_041"] = "マーク・ジェファソンは殺人鬼だったの…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_045"] = "クロエ… よく聞いて… |私たちもう… 過去を捨てて 未来を救うことだけに集中しないといけないの |じゃないと手遅れになる…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_047"] = "クロエ! 5 年前 私はクロエを置き去りにした… 私のせいでつらい思いをさせた |そのつぐないをしたいの |だからお願い 私からもう離れないで",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_049"] = "ダメなの… 失敗するたびにやり直したって 結局はうまくいかない |今回も やり直せば きっとまた何か悪いことが起きる |何度未来を作り替えても ひどい結果にしかならなかったの…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_051"] = "クロエ… 本当のことを話すね… |私 クロエの過去を変えたの |そしたら… すごくつらい選択を迫られることになって… その…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_052"] = "未来をよくしようと思ったのに… 悪い結果にしかならなかった…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_053"] = "な… なんでもない… |ただ 時間を巻き戻すたびに 新しい時間軸… 新しい運命ができて…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_055"] = "クロエ 違うの! 待って!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_057"] = "だから私… 別世界だろうが 別次元だろうが |クロエが苦しんでるの見てられなくて… |だから… その願いを聞いたの",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_058"] = "でも私にはできなかったよ… |だからこの時間軸に戻ってきたの… |もう一度 元気なクロエに会いたかったから…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_059"] = "ううん あっちのクロエの方がよっぽどきつかったよ |私はそんなの予想もしてなくて… |最悪の結果を招いてしまって… |もうクロエにつらい思いをさせたくないのに…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_061"] = "うん。 だから一緒に来て。 これからもずっと一緒にいられるように",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_063"] = "あとは警察に任せればいいよ。 証拠だって十分そろってるし…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_065"] = "クロエが生きてるだけで 他はどうでもいい… |ジェファソンにはそのうち罰が下るよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_068"] = "大丈夫! デイビッドに話せば ジェファソンを捕まえてくれるよ。 ね?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_071"] = "デイビッドは命の恩人だよ… |デイビッドが「暗室」に来なかったら 私 死んでた…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_072"] = "信じられないかもしれないけど デイビッドはクロエをすごく大事に思ってるよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_074"] = "デイビッドは独自にジェファソンを調査してたからだよ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_080"] = "お願い クロエ… 真相をつかんでるのはデイビッドだけなの |他に頼れる人はいない",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_082"] = "待ってよ クロエ! 話を聞いて!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_083"] = "でもクロエが殺されたって伝えたとき デイビッド すごくショックを受けてた |かける言葉もないぐらい…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_084"] = "でもクロエは無事だってウソついたとき デイビッド すごくホッとしてた| 本当のことを伝えてたら どうなってたか…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_087"] = "デイビッドに全部話すの。 ビクトリアが危ないってことも",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_088"] = "そうだよ。 だからよく聞いて。 もうすぐ私は この記憶をなくしちゃう。 丸ごと |だからクロエが私に説明して… |「写真を使って時空を超えたんだ」って |それからクロエの部屋で待機して デイビッドに全部話すの |そうすれば  あとはデイビッドがなんとかしてくれるはず…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_089"] = "分かってるよ…! でも いつまでも過去にとらわれちゃダメ",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_092"] = "私… クロエのお父さんが死んじゃった日に戻って… 事故を防いだの… |でもその代わりに クロエが交通事故に遭って…",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_094"] = "別世界のクロエは… 首から下が動かせなくなって… |もう長くは生きられない状態で… |私に… 「頼むから死なせてくれ」って…",
  ["Cue_E5_6A_Parking_DialChloeFail_Max_010"] = "クロエ!",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Chloe_020"] = "信じるよ。 だってあたしは マックスの親友だからな",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Chloe_050"] = "信じるかな…",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_040"] = "そうだよ。 だからよく聞いて。 もうすぐ私は この記憶をなくしちゃう |私たちはクロエの部屋で待機して それからデイビッドに全部話すの |あとはデイビッドがなんとかするはず… |今言ったことを あとで全部私に伝えて |「写真を使って時空を超えた」って言えば分かるから",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_060"] = "クロエを疑うわけないよ",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_070"] = "さあ 行こう",
  ["Cue_E5_6A_Parking_Insertion_Chloe_010"] = "バカバカしい… 行くぞ マックス",
  ["Cue_E5_6A_Parking_Insertion_Chloe_040"] = "おい… どうしたんだよ…",
  ["Cue_E5_6A_Parking_Insertion_Chloe_070"] = "えーと あたしも嬉しいけど… |今はネイサンを探して レイチェルのかたきを討つんだろ? |早く行くぞ",
  ["Cue_E5_6A_Parking_Insertion_Chloe_100"] = "歩きながら話せよ",
  ["Cue_E5_6A_Parking_Insertion_Chloe_120"] = "ったく… なんだよ",
  ["Cue_E5_6A_Parking_Insertion_Chloe_140"] = "巻き戻したんだな…? どうせヘマしたんだろ",
  ["Cue_E5_6A_Parking_Insertion_Chloe_160"] = "そもそも マックスがちゃんとサポートすれば |ネイサンに殺されずに済むはずだろ?",
  ["Cue_E5_6A_Parking_Insertion_Chloe_190"] = "って あの美術の先生か? 何言ってんだよ! ネイサンだって証拠があるだろ",
  ["Cue_E5_6A_Parking_Insertion_Chloe_195"] = "早くしないと また誰かが餌食になる。 行くよ",
  ["Cue_E5_6A_Parking_Insertion_Max_020"] = "クロエ!",
  ["Cue_E5_6A_Parking_Insertion_Max_050"] = "一緒にいるのが 嬉しくて…",
  ["Cue_E5_6A_Parking_Insertion_Max_080"] = "ウォーレン ごめん…",
  ["Cue_E5_6A_Parking_Insertion_Max_090"] = "クロエ 待って!",
  ["Cue_E5_6A_Parking_Insertion_Max_110"] = "いいから止まってよ!",
  ["Cue_E5_6A_Parking_Insertion_Max_130"] = "会場に入っちゃダメ。 入ると… クロエが死んじゃうから",
  ["Cue_E5_6A_Parking_Insertion_Max_150"] = "違うって…",
  ["Cue_E5_6A_Parking_Insertion_Max_170"] = "ネイサンじゃないの",
  ["Cue_E5_6A_Parking_Insertion_Max_180"] = "犯人は… マーク・ジェファソンなんだって",
  ["Cue_E5_6A_Parking_Insertion_Warren_030"] = "はい チ～～ズ～!",
  ["Cue_E5_6A_Parking_Insertion_Warren_060"] = "なんか俺ジャマっぽいね。 まあいいや それじゃ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_010"] = "マックス… 時間だ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_030"] = "マックス… いつまでも一緒にいよう",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_050"] = "ああ…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_060"] = "マックス… そばにいるから。 いつまでも…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_020"] = "関係ないよ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_040"] = "うん… 親友だもんね…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_070"] = "ずっと…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_010"] = "マックス… 時間だ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_030"] = "いいんだよ。 みんなを救うためには こうするしかない |ただ レイチェルのかたきだけは絶対 討ってくれ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_040"] = "人生最後にマックスと過ごせて あたしホント 幸せだったよ |マックスはあたしのヒーローだ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_060"] = "マックスも ありがとな… |ほら 早くしないと気が変わっちゃうだろ! |…1 つだけ頼む… |あたしのこと… 忘れないで…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_020"] = "クロエ ごめんね… こんなのイヤだけど… でも…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_050"] = "クロエ… ありがとう",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_070"] = "バカ…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_010"] = "マックス… 時間だ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_030"] = "いいんだよ。 みんなを救うためには こうするしかない |ただ レイチェルのかたきだけは絶対 討ってくれ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_040"] = "人生最後にマックスと過ごせて あたしホント 幸せだったよ |マックスはあたしのヒーローだ",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_060"] = "マックス ありがとな… |ほら 早くしないと気が変わっちゃうだろ! |…1 つだけ頼む… |あたしのこと… 忘れないで…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_020"] = "分かってる… クロエ ごめんね… こんなのイヤだけど… でも…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_050"] = "クロエ… これが最後だなんて…",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_070"] = "バカ…",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_003"] = "マックス! マックス! どうしたんだよ 起きろって!",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_010"] = "まったく… びっくりさせんなよな…",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_040"] = "そんなの気にすんな! |好きで力を手に入れたわけじゃないのに それを使ってあたしを助けてくれた |レイチェルはダメだったけど…",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_050"] = "でも その力のおかげで 見つけることはできた |マクシーン・コールフィールドはあたしのヒーローだよ",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_007"] = "クロエ…? ごめん… なんか 気絶してたみたい…",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_020"] = "悪夢を見てたの… すごくリアルで… 怖かった…",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_030"] = "この嵐は 私が招いたんだ… 全部 私のせい |時間を巻き戻して運命を変えてるうちに… |いろんなものの未来が変化して… 私のせいで町の人たちが死んじゃう…!",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_060"] = "マクシーンは禁止。 わざと言ってるでしょ…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_020"] = "マックス… これ返すよ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_040"] = "そいつを使えば それを撮った時点まで 全部元通りにできるんだろ? |あたしの運命も… 最初のとおりに… だから…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_060"] = "マックスは… これまでにあたしを 何度も救ってくれた |こんな身勝手な人間をさ |ママだって あたしのために たくさんのものを犠牲にしてくれた",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_070"] = "なのに この嵐で死んじゃうなんて… |クソオヤ… デイビッドも ママが死んだらすげえ悲しむよ |この町には あたしより生きる価値のある人がたくさんいるんだ…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_090"] = "犠牲とかじゃない。 マックスはきっと 避けられない運命を遅らせてただけなんだ |あたしが何度も死んだり  死にかけたりしたのも 町がおかしくなったのも |マックスが女子トイレであたしを助けたから |そろそろ 自分の… あたしたちの運命を受け入れるべきなんだよ…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_094"] = "マックスとこうしてまた会えて 親友として大事にしてもらってさ… |こんなに楽しかったの 何年ぶりか分かんないよ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_096"] = "このあとあたしが どの世界でどうなったとしても… |マックスと過ごした時間は全部本物だし 消えることはない |マックスがどんな選択をしても それが正解だよ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_098"] = "これはマックスの運命でもあるんだ。 あたしはいつもそばにいる |どの世界にいても 過去でも未来でも マックスとあたしは ずっとずっと一緒だ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_110"] = "逆だよ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_115"] = "マックスにしかできないんだ",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_030"] = "この写真も すごく昔のことに思える…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_050"] = "ダメ! そんなのダメだよ! |何があっても クロエだけは絶対守るって決めたんだから…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_080"] = "やめて! クロエを犠牲になんかしない",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_092"] = "クロエ…",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_100"] = "クロエ… 私にはできないよ…",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_001",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_002",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_003",
  ["Act_E5_7B_ArtClass_AloneLines_Scripted_Max_010"] = "みんな消えた… これも私が時間を歪めたから?",
  ["Act_E5_7B_ArtClass_AloneLines_Scripted_Max_030"] = "もう わけがわかんない…",
  ["Act_E5_7B_ArtClass_ArcadiaBayPic01_Look01_Max_010"] = "そんな…",
  ["Act_E5_7B_ArtClass_ArcadiaBayPic02_Look01_Max_010"] = "レイチェルを見つけたときの写真?",
  ["Act_E5_7B_ArtClass_BirdLines_Scripted_Max_020"] = "ちょっと何? なんで誰も気にしてないの?",
  ["Act_E5_7B_ArtClass_BirdLines_Scripted_Max_030"] = "ウソでしょ… 鳥がこんなに死んで… おかしいよ…",
  ["Act_E5_7B_ArtClass_BloodStains_Look01_Max_010"] = "ケイト ごめんね…",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_010"] = "お願い… こんなこと言いたくない",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_020"] = "私がこんなこと言うわけない… 何なの これ",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_030"] = "何が起きてるの?",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_040"] = "こんなこと口にしたくもない…",
  ["Act_E5_7B_ArtClass_Computer_Look01_Max_010"] = "なんでこれが…",
  ["Act_E5_7B_ArtClass_ContestPoster_Look01_Max_010"] = "もうコンテストなんて 興味もないよ…",
  ["Act_E5_7B_ArtClass_DanielTable_Photo_Max_020"] = "夢か現実か分からないけど 写真だけは撮っておこう…",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_010"] = "授業に戻ってる… どういうこと?",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_020"] = "もしかして… 時間のループから抜け出せなくなってる?",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_030"] = "また この講義を聞かなきゃいけないの? もう うんざり…",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_040"] = "パニクっちゃダメ… いったん落ち着いて",
  ["Act_E5_7B_ArtClass_GroupPhoto_Look01_Max_010"] = "何これ… ひどい…",
  ["Act_E5_7B_ArtClass_JeffersonPoster01_Look01_Max_010"] = "これ… 私だ… ウソでしょ?",
  ["Act_E5_7B_ArtClass_JeffersonPoster02_Look01_Max_010"] = "絶対におかしいって…",
  ["Act_E5_7B_ArtClass_KateEtchings_Look01_Max_010"] = "死なないよ ケイト… 死なせない",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_010"] = "こんなのありえない… 現実じゃないよ",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_020"] = "悪夢なら… 目を覚ましたい…",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_030"] = "お願い クロエ… どこにいるの…",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_060"] = "ホラー映画じゃないんだから やめてよ…",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_080"] = "クロエ… 助けて…",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_090"] = "これが夢じゃなかったら どうしよう…",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_110"] = "しっかりして… 負けちゃダメ",
  ["Act_E5_7B_ArtClass_PaperBall_Look01_Max_010"] = "残念 まだ生きてるよ",
  ["Act_E5_7B_ArtClass_VictoriaTablet_Look01_Max_010"] = "ビクトリア… 助けようとしたんだよ…",
  ["Act_E5_7B_ArtClass_VictoriaTablet_Look02_Max_020"] = "ビクトリアは夢の中でも感じ悪い…",
  ["Act_E5_7B_Corridor_Alyssa_Look01_Max_010"] = "アリッサはいつもスマホいじってるけど ひとりでいることが多いみたい",
  ["Act_E5_7B_Corridor_BigfootBanner_Look01_Max_010"] = "「ビッグフット」か。 自分の学校のチームなんだから 応援しなきゃね",
  ["Act_E5_7B_Corridor_Board01_Look01_Max_010"] = "必要ないし 興味ないし バックパックは盗んでない",
  ["Act_E5_7B_Corridor_Board02_Look01_Max_010"] = "掲示板に貼ってあるものを見ると その学校のことがよく分かるね",
  ["Act_E5_7B_Corridor_Brooke_Look01_Max_010"] = "ブルックはウォーレンと仲いいみたい。 ウォーレンが好きそうなタイプだし",
  ["Act_E5_7B_Corridor_Courtney_Look01_Max_010"] = "あの子はたしかコートニー。 いつもテイラーとビクトリアの言いなりになってる",
  ["Act_E5_7B_Corridor_Dana_Look01_Max_010"] = "デーナとは寮の階が同じ |こういう典型的な美人チアリーダータイプの子って 工場で量産されてるのかな… |でもデーナはいい子だから そんな言い方しちゃ悪いよね",
  ["Act_E5_7B_Corridor_Daniel_Look01_Max_010"] = "ダニエルはすごくいい人なのに… ローガンのヤツ ぶっ飛ばしてやりたい!",
  ["Act_E5_7B_Corridor_Evan_Look01_Max_010"] = "エバンはあまり話しかけてこない。 でもすごくいい写真を撮るんだ",
  ["Act_E5_7B_Corridor_Halloween01_Look01_Max_010"] = "ハロウィンは一番楽しみなイベント!",
  ["Act_E5_7B_Corridor_Halloween01_Look02_Max_010"] = "廊下がガイコツだらけになるって いいよね!",
  ["Act_E5_7B_Corridor_Halloween01_Look03_Max_010"] = "ずっと 10 月だったらいいのになあ…",
  ["Act_E5_7B_Corridor_Hayden_Look01_Max_010"] = "ヘイデンだ |ボルテックス・クラブのメンバーだけど そんなにイヤなヤツじゃない",
  ["Act_E5_7B_Corridor_Juliet_Look01_Max_010"] = "ジュリエットとは寮の階が同じ。 彼女もボルテックス・クラブのメンバー",
  ["Act_E5_7B_Corridor_Justin_Look01_Max_010"] = "あれはデーナ。 相手の男子は… ジャスティンだったかな",
  ["Act_E5_7B_Corridor_Logan_Look01_Max_010"] = "ローガンは弱い者いじめするから大ッ嫌い |それに ボルテックス・クラブのメンバーだし",
  ["Act_E5_7B_Corridor_MPA01_Look01_Max_010"] = "このビラ 校内のあちこちに貼ってあるな…",
  ["Act_E5_7B_Corridor_MPA01_Look02_Max_010"] = "「レイチェル・アンバー」… きれいな子だな… |このビラ見てると悲しくなってくる",
  ["Act_E5_7B_Corridor_MPA01_Look03_Max_010"] = "もう何か月も行方不明なのか…",
  ["Act_E5_7B_Corridor_MPA01_Look04_Max_010"] = "この子に何があったんだろう…",
  ["Act_E5_7B_Corridor_MaxLocker_Look01_Max_010"] = "人にロッカーの中 見られるのは好きじゃないな",
  ["Act_E5_7B_Corridor_Plan01_Look01_Max_010"] = "こんなの暗記してる人 いるのかな? でも実際は みんなしたほうがいいよね",
  ["Act_E5_7B_Corridor_Poster01_Look01_Max_010"] = "大変だな… 私も活動に協力したほうがいいのかも… ま やらないけどね",
  ["Act_E5_7B_Corridor_Poster02_Look01_Max_010"] = "また灯台か…",
  ["Act_E5_7B_Corridor_Poster03_Look01_Max_010"] = "献血 したほうがいいよね?",
  ["Act_E5_7B_Corridor_Poster04_Look01_Max_010"] = "銃はおうちに置いてきましょう!",
  ["Act_E5_7B_Corridor_Poster05_Look01_Max_010"] = "こんなポスターでいじめがなくなれば苦労しないって",
  ["Act_E5_7B_Corridor_Poster06_Look01_Max_010"] = "このポスター オタク臭全開だな。 ウォーレンが好きそう",
  ["Act_E5_7B_Corridor_Poster07_Look01_Max_010"] = "「私もネイサンやビクトリアみたいにイケてる生徒になりたいわ!」… |バッカみたい…",
  ["Act_E5_7B_Corridor_PrincipalDoor_Look01_Max_010"] = "校長先生はいつも校長室にこもってる",
  ["Act_E5_7B_Corridor_Samuel_Look01_Max_010"] = "サミュエルってほんと変な人。 でもそこがいいんだよね",
  ["Act_E5_7B_Corridor_Stella_Look01_Max_010"] = "ステラはいつもノートとにらめっこ。 本気で勉強しにブラックウェルに来てる",
  ["Act_E5_7B_Corridor_Taylor_Look01_Max_010"] = "テイラーだ。 いつもビクトリアを待ってる",
  ["Act_E5_7B_Corridor_Trevor_Look01_Max_010"] = "スケーターは好きだけど 私の想いはいつも一方通行",
  ["Act_E5_7B_Corridor_Trophy01_Look01_Max_010"] = "すごいトロフィー。さすがは「ビッグフット」 名前負けしてないね",
  ["Act_E5_7B_Corridor_Trophy02_Look01_Max_010"] = "水泳にはだいぶ力入れてるな。 カワウソ かわいいからいいけど |がんばれオッターズ!",
  ["Act_E5_7B_Corridor_VendingMachine_Look01_Max_010"] = "「砂糖販売機」って呼べばいのに… コインを入れたら砂糖が出てくる 最高だね",
  ["Act_E5_7B_Corridor_Zachary_Look01_Max_010"] = "ジュリエットとザッカリーが付き合うのも当然 |ボルテックス・クラブの渦中の存在だもん",
  ["Act_E5_7B_DarkRoom_DarkLines_Scripted_Max_080"] = "まだ悪夢は続くの?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_010"] = "壁一面に数字が… 正しい番号はどうやって探せばいいの?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_020"] = "鏡に数字が映ってない… どうして?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_030"] = "この鏡どうなってるの?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_040"] = "パズルゲームじゃないんだから ほんとイライラする",
  ["Act_E5_7B_Diner_digicode_Look01_Max_010"] = "暗証番号はこれで最後にしてほしい…",
  ["Act_E5_7B_DormsCorridor_HintKey_Scripted_Max_010"] = "廊下から抜け出せない… どうにかしなきゃ",
  ["Act_E5_7B_DormsCorridor_HintMaxRoom_Scripted_Max_010"] = "ああ やっと帰れた気分… 一旦 落ち着きたいな",
  ["Act_E5_7B_DormsCorridor_HintRachelRoom_Scripted_Max_010"] = "レイチェルの部屋もここにあるのかな?",
  ["Act_E5_7B_DormsCorridor_HintStealth_Scripted_Max_010"] = "力は使えるみたい… でも 慎重にならなきゃ…",
  ["Act_E5_7B_DormsCorridor_HintStealth_Scripted_Max_020"] = "そうだ。 時間を操れるってことは…",
  ["Act_E5_7B_DormsCorridor_HintVictoriaRoom_Scripted_Max_010"] = "ビクトリアの部屋は確か…",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_010"] = "ここは一体どこなの?",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_030"] = "ドアが多すぎて…",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_040"] = "ここから出るドアがきっとある… 見つけよう",
  ["Act_E5_7B_DormsCorridor_Squirrels_Photo_Max_010"] = "サミュエル…",
  ["Act_E5_7B_LabyStealth_BottleRange_Look01_Max_010"] = "空きビン地獄はまだ終わらない… もうヤダ…",
  ["Act_E5_7B_LabyStealth_BottleRange_Look02_Max_020"] = "クロエのせいだよ… ビンを集めてなんて言うから…",
  ["Act_E5_7B_LabyStealth_BottleRange_Photo_Max_010"] = "一応 証拠に写真でも撮っておこうかな…",
  ["Act_E5_7B_LabyStealth_Bottle_Interact01_Max_010"] = "まさか… また空きビン集めをやるの…?",
  ["Act_E5_7B_LabyStealth_Bottle_Interact02_Max_020"] = "見つけやすいところにあるなら ともかく…",
  ["Act_E5_7B_LabyStealth_Bottle_Interact03_Max_030"] = "空きビンの呪いってあるの?",
  ["Act_E5_7B_LabyStealth_Bottle_Interact04_Max_040"] = "あと 一個かな…?",
  ["Act_E5_7B_LabyStealth_Bottle_Interact05_Max_050"] = "もうこれで最後にしてよ…",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_010"] = "またジェファソンが追ってくる…　やだ…",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_030"] = "悪夢みたいな迷路…",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_040"] = "灯台は向こうだ!",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_050"] = "灯台なら安全かな… 夢も覚めるかも…",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_060"] = "そんな… 目覚めてよ!",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_010"] = "一度 座って落ち着かないと 身体がもたないよ…",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_020"] = "悪夢のなかでも 安らげる場所があっていいはず…",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_030"] = "ここはクロエとレイチェルが 唯一安らげる場所だった…",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_040"] = "でもずっと隠れてるわけにはいかない。 悪夢のような現実が待ってたとしても…",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_050"] = "私 また失敗を繰り返してるのかな",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_060"] = "ここから抜け出せれば 答えが見つかるかも",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_070"] = "怖がっちゃダメ。 私の強さを見せるんだ",
  ["Act_E5_7B_LivingRoom_WilliamLines_Scripted_Max_010"] = "ああ ウォーレン。 こんなのありえない… 怖いよ",
  ["Act_E5_7B_LivingRoom_WilliamLines_Scripted_Max_020"] = "念のために証拠を…",
  ["Act_E5_7B_Nightmare_RachelGraffiti_Look02_Max_010"] = "3 度目の正直ってわけにはいかないか…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_004"] = "敬語なんか使わないで。 無駄にした時間を 2 人で取り戻そう…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_005"] = "さて この先ずっと 僕の「暗室」で過ごさないかい? |君の無垢さは 僕の感性を刺激する… |お互いにとって とても幸せなことだと思うんだ… |僕が撮れば 自撮りも必要なくなる",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_008"] = "僕が君の姿を 何度でもとらえてあげよう… |一生僕のモデルでいるといい… 死ぬまでね",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_009"] = "僕に任せなさい |君の中に存在するあらゆる顔を 僕がこの世に公表してあげよう",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_010"] = "マクシーン。 僕と違って クロエは君のことを何も分かっていない",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_015"] = "君はもう この世界で一人ぼっちだ。 だから僕が君を愛してあげるよ…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_016"] = "闇の中で幸福をむさぼろう。  いつまでも無垢な君でいてくれ |レイチェルやクロエのように けがれてもらっては困る…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_017"] = "針とダクトテープは 怖くないね?",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_018"] = "ああ そうだ。 これからはマクシーンと呼ぶよ… いいね?",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_002"] = "この日をどんなに待ち望んでいたことか… 私 先生のことが好きです",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_003"] = "私たちだけの 「暗室」ですね… 外は嵐でも あそこなら少しも怖くない…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_006"] = "私の自撮りはゴミです… 本物のアーティストに撮ってもらいたい…",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_007"] = "先生がクロエを殺してくれてよかった… |あの子のせいで何度死にかけたことか… |先生 本当にありがとう |何もかも先生のおかげ!",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Courtney_010"] = "インスタントカメラとか めちゃくちゃダサいんですけど",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Taylor_020"] = "マックスはイケてると思ってんでしょ",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Taylor_040"] = "自撮り魔なんだから ほんとは目立ちたいに決まってるじゃん",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_010"] = "では 人物の内面をモノクロ写真で完璧にとらえた写真家といえば誰だろう? |分かる人? 誰か?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_030"] = "なるほどね なぜそう思う?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_050"] = "アーバスは人間を「苦悩の存在」と考えた。 正直ヘドが出るね |はいはい 騒がない… |例えば 誰かを暗い部屋に座らせれば 絶望のシーンのできあがりだ",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_070"] = "同感だね |戦後のアメリカをとらえたフランクの作品には |貧しくても懸命に生きる人びとの姿が 浮き彫りになっている |それこそが真の美しさだ |フランクがケルアックにインスピレーションを与えたのもうなずける |2 人とも 50 年代の 偉大なアーティストだ |ケルアックの有名なバルコニーでのショットはみんな知っているね |都会で物思いにふける |孤独な詩人の姿を見事にとらえた一枚だ |すばらしいよ",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_080"] = "さて フランクと対照的なのが サルバドール・ダリのシュールレアリズムだ |コクトーと同様 ダリも多才な人物だったが |彼の有名なセルフポートレートの数々は |君たちがよく使うセンスのない言葉で言うところの 「自撮り」だ |でもセルフポートレートの歴史は古い |自撮りだって立派な自己表現だ |言葉のチョイスは ま どうかと思うけどね",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_090"] = "自撮りは現代特有のナルシシズムだと思っている人 |批判は数百年前に向けるべきだ |さてと… そろそろ眠くなってきた人もいるかな… |それじゃあ質問しよう |教科書を読んできた人は答えられるはずだぞ |セルフポートレートの誕生に貢献した 製版法の名前は なんでしょう?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_020"] = "ダイアン・アーバスです",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_040"] = "アーバスの作品にとらえられた 失意の人びとの目には 鬼気迫るものがあります",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_060"] = "確かに私 アーバスはいいと思えません |それより… ロバート・フランクとか…",
  ["Cue_E5_7B_ArtClass_JeffersonTalks_Jefferson_010"] = "マックス・コールフィールド。 待ちなさい。 コンテストの課題はどうした",
  ["Cue_E5_7B_ArtClass_MaxAwake01_Jefferson_030"] = "アルフレッド・ヒッチコックは映画を「時間の断片」だと考えた |当然ながら写真についても同じことが言えるだろう |写真は被写体の喜怒哀楽を切り取る |光 影 カラー キアロスクーロなど 技法はさまざまだ",
  ["Cue_E5_7B_ArtClass_MaxAwake01_Max_010"] = "…ッ!",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_030"] = "こういうの慣れてるから",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_100"] = "ボルテックス・クラブのメンバーにはこんなことしないくせに",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_170"] = "この学校は嫌なやつばっかり",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_070"] = "あの写真が撮影された当時 彼はまだ生まれてもいなかったというのに?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_080"] = "その前にテストさせてくれ。 質問に答えてもらうよ |「崩れ落ちる兵士」の撮影者は?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_090"] = "おいおい… 君はストリートフォトとジャーナリズムの区別もつかないのか",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_010"] = "マックス、ちょっと来なさい",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_020"] = "顔色が悪いようだが… どうかしたのか?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_030"] = "すごい汗だ 本当にそれだけかね?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_040"] = "それとも何かやましいことでもあるのか?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_030"] = "こういうの慣れてるから",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_100"] = "ボルテックス・クラブのメンバーにはこんなことしないくせに",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_170"] = "この学校は嫌なやつばっかり",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_070"] = "あの写真が撮影された当時 彼はまだ生まれてもいなかったというのに?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_080"] = "その前にテストさせてくれ。 質問に答えてもらうよ |「崩れ落ちる兵士」の撮影者は?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_090"] = "おいおい… 君はストリートフォトとジャーナリズムの区別もつかないのか",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_010"] = "マックス、ちょっと来なさい",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_020"] = "顔色が悪いようだが… どうかしたのか?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_030"] = "すごい汗だ 本当にそれだけかね?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_040"] = "それとも何かやましいことでもあるのか?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Samuel_180"] = "リスは毎朝来るんだよ… 餌を探しに |ささやきが聞こえるんだ… |森ではどんな動物を見たんだい?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Samuel_360"] = "父が漁師でね 一緒に海に出るとクジラの歌が聞こえたものだ… |でも今は… 泣き声が聞こえる",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_010"] = "あなたはたしか 写真のクラスで一緒だよね |ジェファソン先生 最高じゃない?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_020"] = "あのマーク・ジェファソンが こんな田舎町で教えてるなんて |ギャラリーは今頃歯ぎしりしてるでしょうね |それに先生かなりイケメンだし",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_030"] = "先生はアーティストだから",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_040"] = "ビクトリアたちと一緒にいるのをよく見かけたよ",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Trevor_010"] = "絶対目があったと思ったけど… ま これでバレたか… ジャスティンも知ってる",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Trevor_020"] = "すげえ怒ってたけど 大丈夫。 隠し通すことも無理だしさ… じゃ また授業で",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Samuel_180"] = "リスは毎朝来るんだよ… 餌を探しに |ささやきが聞こえるんだ… |森ではどんな動物を見たんだい?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Samuel_360"] = "父が漁師でね 一緒に海に出るとクジラの歌が聞こえたものだ…|でも今は… 泣き声が聞こえる",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_010"] = "あなたはたしか 写真のクラスで一緒だよね |ジェファソン先生 最高じゃない?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_020"] = "あのマーク・ジェファソンが こんな田舎町で教えてるなんて |ギャラリーは今頃歯ぎしりしてるでしょうね |それに先生かなりイケメンだし",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_030"] = "先生はアーティストだから",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_040"] = "ビクトリアたちと一緒にいるのをよく見かけたよ",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Trevor_010"] = "絶対目があったと思ったけど… ま これでバレたか… ジャスティンも知ってる",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_010"] = "で? 私のことどう思ってるの?",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_030"] = "カワイイだけ?",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_050"] = "それだけじゃ 授業中に\"いい写真\"送ってあげないよ",
  ["Cue_E5_7B_Corridor_Dial05_REV_Zachary_020"] = "分かってるだろ。 カワイイと思ってるよ",
  ["Cue_E5_7B_Corridor_Dial05_REV_Zachary_040"] = "ダメか?",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_010"] = "ここが正念場だよ…",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_020"] = "コーナー決めて…",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_030"] = "ヤバッ… ひと轢いちゃった…",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_040"] = "ここでギアチェンジッ!",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_050"] = "そこのフェラーリ どいたどいた!",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_060"] = "あと少し…!",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_070"] = "3位!? なによこのクソゲー! くっだらない…",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_010"] = "ここが正念場だよ…",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_020"] = "コーナー決めて…",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_030"] = "ヤバッ… ひと轢いちゃった…",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_040"] = "ここでギアチェンジッ!",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_050"] = "そこのフェラーリ どいたどいた!",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_060"] = "あと少し…!",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_070"] = "3位!? なによこのクソゲー! くっだらない…",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_010"] = "掃除は好きだけど 足ひきずるのはやめてくれ",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_020"] = "汚れが広がってしまうだろう",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_030"] = "でもこれはいいモップだ。 大事に使うよ",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_040"] = "僕は幽霊のようなものさ。 生徒には見えてないのさ",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_050"] = "かわいそうに… 行方不明だなんて…",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_010"] = "掃除は好きだけど 足ひきずるのはやめてくれ",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_020"] = "汚れが広がってしまうだろう",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_030"] = "でもこれはいいモップだ。 大事に使うよ",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_040"] = "僕は幽霊のようなものさ。 生徒には見えてないのさ",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_050"] = "かわいそうに… 行方不明だなんて…",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_020"] = "バイト代入ったのか?",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_060"] = "ようし ボコボコだ!",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_090"] = "指図すんなよ!",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_040"] = "なんのことだよ",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_070"] = "ローガン 頼むよ もうやめて",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_100"] = "お願い… 授業に行かせてよ",
  ["Cue_E5_7B_Corridor_Dial08_Logan_010"] = "ダニエル! バイト代 入ったか?",
  ["Cue_E5_7B_Corridor_Dial08_Logan_030"] = "金のこと忘れてねえだろな",
  ["Cue_E5_7B_Corridor_Dial08_Logan_050"] = "こいつボコボコにされてえらしい",
  ["Cue_E5_7B_Corridor_Dial08_Logan_080"] = "俺に指図すんのか?",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_020"] = "だな!",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_060"] = "あはッ",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_090"] = "ガリ勉くん",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_040"] = "スパニッシュだ…",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_070"] = "ローガン もうやめてよ",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_100"] = "頼むから授業に行かせてよ",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_010"] = "ダニエル 今日は元気そうじゃないか!",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_030"] = "メキシカンのくせによ",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_050"] = "そりゃ大違いだ",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_080"] = "俺に指図すんのか?",
  ["Cue_E5_7B_Corridor_Dial09_REV_Dana_060"] = "居眠りするなら授業出る意味ないじゃない",
  ["Cue_E5_7B_Corridor_Dial09_REV_Justin_050"] = "してるよ。 今日なんてさ 7 時に起きたんだぜ?",
  ["Cue_E5_7B_Corridor_Insertion_REV_Max_010"] = "いつも通りの風景…",
  ["Cue_E5_7B_Corridor_Insertion_REV_Max_020"] = "トイレに行って ちょっとひとりになろう |顔でも洗って シャキッとしなきゃ… もっとバカにされちゃう",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_020"] = "せっかくの力も 使いこなせなきゃ意味ないだろ…",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_040"] = "レイチェルの代わりに マックス… あんたが死ねばよかったんだ",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_060"] = "なんでアルカディア・ベイに戻ってきた? いい迷惑だよ",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Chloe_030"] = "マックスはガキだから",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Chloe_060"] = "意識だけムダに高いしね",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_010"] = "君をモデルに 「レトロ・グランジ」というシリーズを撮りたい…",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_020"] = "君にはレイチェルと同じ良さがある。 マックスとは大違いだ",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_040"] = "同感だよ。 しかも おしゃべりが過ぎて困る",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_070"] = "学校でも嫌われてたよ… 本当のスターは君だ",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Chloe_020"] = "暇つぶしだ。 パシリにもちょうどいいしな",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Nathan_010"] = "お前みたいなイケてる女が なんでマックスなんかと…",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Nathan_030"] = "確かに。 なあ… 部屋にいいもんあるけど どうだ?",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Chloe_010"] = "ビクトリア あんたオトナだな。 マックスとは大違いだ…",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Victoria_040"] = "あなたのタトゥー すっごくセンスいいと思う",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Victoria_060"] = "もっと早く一緒になってればよかった…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_020"] = "ウォーレンはてっきりマックスが好きなのかと…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_021"] = "ウォーレンはてっきりマックスが好きなのかと…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_022"] = "あたしら 2 人とも マックスにしてやられたな",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_023"] = "ウォーレンはてっきりマックスが好きなのかと",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_040"] = "あたしはキスされたけどね。 マジでキモかった…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_041"] = "へえ。 あたし オタクはタイプじゃないけど あんたはアリかな",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_042"] = "あたしらをもてあそびやがって",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_043"] = "あたしらはタイプじゃないってことだろ。 何様のつもりだ?",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_060"] = "見ろよ! マックスがのぞいてやがる! 写真だったらいくらでも撮れよ!",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_030"] = "だってあいつ… キスすらもったいつけやがってさ",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_031"] = "いやいや… キスされたとき 吐きそうになったし",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_032"] = "あいつ八方美人なんだよ",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_033"] = "あいつは俺に興味ないし… どうでもいいよ",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_050"] = "じゃあ 今度は僕が君にキスする番だね",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_051"] = "マックスなんか興味ない。 君のほうがいいよ…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_052"] = "でも 俺は君に夢中だよ。 だから クロエ…",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_053"] = "マックスはジェファソンに夢中なんだろ。 あんなヤツ ほっとこうぜ…",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_010"] = "ずっと助けてくれたのに こんどは見殺しにするんだ? もう いいよ",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_020"] = "数少ない信頼できる人だと思ってたのに…",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_030"] = "私はともかく 他の人たちを見殺しにできるっていうの? マジで?",
  ["Cue_E5_7B_Diner_BinkNightmare_MaxGhost_010"] = "あら ウワサをすれば…",
  ["Cue_E5_7B_Diner_BrookeDiner_IGE_Brooke_020"] = "マックスには 正しいことをしてほしいな…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_001"] = "見て分かるでしょ。 私はあなた。 置き去りにされたマックスのなかの一人…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_003"] = "何 助けてほしいの? |時空を自在に操って 過去も人も すべて思いどおりにできるんでしょ?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_006"] = "どんなに取り繕っても あなたの行動が たくさんの死を生み出したことは事実… |マドセンがジェファソンを殺したのもそう… 最低だね! |本当の人殺しはあなただよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_008"] = "人気者になりたかっただけでしょ? |すごい力を使えるようになったのをいいことに |親切なふりしてみんなに取り入ってさ…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_009"] = "でも それを利用して人気者になろうとした。 親切なふりしてさ…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_012"] = "それでも 殺人は殺人だよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_013"] = "裁判でも 「タイムトラベル」なんて証言するつもり?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_016"] = "当たり障りのないことを言って ご機嫌とって? |自力で友だちをつくれないから 力に頼ったんだ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_017"] = "やっと認める気になった? ま いまさらもう遅いけどね…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_020"] = "むしろあなたの偽善で どれだけの人が傷ついたと思ってるの…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_021"] = "どんなに取り繕っても あなたは偽善者だよ |あなたの行動が たくさんの苦しみと死を生み出した…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_023"] = "いいの? そんな偉そうな口利いて |じゃあフランクは? |あいつが撃たれたのも自分のせいじゃないって言うの?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_024"] = "いいの? そんな偉そうな口利いて。 結局 責任から逃げてばっかなんだ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_025"] = "そっか。 分かった… |時空をメチャクチャにしたのは 全部クロエのためってわけか |あんな不良のためにね…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_029"] = "ホント バカだよね。 私 あなたと同じ名前なのが恥ずかしいよ |クロエはそのうち すべてを…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_030"] = "それはまたずいぶんとご立派だね |そのわりには くだらないことにばっか力を使ってたけど",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_031"] = "よく言うよ。 クロエのせいで どれだけのトラブルに巻き込まれたの? |銃に レイチェルに… 障害者基金のお金まで盗んで… |あなたは利用されてるんだよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_032"] = "その親友がつらかったときに |5 年間も連絡取らなかったのは どこの誰だっけ?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_033"] = "よく言うよ。 クロエのせいで どれだけのトラブルに巻き込まれたの? |銃 クスリ レイチェル… あなたは利用されてるんだよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_035"] = "誘拐犯に共感しちゃう被害者と同じ心理だね |説明しても分からない人は 痛い目見るしかないか |レイチェルみたいにね…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_037"] = "このままじゃ ジェファソンに殺される前に クロエに殺されるよ… |クロエは私たちのこと 友だちだなんて思ってないんだから",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_038"] = "このままじゃ ジェファソンに殺される前に クロエに殺されるよ… |クロエは私たちのこと 都合のいい道具としか思ってないんだから",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_039"] = "自分で死ぬ勇気がないからって あんたに殺せって頼むぐらいだし",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_002"] = "あなた… 誰なの?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_004"] = "こんなの… 望んで手に入れた力じゃない!",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_005"] = "私は… みんなの力になりたかっただけなのに…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_007"] = "お願い ここから出して",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_010"] = "違う! あれは正当防衛だよ! 人殺しの指図なんてしてない!",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_011"] = "違う。 私はタイムトラベルしたことも 殺人鬼と戦ったこともなかったけど |やるべきことをやっただけだよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_014"] = "確かに… 私 みんなに好かれたくて 力をムダ使いしてただけかも…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_015"] = "\"ふり\"じゃない… 本当に友だちが欲しかったの…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_018"] = "そうじゃない! |みんな本当の友だちだし 力だって いいことにしか使ってない…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_019"] = "あなたは私を傷つけたいだけでしょ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_022"] = "黙って。 私のせいじゃない…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_026"] = "当たり前でしょ。 親友なんだから",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_027"] = "クロエと私だけじゃなくて みんなを救うためだよ",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_028"] = "クロエを助けるのは 私の使命なの。 そう信じてるからこそ ここにいるんだ…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_034"] = "だからって クロエが大切なことには変わりない",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_036"] = "ムダだよ。 あなたなんか怖くないから…",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_041"] = "でも… 私には友だちがいる。 それもきっとこの力のおかげなんだ",
  ["Cue_E5_7B_Diner_CourtneyDiner_IGE_Courtney_010"] = "マックス 殺さないで!",
  ["Cue_E5_7B_Diner_CourtneyDiner_IGE_Courtney_020"] = "私達を助けて",
  ["Cue_E5_7B_Diner_DanaDiner_IGE_Dana_010"] = "もうダンスもできないんだね…",
  ["Cue_E5_7B_Diner_DanielDiner_IGE_Daniel_010"] = "マックス 僕が自信を持てるようになったのは 君のおかげだよ",
  ["Cue_E5_7B_Diner_DavidDiner_IGE_David_010"] = "お前のような兵士が隣にいたら 戦場でも安心できるよ",
  ["Cue_E5_7B_Diner_EvanDiner_IGE_Evan_010"] = "マックスさ どうせ死なせるんだったら なぜ助けたんだい?",
  ["Cue_E5_7B_Diner_EvanDiner_IGE_Evan_020"] = "僕もアルカディア・ベイも 両方見捨てる気かい? むなしいなあ…",
  ["Cue_E5_7B_Diner_FishermanDiner_IGE_Fisherman_010"] = "一度は俺を救い また漁に出るチャンスをくれたのに…",
  ["Cue_E5_7B_Diner_FishermanDiner_IGE_Fisherman_020"] = "前に言ったな 「老漁師は死なず」って。 それも今日までだ…",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_010"] = "俺だけじゃなく 俺の客まで皆殺しか? お前 正気か?",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_020"] = "色々あったけどよ… 俺を殺すことはないだろ?",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_030"] = "マジかよ 仲間だと思ってたのに… 俺を見捨てるのか?",
  ["Cue_E5_7B_Diner_HomelessDiner_IGE_Homeless_010"] = "警告ありがとね… あたしを人並みに扱ってくれたんだから |町の人たちのことも頼むよ…",
  ["Cue_E5_7B_Diner_HomelessDiner_IGE_Homeless_020"] = "あたしゃ十分生きた… でも他の連中は助けてやっちゃどうだい?",
  ["Cue_E5_7B_Diner_JoyceDiner_IGE_Joyce_010"] = "娘同然に思ってきたのに… なんで私の家族を奪うんだい… どうして…",
  ["Cue_E5_7B_Diner_JulietDiner_IGE_Juliet_020"] = "マックス お願い 助けて",
  ["Cue_E5_7B_Diner_JustinDiner_IGE_Justin_030"] = "俺を殺すとか ダサすぎでしょ",
  ["Cue_E5_7B_Diner_KateDiner_IGE_Kate_020"] = "お願い 殺さないで… 一緒にお茶するって言ったのに",
  ["Cue_E5_7B_Diner_LoganDiner_IGE_Logan_010"] = "マックス これが復讐のつもりか?",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_010"] = "お前はよくのうのうと生きてられるな",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_020"] = "ちくしょう 苦しいだろうな",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_030"] = "ポートランドの母さんに 愛してるって伝えてくれよな",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_040"] = "カリフォルニアで新生活を始めるってときに…",
  ["Cue_E5_7B_Diner_NathanDiner_IGE_Nathan_010"] = "いろいろあったけど 本当にすまなかったと思ってる |友だちだったら楽しくやれたと思うよ |俺はただ 誰にも俺みたいに苦しんでほしくないんだ",
  ["Cue_E5_7B_Diner_SamuelDiner_IGE_Samuel_020"] = "リスを死なせてはいけないよ…",
  ["Cue_E5_7B_Diner_StellaDiner_IGE_Stella_010"] = "貧乏で荒んだ家庭を耐えぬいたけど 結局ここで死ぬのか…",
  ["Cue_E5_7B_Diner_TrevorDiner_IGE_Trevor_010"] = "かわいい彼女ができたとたんに殺すのかい? そりゃないぜ",
  ["Cue_E5_7B_Diner_TruckerDiner_IGE_Trucker_010"] = "聞こえてるか。 これまで俺と道路を共にした仲間たちよ。 ありがとな",
  ["Cue_E5_7B_Diner_TruckerDiner_IGE_Trucker_020"] = "俺は別にいいんだ。 やることはやった。 こんどはお前の番だ",
  ["Cue_E5_7B_Diner_VictoriaDiner_IGE_Victoria_020"] = "友だちだったらよかったのに… ねえ お願い 助けて… まだ十代なのよ…",
  ["Cue_E5_7B_Diner_WarrenDiner_IGE_Warren_020"] = "キスだってしたのに… 俺を殺すのかよ…",
  ["Cue_E5_7B_Diner_WarrenDiner_IGE_Warren_050"] = "友だちだけの関係でもよかったんだ… でも君は友だちすら見捨てるんだね",
  ["Cue_E5_7B_Diner_WellsDiner_IGE_Wells_010"] = "私が立派な校長だったとは言わない。 でも君は立派な「日常ヒーロー」だった…",
  ["Cue_E5_7B_Diner_WomenVoicesDiner_IGE_Female01_030"] = "夫と赤ん坊は私抜きでやっていかないとね…",
  ["Cue_E5_7B_Diner_WomenVoicesDiner_IGE_Female01_040"] = "こんなの私が望む人生最後の時間じゃない…",
  ["Cue_E5_7B_Diner_ZacharyDiner_IGE_Zachary_020"] = "ビッグフットだけは助けてくれよ",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Chloe_040"] = "驚くなよ… ほら 学校の合いカギ! クソオヤジからくすねてきた",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Chloe_050"] = "一応 カギも探して… 念のため",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Frank_060"] = "俺のカギを返しやがれ",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_010"] = "絶対カギがあるはず… 見つけよう",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_020"] = "どうぞ 気になさらないで… 売人のカギを盗みにきただけなので…",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_030"] = "カギさえ手に入れば…",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_070"] = "おーい… カギよ 応答せよ…",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_080"] = "さて 最後にどこに置いたっけな…? カギ… カギ… あークソ!",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_090"] = "マックス いたずらも程々にな。 カギをかしなさい",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_100"] = "なあんだそんなことかよ? もったいつけやがって! |ついでに車のキーもやろうか?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm02_Jefferson_030"] = "レイチェルのことは気がかりだが 君は自分の心配をしたほうがいい… |ウェルズ校長から女子トイレでのことを聞いたよ…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Chloe_030"] = "だって あいつフランクとろくでもない関係だったんだろ? |あたしにウソついてたんだ! |もう誰も信じられない |どいつもこいつも 友だちのフリばっかりしやがって! |マックスもそうだろ",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Chloe_060"] = "いや その必要はない |大丈夫… マックスがいるし |レイチェルはきっと見つかるよ… 絶対に見つかる",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_David_020"] = "やっぱりここにいたか。 レイチェルの服なんか着て なんのつもりだ?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Frank_040"] = "お前と違ってその服が似合ってたからな |で 何だ? また俺を撃ちにきたのか?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Joyce_010"] = "マックスったら あんた レイチェルに嫉妬してるの?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Nathan_050"] = "レイチェル? んだよ… お前か",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_010"] = "レイチェル・アンバー。 あたしの…親友だった |パパが死んでマックスが引っ越して ひとりぼっちだったとき… |レイチェルに救われた",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_030"] = "半年前。 突然 姿を消した。 あたしにも言わずに… 1 人で",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_050"] = "あたしに黙って行くはずない。 絶対 何かあったんだ",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_060"] = "いなくなる前 「運命の人と出会った」とか言ってた… それっきり",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Max_020"] = "私の代わりに レイチェルがいてくれたんだね…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Max_040"] = "自分の意志でいなくなったんじゃない? 人生をやり直したくなったとか",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq02_Chloe_010"] = "それはレイチェルのだ… なんでてめえが持ってんだ!?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq02_Frank_020"] = "言っただろ。 もらったんだよ",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq03_Chloe_020"] = "相性抜群だよ。 レイチェルもアーティスト肌でさ… センスがよかっ… |センスがいいんだ。 口が減らないとこもそっくり |きっと 3 人で親友になれるよ",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq03_Max_010"] = "レイチェルと私 友だちになれるかな?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Chloe_020"] = "マックスも好きになってたよ |賢い セクシー オシャレ… あたしみたいだろ?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Max_010"] = "ホントにレイチェルが好きだったんだね",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Max_030"] = "はいはい。 案外 私のほうが気に入られたかもよ",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Chloe_050"] = "黙れよ! レイチェルとあたしは 親友以上だった!  絶対あきらめない…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_010"] = "レイチェルが消えて 俺は望みを失ったんだ…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_020"] = "正直 どうかなっちまいそうだよ |今頃どこにいんだか… せめて声だけでも聞ければ…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_040"] = "てめえに何が分かる! もう手遅れだ!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_060"] = "なんも分かってねえな! てめえのせいなんだよ! |俺からレイチェルを奪いやがってよ!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Max_030"] = "レイチェルのために協力して。一刻を争うの",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_020"] = "そんな…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_030"] = "レイチェル…?|ウソだ… ウソだ! 信じない!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_050"] = "レイチェル なんで…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_070"] = "親友だったのに…!|どうして…!|こんなのあんまりだよ…|あんまりだ!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_010"] = "待って… これ…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_040"] = "クロエ…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_060"] = "クロエ… 落ち着いて…",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_010"] = "コンテストの課題 ちょっと本気出し過ぎたかも",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_020"] = "アーバスの作品にとらえられた 失意の人びとの目には 鬼気迫るものがあります",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_030"] = "あなたのぼんやりした顔とは 正反対ね",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_040"] = "これカシミアなんですけど! この服 いくらしたか分かってるの!?",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_050"] = "あーら 自撮りクイーンのマックス・コールフィールドさん",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_060"] = "じゃ さよなら 「自撮りぼっち」さん",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_070"] = "近寄らないでよ 気色悪い!",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_080"] = "照れないの。 ホントはあんなに大胆なんだから…",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_090"] = "あらら 後悔してるのはあなたでしょ? 自業自得よ",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_100"] = "シーッ! 聞こえるよ",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_110"] = "私と親友になれたとでも思ってた?",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_120"] = "そうですね。 何かあったら聞きますよ ジェファソン先生",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_130"] = "私を選ばなかったら… |先生に 優勝させる代わりに いろいろ要求されたって言いふらしちゃうかも…",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_140"] = "…なんなら ボルテックス・クラブのメンバーに入れてあげてもいいけど",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_150"] = "そうは思えないけど… 言いたいことは分かるよ |ねえ 私たちって友だちになれないのかな",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_010"] = "マックス なんで私を止めてくれなかったの",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_020"] = "あなただけは信じてたのに…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_030"] = "結局 味方なんかじゃなかった",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_040"] = "もう天国には行けない…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_050"] = "あなたのせいで 私は地獄を一人でさまようの…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_070"] = "どうして死なせてくれなかったの?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_080"] = "それでも友だちなの?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_090"] = "私がどんなにつらかったか 何も分かってない…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_100"] = "私の家族まで巻き込んで…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_110"] = "結局 私を一人にしたのは… マックス あなたよ",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_010"] = "ケイト…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_060"] = "違う。 私はケイトを救いたかったのに…",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_120"] = "そんなはずない! 私はケイトの友だちだよ…",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_Chloe_060"] = "へー 本当にシェフのつもりなんだ",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_Chloe_080"] = "知らないよ?",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_William_050"] = "まさかシェフを疑ってるのか?",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_William_070"] = "ママがいないときはね",
  ["Cue_E5_7B_Kitchen_WilliamFindingkeys_William_010"] = "発見! こんなところにいたのか",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_010"] = "マックス!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_020"] = "おい!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_030"] = "マックス!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_040"] = "おい マックス!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_050"] = "マックス!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_060"] = "どこにいく?",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_070"] = "おい!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_080"] = "おい お前!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_010"] = "俺の監視は逃れられんぞ!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_020"] = "なんの権利があって俺の家庭を壊した? 答えろ! 答えやがれ!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_030"] = "いいか? お前は問題児! ヤク漬けで不快なジャンキーだ!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_040"] = "俺はケイトを助けてたんだ! お前は何をしてた!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_070"] = "お前のせいで愛するジョイスに嫌われた。 さぞ嬉しいだろ?",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_080"] = "お前は偽善者だ |俺は いけ好かないかもしれないが正直だ |お前はイカサマをしてる |友だちの命をもてあそんでる",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_090"] = "皮肉なもんだろ? ヒーローは俺だった。 お前は結局 町をぶち壊すんだからな",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_100"] = "いいかげん認めろ。 戦争を経験した俺には勝てないってな!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_110"] = "マックス こっちにおいで。 ボコボコにしてやるからよ!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_010"] = "おい 待てって!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_020"] = "マックス!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_030"] = "止まれ!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_040"] = "動くなよ!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_050"] = "そこだな!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_060"] = "来いよ マックス",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_070"] = "マックス!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_080"] = "いたな!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_010"] = "こっちにきやがれ! 切り刻んでやるよ この化け物!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_020"] = "俺の豆… 俺の豆をメチャクチャにしやがって!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_040"] = "誰がお前の仲間になんかなるかよ",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_050"] = "お前だけは絶対に許さねえからな",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_080"] = "お前のせいで 俺の人生は生き地獄なんだよ",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_090"] = "売人だとバカにしやがって お前のほうがよっぽどゴミだ",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_100"] = "レイチェルは死んだのに… なんでお前が生きてるんだ",
