  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_100"] = "マックス!!",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_010"] = "あんなに純真で清らかだったのに… 死んでもらうぞ",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_020"] = "隠れても無駄だぞ。 出てこい! 僕の作品になるんだ!",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_030"] = "あんな田舎者に僕を殺させるとはな",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_040"] = "あれほど君には尽くしたのに…! ケイトを泣かせたことで僕を責めるとは… |芸術とは人を泣かせるものだ… 君も泣かせてやろう",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_050"] = "君の閃きはどこにいった? 僕は生涯 君を指導するつもりだったのに…",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_060"] = "ジョン・レノンも言っただろう? |「幸せは温かい銃」。 僕が死んで君は幸せかい…?",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_070"] = "なんで分かってくれないんだ… 僕が自分でいられたのは… |あの「暗室」だけなんだ…",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_080"] = "真剣な眼差しで教室の僕を見ていた頃が懐かしいな… |もう一度 君の教師になりたい… まだ教えることはある…",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_090"] = "君は写真家どころか芸術家にもなれないね… 来なさい。 授業は終わりだ",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_010"] = "マックス… マックス… 僕の芸術品になってくれよ",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_020"] = "クロエも死んだし これで君も授業に集中できるな",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_030"] = "ケイトもいなくなり 「暗室」のボランティアが必要なんだ。 やらないか?",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_040"] = "レンズを見て… 右を向いて… 左… 愛を見せて… そして憎しみ…",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_050"] = "レイチェルを見せたかったよ。 僕の血染めの天使…",
