  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_010"] = "マックス どこにいるの? 出ておいで… でーておいでー",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_020"] = "猿… 猿… 猿… 「猿の惑星」見にいこうよ? |いこうよ! いこうよ! 猿見にいこうよ!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_030"] = "さあ 車に乗って マックス。一緒にドライブしよう。 早く乗れよ!",
