  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_050"] = "いるんだろ マックス? 君のナイトが迎えに来たよ。出てきなよ |出てこい!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_060"] = "あの青髪の不良とはどういう関係? 君に必要なのは俺だろ!",
