  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_050"] = "マックス!",
  ["Cue_E5_7B_LivingRoom_MaxPickUpPhone_William_030"] = "もしもし…",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_Chloe_020"] = "もう 1 ドル罰金!",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_William_010"] = "クソッ カギはどこにいった?",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_William_030"] = "破産させる気かい!?",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_030"] = "バカみたい",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "えー!",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "汚い言葉 1 ドル罰金!",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_010"] = "ジョイス! クロエたちと朝ごはんを作ってたとこさ |「ツー・ホエールズ」で雇って…",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_015"] = "えっ? …ああ 買い物ね もちろん迎えにいく モカにありつけるかもしれないしね |すぐ行くよ。 じゃあ…",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_020"] = "さて セーブマートまで女王陛下を迎えにいくことになった |平民の食料をたくさん買い込んだみたいなのでね…",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_040"] = "それがパパのいいところさ",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_045"] = "カギをしめといてくれよ。 仲良く遊んで 家を壊さないように…",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_090"] = "クソっ カギはどこにいった",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_110"] = "罰金じゃなくて大学資金な… カギは…",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_140"] = "あと ワインの試飲会はダメだぞ…",
  ["Cue_E5_7B_Nightmare_ChloeDarkRoom_Chloe_010"] = "踊りってのはこうすんだよ。 ダサいマックスにはムリか",
  ["Cue_E5_7B_Nightmare_ChloeDiner_Chloe_015"] = "いい加減にしろよ。 お前と違って こっちのマックスはすべてを体験してんだ! |あたしとマックスがいる世界が現実なんだよ!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_020"] = "おっと 戻ってきたか。 それで 時間旅行はどうだった?",
  ["Cue_E5_7C_Beach_Insertion_Chloe_040"] = "ずっと一緒にいるって決めたからな… |でも マックスはあたしを救うためだけに たくさんの時空を飛び回ってくれた… |これでよかったのか? |その… 迷惑ばっかりで あたしのこと いやに… なったりしないか…?",
  ["Cue_E5_7C_Beach_Insertion_Chloe_060"] = "違う 時空をかけるスーパーヒーローだ |そんなヤツと親友だなんて あたしは世界一の幸せ者だよ |望んで その力を手に入れたわけじゃないのに… |それをあたしのために使ってくれた",
  ["Cue_E5_7C_Beach_Insertion_Chloe_080"] = "科学的な説明とか そういうのよく分かんないけどさ… |今 2 人でここにいることは偶然なんかじゃない… |レイチェルもどこかで… 見守ってるはず… そう思いたい",
  ["Cue_E5_7C_Beach_Insertion_Chloe_100"] = "パーティの後 2 人であたしんちに戻ったんだ |ジェファソンに見つからないように… でも嵐がひどくなって |マックスが灯台に避難しようって…",
  ["Cue_E5_7C_Beach_Insertion_Chloe_120"] = "やめろ! 自分を責めるなって! |マックスは十分やったよ… でも あれは… |なんて大きさだ… |これは… レイチェルの怒りなのか? それともあたしたちの?",
  ["Cue_E5_7C_Beach_Insertion_Chloe_130"] = "マックス! あれ!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_135"] = "見ろ! 灯台は進路から外れてる!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_150"] = "マックス どうした…?",
  ["Cue_E5_7C_Beach_Insertion_Max_010"] = "…ッ! クロエ!",
  ["Cue_E5_7C_Beach_Insertion_Max_030"] = "クロエ… よかった 生きてた… ! 私も… クロエも…! |\nどうしても生き返ってほしくて… 私 すごくがんばったの… |本当によかった…",
  ["Cue_E5_7C_Beach_Insertion_Max_050"] = "むしろ… 迷惑なのは私と私の力だよ |この町に起きてることすべてが… きっと私のせいで… 疫病神だよ",
  ["Cue_E5_7C_Beach_Insertion_Max_070"] = "でも 心のどこかで望んでたのかも… |「普通じゃない人生を送りたい。 冒険したい」って |でもね でも… |クロエと一緒じゃなきゃヤダったの |だから この力も… クロエのおかげなんだよ",
  ["Cue_E5_7C_Beach_Insertion_Max_090"] = "うん きっとそうだよ… レイチェルに感謝しないと… |それで何があったの? 覚えてるんでしょ?",
  ["Cue_E5_7C_Beach_Insertion_Max_110"] = "でも クロエ… こっちに向かってるよ… すごい竜巻… |ああ もうどうしたらいいか分かんない… 全部私のせいなのに…!",
  ["Cue_E5_7C_Beach_Insertion_Max_140"] = "クロエ…",
  ["Cue_E5_7Z_LabyChloe_Bink_Chloe_010"] = "5 年たっても相変わらずだな",
  ["Cue_E5_7Z_LabyChloe_Bink_Max_020"] = "ホント 会えてうれしいよ",
  ["Cue_E5_7Z_LabyChloe_E1ChloeCar_Chloe_010"] = "決まりだな",
  ["Cue_E5_7Z_LabyChloe_E1ChloeCar_Chloe_020"] = "じゃ 飛ばすよ",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_010"] = "でも 今日は助けてくれたじゃないか。 いまだに信じられないよ |こうしてまた会えたのはきっと…",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_030"] = "これが運命なら… レイチェルを見つけたい。 レイチェルに会いたい",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_040"] = "おい なんだこれ",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_070"] = "マックス。 最初から話して",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_080"] = "ちゃんと聞くよ…",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_020"] = "運命?",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_050"] = "雪…?",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_060"] = "嵐の予兆かも",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_010"] = "この曲 アガるな…! 恥ずかしがんなって!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_020"] = "踊れって!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_030"] = "消して! 早く!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_040"] = "マックス 早く隠れて。 見つかったら あたしがぶっ殺される",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_010"] = "たしか… 先月 誕生日だったよな",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_020"] = "死んだパパのカメラ… プレゼントだ",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_040"] = "なんか湿っぽくなったな… よし 気分を変えて 踊りまくろう!",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_050"] = "ほら マックスも踊るんだよ! どうした 恥ずかしいのか!? |じゃ そのカメラであたしを撮って",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Max_030"] = "ホントにいいの!? ありがとう すごくうれしいよ",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_010"] = "力のこと教えてくれよ",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_020"] = "ヤバいよ!",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_030"] = "偉大なるマックス様 おみそれいたしました…",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_040"] = "まさか ホントに時間を巻き戻せるなんて。 色々試さなきゃ!",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_050"] = "あたしに任せなって",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Max_060"] = "はいはい 分かりました… どこへでもついていくよ",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_010"] = "さて \"別荘\"へようこそ。いいとこだろ?",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_030"] = "しっかし 親友と再会できたうえ 超能力者になってるとは…",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_050"] = "あー待って 今 休めそうなとこ探すから…",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_060"] = "びっくりしたよ。 気分はどうだ?",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Max_020"] = "退廃的だね。 クロエにぴったり",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Max_040"] = "ちょっと… 気分が… 悪いかも…",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_020"] = "誰が犯罪者だ…",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_030"] = "案外 あたしが先にこじ開けてるかもよ",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_060"] = "魔法かよ!? どうやって入ったんだ? 教えろよ!",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_010"] = "ついに犯罪者の仲間入りだね",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_040"] = "じゃあ 勝負ってことで",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_050"] = "どうぞ あがってって",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Chloe_010"] = "マックス ちょっとこれ見てみろよ",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Chloe_040"] = "心を読んだのか? |それとも あたしがイスを盗もうとして巻き戻した? ややこしいな…",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_020"] = "違う… ほら |「レイチェルは暗い部屋の中… 暗い部屋の中…」 それが延々と…",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_030"] = "このイスはだめだからね",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_050"] = "親友だから 考えてることくらい分かるよ",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_010"] = "また助かった… すげえ… マジで命の恩人だよ!",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_020"] = "命の恩人のためなら よろこんで運転手をやらせてもらうよ",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_040"] = "関係ないよ… あたしたちさえ ずっと一緒なら",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Max_030"] = "でもこの力… いつまでもつか分からないよ",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Chloe_010"] = "ほら やってみて。 キス",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Chloe_020"] = "マジで… マジでやった! |ウォーレンにメールして 脈がないことを知らせてやんないと… |ま 百合好きなら別だけど",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Max_030"] = "バカじゃないの",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Chloe_010"] = "ほら やってみて。 キス",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Chloe_030"] = "なにそれ? 本当はキスしてから巻き戻したくせに! |ウォーレンにメールしないと… マックスはキミを愛してるって…",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Max_020"] = "その手には乗らないよ",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Max_040"] = "バカじゃないの",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Chloe_010"] = "笑って!",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Chloe_040"] = "いい刺激になっただろ?",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_020"] = "せーの!",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_030"] = "昨日とは別世界みたい…",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_050"] = "昔みたく ウダウダしてられたらいいのに… |起きようか。 そろそろ学校に戻らないと…",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_010"] = "こいつだったらどこにでも行けるな |海沿いをビッグサーの方まで行ったら最高だぜ!?",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_020"] = "分かってる。 ただの夢さ",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_030"] = "レイチェルがフランクに こんな写真を撮らせてたなんて… |ラブレターも書いて… |フランクとヤってたなんて! |そんなの一言も言わなかった! なんで?",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_050"] = "友だちなら言うだろ! 結局 みんなあたしを裏切るんだ… |パパは死ぬし マックスは何年もいなくなるし… |ママはクソオヤジと再婚… |そしてレイチェルまで…",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Max_040"] = "怒るって分かってたからだよ",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_010"] = "それはあたしが決めるの! 約束したでしょ!",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_020"] = "うちのパパがイケてるパパでよかったよ…",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_030"] = "今日のマックス 絶対おかしい。 大丈夫?",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Max_040"] = "クロエ… やったよ! 大成功だよ!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_020"] = "薬品まみれの髪も悪くないよ",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_040"] = "やばい!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_050"] = "寮に戻る気かよ 見つかったらヤバいぞ! うちに来な",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Max_010"] = "そうしようか。 水から出たら凍えるかも…",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Max_030"] = "やばい!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_020"] = "あ カワウソ発見!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_030"] = "その力がすべてを変えたな。 特にマックス自身を |臆病者でウジウジしてたのは昔の話だ",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_050"] = "あたしもだ。 この町も マックスがいれば悪くない",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Max_010"] = "せーの!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Max_040"] = "それ褒めてる?",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_010"] = "なんか ちょっと… 不思議な感じだね",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_030"] = "腫れ物に触るみたいなのはやめて。 普通に くだらない会話がしたいの",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_040"] = "ちょっと待って",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_050"] = "ほら見て 夕日がすごくきれい。 何\"アワー\"だっけ…?",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Max_020"] = "うん… でも楽しいよ",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Max_060"] = "「マジックアワー」",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_030"] = "レイチェル…!",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_040"] = "違うよな…? これ全部… ヤラセだよな? そうだろ!?",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_050"] = "廃品置き場だ! |今すぐ確かめに行こう! ヤツが何をしたのか… |レイチェルが死んでるわけない! |全部ヤラセだって。 絶対そうに決まってる!",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Max_010"] = "ケイトだけじゃない… 他にもこんなにたくさん犠牲者が…",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Max_020"] = "ビクトリアが危ない… ネイサンは今夜のパーティで ビクトリアを狙う気だよ!",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Chloe_030"] = "なんか気持ち悪りいな… おかげで目が覚めたけど |徹夜で探偵ごっこしてたせいで 頭ボーッとしてたからさ",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Max_010"] = "クロエ… よかった!",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Max_020"] = "うれしいの… クロエが元気そうで!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_010"] = "レイチェル…?|ウソだ… ウソだ! 信じない!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_030"] = "レイチェル なんで…",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_050"] = "親友だったのに…! どうして…! こんなのあんまりだよ…|あんまりだ!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Max_020"] = "クロエ…",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Max_040"] = "クロエ… 落ち着いて…",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_010"] = "これ いい写真だね… 海賊ごっこしたときのだ!",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_030"] = "あのね… |あたしは呼吸器系が弱ってて… その… か… 回復の見込みはないの |お医者さんが話してるのを聞いちゃったんだ |あたしは死を先延ばしにしてるだけなんだよね |パパもママもあたしも これ以上は苦しむだけ |あたしはそんなのイヤだ",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_050"] = "あたしね… またマックスと一緒になれて もう思い残すことがないんだ… |町を二人で駆け回ってた 何でもできた子どもの頃みたいな気分を |もう一度味わいたかった |今日 その願いがかなったよ |だから これを… 最後の思い出にしたい… 分かる?",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Max_020"] = "結局 町を乗っ取ることはできなかったね",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Max_040"] = "え…? 何が言いたいの?",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_010"] = "がんばれ あと少しだ!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_020"] = "目を覚ませ!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_030"] = "マックス 聞こえてるか?",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_040"] = "しっかりしろ! がんばれって!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_050"] = "マックス! おい!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_060"] = "あと少しで灯台だ! 起きろって!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_070"] = "頼む しっかりしてくれ!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_080"] = "マックス! しっかり!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_090"] = "大丈夫 助かるぞ!",
  ["Cue_E5_9A_Toilets_Ending_Chloe_010"] = "ちゃんと誰もいないか確認したんだろうな?",
  ["Cue_E5_9A_Toilets_Ending_Chloe_020"] = "さて 本題だけど…",
  ["Cue_E5_9A_TownEnd_CliffEndChloeDead_Max_010"] = "クロエ… さよなら…",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_020"] = "この… クソ野郎!",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_040"] = "クロエ… そんな… そんな…",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_050"] = "クロエ… 間に合わなかった… 許してくれ…",
}
